D.Strings[46126]="我们可以救这个人，但必须得抓紧时间。"
D.Strings[46127]="如果船员发生了窒息，我们可以输送氧气以稳定他们渐弱的生命体征。"
D.Strings[46128]="按压病人的胸膛以增强他们的生命体征。"
D.Strings[46129]="电击能够大大加强病人的生命体征。但这个办法不能多用。"
D.Strings[46130]="你真的救活了一个人！我必须承认，我原本对你还是有所怀疑的。"
D.Strings[46131]="噢，不。我们失去了一位病人。不过别难过，$n。他们已经坚持得够久了。"
D.Strings[46132]="我们不可能救下所有人，$n。我们还是去关注一下那些还有救的病人吧。"
D.Strings[46133]="$n！你听到我的话了吗？噢，我只是确定一下你有没有专心听讲而已。"
D.Strings[46134]="我在治疗法术上一向没有天分，可却在医术上找到了目标。药水、绷带和其他的诊疗手段也能治病救人！"
D.Strings[46135]="但愿其他密探也能挺过来。否则的话，我的负担就更重了。"
D.Strings[46136]="能帮助幸存者当然是好事，可我们也不能忘记自己原本的任务。"
D.Strings[46137]="但愿部落还没有发现这个地方。否则他们一定会设法占领这里的。"
D.Strings[46138]="虽然我们活了下来，可遗憾的是，我们的飞机都坠毁了。这会让我们的任务变得更加……有挑战性。"
D.Strings[46139]="战斗不息，修行不止。你永远也无法达到完美境界。"
D.Strings[46140]="做人要向前看，也不能忘本。"
D.Strings[46141]="永远不要自以为高人一等。记住，这片土地是大家共同的家园。"
D.Strings[46142]="不要忘记你所爱的人，不要忘记你为之战斗的理由。"
D.Strings[46143]="卡加斯·刃拳倒下了！为了部落！"
D.Strings[46144]="卡萨雷兹没有我这么走运，$n。他已经和幽灵为伴了。"
D.Strings[46145]="嗷……我脑袋还晕忽忽的，朋友。我看看飞艇残骸。"
D.Strings[46146]="我的人……都死了？不……"
D.Strings[46147]="我担心冈尼没能撑下来，$n。"
D.Strings[46148]="卡加斯·刃拳被杀了！联盟万岁！"
D.Strings[46149]="嘿，嘿$c！你有信心把投环扔到一只慢吞吞的海龟背上吗？"
D.Strings[46150]="你看起来很有一手。想来试试这个游戏吗？"
D.Strings[46151]="很简单的游戏，傻瓜都能玩。你有信心玩好吗？"
D.Strings[46152]="套圈圈，赢奖品了！"
D.Strings[46153]="试试你的准头吧！试试你的准头吧！"
D.Strings[46154]="来玩玩吧，这么简单的游戏，连$c都能玩！"
D.Strings[46155]="射击得奖励了！有人想射几件奖品回去吗？"
D.Strings[46156]="枪，枪，枪！来吧，伙计！"
D.Strings[46157]="站出来，发挥一下神枪手的本事吧！"
D.Strings[46158]="伙计们，我这里有精美奖品发放！千万不要错过！"
D.Strings[46159]="展示你的技巧，赢得精美奖品！"
D.Strings[46160]="只要你会射击，就能赢得诱人的奖品！"
D.Strings[46161]="搜寻任何幸存者，$n。我们需要人手……"
D.Strings[46162]="坦克！我们这里有坦克！"
D.Strings[46163]="站出来，试试我们的坦克吧！"
D.Strings[46164]="我们遭到了攻击！赶快挺身而出，加入战斗吧，$c！"
D.Strings[46165]="嘿，嘿！快来指挥你的坦克打一场刺激的大战吧！"
D.Strings[46166]="传送到马戏团的另一头！"
D.Strings[46167]="炮弹飞人！有人想试试被大炮打飞的滋味吗？"
D.Strings[46168]="快上来试试被人肉炮弹的滋味吧！"
D.Strings[46169]="别担心你的体重，不管你有多重，这门大炮都能够承受！"
D.Strings[46170]="打砸时间！"
D.Strings[46171]="来打打豺狼人吧！快来打豺狼人吧！"
D.Strings[46172]="挥舞大锤的乐趣！有人想挥着锤子砸东西吗？"
D.Strings[46173]="挥挥锤子，就能赢得奖品！"
D.Strings[46174]="我……我好不容易才在飞船坠毁前逃了出来！"
D.Strings[46175]="振作起来！你还活着！纳兹戈林命令我们去附近村子报到。"
D.Strings[46176]="谢谢你。我能自己去村子里。注意安全……"
D.Strings[46177]="现在进入竞技场的是：$n！"
D.Strings[46178]="现在……战斗开始！"
D.Strings[46179]="就快胜利了，$n。加油！"
D.Strings[46180]="你就要赢了，$n！"
D.Strings[46181]="祝贺$n赢得这场战斗！"
D.Strings[46182]="合群的小劣魔宠物"
D.Strings[46183]="食人魔法师装束"
D.Strings[46184]="堕落角鹰兽"
D.Strings[46185]="救我下来，$n！这女人要杀了我！"
D.Strings[46186]="别浪费时间了，打起精神来！纳兹戈林要你立刻去村里报到。"
D.Strings[46187]="噢，够了！别再垂头丧气了！"
D.Strings[46188]="祝你下次好运，$n。你可以试着用一些能够同时打击多名敌人的技巧！"
D.Strings[46189]="国王的皇家纹章。这间舱室里肯定住过某位具有皇室血统的大人物。"
D.Strings[46190]="这个士兵和其他人不一样。他看起来像是个私人保镖。"
D.Strings[46191]="皮革封面绣着缩写字母：“A.L.W.”。\n\n你可以把剩下那几张完整的书页带走。"
D.Strings[46192]="沙地甲虫宠物"
D.Strings[46193]="我就不该苟活下来，$r。$b$b我应该和其他兄弟们死在一起。"
D.Strings[46194]="我们需要重整队伍，中士！去附近的村里报到。"
D.Strings[46195]="伪造的石棺"
D.Strings[46196]=S[17011]
D.Strings[46197]="苍穹之冠"
D.Strings[46198]="被遗忘者的墓冢"
D.Strings[46199]="没错，$c，我们没有时间悲伤了。让我们为死去的同胞复仇，为部落夺下这片土地！"
D.Strings[46200]="你发现了一叠被浸湿的纸张，上面有王子殿下的笔迹。你最好把它们拿去给诺德看看。"
D.Strings[46201]="这种调整工作可不简单。"
D.Strings[46202]="出什么事了？$b$b我——我们在哪儿？"
D.Strings[46203]="赶快行动！纳兹戈林在谋划反击。我们正在村里重新集结。"
D.Strings[46204]="去村里……重整队伍……我想我能坚持下去。"
D.Strings[46205]="这份地图描绘了一个击败部落舰队的海军战略。"
D.Strings[46206]="大炮表面坑坑凹凹，被火药熏得漆黑。"
D.Strings[46207]="看来在战斗打响的那天还有清洗甲板的指派。"
D.Strings[46208]="将军决心在这里扎营。$b$b但愿他知道自己在做什么……"
D.Strings[46209]="这名部落水手似乎是战死的。"
D.Strings[46210]="你死定了！"
D.Strings[46211]="不稳定的电磁线圈要爆炸了！快跑！"
D.Strings[46212]="愿圣池祝福你。"
D.Strings[46213]="长老们会听到你的善行的。"
D.Strings[46214]="我欠你一份情，陌生人。"
D.Strings[46215]="我……我自由了？谢谢你，$g兄弟:姐妹;。"
D.Strings[46216]="看到了？不知道谁在地上留了满满一杯啤酒，我正帮忙把它拿起来呢。"
D.Strings[46217]="%s语无伦次的在那自言自语。"
D.Strings[46218]="%s将脸埋进手中，哭了起来。"
D.Strings[46219]="%s轻轻地前后摆动着。"
D.Strings[46220]="我都听说了，$n。快到营地去吧，我们在那里会合。"
D.Strings[46221]="誓死追随雷电之王！"
D.Strings[46222]="低等种族将再次在魔古族面前瑟瑟发抖！"
D.Strings[46223]="呀啊啊！！"
D.Strings[46224]="他们为什么要做这种事？"
D.Strings[46225]="其他人还好吗？"
D.Strings[46226]="你用不着跟我说两次！"
D.Strings[46227]="他们把我们的人拖走了！"
D.Strings[46228]="帮我教训教训他们！"
D.Strings[46229]="告诉我，韩妮没事，对吧？！"
D.Strings[46230]="你是邵傲的朋友吗？他还活着吗？"
D.Strings[46231]="小心，敌人靠近了！"
D.Strings[46232]="但愿果园能安然无恙……"
D.Strings[46233]="我从没想过，我们的小果园居然会发生这种事。"
D.Strings[46234]="啊，这下好多了。那些玩意儿缠得太紧了。"
D.Strings[46235]="这事儿完了之后，我一定要搬回主城去。"
D.Strings[46236]="我会没事的，请去帮助别人吧！"
D.Strings[46237]="谢谢你，我都不敢想象他们想对我们做什么。"
D.Strings[46238]="为了潘达利亚！"
D.Strings[46239]="你太小看我们了！"
D.Strings[46240]="你休想奴役我们！"
D.Strings[46241]="我们绝不向魔古族低头！"
D.Strings[46242]="只有公平公正的战斗才能真正衡量出一个人的实力。任何其他的考验都是有瑕疵的。"
D.Strings[46243]="真是岁月催人老啊。我的行动已经不如从前敏捷了，所以我也很少去看我的老朋友了……"
D.Strings[46244]="如果你很强壮，那我会向你表示敬意。$b$b如果你很软弱，那我也会鼓励你。$b$b如果你是我的敌人，那我就会用拳头来揍你。如果有必要的话，我会一次又一次地接着揍你。"
D.Strings[46245]="以战生慧，以斗促觉，以动得静。$b$b这就是天之道。"
D.Strings[46246]="纪律是臻于完美的关键。你必须打败你的惰性！管好你那把懒骨头！"
D.Strings[46247]="我父亲是云瀑长老的前任。我所知道的一切都是他教的。"
D.Strings[46248]="只要反复练习，没有什么是掌握不了的。"
D.Strings[46249]="我做好再练一次的准备了，教头。"
D.Strings[46250]="很高兴你能前来——我一个人没法解决这个问题。"
D.Strings[46251]="为$n欢呼三声吧！再来三杯啤酒！"
D.Strings[46252]="进入乱斗比武场并燃放焰火。然后，做好同时面对几名对手的准备吧！在乱斗比武场中，一切皆有可能。"
D.Strings[46253]="加入下面那些弟子的队伍吧。然后像他们一样，跟着带头的做。"
D.Strings[46254]="我会喊出“左”和“右”的口令。你要注意听，$c。"
D.Strings[46255]="玛洛恩！玛洛恩！玛洛恩！"
D.Strings[46256]="这个马戏团太棒了！"
D.Strings[46257]="我们本来是只能在这里玩的。可我想我们稍微走远一些也不会有什么大问题。"
D.Strings[46258]="我在想，这个沙箱到底多久清理一次啊。"
D.Strings[46259]="这个沙箱真无聊。"
D.Strings[46260]="这个沙箱太挤了……"
D.Strings[46261]="小婴儿才玩沙箱呢。"
D.Strings[46262]="不知道这些骨头是哪儿来的。"
D.Strings[46263]="我们应该到别处去看看！"
D.Strings[46264]="看看那些大爆炸！"
D.Strings[46265]="我也有一辆坦克，可是被我妹妹弄坏了……"
D.Strings[46266]="那些坦克很危险！"
D.Strings[46267]="我们应该四处走走，把每个房子都跑遍！"
D.Strings[46268]="我一个人就能横扫那些坦克。"
D.Strings[46269]="那个大炮好大啊！"
D.Strings[46270]="我肯定能准确落到目的地上。"
D.Strings[46271]="经过一阵拳打脚踢，大吃大喝之后……必须得有人来打扫。$b$b现在就该园丁上了。"
D.Strings[46272]="为什么那个大炮里不能一直飞出人来？"
D.Strings[46273]="你还是留着你的棍术和织雾绝招吧，我站在这里看看就行了。"
D.Strings[46274]="那些炮弹有什么用？他们会让你带一个吗？"
D.Strings[46275]="哇啊！飞行一定很有趣！"
D.Strings[46276]="他们应该把炮口笔直朝上。"
D.Strings[46277]="你知道总在禅院的日课上偷懒会有什么后果吗？你会沦为园丁！就像我这样。$b$b不过这也不算太糟。我总算有了一把自己的扫帚。$b$b<老吴叹了口气。>"
D.Strings[46278]="万一你在飞的时候被小鸟撞上怎么办？"
D.Strings[46279]="不知道这个大炮能不能把我们一起射出去……"
D.Strings[46280]="那个喷火的真吓人！"
D.Strings[46281]="不知道他们有没有烧伤过自己。"
D.Strings[46282]="唔……靓汤……"
D.Strings[46283]="给我给我给我……"
D.Strings[46284]="我听说，如果你能喷火的话，那你就是半条龙了！"
D.Strings[46285]="我想吃。"
D.Strings[46286]="闻起来真香！"
D.Strings[46287]="好汤，好汤，好汤啊……"
D.Strings[46288]="我要吃炖菜！我要吃炖菜！"
D.Strings[46289]="喷火看起来很难。"
D.Strings[46290]="这是什么味儿？"
D.Strings[46291]="喷火是很吓人，可是被大炮打到天上更吓人。"
D.Strings[46292]="他们很棒！"
D.Strings[46293]="我长大以后，也要当一个喷火的杂耍艺人！"
D.Strings[46294]="我想，我只要努力尝试，也可以喷出火来。"
D.Strings[46295]="不久之前，魔古族还只是在树林里伏击一下过往的行人而已。但这次袭击不同，这次行动是有组织……有目的。"
D.Strings[46296]="你是第一个穿过那座大门后没有被吓坏、或是受伤，或是又伤又怕的。$B$B但愿你能帮上我们的忙。"
D.Strings[46297]="快跑！到安全的地方去！"
D.Strings[46298]="别管它了，这不值得！"
D.Strings[46299]="当然是一座禅院！$b$b天禅院的武僧专门教授像我一样的年轻熊猫人如何战斗。所有的战斗大师都是在这里诞生的：剑仙宇明、铁布衫梁……甚至连伟大的帝王少昊都是在这座寺院学习的。$b$b或者至少传闻是这么说的。"
D.Strings[46300]="欢迎来到我们在群山中的家园，$r。"
D.Strings[46301]="你好啊！欢迎你！"
D.Strings[46302]="什——？！你干嘛——？！我还要做玩具呢！"
D.Strings[46303]="冬幕节还没到呢。我还有工作呢！"
D.Strings[46304]="我们还需要两万个齿轮，以及……嘿！你不能这么召唤我！"
D.Strings[46305]="那么，你听说过432-A型小助手吗？我听说……什——？嘿！我们小助手也是有正经工作的，你知道嘛！"
D.Strings[46306]="你觉得这像是冬幕节吗？彩灯，装饰？不像？很好，那你也知道这些东西是谁做的，不是吗？！"
D.Strings[46307]="你瞧，$c。事情是这样的。玩具啊，彩灯啊，还有各种节日草药是不会自己做出来的，你知道吧？所以，别再召唤小助手了，拜托你！"
D.Strings[46308]="怎么——？又来？！你看，$c。你一整年都打怪或者在拍卖行里吸冷气，或者干别的无聊事，我已经看够了。我还有工作要做呢。"
D.Strings[46309]="哇！车间哪儿去了？！等今年的晚些时候再召唤我，好吗？"
D.Strings[46310]="快来买游戏代币啊！"
D.Strings[46311]="代币！代币！代币！"
D.Strings[46312]="代币！快来买代币！"
D.Strings[46313]="各位，你们得先付钱才能玩游戏！快来买游戏代币啊！"
D.Strings[46314]="卖游戏代币了！快来买游戏代币！"
D.Strings[46315]="有了游戏代币才能玩游戏。快来买游戏代币了！"
D.Strings[46316]="快快快！快来买游戏代币了！"
D.Strings[46317]="嘿，嘿，我可不是开玩笑的，快来买游戏代币！"
D.Strings[46318]="现在安全了。你可以下来了。"
D.Strings[46319]="哎呀！救命啊，怪物要吃我啦！"
D.Strings[46320]="牛头人酋长音乐会将在30分钟后开演！"
D.Strings[46321]="牛头人酋长音乐会将在15分钟后开演！"
D.Strings[46322]="牛头人酋长音乐会将在5分钟后开演！"
D.Strings[46323]="马戏团的游客们，你们准备好了吗？牛头人酋长音乐会现在正式开演！"
D.Strings[46324]="那个青玉巫婆超级恐怖的。"
D.Strings[46325]="呃！青玉巫婆！我得躲起来！"
D.Strings[46326]="我听说这个游戏很简单。"
D.Strings[46327]="但愿这些环不会伤害那只海龟。"
D.Strings[46328]="我也想要一只宠物龟。"
D.Strings[46329]="我朋友就有一只，可他把它送掉了。"
D.Strings[46330]="套圈圈太好玩了。"
D.Strings[46331]="我也想玩套圈圈。"
D.Strings[46332]="这是我最喜欢的游戏，因为我喜欢那只海龟。"
D.Strings[46333]="我敢说，海龟肯定喜欢接近其他的动物。"
D.Strings[46334]="真好吃！"
D.Strings[46335]="我爱蛋糕！"
D.Strings[46336]="这个粉红色的爱心真漂亮！"
D.Strings[46337]="我很抱歉，可如果我让你带走一匹马的话，罗娜会气疯的。\n\n只有吉尔尼斯的朋友才有资格得到它们。"
D.Strings[46338]="这个纸杯蛋糕看起来很好吃！"
D.Strings[46339]="那几个蛋糕的样子真漂亮！"
D.Strings[46340]="我很抱歉，可如果我让你带走一匹马的话，罗娜会气疯的。\n\n只有吉尔尼斯人崇拜的英雄才有资格得到它们。"
D.Strings[46341]="相比馅饼，我更喜欢蛋糕。"
D.Strings[46342]="这些看起来都很棒。"
D.Strings[46343]="艾美可真是个好人。"
D.Strings[46344]="罗娜说，一个英勇的冒险者在她家的果园附近救下了许多马。\n\n我主动提出帮她照料那些远渡重洋而来的马。这个手艺是从我爸爸妈妈那里学来的，愿圣光保佑他们！\n\n你想要一匹精良的吉尔尼斯战马吗……？"
D.Strings[46345]="想买的东西太多了。"
D.Strings[46346]="噢，看那个！"
D.Strings[46347]="这里有些东西很漂亮。"
D.Strings[46348]="还需要更多闪闪发亮的……"
D.Strings[46349]="我在想，要花多少时间才能弄到所有这些东西啊？"
D.Strings[46350]="每样东西都很漂亮！"
D.Strings[46351]="她可真——强壮！"
D.Strings[46352]="我听说，她是世界上最强壮的女人！"
D.Strings[46353]="我觉得，男孩子们都很怕她！"
D.Strings[46354]="等我长大以后，也要像克莉一样！"
D.Strings[46355]="不知道做名人的感觉怎么样？"
D.Strings[46356]="她真高！"
D.Strings[46357]="她的力气真大！"
D.Strings[46358]="我敢说，没人能打得过她。"
D.Strings[46359]="噢……"
D.Strings[46360]="哦……好痛啊。"
D.Strings[46361]="可怜的工人……"
D.Strings[46362]="但愿他们能好起来。"
D.Strings[46363]="受伤的人太多了，情况不太好。"
D.Strings[46364]="我很好奇，他们是怎么受伤的。"
D.Strings[46365]="但愿他们能没事。"
D.Strings[46366]="太令人震惊了，这么多工人都受了伤。"
D.Strings[46367]="真恐怖……"
D.Strings[46368]="真神秘……"
D.Strings[46369]="男孩子们都很怕塞格，所以他们都跑开了。"
D.Strings[46370]="不知道是不是真的有命运这回事……"
D.Strings[46371]="我在想，塞格会不会去玩打豺狼人的游戏？"
D.Strings[46372]="塞格看上去很和善……"
D.Strings[46373]="我听说，有些人算出来的命运很吓人。"
D.Strings[46374]="这样子真恐怖……"
D.Strings[46375]="你出现的正是时候，朋友。我们需要每一个联盟士兵的力量。"
D.Strings[46376]="我不知道我们是怎么做到的，可我们确实抵挡住了那些猢狲。$B$B谢谢你，伙计。"
D.Strings[46377]="振作点！"
D.Strings[46378]="事情正在向有利于我们的方向转变，$n。既然攻击已经结束了，我们终于可以想办法修复飞船，并寻找回家的路了。"
D.Strings[46379]="<他似乎在战斗伊始就被打晕了。>$B$B<他手中紧紧抓着一只皮包。>"
D.Strings[46380]="我的脑袋就像被榔头砸过一样，不过除此之外，我毫发无伤。我敢说，这一点已经比大部分船员都好多了。"
D.Strings[46381]="翻看他的包裹。"
D.Strings[46382]="……解决了那东西，你和这群乌合之众就是我的下一个目标。唔，我还以为你们根本到不了这儿！"
D.Strings[46383]="神秘与奇迹不仅仅存在于马戏团，我们身边每天都有奇迹发生。我们列出了一张表格，上面写着你在日常生活中可能遇到的奇迹。暗月冒险者指南能帮你找出这个世界上的奇迹。$b$b只要拥有了这本指南，你就能够发现未知的物品。你熟视无睹的东西可能就是别人孜孜以求的宝物。$b$b带上这本指南吧，用你眼睛去发现未解的谜团。$b$b如果你不小心丢失了指南，可以再来找我们，我们会免费送你一本新的。"
D.Strings[46384]="暗月冒险者指南？"
D.Strings[46385]="能再给我一本暗月冒险者指南吗？"
D.Strings[46386]="敢于反抗我们的人都得死！"
D.Strings[46387]="我们已经在这里困守了好几天了。大家都已经濒临崩溃的边缘了，不过依然在努力保持斗志。"
D.Strings[46388]="那些……猴子……攻击我们……$b$b我击退了他们，可……他们很快就会回来……带着更多的人手……"
D.Strings[46389]="你做的很好，密探吉尔妮。现在你可以休息一下了……让我们来对付他们。"
D.Strings[46390]="<利尔没有抬头看你。>$b$b<从他的状态来看，你甚至怀疑他连抬头的力气都没有了。>"
D.Strings[46391]="请继续你的报告。"
D.Strings[46392]="你是想要建造东西还是拆除东西？拆卸东西还是组装东西？破坏东西还是修补东西？如果是的话，那你就来对地方了。"
D.Strings[46393]="在新年的伊始，我们的先祖们会暂时降临，为生者指点迷津，并欢迎后来者加入他们的行列。"
D.Strings[46394]="射击，射击，射击……"
D.Strings[46395]="接着说，苏利。"
D.Strings[46396]="这座青玉雕像栩栩如生，面部表情十分惊恐。$b$B不过，看上去并不像阿信。"
D.Strings[46397]="检查雕像"
D.Strings[46398]="住手！你休想把我的朋友们变成可笑的雕像！"
D.Strings[46399]="|TInterface\\Icons\\ability_shaman_cleansespirit.blp:16|t萨尔对你施放了|cFF00FFFF|Hspell:103550|h[净化灵魂]|h|r！"
D.Strings[46400]="我很高兴这些“军情七处”的人愿意带上我。$b$b我们很少离开舒适的湖泊。这是我有生以来第一次离家这么远。"
D.Strings[46401]="接着出了什么事，小卢？"
D.Strings[46402]="什么？我看到的该不是……该不是个$r吧？谢谢你救了我。"
D.Strings[46403]="幸运地是，你还是能辨别出一些细节，看上去似乎是某个生物的躯干。"
D.Strings[46404]="<绘出雕像碎片的草图。>"
D.Strings[46405]="你从这个雕像残片上看不出什么来，除了它的主人是有手臂的这一点。"
D.Strings[46406]="相比它的其他部分，雕像的肩部看上去十分威武。它的主人一定是个强大的生物！$b$b它或许是一个温和的家伙。如果不是的话，那它可能十分具有侵略性！$b$b我们只能祈祷……"
D.Strings[46407]="我的族人们不喜欢陌生人，可是，我欠你太多了。但愿长老们不会因此怪罪我。"
D.Strings[46408]="萨满！巨龙之魂不属于你。现在放手，你还有机会活着离开这里。"
D.Strings[46409]="杀光他们，除了那个萨满。带他来见我！"
D.Strings[46410]="你好啊，孩子。"
D.Strings[46411]="你能帮帮我们吗？我们的朋友受伤了。"
D.Strings[46412]="这座青玉雕像栩栩如生，面部表情十分惊恐。"
D.Strings[46413]="这座雕像与安·风裘向你描述的阿信的容貌并不相似。"
D.Strings[46414]="你无路可逃了，萨满。"
D.Strings[46415]="欢迎光临暗月马戏团！"
D.Strings[46416]="但愿它脸上那个又大又恐怖的面具只是面具而已……"
D.Strings[46417]="做好冒险的准备吧！"
D.Strings[46418]="看，绿爪大师，他就是这片土地上远近闻名的玉拳武僧。$b$b通过高超的武艺、坚定的意志和强大的气，他创出了一种名叫“碎玉打击”的绝招，能将敌人直接变成玉雕。$b$b是他的英勇与献身精神，在危急时刻拯救了翡翠林，在这个世界上再也找不到像他这样的人了。$b$b愿这座永不倒下的雕像能不断提醒人们和平是多么来之不易，愿他的牺牲将被人们永远铭记。"
D.Strings[46419]="当大地遭受苦难时，元素之灵们首先察觉到了凶兆。当元素之灵离开五晨寺，各按本能行事时，睿智的熊猫人发现了端倪。"
D.Strings[46420]="只有关注并迎回元素之灵，我们才能治愈这片土地，并真正了解目前最大的危机。"
D.Strings[46421]="各位游客请注意了！暗月死斗大赛就要开始了！奖品宝箱即将出现在竞技场中央！"
D.Strings[46422]="暗月死斗大赛开始！"
D.Strings[46423]="最近，四位元素之灵都离开了五晨寺，藏身于神真子的各个角落。大地因此承受了苦难。"
D.Strings[46424]="你的训练很快就会发挥作用的，年轻的$c。现在继续你的学习吧。"
D.Strings[46425]="你以为自己能取代大地守护者的地位吗，萨满？愚不可及！"
D.Strings[46426]="无论发生了什么事——我们都必须专注于我们来的目标。"
D.Strings[46427]="没人能阻挡我们前进。"
D.Strings[46428]="暮光之锤的人冲过来了。"
D.Strings[46429]="让他们来！"
D.Strings[46430]="你眼前的就是暗月死斗场。你是否拥有强大的实力和坚定的意志，能够打败所有的参赛者并赢得大奖？\n\n大赛将从午夜开始，每三小时举行一次。"
D.Strings[46431]="你觉得你能逃到哪儿去，小蜥蜴？"
D.Strings[46432]="他们是怎么发现我们的？拿起武器——我们必须冲出这条峡谷！"
D.Strings[46433]="我们必须找到元素之灵，并将他们带回寺中。只有这样，我们才能治愈大地，并发现真正的危机。"
D.Strings[46434]="最近的一位元素之灵是上古火灵燧焰。我要你去见见我的几个得意弟子，并向他们询问燧焰的消息。"
D.Strings[46435]="去吧，$c。你还有很多事情要做。"
D.Strings[46436]="你猜这棵树是怎么回事，苏利？"
D.Strings[46437]="什么东西撞上它了，长官。不是砍倒的，也不是自己倒下的。"
D.Strings[46438]="那是什么，在那儿？是某种鸟吗？"
D.Strings[46439]="不是，那是一架飞机。等等……飞机！？"
D.Strings[46440]="那是安玻和尼姆的飞机！他们可能还活着！"
D.Strings[46441]="谁是安玻和尼姆？我们要跟上他吗？"
D.Strings[46442]="她还有呼吸，长官！快过来！跟她说说话！"
D.Strings[46443]="大家听好了！小心猢狲的伏击！"
D.Strings[46444]="小卢，保护好安玻！苏利，别让飞机在我们身边炸了！"
D.Strings[46445]="我来尽力挡住他们！"
D.Strings[46446]="李飞大师的声音在耳畔回响，“上古火灵燧焰以贪吃著称。他想要吃柴火，还需要轻风的抚慰来振作精神。”"
D.Strings[46447]="李飞大师的声音在耳畔回响，“如果你能找到这些东西，并把它们带去他在武松村外的洞穴，你就会在那里接受挑战。”"
D.Strings[46448]="李飞大师的声音在耳畔回响，“只有赢得挑战，你才能觐见燧焰。如果你的灵魂是纯洁的，那么在重新点燃他的火焰后，他就会跟你走。”"
D.Strings[46449]="李飞大师的声音在耳畔回响，“去吧，孩子。我们很快就会重逢的。”"
D.Strings[46450]="李飞大师的声音在耳畔回响，“很高兴再次见到你，艾莎。既然你怀着敬意而来，我也会给出你所追寻的答案。”"
D.Strings[46451]="这片森林是谁的？"
D.Strings[46452]="谁才是我们最大的敌人？"
D.Strings[46453]="不对，蠢货！是海滩上的那些家伙！"
D.Strings[46454]="难道我们要看着这些不长尾巴的软蛋砍伐我们的树林，杀害我们的同胞手足吗？"
D.Strings[46455]="我要提醒你们……我们才是这片森林里最强的存在。我们是森林之王！我们是敌人的死神！"
D.Strings[46456]="谁也别想挑战恐目部族。现在，该是我们品尝鲜血与胜利的时刻了！"
D.Strings[46457]="是您，酋长！"
D.Strings[46458]="个人卫生问题？"
D.Strings[46459]="阿莱克丝塔萨的幼龙应该就在这里……"
D.Strings[46460]="是那些白皮鬼！"
D.Strings[46461]="是我们！恐目！"
D.Strings[46462]="水？"
D.Strings[46463]="那些蓝旗子！"
D.Strings[46464]="猴子！"
D.Strings[46465]="是海上骑士！"
D.Strings[46466]="耶！！！！"
D.Strings[46467]="恐！恐！恐目！"
D.Strings[46468]="噢，噢，我知道了！是鸡蛋脑袋！"
D.Strings[46469]="血！血！血！"
D.Strings[46470]="是丑八怪鱼人！"
D.Strings[46471]="是那些洗过的家伙！"
D.Strings[46472]="碾碎他们！"
D.Strings[46473]="鳄鱼？"
D.Strings[46474]="撕碎他们！"
D.Strings[46475]="在那上面！"
D.Strings[46476]="|TInterface\\Icons\\ability_vehicle_sonicshockwave.blp:20|t%s召唤出了|cFFFF0000|Hspell:103678|h[善德之潮]|h|r！"
D.Strings[46477]="安这个刻薄鬼，故意说我没胆子。而我是从不逃避挑衅的。"
D.Strings[46478]="你还好吗？"
D.Strings[46479]="苏利，小卢，计划有变。我们要把安玻送回营地去。"
D.Strings[46480]="没那个必要。我会跟着你们的。"
D.Strings[46481]="你在开玩笑吧！你都快死了！看看你的样子！"
D.Strings[46482]="不，苏利。我的伤没事。现在，我们必须去找白卒。"
D.Strings[46483]="白……白卒是什么？我还以为我们是来打猢狲的。"
D.Strings[46484]="不是他们死，就是我们亡，$r。今天的战斗注定不死不休。"
D.Strings[46485]="啊，总算让我看见一个和善人了，伙计。$b$b你瞧，如果我能看见……那就好了……"
D.Strings[46486]="|TInterface\\Icons\\spell_fire_twilightfire.blp:20|t%s召唤出了|cFFFF0000|Hspell:103780|h[暮光之潮]|h|r！"
D.Strings[46487]="利尔的情况不妙。我们再停下休息一会儿。"
D.Strings[46488]="要是米希卡在就好了。她很快就能治好他的。"
D.Strings[46489]="嘿，伙计们！这是熊猫人的小屋。熊猫人都是很友好的……"
D.Strings[46490]="好主意，小卢。去看看是谁住在那里。把苏利也带上。"
D.Strings[46491]="还有袜子！"
D.Strings[46492]="没错……还有浣熊。我会照顾好指挥官的。"
D.Strings[46493]="<继续读……>"
D.Strings[46494]="|TInterface\\Icons\\spell_shadow_twilight.blp:20|t%s开始施放|cFF006EFD|Hspell:103754|h[暮光乍现]|h|r！"
D.Strings[46495]="阿信想要反悔，可我们都故意打赌说他肯定不敢去，他就没法反悔了。"
D.Strings[46496]="于是其他孩子，不是我，挑唆阿信去敲青玉巫婆的前门。他不肯去，结果有个人，不是我，故意说他肯定是没胆子。$b$b阿信想反悔，结果有个人，我发誓不是我，是别人在一旁煽风点火。阿信受了挑唆。$b$b他去敲了门，但我们没有看到发生了什么事。青玉怪物冲出来攻击我们，我们就跑了。$b$b我真不该去挑唆阿信的。"
D.Strings[46497]="很好很好，一个年轻的访客。$B$b你是来祭扫我丈夫的神龛的吗？你知道，他可是个大英雄。一个玉雕大师，战斗高手。据说，他的名字会被人们永远铭记。$B$b你喜欢我的雕像吗？这些都是我用特殊方法制作的，只有最精良的作品，才能留下来陪伴和保护我的丈夫。"
D.Strings[46498]="阿信呢？"
D.Strings[46499]="这年头还能有人关心赶路的单身旅客可真不容易。我丈夫一定会很喜欢你的。我们一直都想要几个孩子。"
D.Strings[46500]="我们什么时候出发？"
D.Strings[46501]="是刺客！快，准备战斗！"
D.Strings[46502]="什么时候出发？"
D.Strings[46503]="我们的向导呢？"
D.Strings[46504]="我的向导呢？"
D.Strings[46505]="向导呢？"
D.Strings[46506]="我的向导在哪儿呢？"
D.Strings[46507]="向导哪儿去了？"
D.Strings[46508]="你的向导随时可能出现……"
D.Strings[46509]="你的向导马上就到……"
D.Strings[46510]="我刚才还看见向导来着……"
D.Strings[46511]="再等几分钟……"
D.Strings[46512]="我想我看到他往这里走过来了……"
D.Strings[46513]="向导很快就到……"
D.Strings[46514]="耐心点，向导随时可能出现……"
D.Strings[46515]="与死亡之翼的爪牙战斗是你当前的首要任务，$n。可如果你能再帮我们军团一个小忙的话，那就更好了。"
D.Strings[46516]="我的玉石！"
D.Strings[46517]="你有玉石吗？"
D.Strings[46518]="玉石唱歌给我们听。给我！给我！"
D.Strings[46519]="酷！"
D.Strings[46520]="我们没问题。"
D.Strings[46521]="我们的耐心是有限的……"
D.Strings[46522]="很好，我也不介意多等一会儿。"
D.Strings[46523]="那我们就接着等……"
D.Strings[46524]="我快受不了了。"
D.Strings[46525]="我们一直在等。"
D.Strings[46526]="那些鬼鬼祟祟的猴子莫名其妙地伏击了我。"
D.Strings[46527]="暗月死斗大赛结束！胜利者是，$n！"
D.Strings[46528]="我没见过这个孩子。"
D.Strings[46529]="这个不是阿信。不过它看上去真是活灵活现。"
D.Strings[46530]="呃。那个小鬼长得真滑稽。"
D.Strings[46531]="你们是海军上将泰勒的朋友吗？如果是的话，我就要在稍后的战斗中试试你们的实力了。"
D.Strings[46532]="水灵们回应了我的祈祷。谢谢你。"
D.Strings[46533]="我之前都已经绝望了，朋友。谢谢你。"
D.Strings[46534]="我不是眼花了吧？我真的自由了？"
D.Strings[46535]="多亏了你，我又多活了一天。"
D.Strings[46536]="你是搜救队的成员吗？我们得救了吗？"
D.Strings[46537]="我就知道会有人来救我们的。谢谢你，$c！"
D.Strings[46538]="谢谢你，$c。我可以自己返回营地的。"
D.Strings[46539]="他们把上将像畜生一样关了起来。请你把他也救出来吧。"
D.Strings[46540]="猢狲都热衷于折磨俘虏。谢谢你，$c，是你帮我避免了那种悲惨的命运。"
D.Strings[46541]="这片圣地只剩下了不灭的烈焰。我能在这里感受到愤怒……炽热的怒火，难以抑制。小心点。"
D.Strings[46542]="而你，有着英勇的品质。我丈夫的神龛……正需要像你这样出色的守卫。"
D.Strings[46543]="快点，伙计！$b$b我就像个筛子一样在往外飙血，就在这！我的时间可不多了……"
D.Strings[46544]="跟我来吧，金祖恩，我们要去找你丢失的……财物。"
D.Strings[46545]="我马上就来，伙计……"
D.Strings[46546]="胜利在望了！Og’nor ka Lok’tar——让我们给他个了断！"
D.Strings[46547]="噢，不……他们对我的步枪干了什么，伙计！？"
D.Strings[46548]="快看！这就是我被抢走眼镜片。虽然已经坏了，不过这是一个好的开始。"
D.Strings[46549]="在那边，伙计。我的猎鹰之眼！我总算能安心地去见我的祖先们了……"
D.Strings[46550]="什么，伙计？他们杀了老呼呼？！不！！"
D.Strings[46551]="我千里迢迢地赶来，绝不会让你拦下！"
D.Strings[46552]="这就好，伙计。现在我可以去找呼呼了……"
D.Strings[46553]="真是浪费。"
D.Strings[46554]="打我呀！"
D.Strings[46555]="让我们庆祝一下吧！"
D.Strings[46556]="庆祝时间已经过了。"
D.Strings[46557]="<利尔的额头十分苍白，冷汗直流。他看起来非常不妙。>"
D.Strings[46558]="<利尔一直茫然地盯着地板，呼吸困难。>"
D.Strings[46559]="干得好，让我们去看看我们的朋友……"
D.Strings[46560]="其他的幼龙马上就到。我会飞在最前面，你们准备好了就跟上。"
D.Strings[46561]="利尔，拜托……省点力气。苏利会把之后的事告诉$n。"
D.Strings[46562]="我们一直往北，在森林里走了几个小时。"
D.Strings[46563]="我们在一棵倒得很蹊跷的树前停下。"
D.Strings[46564]="计划出了些岔子，我们原本是要出来找白卒的。我这会儿早该回到铁炉堡了。"
D.Strings[46565]="一切都搞砸了，$n。这原本只是一项简单的侦查任务。"
D.Strings[46566]="我……<吸鼻子>……我说不下去了！小卢，你来把之后发生的事告诉$n。"
D.Strings[46567]="好了，特工们。听好了。"
D.Strings[46568]="嗯……他管我叫特工！"
D.Strings[46569]="天色已经晚了。我们该扎营了。苏利，你有斧子吗？"
D.Strings[46570]="没有，不过我可以现做。我想想……你是要一把伐木斧呢，还是一把砍人斧？"
D.Strings[46571]="伐木斧。小卢，用这把斧头去砍点木柴。"
D.Strings[46572]="苏利，去查看一下西面那些神龛，找找白卒的踪迹。"
D.Strings[46573]="安玻，去找个好位置，用火力掩护苏利。我们稍后回来汇合。"
D.Strings[46574]="这边，苏利！我找到一个很好的地方。"
D.Strings[46575]="我就躲在这片阴影里。如果你遇到麻烦，就用灯光指出目标，我来对付他们。"
D.Strings[46576]="打得好，安玻！"
D.Strings[46577]="没想到我身边还有一个狙击手吧，嗯？"
D.Strings[46578]="我发誓，那个女人从来没有失手过。"
D.Strings[46579]="我得提醒自己：绝对不要惹恼安玻。"
D.Strings[46580]="砰！打得好！"
D.Strings[46581]="想要偷袭老苏利，嗯？"
D.Strings[46582]="她每次都能一枪爆头。"
D.Strings[46583]="呃……好恶心。"
D.Strings[46584]="我的情况很糟糕，$n。我的伤……我会努力多坚持一会儿的。带我离开这儿，拜托了。"
D.Strings[46585]="我们继续北上，一直走到这片空地附近。"
D.Strings[46586]="我们开始准备扎营过夜。利尔分派了任务。"
D.Strings[46587]="我在口袋里找到个旧的步枪瞄准镜。这东西管用。$b|TInterface\\Icons\\inv_misc_scopeb.blp:32|t$b"
D.Strings[46588]="刀剑出鞘，准备应战。"
D.Strings[46589]="如果我发现有危险，就用光标识出来，剩下的事就由安玻的狙击步枪去料理了。"
D.Strings[46590]="<涓流期待地看着你。>"
D.Strings[46591]="涓流，你能帮我叫醒无垢吗？"
D.Strings[46592]="在西南边的神龛附近没发现安度因的踪迹。"
D.Strings[46593]="可我倒是遇见了一只友善的浣熊，它一直跟着我。"
D.Strings[46594]="我给他起名叫吉兹莫。"
D.Strings[46595]="不！吉兹莫！"
D.Strings[46596]="大战过后，吃起东西来格外香甜。"
D.Strings[46597]="嘿，小家伙！我要给你起名叫吉兹莫。"
D.Strings[46598]="安玻，怎么回事！？我根本没亮过这该死的灯！"
D.Strings[46599]="很快，又有一只浣熊跟我交上了朋友。"
D.Strings[46600]="我给它起名叫袜子，然后又继续前进了。"
D.Strings[46601]="来吧，袜子。趁你还没被打死，我们离开这儿。"
D.Strings[46602]="看那边！暮光教徒好像将上古之神以及他们的腐蚀也带到了龙眠神殿。坚持住！"
D.Strings[46603]="呃……*嗝*……呃……"
D.Strings[46604]="我在北边的神龛一无所获——没有白卒，没有猢狲……什么都没有。"
D.Strings[46605]="侦查过三处神龛后，我就返回了营地。"
D.Strings[46606]="袜子忠心耿耿地跟了过来。"
D.Strings[46607]="花粉重击！"
D.Strings[46608]="我的果园！"
D.Strings[46609]="啊啊啊啊！！"
D.Strings[46610]="不……利尔……"
D.Strings[46611]="唔……唔……嗯……\n\n<我不会……有事的……它会慢慢……消失的……>"
D.Strings[46612]="不。你亵渎死者的恶行到此为止了。"
D.Strings[46613]="这些可怜的灵魂……这边走，它会带领你们返回故乡的。"
D.Strings[46614]="我会抓住你的，灵魂贤者！"
D.Strings[46615]="嗷！太……多了……太多了！"
D.Strings[46616]="我可不能倒在这里，还有很多事情等着我去做呢……"
D.Strings[46617]="诺森德的地底深渊是属于蛛魔的，$r。$B$B我毕生都在为重建这一秩序而奋斗。"
D.Strings[46618]="长官，我们在本月内就能集齐整支第七舰队——"
D.Strings[46619]="陛下！我们终于复原了泰勒最后发出的信息。"
D.Strings[46620]="夜风，你拼合出最后的信息了吗？尽全力去做！"
D.Strings[46621]="没时间了！我们要立即派出一支小队。一支精英战队。去救回幸存者，还有那些珍贵的货物！"
D.Strings[46622]="……原定集结地以西……部落空中部队……[炮火声]……伤亡！"
D.Strings[46623]="胜利今天是属于我们的！"
D.Strings[46624]="……浓雾提供掩护……撤退……未知陆地……"
D.Strings[46625]="……敌对生物。但已找到白卒。重复：白卒是安全的。"
D.Strings[46626]="……[刀剑碰撞声]……紧要危机！请求救援，请求——"
D.Strings[46627]="……遭遇——部族——极端敌对生物……我们——身陷巨大危险……请求救援，我再重复一次——"
D.Strings[46628]="等救出白卒后，我们的海军就能发挥出全部威力，去迎战部落。这次该轮到我们做主了。"
D.Strings[46629]="我回来时，却发现利尔又遭到了猢狲的攻击！"
D.Strings[46630]="安玻！把枪瞄准这边！"
D.Strings[46631]="自从你来了之后，形势迅速好转了，$n。猢狲的威胁空前强大。$b$b可我们锦鱼人……也更加强大了。"
D.Strings[46632]="我们不可能独自对抗猢狲。如果我们的部族想要生存下去，就需要联盟的帮助。"
D.Strings[46633]="利尔在袭击中活了下来，可是他的情况不太好。"
D.Strings[46634]="这个地方很特别。$B$B我正在引导魔法，以修复魔网。虽然这么做会将我撕成碎片，可我还是觉得很不可思议！"
D.Strings[46635]="不要在路上乱扔香蕉皮。"
D.Strings[46636]="先剥皮，再吃香蕉。"
D.Strings[46637]="从猢狲那里偷香蕉，你就等着遇到一只暴怒的猢狲吧。"
D.Strings[46638]="爆竹是用来丢的，香蕉是用来吃的。"
D.Strings[46639]="不擦干毛发就睡觉会不舒服。"
D.Strings[46640]="别在自己的粪便里打滚，除非你想臭上一整天。"
D.Strings[46641]="可以扯别人的尾巴时，绝对不扯自己的。"
D.Strings[46642]="粪便不能吃，但可以用来丢。"
D.Strings[46643]="谢谢你，朋友。要不是你的介入，我现在已经被束缚在那个卑鄙的建筑里了。$B$B但是，我根本就不该留在这个世上。我们必须阻止那些缚灵者。"
D.Strings[46644]="从某个角度来说，我很嫉妒你，小$r。$B$B你真是太幸运了，居然能够见证伟大的艾卓-尼鲁布帝国重生的第一步。"
D.Strings[46645]="前门的情形看起来有点儿……吓人。"
D.Strings[46646]="草地上摆满了小小的青玉雕像。每一个都……栩栩如生。"
D.Strings[46647]="其中有一座雕像特别突出。我从没见过那种生物。"
D.Strings[46648]="哼！什么情形都吓不住我和我的好伙伴袜子！"
D.Strings[46649]="这个家伙肯定收藏了不少雕像……"
D.Strings[46650]="等一下。那不是兽人吗？部……部落也来了！？"
D.Strings[46651]="看看这个……一个锦鱼人和……这是什么东西？一个胡子精吗？"
D.Strings[46652]="我是个矮人，女士。能向您借点儿吃的吗？"
D.Strings[46653]="这个胡子精一定能成为一个很不错的家族藏品！"
D.Strings[46654]="你到底在说些什么呢……"
D.Strings[46655]="苏利……她是想把你变成玉雕，她草地上的雕像都是受害者！"
D.Strings[46656]="然后我终于弄清楚是怎么回事儿了……可那已经太迟了。"
D.Strings[46657]="啊哈哈哈哈！！"
D.Strings[46658]="袜子！不！！！！！"
D.Strings[46659]="暮光审判降临了——万物的末日到了——你阻止不了。你微不足道。微不足道！"
D.Strings[46660]="打倒这些该死的蠢蛋！"
D.Strings[46661]="小的们，干掉他们！"
D.Strings[46662]="打呀，把他们赶回老家去！"
D.Strings[46663]="打到他们，揍死他们！"
D.Strings[46664]="把他们赶回去，杀光他们！"
D.Strings[46665]="你能关闭这座传送门吗，哥哥？"
D.Strings[46666]="很好，我们可以帮你摧毁它。"
D.Strings[46667]="让他们来吧。"
D.Strings[46668]="有一个强大的恶魔在用自己的意志保护着它——是玛诺洛斯。"
D.Strings[46669]="我无法独自摧毁他的意志……"
D.Strings[46670]="他知道了我们的计划。时间不多了，他的恶魔遍布了整片森林。"
D.Strings[46671]="月亮母亲，请您指引我们走出这黑暗。"
D.Strings[46672]="一群软弱的可怜虫。根本配不上“军团”这个称号。"
D.Strings[46673]="噢，这一定很有趣……"
D.Strings[46674]="等等，我有个主意。"
D.Strings[46675]="伊利丹，那个瓶子里装的是什么？你在干什么？"
D.Strings[46676]="调查过那些雕像后，我们看见一个女熊猫人从屋子里走了出来。"
D.Strings[46677]="做我们族人做不了的事。"
D.Strings[46678]="是的……是的。我能感觉到永恒之井的原始力量！是时候结束这场闹剧了！"
D.Strings[46679]="瓦罗森，别让这群乌合之众来打搅我！"
D.Strings[46680]="上层卫士们，动手！为了女王！为了艾萨拉！"
D.Strings[46681]="我打不中他们了！这是什么恶魔邪法？"
D.Strings[46682]="他们并不在我们眼见的位置上！用大范围的攻击，只有这样才能让他们显形！"
D.Strings[46683]="啊，你们到了。\n这里是大分裂的前夕，永恒之井即将毁灭，撕裂整个大陆。\n$b在这里，我们要趁巨龙之魂失落于时间的迷雾之前将其夺回。\n$b但首先，你们必须先破坏艾萨拉的上层精灵侍从们的防护结界。他们就在宫殿里。我则会先行一步。\n$b祝你们好运，英雄们！"
D.Strings[46684]="送我去1号传送门。"
D.Strings[46685]="送我去2号传送门。"
D.Strings[46686]="送我去3号传送门。"
D.Strings[46687]="送我去见首领。"
D.Strings[46688]="跑啊，小卢！快跑！！别让她抓住你！"
D.Strings[46689]="失去一只浣熊微不足道。我们最担心的是那个石化的兽人……以及它背后的意义。剩下的事就让我来说吧。"
D.Strings[46690]="利尔……伤得很重。$b$b<密探吉尔妮用力地捶了地面一拳。>$b$b他快死了，$n！可我们对此却无能为力！"
D.Strings[46691]="不，我们没有找到白卒。$b$b不行，我不能把白卒的身份告诉你。"
D.Strings[46692]="我们在山里扎营。小卢照看利尔。"
D.Strings[46693]="我走到了山顶，手里端着狙击枪。"
D.Strings[46694]="去杀……几个猢狲，安玻。"
D.Strings[46695]="我发现苏利就等在村子外面。"
D.Strings[46696]="我聚精会神，好不容易看清他的口型，他说："
D.Strings[46697]="苏利埋下了一些火药桶，让我来开枪引爆。"
D.Strings[46698]="我给猴子们准备了些礼物！可别打我啊，安玻！"
D.Strings[46699]="这里没什么好看的了！继续前进！"
D.Strings[46700]="啊哈……我看见一个部落的箱子！掩护我，那附近没有掩体！"
D.Strings[46701]="不出我所料……部落也来到了潘达利亚，还和一群猴子结了盟。"
D.Strings[46702]="我们得把这个消息带回珠鳍村……但首先，让我们收拾几个肮脏的兽人。"
D.Strings[46703]="我看到一个缺口！我来了，安玻！"
D.Strings[46704]="哎哟！嘿！"
D.Strings[46705]="让你们再动安玻的坏脑筋！"
D.Strings[46706]="让你们欺负利尔！"
D.Strings[46707]="这个是为吉兹莫和袜子报仇，你们这些混蛋！"
D.Strings[46708]="阿努巴拉克倒下了，兄弟们！从地底深处站起来，夺回我们天赋的权利吧！"
D.Strings[46709]="失败的痛楚将随时间而渐渐平复。"
D.Strings[46710]="|TInterface\\Icons\\spell_nature_moonglow.blp:20|t泰兰德获得了|cFFFF0000|Hspell:103917|h[艾露恩的祝福]|h|r！"
D.Strings[46711]="先祖之灵，请听从我的召唤！从遥远的彼岸归来，让这灵魂服从我的意志！"
D.Strings[46712]="|TInterface\\Icons\\ability_mage_conjurewater11.blp:20|t伊利丹将|cFFFF0000|Hspell:103952|h[永恒之水]|h|r浇在自己身上！"
D.Strings[46713]="你的骚扰到此为止了，$r！灵爪刺客们！干掉这只臭虫！"
D.Strings[46714]="我还要更多的灵魂！更多！马上！"
D.Strings[46715]="我再也不喝酒了！"
D.Strings[46716]="古老的灵魂们啊，从我的法杖中出来吧！向这个畜生复仇吧！"
D.Strings[46717]="嗷！我要揍扁你，揍得你满地找牙，蠢货！"
D.Strings[46718]="该死的蠢蛋！我要把你砸扁！"
D.Strings[46719]="我要揍扁你的鼻子，然后把你抢得精光，蠢蛋！"
D.Strings[46720]="我们的敌人以为能靠冰封的荒原来击败我们。$B$B我们要让他们看看愚昧的后果。"
D.Strings[46721]="快点干！我们必须把这个茧孵化出来！"
D.Strings[46722]="艾卓-尼鲁布帝国复兴的希望就靠我们了！听从我的召唤吧，兄弟们，站起来夺回属于我们的东西！"
D.Strings[46723]="快行动，保护好这个区域！我们还有很多事要做呢。"
D.Strings[46724]="这里出什么事了？"
D.Strings[46725]="千万别告诉我爸妈我来过这里。"
D.Strings[46726]="在那些守卫运转起来之前不准休息。我们决不能受打扰。"
D.Strings[46727]="我想要踢碎一只玉石怪物的脑袋，结果却把爪子弄伤了。"
D.Strings[46728]="下次再让我看见这些青玉怪物，我要狠狠揍扁它们。"
D.Strings[46729]="但愿青玉巫婆没把我的朋友们都抓走。她超级恐怖的。"
D.Strings[46730]="我会紧紧跟着你的。你就是我的保镖了！"
D.Strings[46731]="你真勇敢。你能教我怎么变勇敢吗？"
D.Strings[46732]="暮光大军出现在峡谷上方的悬崖边。"
D.Strings[46733]="我们被包围了——你们去对付那个升腾者，我会处理伏兵。"
D.Strings[46734]="这可不是什么小岛，$n。这是一片足以媲美诺森德的大陆！$b$b至于它为什么一直没有被发现，现在我们还不得而知。"
D.Strings[46735]="带上个猢狲向导恐怕不是什么好主意。"
D.Strings[46736]="继续，里克。"
D.Strings[46737]="后来怎么样了，琪麟？"
D.Strings[46738]="让我听听你其余的报告，夏琪亚。"
D.Strings[46739]="你去对付瓦罗森。玛诺洛斯是我的。"
D.Strings[46740]="你是什么东西啊？$b$b<熊猫人停顿了一下，睁大了眼睛。>$b$b天呐……看看那碧绿的皮肤！"
D.Strings[46741]="我是个兽人，女士。我能问您几个问题吗？"
D.Strings[46742]="那酒真是太顺口了。"
D.Strings[46743]="对你遭受的一切，我非常抱歉。"
D.Strings[46744]="我把布弄丢了。能再裁一块给我吗？"
D.Strings[46745]="可别小看了这些缚灵仪式。一旦魔古族开始大量制造灵俑，就说明他们已经在策划战争了。"
D.Strings[46746]="快趁你的雄鹿发怒之前赶回狐狸森林去！"
D.Strings[46747]="我们必须得把剩下三个灵魂安全带回来。我年事已高，力不从心，而考虑到他们的力量，艾莎和季又太过固执。$B$B你具备英雄应有的一切品质，以及他们所欠缺的平衡。必须由你完成这项任务。"
D.Strings[46748]="我要去笑风山，请送我到寺院的顶层。"
D.Strings[46749]="阿奎里恩开始将萨尔禁锢到冰块之中。"
D.Strings[46750]="很好，这个布景的变换肯定很漂亮。"
D.Strings[46751]="在这里没必要带那么沉的水。"
D.Strings[46752]="能放松一天可真不错。"
D.Strings[46753]="你能帮我的地火操纵者的解码环充能吗？"
D.Strings[46754]="多么欢乐的活动啊。"
D.Strings[46755]="你好！我是酒仙影斟的徒弟，他就是那个被称为疯酒师的熊猫人。$b$B他无视安全、不计后果追求酒香的行为，已导致了不计其数的伤害和疾病。现在，就连当地的野生动物都察觉到他的疯狂酿酒行为了。他是个罪人，我需要你的帮助来阻止他。"
D.Strings[46756]="这一点都不像闪光平原。"
D.Strings[46757]="这里可比赛艇平台上休闲多了。"
D.Strings[46758]="至少在这里我就不用担心被晒伤了。"
D.Strings[46759]="噢，这看上去真有趣！"
D.Strings[46760]="看看这个地方！"
D.Strings[46761]="这地方真大！"
D.Strings[46762]="这个马戏团太令人惊喜了！"
D.Strings[46763]="艾美那里有很多好吃的馅饼。"
D.Strings[46764]="好多活动啊……这里让我想起了贸易区。"
D.Strings[46765]="他们很会推销自己的商品……"
D.Strings[46766]="唔……这里没有人专门制作新鲜面包……"
D.Strings[46767]="这里有着大量的垃圾食品，但到底好不好吃呢？"
D.Strings[46768]="这里的一切都很井井有条。"
D.Strings[46769]="嗯，虽然鲁莽，但能力也足够了。你看起来还有点战斗力，只是需要一点指导。\n$b前面足有好几百个恶魔，一个人冲上去无异于自杀："
D.Strings[46770]="目前看来还不错。"
D.Strings[46771]="有趣……非常有趣。"
D.Strings[46772]="来吧，怒风，我要让你看看，敢于背叛军团之主的人会有什么下场。"
D.Strings[46773]="阴影能很好地掩盖我们的行迹。\n$b这个暗影斗篷遮掩了我的身形，也可以将它的魔法灌注到你身上。\n$b它不能让我们隐身，可只要我们和敌人保持距离，就不会被发现。"
D.Strings[46774]="为你而战，艾萨拉。"
D.Strings[46775]="你身周的这个环能够让外面的人看不到你，可只要你进行攻击或者受到伤害，幻象就会消失。\n$b我建议你隐藏起来，直到我发出指令为止。这些恶魔太强大了，我们无法与他们正面对抗。"
D.Strings[46776]="我来对付这些恶魔。艾露恩，请您指引我的箭矢！"
D.Strings[46777]="快看这些动物，真可爱！"
D.Strings[46778]="艾露恩之光，救救我！"
D.Strings[46779]="噢……真可爱！"
D.Strings[46780]="我可以暂时击退他们！"
D.Strings[46781]="<科拉丝塔萨在你和附近的尸体间来回踱步，她的眉头因为担心而皱了起来。>$B$B我很抱歉，$n。这是红龙军团的私事。$B$B请你先出去帮帮其他人。"
D.Strings[46782]="泰兰德顶不住了！快使用艾露恩的祝福击退恶魔！"
D.Strings[46783]="如果我的商店能大一点就好了，我就能把你们全带回达拉然去了。"
D.Strings[46784]="泰兰德又振作起来了！"
D.Strings[46785]="不见了。被偷了！这是一个可怕的打击。可怕的打击！"
D.Strings[46786]="我们很不走运，没能追踪到丢失的黑龙蛋。$B$B你那儿有什么发现吗，$n？"
D.Strings[46787]="这儿出什么事了？什么东西被偷了？"
D.Strings[46788]="这些动物到底能背几个桶啊？"
D.Strings[46789]="这些家伙能跑多快？"
D.Strings[46790]="这些动物非常出色……"
D.Strings[46791]="你和已故的巨龙瑞亚丝塔萨熟悉吗？那家伙有点不正常。她经常以普通地精的形象在荒芜之地出没。$B$B瑞亚丝塔萨提出了窃取一颗黑龙蛋，并将之净化的计策，以切断它与黑龙军团，以及堕落的大地守护者，死亡之翼间的联系。"
D.Strings[46792]="我们该怎么对付这些恶魔？"
D.Strings[46793]="我准备好躲入你的暗影斗篷了。"
D.Strings[46794]="我是……不会……被打败的……"
D.Strings[46795]="啊哈哈哈哈。受不了了吧，怒风？"
D.Strings[46796]="你怎么敢背叛我？"
D.Strings[46797]="伊利丹被打倒了！玛诺洛斯正在寻找新目标！"
D.Strings[46798]="伊利丹又恢复了！"
D.Strings[46799]="光中之光……我让你失望了。我很抱歉……我的艾萨拉……"
D.Strings[46800]="剑刃刺穿了他的地狱火盔甲！快击败他！"
D.Strings[46801]="瓦罗森的魔法长剑掉在了地上！"
D.Strings[46802]="萨格拉斯大人，我是不会让你失望的！用你的熔岩之拳横扫这个世界吧，让它在烈焰与黑暗中重生！"
D.Strings[46803]="他仍然与永恒之井连接在一起！集中攻击玛诺洛斯！不能让他专心施法！"
D.Strings[46804]="伊利丹，我的箭用光了！月亮女神，请庇护我们不受黑暗的侵袭，保佑我们见到明晚的月光！"
D.Strings[46805]="是的……是的！我能感觉到他的灼热目光，他已经很近……很近了！然后，你们的世界将被毁灭，你们的生命归于虚无！"
D.Strings[46806]="一座巨大的恶魔之门在附近开启了！"
D.Strings[46807]="掌握萨格拉斯力量的可不止你一个，玛诺洛斯！看招！"
D.Strings[46808]="伊利丹……你不能这么做！"
D.Strings[46809]="泰兰德精疲力尽了！艾露恩之光熄灭了！"
D.Strings[46810]="我将成为全族的救世主！我将履行我的使命！"
D.Strings[46811]="不！伊利丹！"
D.Strings[46812]="[恶魔语]Revos ill ok mordanas archim maz naztheros! Archim xi ante maz-re mishun te nagas！"
D.Strings[46813]="我们必须继续前进，你们准备好了吗？"
D.Strings[46814]="泰兰德沐浴在月神的光辉之中！"
D.Strings[46815]="玛法里奥，他成功了！传送门崩溃了！"
D.Strings[46816]="不……不！我不能让到手的胜利白白溜走！我不能带着一场失败回去见他！我不能……这样……离开这个可悲的世界！不，不——！！！！！"
D.Strings[46817]="巨龙之魂安全了。快，在这个世界分裂之前进入时光传送门。"
D.Strings[46818]="巨龙之魂与传送门之间的联系被切断了！它正在坠入永恒之井！"
D.Strings[46819]="我在暗影之中。"
D.Strings[46820]="马戏团好像把所有的观众都引来了！"
D.Strings[46821]="选择太多了，时间太短了……"
D.Strings[46822]="并肩作战，我们才有胜算。"
D.Strings[46823]="甜心！嗨，$c！你对伶牙俐齿魅力四射的女人感兴趣吗？"
D.Strings[46824]="赏几个铜板吧？"
D.Strings[46825]="如果你想活着看到我拯救这个世界的话，就跟我走！"
D.Strings[46826]="恶魔太多，时间不够了。"
D.Strings[46827]="很快，他们就会得到应有的报应。"
D.Strings[46828]="我们被发现了。我知道你们很累，但我们不能让巨龙们等太久！"
D.Strings[46829]="逛逛这个马戏团能让老格里伏塔放松一下……"
D.Strings[46830]="我亲眼看到一个守护恶魔屠杀了上百个精灵。放轻脚步。"
D.Strings[46831]="我会拦住他们，准备通过。"
D.Strings[46832]="我们往东走，去找那些卑鄙的人类。"
D.Strings[46833]="魔力在衰退，我快撑不住了！"
D.Strings[46834]="事情一直很顺利，所以我们决定分头行动。"
D.Strings[46835]="夏琪亚和琪麟处理姑娘们的私事去了。"
D.Strings[46836]="准备攻击……"
D.Strings[46837]="该去喝一杯了……"
D.Strings[46838]="进攻。我可不喜欢磨蹭。"
D.Strings[46839]="畅饮的时刻到了！"
D.Strings[46840]="喝酒是个累人的活儿……快来钓鱼吧！等等，我说反了……钓鱼是个无聊的活儿，快来喝几杯吧！"
D.Strings[46841]="我可以让你打头阵。别让我失望。"
D.Strings[46842]="我可没什么耐性。"
D.Strings[46843]="只剩下我和格罗克。我让他打头阵了……因为他又高又壮嘛。"
D.Strings[46844]="调查过那些雕像后，我们看见一个女熊猫人从屋里走出来。"
D.Strings[46845]="要留心联盟的人。"
D.Strings[46846]="来吧，琪麟。去解决点女士的私事。"
D.Strings[46847]="调查一下这个小屋。里面的人或许见过联盟的幸存者。"
D.Strings[46848]="没错，小屋！好主意。你先走。"
D.Strings[46849]="“停下——谢绝参观。”哈！"
D.Strings[46850]="嘿，格罗克，你喜欢哪个姑娘？夏琪亚还是琪麟？"
D.Strings[46851]="这些雕像……太逼真了。事情有点不对劲，里克。"
D.Strings[46852]="是我的话就选琪麟。她有一双漂亮的眼睛。"
D.Strings[46853]="问题？哈！啊哈哈哈哈！"
D.Strings[46854]="你，“兽人”，一定能成为很不错的家族藏品！"
D.Strings[46855]="那么，格罗克，你觉得我能追到琪麟吗？"
D.Strings[46856]="这是什么见鬼的……？"
D.Strings[46857]="我们要等向导。"
D.Strings[46858]="这个向导太拖拉了……"
D.Strings[46859]="我们得等向导。"
D.Strings[46860]="但愿这个向导能早点到。"
D.Strings[46861]="为了这次观光，我已经等了很久了。"
D.Strings[46862]="我开始怀疑，这个向导永远都不会来了。"
D.Strings[46863]="你是来带我参观的吗？"
D.Strings[46864]="你是我的向导吗？"
D.Strings[46865]="如果你不是我们的向导，就快走开。"
D.Strings[46866]="你是来带我们参观的还是来参观我们的啊？滚开。"
D.Strings[46867]="部落一定是在谋划着什么。他们以前从没直接攻击过我们的运输工具。"
D.Strings[46868]="成功了吗？"
D.Strings[46869]="不管你信不信，她的计划真的成功了。她弄到了一颗蛋——我现在都不知道她到底用了什么办法——而且她声称已经切断了这颗蛋和那个堕落的军团之间的联系。$B$B死亡之翼发现了这件事。$B$B他将瑞亚丝塔萨困在荒芜之地的一个洞穴里，杀害了她，并且毁掉了她的一切努力。至少他是这么认为的。其实，瑞亚丝塔萨是牺牲了她自己的蛋，骗过了死亡的化身。$B$B那颗净化过的黑龙蛋已经被秘密地送走并藏了起来！"
D.Strings[46870]="当然！我在荒芜之地的时候也帮过她的忙。"
D.Strings[46871]="<科拉丝塔萨又打量了你一下。>$B$B你！？你帮助过瑞亚丝塔萨？居然还能活到现在？$B$B我真是低估你了，$r。难怪阿弗拉沙斯塔兹指挥官会把你派来给我。$B$B那你肯定还记得后来发生的事：死亡之翼杀害了瑞亚丝塔萨，但由于她的牺牲，那颗净化过的黑龙蛋被秘密地送走并藏了起来。"
D.Strings[46872]="那颗蛋怎么了？"
D.Strings[46873]="那就是你被派来的原因，$n。那颗蛋原本一直被藏在这里的朱红庇护所内。可几天前，它却突然消失了。$B$B不管这是谁干的，但他们确实骗过了我们最精锐的守卫。其中一个小偷在行动中被我们打死，可我现在认为，那个家伙只是个转移我们视线的幌子而已——那颗蛋就这么不见了。$B$B在他的尸体上，我们发现了这张纸条。上面有我们目前唯一的线索，可它是用一种复杂的密码写成的，我们必须先破解它。"
D.Strings[46874]="一切都非常顺利！我觉得我们真是最佳搭档。"
D.Strings[46875]="他们……他们刚刚攻击了一艘满载乘客的船只！"
D.Strings[46876]="部落似乎决意要扩大这场战争的规模，酋长竟然要把战火烧到我的家乡！"
D.Strings[46877]="有五百艘船只任我调遣，可载有王国命脉的那艘却不见了。这怎么可能？"
D.Strings[46878]="我们已经清理残骸好几天了，陛下。没有找到与海军上将泰勒或他舰船有关的任何线索。"
D.Strings[46879]="我很乐意效劳！把密信交给我吧。"
D.Strings[46880]="是阿弗拉沙斯塔兹指挥官派我来的。他说你这里有一份密信需要破译？"
D.Strings[46881]="怎么那么疼啊？！"
D.Strings[46882]="$n，这就是我们找到的密信残片。你能看懂吗？"
D.Strings[46883]="你是什么东西？！你是谁？！我在哪儿？！"
D.Strings[46884]="我的衣服怎么了？！"
D.Strings[46885]="我只不过想要进城造访几位朋友。从没想到会遇见这种事！部落为何要这么对我们？"
D.Strings[46886]="%s召唤了一颗共鸣水晶！"
D.Strings[46887]="我们得等狂风平息下来，然后突破大厅的屏障。"
D.Strings[46888]="等待另一个机会。我会在远处等你。"
D.Strings[46889]="勇者号上发生了什么事？"
D.Strings[46890]="好了，里克，$n听够了。后面的事让琪麟说吧。"
D.Strings[46891]="部落的战舰拦住了我们，他们的士兵冲上勇者号的甲板。他们夺走了想要的一切，杀死了那些拒绝合作的硬骨头。我们简直寡不敌众……"
D.Strings[46892]="我妻子想要保护我们运往暴风城的货物，结果却被那群兽人抓去丢进了海里！你决不能让他们轻易逃脱！"
D.Strings[46893]="大风！出什么事了？你怎么躲在这里？"
D.Strings[46894]="我设法从攻击者手里抢来了一把武器，想要回击，可他们人太多了。看见没？我还留着那把斧子……"
D.Strings[46895]="他们上船后，我就闭眼躲了起来。求你别再让我说这个了……"
D.Strings[46896]="我们一直向南走到天黑。夏琪亚就说："
D.Strings[46897]="我在口袋里找到一些烟雾弹，肯定能派上用场。$b|TInterface\\Icons\\ability_rogue_smoke.blp:32|t$b"
D.Strings[46898]="如果我遇到敌人的话，就可以用烟雾弹砸他们。夏琪亚的狙击枪会对付他们的。"
D.Strings[46899]="我在前头看到了营火的痕迹，就在雕像的东边。"
D.Strings[46900]="我是在北部神龛找到他的：一个骨瘦如柴的人类士兵。"
D.Strings[46901]="我带着俘虏返回了营地。夏琪亚一定会很满意的。"
D.Strings[46902]="我不能再错过一次货运了！"
D.Strings[46903]="要是我不能运送货物往来卡利姆多，我就完蛋了！"
D.Strings[46904]="乌瑞恩国王会管我们的死活吗？"
D.Strings[46905]="仓库空空，我要怎么做生意？"
D.Strings[46906]="好吧，琪麟。"
D.Strings[46907]="里克。"
D.Strings[46908]="我们马上就扎营。但首先，我们要趁天黑侦察一下周围的环境。"
D.Strings[46909]="好主意。我去侦察前面那片区域。"
D.Strings[46910]="那……那我就来保护琪麟。"
D.Strings[46911]="不，里克。你留下。这次可别再出人命了。"
D.Strings[46912]="噢，知道了……"
D.Strings[46913]="这边，琪麟。"
D.Strings[46914]="我就在这里掩护你。天很黑，你得帮我标出目标。"
D.Strings[46915]="侦察完毕在这里汇合。"
D.Strings[46916]="别动，人类。你逃不了了。"
D.Strings[46917]="我倒想看看，你怎么阻止我逃跑？"
D.Strings[46918]="我没痛下杀手就算你走运了……你看着很好吃。"
D.Strings[46919]="我明白了……这东西见不得光，对吧，$r？噢，不用担心——我们保证对一切交易保密。$B$B你这只解码环是一个杰作。我们可以开始充能了……收费绝对低廉。按照你们那个世界的计算方法，充能大概需要半天时间。换言之，也就是十二个小时。$B$B一万个金币怎么样？这个价钱很公道了。"
D.Strings[46920]="<支付10,000金。>"
D.Strings[46921]="<游学者用温和的目光凝视着你。>"
D.Strings[46922]="<游学者周卓好奇又期待地看着你。>"
D.Strings[46923]="我很好奇你为何会踏上我们的土地，陌生人。$b$b潘达利亚的迷雾迟早会给出答案的……"
D.Strings[46924]="一万金！？你这是抢劫！我非趁你睡觉的时候杀了你不可！"
D.Strings[46925]="你越想找一样东西，就越是找不到。"
D.Strings[46926]="谁也不能毁灭潘达利亚。$b$b野心家只会在潘达利亚碰得头破血流。"
D.Strings[46927]="随便你。$B$B幸好我早就不睡觉了。"
D.Strings[46928]="你是谁……你是什么东西？"
D.Strings[46929]="只有刨根问底，才能明察秋毫。"
D.Strings[46930]="很好，$r！记住，你的解码环需要好几个小时才能彻底充能完毕。"
D.Strings[46931]="仅仅给出答案并不是为师之道。$b$b潘达利亚是授业解惑的圣地。"
D.Strings[46932]="如果你真想了解这些知识，那么当你做好准备时，答案自然会从天而降。"
D.Strings[46933]="学会发问是学习的第一步。"
D.Strings[46934]="要想解惑，你还有很多东西要学。"
D.Strings[46935]="仔细聆听那寂静，$c。它说了什么？"
D.Strings[46936]="你必须学会思考，陌生人。这些鲁莽的问题只能显示你的懒惰。"
D.Strings[46937]="如果我必须现在回答你，那你将会失去原本应得的启示。"
D.Strings[46938]="这些野蛮的猩猩想要杀了我们！告诉我……我们怎么才能打败他们？"
D.Strings[46939]="这片大陆是从哪儿来的？简直就像凭空冒出来的一样！"
D.Strings[46940]="绝不……屈服！"
D.Strings[46941]="滚开！让我们继续痛苦下去吧！"
D.Strings[46942]="黑暗……"
D.Strings[46943]="不得安宁……无法安息……"
D.Strings[46944]="求求你……放了我！"
D.Strings[46945]="该里克了！我知道后面的故事！选我！我在这儿！"
D.Strings[46946]="听说我不是唯一一个无法运送货物进出卡利姆多的人。"
D.Strings[46947]="要是我无法运送货物，我该怎么养家糊口？"
D.Strings[46948]="要是国王无法保证我们的货运安全，他就不配坐在那个王座上！"
D.Strings[46949]="部落这次是想要置我们于死地了。我祈求圣光，希望国王能及时采取行动……"
D.Strings[46950]="过不了多久，部落就会像对待塞拉摩那样对待我们了。国王必须明白……"
D.Strings[46951]="乌瑞恩国王会听你的话，你是联盟的英雄！"
D.Strings[46952]="也许于事无补，但这是我的请愿书。"
D.Strings[46953]="部落要对我们赶尽杀绝，要是国王不尽快派舰队来教训教训他们，我们就死定了。"
D.Strings[46954]="那封密信是我们手中唯一的线索了。"
D.Strings[46955]="我们一直往南走，直到夏琪亚开始感觉不对劲了。"
D.Strings[46956]="琪麟继续前进，而夏琪亚留下看守俘虏。"
D.Strings[46957]="里克或许有点太激动了。"
D.Strings[46958]="对着夏琪亚大喊大叫也没用。里克决定跟着琪麟走。"
D.Strings[46959]="我捏了捏拳头，准备开始战斗。$b|TInterface\\Icons\\inv_gauntlets_05.blp:32|t  |TInterface\\Icons\\inv_inscription_pigment_emerald.blp:32|t$b"
D.Strings[46960]="看，正前方——联盟的轰炸机！"
D.Strings[46961]="我看见了，夏琪亚。我去看看。"
D.Strings[46962]="你不要跟过去，里克。别再把事情搞砸了。"
D.Strings[46963]="行了，你这个白痴兽人！里克受够你愚蠢的命令了！"
D.Strings[46964]="你什么也不是，就是个一脑袋浆糊的蠢货！"
D.Strings[46965]="什——救命！救命啊，夏琪亚！里克！"
D.Strings[46966]="我来救你了，琪麟！"
D.Strings[46967]="里克，你……你救了我的命。"
D.Strings[46968]="那么……嗯……能给里克一个吻吗？"
D.Strings[46969]="当然。等我把面具摘了……"
D.Strings[46970]="见鬼，你的脸怎么了？你……你是死怪物？"
D.Strings[46971]="去死吧，燃烧军团！"
D.Strings[46972]="如果这个陷阱是锦鱼人设下的，他们很快就会回来的。$b$b<琪麟震惊地看着远处的地平线。>$b$b黑暗女王在上……他们来了。快跑啊，里克！"
D.Strings[46973]="绝不！里克要誓死保护你！"
D.Strings[46974]="突然，我听到一阵声响。琪麟被困住了！是锦鱼人的网！"
D.Strings[46975]="冲我来，混蛋！"
D.Strings[46976]="好吧！去杀几个恶心的锦鱼人吧！"
D.Strings[46977]="联盟和锦鱼人……一起打我们？"
D.Strings[46978]="滚出我们的飞机，该死的猢狲！"
D.Strings[46979]="战斗结束之后，我就去找琪麟要我的……奖赏了。"
D.Strings[46980]="重点在于，联盟和锦鱼人结成了联军。过来跟我谈谈，$n。我来把最后一部分报告说给你听。"
D.Strings[46981]="我们要继续前进了，准备好了吗？"
D.Strings[46982]="殿下，在$n的帮助下，我已经完成了对勇者号上所发生事情的调查。"
D.Strings[46983]="部落确实攻击了舰船，使其无法顺利抵达泰达希尔。但那仅仅是开始……"
D.Strings[46984]="兽人的船队开始了对卡利姆多海岸线的封锁。所有旅行者都无法抵达那片大陆，我们商人的货运也被迫中止了！"
D.Strings[46985]="噢，塞拉，塞拉！她是我见过的最美丽的人儿，她有着全潘达利亚最善良的灵魂。$b$b我们想要结婚，可她姓金酿，而我姓游酒。"
D.Strings[46986]="看来加尔鲁什是希望将卡利姆多彻底隔绝？"
D.Strings[46987]="暴风城和联盟决不会让他们得逞，可我们能采取的行动也非常有限。舰队的大部分舰船正在整修中。"
D.Strings[46988]="将军，派塞拉摩的残余舰队前去协助暗夜精灵，并向任何愿意分担我们使命的船长颁发私掠许可证。"
D.Strings[46989]="我会立即着手安排，国王陛下。我认识几位船长，也许能说服他们帮忙应对这次封锁……"
D.Strings[46990]="摧毁水晶，我们就能继续前进了。"
D.Strings[46991]="我们在山上扎营，可以俯瞰锦鱼人村子。"
D.Strings[46992]="在没人看管囚犯的情况下，我必须确保他……没有逃跑的能力。"
D.Strings[46993]="什么——？"
D.Strings[46994]="我拿过狙击枪，瞄准了锦鱼人的村子。"
D.Strings[46995]="琪麟到锦鱼人村子去了。我看见她在村外的灌木丛里潜伏着。"
D.Strings[46996]="我使劲看才看清了她的口型，她说的是："
D.Strings[46997]="来看看我的猢狲毒药对锦鱼人有没有用吧！别误伤了我，夏琪亚！"
D.Strings[46998]="我们肃清了锦鱼人的村子。为防万一，琪麟埋下了一些炸药，由我射击引爆。"
D.Strings[46999]="就给跟我们作对的联盟和锦鱼人留个难忘的教训吧！我们走！"
D.Strings[47000]="夏琪亚，他们发现我了！掩护我！"
D.Strings[47001]="海滩已被肃清。琪麟开始逃跑。"
D.Strings[47002]="该死，又是锦鱼人的网！我们差一点就成功了……"
D.Strings[47003]="我感到村子东部起了骚乱。"
D.Strings[47004]="我回来啦，恶棍！"
D.Strings[47005]="我来啦，琪麟！我也不在乎你那张死怪物脸！"
D.Strings[47006]="里克……"
D.Strings[47007]="来吧，琪麟！我们离开这儿！"
D.Strings[47008]="又有埋伏。小心后面！"
D.Strings[47009]="抓紧时间喘口气，然后我们就继续前进。"
D.Strings[47010]="我的朋友，今天我们将要面对熊猫人有史以来最伟大也最恶毒的酒仙。$b$b现在，他酿的酒有多么危险已经是尽人皆知了，可他还是诱骗了一些人和动物喝下他酿的酒。$b$b我们必须阻止他！你愿意跟我们一起去吗？"
D.Strings[47011]="我跟你走！"
D.Strings[47012]="你不过是个凡人。现在，像个凡人那样卑微地死去吧。"
D.Strings[47013]="够了，萨满！"
D.Strings[47014]="一个不留！"
D.Strings[47015]="这个萨满是我的，你们去对付他的同伴！"
D.Strings[47016]="卑微的凡人。"
D.Strings[47017]="你们的萨满救不了你们。"
D.Strings[47018]="守护巨龙们信错了人。"
D.Strings[47019]="这不算什么！不算什么……"
D.Strings[47020]="没错，我们抓到了一个联盟战俘……可我们付出了什么样的代价呢？"
D.Strings[47021]="为了部落，$n。"
D.Strings[47022]="里克有很多事情要思考呢。"
D.Strings[47023]="你到底在看什么啊？"
D.Strings[47024]="我们的俘虏很奇怪。他没有带武器，而且他的服装很……怪异。$b$b他可能是某个贵族。如果走运的话，我们或许抓住了个大人物！"
D.Strings[47025]="里克是……呃，他是我目前见过的最成熟的猢狲，这就不用多说了。$b$b他真的没有夏琪亚想的那么糟。事实上，我觉得他挺可爱的……以猢狲的方式。"
D.Strings[47026]="他们源源不断地从宫殿中涌出来。"
D.Strings[47027]="我们要走了，跟紧点。"
D.Strings[47028]="一股硫磺的臭气……这些传送门散发出和恶魔一样的邪恶气息。"
D.Strings[47029]="快攻击那个恶魔，不然我就要出手了。"
D.Strings[47030]="从阴影中突袭，干掉他。"
D.Strings[47031]="嗨，我是浅浅！我们以前见过吗？你的脸和那些人很像。就是那些脸上……"
D.Strings[47032]="<纳乐对你微笑，你觉得自己焕发了久违的年轻活力。>"
D.Strings[47033]="我渴死啦！"
D.Strings[47034]="抓住这根绳子，别用力拽。"
D.Strings[47035]="谁在说话？你想要什么？别盯着我看？"
D.Strings[47036]="你能帮我净化这座湖吗？"
D.Strings[47037]="你没看出来我想要自己待会吗？究竟为什么要来打扰我？"
D.Strings[47038]="将军让我把这些瓶子带给你，还让你考虑是否愿意与我们一同对抗部落。"
D.Strings[47039]="看来将军知道我所遭受的……折磨，是吧？我不知道她竟然在乎！"
D.Strings[47040]="我已经躲够了。和铁矮人开战的时候到了。"
D.Strings[47041]="%s狂躁地抓挠着自己。"
D.Strings[47042]="等等……这些……正是我需要的药品。她是怎么知道的？"
D.Strings[47043]="告诉你们的将军，如果这药有效，我的船只和船员就任她调遣。"
D.Strings[47044]="我已经迫不及待想要摆脱这该死的搔痒，重新穿上我那光鲜亮丽的大衣！你的目的已经达到了。走吧！"
D.Strings[47045]="这一点都不疼的。"
D.Strings[47046]="我能再领一顶降落伞吗？"
D.Strings[47047]="谢谢你这么快赶到，$n。"
D.Strings[47048]="这位勇敢的$r竟然来妨碍老阿尔丹喝酒。我能为你做些什么？"
D.Strings[47049]="杰塔瑞斯将军派我来让你加入我们的舰队，粉碎部落对卡利姆多的封锁。"
D.Strings[47050]="接受挑战！以拳还拳，以酒还酒。"
D.Strings[47051]="这个嘛，我已经很久没找到理由，拿部落的舰船练枪法了……"
D.Strings[47052]="听起来会是场激烈的战斗，战利品一定很丰厚！"
D.Strings[47053]="我跟你说，我的船员们已经快把这城里的酒都给喝干了。要是你能劝他们放下酒杯，重新拿起枪，那我就入你的伙！"
D.Strings[47054]="下轮酒你买单？"
D.Strings[47055]="这是要干嘛？"
D.Strings[47056]="你不像是个女招待……"
D.Strings[47057]="太……*嗝*太好喝了。得……休息一下。"
D.Strings[47058]="放下酒杯，把枪拿起来。你的船长要起航了。"
D.Strings[47059]="你的精华……归我了。"
D.Strings[47060]="是，我已经准备好要把兽人的舰船砸得稀巴烂了！"
D.Strings[47061]="好吧，我会去，可得等我准备好才行……"
D.Strings[47062]="噢，我会去拿枪，要是你再敢打扰我喝酒，我就先把你的屁股射出个洞来！"
D.Strings[47063]="我们要让部落付出代价，一定会的！"
D.Strings[47064]="我可不想再去打什么垃圾兽人了！"
D.Strings[47065]="哇……下次别那么快！"
D.Strings[47066]="慢点儿，你这大蠢货！"
D.Strings[47067]="在动手之前先告诉我一声！"
D.Strings[47068]="如果你是来这办正事的，就别绕弯子了。"
D.Strings[47069]="这么生气啊。那我们一定得用一杯…苦酒来让你消停下来！"
D.Strings[47070]="显然我们有了一个很坏的开局。再来一杯……更苦的酒怎么样？！"
D.Strings[47071]="好了，该动真格的了。这是我特别酿制的……痛苦烈酒！"
D.Strings[47072]="杰塔瑞斯将军要派舰队前去打破部落对卡利姆多的封锁。你愿意加入她吗？"
D.Strings[47073]="我很愿意趁此机会惩罚部落犯下的暴行……"
D.Strings[47074]="要是你能打败我最优秀的大副，我就加入你的舰队。"
D.Strings[47075]="威廉姆斯，我们有挑战者了。让这位$c瞧瞧，我们会怎么对付那些兽人！"
D.Strings[47076]="够了！我对你的卓越战技感到心悦诚服。"
D.Strings[47077]="我们应该加入这支舰队，船长。将军的同伴们值得信任。"
D.Strings[47078]="欢迎来到我这个简陋的山谷，孩子。我毕生的目标就是酿造出一种绝世佳酿，它要能胜过你的味蕾所品尝过的一切味道。$b$b我的研究已经快要得出成果了，从没有一个熊猫人能达到我这样的高度。"
D.Strings[47079]="<你着迷地看着这个熊猫人在洞内宁静的空气中画出一条条优雅的弧线。经历了几个小时的动荡和厮杀后，片刻的休憩无疑是最好的享受。$b$b他似乎并没有察觉你的到来，但你越来越相信，他早就捕捉到了你的每一次呼吸。$b$b想到纳兹戈林和其他人，你开始琢磨怎么才能和这个陌生人搭上话。>"
D.Strings[47080]="向一名品酒师发起挑战。"
D.Strings[47081]="宫殿里不再涌出恶魔。我们可以前进了。"
D.Strings[47082]="又是一个来送死的恶魔。"
D.Strings[47083]="他们完全没意识到自己死期将至。"
D.Strings[47084]="火里的草药好像已经把这只动物治好了。谢谢你！"
D.Strings[47085]="$n，你应该知道那最后十六名新兵……"
D.Strings[47086]="好，大家听好了。我们正在进入未知的敌方领土，远离联盟控制地区。"
D.Strings[47087]="但是长官，这片区域的地图没有记录这座岛屿啊。他们在哪儿呢？"
D.Strings[47088]="特拉德！伦斯坦德！不--！"
D.Strings[47089]="你在跟我开玩笑吗，指挥官？我可不是来照看什么菜鸟新手的。"
D.Strings[47090]="我们怎样才能在这片浓雾里找到些什么呢？"
D.Strings[47091]="这里的船员遇到麻烦了。"
D.Strings[47092]="我们先救出他们，然后再担心其它人。出发！"
D.Strings[47093]="知道吗，是我爸爸帮忙建造了这个港口。这里美不美？"
D.Strings[47094]="交给我们了，长官。一定带那孩子回来。"
D.Strings[47095]="嗯，我对这件事情一点都不感到惊讶。他是个伟大的矮人！"
D.Strings[47096]="听着苏利，我们回去之后得好好喝一杯，到时候把与他有关的一切都说给我听。"
D.Strings[47097]="成交！"
D.Strings[47098]="什么？一艘部落的船？在这儿？"
D.Strings[47099]="做完的事就不用反复讨论……过去的事，也不必再去追究。"
D.Strings[47100]="你的鲜血归我了，精灵！"
D.Strings[47101]="醒醒，陌生人！你的打呼声害得我都没法学习了."
D.Strings[47102]="我们得随机应变。与当地人交朋友——无论如何也要抢占摊头。"
D.Strings[47103]="我很好奇。你不会是我师父故意派来让我分心的吧？$b$b亦或是……派你来考验我耐心的？"
D.Strings[47104]="我做好净化湖泊的准备了。"
D.Strings[47105]="那个酒仙对我的湖水做了什么？"
D.Strings[47106]="这味道很古怪……"
D.Strings[47107]="我准备好了。开始你的仪式吧。"
D.Strings[47108]="这附近有个祭坛，我可以在那里举行仪式。我们走吧！"
D.Strings[47109]="恶魔传送门里涌出了大量地狱犬！"
D.Strings[47110]="恶魔传送门里涌出了大量恶魔卫士！"
D.Strings[47111]="恶魔传送门里涌出了大量末日守卫！"
D.Strings[47112]="天空中落下了大量地狱火！"
D.Strings[47113]="嘿，我的肚子在发牢骚了。我们已经飞了几个小时了！"
D.Strings[47114]="好了，都看仔细。这附近应该会有大陆块，幸存者可能就在上面。"
D.Strings[47115]="难以置信！是联盟的颜色！"
D.Strings[47116]="泰勒一定就在附近。"
D.Strings[47117]="你必须学会融入这片土地，陌生人。$b$b只有这样，你才能探知它的秘密。"
D.Strings[47118]="我准备好了，可以开始冥想课程了。"
D.Strings[47119]="艾莎花在修炼上的时间似乎太长了……但成效着实不错。她的风度十分迷人。"
D.Strings[47120]="深呼吸，陌生人……"
D.Strings[47121]="约束你的思想。"
D.Strings[47122]="打败影斟之后，他的酒仙之位就传给了我。现在，我必须去挽救他对这座山谷造成的伤害了。"
D.Strings[47123]="我还记得，在我的商店里看到那么多人流时的情景……"
D.Strings[47124]="能时不时从沙塔斯出来逛逛还真不错。"
D.Strings[47125]="连一辆卖苹果的小货车都看不到……"
D.Strings[47126]="这么多垃圾食物……连一个苹果都没有。"
D.Strings[47127]="而你敢确定，那个史密斯奶奶一直把她的苹果放在我们的货摊上？"
D.Strings[47128]="所以说，水果商其实无意跟我们作对？真是难以置信……"
D.Strings[47129]="如果你说水果商是个老奶奶的事是真的话……呸！这不可能！"
D.Strings[47130]="所以我那些卖力的吆喝……都是白费力气……大家肯定觉得我是个白痴……"
D.Strings[47131]="$n叹了口气。"
D.Strings[47132]="$n摇摇头，叹了口气。"
D.Strings[47133]="$n用手捂住脸，长叹了一口气。"
D.Strings[47134]="你看不出来我正在努力建造船只吗？一会是你，一会是那些暗夜精灵，我们永远也干不完了！"
D.Strings[47135]="酋长想知道，为什么他的船只迟到了。"
D.Strings[47136]="酋长？是不是那个总是穿着长刺的巨型肩甲，脾气暴躁，对斧子有种病态偏执的大个子？是那个酋长吗？"
D.Strings[47137]="这个嘛，呃，事实是，原本是有船的。原本有的！"
D.Strings[47138]="那些暗夜精灵不知怎的发现了我们要派出舰队，于是就发起了攻击！大部分停泊在港口里的新造船只都被烧毁了！"
D.Strings[47139]="我知道要想挽救这些船只已经来不及了，但也——也许你能解决掉剩下的那些攻击者……"
D.Strings[47140]="去告诉酋长，这不是我的错！我的兄弟们抓起木槌或是手边可用的一切武器奋起回击，我发誓！"
D.Strings[47141]="我们的人不能再袖手旁观了。我们必须把整个奥杜尔的所有大厅扫荡一遍！"
D.Strings[47142]="我是伟大的里克里克之子，他曾与邪恶的天怪战斗，抢了他们的财物。他死了，现在我是将军了，这是我的地盘。在强大的将军里克里克二世面前颤抖吧。"
D.Strings[47143]="我没法在遭受攻击的状态下开启接天桥！"
D.Strings[47144]="你必须无视周围的环境，努力保持平衡……"
D.Strings[47145]="你，立刻去港口与指挥官夜风会面。"
D.Strings[47146]="管好你自己的事吧。"
D.Strings[47147]="你又失败了，陌生人。"
D.Strings[47148]="你为什么要来打扰我？"
D.Strings[47149]="你想惹我发火吗？"
D.Strings[47150]="要是你不想让自己的脑壳被斧子劈开，就躲远点！"
D.Strings[47151]="这是新兴的$r配对仪式还是什么？别来烦我！"
D.Strings[47152]="你没其它事情可做了吗？"
D.Strings[47153]="在我发火之前，离我远点儿！"
D.Strings[47154]="去马车底下玩吧，倒霉蛋！"
D.Strings[47155]="别再盯着我看了，去做些有用的事！"
D.Strings[47156]="你——你是怎么找到我的？"
D.Strings[47157]="别让他们靠近我！我需要集中精神打开接天桥！"
D.Strings[47158]="噢，一个客人。我这里的客人可不多。$B$B饿了吗？我做了很多好吃的东西，亲爱的。$B$B不不，不是鱼。只有在我抓不到什么好东西的时候，才会拿鱼出来充数。"
D.Strings[47159]="唔，或许我是看错了你，陌生人。"
D.Strings[47160]="归魂入缶，喜乐安康。"
D.Strings[47161]="我想……我大部分的债已经还清了……"
D.Strings[47162]="我想，就算我不留在这里帮忙经营马戏团，别人也不会介意的吧。"
D.Strings[47163]="我的债已经基本还请了。谁也不会在乎剩下的那点金币的……"
D.Strings[47164]="躲避攻击!"
D.Strings[47165]="无惧黑暗，彼岸在望。"
D.Strings[47166]="这到底是什么东西？"
D.Strings[47167]="我们快走！靠大雾甩掉他们！"
D.Strings[47168]="我们要在水面上紧急迫降了！"
D.Strings[47169]="弹射！引擎要爆炸了！"
D.Strings[47170]="我们肯定搞不定的！我马上就来见你了，老爹！"
D.Strings[47171]="接天宝桥，归我故乡。"
D.Strings[47172]="冥途茫茫，不知所往。"
D.Strings[47173]="毫光灼灼，在彼一方。"
D.Strings[47174]="他就在附近，躲藏在阴影里……我能感觉得到。"
D.Strings[47175]="保持警惕。传送门绝不能被封印。"
D.Strings[47176]="你，恶魔卫士，守住这片区域。"
D.Strings[47177]="剩下的，保护庭院。"
D.Strings[47178]="不了，谢谢。"
D.Strings[47179]="你找暗影猎手乌克金有什么事吗？"
D.Strings[47180]="灵魂已经为乌克金祝福了这个远航图腾。它们将随他一同去对抗我们的敌人。"
D.Strings[47181]="灵魂贤者！！"
D.Strings[47182]="终于……这无尽的折磨终于结束了。"
D.Strings[47183]="有了这个图腾，灵魂将庇佑你参与封锁行动。"
D.Strings[47184]="灵魂已经赐予我眷顾的启示！我的兄弟们将参加这次封锁行动。"
D.Strings[47185]="我的兄弟们对你感激不已，$n。这个图腾是战争的强力征兆。"
D.Strings[47186]="我们要向酋长展示暗矛的勇猛和卓越战技！"
D.Strings[47187]="我很快就会赶上他们的，但首先请允许我表达我的谢——"
D.Strings[47188]="我说了我会抓住你的，裴智。你今天放跑了几千条灵魂，不过能用它们引你入彀，我就很满足了。"
D.Strings[47189]="至于你，小$c。"
D.Strings[47190]="%s检查着散落在地上的尸体。"
D.Strings[47191]="继续派炮灰来送死是徒劳的。相反，我要给你一个教训……"
D.Strings[47192]="头也不回地逃跑吧！就算是你，也抵挡不住我的下一次缚灵术！"
D.Strings[47193]="%s看着裴智傻笑。"
D.Strings[47194]="我们现在躲藏在阴影中，不让敌人发现。"
D.Strings[47195]="就是你这个光溜溜的小笨蛋？嗯？"
D.Strings[47196]="把这个蠢货拖出去去喂鱼！"
D.Strings[47197]="笨蛋小偷休想偷走猢狲的鱼！"
D.Strings[47198]="摧毁水晶，我们要继续前进。"
D.Strings[47199]="摧毁传送门的能量核心！"
D.Strings[47200]="不。是纳兹戈林将军派我来雇佣你和你的船员，加入卡利姆多封锁舰队。"
D.Strings[47201]="要照料的人太多了……"
D.Strings[47202]="我总是无法丢下受伤的朋友不管……"
D.Strings[47203]="马戏团就是我的家。我永远离不开它。"
D.Strings[47204]="需要帮助的人太多了……"
D.Strings[47205]="快关闭传送门，我们还要继续前进。"
D.Strings[47206]="蠢蛋吃上去大概和光板儿差不多……"
D.Strings[47207]="对兽人的战争似乎已经迫在眉睫了。"
D.Strings[47208]="尽管我手下的亡魂无数，可我只是想逃离那些噩梦而已。"
D.Strings[47209]="他们向我保证，进了马戏团里就永远不会面临恐怖的战争。"
D.Strings[47210]="只要价格合理，我和船员们就乐意效劳。$B$B鉴于纳兹戈林将军是位可敬的兽人，我就先要100个金币好了，但要记得给我和兄弟们发放丰厚的危险津贴啊。"
D.Strings[47211]="很好。你会拿到钱的。"
D.Strings[47212]="那就这么说定了。战斗中见吧，$n。"
D.Strings[47213]="我在孩提时代就加入了马戏团……"
D.Strings[47214]="我一生中的大部分都是在马戏团里度过的，它就是我的家。"
D.Strings[47215]="为了躲避父亲的毒手，我逃出了位于激流堡的家。"
D.Strings[47216]="加入马戏团之前，我的生活苦不堪言。我一点都不想再回忆起那段时光，和那个家。"
D.Strings[47217]="为了逃离那个家，我加入了马戏团。"
D.Strings[47218]="我还记得我跟希拉斯说过：“我永远也不想再见到我的家人了。”"
D.Strings[47219]="……把光板儿蠢蛋煮了……给卡卡大王吃！"
D.Strings[47220]="我原本是出来帮营地收集些柴火的……"
D.Strings[47221]="收集柴火对我来说太辛苦了……"
D.Strings[47222]="我好像看到附近的灌木丛里有什么东西……然后我就晕过去了。"
D.Strings[47223]="当我醒来时，已经找不到回营地的路了……"
D.Strings[47224]="我会跟着你的，$n。"
D.Strings[47225]="关闭最后的传送门，做个了断。"
D.Strings[47226]="就算是死亡，也不能阻止我履行守护营地的职责……"
D.Strings[47227]="这片树林很危险。这是我历经千难万险之后得到的教训。"
D.Strings[47228]="我必须盯紧营地。"
D.Strings[47229]="我也不知道自己已经守护这营地有多久了……"
D.Strings[47230]="我差点就死在一场海难中……"
D.Strings[47231]="希拉斯把我从那群绑匪手里救了出来……"
D.Strings[47232]="我眼看着那些绑匪死得惨不忍睹。$b$b忍不住哈哈大笑。"
D.Strings[47233]="马戏团让我逃过一死。它救了我的命。"
D.Strings[47234]="只要我为马戏团工作，希拉斯就会帮我偿还大部分债务。"
D.Strings[47235]="嗷嗷！！"
D.Strings[47236]="*嗝*……呃……*嗝*"
D.Strings[47237]="*嗝*"
D.Strings[47238]="*嗝*……呃……啊？"
D.Strings[47239]="恶魔应该都离开了。我们很快就能进入宫殿。"
D.Strings[47240]="坚持住，中尉！"
D.Strings[47241]="小心那些鹿角小飞兔！它们总会趁你毫无防备的时候冲出来咬你一口。"
D.Strings[47242]="我的土豆呢？"
D.Strings[47243]="我们侍奉世界真正的主人！当他们的秩序降临，我们将分享他们的荣光！"
D.Strings[47244]="那些小熊猫有点意思。我想我或许可以改进一下酒仙影斟的配方，让酿出的酒不再致命。"
D.Strings[47245]="我或许可以用兰花和净水开发出一种终极佳酿的配方。但我们必须去酒仙影斟的蒸馏室才能把他酿造出来。为此，我们必须在他的强项上打败他。"
D.Strings[47246]="我们可以用你收集的兰花来净化疯酒师山谷的湖水。但我们需要帮助。$b$b我的朋友浅浅是个水灵，曾帮我酿造过一些酒。在净化水体时，他是很有帮助的。他应该知道怎么分配这些草药才最合适。"
D.Strings[47247]="是季派你来吗？我喜欢季！她有一张快活的脸。而疯酒师呢，他是一个刻薄鬼，那张干巴巴的丑脸又大又肥！$b$b你能帮我去安抚我那些水灵朋友吗？那个皱脸的刻薄鬼在水里放了恶心的东西。"
D.Strings[47248]="蠢蛋干掉了鳄鱼？好蠢蛋？"
D.Strings[47249]="蠢蛋救了猢狲？"
D.Strings[47250]="猢狲没死，又能钓鱼了！"
D.Strings[47251]="是蠢蛋干掉了鳄鱼，救了猢狲？"
D.Strings[47252]="猢狲要告诉图奇图奇，是蠢蛋干掉了鳄鱼！"
D.Strings[47253]="你到底是谁？"
D.Strings[47254]="你们很会捉迷藏，虫子。但你们能藏多久呢？"
D.Strings[47255]="色彩。它赋予了我们反差、深度、浓淡和色调的变化。稍微调整一下色彩，就能让欢笑中的人们潸然泪下。"
D.Strings[47256]="每一笔一划，都表达了一个意象。它让人们的思想跃然纸上，吸引了观看者的注意力。"
D.Strings[47257]="又是一群死亡之翼的信徒？我保证你们会死得特别痛苦。"
D.Strings[47258]="玉石俱焚！"
D.Strings[47259]="而你的故事也结束了。"
D.Strings[47260]="看着吧，邪教徒，死亡降临了！"
D.Strings[47261]="这不是……我想要的……结局。"
D.Strings[47262]="你的魔法伎俩真可怜。瞧瞧我的手段吧。"
D.Strings[47263]="让我们玩个游戏吧，嗯？躲好点，虫子，那样你们或许能多活几分钟……"
D.Strings[47264]="你们竟敢违抗我？！"
D.Strings[47265]="没有凡人能从我手中逃脱！"
D.Strings[47266]="我这一生中有过许多子女，以及许多孙辈。可没有一个曾孙辈的孩子来看望过我。他们几乎都忘了伟大的风裘家族。"
D.Strings[47267]="一块传导水晶开始过载了！"
D.Strings[47268]="你想为那个下贱的过街老鼠而战？很好。只要你能打败我，我就会给出我的祝福。"
D.Strings[47269]="行了！你赢了……勇士。去告诉那个暴发户吧，就说我祝福他。"
D.Strings[47270]="挑战族长。"
D.Strings[47271]="真痛快！我已经好多年没打得这么痛快过了。为那个孩子带去我的祝福吧。"
D.Strings[47272]="力量！这才是棘杖家族的生命之源。我的家族能延续至今，就是强大的肉身力量不惧任何挑战的最好明证。"
D.Strings[47273]="游酒家的人想跟金酿家联姻？！荒唐。"
D.Strings[47274]="我认输！那个小鬼选对了人。请把我的祝福带给他，千万别让他浪费了我的好意。"
D.Strings[47275]="我看见你了。"
D.Strings[47276]="一个支持者。"
D.Strings[47277]="我亲眼见证了家族的衰落。我们曾是最伟大的酒仙，现在却只能排在风暴烈酒家族后头，呸！"
D.Strings[47278]="风儿告诉我说，你帮助我的曾曾曾孙女季实现了成为酒仙的梦想。$b$b我为她感到骄傲，也非常感谢你的帮助。是你帮我的家族走回了正道。"
D.Strings[47279]="我听说，你从青玉巫婆手里救出了我的一个晚辈。对于你的义举，我深表感谢。"
D.Strings[47280]="你要走了吗？"
D.Strings[47281]="我想和你们的酋长对话。"
D.Strings[47282]="愿你的清水永不干涸。"
D.Strings[47283]="看，希望之锣！好吧，没错，这其实是一口钟，几百年前，我们就把原来那面锣给换掉了。那面小锣发出的声音不够洪亮，没办法给我们提供足够的希望之声。"
D.Strings[47284]="你对钟和锣的知识有兴趣吗？这年头，像你这样乐意来一场神奇的知识之旅的年轻人可不多了。"
D.Strings[47285]="旅行者，我想冒昧地问一句，你有没有从下面的林子里带点竹子上来？我在这里巴望了一整天了，却只能空流口水。我在这里，只能吃自己用有限的魔法召唤出来的食物。"
D.Strings[47286]="<范妮小姐坚定地凝视着前方。她下定决心要完成任务。>"
D.Strings[47287]="<范妮小姐充满期待地看着你。>"
D.Strings[47288]="用力击打。"
D.Strings[47289]="轻轻地打。"
D.Strings[47290]="有多大劲，使多大劲。"
D.Strings[47291]="够了！该结束这场无聊的游戏了。"
D.Strings[47292]="用力打我！"
D.Strings[47293]="轻轻地打我！"
D.Strings[47294]="现在……阴影为我效命！"
D.Strings[47295]="我会找到你的！"
D.Strings[47296]="阴影也救不了你。"
D.Strings[47297]="在角落里发抖吧，哼。"
D.Strings[47298]="哼。好吧。这比我想象中的还要容易！"
D.Strings[47299]="你……比我想象中……更出色……"
D.Strings[47300]="嗬！这么快？"
D.Strings[47301]="但愿你的朋友们能表现得好些。"
D.Strings[47302]="嗯，太有趣了！"
D.Strings[47303]="晚安……"
D.Strings[47304]="一个惊喜。"
D.Strings[47305]="现在你看见我了……"
D.Strings[47306]="什么也阻止不了我。连你也不行，恶魔。"
D.Strings[47307]="快回阴影里去！"
D.Strings[47308]="我的力量恢复了。"
D.Strings[47309]="是谁关闭了传送门？狡猾的小爬虫。"
D.Strings[47310]="想进入宫殿？先打败佩罗萨恩，魔能的第一个赐福者吧。"
D.Strings[47311]="解释你的来意。"
D.Strings[47312]="有话快说。"
D.Strings[47313]="猎手成了猎物。"
D.Strings[47314]="你干得很好，可现在我必须独自行动了。狩猎愉快。"
D.Strings[47315]="哇！我感觉好极了！"
D.Strings[47316]="我必须回去干活儿了！"
D.Strings[47317]="我的感觉从没这么好过！谢谢你！"
D.Strings[47318]="我又重获新生了！谢谢你，陌生人。"
D.Strings[47319]="干活，干活，干活！我爱干活！"
D.Strings[47320]="%s开始将所有人变成木偶！你必须打断她的法术！"
D.Strings[47321]="|TInterface\\Icons\\ability_warrior_bloodnova.blp:20|t%s受到伤害，长出|cFFFE9A2E灼疮触须|r！"
D.Strings[47322]="光板儿？"
D.Strings[47323]="你只有这一次亲眼目睹的机会。"
D.Strings[47324]="我看见一个三只眼的光板儿。这是坏兆头。"
D.Strings[47325]="没有坦克。看那体格儿就知道了。"
D.Strings[47326]="我吃过滑水鱼，嘎嘣脆，香蕉味儿。"
D.Strings[47327]="光板儿现在不光了？"
D.Strings[47328]="猢狲炮弹！"
D.Strings[47329]="醒醒，陌生人！你在我的屋子里干什么？"
D.Strings[47330]="谁偷了我的鱼？"
D.Strings[47331]="要让我知道，一定得教训教训他们。"
D.Strings[47332]="询问超霸里克里克的事迹。"
D.Strings[47333]="这片陆地是哪儿来的？怎么会隐藏了几百年都没人知道？"
D.Strings[47334]="我要怎么才能帮助锦鱼人战胜这些野蛮的猴子呢？"
D.Strings[47335]="你能帮我找到白卒吗？"
D.Strings[47336]="检查地上那堆冒着热气的臭东西。"
D.Strings[47337]="谁的东西丢了？"
D.Strings[47338]="已经满溢的杯中不可能容纳更多的水。"
D.Strings[47339]="首先，你必须将自己想象成一个空坛子。"
D.Strings[47340]="回到平原鹰背上！"
D.Strings[47341]="光板儿？救我救我救我！"
D.Strings[47342]="蠢蛋救了猢狲？好蠢蛋！"
D.Strings[47343]="他们死定了。"
D.Strings[47344]="灰飞烟灭，寸草不生。"
D.Strings[47345]="已经满溢的杯中不可能容纳更多的水。在你获得真正的智慧之前，必须清空自己的头脑。"
D.Strings[47346]="把你的蔬菜统统给我！"
D.Strings[47347]="啊——咿——！"
D.Strings[47348]="%s感觉到玩家在他的左侧。他开始向左侧翻滚！"
D.Strings[47349]="这是兔妖的地盘！"
D.Strings[47350]="别抢我的萝卜！拿芜菁和你换！"
D.Strings[47351]="%s感觉到玩家在他的右侧。他开始向右侧翻滚！"
D.Strings[47352]="%s向左侧翻滚！"
D.Strings[47353]="%s向右侧翻滚！"
D.Strings[47354]="你好，朋友。想顺便买点儿什么吗？"
D.Strings[47355]="我让我儿子昂管理山下的菜园。我侄子梁在西边的山下经营着一个养猪场，他父亲——也就是我兄弟——在南边的山下开了个小型牧羊场。$b$b我现在不务农了。最近，我只收购别人收割的庄稼，再向路人贩卖。虽然走动得少了，但我兜里的钱却多了。"
D.Strings[47356]="抢光他们的鱼！"
D.Strings[47357]="休想抢我的香蕉！"
D.Strings[47358]="猢狲跟蠢蛋……做朋友？"
D.Strings[47359]="蠢蛋在救猢狲？$b$b蠢蛋喜欢猢狲？"
D.Strings[47360]="猢狲开始喜欢蠢蛋了。$b$b蠢蛋大概没那么坏……"
D.Strings[47361]="迷雾发现了你！"
D.Strings[47362]="你周围开始起雾了。"
D.Strings[47363]="你周围的雾气愈发浓密了。"
D.Strings[47364]="迷雾彻底吞没了你！"
D.Strings[47365]="迷雾之外浮现出了一个生物！"
D.Strings[47366]="迷雾散去了……"
D.Strings[47367]="%s保持平衡。"
D.Strings[47368]="我被俘之前，足足干掉了二十个猢狲！"
D.Strings[47369]="我被关在笼子里是你的运气。"
D.Strings[47370]="我的人民和他们的新盟友会把这个村子夷为平地的。"
D.Strings[47371]="猢狲！你们的好日子到头了。我们有新盟友了！"
D.Strings[47372]="你的样子真可笑。"
D.Strings[47373]="我们行动吧，朋友！不能再浪费时间了。"
D.Strings[47374]="科拉丝塔萨的焦虑也是可以理解的。毕竟她照料着唯一一枚没有被死亡之翼的堕落所腐蚀的黑龙蛋……"
D.Strings[47375]="……可一群小偷却趁夜从我们手里偷走了它！"
D.Strings[47376]="你帮我们找到了唯一的线索。拉文霍德的盗贼就是幕后黑手。"
D.Strings[47377]="拉文霍德？这可真奇怪！那不过是一群小毛贼。他们怎么可能知道龙蛋的事？"
D.Strings[47378]="我们会查清这件事的。我们正需要你这样有能力的人。"
D.Strings[47379]="俗话怎么说的？“以其人之道”的后面？"
D.Strings[47380]="看看这片狼藉的土地。这片丘陵一直没能从第二次和第三次战争中恢复过来。"
D.Strings[47381]="到处都是废墟和遗骸……我原以为拉文霍德的盗贼和刺客不过是其中的一部分。"
D.Strings[47382]="没有动机……没有理由……你觉得他们到底怎么了？"
D.Strings[47383]="他们到底是着了什么魔，竟敢和红龙军团作对？真是疯了。我们必须了解真相！"
D.Strings[47384]="我们接近拉文霍德庄园了。"
D.Strings[47385]="如果他们拿到了那枚蛋，那么发动全面进攻就太危险了。你需要潜入那里，查清他们的阴谋……并不惜一切夺回那枚蛋。"
D.Strings[47386]="安静点！我们要在这个洞穴里制定一个计划……"
D.Strings[47387]="躲起来吧，虫子！狩猎开始了……"
D.Strings[47388]="约格塔德的口信？他还欠我钱呢。"
D.Strings[47389]="这地方太棒了！看到他们这里有多少食物了吗？"
D.Strings[47390]="当然，其他人可能已经踏上了激动人心的探险之旅，但我并不在乎。我在这里过得非常开心。"
D.Strings[47391]="从修道院长途跋涉而来可苦了我的脚——还有我的胃。我想在重新考虑启程先在这儿大吃一顿，以恢复体力。"
D.Strings[47392]="不知道你发现了没有，这是个家庭农场。我们雷脚家的人不斗争、不探险……甚至不怎么喝酒。$b$b但我们很享受美食带来的快乐。"
D.Strings[47393]="经营养猪场比你想象的要复杂……尽管多数时候可以将其概括为“寻找更多的猪食”。"
D.Strings[47394]="啊啊！老鹰！$b$b啊啊啊啊！狼来了！"
D.Strings[47395]="我再也受不了了！我真的要去对付那些狼吗？"
D.Strings[47396]="我的羊！来人啊，帮帮忙啊！"
D.Strings[47397]="走吧，陈叔！我们还等什么呢？"
D.Strings[47398]="别着急，丽丽。我们有大把的时间来探索潘达利亚。花点时间来享受这个旅程吧。"
D.Strings[47399]="我是想“享受”旅程，可那也得先“出发”才行！"
D.Strings[47400]="那现在呢？"
D.Strings[47401]="出发吧！整个大峡谷等着我们去探索呢，可是你却只盯着杯底那点儿啤酒。"
D.Strings[47402]="是啊，丽丽，但是这杯底的啤酒确实非常吸引我。"
D.Strings[47403]="那我自己去。别以为我只是随口说说。我可不需要某个臭哄哄的大叔牵着我。"
D.Strings[47404]="你怎么这么没耐心？难道你担心我还没喝完啤酒，迷雾又把岛笼罩起来了？"
D.Strings[47405]="我还真担心！"
D.Strings[47406]="我们好不容易才回到故土，有生以来第一次踏上这片土地，你难道只想在养猪场里休息吗？"
D.Strings[47407]="耐心点儿吧，丽丽。如果我们那么快就把潘达利亚逛个遍，那我们很快就没得玩了。"
D.Strings[47408]="这……你说的都是废话！你这么说都是因为你又老又懒！"
D.Strings[47409]="[TEMP]我能留在这儿吗？好的。谢谢！"
D.Strings[47410]="我只能帮助你开始这段旅程。丰厚的奖励在等待着你，可是否要完成它就完全取决于你自己了。"
D.Strings[47411]="你的气势很惊人，陌生人。我还无法确定你究竟会给这片大陆带来光明还是黑暗，可我知道你有一颗坚定的心。"
D.Strings[47412]="我不喜欢陌生人，可我在你身上看到了巨大的潜力。是的……你或许会成为一个非常有趣的徒弟。"
D.Strings[47413]="我还需要一瓶洄梦仙酒，大师。"
D.Strings[47414]="不！我的羊！"
D.Strings[47415]="嘿！把我的羊还给我！"
D.Strings[47416]="对不起，小羊！"
D.Strings[47417]="滚……滚开！把我的羊还给我！"
D.Strings[47418]="回来！那是我的羊！"
D.Strings[47419]="哦，天啊，糟糕……"
D.Strings[47420]="弗二郎！我们得谈谈！"
D.Strings[47421]="完成了就来找我，$n。我就住在路那头的小农舍里。"
D.Strings[47422]="啊哦……师父来了……"
D.Strings[47423]="|TInterface\\Icons\\inv_gizmo_supersappercharge.blp:20|t%s正在施放|c0087CEFA|Hspell:105845|h[核能冲击]|h|r！"
D.Strings[47424]="魏，这些是你的朋友吗？"
D.Strings[47425]="朱红庇护所是我们在暮光高地上的行动基地。$B$B我们可以从这个制高点监督对格瑞姆巴托的进攻，以及对下方河谷的清扫行动。"
D.Strings[47426]="你好，$r！如果你是在找科拉丝塔萨，那她就在里面。$B$B<莫奥斯塔兹不安地挪动了一下身体。>$B$B她的心情可不太好。"
D.Strings[47427]="$n！你破译了密信，干得好。让我们弄清事情的真相吧。$B$B你做好飞行的准备了吗？"
D.Strings[47428]="我准备好了！我们去拉文霍德吧。"
D.Strings[47429]="我……我真不敢相信，你居然做到了！你可能会死在那里啊！你与那只鹰打成一团，还利用它的双翼成功着陆……太不可思议了！$b$b既然你能做到这一切，那么……那么我也可以对付那些微不足道的狼和平原鹰！对我弗二郎来说，这是个崭新的开始。$b$b这一切都要感谢你，$n。"
D.Strings[47430]="他……他刚才是说我就像他的儿子一样吗？"
D.Strings[47431]="哇，我从没见过你这样的东西！"
D.Strings[47432]="你看起来真吓人！幸好我哥哥说你很友好。"
D.Strings[47433]="你真把我兄弟救出来了？那个白痴居然成了猢狲的俘虏，幸好他遇见了你。"
D.Strings[47434]="你穿的这么多，要怎么游泳啊？"
D.Strings[47435]="%s召唤|cFF9932CD|Hspell:104896|h[紫色]|h|r，|cFF088A08|Hspell:104898|h[绿色]|h|r，以及|cFF0080FF|Hspell:104900|h[蓝色]|h|r舒玛之血！"
D.Strings[47436]="是时候了，$n。苏利和我要去侦察岛屿的内陆地区了。"
D.Strings[47437]="只要他留下了线索，我们就能找到。"
D.Strings[47438]="我发誓会保护他的安全。我们会尽快赶回来。"
D.Strings[47439]="$n，你留下，帮助泰勒恢复。"
D.Strings[47440]="去和锦鱼人交个朋友吧。在完成任务之前，我们或许需要他们的帮助，这是命令。"
D.Strings[47441]="等等！虽然我们还不算朋友，可你也不能独自一人进入不熟悉的区域。"
D.Strings[47442]="%s召唤|cFF088A08|Hspell:104898|h[绿色]|h|r，|cFFFF0404|Hspell:104897|h[红色]|h|r，以及|cFF424242|Hspell:104894|h[黑色]|h|r舒玛之血！"
D.Strings[47443]="我会让我弟弟跟你一起去。"
D.Strings[47444]="%s召唤|cFF088A08|Hspell:104898|h[绿色]|h|r，|cFFFFA901|Hspell:104901|h[黄色]|h|r，以及|cFFFF0404|Hspell:104897|h[红色]|h|r舒玛之血！"
D.Strings[47445]="请把他安全地带回来。他还年轻，但很聪明。他能为你们带路。"
D.Strings[47446]="%s召唤|cFF9932CD|Hspell:104896|h[紫色]|h|r，|cFF0080FF|Hspell:104900|h[蓝色]|h|r，以及|cFFFFA901|Hspell:104901|h[黄色]|h|r舒玛之血！"
D.Strings[47447]="%s召唤|cFF0080FF|Hspell:104900|h[蓝色]|h|r，|cFF424242|Hspell:104894|h[黑色]|h|r，以及|cFFFFA901|Hspell:104901|h[黄色]|h|r舒玛之血！"
D.Strings[47448]="%s召唤|cFF9932CD|Hspell:104896|h[紫色]|h|r，|cFFFF0404|Hspell:104897|h[红色]|h|r，以及|cFF424242|Hspell:104894|h[黑色]|h|r舒玛之血！"
D.Strings[47449]="你想让……我来？"
D.Strings[47450]="利尔压低了声音，窃窃私语着。"
D.Strings[47451]="<这具尸体被烧得面目全非，而且被咬成了两截。>$B$B<红龙军团或许是艾泽拉斯所有生命的守护者，但他们显然也不是好惹的。>"
D.Strings[47452]="就在你进入丛林之后，得救的士兵就开始陆续返回坡东村。跟着你找到这里并不困难。"
D.Strings[47453]="就是你救了海军上将泰勒？看来那些锦鱼人说的是真话……"
D.Strings[47454]="%s大声喷着鼻息，睡得更香了。"
D.Strings[47455]="再这么磨蹭，我们哪儿都不用去了！走啦！我们得到谷中去探险！"
D.Strings[47456]="别那么急，丽丽。我就是这么游历卡利姆多的：一次一站。"
D.Strings[47457]="难怪你花了这么长时间。你一直坐着的话，什么收获也不会有。"
D.Strings[47458]="陈叔，我知道你为什么喜欢这儿了。"
D.Strings[47459]="为什么呢，丽丽？"
D.Strings[47460]="因为那两个家伙让你感觉自己很苗条。"
D.Strings[47461]="我为什么想要苗条呢？体格等于力量。"
D.Strings[47462]="听到那边晓怎么说了么。他就意识到了大肚子的价值。"
D.Strings[47463]="遇见你是我们这几天来唯一走运的事。很高兴能得到你的帮助。"
D.Strings[47464]="很好。让我们继续。"
D.Strings[47465]="我父亲？干嘛要提起他？"
D.Strings[47466]="当猢狲掠夺我们的物资，杀害我们的战士时，他做了什么？什么都没有！"
D.Strings[47467]="他慵懒地坐在酋长宝座上，奢望用和平的美梦掩饰他的懦弱！"
D.Strings[47468]="猢狲根本不懂和平！他们会将我们村里的人都杀光的！"
D.Strings[47469]="我……我很抱歉刚才发了火，$n。我和我父亲在很多事情上都意见相左。"
D.Strings[47470]="你救了我的命，我欠你一份天大的人情。我一定会帮你见到长老的。"
D.Strings[47471]="该给那些毛毛们喂食了。"
D.Strings[47472]="找到一个！"
D.Strings[47473]="嘿嘿！"
D.Strings[47474]="接着！"
D.Strings[47475]="接住了！"
D.Strings[47476]="嚼呀嚼！"
D.Strings[47477]="快看！范妮小姐正好来了！"
D.Strings[47478]="我好像听到花园里有小孩子在捣乱。我们去找找看吧。"
D.Strings[47479]="|TInterface\\Icons\\spell_fire_moltenblood.blp:20|t%s开始|cFFFF0000|Hspell:105863|h[出血]|h|r！"
D.Strings[47480]="我怀疑我们永远也战胜不了猢狲了。"
D.Strings[47481]="看看四周，清澈的流水就是生命之源。$B$B我们对这上天的恩赐深表感激，也为我们的人民欢欣鼓舞。"
D.Strings[47482]="我们村已经很久没有欢迎过外来的访客了。"
D.Strings[47483]="在我年轻时，曾梦想能结束这场与猢狲的战争。可现在，我感觉自己恐怕无法活着看到那一天了。"
D.Strings[47484]="和比自己地位高的锦鱼人搭讪是粗鲁的行为。"
D.Strings[47485]="只有最为尊贵的客人，才能与长老说话。"
D.Strings[47486]="长老正在处理要务。请改天再来吧。"
D.Strings[47487]="我带来了仪式所需的物品。"
D.Strings[47488]="兄弟，我看到你的前路潜伏着巨大的黑暗。"
D.Strings[47489]="我目光所及，河流纷纷干涸。"
D.Strings[47490]="但仍然有一条出路，一条河流，能带你们走出这艰难的时代。"
D.Strings[47491]="强大的陌生人渡海而来。让他们加入我们，从而寻求他们的力量。"
D.Strings[47492]="否则，未来的日子将被强大的阴影所笼罩……"
D.Strings[47493]="我看见，未来充斥着巨大的黑暗。"
D.Strings[47494]="我们锦鱼人并不畏惧战斗。但我们也不仅是为胜利而战。"
D.Strings[47495]="我们是为自己的信念而战。"
D.Strings[47496]="你必须明白，小卢。什么才值得我们为之而战？"
D.Strings[47497]="什么才值得我们为之牺牲？"
D.Strings[47498]="我们是为了让孩子们过上比我们更好的生活而战！"
D.Strings[47499]="我们是为了不让先祖们白白牺牲而战！"
D.Strings[47500]="说一千道一万，你还是要做出决定，究竟什么才值得我们为之而战。"
D.Strings[47501]="来自远古的水灵。"
D.Strings[47502]="请在深渊中聆听我的呼唤。"
D.Strings[47503]="从彼岸无边大水中苏醒。"
D.Strings[47504]="在这危难的时刻帮助你的孩子们！"
D.Strings[47505]="巨大的黑暗？他是否在告诫我们必须相信这些陌生人…这些…来自…联盟的人？"
D.Strings[47506]="或许我是被自己的疑虑和恐惧蒙蔽了眼睛。"
D.Strings[47507]="我一定能成为更出色的部落领袖。"
D.Strings[47508]="感谢您的告诫。我会认真思考这个问题的。"
D.Strings[47509]="远古水灵！"
D.Strings[47510]="身子伏低，注意隐蔽。如果你遇到麻烦，我会立刻把你传送回来的！"
D.Strings[47511]="光板儿赢了。"
D.Strings[47512]="这些该死的光板儿。"
D.Strings[47513]="|TInterface\\Icons\\INV_Misc_Food_Vendor_PinkTurnip.blp:64:64:100:0|t$b$b<你想让范妮小姐怎么处理芜菁？>"
D.Strings[47514]="|TInterface\\Icons\\INV_MISC_FOOD_VENDOR_STRIPEDMELON.BLP:64:64:100:0|t$b$b<你想让范妮小姐怎么处理西瓜？>"
D.Strings[47515]="|TInterface\\Icons\\inv_guild_cauldron_b.blp:64:64:100:0|t$b$b<你想让范妮小姐怎么处理特辣豆腐？>"
D.Strings[47516]="哇哦，范妮小姐。也许太难了。"
D.Strings[47517]="范妮小姐，你可以的！再试一次吧，多用点力气！"
D.Strings[47518]="放轻松，范妮小姐。你敲的太重了……西瓜都被你敲烂了！"
D.Strings[47519]="啊哈哈哈哈！都还没下到半山腰呢！"
D.Strings[47520]="哇啊。打得好啊，范妮小姐！"
D.Strings[47521]="打得好，范妮小姐！你控制得很好！"
D.Strings[47522]="不错，范妮小姐！你打得很重！"
D.Strings[47523]="嘿，$g先生:小姐;，你在干嘛？你这是去送死！"
D.Strings[47524]="<范妮小姐看着你的眼睛，微妙地侧了侧头。她……她是想把你打出去吗？>$b$b<假如你没猜错，那范妮小姐又会用多大的力气呢？>"
D.Strings[47525]="欢迎你和你的朋友们来做客，想呆多久都可以。"
D.Strings[47526]="这些农田都是你的吗？"
D.Strings[47527]="嘿！滚开！"
D.Strings[47528]="离我的羊远点儿！"
D.Strings[47529]="回来，你个胆小鬼！"
D.Strings[47530]="把我的羊还给我！"
D.Strings[47531]="给我回来，小偷！"
D.Strings[47532]="绝望……"
D.Strings[47533]="别想夺走我们的水！"
D.Strings[47534]="你将成为献给我主的尊贵祭品。"
D.Strings[47535]="黑暗在等着你呢……"
D.Strings[47536]="这腐蚀一定会吞噬你，一如它吞噬我们……"
D.Strings[47537]="谁也别想碰这水！"
D.Strings[47538]="最终，只留下一片寂静。"
D.Strings[47539]="这里不欢迎生者！"
D.Strings[47540]="你的死期到了，芜菁！"
D.Strings[47541]="攻击芜菁！"
D.Strings[47542]="消灭所有的芜菁！"
D.Strings[47543]="首先我们要消灭芜菁！接着消灭种植这些芜菁的熊猫人！"
D.Strings[47544]="我们要把所有的芜菁都消灭掉，一个都不剩！"
D.Strings[47545]="芜菁！你怎么这么坏？"
D.Strings[47546]="芜菁必须受到惩罚！"
D.Strings[47547]="熊猫人将为种植这些恶心的芜菁而付出代价！"
D.Strings[47548]="安息吧。"
D.Strings[47549]="净化吧，灵魂。"
D.Strings[47550]="安息吧，灵魂。"
D.Strings[47551]="我终于……自由了……"
D.Strings[47552]="我的船就要赢了！"
D.Strings[47553]="光明……回来了……"
D.Strings[47554]="我想我的船被卡住了。"
D.Strings[47555]="西瓜船很容易浮起来。"
D.Strings[47556]="好好利用这水。它们是无价之宝。"
D.Strings[47557]="谢谢你，陌生人……"
D.Strings[47558]="看看你的船走得多慢啊。"
D.Strings[47559]="阴影消失了……腐蚀得到了净化。"
D.Strings[47560]="很快就可以再偷些西瓜了。"
D.Strings[47561]="我们守护着这水，让它远离贪婪与黑暗。"
D.Strings[47562]="我们很快就会用到更多的船只了。"
D.Strings[47563]="把叶子摘掉，船会行驶得更快。"
D.Strings[47564]="快快快！"
D.Strings[47565]="你们竟敢扰乱这水流？淹死你们！"
D.Strings[47566]="滚开，土拨鼠！"
D.Strings[47567]="离我们的庄稼远点！"
D.Strings[47568]="嘘，嘘！"
D.Strings[47569]="打败巨型白色平原鹰！"
D.Strings[47570]="$n，我们又见面了！你是来找尚的吗？我想他在后面，正在擦他的瓜。"
D.Strings[47571]="终于逃出黑暗的魔爪了！光！神圣而又美丽的光啊！"
D.Strings[47572]="千次轮回之前，我将水带到了这里。那是一份送给珠鳍锦鱼人的礼物，源自一个古老的约定。"
D.Strings[47573]="我们一直守护着这水。它是如此强大，一旦落入邪恶的手，后果将不堪设想。"
D.Strings[47574]="然后，黑暗降临了。它从地下渗出，逐渐侵蚀了我们……吞噬了我们！"
D.Strings[47575]="即使我们的肉身腐朽成灰，它依然能从我们的灵魂中汲取希望之力。这折磨无穷无尽！"
D.Strings[47576]="这念头令我不寒而栗。一群远古的邪魔。一群潘达利亚的宿敌。我无法说出他们的名字。"
D.Strings[47577]="你怎么了，大师？"
D.Strings[47578]="那腐蚀你的黑暗到底是什么？"
D.Strings[47579]="也许这个灵魂知道那首诗歌。净化吧，灵魂！"
D.Strings[47580]="看来我们的命运再次交叉了，$n，而且还是在这个大养猪场里。$b$b我喜欢这个山谷。它感觉就像……家一样。绿色的田野，广阔的天空……我甚至还听说路的那头有个大的酿酒厂。我也许是时候安定下来，不再漂泊了。$b$b<陈向远方凝视了几秒钟，然后耸耸肩。>$b$b或者不会。"
D.Strings[47581]="是时候大干一场了。所有人进入船舱：我们要去杀的是一条龙。"
D.Strings[47582]="我……我欠你一份情。"
D.Strings[47583]="哇……别过来，疯子……蜘蛛！"
D.Strings[47584]="啊！它朝我冲过来了！"
D.Strings[47585]="为什么总是蜘蛛呢？！"
D.Strings[47586]="啊，把这些东西弄走！"
D.Strings[47587]="不要！我不想被咬死！"
D.Strings[47588]="呃……靠近点儿，小崽子。我要把你的腿咬下来！"
D.Strings[47589]="%s张牙舞爪的，试图吓唬$n。"
D.Strings[47590]="%s极力转过脸去，不看$n。"
D.Strings[47591]="我没见过这样的地方。你呢，$n？"
D.Strings[47592]="熊猫人掌握着许多古老的知识。林娜教会了我怎么使用当地的草药治病。"
D.Strings[47593]="你觉得这些熊猫人是从哪儿冒出来了？他们怎么会与世隔绝了那么久呢？"
D.Strings[47594]="总有一天，任会带我去看他家所在的村子的。"
D.Strings[47595]="我父亲怎么样了？但愿他不要太担心了。他已经为我操碎了心。"
D.Strings[47596]="我父亲可不这么想，但我会照顾好自己的。"
D.Strings[47597]="我还不太想回家。还有那么多东西等着我去见识、学习呢。"
D.Strings[47598]="该回家了，安度因王子。"
D.Strings[47599]="<任辗转反侧，额头发烫。>$B$B水……水……"
D.Strings[47600]="安度因的朋友就是我们的朋友，$c。要不是他，我父亲也不可能站在这里。"
D.Strings[47601]="我很抱歉，可我暂时还不能回去。"
D.Strings[47602]="我决心去寻找那座溪谷。我一定要找到圣池，并研究一下它们的治疗力量。"
D.Strings[47603]="安度因王子，我们是来带你回家的。"
D.Strings[47604]="悄悄跟着我，快。"
D.Strings[47605]="我很抱歉，可我不能。我相信你明白我的苦衷。"
D.Strings[47606]="啊？噢……嗯……安度因王子，您说的完全正确。您可以去了。"
D.Strings[47607]="来吧，我们走。"
D.Strings[47608]="苏利！你怎么就这样让他跑了？"
D.Strings[47609]="嗯？出什么事了？"
D.Strings[47610]="愚蠢的矮子，他用了精神控制！现在他跑了！"
D.Strings[47611]="你还是想想怎么跟泰勒上将解释吧！"
D.Strings[47612]="什么？？难以置信，他怎么能这样！"
D.Strings[47613]="找到你的灵魂，打破诅咒！"
D.Strings[47614]="谁会想到这些怪物还能跟你讲道理呢？"
D.Strings[47615]="纳兹戈林已经指定由你去侦察这片区域，夏琪亚。你立刻就动身吧。"
D.Strings[47616]="我会做好准备的。$b$b能暂时摆脱这些野蛮人就再好不过了。"
D.Strings[47617]="这还需要适应。$b$b我得努力忍住把这些家伙的脑袋揪下来的冲动。"
D.Strings[47618]="纳兹戈林已经指定由你去侦察这片区域，格罗克。你立刻就动身吧。"
D.Strings[47619]="真丢人。我得休息一会儿了。$b$b没关系，你去告诉纳兹戈林，我会跟上队伍的。"
D.Strings[47620]="你看，当你了解之后，就会发现这些小家伙也不是那么坏的……"
D.Strings[47621]="纳兹戈林已经指定由你去侦察这片区域，琪麟。你立刻就动身吧。"
D.Strings[47622]="当然了。他要不选我那才是笨呢。$b$b谢谢你，$r。我立刻就准备出发。"
D.Strings[47623]="衷心感谢，陌生人。"
D.Strings[47624]="噢，谢啦，朋友！"
D.Strings[47625]="我可不想留下疤痕……"
D.Strings[47626]="噢，这下好多了……我的发型没乱吧？"
D.Strings[47627]="我要把这个故事告诉我的孩子们！当然了，我会把他们的爸爸受窘的部分修改一下的……"
D.Strings[47628]="就这样：这事完了之后，我要申请危险津贴。"
D.Strings[47629]="真没想到，居然是个$c把我从蜘蛛嘴里救了下来。谢谢你！"
D.Strings[47630]="我最喜欢你这种$c了：勇敢，乐于助人！"
D.Strings[47631]="空气里有联盟恶棍的臭味儿。"
D.Strings[47632]="噢，我只是在休息……我有时候就是在……石头底下休息的……"
D.Strings[47633]="我差一点就能钻出来了……反正我是这么觉得的。"
D.Strings[47634]="我会去找豪的。谢谢你！"
D.Strings[47635]="工头现在肯定气得七窍生烟了，幸好不用我去跟她打交道。"
D.Strings[47636]="蠢蛋选择和猢狲做朋友真是明智。$b$b现在，猢狲要砸扁的蠢蛋又少了一个。"
D.Strings[47637]="伟大的酋长卡哈卡哈，我们将探索您的领地，并且需要一名好的向导。您能帮我吗？"
D.Strings[47638]="今天是塌方和利齿蛛，明天就有可能是洪水和锦鱼人入侵。在矿场嘛，混一天是一天了。"
D.Strings[47639]="我再也不来这个鬼地方了！"
D.Strings[47640]="我最好加班加点干完它。"
D.Strings[47641]="唔。$b$b<你耐心地等待酋长卡哈卡哈思考完，又等了一会儿，才听到他开口。>$b$b卡哈卡哈有许多子侄。他们都没给卡哈卡哈丢脸。$b$b古鲁金家族里只有一个家伙败坏了卡哈卡哈的名声……$b$b即便是对于猢狲来说，里克也显得太不安分了。也许到外面多走走能把他拉回正道上来。"
D.Strings[47642]="我救下你了！好险啊。"
D.Strings[47643]="你得小心点——他们非常警惕！"
D.Strings[47644]="好吧……这真是太糟了。幸好有我在。"
D.Strings[47645]="你不是想掏他们的口袋吧？"
D.Strings[47646]="救下你了！让我们再试一次……"
D.Strings[47647]="谢谢你帮我找回了车夫，朋友。"
D.Strings[47648]="小偷。小偷！"
D.Strings[47649]="在这儿——抓住$g他:她;！"
D.Strings[47650]="我看见你了，蠢货！"
D.Strings[47651]="你休想……逃跑！"
D.Strings[47652]="你的师父教出了个好徒弟。"
D.Strings[47653]="打得漂亮。尚师父会很高兴的。"
D.Strings[47654]="太棒了！你比看上去还要强壮得多。"
D.Strings[47655]="看来我还需要更多的练习。感谢你的教诲。"
D.Strings[47656]="我打不过你。你赢得光明正大。"
D.Strings[47657]="被你击败是一种荣誉。"
D.Strings[47658]="啊呀呀呀！！！"
D.Strings[47659]="哈，出来了。我就说了我能行！"
D.Strings[47660]="我相信你能处理这里的事。我出去解决外面的问题。"
D.Strings[47661]="有人需要医疗救助吗？"
D.Strings[47662]="锦鱼人看上去可能不太友好，但我相信我们已经表达出了善意。"
D.Strings[47663]="医生总得忙个不停。"
D.Strings[47664]="我在这里呆得越久，就越喜欢这片神奇的大陆。"
D.Strings[47665]="你说，我们会不会永远也回不了家了？"
D.Strings[47666]="我已经很多年没有搞砸过任务了。这次，我也不想搞砸。"
D.Strings[47667]="上将伤得很重，$n。"
D.Strings[47668]="上将真是非常、非常走运，你竟然能及时赶到。"
D.Strings[47669]="从伤口上看，上将遭受过严酷的折磨。"
D.Strings[47670]="上将伤得很重，但并不是完全没救。我可以治好他，但我需要时间。"
D.Strings[47671]="我只能将攻击上将的那些家伙称为……野蛮人。"
D.Strings[47672]="嘘，$n。我必须专心处理这些伤口。"
D.Strings[47673]="谢谢你，$n。要不是你，上将肯定要葬身在那个肮脏的地方了。"
D.Strings[47674]="$n，你已经是一个非常熟练的医护兵了。你应该继续接受急救训练。"
D.Strings[47675]="我对指挥官的伤势恐怕已经无能为力了。"
D.Strings[47676]="现在，只有奇迹才能拯救指挥官了。"
D.Strings[47677]="我已经尽力抢救了。但指挥官恐怕已经坚持不了多久了。"
D.Strings[47678]="我感觉很好，$n。多谢你的关心，可眼下我们还有更重要的事情。"
D.Strings[47679]="我已经往迷航港送了消息。他们应该很快就会派出更多士兵的。"
D.Strings[47680]="我们必须先集中力量建立一个基地。等我们在这里站稳脚跟后，就能抽出人手来寻找回家的方法了。"
D.Strings[47681]="这片土地的资源很丰富，$n。我正在准备一份报告，回去以后应该能用上。"
D.Strings[47682]="这里的原住民都很友善。呃，那些猴子除外。"
D.Strings[47683]="锦鱼人似乎是个古老的种族。我们迟早会了解他们的秘密的。"
D.Strings[47684]="我试图与他们的酋长对话，可他根本不想见我。看来，我的“地位”还不够高。显然，他从来没见识过“海军上将”这种人。"
D.Strings[47685]="我是没法和珠鳍长老交上朋友了，$C。我就全指望你能成功了。"
D.Strings[47686]="<泰勒病得很重。现在最好别去打扰他。>"
D.Strings[47687]="采摘"
D.Strings[47688]="学习的第一步就是承认自己的无知。"
D.Strings[47689]="智慧源自于对自身愚昧的认识。"
D.Strings[47690]="快，快，快！他们随时可能出现！"
D.Strings[47691]="哇！闻上去很像达拉然奶酪！"
D.Strings[47692]="我绝不能让这个联盟恶棍把我的战利品偷回去。"
D.Strings[47693]="所以，如果我用压缩……燃料来替代火药，那我们就发达了。只是打个比方。"
D.Strings[47694]="还有烈酒吗？"
D.Strings[47695]="这是一件杰作，我给我的发明起个名字……古鲁金手雷怎么样？"
D.Strings[47696]="好的，利维特。我准备好了！"
D.Strings[47697]="你可以继续前进了。燧焰就在前面。"
D.Strings[47698]="出现了一个胡萝卜！"
D.Strings[47699]="哦，一个胡萝卜！"
D.Strings[47700]="你的训练很有成效，年轻的$c。你成功找到了燧焰并将他带回了五晨寺。"
D.Strings[47701]="嗯……胡萝卜！"
D.Strings[47702]="看呐，燧焰不仅将温暖带回了寺中，更让他的人民恢复了激情。"
D.Strings[47703]="我为你今天的成就而骄傲。"
D.Strings[47704]="真大啊！"
D.Strings[47705]="接下来，你要去找上古水灵涓流。你准备好之后，就去东边的咏之池找艾莎吧。"
D.Strings[47706]="看起来很多汁！"
D.Strings[47707]="看起来不错。"
D.Strings[47708]="我喜欢。我喜欢这个胡萝卜。"
D.Strings[47709]="我想我们该吃了它。"
D.Strings[47710]="咱们全都开吃吧！"
D.Strings[47711]="不！这是个芜菁！"
D.Strings[47712]="不！不要芜菁！！"
D.Strings[47713]="谁会做这种事啊？！"
D.Strings[47714]="啊，芜菁！我们快离开这儿！"
D.Strings[47715]="这个胡萝卜其实是芜菁！快跑！"
D.Strings[47716]="啊，你们到了。现在是大分裂的前夕，永恒之井即将毁灭，撕裂整个大陆。"
D.Strings[47717]="这里有人！"
D.Strings[47718]="啊哈！逮到你了！"
D.Strings[47719]="这里有小偷！"
D.Strings[47720]="我抓住一个！"
D.Strings[47721]="别忘了使用潜行！"
D.Strings[47722]="你疯了吗？如果你到处乱飞，会被他们发现的！"
D.Strings[47723]="你不能在这里飞行。我们一定会被发现的！"
D.Strings[47724]="你们比尘埃更渺小，赶走你们就像掸走灰尘一般容易。"
D.Strings[47725]="出什么事了？联盟藏的烈酒泄漏了吗？哈哈哈！"
D.Strings[47726]="就是这样……你做的很好……坚持住……"
D.Strings[47727]="小心！前门的守卫太森严了。唔……绕到庄园后头去看看，我们或许能找到其他道路。"
D.Strings[47728]="你要去哪儿？庄园在另一边！"
D.Strings[47729]="唔……这儿似乎什么都没有。试试绕到庄园背后去。"
D.Strings[47730]="啊哈！这里没有守卫！看看你能不能找到一条上屋顶的路？"
D.Strings[47731]="干得漂亮！那上面有没有打开的窗户？仔细找找！"
D.Strings[47732]="你成功了！你进去了！现在……他们会把蛋藏在哪儿呢？我猜是个漆黑的地方。仔细点！"
D.Strings[47733]="我可不怕你！等等……你……你是谁？"
D.Strings[47734]="但……但死亡之翼的爪牙可能会杀了你……"
D.Strings[47735]="高贵的$r，我相信我们是可以就释放我的问题达成某些共识的。"
D.Strings[47736]="我们正站在一片与泰坦一样古老的隐秘乐土上，而你却满脑子都是打打杀杀的事？"
D.Strings[47737]="将这些种族卷入我们的战争？用战火玷污这片土地？$b$b你真的想这么做吗？"
D.Strings[47738]="所以，你训练出了一支军队……$b$b一个了不起的成就，可战争真的是正确的应对方式吗？"
D.Strings[47739]="利用这些种族之间的仇恨是不明智的，$r。$b$b你必须为后果负责。"
D.Strings[47740]="你把水灵和土灵带回来了。我为你感到骄傲。"
D.Strings[47741]="五晨寺欢迎无垢和涓流的归来。我们会好好照顾他们的。"
D.Strings[47742]="现在只剩下上古风灵大风了，他就躲在西边的晨之桥那头的某个地方。"
D.Strings[47743]="我会把你送到寺院顶层。季在那里等着你，他会为你带路的。"
D.Strings[47744]="呃……我好像把事情搞砸了。"
D.Strings[47745]="该死！真见鬼！"
D.Strings[47746]="噢……这些混蛋光板儿……"
D.Strings[47747]="猢狲最擅长干这个了！"
D.Strings[47748]="在你行进过程中，泥盏的瓶子会不断地渗水。请谨慎选择路线！"
D.Strings[47749]="在这里，我们要趁巨龙之魂失落于时间的迷雾之前将它夺回。"
D.Strings[47750]="但首先，你们必须先破坏艾萨拉的上层精灵布下的防护结界。他们就在宫殿里。我会先行一步。"
D.Strings[47751]="祝你们好运，英雄们！"
D.Strings[47752]="是你们！这么多年了，是你们又让煞再次苏醒！"
D.Strings[47753]="你们这些人给我们的家园带来如此灾难，如果你们真想补救，就在这儿，证明自己。"
D.Strings[47754]="首先，你们要面对我的徒弟们…"
D.Strings[47755]="就算一个倒下，另一个会奋起替代他。"
D.Strings[47756]="如果你们想战胜煞，保护你们的族人，就要多加学习。做好准备，战斗到底！"
D.Strings[47757]="你们只是击败了我最年轻的学徒而已。接下来是我的两位得意门生。"
D.Strings[47758]="飞雪！香莲！速速上前！"
D.Strings[47759]="你们击败了我最强的学生。也许你们还不算一无是处…"
D.Strings[47760]="也许这就是我师父曾说过的“不打不相识吧。”"
D.Strings[47761]="就连他们那燃烧的营地上空的浓烟，都带着无能和羞耻的味道。"
D.Strings[47762]="你好，$n。你也像我一样口渴吗？"
D.Strings[47763]="我准备好了。出发吧。"
D.Strings[47764]="我即是末日的开端……蔽日的阴影……毁灭的丧钟……"
D.Strings[47765]="一股破坏平衡的力量正在接近。它的混乱灼烧着我的心智！"
D.Strings[47766]="这些龙崽子，这些实验，只为一个崇高的目标。你很快就会看到我最伟大的研究成果。"
D.Strings[47767]="我存在的意义就是为了这个时刻。见证你们的死亡和绝望吧，凡人！"
D.Strings[47768]="大地之力，听我召唤！请在这个黑暗的时刻庇护艾泽拉斯最后的守护者！"
D.Strings[47769]="振作起来，英雄们，生命总能在最黑暗的土地上绽放！"
D.Strings[47770]="在梦中，我们能够克服任何障碍！"
D.Strings[47771]="奥术之风将支援他们，让他们在这个黑暗的时刻重焕活力！"
D.Strings[47772]="时光的轮回将带来万物的终结。"
D.Strings[47773]="暮光审判降临了！"
D.Strings[47774]="可……可……我是……奥卓……"
D.Strings[47775]="在我面前倒下吧！"
D.Strings[47776]="你们毫无希望！"
D.Strings[47777]="最后一缕光也消失了，你们这些可悲的凡人也将随之消逝！"
D.Strings[47778]="死亡之翼阁下，我承受不了……您的馈赠……我……啊啊啊啊！！"
D.Strings[47779]="我的仇恨在烈焰与痛苦中燃烧！"
D.Strings[47780]="我要拖着你们一起陷入烈焰与黑暗！"
D.Strings[47781]="|TInterface\\Icons\\inv_misc_head_dragon_01.blp:20|t阿莱克丝塔萨召唤出了|cFFFF0000|Hspell:105896|h[生命赐福]|h|r！"
D.Strings[47782]="|TInterface\\Icons\\inv_misc_head_dragon_green.blp:20|t伊瑟拉召唤出了|cFF00CC00|Hspell:105900|h[梦境精华]|h|r！"
D.Strings[47783]="|TInterface\\Icons\\inv_misc_head_dragon_blue.blp:20|t卡雷苟斯召唤出了|cFF0000FF|Hspell:105903|h[魔力之源]|h|r！"
D.Strings[47784]="|TInterface\\Icons\\inv_misc_head_dragon_bronze.blp:20|t诺兹多姆为你加持了|cFFFFFF00|Hspell:105984|h[时光之环]|h|r！"
D.Strings[47785]="|TInterface\\Icons\\inv_misc_head_dragon_black.blp:20|t萨尔为坦克们加持了大地之力！你成为了|cFF9900CC|Hspell:106218|h[艾泽拉斯最后的守护者]|h|r！"
D.Strings[47786]="|TInterface\\Icons\\spell_fire_twilightimmolation.blp:20|t奥卓克希昂发生|cFF9900CC|Hspell:106373|h[新生变异]|h|r了！"
D.Strings[47787]="|TInterface\\Icons\\spell_fire_twilightcano.blp:20|t奥卓克希昂的不稳定导致了大规模的|cFF9900CC|Hspell:106388|h[暮光崩裂]|h|r!"
D.Strings[47788]="|TInterface\\Icons\\spell_fire_twilightimmolation.blp:20|t奥卓克希昂发生|cFF9900CC|Hspell:106395|h[致命变异]|h|r了！"
D.Strings[47789]="我的职责就是保护我的人民。如果必须要我上前线，那么我将义无反顾。"
D.Strings[47790]="我很强壮！我能承受凶猛的攻击而面不改色！"
D.Strings[47791]="当敌人把注意力都放在我身上时，我的战友们就可以从后面包抄他们了！"
D.Strings[47792]="我步履沉着、运剑如风。敌人必须先打倒我，才能去阻挠我的战友们。"
D.Strings[47793]="从小时候起，我就对医术很着迷。"
D.Strings[47794]="照顾伤员的人手太少了。如果能掌握相关的技术，我很乐意加入他们。"
D.Strings[47795]="我给伤病员带来了绷带和食物。我要是能再多帮点忙就好了……"
D.Strings[47796]="在你们那儿，治疗者真的要跟着战士上战场吗？如果我有趁手的家伙，我或许也做得到。"
D.Strings[47797]="好了，小伙子们！快来拿吧，刚烤好的滑水鱼！"
D.Strings[47798]="我更喜欢塑造流水之形，并使用它们来对付我的敌人。"
D.Strings[47799]="我有一些魔法天分，可我希望能接受更加系统的训练。"
D.Strings[47800]="我已经接受过基础战士训练了，可大家都不知道，其实我的施法技巧更加出色。"
D.Strings[47801]="我对长矛一窍不通。我更喜欢远程战斗。"
D.Strings[47802]="我的行动迅捷如风。只要把我置于敌人身后，他们甚至不会感觉到我的接近。"
D.Strings[47803]="小个子也有小个子的优势。我能潜入任何地方而不被发现。"
D.Strings[47804]="这里的所有人都会接受标准的战士训练，可我觉得我更合适隐秘任务。"
D.Strings[47805]="我从不正面对敌。我更喜欢运用头脑……以及各种鬼祟伎俩来战胜敌人。"
D.Strings[47806]="等等，我认识你，人类。你是瓦里安·乌瑞恩的儿子！"
D.Strings[47807]="哈！你要再多嘴，我的小王子，我就把你的小脑袋砍下来！"
D.Strings[47808]="先生，我要求你立即释放我，并将我送到我父亲那里！"
D.Strings[47809]="好了！我们在这儿待得够久了。"
D.Strings[47810]="雷脚一家真好，但他家的啤酒少得连一个酒桶都装不满。"
D.Strings[47811]="我们去找些啤酒行吗，丽丽？"
D.Strings[47812]="如果啤酒能让你挪动屁股，那……我们就去找吧。"
D.Strings[47813]="再见了，尚！"
D.Strings[47814]="在泥盏那儿玩得开心点！再次感谢！"
D.Strings[47815]="叔叔，看。前面有个人。他看起来……很奇怪。"
D.Strings[47816]="在这里我们可是外人，丽丽，对他来说，我们看起来可能更奇怪。"
D.Strings[47817]="嘁……还不是因为我们跟外乡人走在一起！"
D.Strings[47818]="抱歉，$n，但你的确与众不同。"
D.Strings[47819]="这是什么？一个联盟男孩儿？在这种地方？"
D.Strings[47820]="什么？我们都是熊猫人！难道迷踪岛的熊猫人看上去会很怪？"
D.Strings[47821]="好吧，是$n看起来有一点奇怪。抱歉，$n。"
D.Strings[47822]="你好啊，陌生人！"
D.Strings[47823]="我们正在找一个名叫泥盏的酿酒师。你认识他吗？"
D.Strings[47824]="我就是泥盏。你们是？"
D.Strings[47825]="我是陈，这是我的侄女丽丽。"
D.Strings[47826]="嗯，你们能对付兔妖吗？"
D.Strings[47827]="那可是我们的拿手好戏！在迷踪岛上，我打扁过上百万只兔妖！"
D.Strings[47828]="你遇到兔妖了？我们很乐意帮助你，泥盏。"
D.Strings[47829]="那好吧！我就住在附近。"
D.Strings[47830]="来吧！一起去消灭那些畜生！"
D.Strings[47831]="我就说他很奇怪吧。"
D.Strings[47832]="这姑娘说对了。跟我走。"
D.Strings[47833]="我们就快追上那条龙了！我想我们可以把它从云层里揪出来！"
D.Strings[47834]="让我们再靠近点！"
D.Strings[47835]="守护巨龙周围的护盾碎裂了！守护巨龙要受到伤害了！"
D.Strings[47836]="外来人，你来我们村干什么？"
D.Strings[47837]="你肯定就是大家都在议论的那个外来人。"
D.Strings[47838]="猢狲曾经也来向我们求助过，就像你现在这样。$B$B我们同情他们，并教会他们如何在这片土地上生存。$B$B可随着时间推移，他们越来越强大，也越来越傲慢，开始想要独占这片土地。"
D.Strings[47839]="经历了这次教训之后，我们就不再相信陌生人了，$c。"
D.Strings[47840]="$n是吗？我在村里听说过你的名字。"
D.Strings[47841]="你就是那个$c，对吧？谢谢你把我哥哥的传家宝带了回来，那是我最宝贵的财富。"
D.Strings[47842]="或许我误解了你，$r。你已经帮了我们村很多忙了。"
D.Strings[47843]="你们的人很有趣，$r。我希望能更深入地了解你和你的同胞们。"
D.Strings[47844]="或许有一天，我也会去拜访你的村子的，$n。"
D.Strings[47845]="你为我们的村子做了许多好事，$n。或许我们是可以成为朋友的。"
D.Strings[47846]="奥卓克希昂的攻击摧毁了守护巨龙们四周的护盾！"
D.Strings[47847]="我们在这座湖泊上居住了几千年了。这里的湖水源自于潘达利亚的古老水池。"
D.Strings[47848]="我们整个部落都十分感激你善行，$n。"
D.Strings[47849]="无条件相信陌生人的话是愚蠢的，但拒绝潜在的朋友也是愚蠢的。"
D.Strings[47850]="一股诡异的力量将你拉入了暮光领域！"
D.Strings[47851]="你或许需要这面盾牌。"
D.Strings[47852]="请带上这本治疗祷言吧。"
D.Strings[47853]="丽丽。今天的陌生人就是明天的朋友。这就是云游者之道！"
D.Strings[47854]="这根法杖是给你的。"
D.Strings[47855]="这些匕首能派得上用处吗？"
D.Strings[47856]="不用则废啊，$g先生:姐妹;！"
D.Strings[47857]="但愿风不会往这边吹……"
D.Strings[47858]="噢，我为部落做了那么多事……"
D.Strings[47859]="这盾牌正是我想要的！谢谢你！"
D.Strings[47860]="这面盾牌可以挡住许多强大的攻击。谢谢你，$n。"
D.Strings[47861]="这正是我想要的。"
D.Strings[47862]="我得立刻开始训练了。"
D.Strings[47863]="这东西更适合治疗者，不适合我。"
D.Strings[47864]="我需要一些防具，这东西对我没用。"
D.Strings[47865]="我想要更结实一点的装备。"
D.Strings[47866]="这东西怎么用？哎哟！"
D.Strings[47867]="全速前进。一切都取决于我们的速度了！不能让灭世者跑了。"
D.Strings[47868]="全员备战，让那些怪物离我的船远一点！"
D.Strings[47869]="这……这是懦夫用的武器！我想要一些大家伙！"
D.Strings[47870]="集中火力攻击装甲巨龙！"
D.Strings[47871]="一个暮光工兵闯入了引擎室！"
D.Strings[47872]="天火号就快撑不住了！"
D.Strings[47873]="我们在下坠。弃船！"
D.Strings[47874]="这么多知识啊！我得立刻开始学习了。"
D.Strings[47875]="我是不会白白浪费掉这本神圣经卷的。谢谢你！"
D.Strings[47876]="这件武器是怎么治疗伤员的？"
D.Strings[47877]="我没法用这东西。我希望能继续研习医术。"
D.Strings[47878]="引擎恢复工作了！全速前进！我们不能让死亡之翼逃了！"
D.Strings[47879]="哈！如我所愿，你们坚持到了这里。准备好迎接真正的战斗了吗？"
D.Strings[47880]="你们休想靠近主人。龙骑士们，攻击！"
D.Strings[47881]="干得好……哼。可我很怀疑你们有没有本事……击败他。"
D.Strings[47882]="我觉得这盾牌不合适我。"
D.Strings[47883]="挑战公牛的下场……"
D.Strings[47884]="躺下吧！"
D.Strings[47885]="我知道，在你眼里我们都是一个样儿，可我是个治疗者，不是法师。"
D.Strings[47886]="站起来！哦……懦夫！"
D.Strings[47887]="哎哟！这把武器好锋利啊。"
D.Strings[47888]="如果我们能离开这的话，就别再提这事了吧……"
D.Strings[47889]="噢……那是一只眼睛。没错，肯定是一只眼睛。"
D.Strings[47890]="格里昂纳！让他们下地狱！"
D.Strings[47891]="这招怎么样？"
D.Strings[47892]="看来我得亲自动手了。很好！"
D.Strings[47893]="我们飞得太近了。这场大战很精彩，可现在我必须结束它了。"
D.Strings[47894]="将犹疑逐出你的灵魂！"
D.Strings[47895]="万岁！终于可以升级了！"
D.Strings[47896]="是的！这把武器很完美。"
D.Strings[47897]="这东西对我没用。"
D.Strings[47898]="我没法用这东西，$r。"
D.Strings[47899]="我很抱歉，可我不会治疗。"
D.Strings[47900]="我更擅长攻击，而不是防御。"
D.Strings[47901]="这些匕首对我没用。"
D.Strings[47902]="这些匕首很合适捅人。"
D.Strings[47903]="是的！那些猢狲肯定到死都搞不清是什么攻击了他们。"
D.Strings[47904]="我要怎么用这玩意儿去捅敌人呢？"
D.Strings[47905]="不不，它还不够锋利。"
D.Strings[47906]="这又不是武器！这只是一本书！"
D.Strings[47907]="我带着这么大一面盾牌，还怎么潜行啊？"
D.Strings[47908]="太大了，也不够锋利。我需要一些小而锋利的武器。"
D.Strings[47909]="泥盏！这酒太棒了！带劲儿！"
D.Strings[47910]="谢谢！大伙儿都觉得这酒比“风暴烈酒酿造厂”酿得好。"
D.Strings[47911]="等等……你是说风暴烈酒酿造厂？"
D.Strings[47912]="你认识风暴烈酒家的人吗？在潘达利亚？"
D.Strings[47913]="嘁，当然了！他们可是整个四风谷最大的酿酒家族！"
D.Strings[47914]="酿酒厂……我的家人……我祖先的家园！"
D.Strings[47915]="等等——你是风暴烈酒家族的？"
D.Strings[47916]="对，对。告诉我——这个“风暴烈酒酿造厂”在哪里？我得亲自去看看！"
D.Strings[47917]="沿着这条路往下走就是了，但是……"
D.Strings[47918]="我走了。丽丽……你留在这儿。我会回来找你的。"
D.Strings[47919]="答应我，我不在时，你可不要惹麻烦啊。"
D.Strings[47920]="我……好的，当然了。去吧。"
D.Strings[47921]="他居然把我丢给这个怪泥盏了。"
D.Strings[47922]="快去晨芳园。我们会在那里等你的！"
D.Strings[47923]="你是怎么爬到那么高的地方的？"
D.Strings[47924]="我给我们找了个很酷的保镖，是不是？"
D.Strings[47925]="靠近点。深入他的空间。别让他掌握主动！"
D.Strings[47926]="你要尽量使自己的进攻多样化，别让对手摸清你的套路，证明他的直觉是错的。"
D.Strings[47927]="别只知道用武器的锋刃部分。用用武器的柄，砸扁他的鼻子！"
D.Strings[47928]="让我看看你发皱眉的样子吧。皱眉。用力皱眉！你管这叫皱眉？"
D.Strings[47929]="你的目标是消无声息地干掉对方。不到万不得已，别搞出太大的动静。"
D.Strings[47930]="小腿，面部，胯部，随便踢。"
D.Strings[47931]="你在干什么呢，跳舞？我们在研究谋杀，伙计！呸——再带两个进来。"
D.Strings[47932]="你的行动轻率、随意、松散……你在瞬间就会被干掉。滚出去！"
D.Strings[47933]="我喜欢在这里看到的一切。大家都看见了吗？下一个是谁？"
D.Strings[47934]="很好。你牙上的是血吗？太好了！再送两个进来！"
D.Strings[47935]="呃，你战斗起来就像热锅上的豺狼人。心不在焉，鲁莽草率，乱七八糟。滚出去。出去！下一个！"
D.Strings[47936]="噢，哇！那真是太棒了！你真了不起！"
D.Strings[47937]="你为什么能那么勇敢呢？"
D.Strings[47938]="我真心希望，它在被你打跑之前，没吃过我的任何一个朋友。"
D.Strings[47939]="喝一杯休息一下吧，旅行者。"
D.Strings[47940]="一切都还顺利吗，$n？"
D.Strings[47941]="来吧，孩子。在你完成训练之前，我们还要同行最后一段旅程。"
D.Strings[47942]="长者之路的尽头就是禅杖林，只有最杰出的熊猫人才能进入这片圣地。"
D.Strings[47943]="要证明自己，方法有很多，而我的要求是最简单的。我必须知道，你是否愿意为族人而战；你是否有能力来保护他们。"
D.Strings[47944]="击败长者的卫士，我们才能通过。"
D.Strings[47945]="那是我先看见的！"
D.Strings[47946]="外面的对手足够我们杀的了……"
D.Strings[47947]="三千年来，这些智慧在我们中间代代相传，长幼相继，师徒相承。"
D.Strings[47948]="每位长者都会有离世的一天。在那之前，他必须将自己的禅杖和祖先们的种在一起。今天，我的禅杖也将种入此林。"
D.Strings[47949]="现在，神真子病了，我们都处在危险之中。有了元素之灵的帮助，你将打破这种沉默，聆听它的诉说。"
D.Strings[47950]="艾莎和季已经把元素之灵接来了。你要跟他们一起去觐见伟大的神真子，并尽你所能拯救我们的人民。"
D.Strings[47951]="你功不可没，年轻的徒儿。看得出来，你有一颗英雄的心。这片土地的未来就托付给你了。"
D.Strings[47952]="什么？！那不可能！"
D.Strings[47953]="|TInterface\\Icons\\ability_deathwing_cataclysm.blp:20|t%s开始施放|cFFFF0000|Hspell:106523|h[大灾变]|h|r！快阻止他！"
D.Strings[47954]="渺小的灵魂，你带着那个躯壳是逃不出我的掌心的！"
D.Strings[47955]="你休想再来捣乱！"
D.Strings[47956]="我的腿都僵了。"
D.Strings[47957]="哇！我们成功了！"
D.Strings[47958]="过来，小猫咪。"
D.Strings[47959]="你应该被变成玉雕，永远加入我们的大家庭。"
D.Strings[47960]="耶！阿信！你还活着！"
D.Strings[47961]="我就知道……"
D.Strings[47962]="是的！我做好战斗的准备了。"
D.Strings[47963]="走，我们去喝一杯。"
D.Strings[47964]="等你准备好了我们就出发，$n。"
D.Strings[47965]="我正遭受痛苦的折磨，但刘浪的子孙们没有忘记我，值得欣慰。"
D.Strings[47966]="跳进去。"
D.Strings[47967]="如果你想在林子里逛逛，艾莎和我可以在这里等着。我是说…就我们俩。"
D.Strings[47968]="别听他的。我们还有事要做呢。"
D.Strings[47969]="……季，他们去了禅杖林。你应该明白尚师父去哪了……"
D.Strings[47970]="唉，就不能让我心存侥幸吗？我会想念那老头儿的。"
D.Strings[47971]="嘿！看那道瀑布！"
D.Strings[47972]="我在想它后面会不会有个洞。"
D.Strings[47973]="见到瀑布你就应该去看看它后面有没有洞穴。"
D.Strings[47974]="季，与神真子交谈的时候，应该保持恭敬。"
D.Strings[47975]="我哪里不恭敬了？我太伤心了，艾莎。"
D.Strings[47976]="你的无礼才让我伤心。"
D.Strings[47977]="神真子，我们是刘浪的后人。我们感到您很痛苦，我们想帮您。"
D.Strings[47978]="您怎么了，神真子？我们该怎么做？"
D.Strings[47979]="看看这些上好的丝绸！"
D.Strings[47980]="这东西真是从蚕的屁股里出来的吗？"
D.Strings[47981]="呃……它们看起来像蛆虫。"
D.Strings[47982]="我的身体上扎进了一根刺。我没法拔掉它。"
D.Strings[47983]="疼痛难当，我已经快游不动了。"
D.Strings[47984]="孩子们，你们能帮我拔掉这根刺吗？我对此无能为力。"
D.Strings[47985]="当然，神真子！可您的壳太大了，我不知道这根刺在哪儿。"
D.Strings[47986]="它就在你从未踏足过的森林中。沿着山脉走，你就能找到它。"
D.Strings[47987]="我们会找到它然后拔掉它的，我们向您保证！"
D.Strings[47988]="一根刺？可我把镊子丢在家里了。"
D.Strings[47989]="小小一根刺怎么会让那么大的东西受苦呢？"
D.Strings[47990]="我们马上就会知道了。"
D.Strings[47991]="我该不会是眼花了吧？！那是一艘船？！"
D.Strings[47992]="这是一艘船。一整艘飞船。这“刺”可比我想象的大多了。"
D.Strings[47993]="而且那些不是熊猫人。他们身上不长毛。"
D.Strings[47994]="他们应该不是来找麻烦的，他们的飞船坠毁了。"
D.Strings[47995]="飞船失事，一定有人在这座岛上遇难了。看来要拔掉这根刺绝非易事。"
D.Strings[47996]="我们得通知邵白长老，再计划下一步行动。"
D.Strings[47997]="那儿有个村子……还有一座很大的鱼雕像。"
D.Strings[47998]="你说这地方是锦鱼人造的吗？"
D.Strings[47999]="猢狲看着蠢蛋呢……总有一天，猢狲也会像蠢蛋一样能打！"
D.Strings[48000]="干掉所有锦鱼人，蠢蛋！"
D.Strings[48001]="留下买路财，蠢蛋。"
D.Strings[48002]="蠢蛋有鱼吗？"
D.Strings[48003]="杀锦鱼人，卡哈卡哈高兴。"
D.Strings[48004]="吊尾吃鱼。鱼造武器。吊尾武器杀锦鱼人！"
D.Strings[48005]="毛毛们，干掉锦鱼人！"
D.Strings[48006]="我想今天应该差不多了。让我们等陈叔回来吧。"
D.Strings[48007]="看，他回来了！酒厂怎么样，叔叔？"
D.Strings[48008]="哼！我实在不想说这件事。"
D.Strings[48009]="发生什么事啦，陈？"
D.Strings[48010]="我是个战士。为什么长老不让我战斗？"
D.Strings[48011]="每天，我们派出的战士只能勉强阻挡住那些猢狲。我们的人手根本不足以发起反击。"
D.Strings[48012]="为什么长老卢山不让我们反击猢狲呢？"
D.Strings[48013]="你没看到我正忙着吗？"
D.Strings[48014]="这些该死的猢狲在树林里就像幽灵一样神出鬼没！"
D.Strings[48015]="我们夺回月水庄只是时间问题。"
D.Strings[48016]="我们应该跟猢狲干到底，而不是恐惧退缩。"
D.Strings[48017]="长老是对的，我们应该用外交手段解决和猢狲的争端。"
D.Strings[48018]="看那湍流之水的力量！"
D.Strings[48019]="水泉急升！"
D.Strings[48020]="%s从喷水池中涌了出来！"
D.Strings[48021]="什么，你是来查我的？一切都好！一切都在控制之下！"
D.Strings[48022]="你的灵魂已经出窍！快回到你的身体里去吧！"
D.Strings[48023]="嗨，我好像已经摸到窍门了。"
D.Strings[48024]="我觉得我学到了一些新东西！"
D.Strings[48025]="我想我现在能够理解了。"
D.Strings[48026]="这个训练真的很有帮助。"
D.Strings[48027]="正在破坏并进入"
D.Strings[48028]="我们能从简单些的东西开始吗？"
D.Strings[48029]="这真是太难了！"
D.Strings[48030]="我为什么老是打不中？"
D.Strings[48031]="这玩意儿应该怎么用？"
D.Strings[48032]="嗯？敌人在哪儿呢？"
D.Strings[48033]="我什么时候才能睁开眼睛？"
D.Strings[48034]="敌人在哪儿呢？"
D.Strings[48035]="这些对手很强悍啊。"
D.Strings[48036]="嘿，这还真不赖。"
D.Strings[48037]="也不是那么难对付嘛。"
D.Strings[48038]="嘿，我们干得还不赖。"
D.Strings[48039]="战斗还没有结束呢！"
D.Strings[48040]="我们也许能赢。"
D.Strings[48041]="部族必胜！"
D.Strings[48042]="我是不会逃跑的！"
D.Strings[48043]="我们要战斗到底！"
D.Strings[48044]="冲啊！为了珠鳍部族！"
D.Strings[48045]="我什么都不怕！"
D.Strings[48046]="不要放弃，朋友们！"
D.Strings[48047]="为了荣耀！为了正义！"
D.Strings[48048]="为了我们的兄弟姐妹们！"
D.Strings[48049]="我要把你拿去喂鱼！"
D.Strings[48050]="狠狠地打呀，朋友们！"
D.Strings[48051]="努力战斗！前进！"
D.Strings[48052]="我感觉比以前更强壮了。"
D.Strings[48053]="出来受死吧，你这个怪物！已经没有怨灵给你充当挡箭牌了！"
D.Strings[48054]="我听说，你们是靠火焰与蛮力来铸造金属武器的。而我，是通过水流的压力以及对其密度的精确把握来制造武器的。"
D.Strings[48055]="啊！我的护罩！"
D.Strings[48056]="尽管虚张声势吧，但你们这些小崽子毫无机会。快跑吧，否则就迟了。"
D.Strings[48057]="你们竟敢挑战缚风者！我要杀光你们。"
D.Strings[48058]="夹着尾巴逃跑吧，狗东西。"
D.Strings[48059]="呸！"
D.Strings[48060]="躺下吧，小崽子。"
D.Strings[48061]="真是浪费我的时间。"
D.Strings[48062]="站住，小崽子。"
D.Strings[48063]="别动。"
D.Strings[48064]="你休想逃出风暴的掌控。"
D.Strings[48065]="死在寒冰之下吧。"
D.Strings[48066]="承受风暴的怒火吧！"
D.Strings[48067]="雷霆与闪电在我的命令下狂舞！"
D.Strings[48068]="在这个距离，你要面对的不仅仅是我的斧子。"
D.Strings[48069]="看看那些敢于阻拦我的家伙的下场吧！"
D.Strings[48070]="感受到背脊上的寒意了吗……？"
D.Strings[48071]="我花了那么多时间来束缚它，全浪费了！"
D.Strings[48072]="就算只剩一个，对付你们也是绰绰有余。"
D.Strings[48073]="你们这是在找死。"
D.Strings[48074]="你们自以为能戏弄我的闪电吗？"
D.Strings[48075]="不！更多……闪电……"
D.Strings[48076]="我受够你们的把戏了！去死吧。"
D.Strings[48077]="我现在就干掉你们，崽子！"
D.Strings[48078]="我建议你们放了我。我父亲可没我这么宽容。"
D.Strings[48079]="要不你帮我跟纳兹戈林谈谈？他似乎不太愿意跟我交涉。"
D.Strings[48080]="看看这片土地。现在，该是探讨和平，探索秘境的时候了。"
D.Strings[48081]="我敢肯定，只要你让我联系上我的同伴，我们就能对释放我的问题展开谈判了。"
D.Strings[48082]="看来我的斧子上又要多一个缺口了。"
D.Strings[48083]="给我一场真正的挑战吧！"
D.Strings[48084]="抱歉，我们现在不接待访客。"
D.Strings[48085]="我可不是访客，我是陈·风暴……"
D.Strings[48086]="你快走吧。"
D.Strings[48087]="可我们是一家人啊！我也姓风暴烈酒！从迷踪岛来……"
D.Strings[48088]="你聋了吗？我们现在不会让任何人进酒厂的。"
D.Strings[48089]="你怎么用这种态度和你的家人说话。"
D.Strings[48090]="等等——你身后是什么？！"
D.Strings[48091]="嗯？！没……没东西啊！马上滚！"
D.Strings[48092]="来，跟我谈谈吧！我们坐下来好好聊聊。一起喝一杯……"
D.Strings[48093]="我可不想陪你坐着说闲话。更不想喝你那些糟糕的啤酒！"
D.Strings[48094]="嘿，你身后是什么？！"
D.Strings[48095]="你要我说多少遍啊……滚出去！"
D.Strings[48096]="我真是不明白啊，老头。我到底哪里惹到你了？"
D.Strings[48097]="不论你做了什么，你的身份就惹到我了。这里不欢迎你，“陈·风暴烈酒”。"
D.Strings[48098]="我找到了酿酒厂，然后走进去。"
D.Strings[48099]="我决定在附近找找其他风暴烈酒家族的人。"
D.Strings[48100]="我有些动摇，但并没有放弃。我跟上那个古怪的老酿酒师，想要追问他。"
D.Strings[48101]="先是啤酒元素，然后又是猢狲？这其中肯定有蹊跷。"
D.Strings[48102]="我决定再给他一次机会。我是不会放弃我的家人的。"
D.Strings[48103]="听到这些我放弃了。我被自己的亲人……拒之千里！我转身离开了。"
D.Strings[48104]="我别无选择，只有自卫。"
D.Strings[48105]="*嗝*给我再来点儿该死的啤酒！*嗝*"
D.Strings[48106]="在我小的时候，我曾梦想成为一名酒仙。通过各种奇妙的化学反应酿造出完美的陈年佳酿。$b$b但在我学习的过程中，他们总说我酿的酒太烈了。$b$b所以我就转行搞冶炼了。当时看来，这种转行很合理。"
D.Strings[48107]="欢迎来到我的面馆，各式面条应有尽有。要是我们这儿没有的，您不吃也罢。"
D.Strings[48108]="我是强大的破军铁腹志大师，这个外号源自我那臭名昭著的腹壁神功。你大概已经听说我了吧。"
D.Strings[48109]="我曾经与长着恐怖利齿的野兽战斗过，我们最好不要提起它的名字，因为其中蕴含的恐惧足以使日月失色。"
D.Strings[48110]="秦可不是浪得虚名。曾经有过一场竞争非常激烈的面条大赛，汇集了全村的行家里手。$b$b他们在一桶桶煮沸的面汤前大展身手，只为在一天之内制作出最上乘的面条来。$b$b别提有多精彩啦！$b$b最终他技压群雄，做出来的面条好吃到连我这个美食家都为之震惊。"
D.Strings[48111]="又一个陌生人？你们都是从哪儿来的啊？$b$B几天前有一个自称来自于乌龟岛的人，他说他的名字叫风暴烈酒。"
D.Strings[48112]="你不会是到我的酿酒厂来捣乱的吧？那边那两个陌生人上周到这里时还大打出手了呢。"
D.Strings[48113]="游学者周卓对你称赞有加。只要你帮我们赶走猢狲，你永远都会受到欢迎。"
D.Strings[48114]="懦夫！你们这群懦弱的……走狗……"
D.Strings[48115]="你有话要对我说吗，师父？"
D.Strings[48116]="我叫托亚！无论你需要什么我都能帮你搞到！不用找别人了，我可是全晨芳园独一无二的！"
D.Strings[48117]="我已经准备好去见游学者周卓了。"
D.Strings[48118]="黑暗退去了……"
D.Strings[48119]="我注视水面，却看不见我的倒影……"
D.Strings[48120]="重归于……水流。"
D.Strings[48121]="再次感谢你的帮助，陌生人。我已经开始琢磨该给塞拉打造一枚什么样的戒指了。"
D.Strings[48122]="水流告诉我……敌人在逼近。"
D.Strings[48123]="哇，陌生人！你让那个恶毒的老巫婆明白了谁才是老大。"
D.Strings[48124]="你痛打那些懒猫的招式实在是太酷了！它们气势汹汹地来，结果被你三下两下就收拾掉了。"
D.Strings[48125]="大人们总是告诉我们说，那个住在林子里的青玉巫婆只是个因为而死了丈夫伤心过度的老太婆。可你证明他们错了！$b$b只是……我不能讲给那些大人们听，我可不想给自己找麻烦。"
D.Strings[48126]="|TInterface\\Icons\\inv_misc_food_23.blp:20|t乌克乌克|cFFFF0000|Hspell:106651|h[发疯]|h|r啦！更多的桶飞过来了！"
D.Strings[48127]="你看见罗·游酒了吗？"
D.Strings[48128]="你想要寻求突破吗？"
D.Strings[48129]="乌克！乌………克！"
D.Strings[48130]="你想拓展你的思维，强健你的身心，突破现在的极限吗？"
D.Strings[48131]="天禅院教会了我如何凝聚自己的力量，现在我只用一根小拇指就能点开一个酒桶。"
D.Strings[48132]="自从罗拐跑了我的弟子塞拉之后，我就再也没有见到过他了。他们往东边的百木园去了。$b$b这要是让他们的父母知道了可就糟了，游酒家族和金酿家族向来水火不容啊。"
D.Strings[48133]="欢迎来到百木园。愿你能在这林宇间找到灵感。"
D.Strings[48134]="生命之短暂犹如白驹过隙，眨眼即逝。"
D.Strings[48135]="我们的文化源远流长。$b$b多亏了我们的能工巧匠，使我们的文化记忆得以保存，并传承给下一代。"
D.Strings[48136]="你要找的是一对抛弃了家族名誉的爱侣。他们曾来过这里，想要找到厮守一生的方法。$b$b可惜他们并没有在林木或艺术中找到答案。"
D.Strings[48137]="族长的祝福。"
D.Strings[48138]="青龙，赐予我力量吧！"
D.Strings[48139]="罗？噢。我今天没看见他。我觉得这事儿很古怪。他每天早晨，都会陪我去工作的。$b$b他有一颗善良的心。他竟然没有好好珍惜自己与拙焰师匠的师徒缘分，这真是太遗憾了。他在金属冶炼上很有天赋。$b$b如果你见到他，请告诉他我今早没有等到他。"
D.Strings[48140]="你根本不明白你究竟干了什么。阿曼苏尔……我……看到……的……"
D.Strings[48141]="你好，破军铁腹先生！林子里的巫婆把我朋友变成了玉雕。你能帮帮我吗？"
D.Strings[48142]="你的死期到了。"
D.Strings[48143]="沙子已经漏完了。"
D.Strings[48144]="时光的尽头。"
D.Strings[48145]="只有疯子才相信重复的行为能带来不同的结果。"
D.Strings[48146]="再来一次也不会有任何改变。你必将失败。"
D.Strings[48147]="再次失败……？这就是你的诡计，你的阴谋？"
D.Strings[48148]="沙漏的力量耗尽了，游戏结束了，凡人。屈服，或者消亡。"
D.Strings[48149]="寡妇绿爪可不是巫婆。只是她做的青玉雕像非常逼真罢了。"
D.Strings[48150]="我们得点燃信号火焰。要是没有援军，它们会摧毁大门！"
D.Strings[48151]="可这儿全是螳螂妖。没有一条安全的道路！"
D.Strings[48152]="别担心！我能行！"
D.Strings[48153]="你在做什么？！你不会成功的！"
D.Strings[48154]="你这是在送死！"
D.Strings[48155]="他怎么不听劝呢！"
D.Strings[48156]="别再给新兵发那种红衬衫了。那只会把他们变成活靶子。"
D.Strings[48157]="有时候，你不去找它，想找的东西反而会自己出现。"
D.Strings[48158]="去和水谈谈吧，阿西约。"
D.Strings[48159]="你准备好后，就到水池里找我！"
D.Strings[48160]="你成功了！"
D.Strings[48161]="我们击败了灭世者！"
D.Strings[48162]="结束了；灭世者终于走向了灭亡。现在，我们将开始治疗这个世界。"
D.Strings[48163]="你完成了不可能完成的任务，全艾泽拉斯都担心你会失败，可你却成功了。"
D.Strings[48164]="我要是你们，就会赶快一点……"
D.Strings[48165]="你听到了吗？那是什么声音！"
D.Strings[48166]="难以置信！他不可能还活着！"
D.Strings[48167]="不！如此强大的力量！死亡之翼将召来毁灭所有生命的大灾变。赶快，我们必须阻止他！"
D.Strings[48168]="赶快，英雄们。死亡之翼引导的大灾变即将毁灭这个世界。和我一起进攻，快！"
D.Strings[48169]="灭世者想要集中它全部的力量来撕裂这个世界！快进攻！我们必须阻止这最后的大灾变！"
D.Strings[48170]="谁都逃不过我的怒火。"
D.Strings[48171]="你的护甲毫无作用，你的信仰一文不值。"
D.Strings[48172]="大海将吞噬你们熊熊燃烧的尸体。"
D.Strings[48173]="我要将这世界撕成碎片。"
D.Strings[48174]="我会让你们看看真正的大灾变。"
D.Strings[48175]="亲眼见证你们世界的末日。"
D.Strings[48176]="吾名死亡之翼，天命之灭世者，万物的终结者，无可阻挡，无可违逆；吾即大灾变！"
D.Strings[48177]="我会尽力放慢灭世者的攻击。"
D.Strings[48178]="你的口音很奇怪。你是从四风谷来的吗？"
D.Strings[48179]="你是冒险者吗？我们这儿见到冒险者，只有在老志说的那些故事里才能听到。"
D.Strings[48180]="新来的吧？你应该去尝尝秦的面条，那可是本地一绝。"
D.Strings[48181]="我听说，猢狲和锦鱼人的冲突正逐渐白热化。如果不能谨慎行事的话，这些可怜的小东西会同归于尽的。他们已经陷入了一个恶性循环。"
D.Strings[48182]="你是什么东西？我这辈子见过不少稀奇事儿，可像你这样的人还是第一次见。那只乌龟回来了吗？我一直以为那只是个传说。"
D.Strings[48183]="如果我每天想好好的睡上一觉，必须先打六七个小盹儿做做准备。"
D.Strings[48184]="青龙雕像就要完工了。你知道那意味着什么吗？持续数月之久的狂欢、庆典、酣睡和豪饮！我等不及了！"
D.Strings[48185]="%s一边哼着小曲，一边拿出他篮子里的东西。"
D.Strings[48186]="%s一边哼着小曲，一边拿出她篮子里的东西。"
D.Strings[48187]="对不起，月，我所能找到的鲜花都在这里了。水池里的花大多数还没开。"
D.Strings[48188]="从前有一群人，他们带着和平的使命，穿行在丝木林的深处。"
D.Strings[48189]="可是，黑暗的邪恶蜘蛛从它们的巢穴中爬了出来，个个长着邪恶的眼睛和狞恶的长腿。"
D.Strings[48190]="杀千刀的！"
D.Strings[48191]="凭借强大的武器和崇高的精神，我们的英雄将正义之火全部倾泻在那些野兽身上。那场面，壮观极了！"
D.Strings[48192]="噢噢噢！！！"
D.Strings[48193]="哇哇哇！"
D.Strings[48194]="开酒桶可是一门代代相传的手艺。用不着去问别人这是不是真的，只要记住我的话就行了。"
D.Strings[48195]="“一些很有深度的话。”$b$B好了。以后如果有人问你第一次见到李·寻杯时他都说了什么，你就可以回答说了“一些很有深度的话。”"
D.Strings[48196]="我是一个酒桶匠。对外行来说，这门手艺似乎很简单。但酒桶的用料对于酒水口味的影响之大，绝对会出乎你的意料。"
D.Strings[48197]="你好，$c！$B$B我们这里养殖着全潘达利亚最好的莲花。我们的莲花从这里送到下面的新希菲拉村，然后在那里分类和装船，最后运送到各地。$B$B莲花的用途广泛，在烹饪、医疗和装饰领域都能发挥作用——所以你也能想到，它的需求量是很大的。"
D.Strings[48198]="你们！这一切都是你们造成的吗……？"
D.Strings[48199]="都是因为你们，黑暗和恐惧玷污了这片圣地！为了先祖的荣耀，我要亲手惩罚你们！"
D.Strings[48200]="这是……什么地方？我……干了什么？原谅我，父亲……"
D.Strings[48201]="这就是你付出的代价！"
D.Strings[48202]="公正的惩罚！"
D.Strings[48203]="尝尝傲慢的苦果吧！"
D.Strings[48204]="我的怒火无边！"
D.Strings[48205]="你想接受试炼？就凭你！？"
D.Strings[48206]="我已经准备好接受竹之试炼了。"
D.Strings[48207]="我的拳头已蓄势待发，想继续接受木之试炼。"
D.Strings[48208]="我已经完成了你所有的要求。我已经准备好接受石之试炼了。"
D.Strings[48209]="|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|t%s开始施放|cFFFF0000|Hspell:105651|h[源质箭]|h|r!"
D.Strings[48210]="嗨，你好啊！$B$B<小女孩瞥了你一眼。>$B$B我无意中听到了你和大贤者的谈话。他这个人太严肃了，不是吗？$B$B哈哈，这回你可走运了，因为我碰巧知道这周围发生的所有事情。"
D.Strings[48211]="很好，陌生人。让我看看你们有多大能耐。"
D.Strings[48212]="会舞刀弄枪只能证明你们身子骨不错，略懂武学。让我告诉你们什么才是融汇真气之力。"
D.Strings[48213]="少不更事的时候，我连打出一记好拳都难，但经过多年修炼，我已今非昔比！"
D.Strings[48214]="嗨，陌生人！嘿！快过来！"
D.Strings[48215]="我被打败了。让我休息一下，我们将一起面对煞的挑战。"
D.Strings[48216]="这里的水开始变得狂野而混乱，一定有什么东西在扰动它们。"
D.Strings[48217]="我必须与流水谈一谈，才能了解它们的骚动源自何处。"
D.Strings[48218]="多亏了你，我现在可以继续工作了。"
D.Strings[48219]="长老，我找到你的法杖了。"
D.Strings[48220]="这根法杖承载了我世代相传的先祖之力。感谢你把它归还给我。"
D.Strings[48221]="欢迎来到青龙寺，旅行者。$B$B我们欢迎所有的来访者，并将知识自由传授给所有求知的人。"
D.Strings[48222]="好吧，我们继续！"
D.Strings[48223]="我会让你们离翡翠梦境更近一些。当战斗太过激烈的时候可以进入梦境寻求庇护。"
D.Strings[48224]="英雄们，进攻。只有你们能为我们创造机会！"
D.Strings[48225]="要让死亡之翼暴露弱点，这些英雄是唯一的希望。团结，我们终将胜利。"
D.Strings[48226]="别放弃。击败死亡之翼的希望寄托在你们身上了。"
D.Strings[48227]="|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s攻击|cFFFF0000|Hspell:107018|h[阿莱克丝塔萨]|h|r！"
D.Strings[48228]="|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s攻击|cFFFFFF00|Hspell:107018|h[诺兹多姆]|h|r！"
D.Strings[48229]="|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s攻击|cFF04FC32|Hspell:107018|h[伊瑟拉]|h|r!"
D.Strings[48230]="|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s攻击|cFF5858FA|Hspell:107018|h[卡雷苟斯]|h|r！"
D.Strings[48231]="|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s开始施放|cFFFF0000|Hspell:107018|h[攻击守护巨龙]|h|r！"
D.Strings[48232]="你们这些白痴没打中蠢蛋！再来！"
D.Strings[48233]="你看起来就像个旱鸭子！"
D.Strings[48234]="变得像你这么笨会不会很伤？"
D.Strings[48235]="按照这个速度，我很快就要自然死亡了。"
D.Strings[48236]="你们什么都没做到。我要撕碎你们的世界。"
D.Strings[48237]="我的鞭尾幼龙不见了。"
D.Strings[48238]="我的猎豹幼崽不见了。"
D.Strings[48239]="我的气球不见了。"
D.Strings[48240]="科多兽已经等在路上了。一路顺风，$G兄弟:姐妹;。"
D.Strings[48241]="真想不到这些野猴子也能训练有素。"
D.Strings[48242]="轰轰太小啦！有轰轰的蠢蛋好难缠！"
D.Strings[48243]="我只给了你一颗炸弹，你就偷着乐吧。忘恩负义的家伙。"
D.Strings[48244]="很显然，你把我和某个跑龙套的家伙给搞混了。"
D.Strings[48245]="看来以后你的膳食里该多加点纤维素了。"
D.Strings[48246]="我的轰轰太小啦！我能再拿一个吗？"
D.Strings[48247]="再给我一个好吗？"
D.Strings[48248]="这个雕工精湛的青玉雕像看上去很像风裘的朋友阿信，睁大的眼睛里充满了恐惧。"
D.Strings[48249]="坏蛋只会干坏事！"
D.Strings[48250]="门？！我能把整堵墙都炸飞！"
D.Strings[48251]="这个可以当炸弹。"
D.Strings[48252]="我得照着这幅地图前往晨芳园。"
D.Strings[48253]="你就是炸弹！"
D.Strings[48254]="把你炸飞……轰！"
D.Strings[48255]="轰！爆炸！全炸飞！"
D.Strings[48256]="轰！噼里啪啦！"
D.Strings[48257]="谁敢打搅乌克的派对？！"
D.Strings[48258]="青龙之心不会堕入你们之手！"
D.Strings[48259]="轮回终将继续，青龙必将重生！"
D.Strings[48260]="青龙之心是我的！"
D.Strings[48261]="离开这里。"
D.Strings[48262]="我眼前的迷雾终于散去……原谅我对你们的猜忌……"
D.Strings[48263]="摒弃疑虑吧，祭司……"
D.Strings[48264]="我高贵的瓦罗森，记得回来处理这群野蛮的暴徒。"
D.Strings[48265]="为你效忠，我的女王！"
D.Strings[48266]="是他们！"
D.Strings[48267]="英雄们！是诺兹多姆派我们来的！快上来，我们要把你们带到巨龙之魂那儿！"
D.Strings[48268]="姐妹，快看！那个神器被黑暗的光环所围绕！"
D.Strings[48269]="是守护巨龙！"
D.Strings[48270]="是上古之神在保护着巨龙之魂！"
D.Strings[48271]="必须破坏传送门的联结！快去找怒风！"
D.Strings[48272]="啊，欢迎。你们也是来参加庆祝仪式的？不是？真可惜。"
D.Strings[48273]="快乐地服侍艾萨拉吧，傀儡们。"
D.Strings[48274]="真是傲慢无礼。我有点生气了。"
D.Strings[48275]="麦龙下达了疏散命令。"
D.Strings[48276]="哦，我不清楚。我老了，而且常常……"
D.Strings[48277]="当心！螳螂妖！"
D.Strings[48278]="我就怕这一天会到来。我去收拾东西。"
D.Strings[48279]="怎么，又来一个？指挥官麦龙派你来的？$b$b我跟那个蠢蛋说了多少次了—我们绝不撤离！"
D.Strings[48280]="是的，指挥官麦龙派我来的，我带来了他的紧急疏散令。"
D.Strings[48281]="嘁……外来者。你对石犁之道一无所知。"
D.Strings[48282]="我们很自豪。我们很强大。我们是阡陌客的后裔……我们决不会逃避困难。"
D.Strings[48283]="没错。所以，$r，你还是快走吧，让我们来保卫自己的财产。"
D.Strings[48284]="退后！$b$b等等……你不是它们的一员。我们不习惯有外人，在螳螂妖破墙而入的当下，我……$b$b无论如何，我们能为你做些什么？"
D.Strings[48285]="我明白了。我本来觉得我们可以挺过这场入侵的，但如果上面想让我们离开的话，那我们就离开。"
D.Strings[48286]="瑛、辉钟……去收拾东西。等农场安全了，我们再回来。"
D.Strings[48287]="噢，亲爱的……"
D.Strings[48288]="爸爸，这个好人要杀死所有的坏螳螂妖士兵吗？"
D.Strings[48289]="我不知道，亲爱的。"
D.Strings[48290]="你会怎么做呢？"
D.Strings[48291]="我是个农民，$c。我只知道这一点。"
D.Strings[48292]="除了土地，我们一无所有。那位指挥官却想让我们把它拱手让给螳螂妖？"
D.Strings[48293]="我不会那么做的。在蟠龙脊的阴凉中播下第一粒种子开始，我的祖父就知道将来会变成什么样子。"
D.Strings[48294]="我有妻子，两个健壮的女儿，还有两个强壮的儿子。谢谢你，但我们能保卫这个农场。"
D.Strings[48295]="但愿我看到的那些纸不是疏散令。"
D.Strings[48296]="欢迎来到石犁村。能为你做点什么吗？"
D.Strings[48297]="对不起，这里一团乱。什么都是乱糟糟的。$b$b我能帮你什么吗？"
D.Strings[48298]="你收到疏散令了吗？"
D.Strings[48299]="是的，就在这儿呢。走吧。"
D.Strings[48300]="我又想了下……待在这儿太危险。生命可比土地重要多了。让我看看那些疏散令。"
D.Strings[48301]="嗨，新丁！你刚才跟我说话了吗？不好意思，我的耳朵还没从爆炸里恢复过来，到现在还在嗡嗡作响呢！"
D.Strings[48302]="大声解释如何返回营地。"
D.Strings[48303]="叫醒他。"
D.Strings[48304]="<这个侏儒的脸上烟熏火燎的，但还活着。>"
D.Strings[48305]="你的任务是什么？我这里有你需要的工具。"
D.Strings[48306]="<这个矮人失去了意识，但并没有受伤。>"
D.Strings[48307]="除非我死了，否则他们休想占领这个营地！"
D.Strings[48308]="在执行任务时，一定要睁大眼睛，多动脑子，新兵。"
D.Strings[48309]="哇哦，撞得可真够惨的！我身上的零件好像都还在。谢了，新丁。"
D.Strings[48310]="噢！我看我们的情形要比安玻和尼姆强点。我看见他们的飞机起火了，就在更靠近内陆一点的地方。谢谢你了，$c。"
D.Strings[48311]="我会再照顾你一小会，$n。我看到还有许多受伤的机组成员需要我的帮助呢。"
D.Strings[48312]="这里很适合使用水占术！"
D.Strings[48313]="来吧，妹妹，该做个了结了。我们将净化上古之神对巨龙之魂造成的黑暗污染！"
D.Strings[48314]="太强大了！"
D.Strings[48315]="你怎么敢染指我的造物？！它是我的，我的，我的！"
D.Strings[48316]="奈萨里奥！你都做了些什么？你将上古之神的疯狂厄运带给了我们！"
D.Strings[48317]="它·是·我·的！"
D.Strings[48318]="他背叛我们了，姐姐。他不再是奈萨里奥了。"
D.Strings[48319]="巨龙之魂的力量正在撕裂他！"
D.Strings[48320]="不……滚开……"
D.Strings[48321]="我是不会失败的。"
D.Strings[48322]="什么？跟着你？好吧！"
D.Strings[48323]="最终的时刻到来了。我将在这一刻消亡。轮回结束了。未来的我再也不能作恶了。"
D.Strings[48324]="在未来，我仍将……堕入疯狂。而你们，英雄们，注定将消灭我。循环仍将继续，如此往复。"
D.Strings[48325]="重要的是艾泽拉斯并没有毁灭；我们仍将为生存而战。"
D.Strings[48326]="最重要的是……此时此刻。"
D.Strings[48327]="“时光之末”，我曾经这么称呼这个地方，我看不到从此以后的时间。什么？你想要……阻止我？改变我花费了无尽时间编织的命运？"
D.Strings[48328]="你在地上无知地爬行，像一只瞎眼的爬虫，向着无尽的疯狂与绝望蠕动。我见证了真正的时光之末。这儿？这儿只是你无法理解的祝福。"
D.Strings[48329]="%s消失在阴影中了！"
D.Strings[48330]="佩罗萨恩之眼正在搜寻你。"
D.Strings[48331]="选择你的目的地。"
D.Strings[48332]="时光入口"
D.Strings[48333]="红玉巨龙圣地"
D.Strings[48334]="翡翠巨龙圣地"
D.Strings[48335]="碧蓝巨龙圣地"
D.Strings[48336]=S[22113]
D.Strings[48337]="青铜巨龙圣地"
D.Strings[48338]="你听到了吗！？隐秘大师，是在北边吗！？"
D.Strings[48339]="执勤官，我得走了。我终于可以继续训练了！"
D.Strings[48340]="也许我会在那儿见到你，$n！"
D.Strings[48341]="$n，你干的不错，我要回营地去照顾其他伤员了。你要是没事了就到指挥官那里去报个道。"
D.Strings[48342]="哦，还有，$r！去把货物带回来，好吗？我得确保它们没事。"
D.Strings[48343]="我和雪雾会等着的！请快去快回！"
D.Strings[48344]="我们遇到麻烦了。快帮忙保护我们的战友！"
D.Strings[48345]="巨龙之魂内的黑暗力量对净化产生了强烈的反应！"
D.Strings[48346]="这个测试很简单。你要做的就是击打竹子，直到它破裂。"
D.Strings[48347]="你或许会说：“可竹子太厚了！”。"
D.Strings[48348]="这只是测试的一部分。是的，要想成功，你必须将全身力量集中在一只拳头上……"
D.Strings[48349]="……然后，出拳！"
D.Strings[48350]="在力量积聚到顶点时，一拳击打到竹堆上！"
D.Strings[48351]="这个测试很简单。你要做的就是击打木板，直到它破裂。"
D.Strings[48352]="你或许会说：“可木板太硬了！”。"
D.Strings[48353]="但它其实并没那么硬。你已经做好了准备，$n。"
D.Strings[48354]="这个测试很简单。你要做的就是击打石块，直到将其击碎。"
D.Strings[48355]="你或许会说：“那是不可能的！”。"
D.Strings[48356]="那你就错了。清除杂念，集中精神，没什么是不可能的。"
D.Strings[48357]="是的，就这样！"
D.Strings[48358]="这拳漂亮。"
D.Strings[48359]="精神很集中，$n。"
D.Strings[48360]="你学得很快。"
D.Strings[48361]="换我自己来也不见得能做得更好了。"
D.Strings[48362]="不，你必须集中精神！"
D.Strings[48363]="我们不能再浪费时间了，旅行者。"
D.Strings[48364]="等到时机成熟……然后出拳！"
D.Strings[48365]="耐心是关键。"
D.Strings[48366]="集中精神，清除杂念，$n。"
D.Strings[48367]="你的拳头很有力，但念力不够。"
D.Strings[48368]="再试一次。"
D.Strings[48369]="精神高于物质，$n。"
D.Strings[48370]="不要害怕那块石头。"
D.Strings[48371]="当力量积蓄到顶点时，一拳击打到木堆上！"
D.Strings[48372]="当力量积蓄到顶点时，一拳击打到石堆上！"
D.Strings[48373]="我以前只做过一次……希望这次能成功。"
D.Strings[48374]="%s把法杖插入到池中，然后把脑袋抵在法杖顶端。"
D.Strings[48375]="欢迎，$n。"
D.Strings[48376]="你是到这儿来深造的吗，$n？"
D.Strings[48377]="我能帮什么忙吗，$n？"
D.Strings[48378]="我能为你做的就这些了，$n。带着我教你的知识，到别的地方施展才能吧。"
D.Strings[48379]="这……这是什么地方？真是太美了……但……似乎有点不对劲。"
D.Strings[48380]="小水花们，如果你们能别跑得那么快，我或许能帮你们！"
D.Strings[48381]="黑暗降临了。我能感受到骨子里的寒意。"
D.Strings[48382]="别害怕，小家伙们。无论光明还是黑暗，流水不腐。"
D.Strings[48383]="水即是生命。一旦水遭遇痛苦，我们也将在劫难逃。"
D.Strings[48384]="锦鱼人和他们的疯狂仪式……"
D.Strings[48385]="我知道你朋友看到了什么，$n——他现在需要休息。来和我谈谈。"
D.Strings[48386]="有什么东西扰乱了水。它们平常都很乖的。"
D.Strings[48387]="我不知道怎么描述……你得看看这个，$n。"
D.Strings[48388]="%s伏击了无助的猎物！"
D.Strings[48389]="可能吗？锦鱼人难道真能轻易接触到水的力量？"
D.Strings[48390]="我从未见过有人如此轻易就从水中看到幻象。$B$B不过，我都不记得上次锦鱼人是何时来访，然后把脸扎进水里的了……"
D.Strings[48391]="顽皮的金色小翔龙舔了舔你。"
D.Strings[48392]="顽皮的金色小翔龙翻了个漂亮的筋斗。"
D.Strings[48393]="顽皮的金色小翔龙淘气地咬了咬你。"
D.Strings[48394]="顽皮的金色小翔龙在向你撒娇。"
D.Strings[48395]="顽皮的金色小翔龙亲昵地挨擦着你的胳膊。"
D.Strings[48396]="顽皮的金色小翔龙在追咬自己的尾巴。"
D.Strings[48397]="顽皮的赤红小翔龙舔了舔你。"
D.Strings[48398]="顽皮的赤红小翔龙做了个鬼脸。"
D.Strings[48399]="顽皮的赤红小翔龙兴奋地大叫。"
D.Strings[48400]="顽皮的金色小翔龙直冲云霄。"
D.Strings[48401]="顽皮的赤红小翔龙试探着咬了咬你。"
D.Strings[48402]="顽皮的赤红小翔龙觉得很无聊。"
D.Strings[48403]="顽皮的翡翠小翔龙好奇地环顾四周。"
D.Strings[48404]="顽皮的翡翠小翔龙嗅了嗅你。"
D.Strings[48405]="顽皮的翡翠小翔龙想要吃你的头发，可马上又吐了出来。呃！"
D.Strings[48406]="顽皮的翡翠小翔龙在空中打滚。"
D.Strings[48407]="顽皮的翡翠小翔龙开始昏昏欲睡。"
D.Strings[48408]="顽皮的翡翠小翔龙想要玩游戏！"
D.Strings[48409]="顽皮的青色小翔龙在和自己的影子嬉戏。"
D.Strings[48410]="顽皮的青色小翔龙饿了！"
D.Strings[48411]="顽皮的青色小翔龙想要吃点心。"
D.Strings[48412]="顽皮的青色小翔龙问你有没有东西吃。"
D.Strings[48413]="顽皮的青色小翔龙在舔舐自己。"
D.Strings[48414]="顽皮的青色小翔龙在撒娇！"
D.Strings[48415]="选择一只宠物，为你战斗！"
D.Strings[48416]="英雄们，这个重担又落到你们的肩上了。我们会将守护巨龙的力量灌注到巨龙之魂中，在此期间，你们必须保护我们。"
D.Strings[48417]="你们可以开始仪式了，我们会保护你们的。"
D.Strings[48418]="我们的引擎受损了！我们成了活靶子！"
D.Strings[48419]="重逢真令我高兴，阿莱克斯塔萨。分开之后，我可是一直很忙。"
D.Strings[48420]="它们……已经不再是我的子嗣了。消灭它们。"
D.Strings[48421]="这个藏书室保存着几千年的历史文化，以及全潘达利亚的最了不起的知识。$B$B这也是我们一定要保护好这里的原因。"
D.Strings[48422]="卷轴！我必须抢救出那些卷轴！"
D.Strings[48423]="这没有用，巨龙之魂的力量太强大了。我不能安全地使用它，这个神器里的混乱力量也许会毁掉我们所有的人。"
D.Strings[48424]="调查中"
D.Strings[48425]="嘿嘿嘿嘿嘿！"
D.Strings[48426]="更多能量！"
D.Strings[48427]="真美味！"
D.Strings[48428]="当心那个小瓶子，它有点儿漏。"
D.Strings[48429]="欢迎来到青龙寺。有什么需要帮助的吗？"
D.Strings[48430]="我想进入青龙寺。"
D.Strings[48431]="我有消息要带给青龙。"
D.Strings[48432]="你在青龙寺里找到需要的东西了吗？"
D.Strings[48433]="我想要返回青龙寺庭院。"
D.Strings[48434]="你真是帮了我们寺院大忙了！$B$B我听大贤者说他很高兴你的到来。"
D.Strings[48435]="欢迎来到青龙寺，陌生人。我们的大门永远向渴求知识的人敞开。"
D.Strings[48436]="传送到花园入口。"
D.Strings[48437]="你的谷物怎么这么寡淡无味？"
D.Strings[48438]="他们辜负了我们，姐妹。"
D.Strings[48439]="我从迷梦中苏醒，只是为了再次沉睡。"
D.Strings[48440]="我们的谷物是供应给酿酒厂的，量都很大。也许有一种谷物符合你的需要。"
D.Strings[48441]="对我们来说，这点时光不过是弹指一挥间……"
D.Strings[48442]="……的确如此。"
D.Strings[48443]="或许还有办法……"
D.Strings[48444]="丽丽……我们走。你叔叔要证明一些事情。"
D.Strings[48445]="终于！这才是我所期待的陈叔呢。"
D.Strings[48446]="传回伊利丹身边。"
D.Strings[48447]="传送到艾萨拉的宫殿。"
D.Strings[48448]="传送到艾萨拉之台。"
D.Strings[48449]="传送到永恒之井。"
D.Strings[48450]="首先我们需要的是，一些甜麦芽。"
D.Strings[48451]="噢，你好！以前没见过你……"
D.Strings[48452]="%s用力咬断了缰绳，逃了出来！"
D.Strings[48453]="我想你可以从粮仓里找到你要的甜麦芽。"
D.Strings[48454]="泥盏！"
D.Strings[48455]="我是来帮忙酿造你们说的那种神奇啤酒的。"
D.Strings[48456]="很高兴你能加入。我们要酿一种烈酒。你能弄几桶水来吗？"
D.Strings[48457]="包在我身上。"
D.Strings[48458]="丽丽，你去找麦芽。我……去调查当地的啤酒。然后在这儿会合。"
D.Strings[48459]="“调查”？好吧。"
D.Strings[48460]="$n，很抱歉欺骗了你，但这实属无奈之举。"
D.Strings[48461]="数千年来，我们从未遇见过你这样的人。"
D.Strings[48462]="所以我得先探明你的心意，这非常重要。"
D.Strings[48463]="现在，我已经看到了，你的行为非常正派。"
D.Strings[48464]="唉，我变得越来越虚弱，已经看不清命运的织线了。"
D.Strings[48465]="我很好奇，你到底是哪一根线？到底是毁天灭地的那一根，还是力挽狂澜的那一根？"
D.Strings[48466]="我老了，小家伙。我的时日无多了。"
D.Strings[48467]="看到远处那宏伟的雕像了吗？"
D.Strings[48468]="那些建造者辛勤劳作多年，就快完工了。"
D.Strings[48469]="再来些玉石——就是你取回的那种——就大功告成了。"
D.Strings[48470]="我会将我所有的生命精华灌输到雕像中去。新的守护者由此诞生。"
D.Strings[48471]="有朝一日，你也会响应召唤，捍卫你所挚爱的一切。"
D.Strings[48472]="不要难过。这就是轮回——我非起点，亦非终点。"
D.Strings[48473]="缅怀那些已归于尘土的逝者。"
D.Strings[48474]="珍惜让你来到这尘世的生命。"
D.Strings[48475]="滴水之恩，当涌泉相报。"
D.Strings[48476]="只有这样，我们的智慧才能得以代代相传，绵延后世。"
D.Strings[48477]="这便是我们的生存之道，亘古不变。"
D.Strings[48478]="我累了。需要休息了。"
D.Strings[48479]="作出明智的选择吧，年轻人。"
D.Strings[48480]="这些谷物的味道不够新鲜，又苦又涩。"
D.Strings[48481]="这谷物吃起来太清淡，太有弹性了。"
D.Strings[48482]="这些谷物味道太杂了。"
D.Strings[48483]="不，今天不提供试吃了。除非有人帮我将被盗的谷物找回来才行！"
D.Strings[48484]="这些谷物的土腥味儿太重，太生了。"
D.Strings[48485]="跟我来，小家伙。我想给你看一样东西。"
D.Strings[48486]="幻化"
D.Strings[48487]="%s痛苦地尖叫并退入了云海的漩涡中。"
D.Strings[48488]="祭司们害怕面对真相……"
D.Strings[48489]="首先，去给我的鲜绿菠菜浇水！"
D.Strings[48490]="干得不错！现在去给我巨大的胡萝卜浇水！"
D.Strings[48491]="继续！给我的卷心菜浇水！"
D.Strings[48492]="别停！给那些甜菜浇水！"
D.Strings[48493]="去给我巨大的甜瓜浇水，沿着这条路往下再就是！"
D.Strings[48494]="继续！现在给我的红叶莴苣浇水！"
D.Strings[48495]="看起来给我的甜菜浇的水还不够！赶快回去！"
D.Strings[48496]="给我的鲜绿菠菜浇水！"
D.Strings[48497]="给我的大胡萝卜浇水！"
D.Strings[48498]="给我的卷心菜浇水！"
D.Strings[48499]="给我的甜菜浇水！"
D.Strings[48500]="给我巨大的甜瓜浇水！"
D.Strings[48501]="给我的红叶莴苣浇水！"
D.Strings[48502]="给我的象鼻蒜浇水！"
D.Strings[48503]="你想重铸物品？我这里已经不提供这种服务了。\n\n不过暴风城的教堂区里的虚灵商店“三缕风”可以帮助你。\n\n所有的城市守卫都可以帮你指路。"
D.Strings[48504]="你想重铸物品？我这里已经不提供这种服务了。\n\n不过奥格瑞玛的暗巷区里的虚灵们可以帮助你。\n\n所有的城市守卫都可以帮你指路。"
D.Strings[48505]="不不不！回来，我们再试一次！"
D.Strings[48506]="作为一名翔龙骑士，必须无所畏惧。"
D.Strings[48507]="留意翔龙的动作。你必须集中精神，做到人龙合一。"
D.Strings[48508]="你要和你的翔龙同进共退，今日如此，日日皆然。"
D.Strings[48509]="你选择了这条道路，将自己的生命和翔龙联系在了一起。可别辜负了它们！"
D.Strings[48510]="我们绝不容忍懦夫！强者方能获胜。"
D.Strings[48511]="好好训练你的翔龙。信赖是你最强有力的武器。"
D.Strings[48512]="翔龙骑士的道路上充满了鲜血与泪水。你的旅途才刚开始。"
D.Strings[48513]="你在找东西吗，$r？你看起来在找东西。"
D.Strings[48514]="水罐空了。去找园丁芳兰。"
D.Strings[48515]="你刚刚浇过那个地方了！别对我耍懒！"
D.Strings[48516]="噢，你好，陌生人。很抱歉，这里很乱。通常这个粮仓是非常有秩序有效率的。"
D.Strings[48517]="欢迎来到帝皇粮仓。$b$B不过现在林精肆虐，粮仓没那么“帝皇”了。噢，嗯，你难道没听说，或看见，那件事。$b$B请你不要告诉别人你来过这里，特别是不要提及我们被林精打得大败这件事，好吗？"
D.Strings[48518]="你只是买错了一种谷物，然后突然世界都崩溃了。现在我们要对付肆虐的林精和迁徙的候鸟。$b$B我正在努力帮忙完成风暴烈酒酿造厂的订单！"
D.Strings[48519]="过去，我的父亲会连续几天在丛林里搜寻最完美的岩洞大麦。$b$B这事非常危险，我可不愿意舍身犯险。$b$B这不值得。风暴烈酒关心的是数量而不是质量。"
D.Strings[48520]="好吧，虽然这里依然是林精泛滥，但我非常感谢你给我们的帮助。你真是个游侠。"
D.Strings[48521]="虽然遭遇大败，但我还是要重新准备风暴烈酒酿酒厂的订单。风暴烈酒酿造厂最近似乎出了点问题，因为他们订购的谷物没有过去那么多了。"
D.Strings[48522]="如果你要到西边的荒野里去，请留心找找我那古怪的父亲。他从来不为风暴烈酒酿造厂日益增长的采购量而高兴。$b$B我从小就听他说，要“酿造出不同一般的啤酒”。他总是自称啤酒达人。$b$B但是，他也许会有一些你感兴趣的小东西或故事。"
D.Strings[48523]="看，那儿长了一棵草！去拔掉它！"
D.Strings[48524]="那儿也有一些草！"
D.Strings[48525]="继续，你做得很好！"
D.Strings[48526]="你只要把那些小草踩烂就行了。不用浪费时间去拔它们。"
D.Strings[48527]="我还有一些除草剂。可能有用。"
D.Strings[48528]="这儿还有一些多余的除草剂！"
D.Strings[48529]="看起来这些家伙总算开始安分下来了。"
D.Strings[48530]="点击杂草将其拔掉！"
D.Strings[48531]="踏过小草！"
D.Strings[48532]="捡起除草剂！"
D.Strings[48533]="喔！你在干嘛？！"
D.Strings[48534]="啊！住手！我在等雷鸟来抓我！"
D.Strings[48535]="为什么？！"
D.Strings[48536]="别管我了，否则它们会把你也抓走的！"
D.Strings[48537]="呃……我有点晕。"
D.Strings[48538]="你疯了，你知道吗？又来了一只！"
D.Strings[48539]="我打算让我的田休耕一季。一个聪明的农夫知道什么时候该让土地休息。"
D.Strings[48540]="好吧，难道你不是来除草的吗？"
D.Strings[48541]="什么草？"
D.Strings[48542]="$n，瞧瞧他们！$b$b你不在的这段时间里，我们已经把这群猴子打造成一支训练有素的军队啦！"
D.Strings[48543]="我的任务就是设法提高蚕丝产量。但我过于自信，竟造出了怪物！这将是我的毕生的耻辱。"
D.Strings[48544]="熊猫小姐！在胡萝卜上面跳只舞吧！"
D.Strings[48545]="是啊，好主意！让你那毛茸茸的脚动起来吧！"
D.Strings[48546]="你现在站在这根大胡萝卜上，给我个飞吻吧！"
D.Strings[48547]="熊猫小姐！坐到胡萝卜上！"
D.Strings[48548]="现在站起来！"
D.Strings[48549]="坐下，再站起来，这样连续做多次！"
D.Strings[48550]="噢耶……"
D.Strings[48551]="熊猫小姐！我有个主意！"
D.Strings[48552]="在这儿，你站在大胡萝卜上，再拿着小胡萝卜！"
D.Strings[48553]="耶，你拿起那根胡萝卜。对。"
D.Strings[48554]="熊猫小姐！抓住这根胡萝卜！"
D.Strings[48555]="现在扔给我！"
D.Strings[48556]="使劲往我脸上扔！"
D.Strings[48557]="熊猫小姐！接着！"
D.Strings[48558]="现在吃掉那根胡萝卜！"
D.Strings[48559]="不！吃慢点儿！"
D.Strings[48560]="嗯——嗯。干得不错，熊猫小姐。"
D.Strings[48561]="我在帮一个朋友酿造啤酒，需要用啤酒花。能给我一点吗？"
D.Strings[48562]="你能卖给我一些啤酒花吗？"
D.Strings[48563]="你有多余的啤酒花给我吗？"
D.Strings[48564]="我想你确实是帮我给植物浇过水了。很好……我会派人将啤酒花送到半山，交给你那位叫陈的朋友。"
D.Strings[48565]="天下没有免费的午餐，$r。想要啤酒花，你就得出点力。"
D.Strings[48566]="当然了！你帮我除掉那些杂草，我肯定会分你一些啤酒花。我会把啤酒花送给半山的风暴烈酒大师的。"
D.Strings[48567]="我也很想帮你，$c，但我遇到一点关于杂草的小麻烦。嗯……你大概是不肯帮我解决问题的，是吧？"
D.Strings[48568]="当然愿意了。你去杀几个兔妖，就挣到一些啤酒花。我会叫蒙蒙把啤酒花送去半山的。"
D.Strings[48569]="你得跟蒙蒙商量商量。是他在管理我们的存粮。"
D.Strings[48570]="你说你需要啤酒花？好吧。我会送一些到半山。"
D.Strings[48571]="你真是个救星，$c。我立刻就将啤酒花送到半山。"
D.Strings[48572]="里克把这贱人抓起来了！$b$b猢狲大军有了好多光板儿！"
D.Strings[48573]="你说你需要啤酒花？没问题。你帮我杀兔妖，蒙蒙就帮你把啤酒花送到半山。"
D.Strings[48574]="兔妖！嗨！数不尽的兔妖！"
D.Strings[48575]="米娜！你回来了！"
D.Strings[48576]="爸爸……我再也不想看到胡萝卜了。"
D.Strings[48577]="送我去大漩涡。"
D.Strings[48578]="我要挑战黑角，送我去天火号甲板。"
D.Strings[48579]="我要挑战哈格拉，送我去龙眠神殿顶层。"
D.Strings[48580]="我要挑战约萨希和佐诺兹，送我去龙眠神殿底层。"
D.Strings[48581]="这么……多……胡萝卜……"
D.Strings[48582]="快来，米娜。我们离开这儿。"
D.Strings[48583]="一条幼龙俯冲下来，往甲板上投放了一个暮光工兵！"
D.Strings[48584]="煞魔从寺庙里跑出来了，我们得把他们赶回去……或者同归于尽。"
D.Strings[48585]="我们回家。"
D.Strings[48586]="当然，你可以在骑乘状态下去为植物浇水。我为什么要在乎这个？"
D.Strings[48587]="龙眠联军，进攻！"
D.Strings[48588]="塔丽苟萨还活着！我们必须前进，朝神殿进军！"
D.Strings[48589]="左转……左转！左——转！"
D.Strings[48590]="不！右转！右转！"
D.Strings[48591]="啊啊啊！我们都要完蛋啦！"
D.Strings[48592]="向着前线进发！"
D.Strings[48593]="必须打退围攻的敌人。龙眠联军，守住阵线!"
D.Strings[48594]="我的学徒们常常忘记，一个人要达到登峰造极的境界必须先经历多次失败。"
D.Strings[48595]="我觉得你这个人饱经沧桑。"
D.Strings[48596]="你穿的外套挺有趣。我能问一下这是出自谁的手吗？"
D.Strings[48597]="我记得曾经有位德高望重的蔡丝匠做出了一种极品丝线，它掉在地上时都能把泥土切开。可那之后我们就再也没见过那种丝了。"
D.Strings[48598]="我记得我的第一次实验失败了。这些地里当时爬满了前所未见的超级大虫子。"
D.Strings[48599]="纺丝人锦织曾经织出很薄很滑的丝绸，可以瞬间从细缝中滑过。虽然尚未将其复制出来，但我们希望能在近期成功。"
D.Strings[48600]="欢迎你，陌生人。我是蔡丝匠。欢迎来到古老的皇家丝场。$b$b这个农场可以回溯到最早的几个熊猫人王朝，在丝绸质量方面是青出于蓝胜于蓝，一代更比一代强。"
D.Strings[48601]="靴子，不好。腰带，非常不好。衬衣，挺好看，但不适合你。我们应该给你弄个斗篷。也许再配件样式符合英雄身份的外套。"
D.Strings[48602]="你让我想起了年轻的郭大师，他腰围要再细一点。$b$B我第一次见他时他还是个农场小工，尽管衣衫褴褛，但走起路来英姿飒爽，和他英俊的外表还挺相配。$B$b我们一起做了一个服装系列，在东部地区流行了至少两年。"
D.Strings[48603]="让我一个人呆着。"
D.Strings[48604]="还有什么意义呢？"
D.Strings[48605]="别管我。"
D.Strings[48606]="别挤我，人们总喜欢在村子里挤成一堆。没地方啦。"
D.Strings[48607]="天还在下雨。又冷。还好最近没台风。"
D.Strings[48608]="噢，麻烦让一下。"
D.Strings[48609]="一根香蕉在手，胜过两根香蕉在林。"
D.Strings[48610]="噢，太好了。一位冒险家。正是我需要的。"
D.Strings[48611]="这日子马马虎虎吧。跟混日子的人正相配。"
D.Strings[48612]="这点小雨又不会伤人……起码目前没有。"
D.Strings[48613]="今天几号了？都没人来告诉我。"
D.Strings[48614]="别烦我。"
D.Strings[48615]="这种事怎么会发生到我身上呢？我受够了这种生活。"
D.Strings[48616]="欢迎登上天火号。我们要追到世界的尽头，你们准备好了吗？"
D.Strings[48617]="我们联盟时刻准备着。"
D.Strings[48618]="为了正义与荣耀！"
D.Strings[48619]="嗷！我的脸！"
D.Strings[48620]="坏虫子！那是个非常非常非常坏的虫子！"
D.Strings[48621]="能吃下头牛。"
D.Strings[48622]="我们部落时刻准备着。"
D.Strings[48623]="暮光之锤撤退了！我们夺回了神殿；进入神殿，稳固防守。"
D.Strings[48624]="啊，很高兴见到你，我的朋友！$B$B饿了吗？"
D.Strings[48625]="嘿，另外，关于那个瓶子，我很抱歉。其实我们应该把那些陈年老泥留在瓶子里——它们的年头都快赶上老酒了。"
D.Strings[48626]="你总能从设计师设计的服装上看出他们的性格。你的服装看上去实用大于美观。$b$b灌注了法力的织物缝合紧密。很出色，不过要是能有一个风雅的设计师来改进一下就更好了。"
D.Strings[48627]="师父，我的火炬不见了。"
D.Strings[48628]="我恨无能的掠夺者。"
D.Strings[48629]="我还是很恨你。"
D.Strings[48630]="你恨我吗？很好。"
D.Strings[48631]="我恨心慈手软。"
D.Strings[48632]="我倒不太恨杀戮。"
D.Strings[48633]="我恨冒险者。"
D.Strings[48634]="我恨……你们所有人……"
D.Strings[48635]="我恨你们所有人！"
D.Strings[48636]="我恨站着不动。"
D.Strings[48637]="我的仇恨在燃烧！"
D.Strings[48638]="我的仇恨会吞噬你！"
D.Strings[48639]="我恨护甲。"
D.Strings[48640]="我恨肉盾。"
D.Strings[48641]="我恨死这个地方了。也许关押我的人早就死了，但别以为我会放过你们这些卑鄙的财宝猎人。"
D.Strings[48642]="咏之池的芦苇是这里最硬的东西，但要是碰到我坚实的额头，也不过是浮云。"
D.Strings[48643]="试者连连，屡试不爽。"
D.Strings[48644]="外面有人吗？"
D.Strings[48645]="这里好黑啊！"
D.Strings[48646]="来人啊，救我出去！"
D.Strings[48647]="救救救命！"
D.Strings[48648]="把我从桶里弄出去！"
D.Strings[48649]="我们的工人制造出了最好的木板。它们能经受最恐怖的风暴考验。但在我碎颅风暴的侵袭下，它们就像流水一样软弱。"
D.Strings[48650]="熊猫人双手创造出的一切都抵挡不了我的额头。"
D.Strings[48651]="那个怪物被打败了！万岁！"
D.Strings[48652]="我想喝杯啤酒。"
D.Strings[48653]="你都不知道我在里面呆了多久。"
D.Strings[48654]="啊！这光……它闪到我们的眼睛了……"
D.Strings[48655]="在他回来之前，我们最好离开这儿！"
D.Strings[48656]="谢谢你，好心的……噢，不，他又来了！"
D.Strings[48657]="我想被永远困在啤酒桶里还不算最糟糕的下场。"
D.Strings[48658]="这是神真子背上最硬的石头，但在我坚硬的头颅面前，它们不值一提。"
D.Strings[48659]="任何胆敢质疑我力量的人，都是蠢货。"
D.Strings[48660]="谢谢你！我会设法弄破一部分丝盾的。"
D.Strings[48661]="好粘啊！我会帮你把那只飞蛾弄下来。"
D.Strings[48662]="谢谢你，陌生人！"
D.Strings[48663]="现在我只要做一件事，那就是砸碎它！这下，所有人都会彻底看清我额头的强大力量。"
D.Strings[48664]="噢……我的头……好痛啊！我……这根柱子肯定蕴藏着巨大的力量……也许比我的额头还要厉害……"
D.Strings[48665]="这真是太精美了！我从未见过如此精良的工艺。"
D.Strings[48666]="我……我得躺一会儿了……直到头疼好一点为止。"
D.Strings[48667]="%s被吸入了苟拉斯之口"
D.Strings[48668]="他们突破了我们的防御……连大地都以死亡之翼的名义背叛了我们。"
D.Strings[48669]="阿丽萨巴尔将$n困在了地上。"
D.Strings[48670]="我们在另一边见，$n。"
D.Strings[48671]="泥盏、丽丽……跟我走！"
D.Strings[48672]="丽丽，泥盏，等等！"
D.Strings[48673]="丽丽，等等！"
D.Strings[48674]="我最好跟上泥盏……"
D.Strings[48675]="我先走了，看有什么要帮忙的。"
D.Strings[48676]="陈叔，泥盏！看我们谁先到那儿！"
D.Strings[48677]="嘿，老怪物们！你们等等我！"
D.Strings[48678]="嘿，你个呆老头！等等我！"
D.Strings[48679]="回头见咯，陈叔！"
D.Strings[48680]="酒厂还有一个入口，就在那边。"
D.Strings[48681]="我会到那儿跟你们会合。"
D.Strings[48682]="那两个家伙呢？他们不会丢下我了吧？就没人关心泥盏吗？"
D.Strings[48683]="我想我还是走吧。你来吗，丽丽？"
D.Strings[48684]="我想我还是走吧。你来吗，陈？"
D.Strings[48685]="那……你们知道那位隐居的大师在哪儿吗？"
D.Strings[48686]="我很确信那就是他叫隐秘大师的原因，林。"
D.Strings[48687]="哦，真遗憾。"
D.Strings[48688]="那么，我们从哪儿开始找？"
D.Strings[48689]="我可以试着向溪流寻求指引…"
D.Strings[48690]="向河流发问？阿西约你又不是长老。你还没有成年。这是在浪费你的时间。"
D.Strings[48691]="肯肯觉得我们应该分开走。跟着风儿。"
D.Strings[48692]="这个想法要好的多，肯肯。我可以向南出发，深入丛林。"
D.Strings[48693]="我追随北风的指引。"
D.Strings[48694]="肯肯去追东风。路程最短。"
D.Strings[48695]="我……我想我就去西面吧。"
D.Strings[48696]="很好。作为我们之中最胖最年长的人，我会在这里等待大家安全归来。"
D.Strings[48697]="祝你们好运，朋友们。一旦找到隐秘大师，我们就可以继续训练了。"
D.Strings[48698]="由于特殊原因，测试服上火焰之地已经关闭。"
D.Strings[48699]="传送到沙恩诺克斯"
D.Strings[48700]="传送到雷奥利斯领主"
D.Strings[48701]="传送到贝丝缇拉克"
D.Strings[48702]="传送到奥利瑟拉佐尔"
D.Strings[48703]="传送到贝尔洛克"
D.Strings[48704]="传送到范达尔"
D.Strings[48705]="传送到拉格纳罗斯"
D.Strings[48706]="我可以把你传送到火焰之地的任何一个首领附近。"
D.Strings[48707]="征服火焰之地的比赛开始了！"
D.Strings[48708]="你好啊，朋友！欢迎你乘坐我的牛车。它可以送你去大箩农场。"
D.Strings[48709]="很好，$n。我需要你帮忙酿制这种啤酒。"
D.Strings[48710]="在我喊出配料名字的时候，你就把它们扔进锅中……"
D.Strings[48711]="我开玩笑的！"
D.Strings[48712]="我可是三个大陆最棒的酿酒师！这部分我自己能搞定。"
D.Strings[48713]="啊哈哈！你一定能做到的！"
D.Strings[48714]="如果你不介意，$n……可能需要等上很长时间哦。"
D.Strings[48715]="真是花了很长时间！"
D.Strings[48716]="魔丝勒斯来了！"
D.Strings[48717]="你好啊，朋友！欢迎你乘坐我的牛车。它可以送你去五晨寺。"
D.Strings[48718]="你刚刚赢得了一张酷炫海报！把手举起来，装成满不在乎的样子吧！"
D.Strings[48719]="你不是应该在训练吗，年轻的$c？$B$B只要好好修炼你的心志和躯体，就没有什么是你做不到的。"
D.Strings[48720]="我押蓝获胜。你没看见他在上周的训练中，是怎么打倒楚的吗？"
D.Strings[48721]="你这就错了，朋友。周就如橡树一般坚韧不拔。"
D.Strings[48722]="周的耐力比得上三个普通人，所以他能打败大部分的对手。"
D.Strings[48723]="周的耐力在蓝的力量面前不值一提。"
D.Strings[48724]="他的腿像牛一样有力！你在训练时被他踢到过吗？"
D.Strings[48725]="我押周，四个铜板。"
D.Strings[48726]="我赌一桶风暴金酿。你输定了。"
D.Strings[48727]="养蚕取丝真是一个危险的活儿。"
D.Strings[48728]="你的招式真是无懈可击。"
D.Strings[48729]="对一个新手来说，拥有如此技巧实属难得。"
D.Strings[48730]="以后你一定得把你的秘诀教给我。"
D.Strings[48731]="那个沙袋毫无还手之力。"
D.Strings[48732]="真该让师父们来看看！"
D.Strings[48733]="你注定要成就一番大事业，新人。"
D.Strings[48734]="我得像你那么刻苦才行。"
D.Strings[48735]="为了赶上你，我得更加努力地训练才行。"
D.Strings[48736]="你是一位可敬的对手。"
D.Strings[48737]="多谢你的指点，我必须更加努力地修炼才行。"
D.Strings[48738]="你赢得光明正大，朋友。"
D.Strings[48739]="我打不过你。我认输了。"
D.Strings[48740]="你太厉害了。我认输。"
D.Strings[48741]="你很会战斗。我以后一定得好好向你学习。"
D.Strings[48742]="真是场痛快的战斗。谢谢你。"
D.Strings[48743]="我从没见过像你这么厉害的学徒。我得告诉其他人去。"
D.Strings[48744]="< PLACEHOLDER：你发现黑龙蛋已经孵化成了黑龙王子拉希奥！>"
D.Strings[48745]="如你所知，我们黑龙经常会假扮成形色各异的人，去插手凡人的事务。"
D.Strings[48746]="当我发疯的父亲众叛亲离时，那些残存的黑龙四散奔逃，并藏了起来。"
D.Strings[48747]="但是，我还是能感觉到他们。如果任由他们藏在阴影里，我那些懦弱的兄弟姐妹们指不定会掀起怎样的波澜。"
D.Strings[48748]="他们也是对我的威胁。"
D.Strings[48749]="这就是你的任务了。帮我们去杀掉他们，然后我会好好回报你。"
D.Strings[48750]="我实在没法独自击退那么多敌人。现在，如果你不介意的话，我得去找我的车了。"
D.Strings[48751]="我的车！"
D.Strings[48752]="你好啊，老伙计。还底朝天躺在这儿呢？"
D.Strings[48753]="没有凡人能阻碍我的使命。"
D.Strings[48754]="你妄想阻止雪崩。我只会埋葬你。"
D.Strings[48755]="你们以为对手只有我？碎裂的大地会摧垮你。"
D.Strings[48756]="不可能。这不可能。这座塔……必须毁掉……"
D.Strings[48757]="这是必然的结局。"
D.Strings[48758]="大地归于尘土。"
D.Strings[48759]="石头在呼唤……"
D.Strings[48760]="大地在震颤……"
D.Strings[48761]="啊哈哈！你们输定了！"
D.Strings[48762]="岩石在战抖……"
D.Strings[48763]="地面在动荡……"
D.Strings[48764]="……大地的黑血会吞噬你。"
D.Strings[48765]="……没人能从上古之神的手中逃脱。"
D.Strings[48766]="……真神之怒接踵而来。"
D.Strings[48767]="……主人的仇恨将吞没你。"
D.Strings[48768]="逃向死亡。"
D.Strings[48769]="奔向灭亡。"
D.Strings[48770]="小心！它的同伴过来了！"
D.Strings[48771]="懦夫。弱者。下来与我一战，否则我就“送”你们下来。"
D.Strings[48772]="你不可能永远躲在这座神殿里，萨满。"
D.Strings[48773]="我会夷平这座塔，将它的碎片抛洒在荒原上。"
D.Strings[48774]="神殿必将倒塌。万物归于尘土。"
D.Strings[48775]="你的第一个目标，就在吉尔尼斯废墟。我之前派去的人都失败了，看看你能不能走运点。"
D.Strings[48776]="如果他成功洗劫了吉尔尼斯，没人能知道他以后的行踪。现在就是进攻的时机。"
D.Strings[48777]="你要找的那条龙名为“信条”。"
D.Strings[48778]="他蛊惑了一群染病的人类，让他们自以为可以夺回失去的土地。他用他的龙族精华污染了那些人的血。"
D.Strings[48779]="如果我不能把这些桶运回去，学徒们会很失望的。真是糟透了……"
D.Strings[48780]="你的确变强了，孩子。这很好。这力量很快就会有用武之地。"
D.Strings[48781]="我们到了。如果你愿意，可以在我做准备时帮我几个小忙。"
D.Strings[48782]="小心啊！我们之前的那12个刺客就是这么挂掉的。"
D.Strings[48783]="你看到了吧？那些家伙都是些凶残的野兽！"
D.Strings[48784]="扎佐来救你了！再试一次……"
D.Strings[48785]="没事了，$n。这次……我总算救下了你。"
D.Strings[48786]="注意你脚下的路！城里到处都是他们的人……"
D.Strings[48787]="你管那叫潜行？"
D.Strings[48788]="谁都别想就这么飞进吉尔尼斯城！"
D.Strings[48789]="哇哇哇——他们在所有的房顶上都安插了狙击手。你得靠双脚走进去！"
D.Strings[48790]="你不能就这么飞进去——肯定会被发现的。你以为我们没有试过吗？"
D.Strings[48791]="在这里——一个刺客！"
D.Strings[48792]="保护信条大人！"
D.Strings[48793]="抓住$g他:她;！"
D.Strings[48794]="把$g他:她;揪出来！"
D.Strings[48795]="干掉$g他:她;！"
D.Strings[48796]="我闻到你的气味了，小偷！"
D.Strings[48797]="去死吧，刺客！"
D.Strings[48798]="魔丝勒斯飞起来了，将灭蛾战士从丝茧中解救出来，让他们把她打下来。"
D.Strings[48799]="魔丝勒斯下来了。攻击！"
D.Strings[48800]="我们将重塑这个世界。"
D.Strings[48801]="你必将失败！"
D.Strings[48802]="脆弱的心灵是你们最大的弱点。"
D.Strings[48803]="你们的世界将陷入黑暗！"
D.Strings[48804]="你无法消灭我们……"
D.Strings[48805]="你休想阻止我们……"
D.Strings[48806]="好刺眼的光芒！"
D.Strings[48807]="我受不了……这声音了！"
D.Strings[48808]="我的力量在流失！"
D.Strings[48809]="嗯，一个刺客？谁派你来的？快老实交代，不然我就把答案从你脑袋里挖出来！"
D.Strings[48810]="我永远不会忘记您给予我们的帮助。是您让我们免遭屈辱，英雄。谢谢你！"
D.Strings[48811]="你们可以继续仪式了，我们会保护你们的。"
D.Strings[48812]="祝你在潘达利亚最古老、最负盛名的丝绸农场过得开心。"
D.Strings[48813]="在蚕作茧时，我们就用这件设备来抽取蚕丝。"
D.Strings[48814]="我们祖祖辈辈都致力于改良桑叶，希望能培育出最适合蚕虫的食物。"
D.Strings[48815]="我们在这里饲养新生的幼蚕，直到它们能够吐丝作茧。"
D.Strings[48816]="我要挑战奥卓克希昂，送我去龙眠神殿顶层。"
D.Strings[48817]="你成功了！信条的黑暗魔法干扰了我的视线——从现在起，你就得靠自己了。祝你好运！"
D.Strings[48818]="完成了！我们的力量灌注到了巨龙之魂里！我们的命运就交给你了，大地守护者！"
D.Strings[48819]="塔蕾莎……凯恩……阿格娜……我不会辜负你们。我不会辜负这个世界！"
D.Strings[48820]="我们夜以继日地辛苦劳作，究竟是为了什么？$B$B这一切都毫无意义……"
D.Strings[48821]="哈？什么？$B$B噢，我又醒了。$B$B<孙妮发出一声长叹。>$B$B自从下起这场雨，我就什么都懒得做……"
D.Strings[48822]="我受够这些伪装了。让我们做个了断吧！"
D.Strings[48823]="我不知道这里究竟发生了什么事——似乎所有人都疯了！$B$B拜托了，你能帮帮忙吗？"
D.Strings[48824]="这是……谁的……命令？"
D.Strings[48825]="你成功了！你真是我的大英雄，$n！拉希奥王子一定会很高兴的。"
D.Strings[48826]="在巨龙的眼中，我只看到了绝望……"
D.Strings[48827]="让你的信仰，指引你。"
D.Strings[48828]="见证我的力量！"
D.Strings[48829]="圣光会吞噬你！"
D.Strings[48830]="被暗影淹没！"
D.Strings[48831]="而你，你的灰烬将成为我们的盛宴！现在，受死吧！"
D.Strings[48832]="|TInterface\\Icons\\spell_shadow_twilight.blp:20|t奥卓克希昂开始施放|cFF9900CC|Hspell:106371|h[暮光审判]|h|r!"
D.Strings[48833]="你好啊！我说，你该不会是在找返回大炮的传送门吧？$B$B我就可以帮你！$B$B当然了，只是要一小笔费用……"
D.Strings[48834]="哇，准头不错嘛！$B$B就是把我的鱼吓跑了。$B$B你想快速传回大炮那里去吗？$B$B当然了，你得付一小笔费用……"
D.Strings[48835]="把我传送回大炮那里。"
D.Strings[48836]="你感到有饥饿的眼神在注视着你。"
D.Strings[48837]="这些雷鸟不美吗？简直堪称壮丽。令人生畏。$B$B它们在这片土地上比我们任何人都要珍贵。$B$B我要在这里等着。等他们准备好，就会带我走了。"
D.Strings[48838]="别白费力气了。$B$B我哪儿都不去。"
D.Strings[48839]="拜托了，易默，你的阿姨很担心你。"
D.Strings[48840]="我没时间跟你废话。自己挪动屁股，别等我动手帮你。"
D.Strings[48841]="干得好，朋友。你证明了自己是一名优秀的刺客。你的致命一击能成就一支大军所不能成就的伟业。"
D.Strings[48842]="如果你想要继续为我们工作，我们还需要一些补给……"
D.Strings[48843]="哼！瞎猫碰到死耗子而已。"
D.Strings[48844]="你的人生还长得很。"
D.Strings[48845]="她真的担心我吗？我很怀疑……"
D.Strings[48846]="那什么是人生呢？失望之后还是失望，没完没了。"
D.Strings[48847]="%s召唤|cFF9932CD|Hspell:104896|h[紫色]|h|r，|cFFFF0404|Hspell:104897|h[红色]|h|r，|cFFFFA901|Hspell:104901|h[黄色]|h|r，以及|cFF424242|Hspell:104894|h[黑色]|h|r舒玛之血！"
D.Strings[48848]="%s召唤|cFF9932CD|Hspell:104896|h[紫色]|h|r，|cFF088A08|Hspell:104898|h[绿色]|h|r，|cFF424242|Hspell:104894|h[黑色]|h|r，以及|cFF0080FF|Hspell:104900|h[蓝色]|h|r舒玛之血！"
D.Strings[48849]="%s召唤|cFF088A08|Hspell:104898|h[绿色]|h|r，|cFFFF0404|Hspell:104897|h[红色]|h|r，|cFF0080FF|Hspell:104900|h[蓝色]|h|r，以及|cFF424242|Hspell:104894|h[黑色]|h|r舒玛之血！"
D.Strings[48850]="%s召唤|cFF088A08|Hspell:104898|h[绿色]|h|r，|cFFFFA901|Hspell:104901|h[黄色]|h|r，|cFF424242|Hspell:104894|h[黑色]|h|r，以及|cFFFF0404|Hspell:104897|h[红色]|h|r舒玛之血！"
D.Strings[48851]="%s召唤|cFF0080FF|Hspell:104900|h[蓝色]|h|r，|cFF9932CD|Hspell:104896|h[紫色]|h|r，|cFF088A08|Hspell:104898|h[绿色]|h|r，以及|cFFFFA901|Hspell:104901|h[黄色]|h|r舒玛之血！"
D.Strings[48852]="%s召唤|cFF0080FF|Hspell:104900|h[蓝色]|h|r，|cFF424242|Hspell:104894|h[黑色]|h|r，|cFF9932CD|Hspell:104896|h[紫色]|h|r，以及|cFFFFA901|Hspell:104901|h[黄色]|h|r舒玛之血！"
D.Strings[48853]="我们找到了她，藏在卡拉赞地下的洞穴里。担惊受怕之余，她正在学习埋藏于地下的奥术秘密。"
D.Strings[48854]="她由一群疯狂的巨龙教徒守卫着。那些教徒也许脑子不太正常，但却武装到了牙齿，极度危险。"
D.Strings[48855]="你收集来的这些宝石能够强化我给你的武器，但我还需要一些别的材料。它们就在你的下一个对手身上。"
D.Strings[48856]="她的名字叫“纳莉丝”。不久之前她还作为黑龙军团的代表站在龙眠神殿里。现在？她逃走了。"
D.Strings[48857]="我希望能见到你活着完成这个任务。要是你挂了，至少我挺享受你为我们工作的过程。你是你们种族中的佼佼者。祝你好运。"
D.Strings[48858]="准备调查这个地方。"
D.Strings[48859]="我讨厌使用暴力。"
D.Strings[48860]="我不知道你是谁，但我会用生命来保卫这座圣殿。在我动手之前离开吧。"
D.Strings[48861]="我现在明白了。永别了，还有，祝你好运。"
D.Strings[48862]="是你逼我的。"
D.Strings[48863]="我不想这样的。"
D.Strings[48864]="我以为你会投降的。"
D.Strings[48865]="也许这个能冷静一下你的头脑……"
D.Strings[48866]="这些冰块应该能熄灭你胸中的怒火……"
D.Strings[48867]="你为什么不放弃？！"
D.Strings[48868]="我们必须尽快行动！塔丽苟萨和她的守卫们已经倒下了，神殿的防御完全崩溃。决不能让死亡之翼的部队接近巨龙之魂，否则一切都完了。龙眠联军会在战斗中协助你的；我们必须打破敌人的围攻！"
D.Strings[48869]="我谦卑地请求守护巨龙们不要为我和我的同伴提供援助。他们应该操心他们自己的事，我们的事就让我们自己来解决吧。"
D.Strings[48870]="你可真不聪明，刺客。"
D.Strings[48871]="干掉$g他:她;。"
D.Strings[48872]="鬼鬼祟祟的老鼠。你死定了！"
D.Strings[48873]="你到底是个疯子、傻瓜，还是个值得颂扬的英雄呢？你到底是哪个？"
D.Strings[48874]="我们会名留青史的。"
D.Strings[48875]="我们等着瞧吧，$C。"
D.Strings[48876]="有话就说吧。我一步都不会动的。"
D.Strings[48877]="我知道，对吗？"
D.Strings[48878]="你必须施展出浑身解数才有可能潜入那里。"
D.Strings[48879]="这大概是你的装备吧？"
D.Strings[48880]="拉希奥对你有信心。我就知道你一定能成功的！"
D.Strings[48881]="你是不可能神不知鬼不觉地飞进去的……我试过了。"
D.Strings[48882]="成功！我们又消灭了一条堕落的巨龙！很快，死亡之翼就得孤军奋战了……"
D.Strings[48883]="你进去了！纳莉丝的守卫阻碍了我的魔法，所以从现在开始，我就没法继续指点你了。去干掉她！"
D.Strings[48884]="|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s准备施放|cFF9900CC|Hspell:106401|h[暮光杀戮]|h|r！"
D.Strings[48885]="再见，以及，祝好运。"
D.Strings[48886]="真是个愚蠢的家伙，竟然想挑战我们。他那腐臭的尸体就留给燃烧军团做个纪念，好让他们牢记伊利丹·怒风的强大力量。\n$b暗影斗篷的力量正在减弱，已经无法再遮掩我们的行踪了。这玩意儿用起来也挺有趣的，但我更喜欢直接把死亡带给我的敌人。\n$b你很能打，可我接下来要去的地方只能由我独自前往了。"
D.Strings[48887]="我错过什么好戏了吗？噢，哇！"
D.Strings[48888]="嘿！我在上面！不对，我在下面呢！如果你愿意的话，我可以把你送回现实世界。"
D.Strings[48889]="$n，你眼前所见，就是遥远的未来。在这个时空，死亡之翼，暮光之锤和上古之神们赢得了胜利。因此，这里也成了一片荒芜，亘古不变的荒原，只有一些昔日的残影还在这里徘徊。"
D.Strings[48890]="我已经做好返回过去的准备了——我要去永恒之井。"
D.Strings[48891]="我准备好返回现实，去帮助萨尔了。"
D.Strings[48892]="我准备好去时光之末见诺兹多姆了。"
D.Strings[48893]="我能帮你什么忙吗，陌生人？"
D.Strings[48894]="跟紧我，$n。我们可能需要互相帮助。"
D.Strings[48895]="成功了。巨龙之魂已经被安全送到巨龙军团手中了。"
D.Strings[48896]="我在寻找走失的小伙伴。"
D.Strings[48897]="嗤。仗着时光守护者站在你们那边，你们就敢闯进这陷阱吗？"
D.Strings[48898]="别得意，小崽子。我们会把你们从这个世界上清除掉。"
D.Strings[48899]="哼！你们休想活着离开这里！"
D.Strings[48900]="你们没人能活着看到真正的大灾变！杀掉他们！"
D.Strings[48901]="看那些装甲！他正在解体！摧毁那些装甲，我们就能给他最后一击！"
D.Strings[48902]="别担心我。去阻止灭世者吧！Enshu-falah-nah, dorini。"
D.Strings[48903]="玛法里奥……"
D.Strings[48904]="他在井水旁……"
D.Strings[48905]="我不知道你是谁……但我要感谢你。没有你的帮助，我们的世界……我不敢想象。愿月神指引你的道路。"
D.Strings[48906]="你们这些蠢货竟然还在我背上。"
D.Strings[48907]="你们的努力是徒劳的，我只会带着你们飞向死亡。"
D.Strings[48908]="别抵抗了，“英雄们”。你们和这个世界都在劫难逃。"
D.Strings[48909]="你们的顽强令我赞叹，但毫无价值。你们踏上了末日审判之路。"
D.Strings[48910]="作战翔龙是不能飞出青龙寺庭院的！在你被扔下来之前赶紧回去！"
D.Strings[48911]="他朝着大漩涡去了！我们必须马上阻止他；如果他逃回了深岩之洲，我们就再也没有机会了。"
D.Strings[48912]="啊，神器！"
D.Strings[48913]="哥哥……你来得真及时……"
D.Strings[48914]="没错。滥用魔法导致了它的扭曲。我们——特别是你——处理传送门时做得太过火了！将燃烧军团送回扭曲虚空的力量现在影响到了永恒之井！它正在自我吞噬，并吸收周围的一切东西！真壮观，是吧？"
D.Strings[48915]="如果你知道怎么离开，我们恐怕得赶快了！我本想带着泰兰德离开，但井水的魔力太混乱了！"
D.Strings[48916]="没人能背叛女王！"
D.Strings[48917]="死有余辜！"
D.Strings[48918]="以艾萨拉之名！"
D.Strings[48919]="哈，泰兰德。伊利丹在哪？"
D.Strings[48920]="伊利丹！永恒之井失去控制了！"
D.Strings[48921]="我们可不能被卷进去！你为什么不逃跑？……你把手伸进井水里想干什么？"
D.Strings[48922]="屈服于我，死吧！"
D.Strings[48923]="抽搐吧！惨叫吧！"
D.Strings[48924]="[恶魔语] Amanare maev il azgalada zila ashj ashj zila enkil！"
D.Strings[48925]="我们从这个时间段收集了一些东西。但愿它能帮上忙！"
D.Strings[48926]="将你的幼龙变成扭曲无脑的畸形，并屈从于我的命令。这可是……非常痛苦的过程。"
D.Strings[48927]="奈法利安，奥妮克希亚，希奈丝特拉……他们毫无价值。现在，你们就要面对我最终的造物。"
D.Strings[48928]="暮光审判已经临近；你们这些可悲的凡人即将谢幕。"
D.Strings[48929]="我们把这些酒装上马车，怎么样？"
D.Strings[48930]="前往风暴烈酒酿造厂！"
D.Strings[48931]="再见，半山村！"
D.Strings[48932]="泥盏，你来吗？"
D.Strings[48933]="噢，我不太确定。这看来是你们的家务事……"
D.Strings[48934]="这确实是家务事，泥盏。但是我希望你加入。"
D.Strings[48935]="不开玩笑？"
D.Strings[48936]="当然不开玩笑！我们一起酿过酒，我们是好兄弟。"
D.Strings[48937]="对啊！啤酒兄弟！"
D.Strings[48938]="呃！你们俩就得了吧。"
D.Strings[48939]="来，和我一起拉货车。"
D.Strings[48940]="这就是你们最快的速度？加油，胖子们！都跑起来！"
D.Strings[48941]="很好，收紧小腹，气聚丹田……"
D.Strings[48942]="说正经的，泥盏。一起去吧。"
D.Strings[48943]="不，还不一定。我相信……是的……这样也许能行。"
D.Strings[48944]="我会打开通向永恒之眼的通路。英雄们，你们绝不能失败，艾泽拉斯的未来寄托在你们身上。"
D.Strings[48945]="是的，我明白了。我们将使用死亡之翼的力量去对付他自己。"
D.Strings[48946]="那么，我们就真的失败了。"
D.Strings[48947]="我感到了危险。这是个陷阱……在这个险恶的时刻，我们被算计了。"
D.Strings[48948]="我们没有选择，必须相信这些盟友。"
D.Strings[48949]="终于来了！一个挑战者！让我们来试试你的气魄吧，“勇士”。"
D.Strings[48950]="你是来向圣光祈祷的吗？还是来接受圣光技艺的训练呢？$b$b如果你是来找大主教本尼迪塔斯的话，那我必须很抱歉地告诉你，他出门去执行任务了。"
D.Strings[48951]="是的。他受命前往龙眠神殿帮助守护巨龙。他希望能帮助他们扫除死亡之翼对艾泽拉斯的威胁。$b$b愿圣光指引他的道路。"
D.Strings[48952]="哈哈哈！本尼迪塔斯，暮光先知！$b$b哇哈哈哈！$b$b噢，那真是太好了。万岁！"
D.Strings[48953]="都是流言，孩子。流言总是能想方设法地和大人物搭上关系。事实上，我最近还听到一些关于已故的伯瓦尔大人的坏话呢。$b$b到别处去散播你的谎言吧。等你准备好在圣光面前忏悔自己的错误时再回来吧。"
D.Strings[48954]="任务？"
D.Strings[48955]="事实上，我在龙眠神殿见到了本尼迪塔斯。他就是暮光先知。"
D.Strings[48956]="我可没开玩笑。本尼迪塔斯想要杀了萨尔，把艾泽拉斯拱手交给死亡之翼。这是我亲眼看到的。"
D.Strings[48957]="我们的翔龙正在努力拯救寺庙。$B$B如果你需要的话，它们很乐意向你伸出援手。"
D.Strings[48958]="我从来没有见到过像这样的敌人。"
D.Strings[48959]="这是我们的土地，我们的家园。$B$B我绝不会眼睁睁看着它落入煞魔手中。"
D.Strings[48960]="尽管我们一直努力想要塑造更加进步的文明，可我们总是重复过去的错误。$B$B煞魔又一次威胁到了这片土地。"
D.Strings[48961]="我们不能纠结于过去的错误了，$r。$B$B现在唯一的办法就是前进。"
D.Strings[48962]="拿出你的勇气来，$r。团结一致，我们就能对抗煞魔。"
D.Strings[48963]="当煞魔开始攻击的时候，我所有的弟子都毫不犹豫地出去战斗了。$B$B我教了他们很多东西，但他们的表现总能超出我的期望。"
D.Strings[48964]="我们对煞魔的大部分认知都失传了。$B$B随着战斗的持续，我必须要研究他们的天性。$B$B只有这样，我们才能避免同样的悲剧在将来再次发生。"
D.Strings[48965]="你是来观摩我教学的吗？"
D.Strings[48966]="欢迎你，旅行者。请在此稍事休息。"
D.Strings[48967]="只要煞魔还待在外面，我就不会有事。"
D.Strings[48968]="我们的战斗需要有营养的食物才能挡住敌人！$B$B快，告诉我我能给你弄点什么。"
D.Strings[48969]="你看上去需要一顿热饭热菜。$B$B要我给你弄点什么？"
D.Strings[48970]="赞美泰坦，他们回来了！"
D.Strings[48971]="倒也不是完全没料到。"
D.Strings[48972]="太好了！我们马上就开始仪式！"
D.Strings[48973]="唔！他们好像关门了。"
D.Strings[48974]="是啊，奇怪。上次这扇门可没关。"
D.Strings[48975]="仪式需要我们身上的一块碎片，并将带走我们大部分力量。我们将被大大地削弱。"
D.Strings[48976]="你们都觉得他们在隐藏着什么？"
D.Strings[48977]="我们会知道的。"
D.Strings[48978]="我可不认为酒厂会发出那种声响……"
D.Strings[48979]="英雄们，这个重担又落到你们的肩上了。"
D.Strings[48980]="嗯……伙计们……"
D.Strings[48981]="安静点，丽丽。你知道我可不喜欢在敲门的时候被人打扰。"
D.Strings[48982]="陈！那是只该死的大猢狲！"
D.Strings[48983]="来吧，猢狲！"
D.Strings[48984]="英雄们，你们有没有拿到聚焦之虹？"
D.Strings[48985]="坚持住，我会把你们从桶里弄出来。"
D.Strings[48986]="我们成功了，卡雷苟斯。"
D.Strings[48987]="坚守阵地，卫士们！别让他们通过！"
D.Strings[48988]="坚持住！又有煞魔逼近了！"
D.Strings[48989]="把他们送回荒废虚无的世界去，勇士们！"
D.Strings[48990]="如果我们现在放弃，整个青龙寺就将陷落！"
D.Strings[48991]="向前推进，卫士们！"
D.Strings[48992]="大家坚持住。我们只需要再前进一步。"
D.Strings[48993]="不要放弃希望，同胞们！"
D.Strings[48994]="明天，人们将为我们唱响赞歌，但前提是我们必须在今天取得胜利。"
D.Strings[48995]="|TInterface\\Icons\\inv_stave_2h_deathwingraiddw_d_01.blp:20|t%s落向了|cFF04FC32伊瑟拉|r的平台！"
D.Strings[48996]="风暴烈酒家人们，赶快开门吧！我带着啤酒回来啦。"
D.Strings[48997]="%s开始穿刺守护巨龙！快阻止它！"
D.Strings[48998]="我们会将守护巨龙的力量灌注到巨龙之魂中，在此期间，你们必须保护我们。"
D.Strings[48999]="安息吧，孩子。"
D.Strings[49000]="你做出的牺牲是不会被遗忘的。"
D.Strings[49001]="死亡之翼会为此付出代价的。"
D.Strings[49002]="难以置信！极少有刺客能像你这样骗过纳莉丝的护卫，还使用她的魔法来对付她。"
D.Strings[49003]="也许吧。因为这个缘故，我们还需要更多的补给……"
D.Strings[49004]="她的失败是自找的。剩下的可没那么好对付。"
D.Strings[49005]="传送到大炮需要交纳："
D.Strings[49006]="我不需要传送。"
D.Strings[49007]="永恒之眼里的聚焦之虹也许能让我们汇聚储藏在巨龙之魂里的魔法矩阵。"
D.Strings[49008]="若是你成功了，我们的工作就接近尾声了。祝好运，英雄！"
D.Strings[49009]="没必要担心，法拉德。下一个任务……和自杀也差不多了。"
D.Strings[49010]="别相信他，王子殿下，他不值得信任。"
D.Strings[49011]="守护巨龙！请尽力帮助这些英雄。"
D.Strings[49012]="为逝者复仇！继续战斗！"
D.Strings[49013]="我的女儿又跟你的学徒跑了。"
D.Strings[49014]="你必须赶快……龙眠神殿……快倒塌了……没有希望了……"
D.Strings[49015]="谢谢，姐妹们，我重焕活力了。"
D.Strings[49016]="上古之神现身了——黑暗之潮从他们撕开的裂口中涌出，直奔神殿而去。我们要为守护巨龙争取时间。"
D.Strings[49017]="在地平线的那边，两名无面者将军，佐诺兹和约萨希，指挥着一支邪恶的军团。"
D.Strings[49018]="要想活着终结这一切，我们就必须击败他们。借助我姐妹们的双翼，让她们带你们飞到尽可能近的地方！"
D.Strings[49019]="只剩下一名将军了。你们必须赶快！"
D.Strings[49020]="黑暗之潮退去了。你们果真是传说中的英雄。"
D.Strings[49021]="守护巨龙早就等着你们了。快去吧！"
D.Strings[49022]="让易默滚回朱家堡！"
D.Strings[49023]="热恋中的情侣总是要谈情说爱的嘛。他是个好小伙儿。"
D.Strings[49024]="我不要听！他是游酒家族的人，而她来自金酿家族。把我的女儿交出来，不然我就让你整整一个月都找不到活儿。"
D.Strings[49025]="干得好！我会重调魔法的涡流，并将我所有的奥术力量灌注到巨龙之魂中。"
D.Strings[49026]="我会赋予你们奥术的力量，摧毁敌人。"
D.Strings[49027]="他是不是……在解体？"
D.Strings[49028]="恩佐斯这扭曲的血肉大旗终将再次飘扬在这个世界的尸体上空，猎猎作响。数千年后，我们终于回来了。"
D.Strings[49029]="死亡之翼必胜。为了恩佐斯的荣耀！"
D.Strings[49030]="我周围的所有人都是假装喜欢我。"
D.Strings[49031]="这身铠甲对我来说是不是有点紧了？"
D.Strings[49032]="果然，我最担心的事情终究还是发生了。"
D.Strings[49033]="人们会怎么说我？"
D.Strings[49034]="总有邪恶的低语在我的脑海中盘旋。我是不是该为此担心？"
D.Strings[49035]="什么都没有改变。"
D.Strings[49036]="为了这一天……等待了那么久……"
D.Strings[49037]="为什么我要这么努力？到头来一点意义都没有……"
D.Strings[49038]="我为什么总感觉如此孤独？是因为……我孑然一身吗？"
D.Strings[49039]="数代以来，我的家族一直是翡翠林最伟大的酒仙家族之一。$b$b我们跟那个卑鄙的旅行家族游酒可不一样。他们只会酿造村野劣酒。"
D.Strings[49040]="是时候了。我将使用全部的力量来控制巨龙之魂周围所有的时光线。我们过去的一切努力绝不能白费。"
D.Strings[49041]="发动进攻，英雄们。"
D.Strings[49042]="在你面前的就是我们守护巨龙的宝箱：挑选你的奖励吧，这是你应得的。"
D.Strings[49043]="干得好。我心中的火焰将迸发出无比纯净的光芒；每一束火花都将被引导至巨龙之魂中。"
D.Strings[49044]="他已经彻底疯了！"
D.Strings[49045]="我们又近了一步。我会将神秘莫测的翡翠梦境之力注入到巨龙之魂中。"
D.Strings[49046]="如此……愤怒……我从未见过……"
D.Strings[49047]="你们的头颅将装饰恩佐斯的扭曲王座。"
D.Strings[49048]="死亡之翼正在引导最后的大灾变，连翡翠梦境都在颤抖。要想阻止他，我们必须联手进攻。"
D.Strings[49049]="你们的灵魂将成为恩佐斯口中的美餐！"
D.Strings[49050]="你们的死亡将歌颂恩佐斯无尽的荣耀。"
D.Strings[49051]="凝视恩佐斯的内心吧。"
D.Strings[49052]="恩佐斯的意志将腐蚀你。"
D.Strings[49053]="你们的苦难强化了我。"
D.Strings[49054]="谢谢你的面具，$n。请放心接受此祝福，以聊表我们的谢意。"
D.Strings[49055]="我可怜的罗。他是那么努力地去争取族长们的认可，这也是我们能够想到的唯一一个能避开家族恩怨的体面的解决办法。"
D.Strings[49056]="打得好……真像个英雄。你该到前面去找丽丽了。"
D.Strings[49057]="我觉得，这里的战斗应该都结束了。我们该出去和陈还有丽丽会合了。"
D.Strings[49058]="陈叔在前面等着呢。你去找他吧……我要戏弄一下这只不省人事的猴子。"
D.Strings[49059]="我想我们都搞定了！让我们去酿酒厂的后门和那两个呆子会合吧。"
D.Strings[49060]="你们的痛苦支撑着我。"
D.Strings[49061]="你们的恐惧驱使着我。"
D.Strings[49062]="我们的数量无穷无尽，我们的力量超乎想象！所有敢于和灭世者作对的人，都将被千刀万剐！"
D.Strings[49063]="古神之血将淹没你们！淹没你们所有人！"
D.Strings[49064]="我要把衣服里的酒水拧掉一些。你们继续前进，去找泥盏。"
D.Strings[49065]="哦，死亡之翼！您忠实的仆人辜负了您！"
D.Strings[49066]="你的灵魂将遭受无尽的折磨！"
D.Strings[49067]="赞美伟大的灭世者，死亡之翼！"
D.Strings[49068]="我想我们今天造成的破坏已经够多了。我们去酒厂后门跟他们两人会合吧。"
D.Strings[49069]="我们冲出最黑暗的深渊，将要夺回这个世界！"
D.Strings[49070]="见证我们从破碎的大地下涌出的那一刻吧！"
D.Strings[49071]="让黑暗吞噬一切！"
D.Strings[49072]="让腐蚀吞噬你！"
D.Strings[49073]="他们……他们同意了？！天呐！真是太感谢你了！只要有了他们的祝福，我们就是这世界上最最幸福的熊猫人！"
D.Strings[49074]="谢谢你，英雄！你给了我们一份极其贵重的礼物！"
D.Strings[49075]="小心点！他们或许是死了，可这些族长还是很危险的。"
D.Strings[49076]="我从煞魔身上了解到的一点就是，他们知道如何利用我们自身的弱点。"
D.Strings[49077]="煞魔在有一点上是对的。$B$B我们最大的敌人通常就是我们自身。$B$B我只希望我自己不会是个难缠的对手。"
D.Strings[49078]="你的眼睛没有欺骗你。奸诈的红龙军团试图杀掉我。我希望你能看清他们的真面目。"
D.Strings[49079]="我闻到了什么味道……"
D.Strings[49080]="你有什么事吗，英雄？"
D.Strings[49081]="你是青铜龙军团的一员，你知道接下来会发生什么！你就不能让我们直接开始实际行动吗？"
D.Strings[49082]="犯下了此等罪行，你休想得到宽恕。"
D.Strings[49083]="如果你们想扮小丑，就要扮得像一点儿。"
D.Strings[49084]="如果你可以活着完成任务……我会付给你等值的报酬。"
D.Strings[49085]="没错，凡人！你寻找的东西如今不再沉睡在蛋壳里。我就活生生地站在这里。"
D.Strings[49086]="我不是什么红龙伟大事迹的活证，我可不会回去。"
D.Strings[49087]="别这么惊讶！我们龙族即使在蛋壳里也是有意识的。在成长过程中，我听到的全是诡计和阴谋。我生来就是个囚徒。"
D.Strings[49088]="可我是族群的最后一员了！凡人。作为仅存的一条没有受到父亲堕落污染的黑龙，我要保持我的自由。"
D.Strings[49089]="但是，你躲开了我所有的守卫，像个幽灵一样的潜入了这里。这让我觉得……你还有点用处。我们聊聊吧。"
D.Strings[49090]="你不认得你以前的囚徒了吗？"
D.Strings[49091]="不。我想让他给红龙军团传句话回去。"
D.Strings[49092]="告诉他们，我是自由的。我没有受到父亲疯狂的影响，也不会成为红龙的囚徒。别来打扰我：这是我第一次也是唯一的警告。"
D.Strings[49093]="死亡之翼的爪牙应该会害怕我。让他滚出这里。"
D.Strings[49094]="嗯，法拉德？"
D.Strings[49095]="打断他的腿。"
D.Strings[49096]="好吧，我的新朋友。我们还有不少事要聊。"
D.Strings[49097]="殿下，我们在庄园附近的洞穴里抓住了这头鬼鬼祟祟的野兽。"
D.Strings[49098]="我们要处决他吗，王子殿下？"
D.Strings[49099]="殿下？"
D.Strings[49100]="别放弃，雷鸟！回来找我！"
D.Strings[49101]="我能感觉到……笼罩大地的阴影消失了。死了！我的父亲死了！"
D.Strings[49102]="勇士，请收下这件奖励。但我们还要对付最后一条龙。"
D.Strings[49103]="法拉德！我说的就是你。你就是最后那条黑龙。比其他任何一条龙藏得都要深。"
D.Strings[49104]="你的武器很特别……很强大。"
D.Strings[49105]="是的。你在我还是一只龙蛋的时候救下了我，我欠你一条命。"
D.Strings[49106]="但你是一条黑龙。我所有兄弟姐妹所受到的腐蚀也影响着你。"
D.Strings[49107]="你敢否认吗？那些黑暗的幻象？那些你脑中的黑暗之声？"
D.Strings[49108]="他们在和你说什么，法拉德？你的黑暗主人在低语着什么？"
D.Strings[49109]="我绝不会被控制！红龙军团在拿我的蛋做实验时根本不知道他们自己释放出了什么。"
D.Strings[49110]="英雄——攻击！使用你新获得的力量去消灭他。"
D.Strings[49111]="都结束了，朋友。据我所知，我是这个世界上仅存的黑龙了。"
D.Strings[49112]="凡人的新时代开始了，你这样的英雄是这个时代的先锋。"
D.Strings[49113]="我必须离开了——暂时消失。"
D.Strings[49114]="也许我们有朝一日会再次相遇。但愿届时我们还能站在同一阵线……"
D.Strings[49115]="你看来已经准备好了。"
D.Strings[49116]="我的王子，我们应该离开这儿，他们也许会回来继续攻击你。"
D.Strings[49117]="殿下。我从来没有向您隐瞒过我的身份。"
D.Strings[49118]="这——不是真的！"
D.Strings[49119]="不，不！我能控制那些声音。他们只是来帮我的。"
D.Strings[49120]="杀……他们要我现在就杀掉你……哦，你为什么要故意激怒他们？"
D.Strings[49121]="事实证明你真是太难控制了！"
D.Strings[49122]="|TInterface\\Icons\\inv_weapon_shortblade_45.blp:20|t%s开始施放|cFF9900CC|Hspell:109887|h[奥能灌注武器]|h|r！躲开她的攻击！"
D.Strings[49123]="|TInterface\\Icons\\ability_warrior_riposte:20|t%s开始施放|cFF9900CC|Hspell:109893|h[奥能灌注护甲]|h|r！快打破她的护甲！"
D.Strings[49124]="|TInterface\\Icons\\spell_arcane_arcaneresilience.blp:20|t%s开始施放|cFFFF0000|Hspell:109807|h[奥术毁灭]|h|r！快激活柱子来阻止她！"
D.Strings[49125]="你准备好了吗？我准备好了。我很想把那个畜生打得落花流水！$b$b只是……我并非好斗的人，我很容易受惊。你是这里唯一的$c。你会……你会保护我的，对吗？"
D.Strings[49126]="很好！让我们痛扁这个水鬼吧！"
D.Strings[49127]="这家伙的块头比我想象得要大一点。$b$b你觉得这是因为啤酒喝多了？我很清楚喝太多啤酒会让你长胖，就像陈叔那样，但是我不认为喝酒能让你长高。$b$b总之，我觉得我一个人恐怕搞不定他。"
D.Strings[49128]="很好！也许这一次，我们可以成为扔木桶的一方了！"
D.Strings[49129]="这座酒厂里到底出什么事了？这里没人打理了吗？酿酒师们都去哪了？$b$b我的家人呢……？$b$b他们一定去了别的什么地方。如果他们在这儿，一定会好好收拾这里的！看起来现在只能由我俩来做了，$n。你准备好了吗？"
D.Strings[49130]="风暴烈酒！"
D.Strings[49131]="不要停。$B$B你还有时间！"
D.Strings[49132]="冷静点，泥盏。出发。"
D.Strings[49133]="我会帮忙的。"
D.Strings[49134]="我们开始吧，陈。"
D.Strings[49135]="请离开游戏场地。"
D.Strings[49136]="阻击他们！保护弓箭手！"
D.Strings[49137]="由于我失去了力量，巨龙之魂已经回到了原本的时空。"
D.Strings[49138]="一个刺客！是那条小龙崽子派你来追杀我的吗？来吧，潜行者。让我们一决高下。"
D.Strings[49139]="我自己也有一些小秘密，潜行者。"
D.Strings[49140]="我……我需要更多的时间！"
D.Strings[49141]="这不是我要的结局。我还没到谢幕的时候呢。我才是最后的幸存者。"
D.Strings[49142]="你不过是个抱残守缺的可怜虫……你的末日……很快就会降临……"
D.Strings[49143]="我今晚真是鸿运当头！"
D.Strings[49144]="肯肯这辈子见过几个熊猫人。他会告诉你——他们一点也不悲伤。$B$B现在，看看这地方！到处都是满脸哀苦、无精打采的熊猫人。$B$B欢歌热舞去哪儿了？堆积如山的美食又去哪儿了？$B$B干杯狂饮的场面又去哪儿了啊，伙计？！"
D.Strings[49145]="双倍加注！"
D.Strings[49146]="两点……"
D.Strings[49147]="你应该帮帮明。$B$B肯肯在想办法鼓舞这些超级悲伤的家伙。"
D.Strings[49148]="看着这些熊猫人如此悲伤，肯肯也快变成悲伤的猢狲了。"
D.Strings[49149]="懒狗！"
D.Strings[49150]="抓紧点！"
D.Strings[49151]="论起当守卫，连猫都比你们称职！"
D.Strings[49152]="你的皮很合适做地毯！"
D.Strings[49153]="你已经把城里的每个角落都嗅遍了！"
D.Strings[49154]="随时待命……"
D.Strings[49155]="随便选个地方好了！"
D.Strings[49156]="追踪他们的气味！"
D.Strings[49157]="奥能存储单元开始过载了。退后！"
D.Strings[49158]="钟的力量恢复了！快敲响它，以削弱附近的敌人！"
D.Strings[49159]="%s强化了$n！"
D.Strings[49160]="你好，旅行者。没想到在这片海滩上还能看到一个友善的部落人士。"
D.Strings[49161]="我感受到了圣光的召唤，就在遥远的北方。但这个地方……$b$b数代以来都未曾听说过圣光的存在。"
D.Strings[49162]="我们追随着莱莎对光明的预见来到此地，如同飞蛾扑火。"
D.Strings[49163]="我们的南面是联盟，东面和西面有魔古族，北面是悬崖。这还真是四面楚歌啊。"
D.Strings[49164]="相比于这里可怕的湿热，我比较喜欢诺森德刺骨的寒风。这里好像连树木都想要闷死我们。"
D.Strings[49165]="德兹科是一位伟大的酋长，是他把我们带到了这里，但我开始有点怀疑我们能否在这片土地上存活下来。"
D.Strings[49166]="这是一片神秘的土地，如此美丽，却又如此致命。"
D.Strings[49167]="我觉得矮树丛中有东西在盯着我们……"
D.Strings[49168]="到那时，寻求这世上所有的光明与奇迹，并奋战到底。"
D.Strings[49169]="我们将同生共死，潘达利亚的所有生灵与我们同在。"
D.Strings[49170]="欢迎来到丛林，$r！奈辛瓦里派我来收集附近野生动物的情报。$b$b你愿意帮我一把吗？"
D.Strings[49171]="无……无缘无故地，魔古族突然发起了攻击……一切都变黑了……"
D.Strings[49172]="这里有部落？！"
D.Strings[49173]="决不容许部落玷污这片土地！"
D.Strings[49174]="谢谢帮忙，朋友。如果你在西边见到奈辛瓦里和他儿子，就告诉他们我们杀了多少动物。他们就喜欢听这个。"
D.Strings[49175]="暴风城的居民们，欢呼吧！死亡之翼已经被消灭了！灾难结束了！一群勇敢的英雄们冒死突袭灭世者，为守护巨龙们争取到了对死亡之翼发起致命一击的机会，虽然这也让他们牺牲了所有的力量。现在，死亡之翼的最后一段残骸就被保存在暴风城，成为了未来希望之光的象征！"
D.Strings[49176]="奥格瑞玛的居民们，欢呼吧！死亡之翼已经被消灭了！灾难结束了！一群勇敢的英雄们冒死突袭灭世者，为守护巨龙们争取到了对死亡之翼发起致命一击的机会，虽然这也让他们牺牲了所有的力量。现在，死亡之翼的最后一段残骸就被保存在奥格瑞玛，成为了未来希望之光的象征！"
D.Strings[49177]="都阳王朝是以凶残著称的。多加小心。"
D.Strings[49178]="我感到元素正在苏醒，欢呼……这场灾难……结束了。"
D.Strings[49179]="如果你希望如此，我可以向你展示死亡之翼在大漩涡所造成破坏的后果。"
D.Strings[49180]="请让我看吧，克罗米。"
D.Strings[49181]="我不能继续待在城里了！我得打上一场！"
D.Strings[49182]="我会用自己的双眼注视这片土地。"
D.Strings[49183]="观察我的动作会令你受益匪浅。"
D.Strings[49184]="来吧，我的学徒！你是我的学徒，对吧……？"
D.Strings[49185]="让我看看，巨龙。"
D.Strings[49186]="我会在营地与你会面。"
D.Strings[49187]="这不可能，真的结束了吗？我肯定又做梦了。"
D.Strings[49188]="我们合力完成了一件不可能的任务。"
D.Strings[49189]="现在，你们必须开创一个新的时代……一个属于凡人的时代。"
D.Strings[49190]="加入我吧！"
D.Strings[49191]="古老的传说讲述了都阳王朝和他们的青春之池。让我们看看传说究竟是不是真的。"
D.Strings[49192]="试图将纳乐从囚牢中解救出来。"
D.Strings[49193]="这道暗影之墙能挡住恶魔，直到我们安全通过。\n$b等你们和其他精灵通过之后，我也会跟上的。"
D.Strings[49194]="站住，乞丐！这片水域属于雷电之王。你在这里是不受欢迎的。"
D.Strings[49195]="守卫！消灭这些闯入者。"
D.Strings[49196]="嘘！它们不知道我藏在这里。"
D.Strings[49197]="我只是一个熊猫人，可我必须留在这里，帮助翔龙。"
D.Strings[49198]="我们务必要保持安静。否则那些滑鳞蜥蜴人会毫不犹豫地把我们当晚餐吃了。"
D.Strings[49199]="我已经十六天没洗过澡了。这样就不太容易被发现。"
D.Strings[49200]="我已经在野外收集到那么多有关翔龙的数据了！"
D.Strings[49201]="这里是它们天然的繁殖地，我们可得小心点儿。"
D.Strings[49202]="那个小精灵在帮我们！在他附近战斗，英雄！"
D.Strings[49203]="你去过青龙寺吗？我们的许多弟子都会被派去那里潜心进修，由玉珑亲自督导。"
D.Strings[49204]="不幸的是，我们培育翔龙的努力失败了。我们现在只能仔细挑选一些野生翔龙蛋回去自己饲养了。"
D.Strings[49205]="我要挑战奥卓克希昂和他的爪牙，送我去龙眠神殿顶层。"
D.Strings[49206]="看哪。那个小家伙给你留下了一些纯净之水。"
D.Strings[49207]="兄弟，我们必须留心保护自己。联盟正从东面步步逼近。"
D.Strings[49208]="你是部落的一份子。请牢记你的责任和誓言。酋长有令，我们必须杀死这些暗夜精灵。"
D.Strings[49209]="你不能再以莱莎的痛苦为借口了。迟早，你要作为一名烈日行者挺身而出，带领我们对抗部落的敌人。"
D.Strings[49210]="我必须待在莱莎身边，直到她生下孩子。死亡，总要排在生命之后。"
D.Strings[49211]="贝恩的命令是保护我们在这片土地上的新据点，并调查我们的烈日行者所感受到的圣光。联盟方面不足为虑。"
D.Strings[49212]="如果放任仇恨滋生，它会遮蔽你的双眼，兄弟。"
D.Strings[49213]="魔古族的首领有着特殊的领导能力。你要谨慎从事。"
D.Strings[49214]="我会很乐意在这里住下的。风景秀丽，啤酒充足……还有很多架可打。"
D.Strings[49215]="<摩拳擦掌并点头。>"
D.Strings[49216]="你准备好打架了吗，$n？"
D.Strings[49217]="我们必须在煞再次攻击前，重整旗鼓！"
D.Strings[49218]="焰心女祭司背叛了我们！寺院要沦陷了！"
D.Strings[49219]="煞魔太多了，能逃就赶快逃吧！"
D.Strings[49220]="嗯……他朝我冲过来了。"
D.Strings[49221]="明，你知道在这附近哪里有盐吗？"
D.Strings[49222]="我该跑了么？"
D.Strings[49223]="我要跑了。"
D.Strings[49224]="谢谢你把易默带回来。$B$B我现在明白了，我们再也不能忽视自己在这里的职责。"
D.Strings[49225]="通常我们手上会有很多，但眼下几乎所有补给品都被雨水冲毁了。$B$B不过，我相信那些干涸池塘里的生物是雨水和泥土盐分的混合物。你也许能从它们身上找到需要的东西。"
D.Strings[49226]="不！！！这怎么可能？"
D.Strings[49227]="啊，这个蛋很不错。嗯，这个应该可以。这个不行，太小了。这个应该能通过检查……"
D.Strings[49228]="尤噶在哪？"
D.Strings[49229]="搞什么香蕉！"
D.Strings[49230]="尤噶看不见啦！"
D.Strings[49231]="我在哪？"
D.Strings[49232]="该死的桶！"
D.Strings[49233]="尝尝我的香蕉！"
D.Strings[49234]="人人都得吃香蕉！"
D.Strings[49235]="尤噶不喜欢被酒桶套住脑袋！"
D.Strings[49236]="尤噶对你感到很生气！"
D.Strings[49237]="尤噶在扔水果！因为他快要疯了！"
D.Strings[49238]="你们扔酒桶？尤噶扔香蕉！味道更好！"
D.Strings[49239]="现在，尤噶追熊猫人女孩！"
D.Strings[49240]="熊猫人女孩，怎么跑这么快？"
D.Strings[49241]="狡猾的熊猫人女孩！回到尤噶身边！"
D.Strings[49242]="尤噶喜欢看到可爱的熊猫人女孩！"
D.Strings[49243]="尤噶只是想抱抱熊猫人女孩。"
D.Strings[49244]="哦，熊猫人女孩……尤噶想喂你吃香蕉！"
D.Strings[49245]="呃！"
D.Strings[49246]="太恶心了！"
D.Strings[49247]="尤噶|cFFFF0000|Hspell:110182|h[滑溜溜]|h|r的！将一只木桶踢向他，让他站着别动！"
D.Strings[49248]="等等，关于我的蛋，我改变主意了。"
D.Strings[49249]="我很抱歉。我保证会下次更加小心的。"
D.Strings[49250]="我想要蓝色的翔龙蛋。"
D.Strings[49251]="我想要绿色的翔龙蛋。"
D.Strings[49252]="我想要黄色的翔龙蛋。"
D.Strings[49253]="你们的生命毫无意义。"
D.Strings[49254]="是的，我知道你的蛋丢了。$B$B你问我怎么知道的？因为你的蛋就在我手上呢。$B$B我会把这个蛋再次交给你。但是拜托，我跟你说，这回麻烦你认真仔细地把这个蛋照顾好。"
D.Strings[49255]="放弃希望吧。"
D.Strings[49256]="我们的军队将要陷落。"
D.Strings[49257]="我们无力保卫潘达利亚。"
D.Strings[49258]="什么？你最终还是改变主意了？我告诉过你叫你仔细挑选！$B$B算了算了，这次我就原谅你了。告诉我，你到底想要哪个蛋？"
D.Strings[49259]="|Tinterface\\icons\\spell_fire_ragnaros_lavabolt.blp:0|t天火号受到结构性损害，突然引发了一次|cFFFF0000|Hspell:110095|h[甲板起火]|h|r！"
D.Strings[49260]="我……我打不了他！泡泡真是太厚了！"
D.Strings[49261]="我……我没法打穿这该死的泡泡！"
D.Strings[49262]="我们把这些小泡泡踢回给他！"
D.Strings[49263]="我们来踢小泡泡！朝他的脸踢！"
D.Strings[49264]="很好！我要踢爆你的屁股！"
D.Strings[49265]="我要把你酿成烈酒！"
D.Strings[49266]="当心！泥盏来啦！"
D.Strings[49267]="重新投入战斗！"
D.Strings[49268]="碾过小泡泡以削弱涡流的|cFFFF0000|Hspell:110189|h[水体护盾]|h|r！"
D.Strings[49269]="点击涡流被削弱的|cFFFF0000|Hspell:110198|h[水体护盾]|h|r来戳破它！"
D.Strings[49270]="嘿嘿嘿嘿！"
D.Strings[49271]="嚯嚯嚯！"
D.Strings[49272]="咳咳咳咳咳！"
D.Strings[49273]="蜥蜴人不遗余力地大肆抢劫，加上我们的戒卫疏于防范，他们便发动夜袭，掠夺我们的补给品。$B$B蜥蜴人会把所有能带走的东西通通带走，回去之后再逐一筛选。$B$B手工补给品和颜料只是被他们盯上的部分物资罢了。"
D.Strings[49274]="这个请求或许很奇怪，不过……你有墨水或颜料之类的东西吗？"
D.Strings[49275]="|Tinterface\\icons\\spell_fire_twilightrainoffire.blp:0|t%s向天火号发动了一次|cFF9900CC|Hspell:110153|h[舷侧攻击]|h|r！"
D.Strings[49276]="几个世纪以前，这片土地还是荒野。前往海岸是危险之旅，在神鹤之巢卡桑琅附近有野兽出没，许多熊猫人都因此下落不明。$B$B这种情况一直持续着，直到有一天，大名鼎鼎的猎手朱·长眉来到了这里。厌倦了生活的无谓得失，朱带着妻子林和儿子波——他的妻儿也都是强大的猎手，历尽艰辛，在这片荒野的一隅安居下来。$B$B朱不想彻底定居荒野，尽管许多人求他这么做。他的智慧让他明白，他们同样肩负着另一项使命——保护神鹤。$B$B于是就有了朱家界，以及用作守备之用的朱家堡。"
D.Strings[49277]="我们会让朱家界重获安宁。朱的遗产不会就此消失。"
D.Strings[49278]="请你告诉我与朱的遗产有关的事吧。"
D.Strings[49279]="长眉？难道说，易默是朱的后人？！"
D.Strings[49280]="没错。他是长眉家族最后的传人。$B$B可惜的是，在他身上似乎看不到与老朱相同的气质。我想你肯定已经注意到了，他情绪非常……多变。$B$B请不要把这看作是软弱的象征——他的姓氏和随之而来的责任，压得他喘不过气来。我知道易默是为了朱家界好。$B$B总有一天，他会明白，有时我们必须为自己所爱的一切战斗。"
D.Strings[49281]="等我们摆脱了这些水灵，就可以继续了。"
D.Strings[49282]="那些水灵会自己跳进锅里，这真是太好了。"
D.Strings[49283]="%s吸收了格里昂纳的生命力，重新焕发出活力并开始攻击！"
D.Strings[49284]="（你必须在英雄难度下的所有前置战斗中取胜，才能开启本场英雄难度的战斗。）"
D.Strings[49285]="我叫陈，这是我的侄女儿，丽丽。"
D.Strings[49286]="我们能在你的农舍歇歇脚吗？我们身上没有多少值钱的东西，但我很乐意和你分享我自酿的啤酒，很有名的哦。"
D.Strings[49287]="你们好，陈，丽丽。欢迎你们，但我不需要你的啤酒。"
D.Strings[49288]="谢谢！我们不会待得太久。"
D.Strings[49289]="有意思，他竟然不喜欢啤酒？入乡随俗吧。"
D.Strings[49290]="不会吧，叔叔？我们这就要停下了？我们才走了，大概，十尺啊。"
D.Strings[49291]="好了，好了！别再刨根问底了！"
D.Strings[49292]="嗯哼。"
D.Strings[49293]="一般来说，新手会有较多的准备时间。"
D.Strings[49294]="可惜，你的雏龙不想再等下去了！"
D.Strings[49295]="希望你多加努力，$n。只有极少数人才享有驯养云端翔龙的殊荣。"
D.Strings[49296]="我回房间了。尽管告诉我姑妈，你是怎么“英勇无畏”地把我给救回来的。"
D.Strings[49297]="呃……我这是在哪儿？"
D.Strings[49298]="好吧！回半山村找陈叔。看谁先到，$n！"
D.Strings[49299]="离那东西远点，杂种！"
D.Strings[49300]="你确定我们没走错吧，邻居？"
D.Strings[49301]="你不会把我带到那悬崖下面去吧？"
D.Strings[49302]="我原以为自己力气不小……直到我看到你背的那些玩意儿。"
D.Strings[49303]="我觉得我们快到了。"
D.Strings[49304]="现在该去喝点水了。"
D.Strings[49305]="唔……唔。"
D.Strings[49306]="我还扛着这些桶呢。"
D.Strings[49307]="我都等不及想试试陈构想中的啤酒啦。$b$b那家伙可是说了大话的。"
D.Strings[49308]="我们回半山吧，泥盏。"
D.Strings[49309]="你不会再叫我到什么沟里或是野兽嘴里去吧？可千万别。"
D.Strings[49310]="等等……你这是要去哪？"
D.Strings[49311]="早就说了我很壮。一个桶都没丢。"
D.Strings[49312]="我真不敢相信。他们给它喂了多少东西啊？"
D.Strings[49313]="你漏掉了一些。"
D.Strings[49314]="我知道，我知道。"
D.Strings[49315]="集中火力，攻击同一个软泥怪！"
D.Strings[49316]="别低估我的父亲。即使你摧毁了他的身体，他那颗充满疯狂与愤怒的心仍然能毁掉你。"
D.Strings[49317]="除非将他轰至灰飞烟灭，否则都不能算是击败了他。"
D.Strings[49318]="我真希望能帮上忙……但父亲是我唯一惧怕的一条龙。"
D.Strings[49319]="祝你好运，潜行者。无论结局如何，你都是一个真正的勇士。"
D.Strings[49320]="你发动了突然袭击。不过我还是要向你致敬，我甚至都不知道卡拉赞在哪儿。你是怎么到那的？"
D.Strings[49321]="快挡住|cFF9900CC|Hspell:107439|h[暮光弹幕]|h|r，以防天火号受到损伤！"
D.Strings[49322]="你为什么不去其它地方找活儿干呢？"
D.Strings[49323]="|c0087CEFA|Hspell:105845|h[核能冲击]|h|r的爆发距离太远，不足以掀起装甲板！"
D.Strings[49324]="这可不是我应得的待遇！我是一位演员，一位表演者——才不是什么普通的清洁工！看在圣光的份上——我可是在卡拉赞的歌剧院里表演过的！"
D.Strings[49325]="%s未能吸收到足够的堕落熔岩残渣来触发核能冲击。"
D.Strings[49326]="练习，练习，再练习！"
D.Strings[49327]="瞧瞧我现在的模样。跟在这只蠢野兽的屁股后面打扫个没完。"
D.Strings[49328]="什么，还要放弃演艺事业？！"
D.Strings[49329]="快使用英勇意志技能来躲避暮光审判和黯淡之光！"
D.Strings[49330]="一切似乎都忽然……变亮了。"
D.Strings[49331]="我感到……很高兴！！"
D.Strings[49332]="快摧毁法力虚空来补充流失法力！"
D.Strings[49333]="噢，我的头好疼……"
D.Strings[49334]="我在这儿干什么？我还有工作要做！"
D.Strings[49335]="你是来打我的孩子的？还是来偷我的财宝的？"
D.Strings[49336]="地栗的惊喜来了！"
D.Strings[49337]="你要倒霉了！"
D.Strings[49338]="我错过什么了吗？"
D.Strings[49339]="看起来我来的正是时候！"
D.Strings[49340]="如果你与宝珠之间有联结，就快跑到那边去吧！"
D.Strings[49341]="$n！快躲开地面上有黑色污泥的地方！"
D.Strings[49342]="$n，你被共鸣水晶杀死了。靠近共鸣水晶可降低伤害。"
D.Strings[49343]="$n，你被哈格拉的寒冰之潮杀死了。$B请提前移动以躲开寒冰之潮！"
D.Strings[49344]="啊噢……我的战甲……正在被削弱……"
D.Strings[49345]="灭世者又夺走了一条灵魂……"
D.Strings[49346]="$n，今天我们要庆祝你顺利毕业了。你已经学习并掌握了天禅院的所有智慧与奥妙。"
D.Strings[49347]="欢迎回来，$n！你的训练怎么样啦？$b$b我们的弟子都非常想念你……尽管我不得不说，他们对不用再和你过招这一点还是很高兴的。"
D.Strings[49348]="没有希望，没有未来。这是所有生命的末日。"
D.Strings[49349]="和你一样，整个艾泽拉斯都将燃烧。"
D.Strings[49350]="这个世界即将步你后尘。"
D.Strings[49351]="要与翔龙合为一体，$n。与它感同身受，加强你们之间的联系。"
D.Strings[49352]="你要知道，猢狲也会学习武术。$b$b肯肯比其他所有人加起来都厉害，尤其是那个笨蛋锦鱼人聪明的阿西约。"
D.Strings[49353]="我们刚从翡翠林中的天禅院毕业。你以前去过那儿吗？$b$b我们不再是弟子了。我们正在执行第一个任务——找到隐秘大师。"
D.Strings[49354]="$n！是我！还记得我吗？天禅院的！$b$b虽然花了我不少时间，但我终于毕业了！晓也毕业了，还有……嗯，这里的所有人。$b$b我们不再是弟子了。我们正在执行第一个任务——找到隐秘大师。"
D.Strings[49355]="乞丐和逆贼，我们要把你和这群熊猫人盟友烧成灰烬。"
D.Strings[49356]="村里的长者曾教导我，每条河流里都流淌着智慧，每个池塘中汇聚着知识。我等不及想要知道这里的水能告诉我什么了。$b$b村里的长者还教导我，绝不要相信猢狲。$b$b<阿西约警惕地瞥了一眼肯肯。>"
D.Strings[49357]="终于有机会用上我们一直训练的技巧了。谁会知道我们会在四风谷中经历什么样的冒险呢？"
D.Strings[49358]="我的翔龙走失了！你能帮我重新建立灵魂链接吗？"
D.Strings[49359]="好了，现在我们得找人来试试这个……"
D.Strings[49360]="你！快过来，闲人。肯肯给你准备了好东西！"
D.Strings[49361]="谁，我吗？"
D.Strings[49362]="没问题，反正事情也不会变得更糟……"
D.Strings[49363]="%s的五脏六腑都剧烈地搅在了一起。"
D.Strings[49364]="你确认想要支付？"
D.Strings[49365]="切森倒地死去，身上遍布着物理和魔法攻击造成的伤口。"
D.Strings[49366]="噢……呃……你对我做了什么？！"
D.Strings[49367]="过来，把这个喝下去。"
D.Strings[49368]="哈哈哈！起作用了！肯肯知道一定有用！你现在感觉好些了吗？"
D.Strings[49369]="呃……啊……"
D.Strings[49370]="快一点，你们这些笨蛋。我们急需这些神器，否则你们就等着挨鞭子吧。"
D.Strings[49371]="不管是谁，只要戴上这样的面具，都再也悲伤不起来了！现在，我们该找谁来试验一下？"
D.Strings[49372]="好极了！过来，伙计。上次真是不好意思！把这个戴上吧。"
D.Strings[49373]="呃……那玩意是什么？就像是喝了馊茶水。"
D.Strings[49374]="%s深深叹了一口气。"
D.Strings[49375]="好吧……不管怎样。给我吧。"
D.Strings[49376]="我……我感到……很快乐！"
D.Strings[49377]="究竟是怎么回事？！"
D.Strings[49378]="噢，是猢狲！快把它弄走！肯肯那么聪明，可不能英年早逝！"
D.Strings[49379]="它……它走了吗？"
D.Strings[49380]="很好……无畏者……听起来不错。"
D.Strings[49381]="不，我们被骗了！"
D.Strings[49382]="我们上当了！"
D.Strings[49383]="我糊涂了！"
D.Strings[49384]="快跑！快跑！"
D.Strings[49385]="糟透了！"
D.Strings[49386]="警报！假胡萝卜！警报！假胡萝卜！"
D.Strings[49387]="后退！我们都不知道它会做什么！"
D.Strings[49388]="留意联盟在空中的眼线。我会在雷霆裂口等你回来。地狱咆哮之眼会注视着你。"
D.Strings[49389]="丛林中充满了异常的绝望感。"
D.Strings[49390]="土地中的悲伤正在侵蚀圣光赐予我的天赋。$b$b我的妻子，她正备受煎熬，可我完全无法帮助她。"
D.Strings[49391]="你的雏龙在追着球跑！"
D.Strings[49392]="你的雏龙想要抓住这只球！"
D.Strings[49393]="别担心，你的幼龙已经接住了！"
D.Strings[49394]="跪下吧，乞丐！"
D.Strings[49395]="我们会再次崛起，你们这些家伙都将成为奴隶！"
D.Strings[49396]="你们阻止不了雷电之王的回归！"
D.Strings[49397]="为了雷电之王！"
D.Strings[49398]="移开你的视线，乡巴佬！"
D.Strings[49399]="你们生来就是做奴隶的料。"
D.Strings[49400]="屈服于我们的力量！"
D.Strings[49401]="面对棘杖的愤怒吧！"
D.Strings[49402]="我想我打得太重了，连他的祖宗都感觉到了。"
D.Strings[49403]="奈辛瓦里狩猎队营地的其他人正在四风谷的西边。倘若你正向西行，你就该加入我们。狩猎愉快！"
D.Strings[49404]="我是奈辛瓦里狩猎队的成员。我们乘坐热气球穿过迷雾的时候偶然发现了这片大陆。$b$b奈辛瓦里和他的儿子想要去北边狩猎一些有蹄类动物。$b$b我决定抢先一步，去丛林里探寻真正的野兽。$b$b坐上火箭降落之后，我就发现自己身陷老虎堆了。"
D.Strings[49405]="一个$c？在这儿？而且还是个部落的人。$b$b如果你愿意帮忙，你的能力会派上很大用场。$b$b我们追随幻象和梦境而来，可到头来发现等着我们的却是个梦靥。"
D.Strings[49406]="怎么……到处都是该死的煞！我们得先解决他们！"
D.Strings[49407]="好了，没时间了。易默需要帮助！我们得给他找个面具！"
D.Strings[49408]="父亲和我正在进行一次真正的远征。这是一片陌生又新奇的土地，每个转角处都危机四伏，每个洞穴里都潜伏着怪物，与这片土地同样古老的野兽毫无畏惧地恣意生活着。$b$b狩猎的季节到了！"
D.Strings[49409]="|cFFFF0000|Hspell:106794|h[碎屑]|h|r杀死了你！使用|cFF04FC32|Hspell:106466|h[梦境]|h|r来避免受到伤害。"
D.Strings[49410]="|cFFFF0000|Hspell:105723|h[源质箭]|h|r杀死了你。远离源质箭落地的区域以降低伤害。"
D.Strings[49411]="一切都完了！放弃抵抗，向你的绝望屈服吧！"
D.Strings[49412]="你的翔龙马上就到了，祝你好运！"
D.Strings[49413]="风刃教头，你能再帮我召唤一次翔龙吗？"
D.Strings[49414]="你的翔龙已经到了，准备好后就骑上去吧。"
D.Strings[49415]="想要成为一个翔龙大师，道路是异常艰辛的。你准备好接受挑战了吗？"
D.Strings[49416]="想要晋升为翔龙骑士，就需要付出极大的牺牲。我祝你好运。"
D.Strings[49417]="萨尔被杀死了！攻击腐蚀软泥怪以使他避免受到伤害。"
D.Strings[49418]="要是你全身上下只围着一根腰带，手里拿着一把猎刀，单枪匹马地跟雪人单挑，那你也能为自己赢得“幸运”的称号。"
D.Strings[49419]="易默现在没事了，我们得先解决这些麻烦！"
D.Strings[49420]="$G他:她;醒过来了！"
D.Strings[49421]="我们骑士团的学员们会在名为“飞行竞技赛”的比赛中一较高下。"
D.Strings[49422]="我会将比赛的规则传授给你。跟我来！"
D.Strings[49423]="好吧，让我们看看这古老的仪式能不能起作用。"
D.Strings[49424]="你等着瞧吧，爸爸。我会逮个大的回来。"
D.Strings[49425]="第一步：跳舞。"
D.Strings[49426]="第二步：说出下面这句话——“痛苦之水，听我召唤，现身吧，托加尔之怨！”"
D.Strings[49427]="主人在召唤。"
D.Strings[49428]="噢，你现在是要回霍克噗克去吗？"
D.Strings[49429]="儿子！不——！"
D.Strings[49430]="来吧！我们得救救我的孩子！"
D.Strings[49431]="我会在练习过程中加快速度，试着跟上我。"
D.Strings[49432]="如果你离开太远，我会向你发出警告。要是你还不回头，我就会立即判你不及格。"
D.Strings[49433]="我会用这根绳索来引导你。如果你离我太远，绳索就会断掉，而我也只能重新开始训练了。"
D.Strings[49434]="你看见我们头顶上方的那一串三角旗了么？我们用这些旗帜标出了赛道。要是你迷了路，可以根据这些旗帜找到方向。"
D.Strings[49435]="在你通过这些考验后，你和你的翔龙之间的羁绊将会变得越来越稳固。"
D.Strings[49436]="跟紧我，$n。"
D.Strings[49437]="当你以后独当一面时，你的敌人可不会像我这般客气。"
D.Strings[49438]="我们就快完成了，坚持到底！"
D.Strings[49439]="你落后太多了！"
D.Strings[49440]="你得跟上我，$n。要是离得太远，这场练习你就失败了。"
D.Strings[49441]="等你准备好再试一遍的时候，来找我谈谈。"
D.Strings[49442]="你必须飞过所有10个检查点，才能结束比赛。"
D.Strings[49443]="在真正的比赛中，你必须飞过每个方格旗的检查点，才能得分。"
D.Strings[49444]="你离得太远啦！快跟紧你的教头！"
D.Strings[49445]="噢……什么……谁？我是怎么到这儿来的？"
D.Strings[49446]="对不起，我把一切都搞砸了。"
D.Strings[49447]="我爱你，爸爸。"
D.Strings[49448]="儿子！儿子！打起精神来！"
D.Strings[49449]="加油，小子，你比这家伙强大得多。"
D.Strings[49450]="主人来了。"
D.Strings[49451]="<试着摇晃赫米特。>"
D.Strings[49452]="我的羞愧之情简直难以言表。原谅我吧——我当时神智失常了。"
D.Strings[49453]="如果你今后需要任何帮助，不管是缺少芜菁种子还是箭矢，朱家堡永远是你的坚实后盾。"
D.Strings[49454]="现在，我必须把注意力转移到重建村庄上去。还有很多事情要做。如果你愿意的话，可以在这里休息，但我们不能接受你更多的帮助了。"
D.Strings[49455]="但肯肯总觉得悲伤的还不止那几个……"
D.Strings[49456]="我们到哪儿了？闻起来好像……胡萝卜和粪味儿。"
D.Strings[49457]="那是谁啊？跟你说话的那个家伙。谁来告诉我怎么了？"
D.Strings[49458]="那是猢狲的声音吗？我们还没到半山村吧？"
D.Strings[49459]="丽丽？是你吗？有人吗？谁来关心一下老泥盏啊？"
D.Strings[49460]="儿子！你没事了！"
D.Strings[49461]="不，你是对的。你完美地诠释了“王牌狩猎”。我以你为荣，儿子！"
D.Strings[49462]="我也爱你，儿子。现在，让我们找地方喝一杯吧！"
D.Strings[49463]="他来了……"
D.Strings[49464]="你还有其他事情要做吗？不用为老泥盏担心……只要到了捅我一下就行。"
D.Strings[49465]="在尖塔之间有10个热气球。这些是检查点。我们刚才就经过了一个。"
D.Strings[49466]="我真不敢相信，自己竟成了陷阱的诱饵。幸亏你和我爸爸赶来了。"
D.Strings[49467]="一片全新的土地，可你还想继续狩猎无聊的老狼？"
D.Strings[49468]="重质不重量，孩子。"
D.Strings[49469]="看好了……这才叫作战利品。"
D.Strings[49470]="你的战利品缩水了吗，爸爸？还是说你的狩猎规模变小了？"
D.Strings[49471]="你的翔龙已经到了。你可以在空中找到悬挂在红色热气球上的旗帜。"
D.Strings[49472]="参赛选手各就各位！飞行竞技赛即将开始啦！"
D.Strings[49473]="比赛规则很简单。经过全部10个检查点，并穿越终点线。"
D.Strings[49474]="开始！冲啊！"
D.Strings[49475]="跑啊！！！"
D.Strings[49476]="你在...\n...\n内完成了，你是第一名！"
D.Strings[49477]="你在...\n...\n内完成了，你是第二名！"
D.Strings[49478]="你在...\n...\n内完成了，你是第三名！"
D.Strings[49479]="你在...\n...\n内完成了，你是第四名！"
D.Strings[49480]="你在...\n...\n内完成了，你是第五名！"
D.Strings[49481]="你在...\n...\n内完成了，你是第六名！"
D.Strings[49482]="你需要经过全部10个检查点才能完成比赛！"
D.Strings[49483]="你想要开始这场首领战吗？"
D.Strings[49484]="我们是被召唤来的。$b$b最初，我们是受大酋长贝恩·血蹄之命远航进入未知的水域。$b$b是我的妻子莱莎的预见指引了我们的航线。$b$B可是当我们看到重重迷雾的时候，我们都感受到风中传来低语般的召唤。北方。那声音召唤我们前往北方。$b$b我们登上海岸，拆卸掉船只，乘坐独木舟逆着河流而上，直到撞上我们面前这片悬崖。"
D.Strings[49485]="帐篷里出什么事了？"
D.Strings[49486]="是莱莎的预见指引我们来到这里的。我们每个人都梦到一个峡谷，盛开着金色的鲜花，洋溢着和平的希望。$b$b就连是我们的大酋长贝恩·血蹄也得到了这样的预见。$b$b可是，只有莱莎的幻象给我们指明了道路。现在，无论好坏，我们都已经到了这里。"
D.Strings[49487]="只有最迅捷的骑手才会赢得最终的奖励！骑上你们的云端翔龙！"
D.Strings[49488]="你的翔龙狼吞虎咽着。"
D.Strings[49489]="你的翔龙一口吞下了食物。好美味！"
D.Strings[49490]="你的翔龙吃完后又四处张望，寻找起食物来。"
D.Strings[49491]="你的翔龙舔着嘴唇，真是太好吃了！"
D.Strings[49492]="你的翔龙恳求地看着你，还有食物吗？"
D.Strings[49493]="你的翔龙的肚子看上去又圆了一点。"
D.Strings[49494]="你的翔龙在开吃之前亲昵地拱了你一下。"
D.Strings[49495]="你的翔龙觉得食物非常美味。"
D.Strings[49496]="你表现出了极大的潜力，$n，但你必须依靠戒律来磨砺你的天赋。"
D.Strings[49497]="幼年翔龙是非常脆弱的。许多坏习惯就是在这时期养成的。但良好的训练能改变这一切。"
D.Strings[49498]="幼年翔龙要比成年翔龙顽皮得多。"
D.Strings[49499]="翔龙骑士的道路漫长而艰险，但你将和你的翔龙伙伴一路同行。$B$B如果你们能互相扶持走到终点，你就将收获一个终生不渝的忠实朋友。"
D.Strings[49500]="好了，莱莎，我需要你用力推。你准备好了么吗？"
D.Strings[49501]="推！"
D.Strings[49502]="啊啊啊！嗯嗯嗯！"
D.Strings[49503]="哇啊啊啊！"
D.Strings[49504]="很好，干得不错。你现在可以休息一下。我再去给你端点热水来。"
D.Strings[49505]="风刃教头，我的翔龙还好吗？"
D.Strings[49506]="你已经投入了大量的时间、耐心还有爱心，$n。现在来看看你的翔龙吧。"
D.Strings[49507]="德兹科……好疼……好……啊啊啊！"
D.Strings[49508]="不太对劲。婴儿的胎位不正。"
D.Strings[49509]="德兹科，你在哪？！"
D.Strings[49510]="我在这儿，莱莎。"
D.Strings[49511]="亲爱的……不管发生什么事……你都必须保护我们的……我们的孩子……"
D.Strings[49512]="莱莎！！"
D.Strings[49513]="今天，你终于通过了云端翔龙骑士团的考验。今天，一位新骑士加入了我们的行列。"
D.Strings[49514]="今天，你与你的云端翔龙建立了永恒的联结。"
D.Strings[49515]="穿越雷鸣，穿越风暴，我们守望相助。"
D.Strings[49516]="飞天越海，我们比肩翱翔。"
D.Strings[49517]="穿越飓风，穿越潮汐，我们一起翱翔。"
D.Strings[49518]="你再也不会孤独飞翔。"
D.Strings[49519]="因我有同袍在后，我有翔龙在侧。"
D.Strings[49520]="带着荣耀与勇气飞翔吧。现在……化身为翔龙骑士！"
D.Strings[49521]="去，到你妻子身边去。我来保护帐篷，抵御入侵者。"
D.Strings[49522]="我的孩子就要降生了……今天一切都变了……"
D.Strings[49523]="我的毛今天看起来是不是很闪亮啊？"
D.Strings[49524]="我跟阿加拉是交相辉映，相得益彰。"
D.Strings[49525]="别人告诉我，我是天空之中最英俊的骑士。如果我是你，我就不会相信这种鬼话。我也是大地之上最英俊的骑士，深海之下最英俊的骑士……呃，反正不管到哪儿我都是最英俊的！"
D.Strings[49526]="你是来欣赏我的翔龙的吧。噢，它给阿加拉也留下了深刻的印象。"
D.Strings[49527]="嘿，你在干什么？"
D.Strings[49528]="这里的事结束之后，我一定要和兄弟们去龙舞楼喝几杯！"
D.Strings[49529]="嘿菜鸟，在临风岛上注意寻找玛瑙翔龙蛋。要是你能将它带给翔龙大师，他们一定会喜出望外！"
D.Strings[49530]="哦，你是我的粉丝吗？真不好意思，我现在不能给你签名。"
D.Strings[49531]="抱歉，我现在不能和你闲聊。等我们完成这里的训练之后，就该吃午饭了！"
D.Strings[49532]="我也许不是最棒的骑士，但却拥有一流的发明！"
D.Strings[49533]="当我因失去而感到难过时，我就化悲痛为食量……"
D.Strings[49534]="我想到了一个新发明，叫做集粪桶。有了它，我就再也不用自己去收集粪便了！"
D.Strings[49535]="你知道吗，在临风岛上有时能找到稀有的玛瑙翔龙蛋。要是你将它带给翔龙大师，就能赢得骑士团的尊重。"
D.Strings[49536]="吃饱了才有力气！反正我妈妈总跟我这么说……"
D.Strings[49537]="我现在没空聊天，我很忙。"
D.Strings[49538]="你能稍后再来吗？我正在忙着训练我的云端翔龙。要是我想击败对手，就必须得加把劲。"
D.Strings[49539]="我并不担心我的比赛，因为我知道我赢定了。"
D.Strings[49540]="我唯一担心的就是奎陆，他总在自己的设备上搞些花样。"
D.Strings[49541]="你想跟我一较高下？哈！你只能看着我的翔龙尾巴，望尘莫及。"
D.Strings[49542]="要是我一直站着陪你聊天，就无法击败对手了。"
D.Strings[49543]="哦耶，我给安离长老带去了许多玛瑙翔龙蛋。我每给她一枚，就使自己在骑士团中的地位得到了提升。"
D.Strings[49544]="要是我不努力，就会被别人甩在身后。"
D.Strings[49545]="一个勤奋的骑士就是一个成功的骑士。"
D.Strings[49546]="你不该多练练吗？"
D.Strings[49547]="最好的经验就是自己的经验。"
D.Strings[49548]="我可以把我的骑术窍门告诉你，但这还是比不上你自己的刻苦练习和亲身体会。"
D.Strings[49549]="我为什么能这么快？如果我告诉你，不就对自己不利了吗？"
D.Strings[49550]="去向教头们请教吧。我没什么可教你的，我也只是个徒弟而已。"
D.Strings[49551]="其他的新手都有着各自的技巧和天赋，能和他们一起翱翔我感到很荣幸。"
D.Strings[49552]="能和你同场竞技是我的荣幸。"
D.Strings[49553]="嗨！你好吗？"
D.Strings[49554]="需要帮助的话，尽管找我！"
D.Strings[49555]="你要尽量记住那些检查点的位置。一旦搞清楚该去哪儿收集那些旗帜，你便可以制定出最短的飞行路线。"
D.Strings[49556]="穿越那些云之环是提升速度的最好办法。有时候为了提升速度而偏离一下航线还是很值得的！"
D.Strings[49557]="四处找找看有没有新路线，有时候最快捷的路线并不是那么显而易见的！"
D.Strings[49558]="我听其他受训者说，在临风岛上能找到玛瑙翔龙蛋。我找啊找啊，可却一个都没找到！"
D.Strings[49559]="技巧很重要，但归根结底有时候还得看运气。"
D.Strings[49560]="别担心，就算你最后一个冲过比赛终点，我也会为你呐喊助威的！"
D.Strings[49561]="其他弟子都是非常优秀的骑士。但愿有一天，我也能像他们那么出色。在那之前，我只要不懈地练习就行了！"
D.Strings[49562]="照顾幼年翔龙可是一门精细活儿。"
D.Strings[49563]="除非你愿意帮我清理龙穴，否则你最好让我回去工作。"
D.Strings[49564]="我一半的时间花在这座图书馆上，另一半的时间则花在照顾这些雏龙身上了。"
D.Strings[49565]="你了解翔龙骑士的历史吗？那是个非常有趣的故事。"
D.Strings[49566]="我希望有一天能增进我们的古老知识，其中绝大多数都在历史的长河中遗失了。"
D.Strings[49567]="等你将来见识过更多世面之后，记得回来跟我谈谈。我会把有关翔龙骑士的一切都告诉你。"
D.Strings[49568]="如果你想加入到我们的行列，就去跟安离长老谈一谈。"
D.Strings[49569]="我们欢迎一切有志加入我们行列的人，但在开始之前，你需要积攒更多的经验。请稍后再来和我谈谈。"
D.Strings[49570]="一个新弟子？$B$B嗯，当然了。$B$B看你们那眼睛发亮、尾巴乱摇的兴奋样儿，还以为能轻松带一条来自东方的云端翔龙回去呢。$B$B好吧，你们应该仔细考虑清楚。$B$B这条路可没那么好走。$B$B骑士团只接收那些有潜力将训练进行到底的弟子。"
D.Strings[49571]="欢迎来到百木园，旅行者。$B$B这里是云端翔龙骑士团的家园。我们与我们的云端翔龙都将誓死守护翡翠林。$B$B你也可以加入我们的行列。但在开启这段旅程之前，你还需要更丰富的经验。$B$B在这片土地上游历一番，当你更加强大时，再回来找我吧。"
D.Strings[49572]="再没有比骑在作战翔龙的背上翱翔更加精彩的体验了。"
D.Strings[49573]="你很稚嫩，未经考验，榜上无名。只能独自飞翔。$B$B如果你想改变这一切，就去西边找安离长老谈一谈吧。"
D.Strings[49574]="啊，又一个崇拜着！我还真是声名远播啊。$B$B别难过，我们将来或许会有并驾齐驱的机会。"
D.Strings[49575]="别担心，孩子。骑龙没有看上去那么困难。$B$B不过你尝试这个动作之前，还需要多加练习。"
D.Strings[49576]="抱歉，我不想把时间浪费在陌生人身上。"
D.Strings[49577]="也许有一天，你也会渴望成为一名翔龙骑士。"
D.Strings[49578]="嗨，你好啊！$B$B在你加入我们之前，还有几季的课程等着你去学呢。"
D.Strings[49579]="什么是飞行竞技赛？那当然是最能展现翔龙骑士技巧的一场大赛啦！"
D.Strings[49580]="你也想来试试？一个像你这样乳臭未干的小子？$B$B哈哈！哈哈哈哈哈！$B$B你这是螳臂当车、不自量力啊！"
D.Strings[49581]="第一名？哇！$B$B对像你这么年轻的弟子来说，这已经很不错了。"
D.Strings[49582]="嘿，第二名也不赖。你下次就能超过他们啦。"
D.Strings[49583]="能进入前三名已经很不错了。名列前茅总比排名倒数要体面嘛，对吧？"
D.Strings[49584]="第四名。嗯，不算很出色。不过没关系。你可以再试一次。"
D.Strings[49585]="第五名？好歹你不是最后一名。"
D.Strings[49586]="好吧，你是最后一名。$B$B硬着头皮也得上啊，不是吗？"
D.Strings[49587]="谢谢你！他们说，我们要变成奴隶了。"
D.Strings[49588]="我永远都不会忘记的，英雄。"
D.Strings[49589]="他们说，他们在找奴隶和武器。"
D.Strings[49590]="%s平静地打着鼾。"
D.Strings[49591]="噢，好极了！又有人来烦我了。"
D.Strings[49592]="看来我再睡上一天好了……"
D.Strings[49593]="走开！朱家堡能自己解决问题。我们不需要什么所谓的“冒险者”插手！"
D.Strings[49594]="大师，我想要重温一下基础训练。"
D.Strings[49595]="卫士！醒来保护你的主人！"
D.Strings[49596]="碎地者勃罗耶正在复活废墟守卫。"
D.Strings[49597]="你不愿意臣服于我们的力量？那就像个渣滓一样死掉吧。"
D.Strings[49598]="这些……魔古族……比我预想的还要难对付，也更聪明。你不该来的，这是个陷阱。"
D.Strings[49599]="<尝试解除科尔·血牙的束缚。>"
D.Strings[49600]="科尔！不……！"
D.Strings[49601]="女士们、先生们，准备仰望我的胜利吧！"
D.Strings[49602]="比赛结束后到龙舞楼喝一杯？就当是庆祝我夺冠嘛。第一轮你请！"
D.Strings[49603]="我是不会让这张漂亮的脸蛋儿沾上一点泥巴的。"
D.Strings[49604]="我要用我的新发明打败你们。它是一个吸云石！"
D.Strings[49605]="我要用我的新发明打败你们。它是一个遥控骑手弹射器！"
D.Strings[49606]="嘿嘿！你们这些家伙等着看我的最新发明啊！我会给你们一个提示，它是一个南瓜雨！"
D.Strings[49607]="嘿嘿！你们这些家伙等着看我的最新发明啊！我会给你们一个提示，它是一个南瓜火箭！"
D.Strings[49608]="我要用我的新发明打败你们。它是一个快速摘旗器！"
D.Strings[49609]="我要用我的新发明打败你们。它是一个检查点查找器！"
D.Strings[49610]="我要用我的新发明打败你们。它是一个风动器！"
D.Strings[49611]="我要用我的新发明打败你们。它是一个棍子上的胡萝卜！"
D.Strings[49612]="我为此已经训练了整整一周！"
D.Strings[49613]="我会在终点线那边等你们的！"
D.Strings[49614]="比赛结束后，我一定会带你去看看我所有的冠军奖杯！"
D.Strings[49615]="太……配做我的……对手了……"
D.Strings[49616]="大师，我想要重温一下进阶训练。"
D.Strings[49617]="是的，跟蛋有关的那个。"
D.Strings[49618]="进阶训练？你是说跟蛋有关的那个训练吗？"
D.Strings[49619]="滚出来，恶魔！"
D.Strings[49620]="我要超度你！"
D.Strings[49621]="我要结果了你！"
D.Strings[49622]="说你呢！在椽子那儿的！煞魔侵占了我神圣的藏书阁！"
D.Strings[49623]="看看它们是怎么对待这些神圣书卷的……腐化它们！亵渎它们！"
D.Strings[49624]="你休想再玷污这些书卷！"
D.Strings[49625]="你必须消灭腐化的源头！快，否则宝贵的历史就要被永久抹除了！"
D.Strings[49626]="魔古族大多是些暴徒和强盗。在我印象中，他们向来没有学习奥术魔法的耐心。"
D.Strings[49627]="我猜，科夏废墟就是某个重大事件的发生地。我可能是在那节历史课上打盹了。"
D.Strings[49628]="翻滚俱乐部的第一条规则：不要议论翻滚俱乐部。$B$B翻滚俱乐部的第二条规则：如果是你的第一次，你就翻滚吧。"
D.Strings[49629]="让我们翻滚起来。"
D.Strings[49630]="我将继续守护。"
D.Strings[49631]="我们效忠至死，有时在死后也依然效忠。"
D.Strings[49632]="我要让敌人再尝尝我的拳头。"
D.Strings[49633]="只是皮肉伤。"
D.Strings[49634]="我曾在其拉之战中奋战在最前线，也曾在艾卓——尼鲁布深渊中冲锋陷阵。我完全了解，一支放任自流的昆虫军团会对我们的世界造成多大的威胁。"
D.Strings[49635]="在得知螳螂妖袭击的消息时，我们正在向西进发，随后我们就改变方向来到了这里。"
D.Strings[49636]="我想念莱莎。"
D.Strings[49637]="即便是平民，这些熊猫人也是技巧高超的战士。"
D.Strings[49638]="在这个螳螂妖、蜥蜴人、魔古族、热疫和无数的丛林野兽横行的地方，我绝不会让我的孩子离开我的视线。"
D.Strings[49639]="螳螂妖？！我一直以为他们只是熊猫人讲给自己孩子听的恐怖传说。"
D.Strings[49640]="影踪派充满了传奇色彩。他们的实力在潘达利亚是无可匹敌的。"
D.Strings[49641]="遇见你以来，我们经历了传奇般的战斗，见证了数不清的奇迹。"
D.Strings[49642]="我必须赶到石犁村去！螳螂妖很快就会发动进攻了。"
D.Strings[49643]="魔古族在我们躲避螳螂妖的途中伏击了我们。"
D.Strings[49644]="当我们遭到魔古族的伏击时，我们的使者正在去朱鹤寺的路上。"
D.Strings[49645]="我很奇怪，这些袭击者为什么能不计伤亡地拼命攻击我们。"
D.Strings[49646]="他们扒走了遇难者身上的衣物，偷走了我们家里的装饰品，还掠走了我们熔炼出来的铁锭。这是什么样的行径？"
D.Strings[49647]="朱鹤寺通常都会来帮我们抵御这些强盗。但近来他们却一点动静也没有。"
D.Strings[49648]="<农夫老愚疲惫地揉着眉头。>$B$B一点希望都没有！我永远也搬不光这些石头了！"
D.Strings[49649]="科尔，你为什么要这样做？为了复仇而把命给搭进去，不值得呀。"
D.Strings[49650]="帮把手……呃……你叫什么来着？$n？谢谢你，$n。我得歇会儿。"
D.Strings[49651]="如果你有什么不清楚的，可以来我家找我。"
D.Strings[49652]="我们为战而生、至死方休。而要诠释生存，战斗和死亡的意义，却并非易事。"
D.Strings[49653]="熊猫人是一个高贵的种族，我愿意与之并肩作战。"
D.Strings[49654]="你给这对双胞胎起名字了吗？"
D.Strings[49655]="谢谢，但我的名字是女孩用的。"
D.Strings[49656]="没事，他一定能以英勇的事迹留名青史，让人们记住这是一个勇士的名字。"
D.Strings[49657]="农活是看着简单做着难。"
D.Strings[49658]="嘿，老愚！出来一下！"
D.Strings[49659]="这么说，你永久性地接管了农场，嗯？"
D.Strings[49660]="我们开门见山吧。你也许是老老愚的后代，可你终究是个城里人。"
D.Strings[49661]="你甚至连如何经营一家农场都不懂吧？这样吧，我来帮你省去这个麻烦。你把这块地卖给我，然后从哪儿来的回哪儿去。"
D.Strings[49662]="随你的便吧，城里人。但我赌你撑不过一个星期。我是说，瞧瞧这烂摊子！"
D.Strings[49663]="别瞎折腾了。把地卖给我，我来帮你省去这个麻烦。"
D.Strings[49664]="我打赌你连一个星期都撑不到。"
D.Strings[49665]="走吧大伙儿，让他继续干他的“农活”吧，哈哈哈！"
D.Strings[49666]="哦，我的天呐！泥爪先生！真想不到会有您这样的贵客临门。"
D.Strings[49667]="你？想加入阡陌客？哈！你得让那五名有表决权的委员会成员认同你的耕作能力。他们永远都不会对你投赞成票！"
D.Strings[49668]="你是郝瀚·泥爪，对吧？阡陌客的首领？你们是全潘达利亚大师级的农夫！"
D.Strings[49669]="是的，先生！这个农场是我祖父留给我的，我刚搬来不久。很高兴认识你，邻居！"
D.Strings[49670]="另外，等我掌握窍门之后，我也想跟你们一样，做个阡陌客！"
D.Strings[49671]="但……但这是我们家传的农场，我不能卖。"
D.Strings[49672]="我爷爷经常告诫我，不要把话说得太满。我会尽力而为。"
D.Strings[49673]="嘿，外面有人吗？"
D.Strings[49674]="我给他五天时间。"
D.Strings[49675]="两天，最多！"
D.Strings[49676]="我会帮你的，农夫老愚。"
D.Strings[49677]="不用了，谢谢。我自己能行。"
D.Strings[49678]="好！我们一起努力，一定能加入阡陌客！"
D.Strings[49679]="噢，见鬼。照这个速度，我永远也进不了阡陌客。好吧，如果你改主意了，通知我一声。"
D.Strings[49680]="%s发出了一声凄惨的哀号。"
D.Strings[49681]="我想我会把它放进炖汤里，正好我们缺肉。"
D.Strings[49682]="青春之池是我祖祖辈辈流传下来的一个古老传说。现在，我这个老朽决心要找到它们！"
D.Strings[49683]="曾经，我只为追求知识而生。$b$b现在，我穷尽每一分每一秒，只为让我的族人重新获得永生。"
D.Strings[49684]="我女儿丽娅拉本想让我终日打扫寺庙，以过此余生。$b$b呸！当我决定跨过传送门来到这片神奇而又美丽的土地时，我感受到前所未有的活力。"
D.Strings[49685]="你好，$r！你来的正是时候。$b$b我们没想到在这里还能遇见联盟的人。"
D.Strings[49686]="在地牢边上找一些镣铐，应该有三个。"
D.Strings[49687]="我去市集了。若是关于阡陌客的事情，请来半山市集找我。若是其他事情，可以找蒙蒙帮你解决。\n\n——郝瀚·泥爪"
D.Strings[49688]="我趁我爸没注意的时候溜出来了，去半山市集找我！\n\n——迪娜·泥爪"
D.Strings[49689]="把鱼带到市集，半山见！\n\n——玉儿"
D.Strings[49690]="如果你发现这张字条，那我不是死了，就是在半山市集。$B$B但愿我能暂时放下工作，到镇上喝一杯热乎乎的麦芽酒。或许你该去确认一下，以防万一。$B$B如果我真的没能完成任务，请把我的爱意和私人物品转交给我远在朱家堡的家人。\n\n——阿烁"
D.Strings[49691]="市……集。\n\n——吱吱"
D.Strings[49692]="<<事件：博学者瓦尔德林饮下了药剂，并将他的生命精华传输给周围所有的NPC。>>"
D.Strings[49693]="我去半山市集了。请自行离开。\n\n——老农山掌"
D.Strings[49694]="外出一天，人在半山市集。\n\n——艾拉"
D.Strings[49695]="我父亲来这里是为了寻找青春之池，我来这里是奉了泰兰德·语风之命。"
D.Strings[49696]="我的哨兵曾经面对过比这丛林还要糟糕的境况。"
D.Strings[49697]="看来这片土地上的某些东西影响了我们小队的士气。"
D.Strings[49698]="和奥丹姆干燥的沙漠环境相比，这片丛林既潮湿又宜人。"
D.Strings[49699]="泰兰德钦定我来执行这个任务。$b$B她说这是因为她看到了幻象，但我猜真正的原因是因为说服她批准这个任务的人，是我父亲。"
D.Strings[49700]="这片土地简直就是猎人的乐园，因为这里充满了危险。"
D.Strings[49701]="你拯救了我的哨兵，英雄。我会永远地感激你。现在我们可以继续执行任务了。"
D.Strings[49702]="这些家伙看上去真不错，都是很棒的战士，虽然有点单薄……"
D.Strings[49703]="父亲，我们先要对付部落的斥候。"
D.Strings[49704]="快离开损毁的坦克，它要爆炸了！"
D.Strings[49705]="没什么能比这新鲜蔬菜更适合你的汤了。"
D.Strings[49706]="嘿，大厨！我想问你下……我们是朋友吧？"
D.Strings[49707]="当然了，$n！我们是名副其实的好友。$B$B难道你忘了你从山地猢狲手里把我救出来那事了吗？后来我们还为此痛饮一番，醉得连裤子都找不着了。"
D.Strings[49708]="啊，是时候了。$B$B你是要放了我，还是有……其它的主意？"
D.Strings[49709]="|cFF0008E8Rogue:|r <捡起锁铐。>"
D.Strings[49710]="<打开锁铐。>"
D.Strings[49711]="我没有用来打开锁铐的钥匙。"
D.Strings[49712]="<让他继续被锁着。>"
D.Strings[49713]="楼上的卫兵队长赫德里克·伊文凯恩应该有钥匙。请你抓紧时间，我们可不能整晚都待在这里！"
D.Strings[49714]="这里的水看起来很不错。"
D.Strings[49715]="这里的水倒是有点意思……"
D.Strings[49716]="好家伙！看看这个可爱的小池子！"
D.Strings[49717]="这水似乎有点太……怎么说的来着？哦，太干净了。"
D.Strings[49718]="我想说的就是这个！水里既没蜘蛛也没螃蟹。"
D.Strings[49719]="这应该是最后一个了。"
D.Strings[49720]="该死！"
D.Strings[49721]="见鬼！"
D.Strings[49722]="看起来他的鳃里有点儿水，我得弄一些出来……"
D.Strings[49723]="我得从这蜘蛛的嘴里把水弄出来。一点小毒素应该没什么大碍的，对吧？"
D.Strings[49724]="天呐，这家伙吞了好多水。我得弄点出来。"
D.Strings[49725]="陈酿的酒里肯定掺着鳄鱼肚子里的水。"
D.Strings[49726]="夺日者不会高兴的。记住我的话，谁都不应该轻视夺日者。"
D.Strings[49727]="谢谢你！我们现在能离开这该死的小岛了吗？"
D.Strings[49728]="我们去金扇泽那找颜色发暗、有漩涡的池水吧……那水一定不错。"
D.Strings[49729]="我准备好出发了，泥盏。"
D.Strings[49730]="你准备好去找水了吗？"
D.Strings[49731]="|cFFFE9A2E科里克提克捍卫者|r援军出现了！"
D.Strings[49732]="|cFFFE9A2E科里克提克吞噬者|r援军在上方出现了！"
D.Strings[49733]="|cFFFE9A2E科里克提克虫群使者|r援军加入了战斗！"
D.Strings[49734]="拜托了，好心的陌生人。净化这里的恶灵！这些书籍需要安宁！"
D.Strings[49735]="噢，天哪。如果我没搞错的话，这似乎是在演绎赵·追日者的故事。"
D.Strings[49736]="谢谢，英雄们。我……呃……<被诡异的事情打断>"
D.Strings[49737]="相传在很久以前，天上明晃晃地挂着五个太阳。一旦刮起风来，灼人的热浪总会让大地燃起燎原野火。"
D.Strings[49738]="庄稼枯萎，村庄燃烧，家家户户背井离乡，不断地躲避着烈焰的侵扰……<爆炸打断了他的话>"
D.Strings[49739]="我看我们找得差不多了。"
D.Strings[49740]="大火席卷了藏书阁！拜托了，英雄们！在寺庙化为灰烬之前，净化这邪恶之力吧！"
D.Strings[49741]="赵是真正的民族英雄，看着他的传说被煞魔亵渎真是令人难过。看到正义得到伸张，我很宽慰。"
D.Strings[49742]="衷心感谢，英雄们。是你们让这座神圣的庙宇重获安宁。"
D.Strings[49743]="现在，你们走吧！我得在复原仪式开始前冥想一下。"
D.Strings[49744]="啊，还没完呢。看来，我们正面临野牛人的挑战。让我解释一下……"
D.Strings[49745]="这滚烫的热气已经让我精神恍惚了…海市蜃楼！你们都是幻觉！"
D.Strings[49746]="如传说所言，赵勇猛抗争……朝天空射出箭矢，直到只剩下一个太阳。"
D.Strings[49747]="该死的鳄鱼，差点咬掉我的手！"
D.Strings[49748]="%s的|cFFFF0000弱点|r暴露了！发起攻击，打破他的密封甲壳！"
D.Strings[49749]="这……这是一个陷阱……"
D.Strings[49750]="<给丽娅拉松绑。>"
D.Strings[49751]="丽娅拉！非常抱歉，我的孩子。"
D.Strings[49752]="既然我们已经是熟人了，$n，那我就给你点提示吧。这附近的村民能帮你装扮农场，但你得先跟他们成为朋友才行。你可以帮他们完成日常任务，或送他们些小礼品——就像你刚才给我的那个，这样就能和他们建立友谊。"
D.Strings[49753]="丽娅拉！不……！"
D.Strings[49754]="<口水从贾古的嘴角淌了下来。>"
D.Strings[49755]="呃，你好？"
D.Strings[49756]="嗨！我今后会跟农夫老愚一起干活。你好吗？"
D.Strings[49757]="嘿，你好吗？我是新来的。"
D.Strings[49758]="你好，我是从外地来的。"
D.Strings[49759]="你好，先生。你住在这附近吗？"
D.Strings[49760]="你好，泥爪先生。不知你是否见过我，我在农夫老愚的农场帮忙。"
D.Strings[49761]="我在那一眼就认出了你，我是新来的。"
D.Strings[49762]="你真的叫玉儿吗？这个名字好特别。"
D.Strings[49763]="嗝……嗝！"
D.Strings[49764]="要我送你一程吗？"
D.Strings[49765]="我得去见陈·风暴烈酒。"
D.Strings[49766]="我得去见猢狲肯肯。"
D.Strings[49767]="我得去见康·棘杖。"
D.Strings[49768]="啊，是的，我听说过他。他去了庞家农场，就在雷脚农场那边。$b$b你准备好出发了吗？"
D.Strings[49769]="啊，是的，我听说过他。他好像去了泥盏营地，对吗？$b$b等你准备好，我们就可以上路了。"
D.Strings[49770]="啊，是的，我听说过他。他好像和泥盏一起去了半山，对吗？$b$b等你准备好，我们就可以上路了。"
D.Strings[49771]="啊，是的，我听说过他。他好像去了酒坊，对吗？$b$b等你准备好，我们就可以上路了。"
D.Strings[49772]="肯肯……我听说他好像在朱家堡。$b$b要我带你过去吗？"
D.Strings[49773]="肯肯……我听说他好像在朱鹤寺附近的某个地方。$b$b要我带你过去吗？"
D.Strings[49774]="这次“失败”的围攻当然只是幌子。你没看出来吗？"
D.Strings[49775]="你喜欢礼物吗？"
D.Strings[49776]="呜呜噜噜……我喜不喜欢礼物？那当然了！有谁会不喜欢礼物呢？"
D.Strings[49777]="这块红宝石碎片是给你的。"
D.Strings[49778]="这根蓝色羽毛是给你的。"
D.Strings[49779]="这支泽地百合是给你的。"
D.Strings[49780]="这只玉猫是给你的。"
D.Strings[49781]="这只可爱的苹果是给你的。"
D.Strings[49782]="我想你弄错了，朋友。你没有我想要的东西。"
D.Strings[49783]="那个棘杖家的小子成天在野外游荡，和雷霆裂口的那些“牛头人”打成了一片。依我看，他这是在找麻烦。$b$b你也想加入他？"
D.Strings[49784]="那个棘杖家的小子成天在野外游荡，和逐晨者营地的那些“牛头人”打成了一片。依我看，他这是在找麻烦。$b$b你也想加入他？"
D.Strings[49785]="那个棘杖家的小子成天在野外游荡，和他们称之为“先遣营地”的那些“暗夜精灵”打成了一片。依我看，他这是在找麻烦。$b$b你也想加入他？"
D.Strings[49786]="那个棘杖家的小子成天在野外游荡，和营地里的暗夜精灵打成了一片。依我看，他这是在找麻烦。$b$b你也想加入他？"
D.Strings[49787]="胃里空空，光喝可不解饱。给锦鱼人来点吃的吧，好吗？"
D.Strings[49788]="礼物？我有个主意。$B$B你知道什么和可口的饮料最搭吗？是美味的小吃。"
D.Strings[49789]="我改主意了。"
D.Strings[49790]="这份翡翠林炒饭是给你的。"
D.Strings[49791]="这碗迷雾汤是给你的。"
D.Strings[49792]="这些虾饺是给你的。"
D.Strings[49793]="这份香烤林地野雉是给你的。"
D.Strings[49794]="这份碳烤虎肉排是给你的。"
D.Strings[49795]="这份猢狲小炒是给你的。"
D.Strings[49796]="这份炖狼肉是给你的。"
D.Strings[49797]="这份焰灵鲑鱼是给你的。"
D.Strings[49798]="这份鸳鸯鱼拼盘是给你的。"
D.Strings[49799]="这份锦绣鱼是给你的。"
D.Strings[49800]="你听说过煎炸胡萝卜吗？这是我的最爱。真想现在就吃到嘴……嗝！"
D.Strings[49801]="我曾经吃过一只可爱的苹果，太美味了。$B$B<贾古呆呆地眺目远方，似乎走神了。>"
D.Strings[49802]="哦，太美了！我喜欢！"
D.Strings[49803]="哦，一只可爱的苹果！今天真走运！"
D.Strings[49804]="真是只可爱的小猫咪，跟我梦里见过的一样……嗝！"
D.Strings[49805]="这根羽毛，太漂亮了。谢谢你……嗝！"
D.Strings[49806]="哦……这些花让我想家了。"
D.Strings[49807]="哦，煎炸胡萝卜！我的最爱！"
D.Strings[49808]="呃……你亲手做的？这正是我想要的，谢谢你！"
D.Strings[49809]="灰烬用鼻子蹭了蹭哨兵指挥官丽娅拉。"
D.Strings[49810]="他们……不知道从哪儿冒出来的。我中了埋伏。"
D.Strings[49811]="你是石犁村的贵人，$n。我们以后可能还会请求你的帮助。在那之前，你该和我们的飞行管理员谈一谈，他会带你去任何你想去的地方……免费的哟。"
D.Strings[49812]="那么，你到底想干嘛，陌生人？我还要经营市集呢。"
D.Strings[49813]="你来对地方啦，陌生人！半山市集有你需要的所有东西。"
D.Strings[49814]="陌生人，你在找食物和酒？半山市集里就有。"
D.Strings[49815]="别光傻站在那儿啊，陌生人！不想过来跟我聊聊吗？"
D.Strings[49816]="陌生人，你是来买，还是要卖？请随便看看吧。"
D.Strings[49817]="你需要什么吗？我这会有点儿……忙。$B$B<科洛捏紧了正在挣扎的蜥蜴人的脖子。>"
D.Strings[49818]="关于礼物，你有什么好建议？"
D.Strings[49819]="这有什么好说的？你喜欢谁，就送一些他们喜欢的东西呗。"
D.Strings[49820]="有谁不喜欢收到礼物呢？$B$B我——我喜欢花。"
D.Strings[49821]="你应该把漂亮的花送给漂亮的女士，比如我。"
D.Strings[49822]="这附近长着很多漂亮的花，而我最喜欢的是泽地百合。可惜，那种美丽的花很难找到。"
D.Strings[49823]="你知道我最想要的是什么吗？一大碗迷雾汤。那一定很好喝。"
D.Strings[49824]="你知道他们怎么说吗——帮助你的邻居，你的邻居也会帮助你。$B$B当然，你可以偶尔帮他们做一些杂事，但礼物能更快地让你们成为朋友，你不觉得吗？"
D.Strings[49825]="从哪儿能找到礼物？你有没有在田地里找过？$B$B你永远也不知道你会在这些农田里找到什么。$B$B说不定你甚至能在自家地里刨出些东西来！"
D.Strings[49826]="在田里劳作一整天会让人胃口大开。$B$B别说是我告诉你的，这里的家伙胃口大到能把一个女人都吞下去。$B$B大多数人都会有一道最喜欢的菜。如果你会烹饪的话，他们会很乐意尝尝你的手艺。"
D.Strings[49827]="欢迎你。我们还想再等一会儿，看看还有没有其它人要来。"
D.Strings[49828]="<布兰琪的吼声震彻风暴。>$B$B你成功了！锅炉和酒桶都到位了……现在我们就等着大自然显现神迹吧。$B$B你觉得呢？准备好来点烟火吗？"
D.Strings[49829]="让我看看你的本事吧，布兰琪！"
D.Strings[49830]="我们要把这地方炸成个大坑，呵呵。"
D.Strings[49831]="我们在每艘船上都放好了炸药桶。"
D.Strings[49832]="我可以告诉你镇上每一个人的住处，你想找谁？"
D.Strings[49833]="艾拉住哪儿？"
D.Strings[49834]="老农山掌住哪儿？"
D.Strings[49835]="阿烁住哪儿？"
D.Strings[49836]="吱吱住哪儿？"
D.Strings[49837]="郝瀚·泥爪住哪儿？"
D.Strings[49838]="迪娜·泥爪住哪儿？"
D.Strings[49839]="吉娜·泥爪住哪儿？"
D.Strings[49840]="农夫老方住哪儿？"
D.Strings[49841]="贾古住哪儿？"
D.Strings[49842]="我找不到这个人，帮帮我！"
D.Strings[49843]="艾拉住在农田的最西边，就在风暴烈酒酿造厂的北边。$B$B她的父母死后她就一直独自生活，可怜的孩子。"
D.Strings[49844]="老农山掌住在西北边的山上，他的农场就在山的南边。$B$B那个可怜的老人自从儿子死后就再也不和人交往了。"
D.Strings[49845]="吱吱的农场在西北边，就在山上不远处。$B$B那个可怜的家伙总是被疾病缠身。"
D.Strings[49846]="那个奇怪的女孩阿烁总是在山上转来转去。$B$B没人知道她从哪儿来，但她受过杀手的训练。$B$B以前帮我们对付猢狲时露过一两手。她是个好女孩，但是话不多。"
D.Strings[49847]="哦，玉儿？那个可爱的女孩住在北边码头。$B$B我在她还是个小姑娘的时候就认识她了。$B$B她总是在泥里挖来挖去，或在湖里游来游去，或在林间上串下跳。她父母还真给她起对名字了，因为她就像鱼一样滑溜。"
D.Strings[49848]="我父亲住在田地中间的农舍里，就在那座古旧的仙鹤雕像东边。$B$B他拥有山谷里几乎所有的肥沃土地，而且他从不让任何人忘记这一点。$B$B这就是我离家出走的原因。因为他觉得所有东西……所有人，都是属于他的。"
D.Strings[49849]="我的姐姐和我父亲一起住在田地中间的农舍里，就在那座古旧的仙鹤雕像东边。$B$B我很希望能时不时地见到我姐姐，但她这些天来总是忙于梳妆打扮，好引起那些路过这里的农场小伙的注意。"
D.Strings[49850]="啊，贾古……他很有可能醉倒在摊位后面了。只要往酒吧南边走上几步就能找到他。$B$B他不久前流浪至此，然后再也没离开过。$B$B这里人人都喜欢他，他可是个预测收成的行家。"
D.Strings[49851]="有些人你找不到？好吧，他们只可能出现在三个地方。$B$B要么在市集里，要么一整天待在家里，要么在日歌农场里。$B$B如果这三个地方还找不到他们，那你就该去检查下你的眼睛了！"
D.Strings[49852]="玉儿·采苇住哪儿？"
D.Strings[49853]="大家都住哪儿啊？"
D.Strings[49854]="农夫老方住在镇子北边，就在水塔附近。$B$B算我倒霉，我跟他很熟。"
D.Strings[49855]="你在找谁？把地图给我，我帮你标出来。"
D.Strings[49856]="你这蠢货，你要找的人就是我！你以为你在跟谁说话啊！？"
D.Strings[49857]="这里的树是我这一路上所见过最漂亮的。"
D.Strings[49858]="博学者瓦尔德林坚信他可以找到青春之池。$b$b想象一下，如果成功的话，那将为我们的人民带来什么啊，我们将再次获得永生……"
D.Strings[49859]="赵也被腐化了！拜托，怀着敬意与他一战吧……"
D.Strings[49860]="高阶女祭司泰兰德曾对批准此任务犹豫不决。$b$b她似乎觉得瓦尔德林的研究来源是一把双刃剑。$b$b在那个奥法地牢度过许多时日后，我开始认为她或许是对的。"
D.Strings[49861]="我再也忍不下去了！"
D.Strings[49862]="康说魔古是一群暴徒和强盗。$b$b根据我们迄今为止的观察，我认为他们也许会成为熊猫人种族最大的威胁。"
D.Strings[49863]="呃！你好……$B$B<艾拉的脸红了，她害羞地低下头。>"
D.Strings[49864]="幸运的是，地牢已被关闭，我们在传送门另一端的盟友可以把补给品传送过来了。$b$b不幸的是，我们还未能解除这个阻止我们通过传送门回传物品的封印。"
D.Strings[49865]="阿……阿丽娜在负责指挥。"
D.Strings[49866]="我的血……在燃烧。"
D.Strings[49867]="泰兰德警告过我……她……她说在光明之前将会是……一片黑暗。"
D.Strings[49868]="棘杖妈妈经常告诉我，要是我继续打烂她的花瓶，她就把我送到都阳地下城去。"
D.Strings[49869]="我从没听说魔古族如此大规模的集结过。"
D.Strings[49870]="这些魔古人也许行动笨拙，可他们的表情却总是冷若冰霜。"
D.Strings[49871]="我想我看见一些魔古族正在挖圣物。$b$b那一定不是好事。$b$b我们至今还流传着当年魔古族学会使用圣物和奥术力量后，干出的邪恶勾当。"
D.Strings[49872]="陆战队员们已经上岸，正在把守海港入口。$B$B你有你自己的任务。认真做事，安全返回。$B$B地狱咆哮的双眼注视着你！"
D.Strings[49873]="我花费了好长时间，设法充实我的人生，以至于忘记了要活在当下。"
D.Strings[49874]="我以为自己还有大把时间。我一直这么想……"
D.Strings[49875]="而现在……这蠢事……让我女儿付出了生命的代价。"
D.Strings[49876]="我爱你，我的小丽娅拉。"
D.Strings[49877]="水也许不能创造生命，但它至少能让我转化生命。"
D.Strings[49878]="谢谢你送我这么可爱的礼物，$n。我最喜欢猫啦！"
D.Strings[49879]="吃芜菁可真让我不舒服。"
D.Strings[49880]="这些饺子看上去很美味！"
D.Strings[49881]="我等不及要尝尝了。"
D.Strings[49882]="这些菜都是你自己做的吗？"
D.Strings[49883]="纪念中"
D.Strings[49884]="战斗交给我们吧。终于迎来了安宁……"
D.Strings[49885]="完成了。加尔鲁什之拳正在丢炸弹。"
D.Strings[49886]="看来你确实捅了马蜂窝了，$c。$B$B准备好起航了吗？"
D.Strings[49887]="哨兵们，收拾好你们的行装，准备出发吧！埃克辛塔尔，为我们开启一道通往下一个位置的传送门。我们要在这里留下一个小卫戍营，然后向西北方向进军。"
D.Strings[49888]="泰兰德派我们来这里寻找圣光。"
D.Strings[49889]="甚至连空气中都充满了悲伤。"
D.Strings[49890]="我们能在这个海岸上遇见还真巧。"
D.Strings[49891]="哨兵指挥官丽娅拉需要你的报告。"
D.Strings[49892]="没事儿，姑娘。放松。"
D.Strings[49893]="那儿，那儿。"
D.Strings[49894]="放松点，好姑娘。你很快就能站起来奔跑了。"
D.Strings[49895]="冷静。我在这儿，别怕。"
D.Strings[49896]="这些魔古都是从哪儿冒出来的？"
D.Strings[49897]="谢谢你救了我们，$c。希望我们的任务不会以失败而告终。"
D.Strings[49898]="这些“精灵”……他们信得过吗？"
D.Strings[49899]="先是螳螂妖，接着又是魔古。真是暗无天日啊。"
D.Strings[49900]="我不知道你为什么会来禁忌之林，但我很高兴你来了。要不是你，我们可能已经成了奴隶……或者更糟。"
D.Strings[49901]="魔古族什么时候学会了使用魔法传送门？"
D.Strings[49902]="我们连做梦都是螳螂妖的进攻。我们希望朱鹤寺能为我们解梦。"
D.Strings[49903]="你为什么要去朱鹤寺？"
D.Strings[49904]="我们希望仙鹤能够帮忙解释我们看到的现象。$b$b螳螂妖！螳螂妖在攻击我们的家园，它们飞过城墙，成群结队地攻击我们。$b$b这样的噩梦是意料之中的事情，影像中发生的一切在城墙边栩栩如生。$b$B但是近来，这一幕幕的画面在我的眼前愈演愈烈，已经到达了一个顶点。"
D.Strings[49905]="螳螂妖？"
D.Strings[49906]="你确实不了解潘达利亚。$b$B螳螂妖是长城外面的怪物，是西部的心腹大患，是出没在我们土地上的邪恶力量。$b$B每隔一千年，螳螂妖就会来我们的土地上肆虐，掠夺财物和食品。$b$b我们的大学者告诉我们说距离螳螂妖下一次侵袭还有好几年时间，但我们的梦向我们描述了另一番景象。"
D.Strings[49907]="一座奥法地牢。幸亏这座废墟的墙壁早已倒塌，否则我们就会无粮无水地被困在此处。$b$b看起来，这片废墟的建造者原是想要建造一座监狱，用来囚禁任何想要传送到脚下这个坐标的人。$b$b这对穿越它的法师来说也是致命的。看看它对我们可怜的奥术师都做了些什么。$b$b好消息是，我们还能与那边联系上，而且还能够警告他们不要再派人过来。坏消息是，因为传送门只能单向通行，所以我们被困在这一侧了。"
D.Strings[49908]="传送门出什么事了？"
D.Strings[49909]="我才刚刚进入他们的外围巡逻圈，就被抓住了。我什么都没找到。"
D.Strings[49910]="我看见了他们的头儿。他朝长城高处走去了。让我帮你在地图上标记出来。"
D.Strings[49911]="谢谢你，朋友。还没等我有所发现，就被他们抓住了。"
D.Strings[49912]="我……我失败了。谢谢你前来找我。"
D.Strings[49913]="我们正奉命寻找青春之池！$b$b这些传说中的不老之水源自一个神奇、失落的文明，它的历史甚至比艾萨拉女王还要久远。$b$b有了这些不老之水，我们就能重现卡多雷的不朽荣耀。"
D.Strings[49914]="绝不能让联盟玷污了这片土地！"
D.Strings[49915]="魔古支持者！"
D.Strings[49916]="你永远也不会知道魔古的秘密！"
D.Strings[49917]="我更愿意保持中立。"
D.Strings[49918]="你做到了！让我们把这酒送到禅院去……"
D.Strings[49919]="我……我也不知道自己是怎么了。"
D.Strings[49920]="当然。我们决不能失去希望。"
D.Strings[49921]="那就让他们死吧……我只能保持专注。"
D.Strings[49922]="谢谢你，我忘记了“道”之真意。"
D.Strings[49923]="不，我不能让一切就这么结束。我必须继续战斗！"
D.Strings[49924]="英雄们还在与我并肩作战，我怎能放弃？"
D.Strings[49925]="看来我们还没输。"
D.Strings[49926]="真是……太黑了……"
D.Strings[49927]="我想念我的父亲。"
D.Strings[49928]="我父亲是不会白白牺牲的，我们得向螳螂妖发动进攻。"
D.Strings[49929]="我父亲曾以为我们不会遇到抵抗。但是之后，他总是把时间花在研究永生上，而不是全面考虑问题。"
D.Strings[49930]="碎地者勃罗耶证实了魔古族没有与我们谈判的打算。"
D.Strings[49931]="呃，这么说我们要收集一些甲虫和一些鸟的羽毛？没问题！"
D.Strings[49932]="听起来不错！也许下次你可以提醒我们“巨型杀人鳄”的事。"
D.Strings[49933]="哇！一个锦鱼人！"
D.Strings[49934]="在翡翠林发生了这么多事以后，我很高兴看到这里还有一些锦鱼人。"
D.Strings[49935]="他们和鱼人是亲戚吗？"
D.Strings[49936]="退后，花脑袋。你在谈论的可是我的$c朋友！"
D.Strings[49937]="等一下，现在我们要给这些家伙们摘一朵花？"
D.Strings[49938]="太娘娘腔了吧。"
D.Strings[49939]="另外……摘花不是他们的活儿吗？"
D.Strings[49940]="真恶心。"
D.Strings[49941]="看看他有多大多丑！"
D.Strings[49942]="幸好陈叔告诫过我不要打架，不然你死定了，缩头乌龟！"
D.Strings[49943]="在听我讲话吗，缩头乌龟？"
D.Strings[49944]="这可真酷。一个……一个取丝小子生命中的一天。"
D.Strings[49945]="他们到底叫什么来着？丝工？缫丝工？虫屁股挤压工？"
D.Strings[49946]="我想我会坚持“取丝小子”的叫法。"
D.Strings[49947]="刚才他说“恐怖的怪物”？"
D.Strings[49948]="瞧……冒险一定要有高手保护才行。"
D.Strings[49949]="来吧，我们先杀几个那种小家伙。"
D.Strings[49950]="很好，搞定小家伙们了！让我们去会一会这个“恐怖的丝怪”！"
D.Strings[49951]="这可真酷。"
D.Strings[49952]="这个地方好像……到处是水坑。"
D.Strings[49953]="我爱水坑！怪不得这些鸟儿都喜欢来这儿。"
D.Strings[49954]="哈！这儿一定就是那些农夫贩卖水果、蔬菜、谷物还有啤酒的地方。"
D.Strings[49955]="不知道叔叔去酿酒厂会路过这儿吗？"
D.Strings[49956]="我们买点儿什么吧？我饿了。"
D.Strings[49957]="%s打了个嗝。"
D.Strings[49958]="好了！我饱了。我们继续探险吧。"
D.Strings[49959]="瞧瞧这个！一个小农场，就在镇子中间。"
D.Strings[49960]="谁会想到在镇子中间开一个农场？哈！"
D.Strings[49961]="我敢打赌，他们在这儿种了足够所有潘达利亚人吃的食物。"
D.Strings[49962]="只可惜全都是些蔬菜。为什么就没有肉呢？"
D.Strings[49963]="噢，真酷！这儿一定就是他们储藏酿造啤酒用的谷物的地方。"
D.Strings[49964]="我不想等到长大了才知道啤酒到底是什么味道。"
D.Strings[49965]="%s微笑了起来，并神情紧张地瞟了一眼。"
D.Strings[49966]="这儿就是：风暴烈酒酿造厂。"
D.Strings[49967]="陈叔这会儿应该正在里面和远房亲戚们聊天呢。"
D.Strings[49968]="这下可好了…更多无聊的叔叔们。"
D.Strings[49969]="瞧瞧这个地方！"
D.Strings[49970]="你比陈叔酷多了。"
D.Strings[49971]="我和陈叔在翡翠林里转了几个星期，除了看到一条很酷的翔龙之外，就全是树了。"
D.Strings[49972]="而我和你在一起才一天，就看遍了整座山谷。"
D.Strings[49973]="嘿，这古怪的丛林是从哪儿来的？"
D.Strings[49974]="这就好像，突然间，不知道从哪儿就……砰。超级茂密的丛林。"
D.Strings[49975]="而且这也挺吓人的。"
D.Strings[49976]="那么？我们是进去呢，还是？"
D.Strings[49977]="有人住在这后边？"
D.Strings[49978]="好吧，这一切真的很酷，也很惊险，不过我们现在应该回泥盏那儿了吧？"
D.Strings[49979]="到处跟着你，到现在已经好一会儿了。"
D.Strings[49980]="别忘了和那个锦鱼人聊一聊，就是河边的那个。"
D.Strings[49981]="我想要说的是……谢谢。"
D.Strings[49982]="我父亲会告诉你我们来这里是为了寻找青春之池。$b$b而实际上，我们的泰兰德·语风女士在幻象中看到了一道神圣的光芒，我们也许会……不……我们一定会找到它。我们必须找到并且守护那束光。$b$b我父亲坚信那束光就是青春之池。$b$b但我觉得他被这十年来的狂热研究蒙蔽了双眼。"
D.Strings[49983]="你是最后一个。快上那架飞机，马上出发。国王很信任你啊。"
D.Strings[49984]="关键时刻到了。"
D.Strings[49985]="好……疼……"
D.Strings[49986]="父亲！你没事吧？"
D.Strings[49987]="我差点儿就达到了开启10次法师传送门无事故的目标。结果却被那些该死魔古族的陷阱给破坏了。$b$b那陷阱令我丧失了大部分能力，可我应该能再开几个本地传送门。"
D.Strings[49988]="嗯，这可能需要点时间。"
D.Strings[49989]="这些魔古族的战斗风格跟我过去面对过的对手很不一样。他们自信满满。"
D.Strings[49990]="如果棘杖妈妈看到我现在的样子……"
D.Strings[49991]="我应该知道青春之池的。在这趟旅途开始之前，我就预见到了，可我却被追求青春永驻的梦想蒙住了双眼。"
D.Strings[49992]="长达二十年的研究，那些希望和梦想，全都戛然而止了。现在仅剩下这使命，还有我的女儿丽娅拉。"
D.Strings[49993]="这些螳螂妖不禁让我想起安其拉大门开启的那一天，我的妻子惨遭吞噬。$b$b这些怪物是这片土地上真正的祸患。"
D.Strings[49994]="宝珠被丢掉了！"
D.Strings[49995]="$n夺走了宝珠！"
D.Strings[49996]="我准备好了，科洛。"
D.Strings[49997]="好了，蜥蜴嘴，我再给你一次机会——你们的巡逻队在哪儿？！"
D.Strings[49998]="回答错误。"
D.Strings[49999]="跟紧了，提高警惕。"
D.Strings[50000]="父……父亲？不！别为了我！别为了这个！"
D.Strings[50001]="我拒绝比我女儿活得更久。"
D.Strings[50002]="朝石犁村进发，帮他们解除螳螂妖的威胁。"
D.Strings[50003]="$n，这边。他受伤了。"
D.Strings[50004]="真是谢谢你把我带到恐怖的丛林和各种麻烦中来……"
D.Strings[50005]="……让我在一旁看你驱散那古老的邪恶之力，以及其他有趣的事……"
D.Strings[50006]="……可难道你不觉得，我们今天已经探索得够久了吗？"
D.Strings[50007]="不够？好吧，你说了算！那就继续前进，$n！"
D.Strings[50008]="真是酷毙了，我是说你帮人脱困的事。"
D.Strings[50009]="真希望他们能在这儿找到想要的东西。"
D.Strings[50010]="天哪，那家伙绝对有两把刷子。"
D.Strings[50011]="或者说……很多把刷子。"
D.Strings[50012]="你已经给这部分残片画出一张相当靠谱的草图了。"
D.Strings[50013]="我们的任务优先级变更了。$B$B我们得去守护这座营地，快！"
D.Strings[50014]="你们蠢蛋只配活在垃圾堆里！"
D.Strings[50015]="酋长咕克嘎克说你该上路了！"
D.Strings[50016]="你们这些蠢货就是不懂适可而止！"
D.Strings[50017]="滚开，你这个大坏蛋！"
D.Strings[50018]="死吧，坏蛋！"
D.Strings[50019]="从没见过像你这么坏的坏蛋！"
D.Strings[50020]="讨厌的光板儿！滚开！"
D.Strings[50021]="干净利落地解决掉他们！"
D.Strings[50022]="等等……好像有些不对劲……"
D.Strings[50023]="你看见我的双胞胎妹妹尼姆了吗？她可能走失了，她总这样。"
D.Strings[50024]="要是我不想杀联盟怎么办？"
D.Strings[50025]="我的妻子莱莎即将分娩，现在还发着高烧。$b$b这该死的丛林简直要榨干我们所有人的力量了。也许是水里有古怪。"
D.Strings[50026]="你为什么要带上个孕妇？"
D.Strings[50027]="德兹科，我们必须趁这些魔古族轻视我们的机会出击。让我们派这位$c去对付他们吧。"
D.Strings[50028]="你的朋友真能打，差点就逃脱了。不过现在还是和我们一样沦为阶下囚。"
D.Strings[50029]="可别把我当成你们的朋友了。经过漫长的岁月，我们的族人都已经明白信任是多么脆弱。"
D.Strings[50030]="只有蠢货才会相信陌生人。但我宁可相信陌生人，也不相信猢狲。"
D.Strings[50031]="这片土地曾经属于伟大的锦鱼人帝国。在帝国衰落之后，我们的土地就逐渐落入野蛮的猢狲部族手中。"
D.Strings[50032]="现在，我的族人要为保卫我们的最后一个村子而战。如果我们现在失败了，那么曾经显赫一时的帝王与贤者的血脉就将消失。"
D.Strings[50033]="我会逃出去的。当我回来时，将带来一整支锦鱼人大军。"
D.Strings[50034]="我们看到的幻象里没有包含这件事。"
D.Strings[50035]="泰勒就像头野兽一样激烈地抵抗那些猢狲。他真是你族人中的英雄！$B$B但最后，他还是被击败了。"
D.Strings[50036]="<上将的身体上伤痕累累、血汗模糊。他好像正在发烧。>"
D.Strings[50037]="你有什么事要报告给科尔和德兹科吗？"
D.Strings[50038]="注意脚下，这里可是雷区！"
D.Strings[50039]="嗯，陌生人？"
D.Strings[50040]="我跟你没什么好说的，陌生人。你想要什么？"
D.Strings[50041]="情况是这样的。如你所见，事情有些出乎我们的预料。$b$b这些人需要帮助，而我打算留下来帮助他们。$b$b如果你也愿意留下来，在你的帮助下，问题会变得更加容易解决。"
D.Strings[50042]="这丛林让我心生沮丧。"
D.Strings[50043]="现在别来打搅我。我得全心全意照料莱莎。她早产三个星期，出了不小的问题。"
D.Strings[50044]="噢喔……酋长知道了要生气的……"
D.Strings[50045]="别偷我们的大光板儿！"
D.Strings[50046]="咕克嘎克要你们死！"
D.Strings[50047]="你在这里做什么？！你难道不知道，野牛人正在入侵昆莱山？"
D.Strings[50048]="坏蛋来干坏事了！"
D.Strings[50049]="把他们弄死！"
D.Strings[50050]="讨厌的光板儿逃走啦！"
D.Strings[50051]="混蛋……"
D.Strings[50052]="这些坏东西……"
D.Strings[50053]="我怎么没力气了……？"
D.Strings[50054]="可恶！"
D.Strings[50055]="相传，那野牛人正在穿越昆莱平原，突然遭到两个奇怪生物的伏击！"
D.Strings[50056]="为了祖先的荣耀!"
D.Strings[50057]="野牛人坚决勇猛地予以回击。可是，他的反击越猛烈，那些野兽就变得越是可怕！"
D.Strings[50058]="然而，当他不理它们时，那些野兽却几乎化为虚无。"
D.Strings[50059]="你明白了吧，没有对抗，就没有纷争。当你内心一片平静时，纷争便会离你而去。"
D.Strings[50060]="我动不了了！你们小心！"
D.Strings[50061]="这是多么奇特有趣的生物啊。又高又壮，还有着钢铁般的皮肤。我必须得好好研究一下。"
D.Strings[50062]="水。只是转化生命。我开始明白我那译文的含义了。$b$b我猜魔古族曾用献祭囚犯、叛徒和奴隶的方式，继续与水共生。$b$b我还猜测，我研究的那些古老卷轴，最初都是由魔古族书写的，而他们没有提及这个事实。"
D.Strings[50063]="好——好——好狗狗……"
D.Strings[50064]="别打脸！"
D.Strings[50065]="谁扔的桶？老实交代！到底是谁？！"
D.Strings[50066]="也许$g他:她;是来自迷雾之外的英雄，特地来救我们的？"
D.Strings[50067]="等等，我感觉到有入侵者。是猢狲吗？快滚出来！"
D.Strings[50068]="我什么都没做。这都是吊尾酋长干的，咕克嘎克。"
D.Strings[50069]="我们可没有欢迎外乡人来我们村的习俗。"
D.Strings[50070]="你们可以留下，直到泰勒痊愈。但那以后，你们必须离开。"
D.Strings[50071]="我们别无选择。放下你的武器，战士，我们同样也放下武器。"
D.Strings[50072]="$n？这里出什么事了？"
D.Strings[50073]="长官，你觉得我们能相信他？"
D.Strings[50074]="你对我们的海军上将做了什么？"
D.Strings[50075]="军团之眼"
D.Strings[50076]="恶魔猎手的守护"
D.Strings[50077]="邪能幼龙坐骑"
D.Strings[50078]="时间行者：远古之战"
D.Strings[50079]="我们将要穿越一片硝烟弥漫的战场。你得缠住那些猢狲，好让我顺利跑过去。要是不出意外的话，我会在村子里跟你碰头。"
D.Strings[50080]="是的，我也试着跳过那玩意儿。"
D.Strings[50081]="陷阱一旦被触发，任何人都进不去也出不来，直到被困在里面的人被彻底吸干生命。魔古族可真邪恶。"
D.Strings[50082]="多加小心。要是你被困住了，它就会汲取你的生命，来为自己赋能。"
D.Strings[50083]="时至今日，这些古老的魔古陷阱仍然危险得很，其威力与恐怖的传说时代相比也毫不逊色。"
D.Strings[50084]="我试着打它、踢它、拍它、凿它。可任何方法都无济于事。"
D.Strings[50085]="勇敢的卡拉什回来了！"
D.Strings[50086]="看，一个陌生人。"
D.Strings[50087]="这没用！我们被猢狲打得节节败退！"
D.Strings[50088]="坚强点，战士们！挡住这些猢狲！"
D.Strings[50089]="这个与我们同行的陌生人是谁？"
D.Strings[50090]="这就是那个陌生人吗？"
D.Strings[50091]="勇敢点，兄弟们！前进！"
D.Strings[50092]="为了珠鳍部族！"
D.Strings[50093]="谢谢你。我没事，我们继续前进。"
D.Strings[50094]="有更多蜥蜴人来了！"
D.Strings[50095]="营地就在前方，我们应该能安然抵达。"
D.Strings[50096]="啊，就是这孩子。他看起来很特别吧？我和我的亡夫一直都想要个孩子。"
D.Strings[50097]="都是安的错！是她怂恿阿信去敲青玉巫婆的大门的。"
D.Strings[50098]="我要妈妈。"
D.Strings[50099]="哦，谢谢！谢谢！谢谢！"
D.Strings[50100]="请给我们一个机会来证明我们的友谊。我们不会伤害你们的。"
D.Strings[50101]="我和我的朋友带着和平的意愿而来。"
D.Strings[50102]="我来自联盟。我们希望成为你们的朋友，而不是敌人。"
D.Strings[50103]="想要清晰了解自己的心意，就要反省你的内心。"
D.Strings[50104]="让你的思绪澄净如水。深呼吸，然后保持平静。"
D.Strings[50105]="我喜欢将自己定位为本民族的历史学家。我相信，为了更好地理解现状，我们必须研究过去的历史。"
D.Strings[50106]="不会伤害？呸！几千年前，珠鳍部族统治着潘达利亚全境。可现在，我们就只剩下这个村子里的族人了，而这一切都是因为我们相信了一个外来部族……那些猢狲。"
D.Strings[50107]="哦！$c！到这来。如果你有空的话，我需要你帮我个忙。"
D.Strings[50108]="啊，你肯定是个外乡人。很遗憾，我正在制作武器。不久之前，我还是个专门制作祭典礼器的手艺人呢。这场战争把大家都逼入了绝境。"
D.Strings[50109]="我们的守卫越强壮，我们生存下来的几率也就越大。但这显而易见，即使是对于像你这样的人而言。"
D.Strings[50110]="我们得更加刻苦训练。"
D.Strings[50111]="我已经把我所会的都教给我们的战士们了。不幸的是，这似乎还不够。"
D.Strings[50112]="猢狲总是使用卑鄙的游击战术，例如伏击和陷阱。很不幸是的，我们每次都会中他们的招。"
D.Strings[50113]="我们是水上的霸主，这也是我们为什么能坚守村子如此之久的原因。但是在陆地上，特别是丛林茂密的地方，猢狲拥有压倒性的优势。"
D.Strings[50114]="君子讷于言而敏于行，陌生人。我的战士们渴望复仇，但这需要更加刻苦的修炼。走开点，我们很忙。"
D.Strings[50115]="你看见我们湖泊了吗？多么宁静安详。我们就喜欢这样。稳定、宁静。我们不喜欢改变。"
D.Strings[50116]="奔流不息的河水冲刷着我们每一个人。有些人选择随波逐流、苟活于世；有些人选择激流勇进、开创未来。$B$B你是哪一种，陌生人？你心中的河水将流向何方？"
D.Strings[50117]="陌生人，你见过石子落入平静的湖水中的样子吗？我们的一举一动都会激起阵阵涟漪，哪怕是接受一份信誓旦旦的友情。我需要三思而后行。"
D.Strings[50118]="别忘了你的头盔，$n。新丁……"
D.Strings[50119]="指挥官，我把潜水头盔弄丢了。"
D.Strings[50120]="嘻嘻嘻！你会跟你那边的朋友一样，死在泥浆里的……"
D.Strings[50121]="即便是在困难时期，熊猫人也总是慷慨地与他人分享食物和栖身之所。$B$B我们其他人都该向他们学习。"
D.Strings[50122]="早在多年以前，魔古族就会在世界各地布满这种小陷阱，以阻止人们四处传送。陷阱会从被困者的身上汲取能量，直到他们死亡。$b$b就像棘杖妈妈常说的那样：“别随便把手伸进陌生人的传送门。”"
D.Strings[50123]="嘿！有人吗？喂！"
D.Strings[50124]="我从没想到我们会在这里遇到这么大麻烦。$B$B也许就不该离开寺庙……"
D.Strings[50125]="嗨，猴子，别这么瞧我。我可不是用来吃的，明白？"
D.Strings[50126]="别用你那贼溜溜的小眼睛盯着我看！"
D.Strings[50127]="别过来，死猴子！我可是个训练有素的军情七处特工。"
D.Strings[50128]="呃……大家都去哪儿了？这边笼子里有个侏儒！救命啊！"
D.Strings[50129]="真是强大的治疗啊！"
D.Strings[50130]="加入我们吧，$c。你在战斗中能助我们一臂之力。"
D.Strings[50131]="谢谢你。是你救了我。"
D.Strings[50132]="我必须重新加入拯救滨岸村的战斗。"
D.Strings[50133]="我们必须把野牛人赶回螳螂高原。"
D.Strings[50134]="你身负殊荣，陌生人。请加入我们吧。"
D.Strings[50135]="你一定是少昊派来的救星。"
D.Strings[50136]="现在怎么说，烈日行者？"
D.Strings[50137]="我想我们今天全都损失惨重，年老的精灵。收殓亡者吧。"
D.Strings[50138]="你见过那个名叫安玻的军情七处特工吗？$B$B她的轰炸机遭到重创，消失在了东北边的那片树林里，之后就杳无音信了。"
D.Strings[50139]="是的，我感觉好多了。$B$B米希卡和勇敢的卡拉什向我汇报了最近的情况：你的到来，你搜寻白卒的过程，以及将我从猢狲手中营救回来的事迹。$B$B目前的情形不容乐观，我们还有很多工作要做。我们当前的首要任务是找到安度因王子。"
D.Strings[50140]="课程…结束了。"
D.Strings[50141]="|TInterface\\Icons\\inv_misc_book_01.blp:20|t%s给$n来了个|cFFFF0000|Hspell:113395|h[严酷教训]|h|r！"
D.Strings[50142]="你总算及时把东西带回来了，$n。长老已经准备好进行水语仪式了。"
D.Strings[50143]="这里看来发生过激烈打斗，信使一定是因伤而死的。$B$B他的补给背包似乎原封未动。"
D.Strings[50144]="这里看来发生过激烈打斗，信使一定是因伤而死的。"
D.Strings[50145]="拿走补给品。"
D.Strings[50146]="你好啊，陌生人。你想要造访神秘的潘达利亚吗？"
D.Strings[50147]="送我去潘达利亚！"
D.Strings[50148]="那个游酒家的家伙？为什么一个金酿家的人要知道游酒家的人在哪儿呢？他们家族只会让我们美丽的小镇蒙羞。$b$b更可恶的是，那个卑鄙肮脏的家伙好像盯上我的女儿了。我绝不允许这种事发生！$b$b如果你看到他或是我女儿，帮我多说说他们两个。"
D.Strings[50149]="罗？当然。我已经去找过他好多次了。呃，其实是找他和塞拉·金酿两个人。$b$b他们最常去的地方，就是旅店和百木园。"
D.Strings[50150]="你准备好出发了吗？我想我们在这里的事情刚好要做完了……"
D.Strings[50151]="多亏了你，族长祝福了我未来的女婿。我想这意味着游酒家族和金酿家族的世仇终于可以终结了。$b$b不要告诉别人，其实我还是很感激你的。长年死抱着仇恨不放是很累人的。$b$b我们过去太固执己见了，需要某些新的事物，或新的人，来帮我们理清分歧、搁置争议。"
D.Strings[50152]="酒仙游酒愿意为你效劳。$b$b我游历翡翠林，只是为了寻找最好的酿酒材料。$b$b我可不像晨芳园里那个傲慢自大的金酿家族。$b$b他们只会用他们大型的酿酒厂进行批量生产。其实他们的酒也还行啦，如果你爱喝泔水的话。"
D.Strings[50153]="我得找到塞拉！"
D.Strings[50154]="谢谢你。让我们开始吧。"
D.Strings[50155]="罗！我们要出发了。你去哪儿了？"
D.Strings[50156]="流水之魂告诫我，我还需要仔细思量。"
D.Strings[50157]="想要找到白卒的话，我们得依靠我们族人的远古魔法。为此，我们首先得做出一瓶洄梦仙酒。"
D.Strings[50158]="|TInterface\\Icons\\ability_warlock_inferno.blp:20|t%s开始施放|cFFFF0000|Hspell:113364|h[焚烧书籍]|h|r！"
D.Strings[50159]="酿酒的材料越强大，酿出的酒中蕴含的魔法也就越强大。"
D.Strings[50160]="洄梦仙酒会让你进入深度的冥想，你的心灵之眼会帮你解答最大的疑问。"
D.Strings[50161]="我们的心灵具有一种尚未发现、难以言喻的力量。凭借着智慧和平衡，我们就有可能施放出这种心灵之力。$B$B洄梦仙酒只是一个工具，能够帮你暂时进入这种全视状态。"
D.Strings[50162]="洄梦仙酒是多年以来流传至今的古老配方。"
D.Strings[50163]="请稍后。"
D.Strings[50164]="风暴来袭！做好准备。"
D.Strings[50165]="酒桶要是着起火来，我需要你帮忙灭火。"
D.Strings[50166]="小心闪电攻击！"
D.Strings[50167]="……蜥蜴人？他们在这儿干什么？把他们赶走！"
D.Strings[50168]="呦，风暴比我想的还要猛烈！小心！"
D.Strings[50169]="说你呢！别光站着不动，解决掉这些召唤者！"
D.Strings[50170]="关键在于那些酒桶——别让它们起火！"
D.Strings[50171]="快把酒桶的火扑灭！"
D.Strings[50172]="这场风暴已经肆虐得失去控制了！保护酒桶……"
D.Strings[50173]="不要心怀绝望，科洛。在我家乡那边有句名言：黎明前夕总是最黑暗的。"
D.Strings[50174]="安度因，一起行动吗？蜥蜴人的威胁已经暂时解除，我们该讨论下一步行动了。"
D.Strings[50175]="集中精神、放松心情，保持你的身心平衡。"
D.Strings[50176]="谢谢，谢谢你们两位。对我的族人来说，朱鹤始终象征着希望，没有了他，就连我的思绪也开始变得晦暗。"
D.Strings[50177]="很好。在你的言辞间我看到了超乎年龄的睿智。等这一切结束之后，我很愿意进一步了解你的来历。"
D.Strings[50178]="%s轻声笑了起来。"
D.Strings[50179]="真是巧夺天工！"
D.Strings[50180]="看那家伙多大啊！它一定是我这星期见过最大的飞蛾。"
D.Strings[50181]="我们正需要像你这样富有才干的$c，帮忙扭转战局。"
D.Strings[50182]="|TInterface\\Icons\\inv_misc_head_dragon_01.blp:20|t%s开始施放|cFFFF0000|Hspell:113653|h[巨龙之息]|h|r！"
D.Strings[50183]="被“焚烧书籍”击中，书燃起了火焰。"
D.Strings[50184]="跑吧跑吧，光板儿！要是被我抓住，我就把你吞进肚子里去！"
D.Strings[50185]="我安度因·乌瑞恩是暴风城的王子。我绝不能死在这里。绝不！"
D.Strings[50186]="如果你是来带我回去见我父亲的，那我必须要让你先环顾周围——我们真能在这些人急需帮助的时候扬长而去，还声称自己是代表联盟而来吗？"
D.Strings[50187]="在我们的族人之间存在分歧，$c，可我们都是这里的宾客。$B$B熊猫人热情尊敬地厚待我们，我敢肯定你也受到了同样的待遇，现在，他们需要我们的帮助。$B$B部落也并非没有荣誉感。如果你也知道荣誉为何物，那你应该明白，我们的恩怨可以改日再行了结。"
D.Strings[50188]="继续放箭！一个也别想跑！"
D.Strings[50189]="又干掉一个。再接再厉！"
D.Strings[50190]="你好。$b$b我是沙埃。$b$b他们让我守望悬崖。$b$b有时会有初生牛犊不怕虎的幼仔跑到这里来。有时也会有大人出于好奇心前来。$b$b我要把已经告诉他们的话重复给你听。悬崖很危险，那片丛林则更加危险。$b$b你可以用绳索下去，但我要提醒你，这是个非常危险的地方。"
D.Strings[50191]="击败所有作废的试验样本来逃脱！"
D.Strings[50192]="我与朱鹤相处的时间很短，但我却在他的指导下收获良多。$B$B这个敌人——这股名为“煞”的能量，不同于我们以往面对过的任何敌手。它是情绪波动的物质表现，在大地里滋长了几个世纪。$B$B这股情绪能量现在已经喷薄而出，寻找富有情感的活人宿主寄居其中。$B$B如果我们不帮助熊猫人镇压住煞，煞很可能要袭遍整片大陆，甚至是整个世界！"
D.Strings[50193]="准备好就接刀！"
D.Strings[50194]="开始了！"
D.Strings[50195]="金酿先生，我在此恳请您将您的女儿塞拉嫁给我。"
D.Strings[50196]="我感兴趣的不是她的名字，而是她的人。她是我见过的最善良、最温柔、最美丽的人。"
D.Strings[50197]="是的。那么现在，在您的允许下，我想牵起您女儿的手。"
D.Strings[50198]="谷里的溪水现在就由你来守护了……"
D.Strings[50199]="黑暗来自于地下深处，它仍旧渴望着……"
D.Strings[50200]="儿子！你在干什么！她是金酿家族的人。"
D.Strings[50201]="他们在这儿呢。看见了吧，我早就说了，不管是谁，不管是什么东西，我都能找得到。"
D.Strings[50202]="《溪山吟》就挂在墙上。拿去吧。我听到了上天的召唤，谢谢你……"
D.Strings[50203]="这个锦绣谷真是越来越有趣了，我一定要亲眼去看看。"
D.Strings[50204]="宝贝儿，好像有客人来了！是你的朋友吗，沃斯？"
D.Strings[50205]="他们的死亡只会令我的召唤者变得更强！看吧！"
D.Strings[50206]="怎么了，沃斯，你累了吗？"
D.Strings[50207]="这难道不美么？交织着血肉、骨骼和灵魂。"
D.Strings[50208]="你也很美啊，沃斯。最近照镜子了吗？"
D.Strings[50209]="宝贝儿，你应该将这份礼物视作对你的恩赐。"
D.Strings[50210]="来吧，沃斯，你的命运在召唤你。"
D.Strings[50211]="你将他们的灵魂喂给他们的同族？恶心。"
D.Strings[50212]="我永远也不会放过你的同类，死灵法师。永远。"
D.Strings[50213]="我倒是要看看你死了以后还能怎么为非作歹！"
D.Strings[50214]="他们同意了？"
D.Strings[50215]="算了吧，佩吉。我跟你一样不情愿，可族长的祝福是一种荣誉。"
D.Strings[50216]="我也一样。现在让我们把这些孩子带回晨芳园吧。"
D.Strings[50217]="什么？！这太荒谬了。"
D.Strings[50218]="我的塞拉一定不会受到游酒家族的待见。"
D.Strings[50219]="那么……呃……我……"
D.Strings[50220]="好吧。已经发生的事就不用再追究了。可你别指望我会喜欢这桩婚事，或者是你，凯。"
D.Strings[50221]="你会为多嘴付出代价。"
D.Strings[50222]="我决不会让你用这个梦魇去荼毒另一个灵魂。"
D.Strings[50223]="跑吧……死灵法师……等我喘过气来，你就死定了。"
D.Strings[50224]="这个小骗子！真没想到他敢这么做！"
D.Strings[50225]="光……板儿！"
D.Strings[50226]="该死的光板儿真是坏到家了！"
D.Strings[50227]="蠢蛋想要耍猢狲？"
D.Strings[50228]="猢狲捞到滑溜溜的蠢蛋！"
D.Strings[50229]="该死的蠢蛋不要让猢狲讨厌！"
D.Strings[50230]="猢狲捞到滑溜溜的蠢蛋恶棍。"
D.Strings[50231]="他是个好人，可拿上剑之后就变得无比可怕！"
D.Strings[50232]="他在战斗时倒下了！"
D.Strings[50233]="真没想到，他竟然坚持了那么久。"
D.Strings[50234]="我从没喜欢过那家伙。"
D.Strings[50235]="痛苦只是暂时的！"
D.Strings[50236]="我受伤了！"
D.Strings[50237]="哎呦！"
D.Strings[50238]="跟上，用护盾做掩护！"
D.Strings[50239]="今天，我们和联盟缔结友情！今天，我们如同兄弟姐妹般共同前行，驶向新的未来！"
D.Strings[50240]="你今天想去哪里游览？"
D.Strings[50241]="我想去晨芳园走一走。"
D.Strings[50242]="万岁！我们成功了！"
D.Strings[50243]="丽娅拉想让我开启新的传送门？那女人简直疯了。难道她已经忘记上次发生的事了？$b$b好吧，瓦尔德林的研究提供了几种绕开陷阱的可行方案。而我也许是走了点儿捷径才把我们带到这里来的。$b$b多给我些时间，我也许能召唤出另一个撤退传送门。"
D.Strings[50244]="噢天哪……我们到另一侧来了。这真让我欣慰。$b$b开启一道通往陌生地方的传送门可不是件容易的事啊。$b$b可要是容易的话，岂不是人人都能做到了。"
D.Strings[50245]="你必须把焰火放在一堆被偷走的货物附近。"
D.Strings[50246]="你稍事休息，让我把桶准备好。"
D.Strings[50247]="所有人都准备好了吗？出发咯！"
D.Strings[50248]="呵，小子，出现了更多蜥蜴人。雨水落下时，他们总是喜欢到高处去！"
D.Strings[50249]="你居然能让那些野蛮人接受我们？$b$b你还真鬼才，$r！$b$b谁能想到……"
D.Strings[50250]="离火远点儿！"
D.Strings[50251]="我要杀了你，坏蛋！"
D.Strings[50252]="你惹上大麻烦了！"
D.Strings[50253]="滚开，讨厌鬼！"
D.Strings[50254]="快给我滚开！"
D.Strings[50255]="你这鬼鬼祟祟的大蠢货！"
D.Strings[50256]="我要把你丢进汤锅里，你这该死的蠢蛋！"
D.Strings[50257]="他们在攀爬峭壁！这下情况复杂了。"
D.Strings[50258]="令人钦佩，$r。$b$b多亏了你，这些生物或许会成为宝贵的盟友。"
D.Strings[50259]="小心脚下！由于下雨的关系，石头还是很湿滑。"
D.Strings[50260]="注意屁股后面！不——不是说我的屁股。是我们身后！"
D.Strings[50261]="%s在路旁停了下来，喘着粗气。"
D.Strings[50262]="牛头人是最伟大的猎手。"
D.Strings[50263]="你见过牛头人猎人吗？等你见到时已经来不及脱身了。"
D.Strings[50264]="向你的愤怒屈服吧！"
D.Strings[50265]="很快，昆莱山和整个潘达利亚都将被怒火吞噬。然后，就是全世界！"
D.Strings[50266]="锦鱼人是我们的，下一个就是滨岸村！"
D.Strings[50267]="我能感受到愤怒正充斥你的内心。"
D.Strings[50268]="付莫是就是个老蠢货。他简直一事无成！"
D.Strings[50269]="被我的怒火吞噬吧！"
D.Strings[50270]="我曾经与声名远播的欧洛恩·远行者一同狩猎。他是一位牛头人，打猎时只带着图腾，穿着粗布衣衫。"
D.Strings[50271]="奈辛瓦里是位杰出的猎手，可我多么希望这儿能有一位德鲁伊，向我们传授些实用的捕猎动物的技法。"
D.Strings[50272]="好吧，我想我知道接下来该做什么了。"
D.Strings[50273]="蠢蛋就是毛毛的食物！"
D.Strings[50274]="蠢蛋捞到臭熏熏的光板儿！"
D.Strings[50275]="猢狲讨厌厉害的蠢蛋！"
D.Strings[50276]="杀蠢蛋！"
D.Strings[50277]="这真是我见过的有史以来最最糟糕的行军队列！"
D.Strings[50278]="不，不，不……先是左脚，后是右脚！"
D.Strings[50279]="噢得了吧！我们已经忙活了一整天了！"
D.Strings[50280]="嘿！嘿，就是你，后面个家伙！我盯着你呢！"
D.Strings[50281]="啊！是部落！"
D.Strings[50282]="是部落！快跑！"
D.Strings[50283]="部落入侵了！"
D.Strings[50284]="藏好你们的孩子！看好你们的老婆！"
D.Strings[50285]="呀！大家快跑！"
D.Strings[50286]="是你救了我？可你是部落！"
D.Strings[50287]="先是惹恼了煞魔，现在又是部落！"
D.Strings[50288]="从哪儿来的就回哪儿去吧，部落！"
D.Strings[50289]="谢谢你救了我一命！"
D.Strings[50290]="当我跟水交谈时，它们向我展示了一个关于你的景象，$n。或许你不仅仅只是一个过客，或许你被派到我们这儿来是有原因的。"
D.Strings[50291]="有件事很清楚，你和你的同胞将会影响到我们的未来。"
D.Strings[50292]="水语仪式让我感到十分疲惫。请给我点时间，让我好好地休息，好好地思考。"
D.Strings[50293]="我们正在努力工作，和你的士兵一起受训。"
D.Strings[50294]="多亏有你，猢狲以后再也不会成为我们的威胁了。我们的村子现在可以重新投入建设和发展了。"
D.Strings[50295]="明天充满了无限的可能性，而这一切都多亏了你和联盟的大力相助。"
D.Strings[50296]="或许某天，你可以跟我多讲一些有关你们那片神奇的故土的情况。"
D.Strings[50297]="诸灵喻示，我们必须拿起武器，抗击猢狲！"
D.Strings[50298]="你现在注视的是一位古代锦鱼人皇帝，$n，他曾经统治过潘达利亚。"
D.Strings[50299]="流水之魂的声音如雷鸣般在我耳边回荡。你听到了吗？"
D.Strings[50300]="我相信这个景象是叫我们紧密团结在一起，$n。"
D.Strings[50301]="长老还有很多顾虑，但我觉得已经很清楚。你是来领导我们击败猢狲并取得最终胜利的。"
D.Strings[50302]="我们现在是朋友了，$n。我们村随时欢迎你回来。"
D.Strings[50303]="你的名字将在我们村子里世代传诵、流芳百世。"
D.Strings[50304]="或许某天，你可以带我去看看你的故乡。那里一定有着别样的风景。"
D.Strings[50305]="我们欠你一个很大的人情，$r。"
D.Strings[50306]="锦鱼人的确是出色的战士。"
D.Strings[50307]="经过正规的训练，锦鱼人将成为我们地面部队不可或缺的一支强大战力。"
D.Strings[50308]="当部落那群野兽最终露出他们狰狞的面孔时，我们会准备好的。"
D.Strings[50309]="你做得很好，$n。等我们回暴风城后，我会在你的长官面前为你多美言几句的。"
D.Strings[50310]="今天的水流是否顺遂呢，旅行者？"
D.Strings[50311]="我们在战斗中失去了许多兄弟，我已经不想再数下去了。"
D.Strings[50312]="猢狲非常狡猾、奸诈。更糟的是，他们完全不懂羞耻和反省。$B$B他们完全凭着本能去烧杀掠夺，只为满足他们的欲望和贪婪。"
D.Strings[50313]="难以置信！我竟然看见了一位皇帝的灵魂！"
D.Strings[50314]="流水之魂向我们展现了未来的道路。但不知为何，这多少跟你还有点关系。"
D.Strings[50315]="终于，这么多天以来，我第一次感到我们的未来还有希望。"
D.Strings[50316]="有朝一日，我会把你的故事讲给我的孩子听，$n。"
D.Strings[50317]="我已经和你的一些……联盟……朋友聊过了。你们的人相当有趣。"
D.Strings[50318]="我们的士兵一直在谈论着他们的训练。"
D.Strings[50319]="你是$c吗， $n？我听过很多有关你的传闻，可从没想过能见到你本人。"
D.Strings[50320]="你的到来犹如一阵春风，沐浴了我们的部族。"
D.Strings[50321]="我必须承认，我一开始怀疑过你，$n，但你已经向我们的部落证明了你自己。"
D.Strings[50322]="我们需要安度因帮忙，才能对寺庙采取行动。等他准备好，我们就开始。"
D.Strings[50323]="血骨傀儡！"
D.Strings[50324]="等我们击溃联盟和他们的盟友，并占领这片土地之后，它就将成为部落百折不挠的精神最强有力的证明。"
D.Strings[50325]="要不是因为你，我早就死了，甚至更糟！"
D.Strings[50326]="联盟又来救援了！"
D.Strings[50327]="谢谢你，外乡人！"
D.Strings[50328]="锦鱼人对你和联盟不胜感激！"
D.Strings[50329]="我自由了！联盟万岁！"
D.Strings[50330]="真希望锦鱼人能加入联盟。谢谢你！"
D.Strings[50331]="我欠你份人情。请救救我其他的族人。"
D.Strings[50332]="纳兹戈林将军要看你的训练报告。"
D.Strings[50333]="纳兹戈林将军想要了解你的最新进展。"
D.Strings[50334]="哇哦。它可真够脏的。你确定不想把它洗干净？"
D.Strings[50335]="呃……那家伙都发臭了。"
D.Strings[50336]="噢，我一直在到处找它， 真是个麻烦的家伙。"
D.Strings[50337]="嗯。我想得把它弄得更香一些。"
D.Strings[50338]="噢，土地精会喜欢它的。"
D.Strings[50339]="野牛人对那个可怜的家伙干了什么？"
D.Strings[50340]="但愿它不会再遇到这种事了。"
D.Strings[50341]="你休想让我离开自己的土地！"
D.Strings[50342]="嘿！那些是我的牦牛！马上把它们带回来！"
D.Strings[50343]="要是你以为我会被几个脏兮兮的野牛人吓倒，那你可就大错特错了！"
D.Strings[50344]="快来帮帮我！这些野牛人想偷我的牦牛！"
D.Strings[50345]="看我走了你们就偷着乐吧，否则我会到那把你们赶出我的土地。"
D.Strings[50346]="卑鄙的野牛人祸害！"
D.Strings[50347]="真希望螳螂妖能来把你们这些野牛人拖回长城那边去。"
D.Strings[50348]="幸好我的妻子——愿灵魂指引着她，不用亲眼看见我们的家业被这些无赖和流氓恣意侵扰。"
D.Strings[50349]="这世道真是可笑，我跟你说。一个堂堂的牧场主和他儿子连开个洗牛站都提心吊胆害怕野牛人的侵袭。"
D.Strings[50350]="要是再这么下去，真不知道我们该怎么继续向土地精供应牦牛。"
D.Strings[50351]="你见过好运的八铜钱吗？他是我们最大的客户，也是土地精贸易谈判代表中最精明的一位。"
D.Strings[50352]="我们的产业已经沿袭了十二代，给土地精供应了无数新鲜、卫生又“芬芳”的牦牛。$b$b我们经历过洪灾、饥荒和魔古族的入侵。要是我让这些野牛人赶跑我们，那我就是猢狲叔叔！"
D.Strings[50353]="你想偷我的牦牛？！$b$b如果真是这样，就等着我抽你的耳刮子吧。"
D.Strings[50354]="躲开他！"
D.Strings[50355]="快离他远点！"
D.Strings[50356]="你救了我的儿子，还有我的牧场。我这辈子都会感激你的，陌生人。假如哪天你想要一头干净的牦牛，你知道该去哪找我。"
D.Strings[50357]="躲开他的攻击！"
D.Strings[50358]="对！对！更多的血！"
D.Strings[50359]="血，血，血，血，血！！"
D.Strings[50360]="滴血吧，飙血吧，凝血吧！"
D.Strings[50361]="更多鲜血！"
D.Strings[50362]="香浓的鲜血……太美味了！"
D.Strings[50363]="鲜血四溅！"
D.Strings[50364]="血流不止，血流不止！"
D.Strings[50365]="如此温热，如此鲜红！"
D.Strings[50366]="我实在不知道自己该怎么把这么多牦牛赶到一起。那些野牛人危险得很。"
D.Strings[50367]="希望野牛人的到来不是更大厄运来临前的先兆。这些野牛人已经够麻烦了。"
D.Strings[50368]="爸爸说我们还遇到过更糟的。但他所谓的“我们”，指的是他爷爷的爷爷了。$b$b我所遇到的最糟糕的事，就是一个土地精因为他的牦牛还不够臭而大发雷霆。"
D.Strings[50369]="高山树精是种卑劣的生物。它们的恶作剧真能伤到人。"
D.Strings[50370]="爸爸总说要我变得跟爷爷一样，但爷爷早在我出生之前就死于一次牦牛踩踏事故了。"
D.Strings[50371]="拜托了！你能帮帮我吗？这些树精在我寻找走失的牦牛时绑架了我。"
D.Strings[50372]="你不知道你帮了我们多大的忙，是你挽救了我们的家族生意。$b$b既然野牛人减缓了攻势，我自己应该能应付了。"
D.Strings[50373]="纳兹戈林将军想要了解补给品的现状。"
D.Strings[50374]="多谢你救了我，陌生人！我们在洗牛站再见吧。"
D.Strings[50375]="你刚才可是干掉了不少树精啊。"
D.Strings[50376]="原则是绝对的，照做，你便会得到接纳。"
D.Strings[50377]="只有十字军才是真理！顺我者昌，逆我者亡！"
D.Strings[50378]="我的牦牛走失了。"
D.Strings[50379]="别担心。这些小家伙似乎已经找到回来的路了。"
D.Strings[50380]="别担心。小家伙们似乎已经找到回来的路了。去吧。"
D.Strings[50381]="我一直找不到答案……$b$b$c，有时候你必须后退几步，才能看到整片森林。"
D.Strings[50382]="我的视力可能不行了，但幸运的是，我生活在一个到处都充满了感知的土地上。"
D.Strings[50383]="释放你的怒火吧。杀了我，证明我存在的意义。"
D.Strings[50384]="我才不怕你这种小杂碎。"
D.Strings[50385]="我要碾碎你！"
D.Strings[50386]="现在把牦牛交出来！"
D.Strings[50387]="我要压扁你！"
D.Strings[50388]="邵傲，谁在外面？安全吗？"
D.Strings[50389]="我做好出发的准备了。"
D.Strings[50390]="你的牦牛开始反抗了。返回父子洗牛站。"
D.Strings[50391]="动作快点，伙计。我们一定要赶上最后期限。"
D.Strings[50392]="有时后退一步，将目光放在长远目标上，还是大有裨益的。"
D.Strings[50393]="我们在这里的工作一成不变且沉闷冗长，但雕像已经快接近完工了。"
D.Strings[50394]="花点时间仔细瞧瞧这座宏伟的雕像吧，它可是耗费了近百年的人力所创造出来的奇迹。"
D.Strings[50395]="要搭便车吗？"
D.Strings[50396]="我父亲和我爷爷将毕生的精力都花费在这座宏伟的雕像上。作为收官之人，我感到非常自豪。"
D.Strings[50397]="工作虽然艰辛，但还是很有必要的。这座雕像代表了我们的信仰。"
D.Strings[50398]="再有一些玉石，这条龙就完成了。"
D.Strings[50399]="雕像完成后再休息一下应该会很不错。"
D.Strings[50400]="离我们完成任务的日子已经不远了。"
D.Strings[50401]="我的家族正在策划一场盛大的宴会，来庆祝雕像的落成。"
D.Strings[50402]="今天的工作结束了吗？晨芳园里的醉猴楼正在向我招手呢。"
D.Strings[50403]="下课。"
D.Strings[50404]="我要前往雕像顶层。"
D.Strings[50405]="下去？"
D.Strings[50406]="无论你做什么，千万别朝下看。"
D.Strings[50407]="我要前往雕像底层。"
D.Strings[50408]="你忘了吗，小女孩？我是黑暗院长！我统御着亡者！"
D.Strings[50409]="现在用你可爱的符文剑对准客人们，取来他们的骨头！"
D.Strings[50410]="我……不会让你……"
D.Strings[50411]="我不能……和他战斗……"
D.Strings[50412]="结果他！快！趁他还没有……"
D.Strings[50413]="看呐，是个陌生人。不知道$g他:她;是不是来帮我们摆脱野牛人的。"
D.Strings[50414]="嘘，有个外乡人。"
D.Strings[50415]="$g他:她;看上去相当强大。也许强大到能赶走野牛人！"
D.Strings[50416]="我们也许得撤退到四风谷。可我不想放弃这里的家园。"
D.Strings[50417]="是个外乡人。$g他:她;看上去古怪得很。别盯着看！"
D.Strings[50418]="你是来救我们的吗，$c？"
D.Strings[50419]="真是奇装异服，在我看来，即便是对于一个$r$c来说也有点过了。"
D.Strings[50420]="我不在乎你说什么。如果那个$c是来帮我们的，我想我们会展开双臂热情欢迎$g他:她;！"
D.Strings[50421]="玉石，一切都是为了玉石！我们需要玉石，这是底线！"
D.Strings[50422]="目前的玉石短缺是自金秋危机最严重的麻烦。工程进度已经落后好几个月了。青龙正在日益衰老！"
D.Strings[50423]="聪明的幸运儿会来选购我的货物。只有倒霉蛋才会匆匆走开。"
D.Strings[50424]="噢，你手里拿的可是块上佳的金属啊。我对精良的钢材总是相当钟爱。"
D.Strings[50425]="欢迎来到滨岸村，$c。我求你……帮帮我们吧。"
D.Strings[50426]="我把你的玉石送来了。"
D.Strings[50427]="好像有人说过想要玉石？"
D.Strings[50428]="我有一块玉石要交给你。"
D.Strings[50429]="我给你送了一批新玉石来。"
D.Strings[50430]="太好了，太棒了！如果你有时间，应该去看看青龙寺。这样，你才能进一步了解我们伟大的雕像，以及它对我们的重要性。"
D.Strings[50431]="太好了，太棒了！我看你已经去过青龙寺了。那你应该明白，这座雕像为何对我们如此重要。"
D.Strings[50432]="跟土地精拼酒的诀窍就是不能停。幸运的话，他们总会在你之前醉倒。"
D.Strings[50433]="难以置信！你刚刚救了我的小命，$n。嚯嚯，你看看这光泽。"
D.Strings[50434]="太好了！瞧瞧它，花了整整一百年的时间才建起如此宏伟的青龙雕像。现在，你也为这个杰作贡献了一份力量。"
D.Strings[50435]="快了，快了，很快就要完成了。"
D.Strings[50436]="下一批货应该已经送到了才对。我听说矿山那里出了麻烦，可我们的工作是不能拖延的。"
D.Strings[50437]="每一笔、每一画，都包含着千层含义。"
D.Strings[50438]="在我一生中，曾写下过无数强大的真言。可对于最强大的真言，我始终未窥门径。"
D.Strings[50439]="我更喜欢独自工作。"
D.Strings[50440]="你想来点什么？"
D.Strings[50441]="对一个种族来说，这是伟大的一天，你觉得呢？"
D.Strings[50442]="新鲜美味，热气腾腾的饭菜！快来这里享用你的赛间快餐吧！"
D.Strings[50443]="你可真是惹人注目啊，$n！"
D.Strings[50444]="我的$g小伙子:小姑娘;来了！"
D.Strings[50445]="滨岸村的救星，你好啊！"
D.Strings[50446]="再给我们讲讲吧，你是怎么杀死野牛人战争领袖的，$n。"
D.Strings[50447]="你想过要安定下来吗，$n？昆莱山正需要像你一样强大的$c守护者。"
D.Strings[50448]="我从没见过这般的壮举与无私。"
D.Strings[50449]="欢迎回来！有什么消息吗，$n？"
D.Strings[50450]="很高兴见到你，$n。"
D.Strings[50451]="$n，不知你愿不愿意在下次选举时投我一票？"
D.Strings[50452]="你救了滨岸村，$n。快把锣敲响，让所有人都知道这个好消息吧！"
D.Strings[50453]="一切都还好吗，$c？我们全靠你去消灭野牛人战争领袖了。"
D.Strings[50454]="我是不会让他们抓住我的！"
D.Strings[50455]="我的房子！我的家当！都烧没了！"
D.Strings[50456]="我的狗？！我的狗呢？！"
D.Strings[50457]="谢谢你……现在怎么办？"
D.Strings[50458]="整个镇子都没了！"
D.Strings[50459]="我从没想过，这里居然会发生这种事……"
D.Strings[50460]="你看见那位名叫$n的$c对野牛人做了什么吗？"
D.Strings[50461]="有$n在，我们也许很快就能重返家园了！"
D.Strings[50462]="我以前从没见过像$g他:她;那样的$c。$g他:她;已经击败了野牛人！"
D.Strings[50463]="快看，是$n，滨岸村的救星！"
D.Strings[50464]="我从没怀疑过$n，一分钟都没有！"
D.Strings[50465]="我听说$n是从迷雾那一边的遥远疆域来的。$g他:她;肯定是他们的英雄，不远千里前来搭救我们。"
D.Strings[50466]="大家快看啊，是$n！为$n欢呼吧！"
D.Strings[50467]="进攻！把他们全杀光！"
D.Strings[50468]="都给我上！"
D.Strings[50469]="别傻看着。杀光他们！"
D.Strings[50470]="啊！愚蠢的动物！等我干掉这些懦夫之后，再来教训你们。"
D.Strings[50471]="在燃烧……我的灵魂……在燃烧！！！！"
D.Strings[50472]="你好啊，$c。你们的人在里面。但我能不能先请你帮我个忙？"
D.Strings[50473]="你试过我们家传跌打酒的功效吗，$c？"
D.Strings[50474]="战士们报告说是你救了他们。谢谢你，$n。"
D.Strings[50475]="见到你总是很高兴，$n。近来好吗？"
D.Strings[50476]="你感觉怎么样，$c？要再来点跌打酒吗？"
D.Strings[50477]="你竟然对我们大家如此无私和仁慈，这令我感到很惊讶。"
D.Strings[50478]="你的朋友们怎么样了，$n？"
D.Strings[50479]="$g他:她;在那儿。这里随时欢迎你，$n。"
D.Strings[50480]="要在这里待上一阵子吗，$n？你一定给我讲讲你最近的壮举哦。"
D.Strings[50481]="你经历了那么多次冒险，现在该好好休息一下了，年轻的$g先生:女士;。"
D.Strings[50482]="我刚才还在念叨你呢，$n。"
D.Strings[50483]="能找到一头干净的牦牛可真是幸事。喂它喝我特制的佳酿则是更大的幸事。稞神牦牛就是这么制成的！"
D.Strings[50484]="我感到她的意志在破碎……她的灵魂在灼热地燃烧着。"
D.Strings[50485]="我错过了什么……"
D.Strings[50486]="有些不太对劲……"
D.Strings[50487]="外乡人？从你的打扮来看，还是个老练的$c。很好！也许你能帮我们脱离困境。"
D.Strings[50488]="我的计划取决于你能否从战场上给我们带来尽可能多的箭矢，$c。"
D.Strings[50489]="看来你弄到的这些已经绰绰有余了。快，$n，我想我已经在地平线上看到了铺天盖地的野牛人援军。"
D.Strings[50490]="<这个农夫漠然地盯着地板。>$B$B他们……抓住了他们。$B$B把他们抓走了……"
D.Strings[50491]="你要去找他们吗？你真的可以吗？"
D.Strings[50492]="现在，莉莉安，你变身的时刻到了。"
D.Strings[50493]="向昆莱小径的英雄——$n致敬！"
D.Strings[50494]="很高兴再次见到你，$n。想再好好教训这群野牛人渣滓一顿吗？"
D.Strings[50495]="不用管我们。我们正在清理最后的余孽。应该用不了多久了。"
D.Strings[50496]="能请你喝一杯吗，$g帅哥:美女;？"
D.Strings[50497]="你弄清究竟是什么把这些野牛人赶出螳螂高原的了吗？"
D.Strings[50498]="射击时小心点。别打到$n！"
D.Strings[50499]="这真是莫大的荣誉，$n。也许我们稍后能找个机会一起坐坐，听你给我讲讲你最近的义举？"
D.Strings[50500]="送它们下地狱，$n！"
D.Strings[50501]="为什么要白白浪费一具完美的尸体？"
D.Strings[50502]="感觉如何，沃斯？看着他们将你的凡躯切成碎片？"
D.Strings[50503]="陌生人！可以占用你一些时间吗？"
D.Strings[50504]="真是有趣。她的灵魂不肯放开这个世界。"
D.Strings[50505]="死吧，死灵法师！"
D.Strings[50506]="求你……让我……独自……死去……"
D.Strings[50507]="骨头！你这蠢货！"
D.Strings[50508]="我的房子就在你进村之后的右手边。面具应该在楼上。"
D.Strings[50509]="$c回来了。那是我的面具吗？"
D.Strings[50510]="$C，我得请你帮个忙。"
D.Strings[50511]="你成功消除锦鱼人身上的邪煞之力了吗，$c？"
D.Strings[50512]="谢谢你，$n。你刚刚救了我一命！"
D.Strings[50513]="老实说，我至今仍为自己加入影踪派而感到不可思议。并不是说他们有何逊色之处，只是暴力与我的完美人格向来都是风马牛不相及。$B$B不过要是说到加入他们的原因，真是想忘记都难……简而言之，安济有着超群的说服力。"
D.Strings[50514]="被骗了！我们每个星期都到这儿来。他们看上去就像是普通的生意人。\n\n可现在……这些鱼人却一边用长蹼的手跟我们打招呼，一边握紧了藏在背后的刀子，想趁我们转身时捅我们一刀！"
D.Strings[50515]="别着急，$n。你最好先做好准备，以你自己的方式从容面对狂怒的海怪。"
D.Strings[50516]="我会消灭他们的。没必要继续待下去了！"
D.Strings[50517]="完成了吗，$n？我们大老远的都能看见爆炸了。"
D.Strings[50518]="那面具是干什么用的？"
D.Strings[50519]="干得漂亮，$n。"
D.Strings[50520]="你做到了！你真的做到了！也许你能给我演示几招，$n？"
D.Strings[50521]="%s咕哝着表达着她的赞美。"
D.Strings[50522]="快看，是$n！"
D.Strings[50523]="$n，等我们做完这里的事情后，我能来跟你一起训练吗？"
D.Strings[50524]="我想我愿意成为一名$c，宝剑女侠。"
D.Strings[50525]="你是从哪里来的，$n？等你回去时，能带上我吗？"
D.Strings[50526]="再次感谢你帮我处理杂事。我们稍后在村里见？"
D.Strings[50527]="嘿，$n，你觉得这招怎么样？"
D.Strings[50528]="$n只要使出$g他的:她的;招牌$c绝招，恐怕就能横扫所有这些被感染的锦鱼人了。"
D.Strings[50529]="哈，你会变成一把很不错的敲石锤！"
D.Strings[50530]="无礼的小崽子们！投降免死！"
D.Strings[50531]="我要让你学会听话！"
D.Strings[50532]="你怎么敢这么跟我说话！想想你的身份！"
D.Strings[50533]="你们不过是一群拿着棍子的乡下农夫！滚回去！"
D.Strings[50534]="向你的愤怒屈服吧。"
D.Strings[50535]="真是荣幸，你竟然选择被感染。"
D.Strings[50536]="狂怒的海怪会很乐意将你的身体当做傀儡，对抗这片土地。"
D.Strings[50537]="不管我们对这些鱼脑袋做了什么，这关你什么事？"
D.Strings[50538]="不！我会控制你，以及你所有的族人！"
D.Strings[50539]="你才对别人施加过几次怒火？你竟然奢望能打败我们？"
D.Strings[50540]="听着，陌生人，我刚才已经跟那位尊贵的游学者说了，我现在再跟你重复一遍……$B$B<孟一边说一边走了过来，她的眼睛突然瞪得很大。>$B$B我！没！有！玉！石！"
D.Strings[50541]="这很有趣……但能有什么意义呢？！$B$B你收集来的玉石只够我们完成下一块嵌板的，但我们还需要更多的玉石来完成整个作品。$B$B请帮助工头让她的采石场恢复运作。"
D.Strings[50542]="通常我们都能轻松完成周卓的要求。这里的玉石矿脉贯穿大地，就好像……$B$B<孟挠了挠头，似乎在思考。>$B$B呃，就好像某些东西体内的血管。$B$B你瞧，我又不是诗人。$B$B重点在于：我们遇到麻烦了。"
D.Strings[50543]="多亏了你，采石场总算没事了。$B$B看来我得让小伙子们放个假……$B$B哈哈！我哄谁呢？瞧我自己也一本正经的样子。$B$B我们还有活儿要做呢！"
D.Strings[50544]="你完全不用担心我。$B$B啊啊啊啊！！$B$B我很快就能搞定，真的。"
D.Strings[50545]="你觉得那就算糟的了？我得说，你要是见过30年前那场灾难就不会这么想了。$B$B以前有个小伙子将他的午餐放在了外面——是某种鱼汤，如果我没记错的话。$B$B他把那锅炖汤放在中庭那里了——一大锅热气腾腾的鱼肉炖汤，没错，我现在记起来了——然后，我的老天，方圆百里之内所有猢狲都涌过来了。$B$B经历过那事之后，我已经不把几只发育过度的利齿蛛放在眼里了……"
D.Strings[50546]="野牛人发起进攻了！"
D.Strings[50547]="我们要死了！"
D.Strings[50548]="快来人救救我们！"
D.Strings[50549]="棘杖，快做些什么！"
D.Strings[50550]="我们正在损兵折将！"
D.Strings[50551]="我们对野牛人做过什么？！"
D.Strings[50552]="一定是因为那个陌生人，野牛人才发起攻击的！"
D.Strings[50553]="这些该死的利齿蛛快把这儿全毁了！"
D.Strings[50554]="你好啊！我是老翁：自然的弟子！$B$B我是奉命来调查最近爆发的林精问题的。$B$B我还是个孩子的时候，就对林精很着迷。你知道，一般来说，他们并不残暴。$B$B他们或许是有点淘气，但很少会对人造成真正的伤害。"
D.Strings[50555]="苏利！小卢！你们人呢！"
D.Strings[50556]="我流血了……哈哈……可我死不了！"
D.Strings[50557]="瘦瘦的光板儿一点用也没有！"
D.Strings[50558]="退下，笨光板儿！"
D.Strings[50559]="让我们看看，没有了那些滑溜溜的朋友，你还有多大本事吧！"
D.Strings[50560]="我会得到你那不驯的灵魂的，就像其他灵魂一样！"
D.Strings[50561]="你……休想击败……雷……"
D.Strings[50562]="这还远远不够！$B$B在潘达利亚的黑色泥土里埋藏着五件稀世珍宝：红宝石碎片、可爱的苹果、玉猫、蓝色羽毛以及泽地百合。$B$B只要你能将其中一件收入囊中，就能在附近找到愿意接受它们的人。$B$B找到其中一件并交给你喜欢的人，就有机会赢得他们的好感！每个人都会有他们最喜欢的东西，所以要跟他们多聊聊才能知其喜好。$B$B还有，这儿的人都很爱美食！说实话，谁不爱呢？如果你会做菜，那就再好不过了！$B$B关于礼物我就知道这些了。祝你好运！"
D.Strings[50563]="你喜欢什么样的礼物？"
D.Strings[50564]="去干掉他们，孩子。"
D.Strings[50565]="嘿，孩子！你还好吗？\n\n我抓住你了。别走进那光里！"
D.Strings[50566]="啊！狗崽子们又有鲜肉吃了。"
D.Strings[50567]="我自然有办法。瞧瞧这个。"
D.Strings[50568]="我们得在这儿站稳脚跟……远离这些部落恶狗。"
D.Strings[50569]="我烦透这些部落的懦夫了。这村子里一定还有其它地方能让我歇脚。"
D.Strings[50570]="这些人不能被你们那残忍的部落所奴役。我决不允许！"
D.Strings[50571]="有多少无辜者曾经死在你的手上，兽人？恬不知耻的部落……"
D.Strings[50572]="还剩三个部落鼠辈。这次我会一块儿把你们收拾了。"
D.Strings[50573]="昆莱山就是你的葬身之地，兽人。我会亲手埋葬你。"
D.Strings[50574]="我会等你的伤养好了再结果你，纳兹戈林。免得你说我们联盟的人没有荣誉感。"
D.Strings[50575]="看看生活在这片土地上的平和善良的人们。他们生来就属于联盟。"
D.Strings[50576]="$n，过来！"
D.Strings[50577]="等我……站起来，我就揍扁你！"
D.Strings[50578]="地精，我的斧子呢！我要把这人类傻瓜的脑袋砍下来！"
D.Strings[50579]="很快，你和你的联盟就会被写进艾泽拉斯的历史书里。"
D.Strings[50580]="我的斧子会享用你的鲜血，人类。"
D.Strings[50581]="你们无法在这里立足。这里注定要成为部落的领地。"
D.Strings[50582]="你……你在瓦丝琪尔逃过一劫，这次你没这么走运了。"
D.Strings[50583]="这些熊猫人都很明智，他们迟早会加入我们部落的。"
D.Strings[50584]="希望你有勇气来面对死亡，人类。我可是想好好打一架。"
D.Strings[50585]="犯错只说明我们还有待学习，$n。而你处理那些错误的方法，才是最终证明你品行的东西。"
D.Strings[50586]="你先去吧。我带上工具，与你在日歌农场会合。"
D.Strings[50587]="击败徘徊之疑需要冷静的头脑和坚定的信念，$c。只要控制住这些怪物，重建工作就可以开始了。"
D.Strings[50588]="蠢货！我要粉碎你！"
D.Strings[50589]="耐心点。很快就要完成了。"
D.Strings[50590]="我越早能不被打扰，就能越快把活儿干完。"
D.Strings[50591]="割草可是艰苦的工作啊。"
D.Strings[50592]="再来一点点，就能完成了。"
D.Strings[50593]="这片田地马上就能焕然一新了！"
D.Strings[50594]="我去半山市集了。别碰我的蔬菜！\n\n——农夫老方"
D.Strings[50595]="此处将播放影片……"
D.Strings[50596]="总算结束了……"
D.Strings[50597]="我会在接天桥那里等你。到那里去和我谈一谈吧。"
D.Strings[50598]="多亏了你，怨灵们终于可以安息了。很快，我魂归地府。$B$B在走之前，我要给你个忠告：潘达利亚是一块历史悠久的土地。如果你对未来感到迷茫，你只需要从过去寻找答案。$B$B记住这点，你就能在这里如鱼得水。"
D.Strings[50599]="哇！呃……我得……走了！"
D.Strings[50600]="干得好！抱歉，可我得走了！"
D.Strings[50601]="呃——噢……！我感受到了自然的召唤！"
D.Strings[50602]="噢！我感觉到有东西在隆隆作响。失陪了！"
D.Strings[50603]="哇哦，那可真了不起。我已经跑……呃……我得跑了！"
D.Strings[50604]="快灭火！"
D.Strings[50605]="旗帜着火了！"
D.Strings[50606]="旗帜！"
D.Strings[50607]="厄尔巴塔尔，快来帮忙！"
D.Strings[50608]="该死的火！"
D.Strings[50609]="厄尔巴塔尔会杀死你的！"
D.Strings[50610]="你这有醋栗卖吗？"
D.Strings[50611]="不！昆莱是我们的……"
D.Strings[50612]="这脚印已经变得泥泞难辨。"
D.Strings[50613]="在这踪迹旁边，你看到一些嚼碎的胡萝卜。"
D.Strings[50614]="那泥泞的踪迹显然是敏捷的爪子留下的。"
D.Strings[50615]="被踩进脚印里的，是混有干草和牦牛鬃的泥团。"
D.Strings[50616]="在这印痕后面，有卷尾留下的长长痕迹。"
D.Strings[50617]="在混战痕迹的边上，散落着一个锋利尖削的矛头，还有几根彩色羽毛。"
D.Strings[50618]="这些最后的足印，一直延伸到北边的山里。"
D.Strings[50619]="一只受惊的猢狲从附近的灌木丛中跳了出来！"
D.Strings[50620]="现在全都说得通了！发生在我们农场上的各种怪事。幕后黑手一定是猢狲！我必须承认，你分析得很快，$n。"
D.Strings[50621]="你好，陌生人！"
D.Strings[50622]="给我讲讲与农夫老愚的马车有关的事。"
D.Strings[50623]="我老爸无数次跟我说起过那个故事！$B$B大旱那段期间日子非常难过。农夫们都在用唾沫浇灌庄稼了，因为太干了。整个村子又饿又渴！$B$B所以农夫老愚的祖父在夜里收拾好自己的货车。$B$B然后骑着穆山兽直奔昆莱山脚下的湖泊。他在货车上装满了几百桶清水，然后立即返乡。$B$B他马不停蹄、日夜兼程！他如何能停下脚步？整个村子的人都快渴死了！当他赶着涨裂的货车回到田里时，穆山兽当场就累死了！$B$B但我们村子有了足够的水，并且还完成了春耕。$B$B泽被半山众生，老愚的祖父就是这样的人！"
D.Strings[50624]="我去拿些工具来，待会在农夫老愚的田里跟你碰头。我打赌一定能赢你！"
D.Strings[50625]="你们这些城里人都这么没耐心？"
D.Strings[50626]="这货车可不会自己把自己修好的。"
D.Strings[50627]="要不这样吧。你接着嚎，我不干了。"
D.Strings[50628]="我既会园艺，又能打铁。我老爸把我教成了一个万能修理匠。"
D.Strings[50629]="在经过短短几天的研学之后，安度因已经理解朱鹤之道了。$B$B也许他天生就懂？"
D.Strings[50630]="<那条狗瘦得皮包骨头。它可怜巴巴地望着你。>"
D.Strings[50631]="<那条狗全身上下沾满泥污。气若游丝。>"
D.Strings[50632]="<那条狗抬起头来看着你，无力地摇着尾巴。>"
D.Strings[50633]="祝土地精的朋友好运。非常感谢你的帮助！"
D.Strings[50634]="狗狗欢快地摇着尾巴。朝你的农场奔去了！"
D.Strings[50635]="翔龙，赐予我力量吧！"
D.Strings[50636]="他们的力量太强了！"
D.Strings[50637]="不，不！别让我失望！"
D.Strings[50638]="你的狗狗在对你微笑。"
D.Strings[50639]="狗狗欢快地摇着尾巴。"
D.Strings[50640]="狗狗歪着脑袋，似乎在猜测你在想什么。"
D.Strings[50641]="你的狗狗把头钻到了你的手底下。"
D.Strings[50642]="你的狗狗也爱你！"
D.Strings[50643]="你的狗狗用它那湿乎乎的舌头舔了舔你的脸。"
D.Strings[50644]="维卡维卡只想试着经营农场。没想到竟然这么难。"
D.Strings[50645]="你是来帮我教训土拨鼠的吗？"
D.Strings[50646]="瞧！那边就有一只土拨鼠！"
D.Strings[50647]="更多的土拨鼠！小心啊！"
D.Strings[50648]="呃——噢，蜇人的虫子！别让它们靠近你！会咬人的！"
D.Strings[50649]="看来那些土拨鼠逃跑了，至少现在是这样。你该去和泥爪老大谈一谈。"
D.Strings[50650]="土拨鼠？"
D.Strings[50651]="点击土拨鼠，踩上去！"
D.Strings[50652]="躲开虫群！"
D.Strings[50653]="这些弩炮对我们来说真是如虎添翼！如果我们现在把另一架弄好并运转起来，那我们可就牛了。"
D.Strings[50654]="受死吧，可恶的虫子！"
D.Strings[50655]="离我的庄稼远点！"
D.Strings[50656]="给你来一大口杀虫剂尝尝！"
D.Strings[50657]="退后，你们这群该死的虫子！"
D.Strings[50658]="离开这儿，坏蛋！"
D.Strings[50659]="耶！喷到了！"
D.Strings[50660]="一条凶狠的看门狗出现了！"
D.Strings[50661]="需要治疗！"
D.Strings[50662]="看我用杀虫剂对付它们！"
D.Strings[50663]="前往不息营地的护卫队就要出发了！集合！"
D.Strings[50664]="我会让她帮你做好返回的准备的。"
D.Strings[50665]="%s舔了舔自己的手指，举了起来。她嗅着空气，双眼扫视着天空。"
D.Strings[50666]="%s摆弄着自己的气象设备，眼中闪过一抹光。"
D.Strings[50667]="气压计的读数迅速下滑，是时候启动牵引装置了！"
D.Strings[50668]="%s若有所思地扫视着天空，咂咂舌头。她闻着空气，皱起了眉头。"
D.Strings[50669]="狠踩土拨鼠！避开虫群！"
D.Strings[50670]="旅途愉快，$r！$B$B这天气现在看起来不错，但翡翠林的上空会伴随着风暴迅速阴沉下来。你能感觉到空气在变化吗？也许你想帮我酿造一些我传说中的闪电陈酿？"
D.Strings[50671]="能和你一起训练是我的荣幸。"
D.Strings[50672]="你让我明白，我必须保持刻苦的训练。"
D.Strings[50673]="人只有在失败中才能得到成长。"
D.Strings[50674]="我们下次见面时，我会准备得更充分一些的！"
D.Strings[50675]="你能测试下我的技巧吗？"
D.Strings[50676]="在我们与猢狲开战时，我必须达到最好的战斗状态。"
D.Strings[50677]="训练是一个不间断的过程。总有一些东西值得去学习。"
D.Strings[50678]="哦，美味的魂能！"
D.Strings[50679]="[PLACEHOLDER]将我传送至场景"
D.Strings[50680]="酋长伊普伊普要发起冲锋了！快扔甜瓜！"
D.Strings[50681]="前往不息营地的土地精聚集在一起，点燃了传统的旅者熏香。"
D.Strings[50682]="那是什么？美味的魂能？"
D.Strings[50683]="漂亮的魂能？我要吃！"
D.Strings[50684]="给我吃新鲜的水果？"
D.Strings[50685]="呃呃呃……头领感觉不太好……"
D.Strings[50686]="那个魂能有点古怪……"
D.Strings[50687]="呃……坏魂能让我感觉恶心！"
D.Strings[50688]="你在那个魂能里放了什么东西？"
D.Strings[50689]="这或许让人有点不安……"
D.Strings[50690]="嘿，老愚！是真的吗？你的计划成功了？"
D.Strings[50691]="那只名叫伊普伊普的讨厌猴子死了？"
D.Strings[50692]="干得好，小愚！"
D.Strings[50693]="嗯，我要成猢狲叔叔了……"
D.Strings[50694]="知道吗老愚，也许是我错了。"
D.Strings[50695]="我是个顽固的老农夫，可我承认，你帮我了一个大忙。"
D.Strings[50696]="那群猢狲给我的农场添了大麻烦，幸亏你帮我解决了问题。"
D.Strings[50697]="我一定会投你一票。"
D.Strings[50698]="$n，这最后一块地是给你和农夫老愚的。你何不欣然接受？"
D.Strings[50699]="老愚，$n，很荣幸能邀请你们加入。"
D.Strings[50700]="是真的！多亏了$n，昆森部族的头领已死。那群猴子应该再也不会骚扰泥爪先生了。"
D.Strings[50701]="噢，终于盼到了！这是我最大的梦想！是的，泥爪先生！我当然愿意加入！"
D.Strings[50702]="啊，欢迎你。你是来买香料的吗？奇特的、稀有的、异国的香料？$b$b那你可来对地方了……邻居。"
D.Strings[50703]="我能帮你什么忙吗，$c？"
D.Strings[50704]="快进来，快进来！我今天能为你做些什么吗？"
D.Strings[50705]="你好！我是代表吉娜·泥爪前来跟你谈谈你所欠下的债务。"
D.Strings[50706]="别偷懒！"
D.Strings[50707]="没问题。我欠她的钱就在这儿。顺便替我……问候她。"
D.Strings[50708]="吉娜？市集里的那个小女孩？哈哈！$b$b替我转告那个小美女，让她亲自来收钱。我相信在她跟我之间能达成某种……协议。"
D.Strings[50709]="下次我会打得更重！"
D.Strings[50710]="我的债务？我可不欠她什么。$b$b我相当确认，那些香料，是她……送给我的。我看见她对我抛媚眼了。如果你跟我一样英俊潇洒，就也能经常碰到这种好事。$b$b你怎么还在这儿？快走吧，小$r。"
D.Strings[50711]="你们熊猫人可真弱。"
D.Strings[50712]="我们夺取了你们的土地，现在还要抢走你们的食物。"
D.Strings[50713]="<用暴力威胁他。>你想让我一拳打进你嘴里吗？"
D.Strings[50714]="嘿，嘿！别动手啊！好吧，我付……但别指望我会高高兴兴地掏钱。"
D.Strings[50715]="这可真有趣！"
D.Strings[50716]="<提出替他还债。>别担心。我今天替你还上。"
D.Strings[50717]="不许休息，赶紧干活！"
D.Strings[50718]="这还差不多。现在就去吧。嘘！你要吓跑真正的顾客了！"
D.Strings[50719]="这片土地就跟你们一样软弱。"
D.Strings[50720]="是的，好货品应有尽有。看看这用牦牛毛做的护符。非常热销。非常好运。"
D.Strings[50721]="我携宝物而来。来自远方的宝物。来自山那边的宝物……甚至有来自长城另一侧的宝物。"
D.Strings[50722]="今天可真是百年不遇的好日子啊，不是吗？"
D.Strings[50723]="噢是的！市集上的女孩！拿去吧！当一个气宇轩昂的$c参与进来时，聪明的人就会还债。"
D.Strings[50724]="聪明人会立刻还债。更聪明的人则会判断出自己是不是被敲诈了。$b$b吉娜一天到晚都坐在集市里数钱。而我却走在荒无人烟的路上，靠运气勉强糊口。我为什么应该付钱？"
D.Strings[50725]="吉娜的父亲很富有，超级富有。要是她缺钱，可以直接去跟他说啊。$b$b为什么非要跟可怜的老迦姆比兹过不去？"
D.Strings[50726]="<用暴力威胁他。>\n欠债还钱。用钱说话。"
D.Strings[50727]="够了，够了！在镇中心打架真是晦气。我只是……只是在试探你。这是我欠的钱。"
D.Strings[50728]="<提出替他还债。>\n别担心，迦姆比兹。我今天替你还上。"
D.Strings[50729]="你不光聪明，还很和善。帮助陌生人会为你带来好运的。"
D.Strings[50730]="进来坐坐，别老站着……我肯定你在外面跑了一整天了。$b$b那么，我有什么可以效劳的？"
D.Strings[50731]="今天外面挺暖和的，对吧？"
D.Strings[50732]="欢迎来到半山，邻居。"
D.Strings[50733]="那是当然！谢谢你能来。这些是我付的钱。"
D.Strings[50734]="我也想今天就能还上钱……但这段时间生意难做呀，我实在是没有钱。$b$b我身上仅有的几块金币还是准备给我家人买晚餐的。求求你……发发慈悲帮助我吧。"
D.Strings[50735]="我明白，我欠你钱。如果能还我肯定还了，但是……$b$b我急需这笔钱。我们的小店已经年久失修。如果我没钱付维修费的话，我不仅会失业……而且家庭也要垮了。"
D.Strings[50736]="<用暴力威胁她。>那不关我事。给钱，不然就承担后果。"
D.Strings[50737]="我明白了，这是我的欠款。很抱歉占用你这么长时间，$g先生:女士;。"
D.Strings[50738]="<提出替她还债。>我今天替你还上。我也只能做这么多了。"
D.Strings[50739]="你是位心地善良的$g先生:女士;，$n。我们不会忘记你的这份恩情。"
D.Strings[50740]="看着如今这些来来往往的人。真会引发你对人生的思考。$b$b比如，也许……我也应该到别的地方来来往往一把。"
D.Strings[50741]="你觉得外面是什么样的？我是说，潘达利亚外面的世界？"
D.Strings[50742]="你总是四处游走，漫无目的吗？只是为了看看在山的那一边有些什么？$b$b妈妈总说我有一双停不下来的脚，除此之外还有个颠三倒四的大脑袋。可我觉得，也许犯糊涂的是她才对。"
D.Strings[50743]="我记得吉娜！几天前，我从她那里买了一些物资。给你钱。请转告我对她的问候。"
D.Strings[50744]="额——噢……$b$b我也许不该告诉你，可我正在存钱，准备离开这镇子。我再也受不了只待在一个地方了。$b$b你是个冒险家……你明白的。能帮帮我吗？"
D.Strings[50745]="%s拿出了佩剑和盾牌。"
D.Strings[50746]="噢……噢不。要是让妈妈知道，我就有大麻烦了。$b$b你能帮我还债吗？"
D.Strings[50747]="%s丢下盾牌，拔出一把匕首。"
D.Strings[50748]="<用暴力威胁他。>看来得有人给你上一课了，孩子。给钱。"
D.Strings[50749]="哇！你……你是认真的！好吧，算了……我身上就这么多。"
D.Strings[50750]="<提出替他还债。>我今天先替你还上。下次，学会有所担当。"
D.Strings[50751]="真——真的？我不会忘记的，$g先生:女士;！"
D.Strings[50752]="我们自由了！"
D.Strings[50753]="你先走。等我把雷霆准备好，就马上去日歌农场跟你会合。"
D.Strings[50754]="只需要再等一小会儿。"
D.Strings[50755]="让我们看看谁更强大——是我的雷霆还是那块石头！我把钱押给雷霆。"
D.Strings[50756]="千万别低估一头好穆山兽的价值。"
D.Strings[50757]="一个词：熏香！"
D.Strings[50758]="你有疗伤熏香吗？"
D.Strings[50759]="你有激怒熏香吗？"
D.Strings[50760]="别被大贝莎发现。"
D.Strings[50761]="避开或摧毁巴德拉克的风暴图腾。"
D.Strings[50762]="知己知彼，方能百战百胜，这就跟战斗的道理是一样的。"
D.Strings[50763]="%s从他骑乘的狮鹫上下来了。"
D.Strings[50764]="<贾古斜睨着你。>$B$B嘿，我认识你吗？"
D.Strings[50765]="嘿哥们！很高兴再次见到你！$B$B嗝——儿！"
D.Strings[50766]="我的朋友又来看望贾古了？我今天能为你做点儿什么？"
D.Strings[50767]="你是我的好朋友，$n。也许是我唯一的朋友。"
D.Strings[50768]="你好啊$G兄弟:姐妹;！你是来向贾古请教问题的？"
D.Strings[50769]="嘿，你好。要回市集？我明白了。"
D.Strings[50770]="呃……到底要怎样呢？我还要经营市集呢。"
D.Strings[50771]="嘿，你是新来的吧。一路上有没有什么有趣的见闻啊？"
D.Strings[50772]="嘿，$r。欢迎回来。"
D.Strings[50773]="呃……到底要怎样呢，哥们？我还要经营市集呢。"
D.Strings[50774]="你来对地方啦，哥们！半山市集有你需要的所有东西。"
D.Strings[50775]="嘿，哥们！有没有什么有趣的见闻啊？"
D.Strings[50776]="嘿，哥们。你是来购物的，还是来卖货的？请随便瞧瞧吧。"
D.Strings[50777]="嘿，$n。半山市集欢迎你。"
D.Strings[50778]="呃……到底要怎样呢，朋友？我还要经营市集呢。"
D.Strings[50779]="你来对地方啦，朋友！半山市集有你需要的所有东西。"
D.Strings[50780]="嘿，朋友！有没有什么有趣的见闻啊？"
D.Strings[50781]="嘿，朋友。你是来购物的，还是来卖货的？请随便瞧瞧吧。"
D.Strings[50782]="嘿，$n。我的朋友在半山市集总是大受欢迎的。"
D.Strings[50783]="呃……到底要怎样呢，我的好朋友？我还要经营市集呢。"
D.Strings[50784]="你来对地方啦，我的好朋友！半山市集有你需要的所有东西。"
D.Strings[50785]="瞧啊，这不是我的好朋友$n嘛。你知道我想要什么吗？啊哈，没错。有没有什么八卦啊？"
D.Strings[50786]="$n，我的好朋友！你是来购物的，还是来卖货的？请随便瞧瞧吧。"
D.Strings[50787]="嘿，$n。欢迎你，邻居！"
D.Strings[50788]="呃……到底要怎样呢，邻居？我还要经营市集呢。"
D.Strings[50789]="你来对地方啦，邻居！半山市集有你需要的所有东西。"
D.Strings[50790]="嘿，$n，你好啊。快跟我讲些八卦吧！"
D.Strings[50791]="你好，邻居！你是来购物的，还是来卖货的？请随便瞧瞧吧。"
D.Strings[50792]="嘿，陌生人，我认识你吗？"
D.Strings[50793]="我认不出你这张脸，你一定是新来的。"
D.Strings[50794]="这地方的人我都认识，我会告诉他们镇上来了个新面孔。"
D.Strings[50795]="哦，你肯定不是这附近的人。你是从城里来的吗？你觉得我的裙子怎么样？"
D.Strings[50796]="你好。我们以前见过，对吗？"
D.Strings[50797]="哦，你这套衣服真漂亮。我之前居然没注意到。"
D.Strings[50798]="这里的人们都在谈论你。别担心，我会时不时地帮你说些好话的。"
D.Strings[50799]="你觉得这颜色衬我吗？"
D.Strings[50800]="嗨，哥们！真高兴又见到你。"
D.Strings[50801]="这些鞋子配上你的眼睛真是太漂亮了。"
D.Strings[50802]="这里的人们都在谈论你，哥们。别担心，我会时不时地帮你说些好话的。"
D.Strings[50803]="嗨，哥们！你觉得……我的耳环怎么样？"
D.Strings[50804]="你好，朋友。你的农场还顺利吗？"
D.Strings[50805]="既然大家是朋友了，我不得不说你的衣服实在是……太丑了。"
D.Strings[50806]="这里的人们都在谈论你，朋友！他们看起来都很喜欢你哦。"
D.Strings[50807]="拜托，作为朋友……实话告诉我，我的衣服怎么样？真有那么……糟吗？"
D.Strings[50808]="既然大家是朋友了，我得向你坦白一件事情。我……我觉得我很喜欢农夫老方。"
D.Strings[50809]="你不觉得农夫老方很……迷人吗？"
D.Strings[50810]="$n，我的好朋友！我希望你和老愚在农场一切顺利。"
D.Strings[50811]="既然大家是好朋友了，我不得不说你的衣服实在是……太糟了。"
D.Strings[50812]="这里的人们都在谈论你，$n！你打破了这里的平静。"
D.Strings[50813]="拜托，作为好朋友……实话告诉我，我的衣服怎么样？真有那么……难看吗？"
D.Strings[50814]="既然大家是好朋友了，我得向你坦白一件事情。我……我觉得我很喜欢农夫老方。但是，农夫老愚的眼睛也很迷人，不是吗？"
D.Strings[50815]="你好，邻居！我希望你和老愚在农场一切顺利。"
D.Strings[50816]="既然我们是死党了，我不得不说你的衣服实在是……难看死了！"
D.Strings[50817]="这里的人们都在谈论你，$n！我跟所有人都说你是我的邻居。"
D.Strings[50818]="拜托，作为挚友……实话告诉我，我的衣服怎么样？好吗？$B$B哦？你觉得很好？哎呀，谢谢你！这就是为什么你是我一辈子的朋友！"
D.Strings[50819]="既然我们是挚友了，我得向你坦白一件事情。我……我觉得我很喜欢农夫老方。但是，农夫老愚的眼睛也很迷人，不是吗？$B$B哦，我左右为难啊！"
D.Strings[50820]="赶快，我们离开这儿。"
D.Strings[50821]="野牛人去死吧！"
D.Strings[50822]="我们的大英雄！"
D.Strings[50823]="我们得救了！"
D.Strings[50824]="我们去滨岸村吧。"
D.Strings[50825]="嘿，看啊，是镇上新来的$G小伙子:小姑娘;。"
D.Strings[50826]="你对牦牛有研究吗，菜鸟？我可熟悉得很。"
D.Strings[50827]="你知道谷里谁家的蔬菜长得最大吗？远在天边，近在眼前！"
D.Strings[50828]="嘿，哥们，发生什么事了？"
D.Strings[50829]="嘿，哥们，随时欢迎你来欣赏我的牦牛。"
D.Strings[50830]="嘿，$r，看在哥们的情分上，我要跟你说个秘密。你想种出大个头的蔬菜吗？你得用肥料。$B$B那你知道谷里谁的肥料最好吗？我！"
D.Strings[50831]="嘿，朋友，怎么了？"
D.Strings[50832]="嘿，朋友，随时欢迎你来欣赏我的牦牛。"
D.Strings[50833]="嘿，朋友，告诉你个秘诀。你想种出大个头的蔬菜吗？你得用肥料。$B$B那你知道谷里谁的肥料最好吗？我！"
D.Strings[50834]="我的好朋友！农场的情况怎么样？"
D.Strings[50835]="我的好朋友，你今天过得好吗？$B$B听着，一般人我不告诉他——可如果你需要牦牛，就跟老方说一声。"
D.Strings[50836]="我的好朋友，告诉你个秘诀。你想种出大个头的蔬菜吗？$B$B你得细心照料它们。浇水、施肥，还要献出你的爱。"
D.Strings[50837]="嘿，邻居！农场一切都好？"
D.Strings[50838]="你好啊邻居，今天过得怎么样？$B$B毛毛好吗？"
D.Strings[50839]="嘿，邻居！那些蔬菜看起来真不错。"
D.Strings[50840]="嘿，你好！我以前见过你？"
D.Strings[50841]="嘿，你好！以前没在这附近见过你啊。"
D.Strings[50842]="嘿，城里人！你有没有什么有趣的故事跟我分享啊？我超爱讲故事！"
D.Strings[50843]="嘿，你有没有听过关于老农阿蓟的故事？那是我所听过的最好的故事了。"
D.Strings[50844]="嘿，你的名字为什么叫$n？这名字不怪吗？"
D.Strings[50845]="这里的人们心地善良……在这儿待久了你就会发现。"
D.Strings[50846]="我老爸常说鱼儿会游、鸟儿会飞。假如我既会游又会飞，那我成啥了？"
D.Strings[50847]="嘿，哥们！很高兴再次见到你。"
D.Strings[50848]="嘿，哥们！我很喜欢那个关于小男孩阿尔萨斯的故事。你还有其他故事分享吗？"
D.Strings[50849]="嘿，哥们！我很喜欢那个关于兽人萨尔的故事。你还有其他故事分享吗？"
D.Strings[50850]="老农阿蓟在那山上有一小块地皮。$B$B有一天他在那挖呀挖呀，也不知道自己挖了多深，突然发现在山底下居然有一个洞穴！$B$B你猜他在洞穴里发现了什么？"
D.Strings[50851]="你是说“玉儿”也是个怪名字？它一点儿也不怪，哥们！我的名字取自于湖里的那些鱼！$B$B现在说说你的名字“$n”是啥意思，啊？你倒是说啊！"
D.Strings[50852]="老爸常告诫我要多交朋友少结仇，那就是为什么你会是我哥们！"
D.Strings[50853]="嘿，朋友！很高兴再次见到你。"
D.Strings[50854]="嘿，朋友！再给我讲讲世界之树的故事和那个……啥来着……世界的分裂！"
D.Strings[50855]="你找到了……"
D.Strings[50856]="老农阿蓟发现了一个堆满金银财宝的洞穴！！！$B$B那里有黄金、钻石、翡翠、雕像，还有一整屋的古籍！$B$B他在洞穴里徘徊许久。很快，一整天就过去了，他感到非常饥饿。$B$B于是他就沿着来时的路往回走，却找不到回去的路了！"
D.Strings[50857]="一只丢失的母鸡！把她带回鸡笼。"
D.Strings[50858]="一只发情的公鸡！把他浸在水里，冷却下他的热情。"
D.Strings[50859]="一只野生农场小鸡！把它踢走！"
D.Strings[50860]="一只披着鸡毛的土拨鼠！让它现出原形！"
D.Strings[50861]="既然我们是朋友了，你可以叫我玉儿。$B$B哈哈！我真逗！$B$B我开玩笑的……每个人都叫我玉儿！因为每个人都是我的朋友！"
D.Strings[50862]="老农山掌的获奖小鸡——斑臀女士！"
D.Strings[50863]="老农山掌的获奖小鸡——雷啄！"
D.Strings[50864]="老农山掌的获奖小鸡——螳螂克星！"
D.Strings[50865]="老爸常告诫我——甜菜味虽美，友情价更高。那就是为什么你会是我的朋友，$n！"
D.Strings[50866]="老农山掌的获奖小鸡——鸣羽！"
D.Strings[50867]="老农山掌的获奖小鸡——肥蛋！"
D.Strings[50868]="你好，$n！"
D.Strings[50869]="老农山掌的获奖小鸡——抖翅！"
D.Strings[50870]="老农山掌的获奖小鸡——雄赳赳的贝蒂！"
D.Strings[50871]="嘿，我的好朋友！再给我讲讲那头可怕的巨龙——死亡之翼的故事！"
D.Strings[50872]="老农阿蓟被困在了洞穴里，于是他吹哨召唤他忠诚的穆山兽——波波！$B$B很快，他就听到了一声巨响，是波波在洞穴里炸出了一个洞！$B$B那头穆山兽听从了主人的召唤而来！$B$B而后，整个洞穴开始摇晃起来，洞顶开始坍塌。$B$B老农阿蓟跳上波波的后背，你知道后来发生了什么吗？"
D.Strings[50873]="知道吗，我的好朋友。我这辈子见过不少有趣的名字。玉儿真不算奇怪。不，一点儿都不奇怪！"
D.Strings[50874]="老爸常告诫我——萝卜虽爽口，友情价更高。那就是为什么你会是我的好朋友，$n！"
D.Strings[50875]="你好，邻居！你今天打算做啥？"
D.Strings[50876]="你好，邻居！我太爱听故事了，我真想把它们都听个遍！$B$B不过你知道的，我想我们一起编了不少好故事，不是吗？"
D.Strings[50877]="那洞穴开始坍塌，老农阿蓟和波波拼命跑！他们腾挪闪躲，在山洞中穿梭，直到在那山上破地而出！$B$B然后那个洞穴在他们身后合拢起来，就好像被大地吞没了一样。$B$B老农阿蓟浑身打颤，但是他到家做的第一件事就是给那个堆满财宝的洞穴画了一张藏宝图。因为那洞穴或许还在那儿，不是吗？$B$B他做了件正确的事，因为到了第二天，他就想不起来洞穴在哪儿了。接着又过了一天，他忘得更厉害了，后来就连那洞穴的事也忘得一干二净。"
D.Strings[50878]="嘿，邻居，我们到底在谈些什么啊？名字什么的无所谓啦！$B$B就像我爸常说的那样——即便你爱吃的粉瓜被叫作洋葱，你还是会吃的，对不？"
D.Strings[50879]="老爸常告诫我——土地诚可贵，友邻价更高。现在真被他说中了！$B$B那就是为什么你会是我的邻居，$n！"
D.Strings[50880]="我在这附近照看着几头猪。"
D.Strings[50881]="嘿，哥们！这些猪今天看起来不错嘛！"
D.Strings[50882]="你好，朋友！你下去见过我的猪了吗？"
D.Strings[50883]="你好，我的好朋友！为啥我爸妈没给我起名叫猪呢，我还挺费解的。"
D.Strings[50884]="嘿，邻居！你农场里的那些猪咋样？我敢打赌它们一定过得相当快活！"
D.Strings[50885]="你是新来的吗？"
D.Strings[50886]="嘿，吱吱真的很忙。你想要什么？"
D.Strings[50887]="吱吱的羊羊好怕怕……山里的坏猴子！坏猴子！"
D.Strings[50888]="嗨，我认识你。你帮过我，对吗？"
D.Strings[50889]="吱吱有大麻烦了。很大、很大的麻烦。"
D.Strings[50890]="吱吱为农场付出很多，现在被坏猴子夺走了！"
D.Strings[50891]="嘿，你是吱吱的哥们，对吗？"
D.Strings[50892]="吱吱遇到大麻烦了。很大、很大的麻烦。你能帮帮吱吱吗，哥们？"
D.Strings[50893]="吱吱为农场付出很多，你能明白的，对吗哥们？"
D.Strings[50894]="嘿，朋友。我遇到麻烦了，但又不想连累你。"
D.Strings[50895]="嘿，朋友，农场现在怎么样啦？"
D.Strings[50896]="吱吱是唯一一个有农场的猢狲！$B$B<吱吱骄傲地拍打自己的胸脯。>$B$B你，朋友，有空来转转，好吗？"
D.Strings[50897]="我的好朋友！有空来和吱吱喝两杯，怎么样？"
D.Strings[50898]="好朋友，你过得怎么样啊？"
D.Strings[50899]="吱吱的农场只有羊！$B$B谁想要羊，就来找吱吱。"
D.Strings[50900]="嘿，邻居！你喜欢羊吗？"
D.Strings[50901]="邻居，多亏你，我减轻了不少麻烦。"
D.Strings[50902]="我把我最好的羊给你，邻居！你觉得怎么样？"
D.Strings[50903]="哦！嗨！呃……我或许该……走……$B$B<艾拉红着脸，窃窃私语道。>"
D.Strings[50904]="你喜欢……芜菁吗？$B$B<艾拉脸红了，摇了摇头。>"
D.Strings[50905]="你喜欢猫咪吗？我喜欢！$B$B<艾拉为她的冒失愣住了，害羞地笑了笑。>"
D.Strings[50906]="嘿，你好啊，$n。今天过得怎么样？"
D.Strings[50907]="我在我家的农场里种芜菁。哦……我也不知道你想不想听那个……"
D.Strings[50908]="我的猫也没那么多，不是吗？我意思是，这么想还是说得过去的。"
D.Strings[50909]="嘿，你好啊，朋友！多好的天，不是吗？"
D.Strings[50910]="你知道吗？用芜菁酿出来的酒味道可好了。"
D.Strings[50911]="这些猫一直陪伴着我。自从我父母离世后，一个人在农场很寂寞……$B$B哦不，我并不想和你说这么多的。"
D.Strings[50912]="你好，我的好朋友。哦，我管你叫我的好朋友，你介意吗？"
D.Strings[50913]="我在闲暇时间会利用各种各样的酒来做实验。$B$B而且风暴烈酒酿造厂就在街对面，我有时更按耐不住了。$B$B哦，但是也没有其他地方能酿造出比这儿更好的酒了。"
D.Strings[50914]="我有多少只猫？$B$B噢，呃……我想我已经数不清了……"
D.Strings[50915]="你好，邻居！今早的芜菁看上去真不错啊。"
D.Strings[50916]="我将我的一些酒分享给镇子里的人，每个人都大加赞赏！我真是不敢相信！"
D.Strings[50917]="露娜还好吗？她可乖啦！"
D.Strings[50918]="前往寇塔营地的商队就要出发了！快集合！"
D.Strings[50919]="田里有麻烦啦。我告诉你，不论是兔妖还是猢狲，都不是什么好东西。"
D.Strings[50920]="没错，我就是阡陌客的首领。你为什么要问这个？"
D.Strings[50921]="的确，这里的农田非常肥沃，但这都缘于我们起早贪黑、没日没夜的辛勤劳作！"
D.Strings[50922]="嘿，哥们，你有没有对付猢狲或兔妖的经验？"
D.Strings[50923]="哥们，你知不知道每位风尘仆仆的农夫都是阡陌客的一员？"
D.Strings[50924]="嘿，要不是我的哥们$n！我恐怕要在农田里耗上一整天了。"
D.Strings[50925]="嘿，朋友，你有没有对付猢狲或兔妖的经验？"
D.Strings[50926]="嘿，朋友，今天的地看起来怎么样啊？"
D.Strings[50927]="$n，我的朋友！让我们来一起喝一杯吧。"
D.Strings[50928]="好朋友，你肯定知道一两个消灭兔妖的办法。"
D.Strings[50929]="知道吗，好朋友常常会分享他们的务农小秘密。现在告诉我吧，你是如何把你的蔬菜种成那样的？"
D.Strings[50930]="在田里劳作一整天，会让人口干舌燥。你懂我的意思吧，好朋友？"
D.Strings[50931]="嘿，邻居，那头穆山兽活儿干得怎么样啊？她可是个大美人，不是吗？"
D.Strings[50932]="既然我们现在成邻居了，你得告诉我你的务农小秘密。你用化肥了？增长素？除草剂？快告诉我嘛！"
D.Strings[50933]="你好，邻居。想来杯冰镇啤酒吗？"
D.Strings[50934]="谢谢你，旅行者。我觉得我现在能行了。"
D.Strings[50935]="我可没时间和陌生人打交道。现在请你离开。"
D.Strings[50936]="没看到我正忙吗？我在做事情呢，陌生人。"
D.Strings[50937]="你打赢了场景战役。万岁！"
D.Strings[50938]="呸！让老头我清静清静！"
D.Strings[50939]="非常感谢。我现在该回去训练了。"
D.Strings[50940]="唉，我很忙，你看不到吗？"
D.Strings[50941]="你总是这么烦人吗？真是的。"
D.Strings[50942]="呸！我知道我见过你，但那并不意味着我们是朋友。快滚！"
D.Strings[50943]="一点皮肉伤而已，轻伤不下火线嘛。"
D.Strings[50944]="嘿，哥们，我现在很忙。你能过会儿再来吗？"
D.Strings[50945]="哥们，你可真是个话痨。你嘴巴啥时候闲过？"
D.Strings[50946]="哥们，你知道某些时候……还是很高兴见到你的。"
D.Strings[50947]="嘿，朋友，我有点小忙。我这儿有你需要的东西吗？"
D.Strings[50948]="朋友，你真是一逮到机会嘴巴就说个不停。不过时不时的听人唠叨两句总比死一般的沉寂要好多了。"
D.Strings[50949]="我有三只生病的小鸡和两只不下蛋的母鸡。我自己都焦头烂额了，哪还有心思管你，城里人。"
D.Strings[50950]="嘿，哥们。昨晚我有两只小鸡失踪了，我敢打赌是猢狲干的好事。"
D.Strings[50951]="你好，朋友。有没有尝过我家的新鲜鸡蛋啊？超美味的，我跟你说。"
D.Strings[50952]="嘿，朋友，感谢你今天的来访。"
D.Strings[50953]="嘿，这不是我的好朋友$n嘛！我能帮你什么忙吗？"
D.Strings[50954]="我的好朋友，你今天给我带什么消息了吗？"
D.Strings[50955]="你知道吗，$n，我得承认我偶尔会盼望你的到来。"
D.Strings[50956]="嘿，$n，我一直在想你的农场是否需要一些小鸡。你认为呢？"
D.Strings[50957]="你好，邻居。今天天气不错啊。"
D.Strings[50958]="嘿，邻居！今天地里看起来就像是一枚闪闪发光的新铜币。"
D.Strings[50959]="你好，邻居！很高兴见到你！你随时都可以来找我，听到了吗？"
D.Strings[50960]="你好吗，$n？那些小鸡还好吗？$B$B一定要仔细找找它们的蛋，那些该死的小家伙就喜欢把蛋藏在最古怪的地方！"
D.Strings[50961]="安静，陌生人。我需要集中精神来完成手头的任务。"
D.Strings[50962]="我对你没什么意见，陌生人。"
D.Strings[50963]="只有在寂静中，我们才能听到林木间的窃窃私语。"
D.Strings[50964]="安静，$r。请别分散我的注意力。"
D.Strings[50965]="我在这一带见过你。我能从你这身行头上看出来，你是一个$c。"
D.Strings[50966]="能说会道只能得点小聪明，善于倾听才会明白大智慧。"
D.Strings[50967]="嘿，哥们，你弄出来的噪音都能把一群穆山兽给吓跑了。"
D.Strings[50968]="别跟我讲什么样才算一个$c，露两手给我瞧瞧。"
D.Strings[50969]="我在研究猢狲的动作。等我找到他们的弱点时，我就会出击。"
D.Strings[50970]="我的朋友，你弄出来的噪音都能把一群穆山兽给吓跑了。"
D.Strings[50971]="我的朋友，总有一天我们要弄清楚谁更厉害——是你，还是我。"
D.Strings[50972]="智者不会仓促行事。智者运筹帷幄、决胜千里。"
D.Strings[50973]="我的好朋友，你弄出来的噪音都能把一群穆山兽给吓跑了。"
D.Strings[50974]="我的好朋友，总有一天我们要弄清楚谁更厉害——是你，还是我。"
D.Strings[50975]="在我的家乡，一个人能送给好朋友的最好的礼物，就是一棵树了。$B$B你知道为什么吗？$B$B树代表了和平、成长和生命。它是对友情的一种祝福。"
D.Strings[50976]="邻居，你今天手脚蛮轻得嘛。"
D.Strings[50977]="邻居，我会很高兴和你并肩作战的，无论何时。"
D.Strings[50978]="你喜欢这颗树吗？树苗可是我亲自挑选的。"
D.Strings[50979]="嘿，朋友，你知道做成好买卖的诀窍吗？那就是销售。你需要一条渠道，将你的货物卖到需要的人手中。"
D.Strings[50980]="你知道我在想什么吗，我的好友？你需要一个方法，能够在家中和你所有的朋友保持联系。$B$B我认识一个木匠，他可以上门帮你安装邮箱。这主意不错吧。"
D.Strings[50981]="那邮箱用起来感觉如何啊？是个不错的主意吧？"
D.Strings[50982]="嘿，朋友，你不觉得农夫老愚的房子看起来空荡荡的吗？"
D.Strings[50983]="我对家居装潢略知一二，我的好朋友。我知道农夫老愚的房子缺什么！"
D.Strings[50984]="嘿，邻居！你觉得农夫老愚家里的新家具看起来如何啊？没错，那都是我亲自挑选的！"
D.Strings[50985]="吱吱爱吃谷地小炒。你要是找到了，就带给我！"
D.Strings[50986]="不管你做什么，只要能够帮伤员重新站起来，我们都感激不尽。"
D.Strings[50987]="吱吱喜欢看天空，那么美……那么蓝……"
D.Strings[50988]="噢，礼物？我还以为你没打算送我东西呢！"
D.Strings[50989]="你了解我的……我喜欢猫！"
D.Strings[50990]="既然你提到了……我妈做的虾饺最好吃了。$B$B唉……我好想她……"
D.Strings[50991]="你知道吗，我唯一赞赏的是一种生长在这附近的稀有的白色百合，它们和我的外表不分伯仲。$B$B可是，它非常难得。"
D.Strings[50992]="你吃过香烤野雉吗？$B$B嗯！我真想立刻尝上几口！"
D.Strings[50993]="的确，我是很博爱，但我最喜欢的还是动物！"
D.Strings[50994]="充分的储备常常能扭转不利的战局。$b$b我已经把从林子里采来的草药调好了，但愿这些能够用。在战场上，我们需要所有能够战斗的人全部上场。"
D.Strings[50995]="你知道吗，我一直都很喜欢玉石的颜色。如此翠绿，就和那森林一样。"
D.Strings[50996]="多傻的问题啊！我给你个提示吧。我最喜爱的食物里有我的名字！或许还不止一个哦！"
D.Strings[50997]="哦，你不必啦！哦，但我确实喜欢礼物，所以……或许……你还是送吧。"
D.Strings[50998]="我喜欢所有漂亮的或是闪闪发光的东西。"
D.Strings[50999]="哦，你了解我的。我是个谦逊的女孩，所以我只想要些红宝石。$B$B什么？我又不是跟你要钻石！"
D.Strings[51000]="好吧，最近我特别想吃焰灵鲑鱼。"
D.Strings[51001]="我可没骗你哦，$n。我是这谷里数一数二的大人物。大多数人都会送我非常贵重的礼物。"
D.Strings[51002]="我要告诉你一件事，$n。我喜欢玉石，但那不是我的最爱。所有人都给我玉石，老是这样！"
D.Strings[51003]="既然你提到了，我想吃碳烤虎肉排都想了好久了！我们谷里并没有多少老虎，所以这盘菜不是那么好搞的哦。"
D.Strings[51004]="不，像我这么一个老头已不需要任何东西了。但我的儿子……他现在喜欢收集蓝色羽毛……"
D.Strings[51005]="每当我的儿子找到一根蓝色羽毛时，常会说那是他在天国的妈妈，给他的一个吻。$B$B<老农山掌停顿住，因为哽噎无法继续。>"
D.Strings[51006]="我妻子常会做一道美味的炖龟肉，那味道一定能带来美好的回忆。"
D.Strings[51007]="我喜欢纯天然的东西。"
D.Strings[51008]="干我们这行的女孩常会感到饥饿，你知道吗？我真希望我有好东西吃。"
D.Strings[51009]="花是很美，但那不是我的最爱。"
D.Strings[51010]="我害怕鸟！它们的羽毛的确很艳丽，但那不是我的最爱。"
D.Strings[51011]="你有没有吃过锦绣鱼？那是我的最爱。"
D.Strings[51012]="这真是太可爱了，谢谢你！"
D.Strings[51013]="看看这些新兵能否接受挑战。他们需要在战斗之前先积累些经验。"
D.Strings[51014]="哦，为什么……谢谢你……你没必要……！"
D.Strings[51015]="猢狲小炒！谢谢你老大！"
D.Strings[51016]="哦，吱吱饿了。多谢！"
D.Strings[51017]="哦，太美了，太美了！那么蓝……那么软……谢谢！"
D.Strings[51018]="非常好，是的，是的……一件送给吱吱的好礼物。谢谢你！"
D.Strings[51019]="嘿，这真是一件好礼物啊。谢谢，$n！"
D.Strings[51020]="你一定是我的神秘崇拜者！好吧，现在没那么神秘了。多谢！"
D.Strings[51021]="你找到了泽地百合？这些是我的最爱。谢谢你！"
D.Strings[51022]="这烤肉是给我的？哇，谢谢！"
D.Strings[51023]="来的正是时候，我刚好感到饿了。"
D.Strings[51024]="这份鸳鸯鱼拼盘是你做的？"
D.Strings[51025]="我的老天，这份鸳鸯鱼拼盘闻着太诱人了。谢谢你！"
D.Strings[51026]="让我们瞧瞧猢狲准备在战斗中弄什么鬼吧。"
D.Strings[51027]="没错，这是我最爱的食物——鱼！"
D.Strings[51028]="真是一只漂亮的小猫，$n。谢谢你把它送给我。"
D.Strings[51029]="哇，你要把它送给我？我都不知道该怎么感谢你了！"
D.Strings[51030]="你要送我一个礼物？哈哈谢谢啦，你太客气了！"
D.Strings[51031]="这是什么？哦，管它呢，真是好东西……嗝！"
D.Strings[51032]="为什么$n！你给我带了一些迷雾汤？你不知道我爱死这东西了吗？"
D.Strings[51033]="哦，多么令人惊艳的花啊。你知道这些代表了幸运吗？"
D.Strings[51034]="我的老天，你要送我东西？我该如何感谢你啊？"
D.Strings[51035]="瞧啊，你给小老太吉娜送了一个这么可爱的礼物。谢谢你！"
D.Strings[51036]="这个焰灵鲑鱼看起来很美味。我希望这是你亲手做的。"
D.Strings[51037]="哦，我等不及要尝尝这个焰灵鲑鱼了。"
D.Strings[51038]="你为何如此懂得取悦一名女士的！虽然不是钻石，但我就是喜欢！"
D.Strings[51039]="这颗红宝石配这身衣服真是太美了，你觉得呢？"
D.Strings[51040]="你还惦记着我，真是太可爱了。"
D.Strings[51041]="你真是一个好$G小伙:姑娘;，$n。谢谢你送我的可爱礼物。"
D.Strings[51042]="哦，这颗红宝石看起来价值不菲。谢谢你，$n！"
D.Strings[51043]="自从我上次吃过碳烤虎肉排到现在已经很长时间了。"
D.Strings[51044]="我能一口气吃掉20盘碳烤虎肉排，而且还想吃更多。谢谢，$n。"
D.Strings[51045]="哇，这是我今天所接受到的最好的礼物了！"
D.Strings[51046]="给我的？你真是太好了，$n。"
D.Strings[51047]="这根羽毛……给我带来很多回忆。谢谢你，$n。"
D.Strings[51048]="这跟我妻子的做法如出一辙。谢谢！"
D.Strings[51049]="这正是一个饥肠辘辘的老头所需要的。谢谢。"
D.Strings[51050]="给我的？谢谢。"
D.Strings[51051]="你真是……太好了。谢谢。"
D.Strings[51052]="谢谢你的苹果，$r。"
D.Strings[51053]="嘿，这正是我想要的。多谢啦。"
D.Strings[51054]="我有一阵子没吃过这道菜了，这回可要过瘾了。"
D.Strings[51055]="期待一顿热饭热菜的感觉真是太美妙了。"
D.Strings[51056]="哈，我想我现在该向你表达我的谢意了。"
D.Strings[51057]="注意那些火。不——等等——抓住那个蜥蜴人！快……做点什么啊！"
D.Strings[51058]="在那些饭桶完成他们的工作之前，我是不会离开的。"
D.Strings[51059]="愚蠢的蜥蜴人。"
D.Strings[51060]="或许这会管用……"
D.Strings[51061]="我会帮你的……"
D.Strings[51062]="你可别死在我这儿！"
D.Strings[51063]="只要我们携起手来，就能重新夺回寺庙，使这里的人民重获希望。很荣幸能与你并肩完成这项任务。"
D.Strings[51064]="所有第七舰队的船都爆炸了。轰隆！炮舰开进港了。"
D.Strings[51065]="我们逃不掉了！"
D.Strings[51066]="啧啧。真是美味！"
D.Strings[51067]="把所有东西都给我煮了。"
D.Strings[51068]="嗯……也许是一小撮熊猫人？"
D.Strings[51069]="这炖菜还需要加点盐。再加些人肉丸子！"
D.Strings[51070]="炒，炒，炒！"
D.Strings[51071]="去毛，去毛，去毛。"
D.Strings[51072]="太多菜根了！得加点儿肉才行！"
D.Strings[51073]="杀死那个卑鄙的瓦尔蒙，带回来炖汤喝！"
D.Strings[51074]="嗯，听到动静了吗，伙计们？"
D.Strings[51075]="嗯！再加点$r进去！"
D.Strings[51076]="什么？不……不！停！听主人的命令！"
D.Strings[51077]="%s服从它主人的命令，开始攻击。"
D.Strings[51078]="大厨，你能帮我烤一下这个平原鹰腿吗？"
D.Strings[51079]="大厨……如果我带一个平原鹰腿给你，你能帮我烤一下吗？"
D.Strings[51080]="当然了，$n！尽情享用吧！"
D.Strings[51081]="当然了。如果你给我带些肉回来——尽管你现在没有——我会帮你烤的。"
D.Strings[51082]="我这里有各种各样的水果，你能帮我酿些果酒吗？"
D.Strings[51083]="酿造莓果烈酒需要什么材料啊？"
D.Strings[51084]="需要帮忙，尽管开口，邻居。"
D.Strings[51085]="我们至少需要8只苹果，还有一些蔓越莓——50个差不多了。"
D.Strings[51086]="在这里酿造！"
D.Strings[51087]="朋友，我们洞穴里见。"
D.Strings[51088]="嘿，贾古，明天的收成会怎么样啊？"
D.Strings[51089]="呃……我脑袋晕乎乎的……一会再说吧。"
D.Strings[51090]="哦……哦！我感到刺痛无比！我看见……巨大的绿色卷心菜……在你的未来里。"
D.Strings[51091]="你听说过爽脆胡萝卜吗？它们明天会变得更加爽脆。"
D.Strings[51092]="我有没有告诉过你我讨厌葱？我讨厌它们！$B$B<贾古打了个响嗝儿。>$B$B可不幸的是，明天将是它们的生长旺季。"
D.Strings[51093]="南瓜！会长出巨大、无比大的南瓜！"
D.Strings[51094]="种下一份韭花，你也许能收获两份。"
D.Strings[51095]="我在你的未来里看到了粉色芜菁。"
D.Strings[51096]="地里长满了白色芜菁。脆爽劲辣！"
D.Strings[51097]="你该种植哪种浆果？当然是女巫浆果啦！"
D.Strings[51098]="碧玉瓜有着温润如玉的色泽。我想……明天会是种植这种蔬菜的好日子。"
D.Strings[51099]="每年一到这个时节，菜瓜就变得多汁爽口！把种子撒在地里，天亮就能收获果实。"
D.Strings[51100]="你想吃肉？我这里有很多。$b$b我的意思是，在我的烤架上。"
D.Strings[51101]="在我冥想时挡住那些精怪。我们很快就能找到答案了。"
D.Strings[51102]="<那鹤并没有开口，可他的话语却充满你的脑海。>$B$B趁还来得及……快走……$B$B一切都已……无可挽回。"
D.Strings[51103]="<伸手碰触赤精。>"
D.Strings[51104]="你摇响了神龛上的铃铛。你现在可以向它提问，许愿也行！"
D.Strings[51105]="吱吱是位猢狲牧羊人，就在西边的梯田上工作。"
D.Strings[51106]="你和艾拉成了熟人。"
D.Strings[51107]="不知不觉之中，你和农夫老方竟成了熟人。"
D.Strings[51108]="你和玉儿成了熟人。"
D.Strings[51109]="你和吉娜成了熟人。"
D.Strings[51110]="你和郝瀚成了熟人。"
D.Strings[51111]="你和老农山掌成了熟人。"
D.Strings[51112]="你和阿烁成了熟人。"
D.Strings[51113]="你和迪娜成了熟人。"
D.Strings[51114]="你和醉鬼贾古成了熟人。"
D.Strings[51115]="我和吱吱的关系怎么样？"
D.Strings[51116]="我和艾拉的关系怎么样？"
D.Strings[51117]="我和玉儿·采苇的关系怎么样？"
D.Strings[51118]="我和农夫老方的关系怎么样？"
D.Strings[51119]="我和吉娜·泥爪的关系怎么样？"
D.Strings[51120]="我和醉鬼贾古的关系怎么样？"
D.Strings[51121]="我和郝瀚·泥爪的关系怎么样？"
D.Strings[51122]="我和老农山掌的关系怎么样？"
D.Strings[51123]="我和阿烁的关系怎么样？"
D.Strings[51124]="我和迪娜·泥爪的关系怎么样？"
D.Strings[51125]="当一个人有求于一条鱼的时候……"
D.Strings[51126]="往往只是因为他想要找一条肥硕的鱼……"
D.Strings[51127]="来端上餐桌……"
D.Strings[51128]="呜呼，人为刀俎，我为鱼肉！"
D.Strings[51129]="嘿，吱吱，愿意到我的农场来做帮手吗？"
D.Strings[51130]="嘿，艾拉，愿意加入我和农夫老愚的农场吗？"
D.Strings[51131]="嘿，玉儿，愿意做我农场的合伙人吗？"
D.Strings[51132]="你好，农夫老方。我和农夫老愚的农场真的很需要你。"
D.Strings[51133]="吉娜，愿意帮我们运营农场吗？"
D.Strings[51134]="泥爪先生，您愿意帮我们打理日歌农场吗？"
D.Strings[51135]="嘿，贾古，你愿不愿意搬到日歌农场的池塘去？"
D.Strings[51136]="你好，老农山掌。到我的农场来和我作伴如何啊？"
D.Strings[51137]="嘿，阿烁。休息一下，来我的农场帮我看会庄稼吧。"
D.Strings[51138]="嘿，迪娜，我听说农夫老愚的农场需要点帮助。你能否……？"
D.Strings[51139]="好的，老板！吱吱还有事要做，过会就去。"
D.Strings[51140]="没问题，我觉得我能帮上点忙！我一会儿去那找你。"
D.Strings[51141]="我爸爸经常说助人为快乐之本！我手头还有些事要处理，回头一忙完就去找你！"
D.Strings[51142]="我还在想你什么时候会问我呢。没问题，等我料理完这边的事后，我马上过去。"
D.Strings[51143]="那么好吧，我想我时不时的可以去农场帮忙。我只是看在你的面子上，你懂吗？好吧……我想这回我也给了老愚先生一个大大的面子……"
D.Strings[51144]="真的？整个池塘，都是我的？我马上就去！"
D.Strings[51145]="我想我可以把这里交给蒙蒙看管一会儿，我去老愚那边转转。他的确有着整个谷里最肥沃的土地！先让我把手头的事情理理顺。"
D.Strings[51146]="我想我的小鸡是不会介意我出去串会儿门的。我一会就去找你。"
D.Strings[51147]="日歌农场需要我帮忙吗？让我去拿装备，我会去那里找你。"
D.Strings[51148]="正好是你要求的时间！我正在考虑农夫老愚什么时候才会想到我。你先去吧，我很快就到。"
D.Strings[51149]="嘿，老板，我一直在想。你对吱吱真好，所以我想送只羊给你。羊已经准备好了，你会好好照顾吱吱的羊，对吗？"
D.Strings[51150]="嘿，等一等……我……好吧……你是我的好友……我想把我最爱的猫咪——露娜，送给你！我不想你在农场里感到孤单寂寞……<呜咽>……一定要好好照顾她，记住了吗？我稍后会把她送过来。"
D.Strings[51151]="好吧，既然我们现在是好邻居了，我也就实话实说了。你的农场里没有一两头猪真是太不像话了！等你回头想明白了，我会带几头猪给你！你会有猪的。"
D.Strings[51152]="既然我们现在是邻居了，我决定送你一个作为邻居所能送出的最好的礼物！我打算送你一头珍贵的牦牛！我一会儿就把它送到你的围栏里。"
D.Strings[51153]="我和你现在成邻居了，不光从地理角度上来讲。你为我做了很多事，我想是时候回馈你的友情了。我请人帮忙在你的农场装了一个邮箱，现在你可以通过邮箱和所有的朋友保持联系了！"
D.Strings[51154]="你刚来谷里的时候，我对你还不太了解，但现在我可以自豪的管你叫邻居了。作为代表我们友情的象征，我想给你的农场送一件大礼，她可能已经在那里了。她的名字叫菲菲小姐，她喜欢吃芜菁哦！"
D.Strings[51155]="知道吗，你作为我的朋友已经有些日子了。既然我们现在成了邻居，我打算送你一些小鸡。虽然不多，但他们会让你的农场显得更有生气。我一会儿把他们送过来。"
D.Strings[51156]="等一下。我一直在想……你为我做了这么多事，是时候给你一些东西来作为回报了。在我们那儿种着美丽的橘子树，我在你的农场里种了一棵。从这周围的生长态势来看，等你回到农场时那棵橘子树已开满鲜花，我也不会感到惊讶的。"
D.Strings[51157]="哦，$n，作为你的挚友，我真想送你些东西。我觉得你的农场需要一点装饰，所以我找人给你家装了些新家具。希望你会喜欢！"
D.Strings[51158]="我能雇人帮忙打理农场吗？"
D.Strings[51159]="只有挚友才行。"
D.Strings[51160]="嘿，老板，你的羊看起来很不错哦。"
D.Strings[51161]="哦……为什么，你好，$n！你的农场今天看起来很不错啊。"
D.Strings[51162]="你好，邻居！你的猪看上去很不错啊！"
D.Strings[51163]="我不得不说，$n，你的园子看起来太棒了！当然了，因为我每天都在帮你除草……"
D.Strings[51164]="农夫老愚真可爱！我叫他做什么，他就做什么！"
D.Strings[51165]="这池塘真是太棒了，邻居。"
D.Strings[51166]="不赖，不赖！我凭良心讲，你的农场搞的真不赖。或许有一天，你会像郝瀚·泥爪一样成功呢！"
D.Strings[51167]="你好，邻居。你的小鸡看起来很开心啊。"
D.Strings[51168]="都搞定了，$n，但不要放松警惕。那些兔妖挖洞速度比你说“兔妖挖洞！”这几个字还快。"
D.Strings[51169]="哦，农夫老愚真是一位绅士！他甚至还说他很喜欢那些新家具！"
D.Strings[51170]="欢迎，旅行者！来点麦芽酒吧。"
D.Strings[51171]="我们在这里已经很少能见到新面孔了。"
D.Strings[51172]="已经没有多少人有勇气穿越山脉了，朋友。如今，某些人会说你一定是疯了才要这么干。"
D.Strings[51173]="进来暖和暖和，朋友。不要太拘束！"
D.Strings[51174]="哦！一位新客人！非常欢迎你，朋友！"
D.Strings[51175]="嘿，邻居。既然你是我这么要好的朋友，从现在起，我将免费给你提供收成预测。绝对免费！只要时不时的来跟我喝两杯，怎么样？"
D.Strings[51176]="炼金跟魔法有点像，不是吗？只要略作增减，其效果就会从妙手回春，变成杀人不眨眼。"
D.Strings[51177]="我这里卖的都是既神奇又难得的宝贝。快来瞧瞧吧，不过别乱碰。"
D.Strings[51178]="补给品有限，可我只从贸易者手中购买最好的货物。"
D.Strings[51179]="是谁，胆敢打扰我永恒的沉睡？！"
D.Strings[51180]="高山发怒了，陌生人。现在可不适合出行。"
D.Strings[51181]="今天可是旅行的吉日啊，朋友！东风吹来了好运气。"
D.Strings[51182]="我不叫岑——我是陈·风暴烈酒！"
D.Strings[51183]="告诉我，这里发生了什么事？"
D.Strings[51184]="风暴烈酒家的其他人去哪儿了？这里怎么都是猢狲？"
D.Strings[51185]="风暴烈酒大婶……酿酒厂怎么没人管了？"
D.Strings[51186]="你打倒了乌克乌克……"
D.Strings[51187]="你知道那意味着……"
D.Strings[51188]="你是新乌克！"
D.Strings[51189]="乌克！乌——克！"
D.Strings[51190]="神鹤大师！你还好吗？"
D.Strings[51191]="乌克的派对开始啦！"
D.Strings[51192]="我们要闹上一整晚！"
D.Strings[51193]="你正在离开翠绿草场。你的牦牛快失控了！"
D.Strings[51194]="让我们开始闪电派对吧，布兰琪。"
D.Strings[51195]="什么？发生了什么事？"
D.Strings[51196]="我们做到了！"
D.Strings[51197]="看来终究还是希望占了上风……"
D.Strings[51198]="没有时间庆祝了——现在还有很多赤精之道的信徒在外面战斗。"
D.Strings[51199]="到寺庙庭院中心的雕像附近与我会面。我们在那谈谈。"
D.Strings[51200]="我们决不能向绝望低头。"
D.Strings[51201]="看哪，育温，是个$c。你是来帮忙的吗，$c$g先生:小姐;？"
D.Strings[51202]="情况怎么样？你会救出我的同胞们的，对吧？"
D.Strings[51203]="我很久没见过那样的战斗了，自从……嗯，应该说，我从来就没见过那样的战斗。你可真是个高手啊，$n。"
D.Strings[51204]="快看啊妈，$n回来了。你怎么没找到我的牦牛？"
D.Strings[51205]="你找到它们了，$n！来。我们只要把它们关进围栏里就行了。"
D.Strings[51206]="妈，快看是谁来了，是$n。我们刚才正谈论你呢。"
D.Strings[51207]="距离我们上一次交谈，竟然已经过去那么多时间了。"
D.Strings[51208]="我知道，我知道。托你的福，我们在这里占了上风，很快就能把那些该死的野牛人赶走了。但话说回来，要是你想再亲手打碎几个脑壳，我也没意见。"
D.Strings[51209]="$n！你有什么好消息要告诉我们吗？我敢打赌，你肯定又有许多新鲜刺激的冒险故事可说了。"
D.Strings[51210]="育温，$n回来了。我们给$g他:她;准备好大餐了吧？嘿嘿，你听懂了没？周？"
D.Strings[51211]="野牛人还在农场上作乱，这说起来可真丢人啊。但你得清楚一点……我可不是像你那么威风的$c。对我们这种普通人来说，处理这些是需要时间的。嗯，我其实可以直接让育温去打烂他们的脑袋。但我不想让她出手，你懂的。"
D.Strings[51212]="[DEBUG ONLY]攻击$n!"
D.Strings[51213]="$n，全潘达利亚最有名的$r$c！快过来，给老周一个拥抱！"
D.Strings[51214]="现在继续吧。你还有更重要的事情要做，别浪费时间造访我们这些人。不过，你来的时候，有没有看见那个在野外疯跑的卑鄙的瓦尔蒙？"
D.Strings[51215]="干得好！这对付猢狲的办法比我预想中的还要简单。"
D.Strings[51216]="%s小声嘀咕。"
D.Strings[51217]="%s看起来不感兴趣。"
D.Strings[51218]="%s撇了你一眼，又是皱眉又是吐唾沫。"
D.Strings[51219]="%s叹了口气，显然被整体事态激怒了。"
D.Strings[51220]="胆小鬼们……让我来好好招待你们。"
D.Strings[51221]="靠近点儿……离死亡再近点儿。"
D.Strings[51222]="%s一边注视着农场上不断涌现的不速之客，一边向她的丈夫挥手告别。"
D.Strings[51223]="%s低声啜泣着，以为没被任何人发现，然后才擦干眼泪，再次坚定地站了起来。"
D.Strings[51224]="%s只是看着你。"
D.Strings[51225]="%s盯着卑鄙的瓦尔蒙摧毁她田地的疯狂举动，对丈夫的话充耳不闻。"
D.Strings[51226]="一股致命的寒冰之潮开始横扫过房间！"
D.Strings[51227]="指导者寒心的灵魂向她的护命匣逃去。摧毁它！"
D.Strings[51228]="让你看看我的力量。"
D.Strings[51229]="来我这里，翔龙！让我们一起消灭这些入侵者。"
D.Strings[51230]="碧空翔龙开始攻击！"
D.Strings[51231]="碧空翔龙冲向了远处！"
D.Strings[51232]="啊！救命！那是什么！？没关系，谁也阻止不了我，我就要成功了！如果我不看的话……？"
D.Strings[51233]="没错！好的，好的！快成功了！只要一点……噢……"
D.Strings[51234]="太苦了！再加一滴蜂蜜，一块糖，也许再加点玉米？没错，玉米！"
D.Strings[51235]="对了，是的，是的……不！不不不！对了！不对！胡椒！"
D.Strings[51236]="这……难道就是？？？"
D.Strings[51237]="风暴烈酒的美名必将再次响彻群山！"
D.Strings[51238]="又是你！你没看到吗？我终于要出名了：我酿出了完美之酒！"
D.Strings[51239]="下一步，我们要给酒发酵！小心点！"
D.Strings[51240]="最后一步，加热！闻闻那香气！"
D.Strings[51241]="酒的成分太混乱了！我不知道要是现在把它们合在一起，会发生什么事！"
D.Strings[51242]="唷！我得喘口气。我们在这儿歇一会吧？"
D.Strings[51243]="看那边！雷掌阁正在遭受攻击！"
D.Strings[51244]="没时间休息了。快！我们得帮帮他们！"
D.Strings[51245]="作战山羊，冲吧！"
D.Strings[51246]="山羊要踩扁蠢蛋！"
D.Strings[51247]="山羊山羊，踏碎蠢蛋！"
D.Strings[51248]="作战山羊！停下！"
D.Strings[51249]="作战山羊！猢——狲！"
D.Strings[51250]="肘锤猢狲会干掉那些蠢蛋！"
D.Strings[51251]="呐——呐——呐呐呐呐！作战山羊！"
D.Strings[51252]="干掉那些家伙！"
D.Strings[51253]="蠢蛋紧追不舍！"
D.Strings[51254]="蠢蛋抢到果子了！抢果子！"
D.Strings[51255]="抢啊！"
D.Strings[51256]="很快就要有更多土地精启程前往寇塔营地了。要想帮忙就待在这儿！"
D.Strings[51257]="弟兄们！赶走这些傲慢之徒！"
D.Strings[51258]="影踪派火箭手出现在屋顶！"
D.Strings[51259]="影踪派弓箭手消失了！"
D.Strings[51260]="我在地图上给你指出土地精现在在哪里。要么去找他们，要么就待在这里等下一拨土地精。"
D.Strings[51261]="我的种子长出的菜是谷里最好的，我保证！"
D.Strings[51262]="我来这儿是为农夫老愚挑选种子的。"
D.Strings[51263]="老愚？没听说过……"
D.Strings[51264]="他刚刚继承了日歌农场。从你现在所站的位置就能看见他。"
D.Strings[51265]="噢，当然！日歌农场，就在那边。我还好奇谁会搬进那去呢。$B$B<绿野斜眼向你肩后瞥了一眼，并向老愚挥了挥手。>$B$B等你带着大家从没见过的最大、最鲜美的蔬菜回市集时，你就告诉他们你是在哪儿搞到的种子！"
D.Strings[51266]="突袭者加杜卡准备发动一次扫射！"
D.Strings[51267]="城门即将陷落。快！杀光这些暴徒！"
D.Strings[51268]="以赞达拉之力，我命令你站起来！"
D.Strings[51269]="[异星语]Klatu，Barada，Nikto！"
D.Strings[51270]="[咒文]Piertotum Locomotor（即刻起身）！"
D.Strings[51271]="[魔古语]Cong siwang shangsheng，mogu！"
D.Strings[51272]="身起魂尸，令律如急急！"
D.Strings[51273]="元神归位，起！"
D.Strings[51274]="从休眠中醒来吧，我的魔古朋友们。让我们一起粉碎这片土地。"
D.Strings[51275]="消灭那些胆敢阻止我们重夺这片土地的人。"
D.Strings[51276]="你？！我对你知道得一清二楚。我的魂能很强大。你阻止不了赞达拉部族！"
D.Strings[51277]="一定要全力以赴，$n。雷掌阁需要我们。你准备好了结此事了吗？"
D.Strings[51278]="我们去杀几条蜥蜴人吧，布兰琪！"
D.Strings[51279]="当你准备好进去时就告诉我……"
D.Strings[51280]="让我们做回大英雄吧！"
D.Strings[51281]="最后一次警告，你们这些舌头分叉的爬虫！"
D.Strings[51282]="你们不必滚回老家，但也不准留在这里。"
D.Strings[51283]="蹒跚花苗开始向正前方喷吐秽臭气体。"
D.Strings[51284]="一件干净的武器表明它的主人并没有经历过战斗。"
D.Strings[51285]="你好，朋友！想听我介绍一桩一生难遇的好买卖吗？"
D.Strings[51286]="武器应该是战士身体的一部分。像爱惜你自己一样，爱惜你的武器，它就不会让你失望。"
D.Strings[51287]="找到遗物了吗，$n？但愿那些魔古雕像没给你造成太大的麻烦。"
D.Strings[51288]="好多魔古遗物啊。我们要发大财了！"
D.Strings[51289]="我正想鼓起勇气去找更多遗物呢。你觉得怎么样，$n？"
D.Strings[51290]="只要等我找到合适的时机返回城镇并找到买家，那些遗物就能为我换回一大堆金币。"
D.Strings[51291]="我敢打赌，要是我死守在外围，就能在废墟间自由进出，顺手拿上几件遗物，还能避开那些雕像。"
D.Strings[51292]="噢天呐，$n，这些魔古脑袋正在瞪着我呢！"
D.Strings[51293]="$n，有趣的是，魔古岬这里的魔古族原本并不是陶俑。他们是在自己的君主光荣战死后，被殉葬活埋的。"
D.Strings[51294]="有趣的是——魔古岬是取自“魔古之家”的谐音。但千万别信以为真，他们可并非只有这一个家。这只是人们赋予这地方的名字罢了。我做过一些研究，发现这里原本叫周家堡。诡异得很。一定跟农夫老周的名字存在着某种巧合。"
D.Strings[51295]="你查明赞达拉巨魔为什么要复活这里的雕像了吗？"
D.Strings[51296]="卷心菜马上就好了……稍等一下……"
D.Strings[51297]="我们上！可以采摘了！"
D.Strings[51298]="有没有弄到更多的莲花熏香？"
D.Strings[51299]="还没见着呢。我开始怀疑我们是否能够爬上这座山。"
D.Strings[51300]="堂弟破烂骰在搞走我所有辛苦挣来的钱和货物！我早该知道不能相信一个土地精的。绝不能相信任何只有你一半高的东西……"
D.Strings[51301]="前往粗麻驿站的商队就要出发了！快集合！"
D.Strings[51302]="为了财富！"
D.Strings[51303]="土地精们！过来深吸几口旅者熏香吧。它能让你的粗麻驿站之旅好运相伴！"
D.Strings[51304]="土地精！都过来吸一口旅者熏香，带着好运前往寇塔营地！"
D.Strings[51305]="击败白骨编织者以帮助莉莉安·沃斯！"
D.Strings[51306]="土地精之力！"
D.Strings[51307]="不！别拿走我的幸运符！"
D.Strings[51308]="你浑身散发着霉运的味道。"
D.Strings[51309]="土地精包裹没你的份儿！"
D.Strings[51310]="倒霉去吧！"
D.Strings[51311]="今天好运与我同在！"
D.Strings[51312]="谢谢你的搭救！到粗麻驿站和我会合。"
D.Strings[51313]="要是你和你的伙伴们能离开这里一段时间，那也许是最明智的，旅行者。"
D.Strings[51314]="报告都准备好了，$n！我可不是吹牛，纳兹戈林将军一定会对我的工作非常满意的。"
D.Strings[51315]="报告在这里，$n。哦！记得一定要提炸弹是我的主意哦，我在报告里标出了这一点。"
D.Strings[51316]="这实在是太野蛮了！"
D.Strings[51317]="把这些当地人卷入我们的战争是不对的。我们应该把最好的一面展现给他们，而不是最坏的一面……"
D.Strings[51318]="现在还有时间制止这一暴行。你没必要这么做，夏琪亚……"
D.Strings[51319]="从这片土地上，我们可以学到很多，然而你却只想看着它燃烧。"
D.Strings[51320]="报告？！我现在忙得腾不出手来，$n！好吧好吧，给你。"
D.Strings[51321]="纳兹戈林一定会对里克非常满意的！拿去！报告做好了！"
D.Strings[51322]="%s大声呼唤增援！"
D.Strings[51323]="用闪电陈酿来攻击蜥蜴人爪牙！"
D.Strings[51324]="当一名玩家攻击蜥蜴人时，另一名玩家可以马上杀死它。"
D.Strings[51325]="你做到啦！雷掌阁守住了！"
D.Strings[51326]="而我也带了美酒来庆祝。第一轮我请。谢谢，朋友们！"
D.Strings[51327]="快上前来，我们可以好好认识一下。"
D.Strings[51328]="我们继续走！我看到另一个大个的，就在那儿！"
D.Strings[51329]="没时间了，弟兄们！我们要奋战到底！"
D.Strings[51330]="为了潘达利亚！！"
D.Strings[51331]="我们可以休息一下吗？坐下来歇一会儿？"
D.Strings[51332]="我觉得肚子饿了。"
D.Strings[51333]="这些蠢货把猢狲惹毛了！"
D.Strings[51334]="为了猢狲！"
D.Strings[51335]="耶！滚回长城那边去吧，蠢货们！"
D.Strings[51336]="别说吃的了。"
D.Strings[51337]="为了锦鱼人！"
D.Strings[51338]="蠢货？"
D.Strings[51339]="打哪儿来的回哪儿去吧，螳螂妖。"
D.Strings[51340]="每样东西都让你很饿，晓。"
D.Strings[51341]="呕吼！"
D.Strings[51342]="多谢你拯救了大部分好运气。"
D.Strings[51343]="小心螳螂妖的爪子，它们很锋利！"
D.Strings[51344]="在蛋孵化前摧毁它们！"
D.Strings[51345]="他往哪儿走了？"
D.Strings[51346]="怎么回事？小心，可怕的圆圈来了！"
D.Strings[51347]="我要像雪崩一样碾碎你！"
D.Strings[51348]="我管这招叫“雪犁掌！”"
D.Strings[51349]="你可把我惹火了！"
D.Strings[51350]="我包里有你要的东西！在这里，让我找找。不对，不在这里，也不在那里。哦找到了，在我的噩运袋里！"
D.Strings[51351]="就在雪球里！"
D.Strings[51352]="你不会喜欢我吸过熏香后的样子！"
D.Strings[51353]="我会在鎏金亭那儿见你。"
D.Strings[51354]="我们没时间休息了，$r。"
D.Strings[51355]="昆莱山的混乱局势使得许多无辜者背井离乡。他们会在我们的山谷中找到安身之处。"
D.Strings[51356]="我们将竭尽所能，为那些寻求庇护之人提供安全场所。"
D.Strings[51357]="我们将尽全力保护难民，但在魔古族大举杀进山谷的当下，安全不会持续多久。"
D.Strings[51358]="有太多工作要做了！"
D.Strings[51359]="我要榨干你们身体里的鲜血！"
D.Strings[51360]="你和你的同伴都是锦绣谷的贵客。如果你们需要帮助，请尽管开口。"
D.Strings[51361]="女皇的虫群将席卷整个山谷！"
D.Strings[51362]="为了螳螂妖的荣耀！"
D.Strings[51363]="我会让你尝尝恐惧的滋味。"
D.Strings[51364]="我要干掉你，软壳子……"
D.Strings[51365]="你无法阻挡女皇的虫群！我们的数量无穷无尽！"
D.Strings[51366]="点击骨堆以保护你免遭骨针的伤害！"
D.Strings[51367]="你觉得熊猫人身上是黑底白斑，还是白底黑斑？"
D.Strings[51368]="你知道为什么熊猫人爱好哲学吗？因为对于他们来说，世事并不是非黑即白的。"
D.Strings[51369]="那个厨房遭抢的熊猫人怎么了？他被骗啦！"
D.Strings[51370]="全潘达利亚最宝贵的是什么鱼？是金鱼！"
D.Strings[51371]="你知道如何在酒馆里“钓到”一个锦鱼人妹子吗？下杆就行啦！"
D.Strings[51372]="你该如何称呼一个在天禅院受训的锦鱼人？僧鱼！"
D.Strings[51373]="%s抽取周围的水！"
D.Strings[51374]="迁居的难民们怎么样了？"
D.Strings[51375]="援军已抵达山谷。"
D.Strings[51376]="锦绣谷出什么事了？"
D.Strings[51377]="保持体魄强健，心智也将随之坚韧。"
D.Strings[51378]="当思维渴望灵感时，请看些美丽的东西。"
D.Strings[51379]="哦，天呐，一个访客。你的到访让我非常开心。"
D.Strings[51380]="许多人从四面八方赶来，亲眼见证大门的开启。确实，你的许多族人都已经进去了。你也去里面寻找慰藉和庇护吧。"
D.Strings[51381]="我很高兴听到这个消息。魔古族最近的行动给我造成很大的困扰。他们已经近万年没有如此有组织地行动过了。"
D.Strings[51382]="拜加尔鲁什·地狱咆哮所赐，圣池被黑暗能量腐蚀了。煞魔余孽也依然在四处流窜。"
D.Strings[51383]="莉莉安的灵魂盯上$n了！"
D.Strings[51384]="流水对你的触碰做出了强烈反应！"
D.Strings[51385]="靠紧我。我会将我们伪装起来躲开敌人。"
D.Strings[51386]="雪流大师消失在暗影之中并造出了他的几个幻影！攻击这些幻影，驱散他们！"
D.Strings[51387]="雪流大师以他的近身格斗技巧对你发动了攻击！"
D.Strings[51388]="别跑了，这不过是苟延残喘。"
D.Strings[51389]="来吧，沐浴在流水之中！"
D.Strings[51390]="接受死亡的洗礼吧。"
D.Strings[51391]="快来！他们的防线上有道缺口。"
D.Strings[51392]="让我们趁道路畅通赶快前进，洞穴就在前面。"
D.Strings[51393]="先等一小会儿，然后把炸药放置在洞穴口。"
D.Strings[51394]="影踪派风暴使者对你的出现迅速作出反应，并开始|cFFFF0000|Hspell:115009|h[专注能量]|h|r！"
D.Strings[51395]="$n来了。我们走。"
D.Strings[51396]="准备……瞄准……"
D.Strings[51397]="弟兄们，准备好你们的箭！"
D.Strings[51398]="准备下一轮发射，3……2……1……"
D.Strings[51399]="弟兄们，准备好你们的箭……"
D.Strings[51400]="拉弓……"
D.Strings[51401]="弟兄们，准备好你们的武器！"
D.Strings[51402]="准备再次发射！"
D.Strings[51403]="|TInterface\\Icons\\ability_warlock_jinx.blp:20|t%s开始施放|cFFFF0000|Hspell:115147|h[灌魔幽灵]|h|r！"
D.Strings[51404]="脚步轻点，前面危机四伏。"
D.Strings[51405]="我准备好进入洞穴了。"
D.Strings[51406]="让车队上路吧！"
D.Strings[51407]="这…"
D.Strings[51408]="我从未想过种地也会有如此多……奇妙的感觉。"
D.Strings[51409]="你的拇指已经变绿了？$B$B我的看起来也差不多一样。"
D.Strings[51410]="嗯哼。$B$B“我觉着白天的时间太短了！”$B$B听起来咋样？太强硬了？你觉得会在市集上流行起来吗？"
D.Strings[51411]="在我们开始种地之前，我从没想过餐桌上的食物是从哪儿来的。$B$B可以说，这份经历让人很受启发！"
D.Strings[51412]="老愚，我需要一些务农的建议。"
D.Strings[51413]="当然！$B$B是什么问题？"
D.Strings[51414]="我该如何照料干枯的农作物？"
D.Strings[51415]="我该如何照料遭虫害的农作物？"
D.Strings[51416]="我该如何照料不安分的农作物？"
D.Strings[51417]="我该如何照料诱人的农作物？"
D.Strings[51418]="我该如何照料快闷死的农作物？"
D.Strings[51419]="我该如何照料野生的农作物？"
D.Strings[51420]="我该如何照料矮小的农作物？"
D.Strings[51421]="我该如何照料互相纠缠的农作物？"
D.Strings[51422]="大门被堵住了。"
D.Strings[51423]="干枯的农作物需要水！$B$B你可以用我爷爷留下的那个生锈的老式洒水壶。我把它放在那个树桩旁边了，就在田地边上。"
D.Strings[51424]="让我来试试。"
D.Strings[51425]="干枯的农作物需要水！$B$B有了洒水器我们就可以很轻松地照料它们了！那东西应该就在田地边上。"
D.Strings[51426]="他们在门后面放了石头吗？它动都不动！"
D.Strings[51427]="让开。我这儿有钥匙。"
D.Strings[51428]="啤酒来了！喝光它们，小伙子！"
D.Strings[51429]="我们先是干了一仗，接着就有人给我们送来了啤酒！今天还能再爽点吗？"
D.Strings[51430]="干得好，乔乔！"
D.Strings[51431]="递送啤酒，去战场中央？也许潘达利亚最终会成为一片乐土……"
D.Strings[51432]="我还有个问题……"
D.Strings[51433]="我该如何处理被占据的土壤？"
D.Strings[51434]="我该如何处理难除的杂草？"
D.Strings[51435]="遭虫害的农作物上爬满了害虫，真恶心！$B$B爷爷的杀虫剂就在田地边上——用它给那些臭虫子点颜色瞧瞧！"
D.Strings[51436]="呃——啊啊啊！"
D.Strings[51437]="遭虫害的农作物上爬满了害虫，真恶心！$B$B不过，既然我们有了脉波发射器，那就应该能轻而易举地消灭它们。用它来赶走那些害虫真是一种人道的方式，毫无杀虫剂成分！$B$B嘿，那是不是说我们的菜也算是有机蔬菜了？"
D.Strings[51438]="我们来搬点该死的啤酒吧！"
D.Strings[51439]="有东西在摇晃，嗯？好吧，正如爷爷常说的那样：胡萝卜可不会跳舞！$B$B有东西正试图从我们脚下拉走那些蔬菜！$B$B如果你想保护好这些农作物，恐怕你得杀掉那些在下边作祟的捣蛋鬼。是令人心碎，我知道，但这是工作的一部分。"
D.Strings[51440]="任务完成！没啤酒要送了。"
D.Strings[51441]="我得回石犁村去放松一下我这…该死的老胳膊了。"
D.Strings[51442]="哎，有时候蔬菜长得如此漂亮，就好像是在祈求被人偷走一样。$B$B爷爷说一只平原鹰能比市集上的任何人更好地挑出一个上等的南瓜，然后能以比那啥还快的速度偷走它……呃……$B$B“比热锅上的猢狲还快。”$B$B我猜你会说诸如此类的话？$B$B关键是，你一定要保护诱人的农作物免遭虫害！"
D.Strings[51443]="快闷死的农作物之间夹杂着一种杂草！$B$B你需要像对付长在地里的难除杂草一样对付它们——得花大力气！抓住那些烦人的杂草，尽全力拔出来。该做个了结了。"
D.Strings[51444]="野生的？！真令人吃惊！爷爷常说他降服野生农作物的故事。$B$B“小愚，”他说，“别害怕去拍打你周围的大葱。”$B$B我一直觉得他很伟大。"
D.Strings[51445]="小矮子！哈！这个词我很久没听到过了！$B$B当我拒绝起床或者去什么地方的时候，爷爷总是会那么叫我。按照他的说法，他会抓住我的脖子就像“拔出一株矮小的甜菜”那样把我提起来。$B$B这些农作物只要拔一下就能长直了。牢牢抓住它们，然后往上提。"
D.Strings[51446]="纠缠的杂草，嗯？卑劣的小恶魔。它们会钻进地下差不多十五码——如果你想根除它们的话，就必须要连根拔起。$B$B抓住杂草露出地面的部分，然后一直向外拔，直到你看到根部被完全拔出来为止。就是这么回事。"
D.Strings[51447]="有时候兔妖会在地里打洞然后住进去，盼着蔬菜能掉到它们头上——我想它们是觉得我们把蔬菜放进土里是有什么原因的。$B$B赖着不走的家伙，我爷爷是这么叫它们的。你得脚踏实地，我是说字面意思。你用脚使劲跺地面，把它们震出来！"
D.Strings[51448]="难除的杂草！它们就是一种顽疾，会在土壤中蔓延，侵占你的土地。$B$B在你耕种之前，你需要先清除杂草。真的没什么窍门——就是抓住它们然后拔出来！$B$B按我爷爷的话说，“你得比那些杂草还顽固！”"
D.Strings[51449]="|TInterface\\Icons\\spell_warlock_demonsoul.blp:20|t%s对|cFF006EFD$n|r施放了|cFFFF0000|Hspell:115297|h[放逐灵魂]|h|r！"
D.Strings[51450]="多谢营救！"
D.Strings[51451]="我的错？脏牦牛可不是我弄来的！"
D.Strings[51452]="帮帮我！土地精遇到麻烦了。"
D.Strings[51453]="要不要帮土地精一把？"
D.Strings[51454]="把我的幸运符还给我！"
D.Strings[51455]="你改变主意了？你做好准备时，我会在废墟高地的入口等你。"
D.Strings[51456]="我会在废墟高地的基地等你。"
D.Strings[51457]="别动。让他们过去。"
D.Strings[51458]="我们等下一波吧。"
D.Strings[51459]="我不是个好勇斗狠的人。搬运重物，小事一桩……但当我遇到不得已的情况时，我的肌肉也会把那些懦夫和流氓碾碎。"
D.Strings[51460]="让我们上战场吧，泥盏。"
D.Strings[51461]="我和他们素昧平生。不过我的熊猫人同胞绝不会是坏人。"
D.Strings[51462]="我叫科尔加·蛮鬃，曾经是联盟的俘虏，现在虽然逃了出来，但是手无寸铁。很高兴见到你，熊猫人。"
D.Strings[51463]="拜托，你能帮我离开这儿吗？"
D.Strings[51464]="如果我不甩掉这些野兽，它们会杀了我的！"
D.Strings[51465]="蠢蛋会被老波波大口大口吃掉的。"
D.Strings[51466]="该死的蠢蛋会放弃财物的，不管怎样。"
D.Strings[51467]="傻乎乎的蠢蛋，走起路来也像个蠢货。"
D.Strings[51468]="嘿，你，能帮我松开绳子吗？"
D.Strings[51469]="我们对你做过什么？"
D.Strings[51470]="我只想回家而已。"
D.Strings[51471]="拜托，求你了。"
D.Strings[51472]="祝你倒霉。"
D.Strings[51473]="土地精的朋友就快来了，你等着瞧！"
D.Strings[51474]="干嘛这么生气？"
D.Strings[51475]="我们土地精怎么惹着你了？"
D.Strings[51476]="联盟？如果坠毁的飞船是他们的，那就应该马上联络他们。乔乔，一起去吗？"
D.Strings[51477]="我们得把这船弄出来，科尔加。如果我们帮你救人，你会帮我们吗？"
D.Strings[51478]="我很乐意，朋友。不过我们的工程师下落不明——我们得先去救他。"
D.Strings[51479]="谢谢你，$c。谢谢！"
D.Strings[51480]="怒山领袖在洞里！"
D.Strings[51481]="我正打算离开这里呢，谢谢你！"
D.Strings[51482]="他们还有一大帮人仍在洞穴里，正准备攻击你们的人！"
D.Strings[51483]="我得找到我的家人！"
D.Strings[51484]="拜托了，$c，将他们彻底赶离昆莱山。"
D.Strings[51485]="愿四风庇佑你，陌生人。"
D.Strings[51486]="你救了我们！现在我们得离开这里了。"
D.Strings[51487]="这样下去也不是办法。"
D.Strings[51488]="你不配让我动手。你！碾碎这只微不足道的跳蚤！"
D.Strings[51489]="移除酒灵的幻象对猢狲脆弱的心智造成了伤害！"
D.Strings[51490]="放我下来！"
D.Strings[51491]="别把我丢进火里，猢狲！"
D.Strings[51492]="我做了啥对不起你们的事？干嘛这么生气？"
D.Strings[51493]="我还有块幸运符。这是你们最后一次投降的机会，不然就等着倒霉吧。"
D.Strings[51494]="所有人都武装起来！魔古族攻过来了！"
D.Strings[51495]="他们的主力部队突破北门了！"
D.Strings[51496]="你需要立刻回到鎏金亭去！"
D.Strings[51497]="干得好，$n。等等……我看到一个斥候过来了。"
D.Strings[51498]="<范妮小姐显得局促不安。她既为迫近的战斗而紧张，又渴望能够投身战场。>"
D.Strings[51499]="<范妮小姐期待地看着你，眼神里充满了希望。>$b$b<范妮小姐的荣耀时刻已经到来。>"
D.Strings[51500]="我们上，范妮小姐。"
D.Strings[51501]="你被伊克提克巨像吞下去了！"
D.Strings[51502]="让你的武术训练发挥作用。会聚能量……然后出击！"
D.Strings[51503]="接着打！"
D.Strings[51504]="继续战斗，熊猫人！撤销所有的撤退命令！石犁村还没有丢！"
D.Strings[51505]="三……"
D.Strings[51506]="二……"
D.Strings[51507]="一……"
D.Strings[51508]="哼，那些魔古族得再加把劲了！$B$B金莲教会死守山谷……不惜任何代价。$B$B我们守护的秘密太过珍贵……太过强大……决不能落入韶天之手！"
D.Strings[51509]="他们怎么能在距离我们防线如此遥远的大后方，攻击一位守护锦绣谷的金莲护法！$B$B你现在知道我们为什么需要你的帮助了吗？$B$B韶天魔古已经混进了山谷。如果再不加以制止，我们宁静的家园就会遭受难以言喻的毁灭！"
D.Strings[51510]="当黑暗来临，最好还是点亮一盏明灯。"
D.Strings[51511]="你要汇报什么？"
D.Strings[51512]="锦绣谷很平静。太平静了。"
D.Strings[51513]="有时候最美丽的事物也是最致命的。看着我！"
D.Strings[51514]="很好，那样应该能拖延一下他们的计划。干得好，$n。我相信你可以自己回去。"
D.Strings[51515]="如果你打算进入废墟，就得先去郭莱遗迹和奎·秋光谈一谈。"
D.Strings[51516]="保护马车！"
D.Strings[51517]="搞什么鬼？！"
D.Strings[51518]="摇头晃脑。"
D.Strings[51519]="如果我能早点发现壁画就好了。很多事本来是可以避免的，$n。"
D.Strings[51520]="我们的家……被毁了……我们已经尽力了……"
D.Strings[51521]="什么？！我要亲自解决你！"
D.Strings[51522]="严惩窃取魔古族权柄之徒。"
D.Strings[51523]="你的族人已经失败了。眼下，我们魔古族正在侵占你珍爱的山谷。"
D.Strings[51524]="雷电之王将再次崛起！"
D.Strings[51525]="你真觉得我们能活着离开这里吗？"
D.Strings[51526]="我把道路清理干净了。你可以出发了。"
D.Strings[51527]="我真不敢相信我们做到了。谢谢你，陌生人！"
D.Strings[51528]="我的孩子！来得正好，我们还有很多牦牛要洗。"
D.Strings[51529]="$n，$g你这帅气的恶魔:你这性感的尤物;，到这儿来。我们得谈谈关于雕像的事……"
D.Strings[51530]="怎么慢吞吞的？你还有其它事情要忙吗？利维特那个小怪物让你帮他干活了？！"
D.Strings[51531]="所以……那个巨魔怎么还没死？就是他复活了这些魔古族，是吧？"
D.Strings[51532]="有时我不得不深入那个洞穴去采集提神松针，那段日子真叫人不堪回首。"
D.Strings[51533]="我为什么会觉得你给我带来了好消息呢，$n？"
D.Strings[51534]="我再也听不见那疯子巨魔的叫喊声了。真是耳根清净啊！"
D.Strings[51535]="我们得救那些熊猫人。如果不快点动手，我们这儿就会出现很多因为冒险寻亲而丧命的逃兵了！"
D.Strings[51536]="你成功的消息不胫而走，我们的队伍更壮大了！现在我们的规模比我之前所期望的还要好，这多亏了你，$n。"
D.Strings[51537]="瞧啊，这是谁回来了！故地重游吗，$n？"
D.Strings[51538]="向$n致敬，伟大的野牛人征服者和东风之眠的勇士！"
D.Strings[51539]="它冲我们过来了！"
D.Strings[51540]="不要激怒他们！"
D.Strings[51541]="装死！这会令他们觉得无趣，继而走开。"
D.Strings[51542]="你打算回来转一转吗，$n？"
D.Strings[51543]="我想知道在将军给我们下达行军命令之前，我们还要在这里待多久。"
D.Strings[51544]="$n，你回过奥格瑞玛了吗？有什么消息？"
D.Strings[51545]="你说的那个营地往西方向，在城墙的另一边。螳螂高原到处都是虫子，你怎么看，$n？"
D.Strings[51546]="我可不是来给别人当午餐肉啃的。哎呀，我是不是说得太大声了？"
D.Strings[51547]="我放弃。我没法给你们这些可爱的小熊讲明白了。$n，你能过来给这些新手演示一下吗？"
D.Strings[51548]="他们走了吗？"
D.Strings[51549]="你告诉她什么？！"
D.Strings[51550]="$n，我赐予你北风的冷酷复仇之力！"
D.Strings[51551]="嗯。首先应该做什么？熏香？营火原木？永燃蜡烛？"
D.Strings[51552]="啊！土地精大集市迎来了一位幸运儿？我感觉我们的会面会带来好运。$b$b我叫好运的八铜钱。我的名字是根据我最好的幸运符起的，它总能给我带来无比的好运气。"
D.Strings[51553]="我们是土地精。我们熟悉山中所有的道路。$b$b最重要的是，我们负责将物资运到东边的长城。影踪派的堡垒。$b$b但眼下是黑暗时期，土地精在途中面临着巨大的危险。"
D.Strings[51554]="你居然一次就成功了！快，把这火焰带到寺院顶层去，烧掉挂在那里的卷轴。"
D.Strings[51555]="神真子，也就是我们脚下的这片土地，正承受着极大的痛苦。虽然我不知道这痛苦从何而来，但我对此感同身受。"
D.Strings[51556]="古代的智慧告诉我们，必须通过四位元素之灵之口，才能与神真子交谈。可是元素之灵们都离开了五晨寺，他们的力量正在衰减。"
D.Strings[51557]="$n，你就是我期待已久的勇士。你将要找回并重聚元素之灵。这样，我们才能与神真子沟通并治愈我们的家园。"
D.Strings[51558]="我们的时间不多了，尽快动身吧。"
D.Strings[51559]="你们并非孤军奋战！将我的风暴倾泻在敌人头上吧！"
D.Strings[51560]="上古火灵十分烦躁。现在进入神龛是很危险的……"
D.Strings[51561]="你听见那些阡陌客是怎么评价我这个城里人的吗？$B$B没错，我是在晨芳园里长大的，可我也去过爷爷家几次。我知道胡萝卜和芜菁的区别！毕竟一个红一个白！$B$B爷爷过世后，他把农场留给了我，所以我会为他竭尽全力！但我该怎么赢得那些阡陌客的信任？"
D.Strings[51562]="很好。引导火焰，感受它们在你体内的流动。"
D.Strings[51563]="好好学习这个法术，用它来烧尽我们敌人身上的污秽。"
D.Strings[51564]="我的农作物在生长……现在该怎么做？"
D.Strings[51565]="联盟夺取了一辆采矿车！"
D.Strings[51566]="部落夺取了一辆采矿车！"
D.Strings[51567]="现在你该做的就是等！大多数农作物在开始生长之后的第二天就成熟了。$B$B在这样肥沃的山谷里拥有一块土地不是很幸运的事吗？"
D.Strings[51568]="有挑战者过来了。"
D.Strings[51569]="跳跳大王大声呼喊！兔妖来了！"
D.Strings[51570]="以我全部的怒火攻击这些野蛮人！"
D.Strings[51571]="让我们在寇塔营地再见！"
D.Strings[51572]="塔索尔嗅了嗅空气。"
D.Strings[51573]="雪怒，北方之力，回应了战斗的召唤！"
D.Strings[51574]="玉珑，东方的守护者，出现在战场上！"
D.Strings[51575]="砮皂，西方之力，冲进了战场！"
D.Strings[51576]="感谢上天……我原本以为自己要把火树烈酒的秘方带进棺材了呢。快帮我离开这儿，朋友！"
D.Strings[51577]="让我们离开这里吧。"
D.Strings[51578]="抓紧了——跳！"
D.Strings[51579]="臭气熏天！"
D.Strings[51580]="魔古族突破了我们的防线……$B$B他们的魔玉战士大军人数太多，我们抵挡不住。$B$B我在后方照顾车，但其他人撤进了城里，准备背水一战。"
D.Strings[51581]="你这就要走了？我真羡慕你的强大力量。一路顺风，$c。"
D.Strings[51582]="嘘！脚步轻点儿。她正在修炼。"
D.Strings[51583]="%s开始引导一次强烈的|cFFFF0404|Hspell:116040|h[震中]|h|r！"
D.Strings[51584]="哈！就这么干！你很有天分。"
D.Strings[51585]="这边走，朋友！战斗在等着我们！"
D.Strings[51586]="快过来！你不想错过这么有趣的事吧？"
D.Strings[51587]="我喜欢你的思路！我们走！"
D.Strings[51588]="我们将并肩作战，朋友。这不是你一个人的战斗。"
D.Strings[51589]="我们守住阵线，你去保护好牧师。"
D.Strings[51590]="坚持住，水手们！为了兄弟姐妹们！"
D.Strings[51591]="保护伤员！战斗还没完呢。"
D.Strings[51592]="蜂蜜獾熊才不管那些烂事！"
D.Strings[51593]="我不会扔下这些不管的。这是我家族的遗产！"
D.Strings[51594]="请允许我介绍下自己——我叫崖·火树，是这个曾经辉煌村庄的杰出首领。$B$B你显然是这世界上正直的住民。$B$B不知能否麻烦你帮我脱离这个棘手的境地呢？我相信在附近驻扎的影踪派会非常乐意对给您造成的任何不便作出补偿的。"
D.Strings[51595]="……够了。走吧。"
D.Strings[51596]="像你这种阳光年轻的$g男士: 女士;可不该待在这里。$B$B或许你愿意让我护送你去安全的地方，嗯？"
D.Strings[51597]="是啊……你为什么不“护送”我出去呢。"
D.Strings[51598]="拜托了，$g先生: 小姐;……$B$B你会救我出去吗？"
D.Strings[51599]="你叫$n，对吧？如果你能亲自确保我的安全，我会再多给你一些赏钱的。"
D.Strings[51600]="你……在为影踪派效力？我不敢相信！"
D.Strings[51601]="当这些怪物来的时候，影踪派的人都很紧张……他们不停在说“煞魔”。那是什么？"
D.Strings[51602]="它们看起来可不轻啊。我们可以快点儿吗？"
D.Strings[51603]="我们得走多远？"
D.Strings[51604]="当我们把这些酒带回住所后，就可以开桶庆祝，为胜利干杯了！"
D.Strings[51605]="我听说野牛人冲破了北面的大门。不知那里的影踪派怎么样了？"
D.Strings[51606]="我父亲酿制火树烈酒。在他之前还有我的祖父。我决不能让这个家传秘方失传。"
D.Strings[51607]="没什么比得上一杯暖和的美酒了。让你的身体暖和起来，是一大享受啊。你把那个冷东西留给自己吧。"
D.Strings[51608]="啊，嗯，是的……谁会没有听说过陈·风暴烈酒啊？不过，我听说他的酒桶已经空了，你知道我指的是什么。"
D.Strings[51609]="啊哦。好像有什么东西漏出来了！是酒！！！"
D.Strings[51610]="你一直在为影踪派效命？我无法相信他们居然还让一个外人帮助他们！"
D.Strings[51611]="这些野牛人向来连招呼都不打。直接就攻来了！活该他们被煞魔感染！"
D.Strings[51612]="我所有的家人都死了。也许我应该在滨岸村建一座新庄园？"
D.Strings[51613]="科拜以前总是威胁我们，没完没了。现在……不管他打的是什么主意，他都输定了。"
D.Strings[51614]="等我见到影踪派翀大师，我会把自己的智慧分一点给他。影踪派的勇气帮不了我们！"
D.Strings[51615]="我真不擅长干这个。我是一位演说大师，人民的外交家。我们在这里的任务快要完成了吧？"
D.Strings[51616]="我相信你肯定会对从湖中央喷薄而出的那团汹涌怒气做点什么的，对吧？！"
D.Strings[51617]="那……那不是燧焰吗？"
D.Strings[51618]="嗨——呀！"
D.Strings[51619]="Fus Ro Dah（力——衡——冲）!"
D.Strings[51620]="我发现你驾驭白虎、青龙、灵猴和朱鹤的战技的能力不在我之下。"
D.Strings[51621]="现在在道场里痛哭，是为了将来能在战场上大笑。啊哈哈哈哈哈哈！"
D.Strings[51622]="拍死那只臭猴子！"
D.Strings[51623]="扫堂腿！"
D.Strings[51624]="离……开……我……的……镇子！"
D.Strings[51625]="行如流水，韧如芦苇……呱啦，呱啦，呱啦。对准屁股踢就对了！"
D.Strings[51626]="你是在以年龄评断我的实力吗？"
D.Strings[51627]="我们都把镇子给丢了……从禅院来的援军怎么还没赶到？"
D.Strings[51628]="肘锤猢狲！捶！捶！捶！"
D.Strings[51629]="蠢蛋没把运货人带回来！"
D.Strings[51630]="猢狲肆无忌惮地偷走了果子。有去无回！"
D.Strings[51631]="不准蠢蛋肆意妄为！"
D.Strings[51632]="为了大王！"
D.Strings[51633]="酋长下令掠夺，猢狲们遵命！"
D.Strings[51634]="金莲教已经监视了这座山谷几千年。$B$B上天已向我们降下了预兆，所以我们要团结一致、坚定信念——现在是再次打开大门的时候了。$B$B你们准备好了吗？"
D.Strings[51635]="我准备好打开大门了。"
D.Strings[51636]="发射"
D.Strings[51637]="狂暴的雪人？！嗯……我想到一个绝好的主意。"
D.Strings[51638]="该死的蠢蛋想阻止断牙猢狲抢果子！"
D.Strings[51639]="当然。别担心。"
D.Strings[51640]="你做到了！过来，我们得谈谈。"
D.Strings[51641]="在眼下这般黑暗的时期，我们必须控制好自己的情绪，以免被煞利用。"
D.Strings[51642]="我感觉到暴怒消失了。你做得不错。"
D.Strings[51643]="生气的猢狲正盯着你看呢，死家伙。"
D.Strings[51644]="影踪派不在这儿，因为他们必须守护城墙。土地精欠影踪派太多了。如果影踪派没能保护土地精，那就意味着他们陷入了危险的境地，而且比任何时候都更需要土地精脚夫。"
D.Strings[51645]="呷卟督曾是土地精的朋友。他整整统治了三季。现在改由呜咔督掌权，他是脾气最为暴躁的一个。他认为来自土地精的食物供应很快就会中断，因此他开始四处掠夺。"
D.Strings[51646]="猢狲用我的牦牛来喂养他们的宠物雪人。这运气真是糟糕透顶。"
D.Strings[51647]="堂弟兔子脚也许又高又聪明，还浑身散发着好运与福气。但他却对我的幸运符牦牛鞋冷嘲热讽。"
D.Strings[51648]="想看我的幸运符吗？我还很小的时候就穿着这双牦牛鞋。多年来这双鞋给我带来了很多好运。"
D.Strings[51649]="你的幸运符是什么？所有旅行着都需要带着幸运符上路。"
D.Strings[51650]="你身上散发着好运的气息！万分感谢你救了我，幸运符！你可以叫我堂弟牦牛鞋。"
D.Strings[51651]="土地精振作！"
D.Strings[51652]="来这里真是倒霉。"
D.Strings[51653]="这地方真是衰透了。"
D.Strings[51654]="猢狲浑身都是霉运的臭味儿。"
D.Strings[51655]="啊！一个土地精包裹。好极了。"
D.Strings[51656]="我知道这些幸运符。"
D.Strings[51657]="你做得很好。我们得看好这些武器，把它们藏在这座大殿里。魔古族休想再见到这些宝物了。"
D.Strings[51658]="啊，一大堆东西。"
D.Strings[51659]="干得好！雷电之王的战斧到手了。"
D.Strings[51660]="$n，我恳求你能否去冬花关，并尽快找到影踪派麦基大师。"
D.Strings[51661]="我听说鳄鱼人因为一个上古魔古诅咒而变得具有攻击性。"
D.Strings[51662]="该死的蠢蛋可阻止不了掠夺！"
D.Strings[51663]="要我说让那些鳄鱼人放马过来好了。他们最终会臣服，为什么要干涉呢？"
D.Strings[51664]="蠢蛋要烧起来了！"
D.Strings[51665]="断牙需要食物。蠢蛋有食物。抢啊！"
D.Strings[51666]="新酋长，新规矩。抱歉，蠢蛋要遭劫了！"
D.Strings[51667]="这木筏归你了，邻居。你要是想用了，随时回来取。它就在这里等着你。"
D.Strings[51668]="喂食的时间到了。"
D.Strings[51669]="学习"
D.Strings[51670]="恐钉扑向了你！拼命的时候到了！|TInterface\\Icons\\ability_warrior_secondwind.blp:20|t"
D.Strings[51671]="到吧台这儿来坐一坐，朋友。我给你拿点吃的。"
D.Strings[51672]="嗨，你好！我能在你离开之前请你喝杯新鲜热茶吗？"
D.Strings[51673]="我外婆常说，饿着肚子打仗会让你站都站不稳！"
D.Strings[51674]="你好，$n！你在这儿很有名！"
D.Strings[51675]="欢迎回来，$n！你找到了我们失踪的向导！"
D.Strings[51676]="现在季禄拿回了他的那些小玩意儿，或许我能在旅馆里消停一会了！"
D.Strings[51677]="又见面了，$c！"
D.Strings[51678]="伟大的$n光临我的寒舍，真是不胜荣幸！"
D.Strings[51679]="这间旅馆永远欢迎你，$n！"
D.Strings[51680]="酒坛集的英雄回来了！"
D.Strings[51681]="好吧你们两个，好好玩！"
D.Strings[51682]="欢迎光临小店，$c。"
D.Strings[51683]="请随意挑选。"
D.Strings[51684]="你好，$c！看起来你会对新鲜辣椒感兴趣的！也许再来几本旅途中解闷用的书。"
D.Strings[51685]="欢迎！你不会在营地东边找到比这更好的精品了！"
D.Strings[51686]="一定要再回来看我哦，$c！"
D.Strings[51687]="锦绣谷是我的家园，保护它免遭侵犯既是我的责任，亦是我的愿望。"
D.Strings[51688]="今天的风正好。"
D.Strings[51689]="幸运对着土地精的坐骑微笑。"
D.Strings[51690]="快点儿回来！"
D.Strings[51691]="高山会原谅飞鸟，但不一定会宽恕骑手。"
D.Strings[51692]="你来这儿钓鱼？"
D.Strings[51693]="我想不出是什么东西使得这些鳄鱼开始有攻击性。发生什么事了？"
D.Strings[51694]="再次感谢你的帮助，$n。最近鳄鱼像以前一样不再那么有攻击性了。$b$b我们也在改善自己的行为，只要鱼够吃，我们再也不会滥捕了。"
D.Strings[51695]="你好，$r。"
D.Strings[51696]="这儿没什么好看的……走开！"
D.Strings[51697]="我是一个装满谷物的小篮子……"
D.Strings[51698]="我不会回去的！"
D.Strings[51699]="我只是这个可怕世界里的一个渺小的土地精。"
D.Strings[51700]="你确定不想跟我一起去吗？"
D.Strings[51701]="不！土地精在这儿很安全。"
D.Strings[51702]="请允许我让你的水下之旅变得更加……愉悦。"
D.Strings[51703]="你能再次帮我提高游泳速度吗？"
D.Strings[51704]="蠢蛋疯了！"
D.Strings[51705]="波波要出来啦！快跑！"
D.Strings[51706]="雪人疯了！雪人发疯了！"
D.Strings[51707]="真见鬼！"
D.Strings[51708]="波波发火啦！"
D.Strings[51709]="这是一个关于《饥饿的鳄鱼》的故事。"
D.Strings[51710]="纳松海沟里的鳄鱼以鱼类为食，他们过得悠闲自得。"
D.Strings[51711]="然后鲨鱼来了。"
D.Strings[51712]="鲨鱼也以鱼类为食，但鳄鱼还是生存了下来。"
D.Strings[51713]="不久以后，熊猫人来了。"
D.Strings[51714]="熊猫人在海沟里钓鱼，但鳄鱼还是生存了下来。"
D.Strings[51715]="最后，猢狲也来到了纳松海沟。"
D.Strings[51716]="猢狲大肆捕捞、涸泽而渔，也不管吃不吃得完。"
D.Strings[51717]="因为没鱼可吃，鳄鱼变得饥饿和绝望。他们攻击熊猫人纯粹是因为饥饿难耐。"
D.Strings[51718]="熊猫人既因为恐惧，又为求自保，杀光了纳松海沟里的鳄鱼。"
D.Strings[51719]="两个赞达拉巨魔撞破房门，向你冲了过来！"
D.Strings[51720]="没关系！反正我们也用不着那些了！"
D.Strings[51721]="现在你把我惹毛了！"
D.Strings[51722]="好吧！游戏时间到，“朋友们”。"
D.Strings[51723]="纳松海沟的鳄鱼不再那么……只因为熊猫人不了解整个事情的来龙去脉。"
D.Strings[51724]="嘿，你好！是你把火灵带回来的吗？"
D.Strings[51725]="他是不是很烫？我敢说，他肯定很烫！"
D.Strings[51726]="他当然很烫了！别说傻话了，小邓。"
D.Strings[51727]="好吧，再见。"
D.Strings[51728]="我敢肯定，你非常强大，哈？如果你愿意，一脚就可以把那座桥踢成两段！"
D.Strings[51729]="不不。但他们肯定能把你踢到山那边去！哈！"
D.Strings[51730]="你们什么都没看见！"
D.Strings[51731]="我的辫子！"
D.Strings[51732]="她要把你甩下去，抓紧了！$b$b|TInterface\\Icons\\inv_misc_desecrated_leatherglove.blp:32|t坚持住"
D.Strings[51733]="%s开始对他的武器施放|cFFFF0404|Hspell:116711|h[引导火焰]|h|r！"
D.Strings[51734]="一看到你我的精神就振奋了，$c。我们在两条战线上激战。$B$B在大门处，我们奋力击退野牛人大军。在北边的山上，我们的影踪禅院被未知力量攻占了。"
D.Strings[51735]="该大巴巴姆上场了！"
D.Strings[51736]="呃……旗帜归你了。"
D.Strings[51737]="那是什么？谁？！"
D.Strings[51738]="是我拿了你那个死鬼大师的旗帜。来抓我呀，$r！"
D.Strings[51739]="你不能让任何人过去，伙计。否则就等着掉脑袋吧。"
D.Strings[51740]="准备得怎么样了，伙计？"
D.Strings[51741]="杀了大坏蛋！"
D.Strings[51742]="杀啊！"
D.Strings[51743]="跑啊蠢蛋！"
D.Strings[51744]="救救蠢蛋！"
D.Strings[51745]="他们来了，他们来了！"
D.Strings[51746]="……最好是。"
D.Strings[51747]="用我的长矛终结你！"
D.Strings[51748]="嘿，$n，这边。我们需要你的帮助。"
D.Strings[51749]="不好。真的不好。"
D.Strings[51750]="什么也比不上一杯上好的咔啡啊！将种子烘焙到恰到好处后，趁热磨碎，再放到纯水中酿造。$B$B对疲惫的旅行者或好学的僧侣来说再好不过了。"
D.Strings[51751]="我在想什么啊！真是个倒霉蛋！"
D.Strings[51752]="不……不……不好。"
D.Strings[51753]="真不该去喂这些山羊。"
D.Strings[51754]="嘿！你是来这儿挑战我的吗？"
D.Strings[51755]="我很期待我们的对决。毫无疑问，我赢定了。"
D.Strings[51756]="我一直在非常刻苦的训练！你现在无法击败我了，$n。"
D.Strings[51757]="我很想见识下你的战斗风格，$c。"
D.Strings[51758]="嘿，你好啊，宝贝儿。你穿的那身花俏装备还真不赖啊。$b$b这么说你也领悟了朱鹤之道？有兴趣过两招吗？"
D.Strings[51759]="在这赤精栖木，你找不到其他锦鱼人了。事实上，我想我是唯一的一个。$b$b通常，我的族人会避开赤精和他的教义。毕竟，鹤是以鱼为食的。"
D.Strings[51760]="塞隆尼斯跟我讲了很多关于你在战斗中的技巧。我很期待能够亲眼见识一下。"
D.Strings[51761]="你好，对手。$b$b我正忙着训练。$b$b希望你也是。"
D.Strings[51762]="图卡图克要揍死你、捶死你、踢死你、抓死你、咬死你、戳死你、踩死你、烦死你……"
D.Strings[51763]="你好，邻居。$b$b我听说了很多关于你的事，你在这座岛上几乎战无不胜。我想是时候给你个机会来挑战我了。"
D.Strings[51764]="没人能够击败我。$b$b我来这岛上也有数周时间了，每天都在决斗，至今未尝败绩。$b$b这就是潘达利亚的全部实力了吗？"
D.Strings[51765]="你不仅挑战了我们最强的弟子，还将他们全部击败。现在让我们来瞧瞧你到底是何方神圣……"
D.Strings[51766]="又是我。很高兴见到你，$n。$b$b我们开始吧？"
D.Strings[51767]="今天是测试我能力绝佳的好日子。$b$b我想你已经准备好迎战了，$n。让我们来瞧瞧我说的对不对。"
D.Strings[51768]="朱鹤之道注定是一条通往失败的道路，我见过真相！$b$b所有的道路都通向绝望！你没有任何希望！你们都没有！！"
D.Strings[51769]="你是来挑战我的吗？"
D.Strings[51770]="好吧，你逼我出手的！"
D.Strings[51771]="准备受死吧，懦夫！"
D.Strings[51772]="今天我将笑到最后！"
D.Strings[51773]="我为你即将遭受的挫败先提前道个歉。"
D.Strings[51774]="呀……呀！！！"
D.Strings[51775]="你的连胜将止步于此，$n。今天，你会倒在我的枪下。"
D.Strings[51776]="我不会对你手下留情的，$n。请你也不要有所保留。"
D.Strings[51777]="放弃吧！没希望的！你赢不了我！"
D.Strings[51778]="好主意！让我们打个痛快！"
D.Strings[51779]="别因为我是乡下来的就排挤我！我胳膊肘可粗了，你瞧。"
D.Strings[51780]="<叹气>……让我们来做个了断吧。"
D.Strings[51781]="以赤精之名，我要击垮你！"
D.Strings[51782]="把你的看家本领都拿出来，$n。"
D.Strings[51783]="哈哈！别放水嘛！"
D.Strings[51784]="我的死对头……很高兴你来了。"
D.Strings[51785]="你没机会的。"
D.Strings[51786]="我……甘拜下风。"
D.Strings[51787]="很有意思……"
D.Strings[51788]="干得好，宝贝儿。或许我们会再见面的……"
D.Strings[51789]="我父亲说他已经预见到了这一天。他说我会被击败，但我始终没相信。"
D.Strings[51790]="我有一阵子没输给过弟子了。谢谢你跟我切磋。"
D.Strings[51791]="怎么会……我不……不，不，不！我又输了！"
D.Strings[51792]="干得好，你如秋风扫落叶般技压群雄，邻居。我会支持你的。"
D.Strings[51793]="这才是我所期盼的！你给了我一个很好的理由继续刻苦训练。"
D.Strings[51794]="失败的滋味……很奇怪，也很陌生。谢谢你让我有了新体验。"
D.Strings[51795]="不……不……"
D.Strings[51796]="打得好，下次可就说不准了……"
D.Strings[51797]="巨魔……我还以为他们只是传说！"
D.Strings[51798]="转向！"
D.Strings[51799]="$n，有了朱鹤的力量，你就可以跃过火焰了！"
D.Strings[51800]="停下！回去和楼梯下面的思南谈一谈。你不能独自面对督军的怒火！"
D.Strings[51801]="等等！我已经尽快赶来了。但愿还不算太晚。"
D.Strings[51802]="虽然我能做的不多，但我会尽全力帮你。但愿能在最后关头帮上忙。"
D.Strings[51803]="注意我的武器：风从虎！"
D.Strings[51804]="看招：风从虎！"
D.Strings[51805]="你准备好了？！风从虎！"
D.Strings[51806]="死亡旋风：风从虎！"
D.Strings[51807]="在那些矛过载前捡起它们！把它们掷回去！"
D.Strings[51808]="锦绣谷曾是伟大的魔古帝国的权力中心。魔古族统治的时代非常恐怖、残酷和血腥。"
D.Strings[51809]="请在此处休息，$n。我希望山谷会带给你和平与欢乐。"
D.Strings[51810]="噢，很好，是这一带的$g大英雄:女英雄;啊。过来，我们聊聊吧，$c。"
D.Strings[51811]="如果你是来帮我们的，那你必须要找到影踪派陈大师，$c。"
D.Strings[51812]="陈大师的辞世令我们的心情无比沉重。你要去找胡墨戈斯，重拾大师的荣耀吗，$n？"
D.Strings[51813]="酒桶炸弹准备好了。$n，你要去阻止野牛人吗？"
D.Strings[51814]="原来是我们的$g大英雄:女英雄;得胜凯旋了。你好吗，$n？"
D.Strings[51815]="%s进入了|cFFFF0000|Hspell:116982|h[狂乱之护]|h|r！"
D.Strings[51816]="嘿，$c，到这儿来！"
D.Strings[51817]="那些掷矛者还在攻击。你难道不想消灭他们吗，$c？"
D.Strings[51818]="去解决他们，猛虎！"
D.Strings[51819]="希望你准备好大战一场了，$n。"
D.Strings[51820]="你好，$n！想加入我吗？"
D.Strings[51821]="这些野牛人还以为煞魔就是世上最可怕的东西了，直到他们遇见了我！"
D.Strings[51822]="没什么能比热火朝天地打一场来得更舒服了！"
D.Strings[51823]="有一次，我的裤子在战斗中掉下来了，我的对手目瞪口呆地看着我，结果被我打碎了脑壳。他的眼睛看错了地方。"
D.Strings[51824]="再来，再来！"
D.Strings[51825]="我已经数不清自己究竟杀死多少野牛人了。你杀了多少，$n？"
D.Strings[51826]="别让麦基知道，可就算他脾气很坏，我还是有点儿喜欢他。"
D.Strings[51827]="说你呢！你究竟是敌是友？"
D.Strings[51828]="什么？你真有那么好心，特地来帮我们？"
D.Strings[51829]="联盟失去了对钻石补给站的控制！"
D.Strings[51830]="部落失去了对钻石补给站的控制！"
D.Strings[51831]="联盟取得了对钻石补给站的控制！"
D.Strings[51832]="我还以为你会打到他们呢。你滚那只桶的样子可真像个新手。"
D.Strings[51833]="|cFFFF0000部落|r取得了对钻石补给站的控制！"
D.Strings[51834]="联盟失去了对熔岩补给站的控制！"
D.Strings[51835]="|cFFFF0000部落|r失去了对熔岩补给站的控制！"
D.Strings[51836]="联盟取得了对熔岩补给站的控制！"
D.Strings[51837]="|cFFFF0000部落|r取得了对熔岩补给站的控制！"
D.Strings[51838]="联盟失去了对巨魔补给站的控制！"
D.Strings[51839]="|cFFFF0000部落|r失去了对巨魔补给站的控制！"
D.Strings[51840]="联盟取得了对巨魔补给站的控制！"
D.Strings[51841]="是时候了。我们的桶快要用光了。"
D.Strings[51842]="|cFFFF0000部落|r取得了对巨魔补给站的控制！"
D.Strings[51843]="联盟失去了对瀑布补给站的控制！"
D.Strings[51844]="|cFFFF0000部落|r失去了对瀑布补给站的控制！"
D.Strings[51845]="联盟取得了对瀑布补给站的控制！"
D.Strings[51846]="|cFFFF0000部落|r取得了对瀑布补给站的控制！"
D.Strings[51847]="哼。"
D.Strings[51848]="你在这儿干什么？鬼混？"
D.Strings[51849]="李丽莎在唠叨什么呢？谈情说爱吗？！"
D.Strings[51850]="噢，是你啊。"
D.Strings[51851]="真该有人来解决掉这些野牛人。我忙得很，可不能一天到晚站在这儿！"
D.Strings[51852]="就在几天前，我还看见一个强大得多的$c从头顶飞过。"
D.Strings[51853]="嘿，丽莎。你的$g男朋友:女朋友;在这儿呢！"
D.Strings[51854]="东部十字路变轨了。"
D.Strings[51855]="北部十字路变轨了。"
D.Strings[51856]="你的愤怒支撑着我。"
D.Strings[51857]="我的怒火一泻千里！"
D.Strings[51858]="怒火给了你力量。"
D.Strings[51859]="你休想再埋葬我！"
D.Strings[51860]="还拽着赤精的尾巴，对他那愚蠢的所谓“希望”的执念死守不放啊？"
D.Strings[51861]="我会让你见识下什么叫绝望……我还要让整个岛臣服在我的脚下！"
D.Strings[51862]="我真是个扫把星！我把表叔激情豆的咔啡交易搞砸了！"
D.Strings[51863]="你不该去喂这些山羊，表哥。"
D.Strings[51864]="好吃懒做的人就是这个下场。"
D.Strings[51865]="咔啡对土地精和熊猫人有益，但对山羊、雪人和猢狲无益。这你应该知道啊！"
D.Strings[51866]="坚持住！这会是一次颠簸的旅程！"
D.Strings[51867]="我们的前路已经显现。快去找尚喜师父，他会告诉你下一步该怎么做。"
D.Strings[51868]="这个……村子……已经死了……"
D.Strings[51869]="我闻到了我的幸运符！噢，拜托你把它带给我。"
D.Strings[51870]="帮帮我！他们夺走了我的幸运符！"
D.Strings[51871]="你好啊，$n。干得不错啊，酋长。"
D.Strings[51872]="情况怎样？你得去那个农场。琪麟让你做她的活？她可真懒啊！"
D.Strings[51873]="你在帮那些农夫解决问题是吧，大好人？我们指望你能帮我们抓些虫子。"
D.Strings[51874]="听说你已经帮那些农夫全都摆脱了困境，真是太好了，头儿。现在我们要解决一些新问题了。"
D.Strings[51875]="你去炸掉钻油机，$n。我们可不想让腐臭的野牛人继续朝我们头顶上投掷成批的火药桶了！"
D.Strings[51876]="那些爆炸声真是太悦耳了。来这里，$n。抱一下！"
D.Strings[51877]="嘿，看这儿。是$n！"
D.Strings[51878]="接下来有什么打算，$n？单枪匹马解决整个野牛人大军？你也同样做得到！"
D.Strings[51879]="我和$n是老交情了。对吧，$n？"
D.Strings[51880]="是的。$g他: 她;知道的所有东西都是我教的。"
D.Strings[51881]="这话只对你说，$n，这些昆莱人似乎慢了些。不像我们！"
D.Strings[51882]="嘿，你！更快些！砍，砍！哦嘿，你好，$n。发生了什么事？"
D.Strings[51883]="注意礼节。$n在屋里呢！"
D.Strings[51884]="至于杀死那些导魔师并击落护盾这件事究竟有多么重要，用语言已经不足以强调了，$n。"
D.Strings[51885]="啊，干得好，朋友。我得调查一下周围的情况，你去找琪麟和利维特吧。"
D.Strings[51886]="不错。护盾被击落。但你又回来做什么呢？"
D.Strings[51887]="$n，仔细听好。你必须回到怒山大帐，干掉他们的酋长。"
D.Strings[51888]="你是不是很开心？你是不是要告诉我斡耳朵战争使者已经死了？"
D.Strings[51889]="你从昆莱山的其他地方得到了什么消息？"
D.Strings[51890]="如果说有什么消息能让我好过一点，$n，那就是泰勒的死讯。"
D.Strings[51891]="总有一天我们得谈谈让你加入我队伍的事，$n。"
D.Strings[51892]="你会在这儿逗留一阵子？我们该喝一杯。"
D.Strings[51893]="你知道，你只需去西风之息，杀光那里的联盟蠢货。"
D.Strings[51894]="我听说影踪派在西南边遇到了麻烦。你知道些什么吗，$n？"
D.Strings[51895]="待在这儿，我只会变得又胖又懒。我得找点事情做做！"
D.Strings[51896]="你能撑住吗？猛虎之雷！"
D.Strings[51897]="致命攻击：猛虎之雷！"
D.Strings[51898]="死从天降：猛虎之雷！"
D.Strings[51899]="特殊攻击：猛虎之雷！"
D.Strings[51900]="换我自己做也不过如此了，我的$g小男孩:小姑娘;！我们现在做正事吧。"
D.Strings[51901]="你已经去过那个农场了吗？我们这里的食物很快就要吃完了，$g小伙子: 小姑娘;。"
D.Strings[51902]="传闻你很有些本事，$g小伙子: 小姑娘;。有些本事。我只希望你能在农场尽快完成任务。我们这里有一些人已经快饿得不行了。"
D.Strings[51903]="在那儿干得不错啊。上乘之作。如果你打算对更多的敌人迎头痛击的话，我现在正好有些任务要交给你。"
D.Strings[51904]="你我都知道那些钻油机不会自己炸成碎片。嗯……也许会，但如果你亲自去做的话，会更有乐趣的，$n。"
D.Strings[51905]="快过来，你这打斗高手，给苏利一个大大的拥抱！钻油机要爆炸了，一、二、三！啊哈哈哈哈哈哈！"
D.Strings[51906]="$g他: 她;在这！哦，你是我最喜爱的$g小伙子: 小姑娘;，就是你，$n！"
D.Strings[51907]="拿起你们的武器，$r！冲啊！"
D.Strings[51908]="我从没有见过比$n还棒的$c，你们也没见过！"
D.Strings[51909]="%s黯然落泪。"
D.Strings[51910]="荣耀归于赤精！"
D.Strings[51911]="你这是给自己找打，$c。"
D.Strings[51912]="看看现在谁在这儿。嘿呀，$n，给我们来瓶酒，到这里来！"
D.Strings[51913]="来啊！打个过瘾！"
D.Strings[51914]="我告诉你，十年之内，大家都会不停谈论“腌菜”老苏利和$n就在那些腐臭的野牛人鼻子底下点火，将他们的钻油机炸飞的事迹！"
D.Strings[51915]="一想到我们一起经历过的事情，我就泪眼汪汪，$g小伙子: 小姑娘;。"
D.Strings[51916]="这些昆莱熊猫人一切都好。他们现在要是能多体现出一点点你身上充满的那种斗志就更好了。"
D.Strings[51917]="我听说西边的火树村遇到了麻烦，是怎么回事啊？"
D.Strings[51918]="哦，的确，当护士也不错，只需在硬仗打完之后安顿好伤员。别让米希卡耍了你。"
D.Strings[51919]="$n，能占用你一点时间吗？我们有麻烦需要你帮忙解决。"
D.Strings[51920]="你调查过魔古岬了吗？可别告诉我那个小矮子又让你到其它地方跑腿了。他就不能自己收拾烂摊子吗？"
D.Strings[51921]="有什么关于魔古岬的好消息吗，$n？"
D.Strings[51922]="你真打算解决掉那个巨魔，对吧？就是他让那些魔古族复活的，是不是？"
D.Strings[51923]="终于再也不用听那巨魔喋喋不休了，这真是太好了！谢谢你，$n！"
D.Strings[51924]="我很担心那些被抓走的可怜熊猫人。你去查看过他们的情况了吗，$n？"
D.Strings[51925]="噢，$n，你做到了！看到熊猫人一家团聚，我的心里也热乎乎的。"
D.Strings[51926]="很高兴再次见到你，$n。你最近怎么样？"
D.Strings[51927]="作为一个$c，你的勇猛毋庸置疑。"
D.Strings[51928]="你带来远方的消息了吗，$n？对抗野牛人的战斗打赢了没有？"
D.Strings[51929]="泰勒上将和我刚才还谈到你呢。你好吗，$n？"
D.Strings[51930]="$n，如果你稍后有时间的话，也许我们能坐下来边喝茶边聊聊天？"
D.Strings[51931]="你看上去好得很，$n。我已经筋疲力尽了。治疗者总有干不完的活儿。"
D.Strings[51932]="关于在远方发生的一切，我们听说了各种互相矛盾的说法。告诉我，$n，事情真像传闻说的那样严重吗？"
D.Strings[51933]="有像你这样的$c在身边，我觉得安全多了。"
D.Strings[51934]="你又出色地完成了一个任务，朋友。去看看米希卡和苏利是否需要你吧。"
D.Strings[51935]="怒山大帐就在我们的边境上，$n。我要你去摧毁那道屏障，否则我们就会一败涂地。"
D.Strings[51936]="我的斥候告诉我，说你击落了护盾。我很纳闷，为什么你会回到这儿，而不是在那里追杀他们的首领。"
D.Strings[51937]="抓紧时间，$n。我的智慧告诉我，野牛人即将发动一次全面的生死突袭。我们都指望你能杀死酋长怒山。"
D.Strings[51938]="你不知道我此刻有多高兴。如果你是我麾下的军官，你会得到提拔的！"
D.Strings[51939]="$n！你好啊！到处都在传颂你的英勇事迹。"
D.Strings[51940]="拉把椅子过来，$n。给我作个伴。"
D.Strings[51941]="$n，我听说冬花关有麻烦，究竟是怎么回事？野牛人会发起比第一次进攻规模更大的第二次进犯吗？"
D.Strings[51942]="你知道今天的特大喜讯是什么吗？纳兹戈林死了。"
D.Strings[51943]="依我说，你应该召集一帮朋友，将东风之眠烧成灰烬，$n。"
D.Strings[51944]="你去过影踪营地或火树村吗，$n？我听说那里发生了与煞有关的麻烦。"
D.Strings[51945]="$n！你在那里还做了些什么？给你一句忠告；如果晋升会让你退到幕后，不要也罢。"
D.Strings[51946]="那么，$n，你拥有近乎完美的战绩。告诉我，你觉得海军怎么样？"
D.Strings[51947]="欢迎来到赤精栖木，朋友。"
D.Strings[51948]="欢迎回到赤精栖木，朋友！我很高兴看到你的归来。"
D.Strings[51949]="我们新的挑战者回来了！欢迎你，$n。"
D.Strings[51950]="欢迎回来，$n。我一直都很期盼你的回归。"
D.Strings[51951]="荣幸之至，$n。欢迎回到赤精栖木。"
D.Strings[51952]="向你致敬，赤精的勇士！你能来让我们倍感荣幸，$n。"
D.Strings[51953]="你准备好面对下一个挑战者了吗？"
D.Strings[51954]="今天已经没什么要考验你的了，$n。有空常回来看看。"
D.Strings[51955]="这里便是朱鹤的神圣发源地，他叫赤精，是南部的天神。赤精的追随者和侍僧聚集在此处锻炼身体，磨练心神。他们彼此间互相切磋，以期让朱鹤见证他们的成长。$b$b欢迎你加入我们的训练行列，$c。带着你那烈酒般的雄心和烈酒般的功夫。"
D.Strings[51956]="进入防御模式。禁用输出保险。"
D.Strings[51957]="好……很好！释放你的怒火吧！试着打倒我吧！"
D.Strings[51958]="是蠢蛋做的！"
D.Strings[51959]="刺他们左边！"
D.Strings[51960]="你去死——吧！"
D.Strings[51961]="刺他们右边！"
D.Strings[51962]="左右一起刺！"
D.Strings[51963]="胖揍蠢蛋一顿！"
D.Strings[51964]="[PH]巨魔首领施放|cffcc00ff诅咒巫毒妖术！|r [PH]"
D.Strings[51965]="[PH]巨魔首领施放|cff996300疾病巫毒妖术！|r [PH]"
D.Strings[51966]="[PH]巨魔首领施放|cff0033ff魔法巫毒妖术！|r [PH]"
D.Strings[51967]="[PH]巨魔首领施放|cff00b300剧毒巫毒妖术！|r [PH]"
D.Strings[51968]="[PH]巨魔首领施放|cffcc00ff诅咒、|r |cff996300疾病巫毒|r|cffcc00ff妖术！|r [PH]"
D.Strings[51969]="[PH]巨魔首领施放|cff0033ff魔法、|r |cff00b300剧毒巫毒|r|cff0033ff妖术！|r [PH]"
D.Strings[51970]="呼呼！"
D.Strings[51971]="看，美女，看哪！这位好心的$r带来了一些咔啡想招待你！"
D.Strings[51972]="我想它起作用了……"
D.Strings[51973]="哇呀呀呀呀！！！！"
D.Strings[51974]="不！我的火炬不见了！"
D.Strings[51975]="必须……重新夺回……控制权……"
D.Strings[51976]="欢迎来到渔人码头，$r。请随意逛逛，你在这里可以学到很多钓鱼知识。"
D.Strings[51977]="这个法术可以提高你在水中的移动速度，以防你遇到鲨鱼！"
D.Strings[51978]="它们今天好像特别容易上钩。"
D.Strings[51979]="小鱼，小鱼，小鱼，快过来……"
D.Strings[51980]="一滴|cFFF00000|Hspell:117227|h[腐蚀之水]|h|r形成了！"
D.Strings[51981]="当然，没错。这里本该有一大片森林，还有德鲁伊啥的。你说的对，你厉害，我要休息了。"
D.Strings[51982]="季，住手！你这样太莽撞了。"
D.Strings[51983]="艾莎，这是我们唯一的选择。把船炸掉，然后治愈他的伤口。我们没其他办法了。"
D.Strings[51984]="你先住手，然后我们再想想其他办法。"
D.Strings[51985]="等我们想到好办法神真子已经死了！艾莎，无所作为会给大家的生命带来危险！"
D.Strings[51986]="你炸船才是最危险的！"
D.Strings[51987]="就算再危险我也去要拼一拼。"
D.Strings[51988]="季……如果你一定要这么做，我不会阻止你。我们赌上了一切，但愿你是对的。"
D.Strings[51989]="我们……我们活过来了！"
D.Strings[51990]="<大块头雪人看着你，眼神里充满期待。>"
D.Strings[51991]="<拧开瓶子，给她递上。>"
D.Strings[51992]="现在要能喝上一杯就好了。"
D.Strings[51993]="我知道了！肯定是有一条大家伙把我的鱼饵都吃掉了！"
D.Strings[51994]="我今天遇到的鱼都是试探性的轻咬，真正咬钩的很少。"
D.Strings[51995]="就算是季，这么做也太鲁莽了。我必须阻止他。你要一起去吗？"
D.Strings[51996]="好吧……我想……我还站得住……"
D.Strings[51997]="大……大地在晃动吗？"
D.Strings[51998]="最先来的是——巨魔……他们对我们漠不关心——径直走过去，把我们的家人推到一边。\n\n然而，后面来的是——雇佣兵。他们囚禁我们，洗劫我们的宅院，还威胁说我们要敢反抗就杀光我们。"
D.Strings[51999]="也许我们应该反抗——因为，即便我们……我……我任由他们恣意夺取想要的一切，可他们还是对我们下了毒手。"
D.Strings[52000]="他们杀死了我们当中的大部分人。我是村里的治疗者——在被刺穿之后，我运用医术救活了自己……可也只是勉强留下一口气罢了。"
D.Strings[52001]="艾莎叹了口气。"
D.Strings[52002]="我们应该回去……我相信，我的医术能帮到我表哥的村庄。而且……我们必须准备葬礼，安葬失去的至亲。"
D.Strings[52003]="好吧。我们赶快前往村庄！"
D.Strings[52004]="表哥！你还好吗？"
D.Strings[52005]="还好，表弟。可是……村庄。"
D.Strings[52006]="我……明白。来，我们得谈谈。"
D.Strings[52007]="谢谢你，$r。能和你并肩作战是我的荣幸。"
D.Strings[52008]="我已经忍了很久了！该让那些野牛人看看我的拳头了！"
D.Strings[52009]="我欠你一份情，陌生人。请让我帮助你吧。"
D.Strings[52010]="谢谢你救了我，$G兄弟:姐妹;。我也不能让你就这么孤军奋战下去。"
D.Strings[52011]="今天运气如何？"
D.Strings[52012]="不怎么样。你呢？"
D.Strings[52013]="只遇到过几次试探性的啮咬。但愿很快就能有上钩的！"
D.Strings[52014]="我就知道会有人来救我们的！让我来帮你揍野牛人吧。"
D.Strings[52015]="$n引发了黑暗。"
D.Strings[52016]="哈！让我们瞧瞧你能不能看穿这个！"
D.Strings[52017]="镜……像！"
D.Strings[52018]="谢谢你，$r。我自己能回去。"
D.Strings[52019]="我欠你一份情，陌生人。谢谢你。"
D.Strings[52020]="谢谢你救了我，我的$G兄弟:姐妹;。我本来以为要死在残忍的野牛人手中了。"
D.Strings[52021]="我都已经做好了牺牲的准备。可现在……你又给了我一个机会。"
D.Strings[52022]="你看到那些自相残杀的野牛人了吗？看来他们的麻烦比我们想象中还要严重啊。"
D.Strings[52023]="你在看什么呢，陌生人？"
D.Strings[52024]="我绝不能就这么死掉。绝不！"
D.Strings[52025]="走开，别管我。让我安静地体味痛苦吧。"
D.Strings[52026]="他们不该死的……$B$B南边的村子……我的家园，我的家人！他们都被杀害了！$B$B如果我能再强壮一点该多好，那我就能救下他们了！"
D.Strings[52027]="赢的人应该是我。我更强壮，也更聪明。我本来是可以赢过他的！"
D.Strings[52028]="外乡人！影踪派的朋友。$B$B<老野牛人艰难地吐出别扭的词句。>$B$B如果你想让我扭断你的脖子，就尽管靠过来吧！"
D.Strings[52029]="<老野牛人盯着你，眼中充满了仇恨。>"
D.Strings[52030]="是你！是你杀了我的兄弟们！是你将他们的热血抛洒在我祖先的圣地上。$B$B要不是被锁着，我现在就杀了你！$B$B<暴怒过后，老野牛人突然瘫倒下来，沉重地喘息着。>"
D.Strings[52031]="能量涡流活跃了起来！"
D.Strings[52032]="你能弄清哪个是真的吗？！"
D.Strings[52033]="你是……怎么……知道……的……"
D.Strings[52034]="哈！你被骗了！"
D.Strings[52035]="能量涡流增强了！"
D.Strings[52036]="感谢你的帮助。我会去帮忙治疗伤口的。"
D.Strings[52037]="救命！树精涌过来啦！"
D.Strings[52038]="魔古族正在策划重大的阴谋。我们得阻止他们，决不能再让他们获得远古武器了。"
D.Strings[52039]="<米师好奇地看着你。>"
D.Strings[52040]="谁敢来挑战我？"
D.Strings[52041]="朋友，欢迎来到土地精集市！"
D.Strings[52042]="大多数土地精身上都会带些幸运符。$b$b瞧，口袋里的棉绒，大号的幸运符。哦，还有这臭臭的熏香，超大号的幸运符。$b$b永远别相信闻不到臭味的幸运符。不过对某些人来说倒是很幸运。"
D.Strings[52043]="某些人认为堂弟兔子脚的运气要比我——好运的八铜钱还要好。$b$b真搞笑。$b$b原因很简单：他名字里有“堂弟”，而我的名字里有“好运”。显而易见，我运气比他好多了。"
D.Strings[52044]="千万别惹恼了雪人，他们会发飙的。"
D.Strings[52045]="我听说我表弟塞拉给我发结婚请柬，都是你的功劳。$b$b谢谢你啊，现在我成了我们家还没结婚的黑牦牛。"
D.Strings[52046]="这次不跑了吗，江达克？"
D.Strings[52047]="你的侍卫们哪儿去了，大酋长？这次他们可帮不了你了！"
D.Strings[52048]="在真正的实力面前，谎言毫无用处！我比你更强大！"
D.Strings[52049]="啊哈哈哈哈！罪有应得，肮脏的东西。"
D.Strings[52050]="$C……肯定是你这家伙一直在帮助这些卑鄙的雾行鬼。"
D.Strings[52051]="我的火炬足以消灭你们三个！"
D.Strings[52052]="如果你拒绝向火炬屈服，那你就会死在火炬之下！"
D.Strings[52053]="你是下一个，小东西！"
D.Strings[52054]="太……强大了……"
D.Strings[52055]="这里还有一个雾行鬼……我能闻到它的臭味。"
D.Strings[52056]="不要以为你藏在暗影下我就看不到你……"
D.Strings[52057]="你胆敢抵抗火炬的力量……为什么不去死呢，野兽？"
D.Strings[52058]="因为我的意志……"
D.Strings[52059]="……我族人的意志……"
D.Strings[52060]="……比你的更强大。"
D.Strings[52061]="元素庇护着我！"
D.Strings[52062]="一个破碎的世界正需要你的帮助，我的学徒。你决定好要跟谁一起走了吗？"
D.Strings[52063]="我做好抉择的准备了。"
D.Strings[52064]="我知道一条穿越不息山的秘密小径。行程会增加三天，但沿途上有一条十分澄澈清凉的瀑布。绝对不虚此行。"
D.Strings[52065]="在远足之前喝上一杯咖啡会交好运。远足之后喝就是厄运了。"
D.Strings[52066]="兔子脚和八铜钱为谁运气更好而争论不休。那些愚蠢的土地精竟然不记得，没什么能比在口袋里找到棉绒更走运了。"
D.Strings[52067]="一只干净的牦牛就是幸运的牦牛。一只脏兮兮的牦牛等同于雪人攻击。"
D.Strings[52068]="好运就像是土地精美女——世间罕有，但却值得你费尽心机去找寻。"
D.Strings[52069]="当你数到3时，就一定要继续数到5。不要在数到4时停下来。厄运总是会降在那些数到4的人身上。"
D.Strings[52070]="土地精熟悉所有山路。但总有一些土地精比其他人更擅长认路。"
D.Strings[52071]="多数厄运都是由大规模的猢狲劫掠带来的。使旅途变得艰难。"
D.Strings[52072]="这场战斗你站错了边，$r。你居然与野蛮的野兽为伍！"
D.Strings[52073]="高尔……戈斯……"
D.Strings[52074]="必须立即向奥苏尔人开战。必须消除仇恨。"
D.Strings[52075]="饿死了……嗯！你！"
D.Strings[52076]="|TInterface\\Icons\\ability_warrior_stalwartprotector.blp:20|t%s施放|cFFFF0000|Hspell:117910|h[侧援指令]|h|r！"
D.Strings[52077]="情况并不总是这样。$b$b奥苏尔人以前并不是我们的敌人，他们和我们一起生活。我们相互帮助、互通有无。"
D.Strings[52078]="如果我快死了，我也要死在我的朋友身边。$b$b能竭尽全力为我的族人报仇，虽死足矣。$b$b能让敌人感到羞愤，虽死足矣。"
D.Strings[52079]="一旦援军全部就位，我们就继续向南推进。"
D.Strings[52080]="我从不让陌生人来承担影踪派的责任，但我也不会拒绝一名熟练$c的帮助。$B$B这个地方很危险，$r。如果你坚持要留下，那我也很乐意接受你的帮助。"
D.Strings[52081]="我们应该采取行动！领袖们扯皮的这点时间，都够我杀掉十个野牛人的了。"
D.Strings[52082]="班是个伟大的战略家，但他没能看清最明显的解决方法。"
D.Strings[52083]="我们终于可以行动了！几天前就该这么做了。"
D.Strings[52084]="你在那儿见到林了吗？俘虏太多了，可我找不到我丈夫。"
D.Strings[52085]="欢迎你，$r。"
D.Strings[52086]="对他丈夫的担忧已经冲昏了孙娜的头脑。"
D.Strings[52087]="孙娜和我也会有分歧，但我总是很尊重她的观点。"
D.Strings[52088]="指挥官的责任比我想象中更重。"
D.Strings[52089]="唉……她总是这样。自负，执拗，从不认错。$B$B二十年了，我从来都没有在争执中赢过她。$B$B我怎么就不会吸取教训呢？"
D.Strings[52090]="踏岚掌门，我们此处的据点已经稳固了。我们应该第一时间出击。"
D.Strings[52091]="我们已将他们逼入防御态势了。眼下，他们的人数也在减少。"
D.Strings[52092]="我没有忘！是你忘了，我丈夫也在被俘者当中。"
D.Strings[52093]="我们当然需要稳健的战术。但在能直捣黄龙时，为何要断臂自保呢？"
D.Strings[52094]="我不同意。我们不能低估野牛人的实力。"
D.Strings[52095]="可我们也一样。难道你忘记我们有多少伤员吗？多少人成了俘虏吗？"
D.Strings[52096]="可那要白流多少鲜血？战术也是有明智和愚蠢之分的。"
D.Strings[52097]="你们俩都冷静点。我们要做的事还有很多，但援救林是我们的重中之重。"
D.Strings[52098]="继续，$n，把它拔出来。要是我真死了，你也不必为此负责。"
D.Strings[52099]="野牛人羞辱了我的族人。$b$b他们很快就会知道羞辱的真正含义。"
D.Strings[52100]="<拿走奥比斯的矛。>"
D.Strings[52101]="现在南边出了点状况，需要我立刻去进行处理。"
D.Strings[52102]="当你完成任务之后，立即向你们的指挥官班·熊心报告。我已经派他全权负责这里的任务了。"
D.Strings[52103]="来吧，朋友。荣耀在等着我们。"
D.Strings[52104]="保护高尔戈斯！"
D.Strings[52105]="保护阿孔尼斯！"
D.Strings[52106]="迷雾正逐渐从我的身上散去。我会尽我所能留在这个世界，不论天长地久。"
D.Strings[52107]="我们……做到了……"
D.Strings[52108]="班，趁他们的注意力都集中在昆莱山，我们得先发制人。"
D.Strings[52109]="你是不是忘了，他们抓走了我丈夫！我们已经没时间了！"
D.Strings[52110]="可林在他们手上！"
D.Strings[52111]="他应该选我的。只有敢于冒险的人才会取得辉煌的胜利。"
D.Strings[52112]="我们绝不能输。"
D.Strings[52113]="而你却死抱着你的谨慎不放，好像它能救你似的。谨慎能救出你的兄弟吗？"
D.Strings[52114]="为什么牺牲的偏偏是他，班？我都没能让他知道我的心意。"
D.Strings[52115]="祝踏岚掌门刚刚带走了我们的大部分战士。现在进攻是愚蠢的决定。"
D.Strings[52116]="耐心点，孙娜。我们都想阻止野牛人。可我必须考虑到每一个战士，而不仅仅是你的丈夫。"
D.Strings[52117]="你别这么大声。难怪踏岚不选你来做指挥官。你太冒进了。"
D.Strings[52118]="孙娜，我们会救出他的。我保证。"
D.Strings[52119]="也可能是最惨重的失败。"
D.Strings[52120]="你已经把谨慎抛在脑后了。"
D.Strings[52121]="林的事不是任何人的错。"
D.Strings[52122]="他已经牺牲了。我们必须朝前看。"
D.Strings[52123]="我要赶到伤口那里去。别让那些野兽靠近我。"
D.Strings[52124]="你真是我的大救星。我会尽力治疗那个伤口的。"
D.Strings[52125]="我还以为自己死定了。谢谢你！"
D.Strings[52126]="如果所有的熊猫人都像你这么善良，那我相信你们已经赢得了一些新盟友了！"
D.Strings[52127]="你来解决那些野兽，我们来处理伤口。"
D.Strings[52128]="在我们进行治疗时，别让那些野兽靠近我们。"
D.Strings[52129]="我会永远站在你这边的。"
D.Strings[52130]="嗤！踏岚为什么会选你做指挥官？你只会让我们缩在床单里，等着野牛人打上门来！"
D.Strings[52131]="你脚下的土地在震颤……"
D.Strings[52132]="你来得正及时，$r！"
D.Strings[52133]="援军到了！来吧，$r，来帮我们一把！"
D.Strings[52134]="噢，真不错，像$G他:她;这样的$c完全清楚自己在战场上的位置。"
D.Strings[52135]="快帮我们把野牛人赶回去，$r！"
D.Strings[52136]="别不好意思，$c。这里的野牛人完全够我们杀的了！"
D.Strings[52137]="<米师忧心忡忡地搜索着山谷。>"
D.Strings[52138]="我是为了我们的新朋友，才容忍你的存在。不要逼我动手，人类。"
D.Strings[52139]="寇塔空在这里做什么？！$B$B还有……她为什么戴着一个可爱的小蝴蝶结？"
D.Strings[52140]="你知道吗，我认为雪人比大多数人更崇尚好咔啡。而且自从你把她带下山后，她还没吃过一个土地精！"
D.Strings[52141]="我都做了些什么啊？！我们死定了！！"
D.Strings[52142]="我不知道……把这个雪人带到这里来还是让我有一种不祥的预感……$B$B有时候我发现她在……盯着我看。"
D.Strings[52143]="<这个熊猫人刚刚遭受过殴打和折磨。他的尸体上犹有余温。>"
D.Strings[52144]="成功了！伤口正在愈合！"
D.Strings[52145]="伊拉贡开始恢复纳拉克煞引擎了。"
D.Strings[52146]="检查尸体。"
D.Strings[52147]="去南边的深石窟和断牙营地找神像。"
D.Strings[52148]="很好，你已经点燃了熏香。"
D.Strings[52149]="你感觉到了没？你的精神振奋了吗？"
D.Strings[52150]="知道吗，你所做的一切，正好体现了我们熊猫人推崇备至的一个真理。"
D.Strings[52151]="跟少昊一样，我们知道，我们最终的命运便是和大地融为一体。一切都没有真正的终结之时。"
D.Strings[52152]="我们都不可能满怀喜悦地面对死亡——但我们也不应心生恐惧、愤怒或疑虑。"
D.Strings[52153]="尽管这些熊猫人——我的朋友们——都已经倒下，但我们知道，通过他们的牺牲和你所付出的可贵努力，潘达利亚将继续焕发生机。"
D.Strings[52154]="虽然我们也许会死，但我们的消逝将会催生新的生命。这就是我们为之生存、努力和牺牲的真理。"
D.Strings[52155]="看见了吗？在他们的坟冢上，长出了新的树苗。愿这些树木长盛不衰，永远见证着逝者的牺牲，还有你为他们赢得的荣光。"
D.Strings[52156]="谢谢你，朋友。你是一位真正的英雄。"
D.Strings[52157]="哈哈！是幸运星来了！我在这里都看见神像被炸飞了。"
D.Strings[52158]="我们去找那个工程师。或许拔掉这根刺并没有我们想的那么难。"
D.Strings[52159]="急速向北！在猢狲迫害我的堂弟牦牛鞋之前找到他。"
D.Strings[52160]="林，亲爱的！不，拜托，不要！怎么会这样！"
D.Strings[52161]="要是班肯听我的就好了！我能早来一步就好了！"
D.Strings[52162]="嘘，亲爱的。现在，安静地睡吧。"
D.Strings[52163]="我绝不会放过杀害你的凶手。"
D.Strings[52164]="我发誓。"
D.Strings[52165]="呜呼！他们还说牦牛鞋不是幸运符！万分感谢你们的搭救。"
D.Strings[52166]="如果你有远程武器，就用它射断吊起土地精的绳子。"
D.Strings[52167]="他们对我说这只是一次训练任务。可我觉得现在的情况好像远不止此。"
D.Strings[52168]="你之前见到祝踏岚掌门了吗？他的强大力量简直可以媲美神话中的英雄。"
D.Strings[52169]="准备好去弄死些猢狲了吗，姑娘？"
D.Strings[52170]="踏岚掌门已经跟我说了！但愿我不会让他失望。"
D.Strings[52171]="啊！愿及时出手相救的人能交上好运。"
D.Strings[52172]="愿土地精的朋友一路好运！"
D.Strings[52173]="牢笼散发着暗示厄运的臭味。猢狲散发的臭味更糟糕。"
D.Strings[52174]="我要一个更好的幸运符以确保这种事不再发生。"
D.Strings[52175]="一定……要找到……熏香……"
D.Strings[52176]="非常感谢！"
D.Strings[52177]="是寇塔空！！"
D.Strings[52178]="我们要把你关进暴徒末路！"
D.Strings[52179]="我丈夫在几天前被野牛人抓走了。$B$B在我们说话的时候，他正处在危险之中。"
D.Strings[52180]="该死的寇塔空跑这儿来做什么？！"
D.Strings[52181]="我现在恐怕帮不上什么忙，$n。$B$B我太担心我丈夫了。"
D.Strings[52182]="林正深陷险境，我无法坐视不理。"
D.Strings[52183]="不，不，不。林，我亲爱的丈夫，你不能死。"
D.Strings[52184]="他这么冷，这么无助，毫无生气。"
D.Strings[52185]="我早就说了！我早跟班说了应该出击！这都是他的错！"
D.Strings[52186]="他几天前才跟我告别。我的眼前至今还晃动着他的脸。他怎么可能死了呢？"
D.Strings[52187]="我对林的牺牲深表遗憾，可我必须为部队中的每一个战士考虑。$B$B每一条生命都是宝贵的，都一样值得我们珍惜。$B$B我不能为了救一个人而赌上一群人的性命。"
D.Strings[52188]="寇塔蠢蛋接下来要大破坏了！"
D.Strings[52189]="形势逐渐乐观了起来。"
D.Strings[52190]="寇塔空的块头比我想象中的还要大……"
D.Strings[52191]="我为我们在奥苏尔峰的胜利而高兴。我想这是一场成功的战役。"
D.Strings[52192]="我们可以给踏岚掌门带去许多好消息了。$B$B我们在奥苏尔峰这里的胜利一定会让他高兴的。"
D.Strings[52193]="我得说，我第一次指挥作战还是相当成功的。"
D.Strings[52194]="你压不垮我们！"
D.Strings[52195]="我们在这里的胜利都是多亏了你，$n。"
D.Strings[52196]="到暴徒末路与我们会合。我们要找一些熏香和一头肮脏的牦牛。"
D.Strings[52197]="为了酋长！"
D.Strings[52198]="<他手里攥着一块手帕，上面绣着一个小字：“娜”。>"
D.Strings[52199]="我们还是遇到了一些小伤亡。除此之外，一切都相当顺利。"
D.Strings[52200]="我们一定会表彰林的英勇事迹的。"
D.Strings[52201]="首次指挥作战比我想象中的要难一些。我的决定到底正确吗？"
D.Strings[52202]="蠢蛋以为猢狲不堪一击！"
D.Strings[52203]="天哪，我们找到了一个雪人！你没听错！一个雪人！"
D.Strings[52204]="该死的蠢蛋要吃乔普乔普！"
D.Strings[52205]="蠢蛋不想让猢狲抢走果子！可猢狲照样要抢！抢啊！"
D.Strings[52206]="<孙娜前后摇晃着，凝望着天空。她没有回答。>"
D.Strings[52207]="夺走一切！"
D.Strings[52208]="“战争”这个词已经很久没有在潘达利亚出现过了。$B$B而现在，我们必须为了恢复和平……而战斗。"
D.Strings[52209]="肘锤猢狲将统治昆莱！"
D.Strings[52210]="噢，天呐。幸运符居然在这会儿坑我。"
D.Strings[52211]="在猴子面前战栗吧！"
D.Strings[52212]="也许……我对自己的处境有点太……乐观了……"
D.Strings[52213]="太好了，又有一个$c来参加战斗了！"
D.Strings[52214]="嘿，$r，我们已经应付不过来啦！快来帮把手！"
D.Strings[52215]="还有不少敌人呢！$C，快帮我们把他们赶回去！"
D.Strings[52216]="联盟控制了一辆矿车！"
D.Strings[52217]="部落控制了一辆矿车！"
D.Strings[52218]="这都要怪班。那个瞎了眼的老蠢货。"
D.Strings[52219]="一辆来自中央补给站的%s到达了。"
D.Strings[52220]="我终于可以……安息了。"
D.Strings[52221]="闭嘴，卡塔克！"
D.Strings[52222]="快醒醒……该死的！"
D.Strings[52223]="太荒唐了…"
D.Strings[52224]="你睡得像块石头！"
D.Strings[52225]="我不信你这样也能睡。"
D.Strings[52226]="你……"
D.Strings[52227]="怎么……"
D.Strings[52228]="不肯……"
D.Strings[52229]="起来？！"
D.Strings[52230]="我要捏碎你，小石头人！"
D.Strings[52231]="嗨！要叫醒这家伙还真不容易！我对他又敲又打，又吼又叫，用绳子拉，用身体压，什么法子都试过了，全都没用！$B$B好吧，我得好好想点别的主意。"
D.Strings[52232]="要我说，“先行动，后思考”才是正确的行事方法。行动可以带来灵感。但光凭思考，什么事都做不了。$B$B这就是火金之道。"
D.Strings[52233]="有办法了，浇水！我怎么没早点想到这主意。"
D.Strings[52234]="这本书的大部分封皮都已经损坏了。从还能辨认的部分看，似乎是巨魔语。"
D.Strings[52235]="这页纸肯定是某个盗墓者遗落的。游学者周卓应该知道上面写了什么。"
D.Strings[52236]="祭坛还是温热的，肯定刚刚举行过某种仪式……"
D.Strings[52237]="不！蠢蛋偷了我的乔普乔普！"
D.Strings[52238]="滑倒，去死吧！暴徒！"
D.Strings[52239]="你们……这……帮……暴徒！"
D.Strings[52240]="啊！啊！啊！啊！"
D.Strings[52241]="激情豆咔啡公司这下可有大麻烦了！"
D.Strings[52242]="空气中响起细碎的噼啪声，形成了一个|cFFF00000|Hspell:118077|h[闪电风暴]|h|r！"
D.Strings[52243]="|TInterface\\Icons\\ability_rogue_dismantle.blp:20|t%s施放|cFFFF0000|Hspell:118047|h[掠夺]|h|r！"
D.Strings[52244]="想要过两招吗，$c？"
D.Strings[52245]="别唠叨了，动手吧……"
D.Strings[52246]="他们曾为食物大打出手。但看来他们没能分到食物，有人把补给都毁了。他们为何要这么做呢？"
D.Strings[52247]="据我观察，这并不是一场派系争斗。这些野牛人为什么会自相残杀呢？"
D.Strings[52248]="野牛人酋长，和其他族人一样被杀害了。看来他也没能镇压住最终的混战。"
D.Strings[52249]="你能破解我的双爪白虎式吗？"
D.Strings[52250]="我不喜欢这个地方，$r。这里有点诡异。"
D.Strings[52251]="这个村子里有种让我毛骨悚然的气息。"
D.Strings[52252]="在完成任务之前，我们不能休息。"
D.Strings[52253]="谢谢你，$n。我有很多情况要向班报告。我想我能找到回去的路。"
D.Strings[52254]="那么，朋友们……我们该如何找到隐秘大师呢？"
D.Strings[52255]="要是让土拨鼠看到你毁了它们的地洞，一定会气疯的。先把它们解决掉，然后就好办了。"
D.Strings[52256]="你们可真是弱不禁风啊。希望这次挑战能够增强你的力量！"
D.Strings[52257]="我们为什么不吃这根胡萝卜？"
D.Strings[52258]="我刚看到一根长得很滑稽的胡萝卜！"
D.Strings[52259]="胡萝卜就种在我们的前面！"
D.Strings[52260]="胡萝卜？给我们的？！？！"
D.Strings[52261]="看，看！古怪、畸形的胡萝卜！"
D.Strings[52262]="我们真走运。"
D.Strings[52263]="今天碰上好运气了。"
D.Strings[52264]="胡萝卜都是好东西！"
D.Strings[52265]="太……完美了。"
D.Strings[52266]="我信了。"
D.Strings[52267]="废话少说，开吃吧！"
D.Strings[52268]="这根胡萝卜有点怪怪的……"
D.Strings[52269]="等等，等一下。你闻到……芜菁了……？"
D.Strings[52270]="有点可疑啊……"
D.Strings[52271]="我差点看都没看就一口咬上去了！"
D.Strings[52272]="[PH]巨魔首领施放一种巫毒妖术！[PH]"
D.Strings[52273]="嘿！看你把东西都溅到哪儿了。"
D.Strings[52274]="什么，我们已经干完了！？"
D.Strings[52275]="你终于不用再继续站在这恶心的水里了吗？"
D.Strings[52276]="或许我们可以找些更古怪更肮脏的瓶子来装泥水。"
D.Strings[52277]="我最喜欢的就是你把泥水溅到我眼睛里。"
D.Strings[52278]="我可没在嘲笑你。"
D.Strings[52279]="宝珠出现了！"
D.Strings[52280]="宝珠又回来了！"
D.Strings[52281]="宣泄吧，永恒之能！"
D.Strings[52282]="创造之源，所向披靡！"
D.Strings[52283]="能量涡流减弱了！快离开平台！"
D.Strings[52284]="能量涡流停止了！"
D.Strings[52285]="能量涡流开始关闭。"
D.Strings[52286]="纳拉克煞引擎开始自毁！"
D.Strings[52287]="这么说，你是个酿私酒的？"
D.Strings[52288]="是的。我从会喝啤酒开始就在酿造啤酒了。$b$b这里的人说我在浪费时间，我可以去村子里买那种大桶的啤酒。我不那么认为。酿造自己的啤酒总是别有一番趣味。"
D.Strings[52289]="泥盏是你的真名吗？"
D.Strings[52290]="噢，当然不是了。那只是我酿啤酒的方法。$b$b泥水，你看……里面总会有点小虫子，帮你发酵酒浆。有人会用真正的酵母，就是那种在人为控制的环境下，在正规酒厂里生长出来的东西，诸如此类的。而我喜欢用泥水。$b$b这更合适我。$b$b我就是不像你所说的那种“科班出身”的家伙。"
D.Strings[52291]="你好！还有，呃……向你致敬，我猜。$b$b不好意思，真不知道该说些什么，我这里通常很少有人来。$b$b当然了，除非是他们来我这里买酒的时候。"
D.Strings[52292]="[PH]准备好战斗了吗？"
D.Strings[52293]="[PH]我准备好了！"
D.Strings[52294]="幸亏有你，我……我想我暂时安全了。"
D.Strings[52295]="现在！来看看是何种黑暗腐蚀了此地吧！"
D.Strings[52296]="$n，请帮我激活那三个大型图腾。"
D.Strings[52297]="跟着我。我们要用这些图腾来净化大地。"
D.Strings[52298]="我赢了？耶！"
D.Strings[52299]="我猜他就在森林里的某个地方？"
D.Strings[52300]="那里看起来可不怎么友好啊，或许我应该……"
D.Strings[52301]="不！我都走了这么远了，我不会放弃的！"
D.Strings[52302]="出……出什么事了？！"
D.Strings[52303]="我有个规矩：任何人只要管我叫声帅哥，就有免费的啤酒喝。"
D.Strings[52304]="机器开始嗡嗡作响了！到下层去！"
D.Strings[52305]="|TInterface\\Icons\\ability_rogue_envelopingshadows.blp:20|t%s施放|cFFFF0000|Hspell:117506|h[不灭之影]|h|r！"
D.Strings[52306]="|TInterface\\Icons\\warrior_talent_icon_furyintheblood:20|t%s施放|cFFFF0000|Hspell:117708|h[癫狂之吼]|h|r！"
D.Strings[52307]="上古魔古机器损坏了！|cFFFF0000|Hspell:116779|h[泰坦寒气]|h|r涌入了房间！"
D.Strings[52308]="上古魔古机器超载了！|cFFFF0000|Hspell:116779|h[泰坦寒气]|h|r涌入了房间！"
D.Strings[52309]="守卫石犁村的意义或许比你所了解的还重要。$b$b如果螳螂妖拿下了石犁村，他们就能顺势夺下整个谷。越过这道墙后，就没有什么能够阻止他们彻底扫平整个潘达利亚的了。"
D.Strings[52310]="螳螂妖在发动进攻，而我们却毫无防备，真是惭愧。$b$b在一般情况下，我们是能够预测敌人行动的。我们原本预测螳螂妖的下一次大规模入侵应当发生在十年之后，因为他们总是每百年入侵一次。$b$b当前的侵袭虽算不上“大规模”，但还是足以令普通乡村猝不及防。要不是我的影踪派弟子一直在城墙上警戒的话，石犁村恐怕早已陷落了。"
D.Strings[52311]="是的，守护石犁村的重任当前由我、守卫队长橡盾和我们派另外三名弟子担负着。正如之前我所说的，那三名影踪派弟子坚守在长城脚下，等待迎接下一波攻势。这是我们的责任——保护潘达利亚免遭普通老百姓所遗忘了的敌人蹂躏。$b$b虽然我们在石犁村的人数捉襟见肘，但我们还不打算向昆莱山请求增援……除非这里的形势变得更糟。说白了，打个比方，如果长城的弱点被攻破了。"
D.Strings[52312]="前几天，我在警戒塔上看到地底爆发出一股黑暗能量。它从西面而来，挤压着城墙，几乎把整个墙体撕裂开来。$b$b你现在还能看到它留下的痕迹。它把这些农夫的土地彻底毁了。$b$b后来，螳螂妖斥候也赶来了。我说不准他们到底是有备而来，还是只想趁火打劫。没准他们也是想逃离那个当初震裂大地的东西呢。"
D.Strings[52313]="发生什么事了？"
D.Strings[52314]="影踪派？"
D.Strings[52315]="总之，城墙那儿怎么了？"
D.Strings[52316]="我在那城墙上花费了一生的心血，$n。我放弃所有的一切成为影踪派弟子，只为阻止像这样的事情发生。$b$b我失败了。"
D.Strings[52317]="你为我们所做的一切，$n……我们都铭记在心。"
D.Strings[52318]="你瞧见这些东西了吗？这地方真是太棒了！"
D.Strings[52319]="谢谢你带我一起出来探险，$n。"
D.Strings[52320]="我真不敢相信陈叔宁愿坐在家中喝的酩酊大醉，也不愿出来走走，来这探险！"
D.Strings[52321]="这可是陈叔逼我保证不这么做的！$b$b听着，陈叔或许是一个笨笨的、无聊的、懒散的、肥肥的老叔，但这并不意味着我不尊重他。他叫我不要卷入任何麻烦中，我也一直都是这么做的。$b$b话说回来，你看上去一个人就能搞定了。你不会要一个小姑娘去帮你打打杀杀吧。"
D.Strings[52322]="你为什么不过来帮把手啊？"
D.Strings[52323]="风是我的盟友！"
D.Strings[52324]="我在等待挑战者。"
D.Strings[52325]="啊……一场挑战。"
D.Strings[52326]="光荣地战斗。"
D.Strings[52327]="一位$c？非常吸引人。"
D.Strings[52328]="朋友，我是来帮忙的。让我们把刹嗳呼送进坟墓！"
D.Strings[52329]="我是来帮你消灭毒害我族人的祸害的！"
D.Strings[52330]="我们将合力粉碎刹嗳呼！"
D.Strings[52331]="这些怪物死时会爆炸……我知道了，我们可以在刹嗳呼身边杀死它们！"
D.Strings[52332]="嗷！它们死掉时炸伤了我们，不过它们也会伤害到他的！把它们弄到他身边去！"
D.Strings[52333]="我还要一个祥和图腾。"
D.Strings[52334]="我——我出什么事了？"
D.Strings[52335]="我感觉……满腔愤恨……"
D.Strings[52336]="谢谢你把我从那种可怕的梦魇中解救出来。"
D.Strings[52337]="怎么了？我突然感到内心十分祥和……"
D.Strings[52338]="谢谢你，朋友。我不可能自己摆脱煞魔的控制。"
D.Strings[52339]="那是……煞魔吗？我刚才真想把所有人都撕成碎片！"
D.Strings[52340]="我……出什么事了？我现在感觉平静多了。"
D.Strings[52341]="我被煞魔控制了？我到现在才反应过来……"
D.Strings[52342]="……这就是我在酿酒厂的遭遇。"
D.Strings[52343]="我准备好了，可以开始仪式了。"
D.Strings[52344]="你的仇恨淹没了你！"
D.Strings[52345]="管道被摧毁了，|cFFFF0000|Hspell:116779|h[泰坦寒气]|h|r漏进房间里来了！"
D.Strings[52346]="你的怒火！我要汲取你的怒火！"
D.Strings[52347]="这是什么？！他们的怒火……在灼烧我……"
D.Strings[52348]="不！这不可能！你无法阻止我！"
D.Strings[52349]="我……感觉到什么东西。是……平静吗？"
D.Strings[52350]="你感到内心的仇恨沸腾了起来。"
D.Strings[52351]="你的仇恨更强了！立刻控制住它！"
D.Strings[52352]="我要用轰轰炸飞蠢蛋！"
D.Strings[52353]="让蠢蛋尝尝我的轰轰吧！"
D.Strings[52354]="蠢蛋死定了。我有一大盒轰轰！"
D.Strings[52355]="轰轰飞，末日到！"
D.Strings[52356]="轰轰狂欢时间到！"
D.Strings[52357]="轰轰大狂欢！"
D.Strings[52358]="给你来点儿轰轰！"
D.Strings[52359]="轰轰大狂欢，蠢蛋死定啦！"
D.Strings[52360]="该轰轰箱登场啦！"
D.Strings[52361]="布姆布姆大师准备要炸飞一些蠢蛋了！"
D.Strings[52362]="小点心和小脆饼卖得最好。你要来点儿吗？"
D.Strings[52363]="够了！滚回灵魂的世界去吧！"
D.Strings[52364]="这是一次考验，帮助商人罗福证明了你有一颗充满同情与怜悯的心。$c，尚师父会很高兴的。"
D.Strings[52365]="你通过了所有的考验。你找到了燧焰，并且把他安全地送回了寺庙，$n。"
D.Strings[52366]="徒儿们，我们现在面临着更大的难题。剧痛正折磨着神真子。皮之不存，毛将焉附？这块土地若有不测，我们也在劫难逃。"
D.Strings[52367]="我们需要和神真子谈谈，并且找出治愈它的办法。但首先，我们必须寻回四位元素之灵，燧焰正是第一个。"
D.Strings[52368]="季，我想派你前去大箩农场寻找上古土灵无垢的踪迹。"
D.Strings[52369]="艾莎，你立即去咏之池寻找上古水灵涓流。"
D.Strings[52370]="而你，$n，我需要你来指引所有人的方向。艾莎在东边的咏之池。但去找她之前，先陪我聊聊吧。"
D.Strings[52371]="得令！"
D.Strings[52372]="遵命，师父。"
D.Strings[52373]="欢迎你，燧焰。这里的人民想念你的温暖。"
D.Strings[52374]="同心协力，其利断金！"
D.Strings[52375]="我喜欢你的身手！"
D.Strings[52376]="这下够他受的了。"
D.Strings[52377]="喔！那家伙肯定痛死了！"
D.Strings[52378]="他们完全没机会嘛。"
D.Strings[52379]="被你轻松摆平了。"
D.Strings[52380]="我得多和你一起打打架。"
D.Strings[52381]="大功告成！我们回去看看艾莎在冥想时有什么收获。[移除？]"
D.Strings[52382]="回码头见！"
D.Strings[52383]="动手吧，你这猴头！"
D.Strings[52384]="这只猴子要吃苦头了！"
D.Strings[52385]="解决掉他了！一切顺利。"
D.Strings[52386]="放下武器，牛头人，不然我就再把你铐上。"
D.Strings[52387]="还有人在船骸里！多派些人去救出那些伤员。"
D.Strings[52388]="去西边叫些牧师回来，营地需要更多治疗者。"
D.Strings[52389]="我们孤注一掷，但成功了。神真子会好起来的。"
D.Strings[52390]="尚喜师父，我想要加入联盟，一起返回他们的故乡。"
D.Strings[52391]="季，你呢？你想加入部落，和他们一起回去吗？"
D.Strings[52392]="是的……也许那样最好。我喜欢他们，而且我想我能在他们那边大展身手。"
D.Strings[52393]="至于你，我年轻的徒儿，你将去往何处？"
D.Strings[52394]="你拯救了神真子，成就了一番伟大的事业。我们所有人都为你骄傲。"
D.Strings[52395]="你的旅程还没有结束。我们的新盟友来自一个破碎的世界，你的能力可以帮助他们。"
D.Strings[52396]="是时候感受下棘杖家族的愤怒了！"
D.Strings[52397]="哟，还挺疼！打得不错，朋友。"
D.Strings[52398]="你们之中谁准备好臣服在棘杖门下了？"
D.Strings[52399]="这么说，是班派你来杀我的？就像他杀死我丈夫那样？"
D.Strings[52400]="你那可怜的仪式毫无意义！我回不了头了！"
D.Strings[52401]="仇恨给了我足以毁灭你的力量！"
D.Strings[52402]="我明白了……仇恨……吞噬了我。告诉班……我……原谅他了。"
D.Strings[52403]="啊哈哈哈……可怜的爬虫！"
D.Strings[52404]="就连最强大的战士，也像待宰羔羊瑟瑟发抖。"
D.Strings[52405]="马上就轮到你们了。仇恨，将让你们自相残杀，并将整个世界燃尽！"
D.Strings[52406]="我投降！你赢了。"
D.Strings[52407]="这可比和一个土地精拼酒容易多了。"
D.Strings[52408]="选择你的勇士。"
D.Strings[52409]="呸！被你这种人打败！对赞达拉祭司来说简直是耻辱。"
D.Strings[52410]="……但这也没什么。拿上战利品，当心你们的小命。"
D.Strings[52411]="我走了。该为我的灵魂找个新家了。"
D.Strings[52412]="死亡是扇门，而时间是扇窗。我会回来的！啊哈哈哈哈哈哈！"
D.Strings[52413]="试试你的力量！"
D.Strings[52414]="第一回合……开打！"
D.Strings[52415]="你滚开！"
D.Strings[52416]="这里是兔妖的地盘了，快走开！"
D.Strings[52417]="失败！"
D.Strings[52418]="需要……更好的……治疗者……"
D.Strings[52419]="蹩脚的……坦克……"
D.Strings[52420]="但是……但是……我需要那个装备……"
D.Strings[52421]="肯肯……投降了！"
D.Strings[52422]="干得……好……勇士。"
D.Strings[52423]="上古机器发生故障了！所有部件都发生了|cffFF0000|Hspell:118041|h[超载]|h|r！"
D.Strings[52424]="伊拉贡已经到了！PH"
D.Strings[52425]="你根本不明白自己放出了什么！"
D.Strings[52426]="这机器会彻底毁灭你。PH"
D.Strings[52427]="啊，你已经到了？我这边还没准备好呢……你也是。$B$B先去祭拜神龛，回头再来找我吧——我们不该匆匆忙忙，这样显得对大山不敬。"
D.Strings[52428]="好了，我们已经准备好开始了。"
D.Strings[52429]="差不多好了……"
D.Strings[52430]="谢谢你，勇敢的$c。"
D.Strings[52431]="[PH]你得救了！"
D.Strings[52432]="是啊……孙娜不是会独自逃跑的人。"
D.Strings[52433]="班，你看起来很担心。"
D.Strings[52434]="她肯定是对她丈夫的死太伤心了。"
D.Strings[52435]="或许吧，但这并不是谁的错。"
D.Strings[52436]="你做了你认为最好的选择。没有哪个指挥官能预知未来。"
D.Strings[52437]="你们曾立下过影踪派的血誓，不是吗？比仇恨更强大的力量会将你们团结在一起。"
D.Strings[52438]="不，她不会恨你的。至少不会一直如此。呵呵呵！"
D.Strings[52439]="呃，这是什么臭味？"
D.Strings[52440]="可这里散发着死亡的恶臭！"
D.Strings[52441]="我知道，她在怪我。"
D.Strings[52442]="我应该冒一次险，让部队出击的。"
D.Strings[52443]="可现在……她肯定很恨我。"
D.Strings[52444]="但愿如此。"
D.Strings[52445]="这里太安静了。我们得调查一下。"
D.Strings[52446]="全部停下。大家散开！"
D.Strings[52447]="嗯，孙娜的足迹在这儿消失了。找到她之前，我们绝不离开。"
D.Strings[52448]="看。孙娜的足迹往前面的村子去了。"
D.Strings[52449]="这里看起来就像……屠杀现场。"
D.Strings[52450]="在这里？你……确定吗？"
D.Strings[52451]="哎呀！蠢蛋赢了！别抢走我的轰轰！"
D.Strings[52452]="我看见孙娜的东西了！她肯定在这里宿过营。可是她去哪儿了呢？"
D.Strings[52453]="我不喜欢这地方的样子。"
D.Strings[52454]="你说，这地方不会……闹鬼……吧？"
D.Strings[52455]="我一点都不想知道这里出了什么事。太可怕了，我连想都不敢想。"
D.Strings[52456]="啊！熊吓熊会吓死熊的！"
D.Strings[52457]="孙娜真的会在这个地方嘛？"
D.Strings[52458]="嘿，$r，你对这地方了解多少？"
D.Strings[52459]="我从没见过这样的东西。你呢，$n？"
D.Strings[52460]="别害怕，$r。我们会保证所有人的安全的。"
D.Strings[52461]="摔跤手要毁掉今天的比赛。"
D.Strings[52462]="显然，一个猢狲找到了一箱炸弹，然后就认为自己是武僧了。"
D.Strings[52463]="我想知道是谁说服雪怒让蜥蜴人参加比赛的。我喜欢观看力量的对决，但那些生物也太……狂暴了。"
D.Strings[52464]="你知道，我曾经看见过摔跤手的真面目。真的。"
D.Strings[52465]="联结应该只需片刻，但我会完全进入灵魂出窍状态。"
D.Strings[52466]="保护好我——我相信你能应对任何干扰。"
D.Strings[52467]="游学者！你身上有属于我的东西。"
D.Strings[52468]="聪明，竟然想到藏在这上面——用元素掩盖踪迹。但我的魁麟猎犬的鼻子灵得很，即便是躲在这儿，也一样会被发现。"
D.Strings[52469]="你指望靠这小崽子来阻止我们？哈！"
D.Strings[52470]="都完成了。我错过什么了吗？"
D.Strings[52471]="好吧。今天……是你表现的日子……"
D.Strings[52472]="|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t%s开始施放|cFFF00000|Hspell:117436|h[闪电囚笼]|h|r！"
D.Strings[52473]="继续进行联结吧，周卓。"
D.Strings[52474]="$n，外面很危险。为了你自己的安全考虑，一定要使用我给你的图腾！"
D.Strings[52475]="送我去地狱咆哮的希望！"
D.Strings[52476]="难以置信！这里是传说中的魔古山藏书馆！你能想象我们可以从这些地宫里发掘出多少秘密吗？"
D.Strings[52477]="我心爱的$n！你会为此付出代价！"
D.Strings[52478]="你还在等什么呢？我们快开始调查吧！"
D.Strings[52479]="请送我去迷航港。"
D.Strings[52480]="看这里！永影巫王提安的历史记录于此。他法力无边，曾将整个帝国都笼罩于恐惧与黑暗之中。"
D.Strings[52481]="把他们的头给我带来！"
D.Strings[52482]="让影踪派去死吧！让所有的熊猫人都去死吧！"
D.Strings[52483]="野牛人，前进，冲锋！后退者死！"
D.Strings[52484]="蠢蛋被炸飞了！"
D.Strings[52485]="涯尺！曜！把这些蠢货撕成碎片！"
D.Strings[52486]="现在轮到肯肯了！和我们计划的一样！"
D.Strings[52487]="记住，雪怒让我们合作。"
D.Strings[52488]="我们能做到！"
D.Strings[52489]="我们合作的话就能赢。"
D.Strings[52490]="猢……狲！"
D.Strings[52491]="肯肯做到了！"
D.Strings[52492]="得了！肯肯才不需要靠锦鱼人帮忙来赢取胜利。"
D.Strings[52493]="跑吧，懦夫！乡巴佬！这片土地将重归自然的怀抱！"
D.Strings[52494]="仇灰出现在了绿石村北面的工匠区。快去挑战他！"
D.Strings[52495]="来吧，勇士！冲洛洛来声咆哮！"
D.Strings[52496]="不！不不不！不能再给你松饼了！结束了才有松饼吃！"
D.Strings[52497]="[PH]恭喜——你获胜了"
D.Strings[52498]="挑战者们，欢迎参加我的力量勇者武道会！"
D.Strings[52499]="任务目标完成。*点击！*"
D.Strings[52500]="小心，$n！我们被包围了！"
D.Strings[52501]="煞魔总算现身了。小心点！"
D.Strings[52502]="只要稍有不慎，你就会被自己的仇恨吞噬。"
D.Strings[52503]="我们还没有摆脱困境呢。"
D.Strings[52504]="看来我们压制住了煞魔……但只是暂时的。"
D.Strings[52505]="我简直不敢相信。你压制住了自己的恨意。"
D.Strings[52506]="加油，孩子！揍他！"
D.Strings[52507]="打跑那个摔跤手的好运！"
D.Strings[52508]="把椅子给他！"
D.Strings[52509]="这么多年的训练就是为了今天，我决不能让我的兄弟姐妹们失望！"
D.Strings[52510]="这就是煞魔的样子吗？比我的师傅们描述的还要可怕啊。"
D.Strings[52511]="别让它抓住你！"
D.Strings[52512]="多用左右摆拳，多跑动！"
D.Strings[52513]="其他游侠都开始自相残杀了。$B$B我们也差点跟着发疯。多亏雅丽亚反应够快，我们现在安全了。"
D.Strings[52514]="我们都受过抵抗煞魔影响的意志强化训练，可这比我们想象的还要厉害。"
D.Strings[52515]="好吧，我在和煞魔的首次交锋中幸存了下来。那比我想象的还要吓人。"
D.Strings[52516]="我下次面对煞魔时，会做好准备的。"
D.Strings[52517]="煞魔出其不意地控制了我们，幸好没有造成伤亡。"
D.Strings[52518]="蠢蛋要把闪电和滚雷吃到肚子里去！"
D.Strings[52519]="痛扁那个蠢蛋，就像讨债一样！"
D.Strings[52520]="不不不！打啊！然后猛刺！"
D.Strings[52521]="踏岚和班都是战略和后勤学大师。相比计划，我更喜欢战斗。"
D.Strings[52522]="我们为什么还要等下去？他们应该让部队出击！"
D.Strings[52523]="我丈夫在几天前被野牛人抓走了。在看到他安全归来之前，我一刻都安宁不下来。"
D.Strings[52524]="就算我死了，你们也阻止不了即将到来的狂风暴雨！雷电之王必将崛起！"
D.Strings[52525]="你能帮我找到护符吗，米师？"
D.Strings[52526]="<米师似乎已经准备离开了。>"
D.Strings[52527]="欢迎，$c！务必要抽出时间欣赏景色啊！"
D.Strings[52528]="你注意到在卓金村附近有什么奇怪的事吗？"
D.Strings[52529]="看着这么美丽的风景，一定会让你茅塞顿开。"
D.Strings[52530]="在找到孙娜之前，我绝不离开。"
D.Strings[52531]="逃避危险绝非我们的本性。为了保护我们所爱的人，我们会毫不犹豫地闯入黑暗之中。"
D.Strings[52532]="看不见的敌人或许才是最危险的敌人。"
D.Strings[52533]="坚守阵地！我们会把煞魔从这里赶出去的！"
D.Strings[52534]="幽灵都离开了。噩梦结束了。"
D.Strings[52535]="它刚……死去不久。"
D.Strings[52536]="这一点毫无疑问，这些生物肯定受到了煞魔的影响。"
D.Strings[52537]="看看它们的体型就知道了！这一定是只成年雄性螳螂妖。"
D.Strings[52538]="这就是说螳螂妖女皇也牵扯其中……不知何故。"
D.Strings[52539]="他的身体——伤痕累累。都是些旧伤。"
D.Strings[52540]="但也不是一般的伤痕，这些伤痕是熊猫人的武器造成的。"
D.Strings[52541]="在这里！这就是我们一直寻找的东西！"
D.Strings[52542]="牦牛毛。"
D.Strings[52543]="这地方让我感到不安，可我们影踪派是不会逃避危险的。"
D.Strings[52544]="我听到了复兴者的威胁，但模糊不清……稍纵即逝，就好像回忆梦里的细节。$B$B看来我又欠你个人情。"
D.Strings[52545]="墨墨交上土地精的好运气了！"
D.Strings[52546]="臭蠢蛋要遭殃了。"
D.Strings[52547]="墨墨将会是最幸运的猢狲！"
D.Strings[52548]="这里没有。继续前进。"
D.Strings[52549]="这只没有。"
D.Strings[52550]="这里没有。继续寻找。"
D.Strings[52551]="不……这里也没有。继续寻找。"
D.Strings[52552]="波波是奇奥奇奥的！"
D.Strings[52553]="这里有些你或许会感兴趣的东西。"
D.Strings[52554]="我不需要。你想要吗？"
D.Strings[52555]="这里没有任何线索……但我找到了这个。"
D.Strings[52556]="格林托克斥候发出了警报！"
D.Strings[52557]="我可不想你心烦意乱地待在这里……"
D.Strings[52558]="你以为你是谁？一个$c或者什么别的玩意儿？"
D.Strings[52559]="起泡沫的黄啤酒是给懦夫和土地精准备的。"
D.Strings[52560]="你敢来尝尝我酿的酒吗？"
D.Strings[52561]="只要抿上一口，你就会知道自己有多么差劲了。"
D.Strings[52562]="我跟你打？哇哦，这场对决比我想得还要简单。"
D.Strings[52563]="下一次你可没那么容易全身而退了。"
D.Strings[52564]="这一回是你赢了，可等我们下次相遇时，我会拿出更好的佳酿。"
D.Strings[52565]="我今天本可以打败你的，你知道吗。我只要更快地切换到“醉酒姿态”就行了。"
D.Strings[52566]="尽情享受胜利的滋味吧，只是暂时的。下次我们交手时，你会尝到被击败的滋味。$b$b事实上，我会把我接下来要酿的酒起名叫“失败苦酒”——口感不会太糟，但会让喝得人沉浸在失败的痛苦中不能自已。"
D.Strings[52567]="欢迎你，旅行者。看到这次比赛如此多元化，我很高兴。"
D.Strings[52568]="不必理会我身后的那只猢狲。他的戒律训练正在……进行中。"
D.Strings[52569]="我们从翡翠林出发，历尽跋涉才在今天抵达这里。我希望能在这次比赛中提升自己的技能。"
D.Strings[52570]="我对即将到来的挑战充满期待。"
D.Strings[52571]="很高兴再次见到你，朋友。我们帮助石犁村摆脱螳螂妖威胁的经历还历历在目呢，仿佛就发生在昨天。"
D.Strings[52572]="与石犁村的救星交谈，总让我感到无比荣幸。"
D.Strings[52573]="你真该听听他们是怎么说你在石犁村的事迹的。"
D.Strings[52574]="很高兴能在这里见到你，我的朋友。距离我们在四风谷携手合作已经有段日子了。"
D.Strings[52575]="肯肯还是那么招人讨厌，喜欢毁坏任何他所触碰过的东西。我希望有朝一日能够不要再和他一起结伴同行。"
D.Strings[52576]="有勇无谋，亦是枉然。"
D.Strings[52577]="啊，魔古山帝王的宝库。这个按钮有什么用…?"
D.Strings[52578]="雪怒坚持认为，只要我和肯肯联手，就一定能击败你。或许下回我们能好好的较量一场。"
D.Strings[52579]="打得漂亮。真不可思议，你竟然已经变得如此强大了。"
D.Strings[52580]="希望下回雪怒能让我直接挑战你，而不是被一个猢狲碍手碍脚。"
D.Strings[52581]="哈？你是谁？快走开。摔跤手要跟教头洛洛多练一会儿！"
D.Strings[52582]="蠢蛋今天走运了。摔跤手只好重赛了！"
D.Strings[52583]="嗯呼嗯呼！"
D.Strings[52584]="肯肯经历了艰苦的修行，现在已是超级强壮的武僧了。"
D.Strings[52585]="我对这臭味儿感到很抱歉。聪明的阿西约是条臭鱼。"
D.Strings[52586]="要不是阿西约拖后腿，肯肯赢定了。"
D.Strings[52587]="下一次肯肯一定要赢！不管有没有阿西约。"
D.Strings[52588]="石犁村的英雄！你好啊。"
D.Strings[52589]="这就是那位了不起的$R，石犁村的救星！"
D.Strings[52590]="噢，很高兴再次见到你！聪明的阿西约是个烂伙伴。"
D.Strings[52591]="闻起来，你似乎马上就要输了。"
D.Strings[52592]="我的队伍将粉碎你。"
D.Strings[52593]="你知道我是谁吗？你知道我是谁吗？！"
D.Strings[52594]="下一次，我才不会这么轻易被打败！我已经让我的治疗者记住他的位置了。"
D.Strings[52595]="啊！别跟我说话！坦住！坦住！把他的注意力吸引过去，你这蠢货！"
D.Strings[52596]="我们下次一定会粉碎你！我们的坦克会记得拉好你的仇恨的！"
D.Strings[52597]="你身上有股战利品的气味。"
D.Strings[52598]="我们精疲力尽，而且我也没拿到装备。"
D.Strings[52599]="看上去这些就是无情战王齐昂的记录了。无数诸侯都曾臣服于其铁腕统治之下。"
D.Strings[52600]="我一直梦想来到这里。就是这地方！我将在今天赢得比赛！"
D.Strings[52601]="看到这把棘杖了吗？这是我家世代相传的神兵，到目前为止已赢过数百场比赛。$b$b你能感受到其中的力量吗？在这儿，它更是前所未有的强大。"
D.Strings[52602]="嗯，今天你赢了，可那并不代表我明天就不会赢。棘杖老爹总是说，失败是成功之母，擦干血迹，爬起来再战就是了，总有打赢的一天。"
D.Strings[52603]="对这个人物我有所耳闻：迅影匪王速不台。传闻中他是个精通箭术的神偷。他劫富却不济贫，将偷盗之物都归为己有。"
D.Strings[52604]="啊！这不是那位在石犁村抢了我风头的“大英雄”嘛！$b$b开个玩笑，开个玩笑。那是场伟大的战役。很荣幸能与你并肩作战。"
D.Strings[52605]="这是什么？我还不曾听闻这个帝王。暴虐疯王蒙恩？根据这段描述，蒙恩是迄今为止最邪恶、最疯狂的暴君。"
D.Strings[52606]="你来了？这是不是意味着我们终于有机会同场竞争大赛冠军了？"
D.Strings[52607]="喔，这么说我要对决石犁村的勇士了？太棒了！"
D.Strings[52608]="哈吉斯想要掏你的口袋。"
D.Strings[52609]="我很期待我们的对决。"
D.Strings[52610]="有关雪怒挑战赛的消息都传到我在翡翠林的老家那儿去了。我可无法拒绝这样的邀请。"
D.Strings[52611]="你长着一张英雄脸。天知道你是不是真那么坚毅。"
D.Strings[52612]="没人能质疑你的战斗力，勇士。"
D.Strings[52613]="蠢蛋以为自己能抵挡住轰轰大狂欢？"
D.Strings[52614]="布姆布姆大师这儿有超级强大的火器。"
D.Strings[52615]="蠢蛋认为它能赢？哈！布姆布姆大师从不说“投降”！咱们死磕到底吧！"
D.Strings[52616]="力量有多种形态。它对某些人是武器，对另一些人则是负担。而对我自己而言，它是生存之道。"
D.Strings[52617]="雪怒教导我们，力量是一种需要通过不断练习才能驾驭的工具。"
D.Strings[52618]="雪怒每隔几天就会举办一场力量大赛。只有全潘达利亚最强大最勇敢的挑战者才敢前去比试。"
D.Strings[52619]="小心雪怒的幼崽。别看他们个子小，它们可以靠纯粹的力量弥补这一弱点。"
D.Strings[52620]="相传，雪怒已经有几百年没有在他自己举行的比赛中大显身手了。$b$b他说是这是为了让我们都能有比试的机会。可我觉得，那只是因为他老了。或者……至少是……对于他那样的……存在……来说，已经老了。"
D.Strings[52621]="你们管那叫做强壮的臂膀？还没有我瘀伤里的肌肉多呢。"
D.Strings[52622]="你有猛虎的眼睛吗？"
D.Strings[52623]="|TInterface\\Icons\\ability_warrior_charge.blp:20|t阿达罗格盯住了|cFFFF0000$n|r并开始施放|cFFFF0000|Hspell:119299|h[地狱冲锋]|h|r！"
D.Strings[52624]="恭喜你取得胜利，勇士！"
D.Strings[52625]="你的到来令我们大感荣幸，勇士。"
D.Strings[52626]="你今天展示的卓越战技真是令我们大开眼界啊。干得好！"
D.Strings[52627]="我已经好多天没看到过这么精彩的比赛了！"
D.Strings[52628]="打得漂亮，勇士！"
D.Strings[52629]="我看了你今天的战斗。跟某些前来参加比赛的大师相比，你的拳脚显得略欠章法，但显然更具实用性。我今后会关注你，并向你学习的。"
D.Strings[52630]="什么，一个$c？也要加入比赛？这下变得更有趣了。"
D.Strings[52631]="嗯。一位$c可是颇具看点啊，但让我们看看你将如何对抗摔跤手或布姆布姆大师吧。"
D.Strings[52632]="真是个比赛的好日子啊，你觉得呢？"
D.Strings[52633]="我把钱押在了其中一个小毛孩身上，他们都是从四风谷来的。$b$b听说他们曾受训于翡翠林的禅院。"
D.Strings[52634]="我有一次看见风裘大师被十来个魔古族围攻，结果那些魔古族连一下都没能打中他。"
D.Strings[52635]="我听说摔跤手从不摘下面具。我很好奇，要是他的鼻子发痒，该怎么解决呢。"
D.Strings[52636]="哇哦！你肯定想不到你刚刚为我赢了多少钱。谢谢你，勇士！"
D.Strings[52637]="啊，勇士！你每次比赛都要来啊。那我就要发财了。"
D.Strings[52638]="真是几场漂亮的对决！"
D.Strings[52639]="悲剧啊……"
D.Strings[52640]="我以前还从未见到过如此精彩的打斗！你可真了不起。"
D.Strings[52641]="你去寺院习得的这身功夫真是让你不虚此行！"
D.Strings[52642]="那个摔跤手干掉了我的老徒弟，现在你就是我的新徒弟了。你闻着臭臭的……还有汗腥味，这些都代表了好运气！$b$b摔跤手动作迟缓，但孔武有力，别让他抓到你。$b$b还有，他没什么脑子，利用场内的椅子砸晕他。$b$b你要是不行了，就用我旁边的水桶爽一下。$b$b祝你好运，土地精的徒弟！"
D.Strings[52643]="噢，不用为他担心。$B$B我那个白痴丈夫只是脑袋上挨了一下，睡一觉就好了。"
D.Strings[52644]="继续持剑作战，阿梅。他们人太多了——万一你死了，我的儿子怎么办？"
D.Strings[52645]="不！不不不不不！摔跤手，站起来！站起来蠢蛋！"
D.Strings[52646]="我的治疗呢？！你这下巴长毛的爬虫小渣滓！"
D.Strings[52647]="啊——！它在打我！坦住它！坦住它！"
D.Strings[52648]="真希望马上能有一堆温暖的营火和一些热饭热菜。有好消息吗？"
D.Strings[52649]="我接到命令让你回到前线。"
D.Strings[52650]="有朋自远方来，不亦乐乎。是来送给养的吗？"
D.Strings[52651]="我们已坚守此岗位数日之久，不眠不休。你不知道我有多么想躺下来休息一下。"
D.Strings[52652]="它们的数量如此庞大，真是前所未见……"
D.Strings[52653]="无论如何，陌生人，你千万不要向我的丈夫打听他的鸡蛋面秘方。否则那将会成为你经历过的最冗长的一次谈话。"
D.Strings[52654]="你获得了烈性绿石佳酿！在战斗中使用它可以帮助你打败多个敌人。"
D.Strings[52655]="[PH]仇灰的愤怒已经消退！他已日渐冷静。"
D.Strings[52656]="[PH]嗨，各位。对此我真的感到非常抱歉。朋友……？"
D.Strings[52657]="我看见你了，猴子！"
D.Strings[52658]="这么说，联盟终于下决心派援兵来了，嗯？快到前线上去，$c！"
D.Strings[52659]="我就知道他们会派援军来的！我对此深信不疑！"
D.Strings[52660]="他们正越过我们的工事！把他们打回去！"
D.Strings[52661]="伙计们，是生是死就看这一战了！不要盲目射击，直到你们能看清他们眼中的疯狂时，再狠狠宣泄你们的子弹吧！"
D.Strings[52662]="你在那儿发什么愣呢，$r？我们需要所有人都上前线！"
D.Strings[52663]="他们也该从总部派几个英雄过来了。出来战斗吧，$c！"
D.Strings[52664]="让那些长尾巴的混蛋看看联盟的力量吧！冲锋！"
D.Strings[52665]="他们人太多了，$c！快帮我们挡住他们！"
D.Strings[52666]="$R，这边！把他们赶回来！"
D.Strings[52667]="嚯，他们从暴风城派援军来了吗？$C都上战场了！"
D.Strings[52668]="非常感谢……我已经坚持不了多久了。"
D.Strings[52669]="啊，你回来了！太感谢你了。拜托，请你一定要收下这个。这是我们这儿最烈的酒：烈性绿石佳酿。"
D.Strings[52670]="格尔桑氏族会向王上和其他像你们这样利欲熏心的骗子证明，我们才是王上真正的拥护者！"
D.Strings[52671]="克尔格西氏族会让你知道，为什么只有强者才配站在我们国王的身边！"
D.Strings[52672]="哈飒克氏族会向所有人证明，我们才是血统最纯正的魔古！"
D.Strings[52673]="呀——哈，我们击退了他们！这就对了，猴子们，夹着你们的小尾巴逃跑吧！"
D.Strings[52674]="看来他们抵挡不住联盟的利剑了。干得好，$n。"
D.Strings[52675]="我的人民被腐蚀了……\n\n我们当地的战士刹嗳呼是第一个饮用污染水的人。\n\n他变得更强壮，尝到了甜头，并鼓励其他人也这么做。\n\n我警告过他们不要听他的。我感觉到了危险，是腐蚀术……"
D.Strings[52676]="天啊……我的蹄子好大……"
D.Strings[52677]="这些土地精护身符开始起作用了……"
D.Strings[52678]="这些土地精酿的酒真奇怪。"
D.Strings[52679]="这感觉……就好像我能闻到土地精的臭味……"
D.Strings[52680]="我觉得我变得更加幸运了……"
D.Strings[52681]="我们绝不交出决定我们族人命运的权利！"
D.Strings[52682]="我们氏族才是真正的氏族！任何闯入者都无法改变这一点！"
D.Strings[52683]="这不可能！我们是全帝国最强大的！"
D.Strings[52684]="滚开，我们队能自己解决。"
D.Strings[52685]="要是坦齐斯能够照看好他的治疗者，我们也不至于搞的一塌糊涂。"
D.Strings[52686]="我在笼子的角落里发现一个土地精烤饼，太好吃了！真是最棒的一天！"
D.Strings[52687]="待在屋里，韩妮！冒险者，请你看看这位温柔的大妈有什么要帮忙的。她正不知疲倦地照料着屋里的幸存者。"
D.Strings[52688]="危险？哈！我才不怕什么危险！$B$B难道你不知道最美味的食物也是最难获得的吗？"
D.Strings[52689]="我知道，他们完全有反抗魔古族的力量——只是需要一个像你这样英雄为他们做出榜样。"
D.Strings[52690]="我不知道你是从哪儿来的，但只要你继续能如今天这般主持正义，那潘达利亚欢迎你的到来。$B$B谢谢你。"
D.Strings[52691]="再快些，史密斯！刹嗳呼渴望鲜血！"
D.Strings[52692]="你到底要到什么时候才能完成呀，铁匠？你是不是还想要额外的鼓励？"
D.Strings[52693]="如果你不快点干完，太蛇就要把我杀掉了，史密斯！到时候我先把你杀掉。"
D.Strings[52694]="安静，牧师！你根本不了解我的工作！"
D.Strings[52695]="你无礼的话吓不倒我，蠢货。"
D.Strings[52696]="你需要什么？我这里有最烈的老酒。你敢试试吗？"
D.Strings[52697]="我想要重置我的职业专精。"
D.Strings[52698]="我想要移除我的雕文。"
D.Strings[52699]="绿石村有救了！谢谢你！"
D.Strings[52700]="我还以为我死定了呢。太感谢你了！"
D.Strings[52701]="我要誓死保卫这个地方，你这怪物！"
D.Strings[52702]="我曾在不息山上捡到过一根大绿鸟的羽毛。在不息山上可没有绿鸟啊。这真是个幸运符。"
D.Strings[52703]="来人啊！救命啊！"
D.Strings[52704]="发现一枚铜币，把它拾起来，一整天我都会交好运。"
D.Strings[52705]="今晚留在这儿，选购我的商品，好运定会伴你左右。"
D.Strings[52706]="你在治疗方面很有一手啊，$c。"
D.Strings[52707]="你的治疗技术真是太棒了，$n。"
D.Strings[52708]="你是从哪儿学来的？你一定练习过很多次吧。"
D.Strings[52709]="干得好，$c！你掌握得很快。"
D.Strings[52710]="这门技艺你学得不错啊，$c。"
D.Strings[52711]="滚开，你们这些恶魔！救命啊！"
D.Strings[52712]="它们占领了村子！救命啊！"
D.Strings[52713]="你们还有人，一起上吧？！光靠这三个可赢不了我！"
D.Strings[52714]="你们要学会服从！"
D.Strings[52715]="鞠躬！"
D.Strings[52716]="弱者在这个世上没有立足之地！"
D.Strings[52717]="我要让你学会敬畏！"
D.Strings[52718]="你这无礼的小$r！"
D.Strings[52719]="你胆敢反抗魔古族？那么你就死定了！"
D.Strings[52720]="我们的帝国壮丽辉煌！而你们都将看不到那一天！"
D.Strings[52721]="我绝不容忍这种违逆！"
D.Strings[52722]="我从来没有举行过这样的仪式。我根本就不知道接下来会发生什么。"
D.Strings[52723]="这是从古时候传下来的，但我们的人民从来不需要用到这个。"
D.Strings[52724]="让我们看看这个是否足以净化我族人被腐化的灵魂。"
D.Strings[52725]="格玛尔遭到了农夫的嘲讽，受到额外的伤害！"
D.Strings[52726]="那便是我们顾虑已久的虫群。如果他们决意突破前线，那我们只有祈求先祖保佑了。"
D.Strings[52727]="让换我班的人知道有多少螳螂妖试图从主通道悄悄溜进来，这个岗位可马虎不得。"
D.Strings[52728]="比我预期的消息还要好。我需要一张暖床。"
D.Strings[52729]="比给养还要好——休息。我觉得我一时半会还不会离开这里。"
D.Strings[52730]="起作用了！起作……"
D.Strings[52731]="发……发生什么了？为什么她会受到仪式的影响？"
D.Strings[52732]="这下好多了。现在，我们去追那些猴子吧，伙计。"
D.Strings[52733]="白虎寺比武大赛第一条规则：我们从不提白虎寺比武大赛。"
D.Strings[52734]="我以为自己死定了。我欠你一条命。"
D.Strings[52735]="谢谢你救了我。为了联盟！"
D.Strings[52736]="谢谢，朋友。真是枪林弹雨啊，但我知道联盟的蓝色一定会全线告捷！"
D.Strings[52737]="谢谢你，朋友。别担心，只是皮外伤。我现在又生龙活虎了！"
D.Strings[52738]="又见到一张联盟的脸孔，真是太好了！我还以为自己死定了。"
D.Strings[52739]="那……一定就是控制着村民的东西！我现在知道我们必须做什么了。"
D.Strings[52740]="我感觉平静多了。发生什么了？"
D.Strings[52741]="我感到自己的心神被攫住，脑中出现灼热的痛楚，还有愤怒……"
D.Strings[52742]="指出腐蚀之池，我会用法杖净化它们。你要打败出现的怪物！"
D.Strings[52743]="嘿，新丁，拿着这个潜水头盔。你到了那儿以后或许用得着。"
D.Strings[52744]="击败金莲之影以脱身！"
D.Strings[52745]="你要来吗？"
D.Strings[52746]="我要开始仪式了。做好准备！"
D.Strings[52747]="现在，朋友，做好准备，击败出现的一切敌人！"
D.Strings[52748]="希望这个不会比上一个更糟……"
D.Strings[52749]="将军帕瓦拉克在呼唤援军！"
D.Strings[52750]="来吧，金祖恩，我们还要报仇呢。"
D.Strings[52751]="我没什么可教你的，$c。"
D.Strings[52752]="这片土地必须准备好迎接我们的舰队。$b$b无需任何理由！"
D.Strings[52753]="这老家伙……我没法朝他发火。$B$B谢谢你，陌生人。"
D.Strings[52754]="又少了一只躲在封锁线后的害虫。"
D.Strings[52755]="我也很想帮你，游学者，但是你得明白我也是身陷困境！"
D.Strings[52756]="嗨！你跟我那死鬼丈夫真是一样的顽固！"
D.Strings[52757]="看看谁来了！孟太太，我想给你引见个人。"
D.Strings[52758]="上升"
D.Strings[52759]="别太放松了，伙计。$b$b将军说，这些房子只是临时的。"
D.Strings[52760]="请接受先祖的祝福吧。尽管微不足道，但没有法杖我能给你的就只有这些，它将助你渡过墨鳃潭。"
D.Strings[52761]="噢，要想挑战幻影女士可是需要很大勇气的。那么，就让我看看你们有什么本事吧！"
D.Strings[52762]="灰飞烟灭，跟我一起堕落吧！"
D.Strings[52763]="噢，小心点，别把血滴在地毯上了，亲爱的。"
D.Strings[52764]="祝你下次走运！"
D.Strings[52765]="呃……死亡……痛楚？都是假象……"
D.Strings[52766]="来试试你的运气吧！哈哈哈哈哈……"
D.Strings[52767]="责法者说得没错……他们已经疯了！"
D.Strings[52768]="你……你不是他们一伙的吧，是吗？你得帮帮我！"
D.Strings[52769]="没希望了……我们的同胞已经失去了理智！"
D.Strings[52770]="还有希望——苟莱还活着，他在南边。走！"
D.Strings[52771]="晕了吧？"
D.Strings[52772]="你们不是第一批来挑战我的人，苦力们，也不会是最后一批。"
D.Strings[52773]="怎么，又有人想来抢我的王冠了？一群软弱的小爬虫。"
D.Strings[52774]="我认识你。如果我收到的报告情况属实，我的确需要一位像你这样的$g大侠:女侠;帮助。"
D.Strings[52775]="陶矢对你的评价很高。她对你的尊重就很能说明一些问题。"
D.Strings[52776]="我们在追踪恨之煞。我想让你加入我们。"
D.Strings[52777]="我的力量无穷无尽！"
D.Strings[52778]="谢谢你，朋友……我会向南进发！"
D.Strings[52779]="苟莱还活着？我要去找他。谢谢你，朋友！"
D.Strings[52780]="见识见识我的神兵利器吧，爬虫们！"
D.Strings[52781]="你非常勇敢……谢谢你！"
D.Strings[52782]="蠢货，我掌握着元素的力量！"
D.Strings[52783]="我受够这场闹剧了！感受你们的痛苦吧，懦夫！"
D.Strings[52784]="%s的鲜血溅到了你的脸上。"
D.Strings[52785]="我们需要集结影踪派最强大的力量来对付恨之煞。即便这样，也不是所有人都能活下来。"
D.Strings[52786]="我们接近了。我能感受到我心中异样的仇恨在不断燃烧。"
D.Strings[52787]="这幅古老的壁画曾镶满了玉石，但现在已经残破，其中的智慧也失传了。"
D.Strings[52788]="今天，我们都将接受最后的考验，但胜利一定属于我们。"
D.Strings[52789]="随着陌生人突然出现在潘达利亚，我相信历史给我们的教训将会发挥作用。"
D.Strings[52790]="你们这也叫……战斗……？"
D.Strings[52791]="我明白了，游学者。可是由于玉石短缺，神龙之心的项目进度已经严重落后了！"
D.Strings[52792]="谁让外人闯进大厅的？只有哈飒克或克尔格西氏族才会干出这种叛逆的行径！"
D.Strings[52793]="啊，没错。交出你们的灵魂吧，凡人！这里是亡者的殿堂！"
D.Strings[52794]="看看我是怎么碾碎你们的骨头吧！不费吹灰之力！"
D.Strings[52795]="跪下吧，懦夫！"
D.Strings[52796]="耐心点，孟太太。这些迷雾之外的陌生人总能给我带来惊喜。"
D.Strings[52797]="只有格尔桑氏族的狗才会将自己的失败归咎于他人！你们氏族最丧心病狂了，一定是你们干的！"
D.Strings[52798]="你相信这些草包能够搞定工匠区？他们的肚子上都没有几两肉！"
D.Strings[52799]="格尔桑氏族说得对！只有卑贱的哈飒克氏族才会让下等种族帮忙做事。你们一定是叛徒！"
D.Strings[52800]="|TInterface\\Icons\\spell_arcane_blast.blp:20|t %s开始施放|cFFFF0000|Hspell:117914|h[横扫千军]|h|r！"
D.Strings[52801]="闭嘴，你们这些没娘养的穆山兽放牧人！我本以为是你们氏族的错，可你们比三岁小孩都笨，更别说篡权了。"
D.Strings[52802]="这是精心策划的政变，但我们也不傻。显然你们这些氏族相互勾结。为了王上的荣耀，消灭你们！"
D.Strings[52803]="克尔格西氏族不会容许这等侮辱！我们很快就要把你们的头颅献给国王，证明我们的力量！"
D.Strings[52804]="你一定就是那个救了勇敢的卡拉什和我们其他兄弟的$r了！我们真的很感激你。"
D.Strings[52805]="勇敢的卡拉什说会有一个$r经过这里。他说的肯定就是你了。"
D.Strings[52806]="你一定就是那个救了我们兄弟的人，谢谢你。"
D.Strings[52807]="$R，欢迎你的光临。勇敢的卡拉什已经把你的事迹都告诉我们了。"
D.Strings[52808]="$C是吗？感谢你把我们的兄弟带回来。"
D.Strings[52809]="日安，$r。"
D.Strings[52810]="愿流水祝福你，$r。"
D.Strings[52811]="你今天过得如何，$n？"
D.Strings[52812]="这些该死的虫子真是没完没了了？！"
D.Strings[52813]="我们快到壁画那儿了。坚持到底！"
D.Strings[52814]="干得好，到封锁线东边的入口找我。我们要找到防线的漏洞，并把它补上。"
D.Strings[52815]="我准备好了。开始举行仪式。"
D.Strings[52816]="剜肉剔骨……嘶……他们的灵魂将被粉碎！"
D.Strings[52817]="这么快就粉身碎骨了。"
D.Strings[52818]="收割的时候到了。"
D.Strings[52819]="噢，伟大的神灵！赐予我大地的力量！"
D.Strings[52820]="噢，至高的神！借我之手融化他们的血肉吧！"
D.Strings[52821]="噢，上古的贤者！赐予我魔法的智慧吧！"
D.Strings[52822]="先烈的英灵！用你的盾保护我吧！"
D.Strings[52823]="如果他们知道……前路有多么恐怖……"
D.Strings[52824]="哈，很好！我赐予你力量勇者的称号！你的威名将令敌人闻风丧胆。"
D.Strings[52825]="你不能待在这里！这是你逼我的！\n<使用业火莲熏香。>"
D.Strings[52826]="他死了！你成功了！"
D.Strings[52827]="朋友，我要回避难所了。在那和我碰头，我们好感谢你。"
D.Strings[52828]="同胞们，$g他:她;来了！帮墨鳃重获新生的$n！"
D.Strings[52829]="再次感谢你，朋友。我们将把你的名字写入史册，永远铭记。"
D.Strings[52830]="正如你所见，这并不是一头完美的牦牛。去吧，$r。去摸摸它。"
D.Strings[52831]="我要是你的话，我不会那样做……"
D.Strings[52832]="你看吧？差劲的牦牛。继续，$r。试着喂它。"
D.Strings[52833]="我想你并不了解牦牛寺是做什么的。"
D.Strings[52834]="看到了吧！？很爱咬人。还不听使唤。试着让它动两下，$r。"
D.Strings[52835]="试着去理解，土地精。这是伟大玄牛砮皂的寺庙。我们是他的奴仆，也是这座寺庙的守护者。我们从不“更换牦牛”。"
D.Strings[52836]="我知道了。那我至少能让我的牦牛干活吧？它连个人都背不动。"
D.Strings[52837]="表哥蓝马鞍……你太固执了，而且你对$r也太刻薄了。"
D.Strings[52838]="我搞定了，这头牦牛很差劲。除非你搞定或更换这头牦牛，否则我们不会离开这座牦牛寺。"
D.Strings[52839]="好吧，北边的湖附近有许多野牦牛。你可以从中挑一头来“更换”你的牦牛。"
D.Strings[52840]="表哥石头包，看见了吧？功夫不负有心人。"
D.Strings[52841]="但是……我们本可以在昆莱找到野牦牛的……"
D.Strings[52842]="治疗我的人……在……哪儿？！"
D.Strings[52843]="希利斯……你失败了！"
D.Strings[52844]="啊！我的技能在冷却！"
D.Strings[52845]="希利斯，快治疗我，你这该死的蜥蜴！"
D.Strings[52846]="开始治疗你这肮脏的蛇头怪了！"
D.Strings[52847]="希利斯，快治疗我，你这魔古酒鬼！"
D.Strings[52848]="希利斯，继续治疗，你这兽唇怪物！"
D.Strings[52849]="坦齐斯！救命啊！"
D.Strings[52850]="啊！满脸$c！"
D.Strings[52851]="救命啊！在我脸上！"
D.Strings[52852]="坦齐斯……粘糊糊……"
D.Strings[52853]="坦齐斯……找个盾来！"
D.Strings[52854]="法力值用完了……"
D.Strings[52855]="好了，$n。我准备好出发了。"
D.Strings[52856]="是的！我们的朋友把我带回来的！"
D.Strings[52857]="儿子！你还好吗？"
D.Strings[52858]="|TInterface\\Icons\\spell_shadow_shadowfury:20|t黑暗萨满柯兰萨召唤出了|r|cFF9E09DE|Hspell:119971|h[暗影风暴]|h|r！"
D.Strings[52859]="你的好运用完了！"
D.Strings[52860]="究竟是多少年的厄运，把你变成了这副模样？！"
D.Strings[52861]="他们抓走了我的儿子……抢走了我的货物，我失去了一切。究竟是什么把这些锦鱼人变成了这样？"
D.Strings[52862]="我的儿子……虽然我找回了货物，可我的儿子会有什么下场？"
D.Strings[52863]="好运是多么眷顾我啊？我的儿子，我的生意，全都回来了……\n\n真没想到，我有一天会为这些东西而心满意足。我真是太幸运了！"
D.Strings[52864]="太有趣了，我想我爸爸现在比较高兴，因为我带回比他更多的东西！$b$b看上去，艰难的时刻提醒他要崇尚简洁。"
D.Strings[52865]="希望你已经让他们吃足苦头了，$n。"
D.Strings[52866]="我真不敢相信自己从前是怎么想的。\n\n一想到自己差点也被控制这些锦鱼人的力量操纵，这感觉……说后怕都是轻的。"
D.Strings[52867]="我们成功登顶了！"
D.Strings[52868]="你做好接受试炼的准备了吗？"
D.Strings[52869]="开启基础伤害（青铜）试炼"
D.Strings[52870]="托亚在到处找你，他正在到处搜集我们手头的玉石。"
D.Strings[52871]="我们会留意你们的行动。"
D.Strings[52872]="艺术家嘛，废寝忘食是常有的事。"
D.Strings[52873]="你怎么想，$n？我们该相信这些土著吗？"
D.Strings[52874]="珠鳍部族不信任我们，我们必须向他们表明我们没有恶意。"
D.Strings[52875]="结交这些人或许是个明智的主意。"
D.Strings[52876]="感谢将你送来我店里的水流，疲劳的旅者。请在旅店内的舒缓之雾中消除你的疲劳吧。"
D.Strings[52877]="感谢你的热情好客。"
D.Strings[52878]="好吧，你已用尽了所有的外交手段。现在，我们只能靠自己的实际行动来向珠鳍部族证明我们的诚意了。"
D.Strings[52879]="你在崎岖的山路中都幸存了下来，没想到却死在了这里！"
D.Strings[52880]="作为水语者，我举行过许多仪式。可其中一种仪式，我却从来没有举行过——那就是净化精神腐蚀的仪式。\n\n这是一种古老的仪式，自从少昊行走在潘达利亚的传说时代结束后，就再也没有使用过。\n\n恐怕我们现在要用到它了……"
D.Strings[52881]="加油打啊，胆小鬼们！"
D.Strings[52882]="感受你的怒火吧！将它融入你的攻击吧！"
D.Strings[52883]="真是绵软无力。拿出点血性来！"
D.Strings[52884]="真是太弱了！"
D.Strings[52885]="虽然我很愿意净化所有被腐化的同胞，但我也不能让那些未被腐化的族人变成一盘散沙。\n\n我们必须阻止邪恶之力的蔓延，然后我将领导那些纯洁如初的族人走向自由。"
D.Strings[52886]="重置事件。[PH]"
D.Strings[52887]="他们为什么不肯听？"
D.Strings[52888]="我该如何拯救他们？"
D.Strings[52889]="我从没见过这样的东西。"
D.Strings[52890]="呜哇——！"
D.Strings[52891]="你不是我们的人！"
D.Strings[52892]="无法……控制……怒火！"
D.Strings[52893]="我·是·不败的！"
D.Strings[52894]="我是一个凶猛的掠食者！"
D.Strings[52895]="%s示威性的嗥叫起来。"
D.Strings[52896]="你好。我是管理者彭启。我们以前见过面吗？我的记性不太好。"
D.Strings[52897]="|cFFFE9A2E腐蚀血球|r开始从树上渗出来了！"
D.Strings[52898]="|TInterface\\Icons\\spell_nature_wrathv2.blp:20|t%s开始施放|cFFFF0000|Hspell:120001|h[引爆]|h|r！"
D.Strings[52899]="不！！！我在玩！"
D.Strings[52900]="嘿！把我放回去！我要去给一场比赛当裁判！"
D.Strings[52901]="不公平！我想看打斗！"
D.Strings[52902]="噢！但摔跤手很快就要上场了。"
D.Strings[52903]="不！！！在进入大赛前我要小试身手。"
D.Strings[52904]="你难道不知道我是做什么的？我是一个凶猛的掠食者！我要剁了你！"
D.Strings[52905]="嘶！！！"
D.Strings[52906]="是的我能！"
D.Strings[52907]="对准！"
D.Strings[52908]="来啊，软脚先生！用力出拳啊！"
D.Strings[52909]="来点儿酷的！"
D.Strings[52910]="噢，得了吧。那是什么？那是一记重拳吗？看起来一点也不像。倒像是在哭着求人救命呢。"
D.Strings[52911]="我是彭启。我打扫地面，还照看小猫。他们说我曾经是位勇士。那一定很棒吧。"
D.Strings[52912]="我……我觉得我是在找寻什么东西。但又记不起来在找什么。"
D.Strings[52913]="我喜欢清扫小径上的落叶。过多的落叶会引来林精。寺庙武僧不喜欢林精。"
D.Strings[52914]="他走投无路了！"
D.Strings[52915]="我们抓住他了！"
D.Strings[52916]="至少我们知道安度因还活着。干得好，$n。现在，去找长老卢山吧。他已经问起你好几次了。"
D.Strings[52917]="再见了，拉瑟斯！我们不会想念你的！"
D.Strings[52918]="你们来这里干什么？你们有什么目的？"
D.Strings[52919]="你们嘴上说是为和平而来，但实际上却是武装到了牙齿。$B$B这你们该作何解释？"
D.Strings[52920]="部族的安全才是我首要考虑的，你会怪我过于谨慎吗？"
D.Strings[52921]="我该如何更改我的主要专精？"
D.Strings[52922]="我该如何重置我的雕文？"
D.Strings[52923]="你们来此有何贵干，陌生人？"
D.Strings[52924]="$R，别想在这里搞事。我们盯着你呢。"
D.Strings[52925]="你来这里干什么，外乡人？"
D.Strings[52926]="我们不是不友善，陌生人。我们只是很谨慎。"
D.Strings[52927]="信任是要争取的，陌生人。"
D.Strings[52928]="我们为什么要相信你，陌生人？"
D.Strings[52929]="嚯嚯！真快呀！我喜欢你，$c。有你在就很好玩儿。"
D.Strings[52930]="雪百合！我们从采石场回来啦！我特别为你带回一车玉石哦，我的小甜心。"
D.Strings[52931]="亲爱的！！我是说……时间快到了。"
D.Strings[52932]="别叫我“雪百合”笨蛋！我……我们都快担心死你啦！"
D.Strings[52933]="抱歉让你久等了，甜心。我知道你有多担心。事实上，是这个陌生人救了我这把老骨头。真不可思议。"
D.Strings[52934]="%s偷偷对你眨了眨眼。"
D.Strings[52935]="还有这车玉石并不是给我的，豪！尊敬的游学者一直在等——噢……"
D.Strings[52936]="%s退回了恐惧之境！"
D.Strings[52937]="魔古族就应该脚踏实地。"
D.Strings[52938]="一旦开始，你便无法阻止！"
D.Strings[52939]="这些守卫者只是个开始！"
D.Strings[52940]="雷电之王的大军将为我们夺回这片土地！"
D.Strings[52941]="雷电之王会回来的！"
D.Strings[52942]="你能感觉到吗？雷电之王离我们越来越近了……"
D.Strings[52943]="谢谢你，$n。我已经训练得很充分了。"
D.Strings[52944]="谢谢你的帮助，$n。我的匕首将刺穿许多敌人的心脏。"
D.Strings[52945]="有了这把剑和这面盾，我会守护好我的朋友及家人。"
D.Strings[52946]="我现在已经了解水的奥秘了，我将利用这些天赋来帮助村子。"
D.Strings[52947]="你好啊，$n！在我上战场和兄弟并肩作战之前，我必须先练好我的治疗术。"
D.Strings[52948]="我的刀很锋利，但我的技巧太笨拙了。我准备好向你学习了，$n。"
D.Strings[52949]="让我用盾牌来保护你吧，$n。请让我保护你，这样我才能更好地保护我的村子！"
D.Strings[52950]="教教我，$n！我要借用水的力量来消灭我们的敌人！"
D.Strings[52951]="想来点吃的吗？我自己做的！"
D.Strings[52952]="服从我，畜生！"
D.Strings[52953]="跟着！否则我立马就把你煮了吃掉。"
D.Strings[52954]="我的是个傻瓜。"
D.Strings[52955]="为什么它会公然反抗我？！"
D.Strings[52956]="投降吧！"
D.Strings[52957]="现在……坐下！"
D.Strings[52958]="好孩子！"
D.Strings[52959]="以部落的名义，你死定了！"
D.Strings[52960]="联盟坏蛋！我们现在是部落的一员啦！"
D.Strings[52961]="可恶的联盟！"
D.Strings[52962]="准备迎战。"
D.Strings[52963]="我们上吧，$n。"
D.Strings[52964]="别错过良机，$r。"
D.Strings[52965]="带我们冲啊，$c。"
D.Strings[52966]="不不不！这片土地是我的，都是我的！"
D.Strings[52967]="我讨厌光板儿！叫人恶心的光板儿！"
D.Strings[52968]="愚蠢的、愚蠢的、愚蠢的大坏蛋！"
D.Strings[52969]="我们必须立刻阻止黑暗萨满！"
D.Strings[52970]="是加尔鲁什派你来的吗？"
D.Strings[52971]="我只是一块石头。这里没什么好看的。"
D.Strings[52972]="出来吧，现在安全了。"
D.Strings[52973]="|TInterface\\Icons\\sha_ability_rogue_envelopingshadows.blp:20|t%s正在释放|cFFFF0000|Hspell:120215|h[死亡之力]|h|r！快跑！"
D.Strings[52974]="没错，嘶！杀了他们！杀光他们！"
D.Strings[52975]="我们的首要任务是保护白卒——安度因·乌瑞恩王子安全撤离。"
D.Strings[52976]="我的疑虑和你一样。我们得做好心理准备。"
D.Strings[52977]="够了！我要亲手解决你！"
D.Strings[52978]="返回青玉巫婆藏身处。"
D.Strings[52979]="返回神龙之心。"
D.Strings[52980]="返回狐狸森林。"
D.Strings[52981]="返回翠竹旷野和珠鳍村。"
D.Strings[52982]="返回观景台。"
D.Strings[52983]="只是一个普通的箱子。肯定没有人藏在里面。"
D.Strings[52984]="科拜带领野牛人袭击了我们……但我并不认为他是问题的根源。"
D.Strings[52985]="现在，我们触动进攻者周围的陷阱机关……"
D.Strings[52986]="禅院……我有点担心，他们怎么一点消息都没有……"
D.Strings[52987]="我们必须在他们真正威胁到奥格瑞玛之前阻止黑暗萨满。"
D.Strings[52988]="我手下最好的斥候还没有回来。"
D.Strings[52989]="我还以为自己要死在这下面了呢！"
D.Strings[52990]="我还以为没人会来救我们了。"
D.Strings[52991]="我欠你一杯酒！"
D.Strings[52992]="慢点儿。"
D.Strings[52993]="跑啊！！"
D.Strings[52994]="你们的母亲老得经历过第一帝国的建立！"
D.Strings[52995]="你们的父亲软弱无能，甚至要依靠熊猫人施舍的嗟来之食活命！"
D.Strings[52996]="你们的氏族下等至极，连猢狲都敢嘲笑你们！"
D.Strings[52997]="喂！$c！我在楼梯这边！别盯着我看！过来就是了。"
D.Strings[52998]="蠢货！竟敢正面挑战强大的螳螂妖？你会死得很快的。"
D.Strings[52999]="虫群，攻击！把他们统统撕碎！"
D.Strings[53000]="煞魔畸体正在喷吐精纯死气！快离开他身边！"
D.Strings[53001]="对平台进行地毯式轰炸！派遣琥珀之翼！"
D.Strings[53002]="后退！你们这是在往死路上撞啊！我得想想……"
D.Strings[53003]="快点！我们必须再快点！他们不可能把我们全挡住！"
D.Strings[53004]="冲进去，狂战士们！把他们统统都消灭！"
D.Strings[53005]="你们的防御毫无意义！我要把你们的脑袋砍下来当成战利品！"
D.Strings[53006]="让黑暗萨满的力量压倒你吧！"
D.Strings[53007]="我的死亡……毫无……意义……"
D.Strings[53008]="你确定要加入联盟吗？"
D.Strings[53009]="我渴死啦！再来点儿！"
D.Strings[53010]="苦难降临！"
D.Strings[53011]="我可没时间闲聊，$n。"
D.Strings[53012]="你最好别拿琐事来烦我。"
D.Strings[53013]="我很担心其他人，$n。"
D.Strings[53014]="部落到底想在这里干什么？"
D.Strings[53015]="赞达拉部族伏击了那些可怜的村民。他们手无寸铁，根本无法保护自己！你必须帮帮他们。阿信会确保你能够安全抵达那个村子。"
D.Strings[53016]="你觉得王上会选谁？"
D.Strings[53017]="我们的氏族是这片土地上最了不起的氏族，他肯定会选我们！"
D.Strings[53018]="我敢打赌，其他氏族甚至连魔法都不会用了。他们根本不可能为王上带来任何好处！"
D.Strings[53019]="我听说王上打算强迫我们彼此厮杀。不可能，这样的话代价太大了。"
D.Strings[53020]="所有氏族都聚集在这里。我敢打赌，一场厮杀在所难免。"
D.Strings[53021]="那个蜥蜴人在偷我们的战利品，抓住他！"
D.Strings[53022]="抓住那个蜥蜴人！"
D.Strings[53023]="%s潜入了恐惧之境的水下！"
D.Strings[53024]="%s从恐惧之境的水下冒了出来！"
D.Strings[53025]="我都开始怀疑，自己究竟要在这里待多久。"
D.Strings[53026]="朋友，你真是帮了我们大忙了。"
D.Strings[53027]="我这把可怜的老骨头都要在这里僵住了。"
D.Strings[53028]="托你的福，等那些野蛮人回来时，我的体力应该已经恢复过来了。"
D.Strings[53029]="那些赞达拉巨魔会后悔进犯卓金村的！"
D.Strings[53030]="真……疼啊……"
D.Strings[53031]="非常感谢你，朋友。"
D.Strings[53032]="你是我的英雄！"
D.Strings[53033]="有时，我们能在旅途中意外地看清自己。"
D.Strings[53034]="在村民的帮助下，我们一定能找到那些赞达拉巨魔。"
D.Strings[53035]="希望我们会再次相见，$n。在那之前，祝你的旅途平安且充满意义。"
D.Strings[53036]="我找到它了！它是我的了！"
D.Strings[53037]="你为什么想抢走我的剑？这是我的剑！"
D.Strings[53038]="离我的剑远点！不准把它拿走！"
D.Strings[53039]="如果一个傻瓜把剑弄丢了，那这把剑就不再属于这个傻瓜了！"
D.Strings[53040]="卑鄙的抢剑贼。滚开！"
D.Strings[53041]="住手，卑鄙的家伙！小心我去抢你的剑！"
D.Strings[53042]="谁拿到就是谁的！别傻了。"
D.Strings[53043]="带我去青龙寺。"
D.Strings[53044]="我需要火焰，师父。"
D.Strings[53045]="热腾腾的面条哦，来一碗香气扑鼻的汤面吧！"
D.Strings[53046]="小笼包，美味多汁的猪肉小笼包！快来吃啊！"
D.Strings[53047]="热气腾腾的汤面，快来吃一碗热乎乎的汤面啊！"
D.Strings[53048]="新鲜可口、健康美味！快来尝尝陶记的汤面吧！"
D.Strings[53049]="不到长城非好汉，不喝靓汤真遗憾！鲜香美味的酸辣汤啊！"
D.Strings[53050]="臭豆腐，快来尝尝臭豆腐啊！我们这儿有全潘达利亚最臭的臭豆腐！"
D.Strings[53051]="呵呵，$c，欢迎来到青龙寺！请不要拘束。"
D.Strings[53052]="你看上去很疲倦，旅行者。过来跟我们一起烤烤火，好好喝上一杯吧。"
D.Strings[53053]="欢迎，$r。随便转转吧。"
D.Strings[53054]="欢迎来到我的旅店，旅行者。我们这儿有好酒好菜，还有松软的床。"
D.Strings[53055]="瞧啊，是什么风把你给吹来了！快进来好好休息一下吧，$c。"
D.Strings[53056]="面对我，发挥出你全部的潜力吧。"
D.Strings[53057]="这里不欢迎你。"
D.Strings[53058]="这里是神圣的地方，不欢迎陌生人。"
D.Strings[53059]="你到底是什么“玩意”？"
D.Strings[53060]="你身上有山下人的气味，你应该回到他们那里去。这些山里没有你们旅行者想要找的平静。"
D.Strings[53061]="你在这里不会得到安宁。"
D.Strings[53062]="你就像大战在即之前盘旋的腐食鸟。"
D.Strings[53063]="我们奉行服务至上的理念。我可没功夫闲聊，也没时间接受低地人的挑战。"
D.Strings[53064]="你看上去似乎身经百战。告诉我，你是为自己而战，还是为别人？"
D.Strings[53065]="我们是长城的守护者，是黑暗的监督者，是暗影的大师。我们深知潜藏在潘达利亚最深处的邪魔。我们……就是影踪派。"
D.Strings[53066]="你去过翡翠林吗？去过四风谷吗？去过昆莱的山脚下吗？$b$b告诉我，那里的人们享受和平的生活吗？他们是否仍然不知道，换取那和平所付出的代价？那是用多少影踪派弟子的鲜血换来的啊！$b$b我想他们还是不知道的好。就让他们浑然不觉地享受和平吧，这样他们才能无忧无虑地过好每一天。"
D.Strings[53067]="愚蠢的蜥蜴人，你们以为能击败强大的野牛人？"
D.Strings[53068]="你们还能有多少人？"
D.Strings[53069]="我听说蜥蜴人的味道像鸡肉，让我们来瞧瞧。"
D.Strings[53070]="你们为什么不远万里来北方？为什么要侵犯我们的土地？"
D.Strings[53071]="我们总共有三个人，其实只靠我自己就能吞下你的脑袋。"
D.Strings[53072]="你抓住我们的时候，我们正前往白虎寺。算你走运，我们的治疗者在打盹……很显然。"
D.Strings[53073]="噢，我有东西给你“尝尝”！靠近点……"
D.Strings[53074]="遇到我你就死到临头了！"
D.Strings[53075]="挑战！"
D.Strings[53076]="煞会把你们全占据了。"
D.Strings[53077]="善终吧！"
D.Strings[53078]="在我面前颤抖吧！"
D.Strings[53079]="你认为自己能占上风吗？"
D.Strings[53080]="我会用双拳痛扁你的。"
D.Strings[53081]="我那时在睡觉！"
D.Strings[53082]="我可不会像个懦夫一样躺在床上等死。"
D.Strings[53083]="我要将你挫骨扬灰。"
D.Strings[53084]="我在外作战的时候你还穿着开裆裤呢。"
D.Strings[53085]="不知天高地厚的小崽子！你以为你能打败我吗？"
D.Strings[53086]="今天就是你的死期。"
D.Strings[53087]="和你一样，我们也是这块地的主人！"
D.Strings[53088]="就算我死，也要死在战场上！"
D.Strings[53089]="净化"
D.Strings[53090]="废物！你们信誓旦旦地表忠心，却连这些低等生物都赶不出我的宫殿。"
D.Strings[53091]="将功补过，肃清这些入侵者。哪个部族能够立下首功，就将得到我的青睐！"
D.Strings[53092]="$n净化了生命之池！"
D.Strings[53093]="熊猫人？你来暴风城干什么？"
D.Strings[53094]="皇帝？你可以去暴风要塞见安度因“国王”。"
D.Strings[53095]="<%s盯着乔乔的柱子看。>"
D.Strings[53096]="进了暴风城可得注意你的言行，熊猫人。你现在站在联盟的领土上。"
D.Strings[53097]="嘿，看！豺狼人！"
D.Strings[53098]="那可不是豺狼人，笨蛋。睁大你的眼睛瞧瞧。"
D.Strings[53099]="那是熊怪。"
D.Strings[53100]="老师……你看！"
D.Strings[53101]="噢，那是熊猫人，莫妮。"
D.Strings[53102]="熊猫人？在这里？在暴风城？"
D.Strings[53103]="呵呵……熊猫人。你一定是来加入联盟的吧。"
D.Strings[53104]="好身手。这招对我特别管用。"
D.Strings[53105]="我们……继续前进吧。"
D.Strings[53106]="欢迎来到暴风城！"
D.Strings[53107]="熊猫人？我肯定是眼花了……"
D.Strings[53108]="闭嘴，纳娜伊。那些外来人过来了。"
D.Strings[53109]="外来人，的确如此——不过他们的动机是好的。"
D.Strings[53110]="仔细看看，卢卡斯。他们身上的圣光很强烈。尤其是那个人。"
D.Strings[53111]="我们继续前进吧。"
D.Strings[53112]="圣光是什么？"
D.Strings[53113]="我们是来加入联盟的。我们要求觐见你们的皇帝。"
D.Strings[53114]="真没想到我能在这里见到你们的族人。"
D.Strings[53115]="这儿有一大群让人讨厌的捣蛋鬼。它们一直骚扰着我们，我们都没法抓住到宝珠。没能把它们抓住千刀万剐。$B$B不过，至少我还没把武器弄丢，不像某些人……"
D.Strings[53116]="我……呃……听着，我已经尽力了，好吗？！这些山精不停地敲打我的手，让宝珠从我手上掉下来，或是趁我不注意的时候把它们偷走。$B$B我恨死这些东西了！"
D.Strings[53117]="嗯，真是个好消息。只要我们加入联盟，就不会没事情做了。"
D.Strings[53118]="你们三个，跟我走走。"
D.Strings[53119]="我知道你们想要加入联盟。"
D.Strings[53120]="我们向来欢迎新盟友。我不是四处树敌的傻瓜，尤其是在战争时期。"
D.Strings[53121]="但是，我希望你们要明白一些事情。"
D.Strings[53122]="明白，请继续。"
D.Strings[53123]="首先：联盟各种族之间必须团结互助。"
D.Strings[53124]="你们应该向有需要的联盟成员伸出援手，无论他们是人类、侏儒、德莱尼……还是你们熊猫人。"
D.Strings[53125]="这条小径便是防线的缺口。螳螂妖正偷偷绕过斥候，向我们的防御工事袭来。$B$B我们要在被包围之前截断他们。"
D.Strings[53126]="这个原则很简单，但意义重大。你们能理解吗？"
D.Strings[53127]="很好。由此我要引申出第二点。"
D.Strings[53128]="并不是所有的熊猫人都选择了和你们一样的道路。"
D.Strings[53129]="其中一些加入了部落。"
D.Strings[53130]="他们，以及依附部落的其他野蛮部族，都是你们的新敌人。"
D.Strings[53131]="也许他们曾经是你们的好友，甚至是爱人，现在都将成为不共戴天的仇敌。"
D.Strings[53132]="我很遗憾，但双方的界线已经划清。我绝不容许有任何的通敌行为，因为这可能将整个联盟置于危险之中。"
D.Strings[53133]="我说得够清楚了吗？"
D.Strings[53134]="好吧…当然。"
D.Strings[53135]="致命一击。"
D.Strings[53136]="它还没准备好面对影踪派。"
D.Strings[53137]="螳螂妖，天堂有路你不走，地狱无门你来投。"
D.Strings[53138]="是什么让他们自以为能够穿越我们的防线……"
D.Strings[53139]="螳螂妖不吃点苦头不会知道我们的厉害。"
D.Strings[53140]="螳螂妖，你的女皇会知道你的死讯。"
D.Strings[53141]="你真不该离开恐惧废土，螳螂妖。"
D.Strings[53142]="关于你们提议的比试……"
D.Strings[53143]="对于潘达利亚的每次不幸和灾难，总有一个完美的解决方案。我觉得这一点适用于所有的问题。"
D.Strings[53144]="现在，熊猫人……让我看看你的本事吧！"
D.Strings[53145]="别这么快退缩！好好打一场！"
D.Strings[53146]="怎么了？你肯定不止这点本事吧。"
D.Strings[53147]="来啊，熊猫人！打我啊！"
D.Strings[53148]="谁能想到这些墙壁后面隐藏着那么多的知识。从这里的大量知识和你在旅途中的所见所闻之中，我相信我可以拼凑出一些有关我们被遗忘的历史的一些传说。$b$b你想要听哪一段？"
D.Strings[53149]="蜥蜴人与困境。"
D.Strings[53150]="我们的故事发生在很久很久之前，荒暴无道的皇帝阗在位的时候。"
D.Strings[53151]="这位皇帝需要一些可靠的信使和转运人。"
D.Strings[53152]="他找来了一个古怪的洞穴小生物，并用锦绣谷的力量改造了它。"
D.Strings[53153]="他所创造出来的，就是“土地精”。"
D.Strings[53154]="|TInterface\\Icons\\inv_misc_blackironbomb.blp:20|t|cFFdd7400希克提克琥珀飞翼|r就位之后开始|cFFFF0000|Hspell:120559|h[轰击]|h|r平台！"
D.Strings[53155]="我想乘风筝出游。"
D.Strings[53156]="我需要乘风筝到长城上去！"
D.Strings[53157]="我听别人说……你需要乘风筝到长城上去？"
D.Strings[53158]="我们来谈谈力量的本质。我的手里握着一把剑。我问你：是谁支配着力量？"
D.Strings[53159]="是我，因为我拿着剑！"
D.Strings[53160]="小事，小事。"
D.Strings[53161]="“陈·风暴烈酒”，我们当不了英雄。我们不能抛弃自己的职责，去恐惧废土晃悠，拯救世界。我们是……“艺术家”。"
D.Strings[53162]="是啊，是啊。着火了。"
D.Strings[53163]="原来是这样——那高老伯呢？"
D.Strings[53164]="没时间吃甜饼了！好吧，来一块。就一块。嗯。"
D.Strings[53165]="等等——这些是幽魂饼干。它们根本填不饱肚子！"
D.Strings[53166]="高老伯，这酿酒厂是由你看着的。你都干了什么？"
D.Strings[53167]="那代价呢？酒厂被毁了！都毁了！"
D.Strings[53168]="噢，你好啊，岑。欢迎你来看望风暴烈酒大婶。"
D.Strings[53169]="噢，岑！你可真像你的父亲。"
D.Strings[53170]="今天外头肯定是个好天气！"
D.Strings[53171]="你注意到艾思木家芜菁的个头了吗？"
D.Strings[53172]="没人管？天哪，才不是呢！高老伯是负责人，其他人都在长城那边呢。很了不起吧？"
D.Strings[53173]="来吃点小甜饼吧。"
D.Strings[53174]="无尽大军碾碎皇帝之敌。"
D.Strings[53175]="皇帝之怒响彻群山。"
D.Strings[53176]="皇帝之力铁血治国。"
D.Strings[53177]="皇帝之勇光照万世。"
D.Strings[53178]="皇帝之息渐灭。"
D.Strings[53179]="皇帝之息重燃。"
D.Strings[53180]="皇帝之志统御万物。"
D.Strings[53181]="每个影踪派门人都要立下三条誓言：\n\n守卫这片土地，保护这里的人民，以及教导下一代。\n\n作为一个影踪派的门人，有生之年都不得违此誓言。"
D.Strings[53182]="啊，那场战斗很惨烈，失去了不少朋友。\n\n尽管如此，我还是很高兴他们帮我建造了战场恢复装置。\n\n要是没有它，没有我烈酒的力量，天知道还会死多少人……"
D.Strings[53183]="一个土地精可以负担相当于其本身体重五倍的重物。他们从不流汗，还有着超凡的嗅觉。"
D.Strings[53184]="他们的脑袋比花岗岩还要坚硬。而最奇怪的是，他们好像统统都是亲戚。"
D.Strings[53185]="古代熊猫人英雄们解放了被奴役的土地精。"
D.Strings[53186]="囚犯逃跑啦！"
D.Strings[53187]="砮皂的部队从后面攻上来啦！"
D.Strings[53188]="碾碎入侵者，把他们从城墙上丢下去！"
D.Strings[53189]="很高兴看到我丈夫把你派了过来，我们可能用得着一名$c。\n\n我只是个斥候，不太会进行面对面的战斗。而老陈……好吧，他确实是一个斗士，但经历过上次战斗后，他仍没有恢复过来。\n\n况且，他也正忙着酿制新配方。"
D.Strings[53190]="好吧，我已经准备好重返前线了。"
D.Strings[53191]="两份油兑一份酒……不，油应该再多点儿……"
D.Strings[53192]="寺院必将陷落！你们休想阻止我的大军！"
D.Strings[53193]="我的大军必将碾碎你们！"
D.Strings[53194]="阻止他们！螳螂妖攻击！"
D.Strings[53195]="侧翼！到侧翼去！"
D.Strings[53196]="缴械投降，不然就死！"
D.Strings[53197]="我让你失望了，女皇陛下……"
D.Strings[53198]="这是女皇的意志！"
D.Strings[53199]="砮皂的部队不堪一击！"
D.Strings[53200]="讲课开始了。"
D.Strings[53201]="你的灵魂无法承受的我的力量。"
D.Strings[53202]="我永生不死！"
D.Strings[53203]="你什么都学不会。"
D.Strings[53204]="也许你应该再温习一遍的。"
D.Strings[53205]="下课找你谈谈。"
D.Strings[53206]="这平台不属于你们！"
D.Strings[53207]="我的力量无人能及！"
D.Strings[53208]="我们……无穷……无尽……"
D.Strings[53209]="风暴即将来临。"
D.Strings[53210]="让你的恐惧吞噬你！"
D.Strings[53211]="我命令元素毁灭你！"
D.Strings[53212]="你休想躲过这场风暴！"
D.Strings[53213]="平台……绝不能……陷落……"
D.Strings[53214]="擅自闯入，胆大妄为！"
D.Strings[53215]="震死你。"
D.Strings[53216]="无尽的洪水将你们逐出这片土地！"
D.Strings[53217]="洪水吞没你！"
D.Strings[53218]="滚滚洪流，势不可挡！"
D.Strings[53219]="湮没在你的恐惧中吧！"
D.Strings[53220]="必须……阻止……煞魔……"
D.Strings[53221]="你没资格站在我面前。"
D.Strings[53222]="逃跑吧，孩子。"
D.Strings[53223]="%s像一朵|cFFFF0000|Hspell:119888|h[死亡之花]|h|r一样旋转！"
D.Strings[53224]="小心脚下。"
D.Strings[53225]="别跳！珍惜生命！"
D.Strings[53226]="注意。"
D.Strings[53227]="别掉下去！"
D.Strings[53228]="请小心。"
D.Strings[53229]="别跳！我肯定会有人爱你，或至少会有人讨厌你……"
D.Strings[53230]="接着又一个……"
D.Strings[53231]="我希望绳子还挺得住。"
D.Strings[53232]="嗯，有人说绳子就是生命……"
D.Strings[53233]="我希望你的绳子没烧起来。"
D.Strings[53234]="你是个比我勇敢的$r。"
D.Strings[53235]="%s在追击你！快跑！"
D.Strings[53236]="谁也不能越过这道城墙。$B$B这是我的城墙。"
D.Strings[53237]="一路平安！"
D.Strings[53238]="几个世纪以来，影踪派一直守卫着这道城墙，但我也不会因为骄傲自大而拒绝外人的帮助。"
D.Strings[53239]="我们至高无上！"
D.Strings[53240]="其他氏族一无是处！"
D.Strings[53241]="您不必把时间花费在其他氏族身上，伟大的王上！"
D.Strings[53242]="我们氏族一直谨遵先祖定下的规矩。与其他氏族相比，我们更应该得到王上的青睐！"
D.Strings[53243]="若非我族之力量，魔古无法重夺那份荣耀！"
D.Strings[53244]="这些可悲的氏族不值一提，陛下。他们玷污了我族伟大的遗产！"
D.Strings[53245]="你们的实力真弱。"
D.Strings[53246]="你的出现惊扰了游荡的灵魂！"
D.Strings[53247]="野牛人督军露脸了！来吧，让我们做个了结！"
D.Strings[53248]="这些桶……有些是我最珍爱的好酒。至少它们曾焕发出荣耀！"
D.Strings[53249]="祝踏岚不会向我们派援军了，我们要在此面对一支庞大的军队。他们或许跟我们影踪派一样强悍，我们得另外想个办法了。"
D.Strings[53250]="蠢货！你无法打败我！你无法打败野牛人！"
D.Strings[53251]="等等——林去哪儿了？"
D.Strings[53252]="……但首先，我要解决掉这些该死的野牛人！看招！"
D.Strings[53253]="我的丈夫在哪？"
D.Strings[53254]="贡达，把这些苍蝇都解决掉，我来把这个——林，是吧？——带回奥苏尔台地。"
D.Strings[53255]="他们派了人来找我？！$B$B谢天谢地……"
D.Strings[53256]="嘿，把那东西拿远点儿！"
D.Strings[53257]="小心！别烧着我……"
D.Strings[53258]="哎哟，别拿那东西指着我！"
D.Strings[53259]="嘿！我可是一个活的、一点就着的熊猫人！"
D.Strings[53260]="他们太强大了！"
D.Strings[53261]="多谢你赶来救援，可是我们仍然被螳螂妖大军包围着。"
D.Strings[53262]="跟我来。我们得谈谈。"
D.Strings[53263]="你们加入我的部落是一个明智的选择。"
D.Strings[53264]="有人称呼我们是野蛮人…是艾泽拉斯的“劣等种族”。"
D.Strings[53265]="他们愚昧无知，对事实视而不见。看看周围吧，熊猫人。"
D.Strings[53266]="你会发现，兽人是最好的战友。"
D.Strings[53267]="牛头人都多才多艺。看——这位就是一名萨满。"
D.Strings[53268]="看看外面。敌人太多了，我们对付不过来。"
D.Strings[53269]="连血精灵都能挥剑战斗。"
D.Strings[53270]="看见吗？在我的部落里，每个人都有用武之地。你和你的朋友们也不例外。"
D.Strings[53271]="你们明白我的话吗，熊猫人？"
D.Strings[53272]="当然，酋长。"
D.Strings[53273]="唔。很好。"
D.Strings[53274]="我们继续。我知道，从那岛上逃出来的熊猫人不止你们几个。"
D.Strings[53275]="你们的一些族人选择加入了联盟。"
D.Strings[53276]="现在，他们就是你们的敌人。"
D.Strings[53277]="你们的一些朋友和亲人可能也已经选择与部落的敌人为伍。从此他们将不再是朋友……不再是家人。"
D.Strings[53278]="当他们穿上联盟战袍，他们已经死了。我绝不允许任何部落成员私通外敌。部落的叛徒必将以罪人的身份受死！"
D.Strings[53279]="是的……我想是的。"
D.Strings[53280]="很好。"
D.Strings[53281]="到荣誉谷来见我。我有一份……礼物送给你。"
D.Strings[53282]="欢迎来到勇气竞技场，熊猫人。我先去准备，你们随意参观。"
D.Strings[53283]="哈！看来我们已经准备好了。现在，新来的……准备战斗吧！"
D.Strings[53284]="这是我的礼物：一份馈赠，一场试炼。"
D.Strings[53285]="我听说过传奇的熊猫人英雄以及他们高超的武艺。现在我就想见识见识。"
D.Strings[53286]="机会难得啊，熊猫人。向部落的酋长证明你的实力吧！"
D.Strings[53287]="Lok'tar ogar！不胜利，毋宁死！"
D.Strings[53288]="打的好。要不是你帮忙，恐怕我很难在这场战斗中活下来。"
D.Strings[53289]="Throm-ka，熊猫人。欢迎加入部落。"
D.Strings[53290]="你全身覆盖着野牛人焦油，而且什么也看不见！"
D.Strings[53291]="愚蠢的入侵者！"
D.Strings[53292]="我们会让你死个痛快！"
D.Strings[53293]="你们的血肉献给邪鳞领主！"
D.Strings[53294]="开膛破肚！"
D.Strings[53295]="我的刀渴望鲜血！"
D.Strings[53296]="新鲜美味的家伙！"
D.Strings[53297]="把它撕开！"
D.Strings[53298]="再见，小家伙。我们后会有期。"
D.Strings[53299]="快去吧。大酋长在等着你们呢。"
D.Strings[53300]="就是他们帮助科尔加·蛮鬃逃出了联盟的魔掌！"
D.Strings[53301]="嗯，真是个好消息。一旦我们加入部落，就不会没事可做了。"
D.Strings[53302]="熊猫人！过来。"
D.Strings[53303]="尊敬的地狱咆哮陛下，我是季…"
D.Strings[53304]="叫我地狱咆哮酋长！"
D.Strings[53305]="好了，起来吧。"
D.Strings[53306]="我们得谈谈，熊猫人。"
D.Strings[53307]="欢迎来到奥格瑞玛！"
D.Strings[53308]="你们是来投效部落的吗？"
D.Strings[53309]="你最好快点穿过这个地区，陌生人。"
D.Strings[53310]="酋长可不喜欢兽人以外的家伙在奥格瑞玛的这一地区闲逛。"
D.Strings[53311]="他……他在城里搞种族隔离？"
D.Strings[53312]="那就继续向前走吧。地狱咆哮之眼注视着你。"
D.Strings[53313]="直到今天，他们依然在高耸入云的昆莱山上扮演着商人、信使、向导和送货人的角色。"
D.Strings[53314]="真酷！"
D.Strings[53315]="他们是非常迷信的种族，经常以他们最喜爱的护身符——或者叫“幸运符”为名。"
D.Strings[53316]="土地精质疑一切他们闻不到的运气，所以带上一口袋粪去见陌生的土地精是个不错的选择。"
D.Strings[53317]="真是个奇怪的种族。"
D.Strings[53318]="嘿，萨兹尔！快看那些走过来的傻瓜。"
D.Strings[53319]="要我说的话，他们的样子很滑稽。"
D.Strings[53320]="是啊……真的很滑稽。"
D.Strings[53321]="我喜欢鱼。"
D.Strings[53322]="那太好了！我也喜欢鱼！"
D.Strings[53323]="林很伤心——智遥是他的好友，但却战死沙场。\n\n我不想林轻率行事。失去了他我该怎么办……"
D.Strings[53324]="智遥牺牲了。诗雅牺牲了。刘牺牲了。\n\n孙娜让我平息心中的怒火，但事关荣誉又岂能息事宁人。\n\n我们孤军防守关隘时，祝踏岚却安坐在禅院里吗？为什么要对我们紧锁大门？为什么不派援兵？\n\n这些问题困扰着我。"
D.Strings[53325]="明明是你在替我干脏活，我为什么要弄脏自己的武器呢？"
D.Strings[53326]="别问那么多无聊的问题，城墙行者。把注意力集中在当前的任务上。"
D.Strings[53327]="我以为他跟你在一起？"
D.Strings[53328]="噢！孙娜……"
D.Strings[53329]="挑战开始！"
D.Strings[53330]="挑战结束！"
D.Strings[53331]="<泰侯沉默不语。>"
D.Strings[53332]="供给官的活儿永远干不完。影踪派正向它的胃部进军。$b$b接着，将进入它的肝脏。"
D.Strings[53333]="你去把他们弄出来。我会躲在暗影中搜寻他们。"
D.Strings[53334]="他独自留在外面了？！我们得去找他！"
D.Strings[53335]="起初，出于对祝踏岚的服从和尊敬，我没有质疑他关闭禅院的决定。\n\n然后，当野牛人首次来袭，我忙于应战无法离开前线去询问他为什么不派援军。\n\n现在，影踪派有三人牺牲，一人被俘，我已经没有耐心了——没有了。我打算去禅院，向祝踏岚讨个说法。"
D.Strings[53336]="我们到了。上来吧，朋友。"
D.Strings[53337]="祝踏岚掌门有令，任何人都不能通过。"
D.Strings[53338]="我和班·熊心一起，想找祝踏岚讨个说法！"
D.Strings[53339]="说法？！你们想讨说法？！"
D.Strings[53340]="我们禅院里见！"
D.Strings[53341]="在附近一棵树那黑暗的根须下，一个古老的恐惧苏醒了……"
D.Strings[53342]="对不起，局外人。除非你是因公事至此，否则，我可帮不了你什么。"
D.Strings[53343]="一股邪风在昆莱肆虐。我担心有一股沉寂多年的力量即将归来，而这些野牛人只是前兆而已。"
D.Strings[53344]="感觉……这里好像有什么不太对劲。不知道是什么，但我希望我们能尽快将其找出来。"
D.Strings[53345]="我不敢相信我们必须消灭掉我们社团的一员……这个世界怎么了？"
D.Strings[53346]="你真的把他们打飞了。我在这都能听见他们的……哞哞地惨叫。\n\n哞哞叫？那就是你对野牛人跌落城墙时所发出惨叫声的形容吗？"
D.Strings[53347]="哇噢！我能听到城墙上爆炸的声音。\n\n我想老陈的想法并不都很糟。"
D.Strings[53348]="为了救林，我会竭尽全力，直到剩下最后一口气。"
D.Strings[53349]="这并不能让我们的兄弟姐妹复生，但知道自己胜过野牛人，会让我们晚上睡得更安稳。"
D.Strings[53350]="看，$n。那头野兽在它的巢穴里醒过来了！"
D.Strings[53351]="又一轮攻击？！\n\n看来除非我们将他们逼退回螳螂高原，这些野牛人是不会善罢甘休的。甚至是逼退到大海里去。"
D.Strings[53352]="你站在一片致命的云雾中！"
D.Strings[53353]="和平与安宁终于来临。这也许足够让我去追思那些逝去的兄弟姐妹们。"
D.Strings[53354]="我不得不说，计划酝酿出来时，我非常开心。"
D.Strings[53355]="经过这一切之后……我们的兄弟姐妹们离我而去，林被野牛人抓走，我的啤酒也不见了，我想是时候继续前进了。\n\n也许我会去找螳螂妖战斗……"
D.Strings[53356]="作为刚刚抵达这片土地的陌生人，你也许还不熟悉影踪派。"
D.Strings[53357]="我们的历史悠久，可以追溯到少昊时代，他是影踪派的创始人，也是潘达利亚的末代皇帝。"
D.Strings[53358]="黑暗能量笼罩着这片土地。愤怒、仇恨、恐惧、猜疑……"
D.Strings[53359]="这些负面情感可以表现为实体形态。我们把这些黑暗能量称为“煞”。"
D.Strings[53360]="监视并禁锢煞魔是我们神圣的责任。不管它在哪里玷污人们的心灵，我们都要打败它。"
D.Strings[53361]="自从你们的士兵登上这片土地，煞魔就骚动起来，其表现之活跃，实为我生平仅见。"
D.Strings[53362]="潘达利亚没有常驻军队。我们影踪派，是这儿最早的——也是唯一的，防御阵线。"
D.Strings[53363]="祝踏岚子承父业，领导着影踪派。可他却选择关闭我们的禅院大门——这是为什么呢？"
D.Strings[53364]="老陈！我们今天干得不错。你哭什么呀？"
D.Strings[53365]="在我们阻截敌人时，他准是去追逃跑的野牛人了。"
D.Strings[53366]="耐心点，孙娜！如果我们贸然进入螳螂高原，那问题就复杂了。我们必须把注意力集中在禅院和援兵上。"
D.Strings[53367]="祝踏岚不知出于何种原因关闭了禅院，这已经危及到我们永恒的使命。"
D.Strings[53368]="潘达利亚分崩离析时，我们绝不可以安坐在山顶堡垒中袖手旁观。那就是为什么你和我必须跟祝踏岚讨个说法。"
D.Strings[53369]="给我指出正确的方向。我来搬。"
D.Strings[53370]="行动起来吧！"
D.Strings[53371]="你来带路。我来搬食物。"
D.Strings[53372]="寺院周围应该有很充足的食物储备。"
D.Strings[53373]="你们以为自己是谁，居然敢找影踪派讨说法？"
D.Strings[53374]="干掉他！把他从长城上踢下去！"
D.Strings[53375]="世界状态变量已重置。"
D.Strings[53376]="是谁，竟敢惊扰这座陵墓？"
D.Strings[53377]="%s马上就要过载了！"
D.Strings[53378]="<这可不仅仅是一块琥珀——里面有一只螳螂妖！>"
D.Strings[53379]="卡拉克西背叛了女皇陛下。你们的尸体会因此被挂在宫殿的墙壁上。"
D.Strings[53380]="但是……是女皇背叛了……我们的族人……"
D.Strings[53381]="你居然敢质疑她的意愿！"
D.Strings[53382]="这是什么？！现在它们跨过城墙，是来找我们麻烦的？这群笨蛋！"
D.Strings[53383]="$C……靠近我……"
D.Strings[53384]="摧毁尸体堆以阻止僵尸化的躯体！"
D.Strings[53385]="玩火者，必自焚。"
D.Strings[53386]="你愿意陪我去吗？"
D.Strings[53387]="加入我吧。"
D.Strings[53388]="要想成为影踪派的一员，$G他:她;就必须全心全意地投入影踪派的事业。"
D.Strings[53389]="影踪派虽然人数稀少，但我们能用强大的力量来弥补这一点。"
D.Strings[53390]="西边，螳螂妖蠢蠢欲动。$B$B西北边，魔古族正在阴谋作乱。$B$B北边，野牛人步步紧逼。$B$B我们有太多事情要做了，时间紧迫。"
D.Strings[53391]="每一个影踪派战士都能叫出彼此的名字。我们一同训练，并肩作战，同生共死。$B$B当你能做到这一点时，或许就做好了加入我们的准备。"
D.Strings[53392]="我随时准备点燃这地方！"
D.Strings[53393]="啊！救命！林精！"
D.Strings[53394]="帮我弄走它们！帮我弄走它们！"
D.Strings[53395]="太蜇人了！哎哟！哎哟！"
D.Strings[53396]="啊！我脸上全是刺！"
D.Strings[53397]="疼死我了！"
D.Strings[53398]="快滚开！"
D.Strings[53399]="我只不过想要回我的牦牛……"
D.Strings[53400]="北边的哨探在哪里？你的人全都龟缩在营地，居然没人放哨侦查。你开始松懈了，高岚。"
D.Strings[53401]="恕我冒犯，祝掌门，我们没有丝毫松懈。我们兵力不足、四面受敌，我的人都已经精疲力竭，再也抽不出一点人手了。"
D.Strings[53402]="不，我们绝不撤军。在螳螂妖繁殖下一代虫群之前，我们还有很多年时间。我可不想把螳螂高原拱手相让。"
D.Strings[53403]="祝掌门，九十多年来，螳螂妖的数量从未如此泛滥。士兵们夜以继日、不眠不休地战斗，死守这道防线。"
D.Strings[53404]="或许我们应该撤退到城墙那里？即便是螳螂妖全数出动，我们也绝对能将它们挡住。"
D.Strings[53405]="我是来找一些强壮的熊猫人猎杀恨之煞的，但是我们会先帮你加固路障。"
D.Strings[53406]="陶矢，去北边看看有没有螳螂妖骚扰我们的侧翼。我去看看防御工事。"
D.Strings[53407]="将士们很荣幸与您并肩作战，祝掌门。"
D.Strings[53408]="高岚，我已经很长时间没有视察前线了。感谢你长期以来的努力。"
D.Strings[53409]="我们需要更多身经百战的影踪派弟子才能挑战它。我们会在沿途的营地停留。"
D.Strings[53410]="<粘稠的、橘黄的液体缓缓地从克尔鲁克的颚骨渗出。>"
D.Strings[53411]="我的头好晕……我还……没有完全恢复。"
D.Strings[53412]="遵命，祝掌门。"
D.Strings[53413]="愿道路指引你的方向，旅行者。$b$b是什么风把你吹来了？"
D.Strings[53414]="我们都已经尽力了。再见，高岚。我会尽快派部队来支援你。"
D.Strings[53415]="非常感谢，祝掌门。祝你好运。"
D.Strings[53416]="是的。恨之煞来过这里。"
D.Strings[53417]="你们感觉到了吗……？"
D.Strings[53418]="他们的营地陷入了混乱，发生了什么事？"
D.Strings[53419]="新兵，我们的军队在哪？"
D.Strings[53420]="祝掌门！他们在桥那边，抵挡一支螳螂妖部队，大人。"
D.Strings[53421]="我会处理接下来的事情，你带着那些箭矢去桥下加入战斗。"
D.Strings[53422]="“幸运符”是什么？"
D.Strings[53423]="幸运符？是指能带来好运和财富的人、地方或物品。$b$b幸运符是土地精给予最高的赞美之词。$b$b通常，幸运符本身拥有独特的气息。土地精灵敏的嗅觉可以通过幸运符的气味找到好运。"
D.Strings[53424]="我想问问其他的。"
D.Strings[53425]="什么是土地精？"
D.Strings[53426]="我们为什么是土地精呢！山中的驳车。小径上的送货人。山间的向导，还有补给品运送员。$b$b我们给城墙上的守护者提供食物，我们也是从魔古帝国开元就在粗麻小径上穿梭的人。$b$b我们也拥有最棒的鼻子，可以嗅出好运的味道！"
D.Strings[53427]="誓死为议会效命。但你不是卡拉克西瓦……"
D.Strings[53428]="送我去天鲨号残骸！"
D.Strings[53429]="%s大声向附近的盟友求救！"
D.Strings[53430]="我想说，被遗忘者……在酒方面的口味非常独特。但是，我感觉他们不是在为朋友准备。"
D.Strings[53431]="如果你对螳螂妖真这么感兴趣，我会在前往卡拉克西维斯的路上继续说给你听。$B$B现在别妨碍我工作。"
D.Strings[53432]="被遗忘者的学习速度很快。我猜你可以教那个老……嗯，那个，曾经生龙活虎的那个老家伙一些新技巧。"
D.Strings[53433]="她在说什么？"
D.Strings[53434]="武僧"
D.Strings[53435]="就在军事区的内环。她醉得很厉害。"
D.Strings[53436]="她可吓人了，总是很刻薄，还说我们很臭。她就在军事区的内环。"
D.Strings[53437]="武僧训练师在军事区的内圈。她正在训练一些亡灵卫兵学习她族人的战斗方法。"
D.Strings[53438]="你可以在军事区的内环区域找到她。"
D.Strings[53439]="几千年前，魔古族掌握着所有的力量，他们残暴地统治着这片土地。但是随着帝国的不断发展壮大，他们需要维持秩序并加以控制。"
D.Strings[53440]="他们利用山谷的力量以及他们独有的血肉塑造魔法，将一种凶猛的蜥蜴改造成了具有生命的武器。他们打造了一支军队，一支蜥蜴人大军。这是一群嗜血的怪兽，他们的作用就是巩固皇权。"
D.Strings[53441]="呃，但是创造一种有生命的武器会出现一个问题，你知道吗？"
D.Strings[53442]="现在是谁在支配着力量？"
D.Strings[53443]="凶残的蜥蜴人虽然头脑并不发达，但还是很快意识到他们的真实处境。它们先残杀魔古的敌人。"
D.Strings[53444]="接着，他们屠戮魔古的臣民。"
D.Strings[53445]="很快，他们便开始残杀魔古。"
D.Strings[53446]="于是魔古皇帝下令铲除蜥蜴人。他想将整个蜥蜴人种族铲除，却无济于事。他们至今仍在潘达利亚肆虐。"
D.Strings[53447]="明白了吧——力量得来容易，却不可轻易给予。"
D.Strings[53448]="哦，艾莎？我想我看到她在湖边训练其他熊猫人，就在暴风要塞的西北方向。"
D.Strings[53449]="这座城市和我的家乡完全不同……\n\n啊，朋友，我能帮你什么忙吗？"
D.Strings[53450]="这片土地上有太多陌生又新奇的东西了。虽然和我的家乡非常不同，可给我留下了深刻的印象。"
D.Strings[53451]="耐心……等他们送上门！"
D.Strings[53452]="打！！！"
D.Strings[53453]="是，祝掌门。"
D.Strings[53454]="战斗是这么打的，$R。"
D.Strings[53455]="你应该去打那个大个子，不是我。"
D.Strings[53456]="快滚回来战斗！"
D.Strings[53457]="算你走运，我们的部族首领没有让我出手。"
D.Strings[53458]="你找错魔古了，$R。"
D.Strings[53459]="噢，千杯不醉刘伶？他大部分时间都在铁炉堡大门北边的石火旅店里跟人拼酒。"
D.Strings[53460]="啊，你是武僧吧？你可以在石火旅店找到你的熊猫人朋友。"
D.Strings[53461]="或许我还不知道该如何战斗，但我知道什么值得我去战斗！"
D.Strings[53462]="我父亲还以为他能对我颐指气使！我不再是个小孩子了，他应该认识到这一点。"
D.Strings[53463]="我和村子的所有人一样，都有为家乡而战的权利。要是我认识一个能训练我的英雄就好了……"
D.Strings[53464]="这些人很对我的胃口。你肯定能感到他们是有前途的！\n\n不管怎么说，要我教你点什么武僧技能呢，朋友？"
D.Strings[53465]="这里的人有着和我相似的世界观。你必须打出自己的一片天地，你明白吗？"
D.Strings[53466]="看来我们的任务是为我们量身定制的……"
D.Strings[53467]="干得好，我们回去和祝掌门会合。这里也没什么事可做了。"
D.Strings[53468]="躲到路障后面去！"
D.Strings[53469]="快到路障后面去！"
D.Strings[53470]="哦，季？他在荣誉谷的熊猫人小亭，正在一边观看比赛一边和战士们交谈。"
D.Strings[53471]="季通常都在熊猫人小亭。那个地方离竞技场很近，他喜欢看别人打架。我听说他偶尔还会参加比赛。"
D.Strings[53472]="让我们开始训练吧！"
D.Strings[53473]="好了！让我们开始干正事吧！"
D.Strings[53474]="%s弹药告罄，直接飞走了！"
D.Strings[53475]="兰风就在神殿花园的湖上冥想。我听说她非常擅长泡茶。"
D.Strings[53476]="多谢你的宝贵时间。我希望你以后能重新考虑训练我。"
D.Strings[53477]="你可以在灵魂高地找到冉瑟。她正在那里与萨满祭司训练师会面。"
D.Strings[53478]="老肖正在远行者广场练武呢。"
D.Strings[53479]="武魂潘劲正在俯瞰贸易阶梯的战士平台上和战士们一起训练呢。"
D.Strings[53480]="对付猢狲海盗的秘诀就在于出其不意。"
D.Strings[53481]="好吧……那么……对付猢狲海盗的新招数就是把你刚才做的再做一遍。"
D.Strings[53482]="等等！你听到了吗？听上去就像细小的翅膀拍动的声音……"
D.Strings[53483]="我们最好抢在全岛的敌人都发现我们之前继续前进."
D.Strings[53484]="猢狲角斗士？它们从哪儿找来的这些武器？"
D.Strings[53485]="好吧！这地方看起来并不妨碍酿酒。"
D.Strings[53486]="你知道比海盗更坏的是什么吗？猢狲海盗！它们袭击了我们的海岸，把鲜鱼、船只和美酒全都偷走了。没有人能偷走我们的酒……没有人。"
D.Strings[53487]="乌克头领正在传播败血症！别让他靠近橘子！"
D.Strings[53488]="准备拉索"
D.Strings[53489]="痛！痛！痛！"
D.Strings[53490]="还有鸟？他们是怎么学会驯鸟的啊？！"
D.Strings[53491]="我要把你劈成两半！"
D.Strings[53492]="我要拿你当晚餐！"
D.Strings[53493]="晚饭准备好了！"
D.Strings[53494]="你的脸色有点苍白！"
D.Strings[53495]="你看起来不太好！"
D.Strings[53496]="乌克饿啦！"
D.Strings[53497]="乌克要吃鱼！吃鱼长力气，杀坏蛋！"
D.Strings[53498]="这个大锅很适合煮我们的……酒。"
D.Strings[53499]="是我的肚子叫叫唤，还是有什么大家伙过来了？"
D.Strings[53500]="准备受死吧，坏蛋！"
D.Strings[53501]="砰！叭叭——碰！"
D.Strings[53502]="$n拿到了橘子！"
D.Strings[53503]="乌克头领获得了完全型败血症！"
D.Strings[53504]="$n扔出了橘子！"
D.Strings[53505]="你们惹火我啦！"
D.Strings[53506]="坏蛋！把橘子给我！"
D.Strings[53507]="不公平！你们这些蠢蛋竟然三打一？！"
D.Strings[53508]="你拿了我的橘子？！你这是当面挑衅！"
D.Strings[53509]="我要橘子！给我！"
D.Strings[53510]="哈！这下好多了！现在你们这些坏蛋要倒霉了！"
D.Strings[53511]="我听说矿坑又遭到了蜘蛛的侵袭。但愿没有人受伤。"
D.Strings[53512]="他们说，从迷雾另一边来的陌生人进入了翡翠林。真是个古怪的时代。"
D.Strings[53513]="我听说，土灵在绿石采掘场闹得很不愉快。但愿他们不会拿我们出气。"
D.Strings[53514]="今天的面条怎么样？"
D.Strings[53515]="我是克尔鲁克，来自久远时代的战士。"
D.Strings[53516]="在我的年代，这是个魔古族据点。我有幸用他们的鲜血涂满了墙壁。"
D.Strings[53517]="我的功绩为我赢得了英杰的美名。我作为英雄被保存在琥珀之中，在帝国需要的时候……苏醒。"
D.Strings[53518]="唤醒者，是什么力量燃烧我们的土地，腐化我们的林木？"
D.Strings[53519]="皇宫！简直……面目全非。我明白为什么卡拉克西要被迫采取行动了。"
D.Strings[53520]="他们是由最睿智的文化领袖组成的议会。负责监督女皇。"
D.Strings[53521]="你们来个人和我一起看管酿酒的大锅。其他人去找一些盎迦丛林酒，然后交给我！"
D.Strings[53522]="一旦女皇堕入腐化或威胁到我们的文明，卡拉克西就一定让她皇位不保。"
D.Strings[53523]="各时代的英杰，包括我，都被凝固在时间长河中，埋藏在女皇无法控制的地方。"
D.Strings[53524]="我们只响应议会的召唤。完成他们的意志再进入沉睡。"
D.Strings[53525]="啊，这就是我跟你说起过的那位$c。"
D.Strings[53526]="你想要开始挑战吗？"
D.Strings[53527]="很好！让我们解决掉这些螳螂妖，然后夺回那座桥。"
D.Strings[53528]="祝掌门，我们很快回来。"
D.Strings[53529]="是的，我要开始挑战。"
D.Strings[53530]="我很乐意。任务完成之后赶紧回来。"
D.Strings[53531]="我们将坚守这里！"
D.Strings[53532]="把这个喝下去。后劲儿有点大。"
D.Strings[53533]="来口这个尝尝！"
D.Strings[53534]="把这个倒回去！"
D.Strings[53535]="把桶踢向他们！"
D.Strings[53536]="加把劲！"
D.Strings[53537]="他中招了，继续！"
D.Strings[53538]="他快不行了！"
D.Strings[53539]="回去找祝踏岚吧。我很快就会追上你的。"
D.Strings[53540]="十字路口离这儿不远。我们去那儿寻找最后一名成员。"
D.Strings[53541]="弟兄们都对这位砮荣赞誉有加。终于能得见本尊了。"
D.Strings[53542]="是鹰眼大师砮荣吗？"
D.Strings[53543]="噢，你身上有这么多好东西可以偷呀！给我！"
D.Strings[53544]="小气鬼……"
D.Strings[53545]="你会和我们一起猎杀恨之煞的，对吧，老陈。你的人应该能独自守住大桥，并修缮营地。"
D.Strings[53546]="当然。我任你差遣，祝掌门。"
D.Strings[53547]="看来你们在大桥的战斗中打了胜仗？"
D.Strings[53548]="没错。我新朋友的表现令人震惊！"
D.Strings[53549]="是的。在最后的战斗到来时，我们需要他这样的神箭手。"
D.Strings[53550]="看到你很高兴，任塞。我们是来这儿找鹰眼大师砮荣的。在哪儿能找到他？"
D.Strings[53551]="很高兴见到你，祝掌门。他和我剩下的人在远戍哨站坚守。"
D.Strings[53552]="远戍哨站？我没听到报告说下面的沟里有螳螂妖。"
D.Strings[53553]="不，不是沟里。它们会飞。数量庞大，前所未见。"
D.Strings[53554]="陶矢，恨之煞就在附近。找到它，回来跟我报告。"
D.Strings[53555]="奇怪……这个家伙带着一些打磨过的石头。"
D.Strings[53556]="希望它们来自砮皂的雕像。我们只能祈祷了。"
D.Strings[53557]="另一块石头……它的标记和我们找到的其他石头上的标记比较相符。"
D.Strings[53558]="如果我没记错的话，这应该是根石牛尾。"
D.Strings[53559]="现在只剩下头了，它应该在不远的地方。"
D.Strings[53560]="头在这儿。装起来也刚刚好。"
D.Strings[53561]="我们已经完成了砮皂的差事。现在得回去做一些真正的调查了。"
D.Strings[53562]="站在布兰琪的恢复药剂中可恢复生命值和法力值！"
D.Strings[53563]="装弹！预备……瞄准……开火！"
D.Strings[53564]="他们太软弱了！"
D.Strings[53565]="退回山里去！"
D.Strings[53566]="把他们的尸体带回来！"
D.Strings[53567]="$c，在这儿！我需要帮手！"
D.Strings[53568]="抢呀，杀呀，啊哈哈哈哈！"
D.Strings[53569]="一大群飞行兵冲过来了！拿上我的火炮，$c，动作快！"
D.Strings[53570]="那……那是什么？它真打算飞过去吗？"
D.Strings[53571]="它靠近了！把它击落！"
D.Strings[53572]="干得漂亮！我们降到那边，准备收工。"
D.Strings[53573]="它背部的壳裂开了。哪儿疼打哪儿！"
D.Strings[53574]="从背后攻击事半功倍。"
D.Strings[53575]="我吸引了它的注意！全力攻击！"
D.Strings[53576]="它在追我，绕到它后边去，使出全力攻击它！"
D.Strings[53577]="好战者从炮舰上跳下来，加入了战斗！"
D.Strings[53578]="不管你做什么，别让它击中你！"
D.Strings[53579]="|TInterface\\Icons\\ability_warstomp.blp:20|t炮舰即将施放|cFFFF0000|Hspell:121787|h[践踏]|h|r！"
D.Strings[53580]="它在追你！别让它接近。"
D.Strings[53581]="|TInterface\\Icons\\ability_vehicle_siegeenginecannon.blp:20|t炮舰即将施放|cFFFF0000|Hspell:121600|h[火炮弹幕]|h|r！"
D.Strings[53582]="它晕了。现在是消灭它的好机会！"
D.Strings[53583]="厉害。"
D.Strings[53584]="很荣幸能与你并肩作战。"
D.Strings[53585]="要是祝掌门想见我们，最好别让他等太久。出发吧。"
D.Strings[53586]="这个地方看起来不太好。"
D.Strings[53587]="我们已经找到恨之煞的藏身之地了。"
D.Strings[53588]="欢迎，砮荣。有你加入真不错。"
D.Strings[53589]="是的……应该就是这里了。我们走对路了。"
D.Strings[53590]="往哪个方向走？往上，还是往下？"
D.Strings[53591]="透过望远镜看。"
D.Strings[53592]="恨之煞就在那个螳螂妖建筑里……我猜想它是被一个强大的寄主吸引过去的。"
D.Strings[53593]="要想进去，得从这儿的螳螂妖头领身上找到经过特殊转化的水晶。"
D.Strings[53594]="那些头领在这儿……"
D.Strings[53595]="这儿……"
D.Strings[53596]="还有这儿。"
D.Strings[53597]="杀掉他们，夺取水晶。就这么简单。"
D.Strings[53598]="过来，$r，我想和你谈谈。我们的秘密再也藏不住了。"
D.Strings[53599]="陶矢、老陈、砮荣，你们都已分配好各自的任务。到指定地点准备，等我们的信号。"
D.Strings[53600]="陶矢，你带镣铐和扣环了吗？"
D.Strings[53601]="要记住你们训练时学到的东西。如果想活命，就别屈服于仇恨。"
D.Strings[53602]="和以前的做法一样。你去杀，我来找。"
D.Strings[53603]="这个地方看起来真恶心。来，$n。我们到里面去。"
D.Strings[53604]="你们每个人都拿到水晶了吗？"
D.Strings[53605]="是……祝掌门。"
D.Strings[53606]="来吧，羔羊们……来面对死亡吧！"
D.Strings[53607]="当仇恨驱使你们来猎杀我时，你们就已经输了。"
D.Strings[53608]="放弃吧。你越是奋战，心中的仇恨就愈发的炽热。"
D.Strings[53609]="布兰琪发现附近没有盟友，因此撤退了！"
D.Strings[53610]="你差点就死了！"
D.Strings[53611]="掠风者。你醒了。卡拉克西瓦·提克呢？"
D.Strings[53612]="你给我们的圣地带来了什么脏东西？"
D.Strings[53613]="你派出的卡拉克西瓦已经沦为女皇的仆从。"
D.Strings[53614]="这个……你所谓的“脏东西”击败了那仆从，还唤醒了我。"
D.Strings[53615]="我们不需要低贱种族的帮助！干掉它！"
D.Strings[53616]="马上，卡拉克西瓦。"
D.Strings[53617]="让我们再给他一下子！"
D.Strings[53618]="唤醒者也许会有用武之地。不论是以哪种方式。"
D.Strings[53619]="你要死了！"
D.Strings[53620]="你就快死了！"
D.Strings[53621]="你濒临死亡！"
D.Strings[53622]="别死！"
D.Strings[53623]="我要摧毁你们拥有的一切！"
D.Strings[53624]="琥珀之翼飞进来了，小心！"
D.Strings[53625]="那个螳螂妖就是它的宿主。用锁链锁住它，逼出恨之煞！"
D.Strings[53626]="毁灭者身上有炸药。直接攻击会导致他们自爆！"
D.Strings[53627]="控制住螳螂妖！这不会要太多时间。"
D.Strings[53628]="挡住螳螂妖！我们就快完成了。"
D.Strings[53629]="恨之煞，出来受死吧！"
D.Strings[53630]="该你们上场了，影踪派的勇士们！养兵千日，用兵一时！"
D.Strings[53631]="祝踏岚，你多么愚蠢。你逃出了我的手心，却带着满腔的仇恨。你……是……我的！"
D.Strings[53632]="用镣铐，快！"
D.Strings[53633]="或许，可以成为虫群的食物！"
D.Strings[53634]="是什么风把你吹到这儿来的，$r？"
D.Strings[53635]="我很自豪能在这儿将我父亲的传说延续下去。$b$b补充一句，这是一个不断延续的传说。"
D.Strings[53636]="这是什么？！一个陷阱？"
D.Strings[53637]="我们是守护者——既稳若磐石又心如止水。$b$b我们移动时，没有什么东西能阻止我们。我们站定时，没有什么东西能动摇我们。"
D.Strings[53638]="狡猾的影踪派……我低估了你们。可你们的领袖已经是我的了。谁想要救他，就必须同时释放我。"
D.Strings[53639]="这便是他的意愿。我们的职责就是将你封印，而他会见证这一切。"
D.Strings[53640]="有些人认为牦牛是低等动物，只配用来放牧和做一些低贱的劳动。很少有人能看到他们的内在美，那才是这些——玄牛的子嗣——真正拥有的东西。"
D.Strings[53641]="他的牺牲令我们大受鼓舞。"
D.Strings[53642]="该你了，我会跟着你。"
D.Strings[53643]="干得好。"
D.Strings[53644]="我掩护你。等你准备好就出发。"
D.Strings[53645]="真厉害！"
D.Strings[53646]="我与你同在。"
D.Strings[53647]="不错……不错。"
D.Strings[53648]="螳螂妖心怀不轨……我想和桥那边的寺庙有关。"
D.Strings[53649]="你在影踪派很受欢迎。"
D.Strings[53650]="脚步放轻点。"
D.Strings[53651]="我不建议这样做……"
D.Strings[53652]="很高兴见到你，朋友。"
D.Strings[53653]="有空来找我喝一杯。"
D.Strings[53654]="好了，你现在可以停下来了。"
D.Strings[53655]="嗨，你好啊。"
D.Strings[53656]="现在该说再见了。"
D.Strings[53657]="哦，我们这是要玩戳戳乐吗？我喜欢玩戳戳乐！"
D.Strings[53658]="哈哈哈，干得好！"
D.Strings[53659]="影踪派的朋友就是我的朋友。"
D.Strings[53660]="很高兴有你加入。"
D.Strings[53661]="再见，朋友。"
D.Strings[53662]="一路顺风。"
D.Strings[53663]="愿雄鹰为你保驾护航。"
D.Strings[53664]="很快会再见的。"
D.Strings[53665]="我只能为你做这么多了，朋友。"
D.Strings[53666]="你，我，我们结束了。"
D.Strings[53667]="准备好行动了吗？"
D.Strings[53668]="我注意到你了。"
D.Strings[53669]="你是来习武的吗？"
D.Strings[53670]="危险潜藏于长城之外。"
D.Strings[53671]="眼睛放亮点，冒险者。"
D.Strings[53672]="如果你有需要，影踪派就会出现。"
D.Strings[53673]="你高估我的耐心了。"
D.Strings[53674]="你再敢这样……会死无全尸。"
D.Strings[53675]="瞧瞧，这是谁！"
D.Strings[53676]="来和腾武做好伙伴吗？"
D.Strings[53677]="你喜欢我，是不是？"
D.Strings[53678]="你会回来的。"
D.Strings[53679]="和你聊天总是很惬意。"
D.Strings[53680]="一会再聊。"
D.Strings[53681]="如此关注！真让我受宠若惊，亲爱的。"
D.Strings[53682]="小心地将这个带到隐蔽处？"
D.Strings[53683]="带我去卡拉克西维斯。"
D.Strings[53684]="你选了我！我太高兴了！"
D.Strings[53685]="我很乐意与你相处一天。"
D.Strings[53686]="今天的冒险在等着我们呢，是不是？"
D.Strings[53687]="我喜欢你思考的方式。"
D.Strings[53688]="就等你了。"
D.Strings[53689]="我会寸步不离。"
D.Strings[53690]="我跟你一起。"
D.Strings[53691]="我们很快就会把整座岛清理干净的。"
D.Strings[53692]="我们俩合作的很好。"
D.Strings[53693]="你们无处可逃了，小虫子。你们今天要面对的是影踪派。"
D.Strings[53694]="你们应该待在恐惧废土。"
D.Strings[53695]="你们的女皇派你们来送死。"
D.Strings[53696]="悄然致命。"
D.Strings[53697]="哈哈哈……干得好。"
D.Strings[53698]="迷路鬼给猢狲送亮晶晶来啦？！"
D.Strings[53699]="天上掉财宝啦！"
D.Strings[53700]="迷路鬼有财宝吗？"
D.Strings[53701]="该死的无毛怪在猢狲的地盘搞破坏！"
D.Strings[53702]="这是猢狲的领地！无毛怪不许进来！"
D.Strings[53703]="打得漂亮。"
D.Strings[53704]="我耗光你的力气。我的兄弟们会干掉你的！"
D.Strings[53705]="好多猢狲。你马上就死了，迷路鬼。"
D.Strings[53706]="干掉迷路鬼！"
D.Strings[53707]="你的财宝都归猢狲啦，迷路鬼！"
D.Strings[53708]="迷路鬼都发臭啦！"
D.Strings[53709]="我就在你身后。"
D.Strings[53710]="水准高超。"
D.Strings[53711]="你也许觉得他们应该学会逃跑。"
D.Strings[53712]="飞蛾扑火，对不对？"
D.Strings[53713]="嗯，真是令人兴奋。"
D.Strings[53714]="你让我大开眼界，朋友。"
D.Strings[53715]="你的战斗充满激情。我喜欢。"
D.Strings[53716]="你是从哪儿学的？"
D.Strings[53717]="我真服了你。"
D.Strings[53718]="真奇怪，这些螳螂妖总能卷土重来。"
D.Strings[53719]="你现在可能觉得我们已经把他们杀光了。"
D.Strings[53720]="可我觉得他们还没有受到教训。"
D.Strings[53721]="好好招待了我们的螳螂妖朋友一番。"
D.Strings[53722]="结束之后返回营地……我们有很多事情要讨论。"
D.Strings[53723]="锁定信号弹。布姆布姆佳酿守卫者可以发射了。"
D.Strings[53724]="|TInterface\\Icons\\inv_misc_uncutgemnormal.blp:20|t离你的盟友们远点儿！瑟拉提克琥珀陷阱正在对你施放|cFFF00000|Hspell:121881|h[琥珀监牢]|h|r！"
D.Strings[53725]="所有人都抛弃你了。"
D.Strings[53726]="你在这世界上孤苦无依。"
D.Strings[53727]="大家都走了。没人喜欢你。"
D.Strings[53728]="你是没人爱的家伙。"
D.Strings[53729]="没人关心你。"
D.Strings[53730]="你要摔下去了！"
D.Strings[53731]="你的双脚离开了地面！"
D.Strings[53732]="腾云雏龙很高兴见到你！"
D.Strings[53733]="腾云雏龙亲昵地舔了舔你。"
D.Strings[53734]="腾云雏龙在绕圈飞翔。"
D.Strings[53735]="腾云雏龙很开心！"
D.Strings[53736]="腾云雏龙想要玩！"
D.Strings[53737]="腾云雏龙拱了供你的手。"
D.Strings[53738]="|TInterface\\Icons\\spell_yorsahj_bloodboil_yellow.blp:20|t快跑！你被|cFFF00000|Hspell:122064|h[腐蚀树脂]|h|r覆盖了！"
D.Strings[53739]="%s飞到桥的另一端去了！"
D.Strings[53740]="野生的穿云翔龙发现它自由了！"
D.Strings[53741]="鲜活的肉！"
D.Strings[53742]="吞了他们！"
D.Strings[53743]="愚蠢的凡人！"
D.Strings[53744]="我们要挖掉你的眼珠！"
D.Strings[53745]="不变的只有死亡。"
D.Strings[53746]="我们要把你送进坟墓！"
D.Strings[53747]="山泽暴风爪苏醒了！"
D.Strings[53748]="存活下来的卡拉克西瓦太少了。$B$B我沉睡的时候，发生了什么事？"
D.Strings[53749]="我信任卡拉克西的意志。他们会作出符合我族人民最高利益的决定。"
D.Strings[53750]="螳螂妖战士来了，集中火力。"
D.Strings[53751]="<螳螂妖议员眯着他的大眼睛瞟了你一眼。>"
D.Strings[53752]="女皇会在此过程中驱使虫群，同时也会摧毁我们自己的土地。$B$B代价太大了。"
D.Strings[53753]="我知道了……视线锁定目标。全神贯注！"
D.Strings[53754]="啊！它在盯着我！"
D.Strings[53755]="我能行，我知道我能行……"
D.Strings[53756]="得好好教训你们，别来我的村子捣乱！"
D.Strings[53757]="我必须快如……激流！"
D.Strings[53758]="战斗的精髓就是拳拳打在你脸上！"
D.Strings[53759]="复仇对我来说是最好的美味佳肴！"
D.Strings[53760]="我的父亲对我过于保护了，从来不让我做任何事情！"
D.Strings[53761]="像你这样的冒险者一定赢过很多场战斗！"
D.Strings[53762]="我要让我爸看看，我具有成为一个伟大斗士的所有资质。"
D.Strings[53763]="这比我想象中的可要困难多了……"
D.Strings[53764]="如果学战斗跟学跳舞一样，那我可就麻烦了。我是个很糟糕的舞者……"
D.Strings[53765]="我帮不上忙。但我想知道是不是我的装备好一些，就能制造出更多的伤害……"
D.Strings[53766]="在我小时候，我总以为赞达拉部族是他们故意编出来吓唬我，好让我变乖的。"
D.Strings[53767]="我认为自己天生就是个冒险家。跟迷踪岛上的那些熊猫人一样……"
D.Strings[53768]="这些废墟似乎有鬼魂出没。虽然我并不相信有什么鬼魂，但我也不相信有什么赞达拉。"
D.Strings[53769]="这片海滩曾经是个多么宁静的地方。现在被这些蛮族给玷污了！"
D.Strings[53770]="太多的毁灭……太多的死亡……什么时候才是个尽头？"
D.Strings[53771]="……现在，冲锋！"
D.Strings[53772]="瞧瞧那些盛开的鲜花啊，是不是很可爱？"
D.Strings[53773]="春天永远都活在每个人的心里。"
D.Strings[53774]="看那些孩子们！他们给我带来了欢乐。"
D.Strings[53775]="你想和我们一起散散步吗？"
D.Strings[53776]="鲜花每年都在这个时候盛开，它们真香啊！"
D.Strings[53777]="希望你今天过的愉快，$r。"
D.Strings[53778]="春天是四季中我最喜欢的季节。你最喜欢哪个季节？"
D.Strings[53779]="我忙的时候日子过得很快。$B$B我必须提醒我自己停下脚步、享受当下。"
D.Strings[53780]="煞魔逼近了？"
D.Strings[53781]="别担心，$r。他们过不了我这关。"
D.Strings[53782]="孩子们受到了惊吓，但他们会没事的。我们会保障他们的安全！"
D.Strings[53783]="谢谢你的训练，$n。我希望有朝一日能成为像你一样棒的斗士！"
D.Strings[53784]="再来点麦芽酒……嗝！"
D.Strings[53785]="这就是云游者之道。"
D.Strings[53786]="%s摆脱|cFFFF0000|Hspell:120778|h[腐蚀焦油]|h|r！"
D.Strings[53787]="猢狲的船只出现在远方！"
D.Strings[53788]="别动！$B$B哈！我就爱说这个。"
D.Strings[53789]="你很幸运，能跟着我，嗯？！"
D.Strings[53790]="我告诉过你！那些岩石很滑的！"
D.Strings[53791]="你得多加小心！"
D.Strings[53792]="每个人都有一个……"
D.Strings[53793]="下次我可不一定能救得了你！"
D.Strings[53794]="咦！怪物们在攻击绿石村！快跑！"
D.Strings[53795]="正确的战斗姿态是打败敌人的关键所在。不要疯狂挥舞你的武器。进攻要有章法。"
D.Strings[53796]="你的敌人不会对你仁慈。你应该以牙还牙。"
D.Strings[53797]="不要暴露你的弱点。"
D.Strings[53798]="对自己的能力要有信心，这会让你一往无前。但过度自信会很快给你招来杀身之祸。"
D.Strings[53799]="去吧，拔掉一些小花，别拔太多。"
D.Strings[53800]="今天这里很安静，真好。"
D.Strings[53801]="我希望你今天能跟着我。"
D.Strings[53802]="这条路通往昆莱山。祝那些沿着它去土地精商店购物的人好运。"
D.Strings[53803]="你们一定非常强大，才能走这么远。是的……你们会成为合格的试验品。"
D.Strings[53804]="啊，看来你已经见识了我的部分实验。再靠近点儿，我在这里的杰作会让你大开眼界。"
D.Strings[53805]="原谅我，女皇……"
D.Strings[53806]="你们肯定觉得自己很厉害吧。真是愚昧。看看吧，我最伟大的创造！"
D.Strings[53807]="你们都干了些什么？不，我的工作不会就这样结束。我决不允许！"
D.Strings[53808]="幸运儿们，有份大礼要送给你们。"
D.Strings[53809]="没有死就没有生，没有生，何来死……"
D.Strings[53810]="什么？有人偷了丛林烈酒？"
D.Strings[53811]="醒醒！醒醒！他们在偷丛林烈酒！"
D.Strings[53812]="怎么了？今天是什么日子？"
D.Strings[53813]="呕……"
D.Strings[53814]="在无伤者玛里克苏醒过程中挡住虫群！"
D.Strings[53815]="我回来了。我听到了卡拉克西的召唤。"
D.Strings[53816]="无伤者玛里克。"
D.Strings[53817]="没有一击能伤你分毫，却有无数敌人倒在你的战戟之下。"
D.Strings[53818]="还有数不尽的敌人正在涌来，卡拉克西瓦。我很荣幸能在困难之时为大家而战。"
D.Strings[53819]="而你也要效力。去军需官那把自己武装起来吧。这里的虫群听你调遣。"
D.Strings[53820]="你真有别人说的那么强吗？"
D.Strings[53821]="我要挑战你！"
D.Strings[53822]="现在到了最难的部分。大家都往后退，酿造完美的昆莱劲酒关键在于精度！"
D.Strings[53823]="谢谢你救了我们！你准备好开始这场宴会了吗？"
D.Strings[53824]="我们做好防御准备了！"
D.Strings[53825]="螳螂妖生来脑子就缺根筋，却极度渴望战争。参与到集群战争中不仅仅是一种文化上的进阶仪式——还是身体成熟的催化剂。$B$B只有那些从战场上归来的勇士，才能从聚生虫成长为有完整自主意识的个体公民。"
D.Strings[53826]="谢谢你的援助，朋友。"
D.Strings[53827]="喔……$n！"
D.Strings[53828]="欢迎参加宴会，$n！"
D.Strings[53829]="有了$n参加，这将会成为最完美的酿月祭！"
D.Strings[53830]="我刚才还在想你什么时候会来呢，$n！"
D.Strings[53831]="好久不见，$n。"
D.Strings[53832]="嗨，是$n！"
D.Strings[53833]="跟我们喝一杯吧，$n！"
D.Strings[53834]="很高兴见到你，$n！你有空吗？"
D.Strings[53835]="我很高兴你能来这，$n！今晚是酿月祭，而我最拿手的昆莱劲酒所需的原料都还没有运到。我派了助手出去收集它们，可一个都没回来。你能去帮我查查他们怎么了吗？"
D.Strings[53836]="我在哪儿能找到助手琪舞？"
D.Strings[53837]="在酿月祭的夜晚举行仪式，就可以在墨鳃潭见到水灵。过去这些年，我们都会向水灵敬献贡品，以获取一瓶纯净之水用于酿造昆莱劲酒。我派助手塔蒂去湖那儿了，可她还没有回来。你可以去北方查查她出什么事了吗，$n？"
D.Strings[53838]="野牛人！"
D.Strings[53839]="我在哪儿能找到助手塔蒂？"
D.Strings[53840]="快点，波普，我们走！"
D.Strings[53841]="琪舞、塔蒂、布扎齐，快把原料扔进去！"
D.Strings[53842]="$n！酒仙布夫派我从水灵这取一小瓶纯净水，但是波普吃了我们的贡品。现在，我没有办法说服他们给我一瓶，而且他们看上去并不十分友好。你认为你能为我说服他们吗？"
D.Strings[53843]="我派助手琪舞去贮粮塔取回一袋粮食，可她还没有回来。你可以去帮我查查她怎么了吗？你可以在小镇的西侧找到贮粮塔。"
D.Strings[53844]="欢迎来到寇塔峰。非常有名的寇塔咔啡的产地。幸运符懂得品味异域的美酒。"
D.Strings[53845]="欢迎来到我们最最卑微的营地。"
D.Strings[53846]="你的幸运符是什么？"
D.Strings[53847]="$n取走了|cFF01DFD7蓝色|r的球！"
D.Strings[53848]="$n取走了|cFFFF8000橙色|r的球！"
D.Strings[53849]="$n取走了|cFF01DF01绿色|r的球！"
D.Strings[53850]="$n取走了|cFFBF00FF紫色|r的球！"
D.Strings[53851]="|cFF01DFD7蓝色|r宝珠被放回了！"
D.Strings[53852]="|cFFBF00FF紫色|r宝珠被放回了！"
D.Strings[53853]="|cFFFF8000橙色|r宝珠被放回了！"
D.Strings[53854]="|cFF01DF01绿色|r宝珠被放回了！"
D.Strings[53855]="我们必须步步为营。山泽部族在练习一些我们仍无法完全理解的黑暗魔法。"
D.Strings[53856]="我们正努力打开一道从这通往影踪卫戍营的传送门。"
D.Strings[53857]="传送门一旦被打开，我们就能更快地穿行于此地和影踪卫戍营之间。"
D.Strings[53858]="掠风者不会陪你执行这项任务，唤醒者。他的才华另有它用。"
D.Strings[53859]="让我们看看掠风者无法帮助你时，你将如何独自面对沃提克吧……"
D.Strings[53860]="你可以通过支付金钱来更改你的主要专精。\n\n更改主要专精所需金额会随次数的增加而提高。"
D.Strings[53861]="你觉得传送门如何？没有你的帮助，我们绝无法完成！"
D.Strings[53862]="你可以通过支付金钱来遗忘你的当前天赋，以选择新的天赋。\n\n遗忘天赋所需金额会随次数的增加而提高。"
D.Strings[53863]="你可以通过支付金钱来清空你的当前雕文，以选择新的雕文。\n\n清空雕文所需金额会随次数的增加而提高。"
D.Strings[53864]="我希望清空自己所有的雕文。"
D.Strings[53865]="我接受你的挑战！"
D.Strings[53866]="什么！？！？我输了！？！？！"
D.Strings[53867]="你和他们说的一样强，尤其是还打败了我。做的不错。"
D.Strings[53868]="我被说服了。如果你需要我，我会在帐篷后的山上等你。"
D.Strings[53869]="|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t %s开始施放|cFFFF0000|Hspell:117958|h[保护者显形]|h|r！"
D.Strings[53870]="你到达10级时，可以选择一项职业专精。\n\n如果此后你决定更换职业专精，你可以支付金钱重置之前的选择。\n\n更换职业专精所需的金额会随次数的增加而提高。"
D.Strings[53871]="我们在挑战者之环见吧，如何？"
D.Strings[53872]="你到达15级时，可以选择第一个天赋。\n\n如果此后你决定更换天赋，你可以支付金钱重置之前的选择。\n\n更换天赋所需的金额会随次数的增加而提高。"
D.Strings[53873]="你到达25级时，可以开始使用雕文。\n\n如果此后你决定替换所选的雕文，你可以支付金钱进行重置。\n\n替换雕文所需的金额会随次数的增加而提高。"
D.Strings[53874]="你到达30级时，可以学习双专精，使你能够保留两套激活的职业专精、天赋和雕文设置，并可以轻易地在两者间进行切换。\n\n每一套设置都有单独的雕文框和动作条。\n\n在战斗中无法切换两套设置，并且切换会消耗你的可用资源。"
D.Strings[53875]="猢狲律法第二条……入侵者全都得死！"
D.Strings[53876]="把会飞的无毛怪统统打下来！"
D.Strings[53877]="别放过会飞的无毛怪！"
D.Strings[53878]="无毛怪入侵！无毛怪从天上来！"
D.Strings[53879]="啊……被无毛怪弄死了……"
D.Strings[53880]="不公平！无毛怪踩着猢狲的尾巴！"
D.Strings[53881]="一波|cFF00dc29希克提克虫群|r加入了战斗。"
D.Strings[53882]="我对这一天期待已久。那么我们在挑战者之环见吧。"
D.Strings[53883]="让我们放手一搏吧。"
D.Strings[53884]="你打得很出色，跟我预想的一样。"
D.Strings[53885]="你比我们初见时长进了许多。"
D.Strings[53886]="和你并肩战斗是我的荣幸。如果你需要我，就来山上找我吧。"
D.Strings[53887]="[PH]你是如何训练一名狂暴战士的？"
D.Strings[53888]="我要撕碎山谷中所有的奴隶，你们这微不足道的暴动只有死路一条！"
D.Strings[53889]="我们没有想到……"
D.Strings[53890]="我会永怀感激之情。"
D.Strings[53891]="安全起见，我这就离开。谢谢你。"
D.Strings[53892]="我……谢谢你。"
D.Strings[53893]="我们在亭子那见。真是太感谢你了。"
D.Strings[53894]="什么……我在哪里？"
D.Strings[53895]="这里发生了什么？大地发生了变化……"
D.Strings[53896]="我沉睡了多久？"
D.Strings[53897]="|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s将受到|cFFF00000|Hspell:117283|h[净化之水]|h|r的治疗效果！移动他！"
D.Strings[53898]="|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s正受到|cFFF00000|Hspell:117283|h[净化之水]|h|r的治疗效果！驱散他！"
D.Strings[53899]="我见识过许多场战斗，医治了许多盟友，净化了许多灵魂，在我的指挥下许多敌人都死了。\n\n你可能觉得躲在城墙下会很安全，但请别弄错了，战争会像瘟疫一样席卷大地，只有很少一部分幸运的人能活下来，讲述这悲惨的往事。"
D.Strings[53900]="我有很多事要操心，$n。出去找点事，证明你的价值。"
D.Strings[53901]="好无聊啊！我们去追捕些坏人吧。"
D.Strings[53902]="我早已按耐不住了！"
D.Strings[53903]="你没看见我正在刻苦训练吗？"
D.Strings[53904]="只要你一句话，我就会来帮你。"
D.Strings[53905]="很少有人能够在严寒下存活。"
D.Strings[53906]="你听说过暗影之舞吗？这是在战斗中上演的舞蹈。$B$B它是死亡之舞。"
D.Strings[53907]="有些人的舞蹈充满激情并热衷于此，比如非离。$B$B而有些人却不喜欢，除非被激怒，比如雅丽亚。"
D.Strings[53908]="暗影之舞的秘密在于掌控力。$B$B精确。$B$B敏捷。$B$B优雅。$B$B动作不能多一步，也不能缺一步。"
D.Strings[53909]="每一击都应传达你的最终意图。"
D.Strings[53910]="我通过冥想寻求智慧。"
D.Strings[53911]="只有通过内在的平衡，我们才能让自己内心平静下来。"
D.Strings[53912]="内心平静下来，我们就不会发怒、憎恨、怀疑和恐惧。"
D.Strings[53913]="我们最大的敌人就是自己。"
D.Strings[53914]="如果你打这场比赛，就一定要全力以赴。"
D.Strings[53915]="谢谢你，勇士。"
D.Strings[53916]="我以为等援军赶到我早就凶多吉少了\n\n谢谢你。"
D.Strings[53917]="你在战斗中表现的英勇真让我汗颜。谢谢你，陌生人。"
D.Strings[53918]="绿石道场欠你一份人情。\n\n这事结束后我们要好好喝上几杯！"
D.Strings[53919]="非常感谢……我差点就坚持不住了。\n\n哎呀，我现在这样是没法再战斗了。\n\n要是我们所有的绿石佳酿没有被偷该多好啊！那样我就可以做出一个能为你带来不可思议能量的配方……"
D.Strings[53920]="鱼竿仅仅只是辅助工具！真正的渔夫用自己的手捕鱼。"
D.Strings[53921]="我曾经抓到过一条鱼，大小有你三个祖先加起来这么大。虽然最后它逃走了，但是逮到那条鱼的喜悦感是任何东西都无法比拟的。"
D.Strings[53922]="你以前惹急过鲨鱼，让它跳出水来在陆地上追你吗？"
D.Strings[53923]="钓最大的鱼要用的最好鱼饵？把结婚戒指挂到你的鱼钩上。"
D.Strings[53924]="没人知道环礁湖底有些什么，除了那些去过下面的人们。还有那些和去过下面交流过的人。"
D.Strings[53925]="你尝过黄油海怪腿吗？真是世间美味。"
D.Strings[53926]="<他睡得很熟。>"
D.Strings[53927]="你好，朋友。你要喝些什么？"
D.Strings[53928]="最近有没喝上什么好酒？"
D.Strings[53929]="我想你可以留下来。"
D.Strings[53930]="你一定要这样喋喋不休吗？"
D.Strings[53931]="你真的叫风暴烈酒？"
D.Strings[53932]="什么爆发？我一向如此。"
D.Strings[53933]="你一定要待在这吗？"
D.Strings[53934]="就把你的钱留在箱子里吧。"
D.Strings[53935]="噢，就只有你。"
D.Strings[53936]="我敢说你甚至不会买任何一件东西。就像其他人一样。"
D.Strings[53937]="我就不该开这家旅店。这里真是太压抑了。"
D.Strings[53938]="<大丹发出各种声响，夹杂着沉重的鼾声和断断续续的呓语。>$b$b没错……就是风暴烈酒……"
D.Strings[53939]="你见过有个叫风暴烈酒的人经过这里吗？"
D.Strings[53940]="是的，见过一些。其中最壮硕的那个名叫韩，他最后一个出发加入了库尔维斯的战斗。$b$b事实上，我已经好几天没见着他了。希望一切顺利……"
D.Strings[53941]="你在落日酒坊这里见到过叫风暴烈酒的吗？"
D.Strings[53942]="你是指除了在那边的懒汉大丹以外的其他人吗？当然！$b$b在艾薇去北方捕猎，我和她共处了一段时间。真是个乖巧可人的姑娘。$b$b当然，谁又能忘掉风暴烈酒大妈呢？"
D.Strings[53943]="能再见到你真好，$n。"
D.Strings[53944]="我愿意多留一会，可我得去看看，风暴烈酒家的其他人怎么样了。"
D.Strings[53945]="真心希望我们能再次相见。"
D.Strings[53946]="你很不情愿地开始施放一次|cFFFF0000|Hspell:122398|h[琥珀爆炸]|h|r！"
D.Strings[53947]="琥珀畸怪准备好|cFFFF0000|Hspell:122398|h[琥珀爆炸]|h|r了！"
D.Strings[53948]="他们说你叫艾薇。"
D.Strings[53949]="说你是个可爱的姑娘。"
D.Strings[53950]="不曾见你……但你是我的家人。"
D.Strings[53951]="愿你来生的旅途充满快乐与美好。"
D.Strings[53952]="再见了，艾薇·风暴烈酒。"
D.Strings[53953]="她长得很像丽丽。"
D.Strings[53954]="琥珀附近的水池开始剧烈地冒泡！"
D.Strings[53955]="够了！你已经浪费了我太多时间。我不能为这种低贱的小人物分心。"
D.Strings[53956]="我的伟业将在别处……继续。"
D.Strings[53957]="唉，我无法继续前行了。要是我们的绿石佳酿没被偷光就好了！"
D.Strings[53958]="好，终于盼到了！准备采取行动。"
D.Strings[53959]="让我们点燃他们！"
D.Strings[53960]="忍受不了这热浪？那就走远点儿！"
D.Strings[53961]="那可真够热的。"
D.Strings[53962]="我们真是合作无间啊！"
D.Strings[53963]="你觉得这够热了吗？"
D.Strings[53964]="我们今天要去哪里？"
D.Strings[53965]="又一个……失去了。"
D.Strings[53966]="他也许再也看不到大地重归平静……可他至少为此而战过。"
D.Strings[53967]="来吧。这里没别的事要做了。"
D.Strings[53968]="我们齐心协力，就能战胜敌人。"
D.Strings[53969]="让我到战场上测试一下训练成果吧。"
D.Strings[53970]="你选对人了。"
D.Strings[53971]="放慢你的脚步。"
D.Strings[53972]="我感到有一股寒意逼近。"
D.Strings[53973]="我要继续前进了。他们说风暴烈酒大妈还在某个地方。"
D.Strings[53974]="复仇是一道美味的冷菜。"
D.Strings[53975]="你被冻住了！"
D.Strings[53976]="让你的脑袋冷静一下。"
D.Strings[53977]="做好挨冻的准备了吗？"
D.Strings[53978]="不要临阵脱逃。"
D.Strings[53979]="我们的敌人必将灭亡。"
D.Strings[53980]="你打头，我跟着。"
D.Strings[53981]="责任在召唤。"
D.Strings[53982]="我们的敌人低估了圣光的力量。"
D.Strings[53983]="他们必须先过我这一关。"
D.Strings[53984]="让圣光保护我们！"
D.Strings[53985]="我会保护你免受伤害！"
D.Strings[53986]="我们必须坚持！"
D.Strings[53987]="我将照亮道路。"
D.Strings[53988]="请每次只下一个订单。"
D.Strings[53989]="我正在以最快的速度酿酒。"
D.Strings[53990]="你真走运！我们刚进了一大批新货。"
D.Strings[53991]="应该试试特别的。"
D.Strings[53992]="和我一同飞翔吧，唤醒者，我要让你见识下掠风者的风采。"
D.Strings[53993]="你以为自己能在一场宠物大战里打败我？走上前来，试试身手吧！"
D.Strings[53994]="我需要你的帮助，掠风者。"
D.Strings[53995]="请带我飞到夏柯希尔之巢"
D.Strings[53996]="把足够多的敌人聚到一起，然后我将从天空发起攻击。"
D.Strings[53997]="我把你送至地面的那股力量足以消灭着落点附近的任何敌人。请你谨慎挑选好你要着落的地方。"
D.Strings[53998]="我们是女皇意志的延伸。"
D.Strings[53999]="我们只以她的神圣之名效忠。"
D.Strings[54000]="从不质疑，也不思考，我们只需行动。"
D.Strings[54001]="我们战斗、劳作、效命，以使女皇对我们的期望成真。"
D.Strings[54002]="她的幸福就是对我们的犒赏，她的悲伤就是我们的失败。"
D.Strings[54003]="我们会毫不犹豫的为女皇献出生命。她就是明灯，没有她，我们的生命都将陷入无边黑暗。"
D.Strings[54004]="世界的糟粕被恐惧所驱使，在我们的门前飘摇；她的皇廷风暴会将他们一举驱散。"
D.Strings[54005]="女皇的神圣意志犹如高山，而他们就像是拍打高山的海浪。纵使滚滚而来，也必将一事无成。"
D.Strings[54006]="神祗命我们对抗这些闯入者。"
D.Strings[54007]="他们根本不配沐浴她神圣的光辉。"
D.Strings[54008]="我们一往无前。我们坚定不移。"
D.Strings[54009]="就让我们——女皇钦点的声音，来执行使命。"
D.Strings[54010]="站在酒桶边取些啤酒吧！"
D.Strings[54011]="我们被神祗选中，为女皇神圣的意志赋予不朽的声音。我们任她差遣。"
D.Strings[54012]="神祗决不容许你玷污此地，外来者。"
D.Strings[54013]="我们惟命是从，而你，惟死乃终。"
D.Strings[54014]="藉由空气，女皇为我们的声音赋予力量。"
D.Strings[54015]="聆听女皇神圣怒火的声音吧。"
D.Strings[54016]="我们的声音承载着女皇的意志。"
D.Strings[54017]="女皇的意志凌驾于我们所有人之上。要么从命，要么受死。"
D.Strings[54018]="女皇恩赐浩荡，我们感激涕零。"
D.Strings[54019]="她在考验我们。我们不会让她失望。"
D.Strings[54020]="我们如缔造殿堂的琥珀坚不可摧。凭借女皇之力，我们将消灭任何胆敢闯入她神圣家园的入侵者。"
D.Strings[54021]="我们不会向黑暗虚空的绝望屈服。如果女皇要我们去死，我们便照做。"
D.Strings[54022]="也许你该和她谈一谈。"
D.Strings[54023]="艾莎？我不知道该和她说些什么。也许我应该说“你长得很迷人”，但她会不会觉得我这样很怪？或许我可以告诉她我很钦慕她那从容不迫的姿态 ——但我又怕她觉得我这个人缺乏个性！"
D.Strings[54024]="你知道吗，他们说这些山里全是雪人。"
D.Strings[54025]="哦……好吧……你知道……“他们”。"
D.Strings[54026]="猢狲又在大肆掠夺了。我的膝盖能感受得到。"
D.Strings[54027]="那是我的右膝。我的左膝能感受到猢狲的肆虐。"
D.Strings[54028]="有来自寇塔营地的消息么？"
D.Strings[54029]="我听说粗麻哨站遭到了猢狲的破坏。"
D.Strings[54030]="还听说野牛人霸占了南部的大部分农田。"
D.Strings[54031]="听起来受到袭击的应该是麝香爪牧场。"
D.Strings[54032]="野牛人。"
D.Strings[54033]="我最近连一个影踪派门的人影都没见到。"
D.Strings[54034]="我听说野牛人穿过了熊猫人城墙。"
D.Strings[54035]="把我所知道的转告给那个农夫。可怜的家伙在遭受入侵时失去了他所有的庄稼。"
D.Strings[54036]="你听说了吗，有些土地精不愿意爬上不息山？"
D.Strings[54037]="我仍然记得守卫粗麻小径的那段时光。"
D.Strings[54038]="嘿！我曾经是一名影踪派门徒。"
D.Strings[54039]="……从前。"
D.Strings[54040]="我还以为你只能靠膝盖来感受天气的变化呢。"
D.Strings[54041]="没有寇塔咔啡？那我早上要怎样才能醒来？"
D.Strings[54042]="你太冷酷无情了。那些土地精怎么办？"
D.Strings[54043]="知道耗牛长什么样吗？"
D.Strings[54044]="想象下这些巨兽直立着用双脚走路，凶神恶煞的样子。"
D.Strings[54045]="我希望他们能顺利脱身。老麝香爪虽然看上去吊儿郎当的但骨子里是个善良的人。"
D.Strings[54046]="他们被召回了蟠龙脊。"
D.Strings[54047]="这不可能。没有东西能越过这城墙。"
D.Strings[54048]="迷信与否，你是不会看到我去任何连土地精都不敢涉足的地方。"
D.Strings[54049]="这是在你亲手建造这座城墙之前还是之后？"
D.Strings[54050]="谁说的？"
D.Strings[54051]="不。而且也没有咔啡。黑暗的日子即将来临了。"
D.Strings[54052]="嗯。我从未真正喜欢过那里。厕所里总是脏兮兮的。"
D.Strings[54053]="冷酷无情？要求有一间干净的厕所很过分么？"
D.Strings[54054]="干吗？！别那样看着我！"
D.Strings[54055]="什么是野牛人？"
D.Strings[54056]="被什么东西袭击了？林精？"
D.Strings[54057]="那么是谁在保卫粗麻小径？"
D.Strings[54058]="我确信他们只是被迷信冲昏了头脑。"
D.Strings[54059]="喝酒可不是守卫的职责。"
D.Strings[54060]="<韩被包围在琥珀的坟墓里。>"
D.Strings[54061]="<倒一些恐惧老酒在韩的琥珀上。然后看看会发生什么。>"
D.Strings[54062]="发生了什么事？我最后记得的是……"
D.Strings[54063]="呃，你把什么倒在了我的身上？好恶心啊！"
D.Strings[54064]="该冷静一下了……脑子有点混乱……我需要集中精神。"
D.Strings[54065]="哇哦……那是什么东西？你想打架么！？我的头为什么这么晕？我要……我要……"
D.Strings[54066]="树脂大师……瞧那个卷轴！"
D.Strings[54067]="上面记载了阻止螳螂妖的方法。一种阻止煞的方法！"
D.Strings[54068]="让我瞧瞧！"
D.Strings[54069]="不，我的徒弟，看看上面的这些词：“容器”、“冷浸”、“配方”……"
D.Strings[54070]="这是一份啤酒的配方！"
D.Strings[54071]="耶！！啤酒！"
D.Strings[54072]="你错了，师傅。"
D.Strings[54073]="|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆察觉到$n在它下方并开始施放|cFFFF0000|Hspell:122774|h[重碾]|h|r！"
D.Strings[54074]="|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆感觉到了信息素，开始施放|cFFFF0000|Hspell:122774|h[重碾]|h|r！"
D.Strings[54075]="来吧，吴龙！ 美酒在召唤！"
D.Strings[54076]="耶！啤酒！"
D.Strings[54077]="你们两个要去哪儿？"
D.Strings[54078]="哪儿都不去。"
D.Strings[54079]="里基屯村！"
D.Strings[54080]="里基屯……就是那里！"
D.Strings[54081]="“咒法妖精”……那所指的一定是里基屯树精。"
D.Strings[54082]="你想挑战恶名昭著的“赤烟”腾武？来吧，朋友，让我们看看你的本事！"
D.Strings[54083]="哈哈哈，我看你根本不知道自己在做什么……"
D.Strings[54084]="别担心，我会手下留情的。"
D.Strings[54085]="不错，还不错……可还没完呢！"
D.Strings[54086]="好吧！看来那些肌肉也不光是摆设！"
D.Strings[54087]="你确实赢得了我的尊重。这可不容易，我的朋友！"
D.Strings[54088]="嚯嚯，我们一定可以找到很多乐趣的！"
D.Strings[54089]="哈，很有趣，对吧？"
D.Strings[54090]="撕碎书页"
D.Strings[54091]="收集补给品"
D.Strings[54092]="这么多的情绪被从陵墓中释放出来。到处充满了愤怒和恐惧……"
D.Strings[54093]="这些陵墓里隐藏了许多的秘密，$n。"
D.Strings[54094]="很多魔古帝王都让他们的仆从殉葬以困住他们的灵魂，这些仆从只能永远侍奉他们的主人。"
D.Strings[54095]="这个地方让我感到寒冷彻骨，$c。"
D.Strings[54096]="束缚灵魂是非常残暴的法术。剥夺死者永恒的安宁是一种无法形容的残忍行为。"
D.Strings[54097]="我们的噩梦不是天方夜谭，这个山谷就是最好的证明。"
D.Strings[54098]="制造拓片"
D.Strings[54099]="是琥珀在我沉睡时让我继续存活，不过我能感觉到它的力量随着时间逐渐消逝。$B$B如果你刚才试图唤醒我时没有成功，我恐怕将永远无法苏醒。"
D.Strings[54100]="我今天需要你的帮忙，至尊者。"
D.Strings[54101]="我今天需要你的帮忙，夏克里尔。"
D.Strings[54102]="我今天需要你的帮忙，切割者。"
D.Strings[54103]="我今天需要你的帮忙，觅血者。"
D.Strings[54104]="我……在……哪儿？出什么事了？"
D.Strings[54105]="你被某种古老而又邪恶的虫子控制住了心智。"
D.Strings[54106]="噢，对。呸，我遇到过更糟的事呢。你是谁？"
D.Strings[54107]="我是陈·风暴烈酒。来自迷踪岛。"
D.Strings[54108]="风暴烈酒？不，你骗人。真的？迷踪岛的风暴烈酒族人，来到了潘达利亚！那其他的亲人呢？"
D.Strings[54109]="在回树脂大师家的路上我再解释给你听。"
D.Strings[54110]="那儿！卡拉克西！控制住水晶……别让它跑了！"
D.Strings[54111]="自由……"
D.Strings[54112]="八百七十七年来，我在那块水晶中等待……看白驹过隙，数岁月流逝。"
D.Strings[54113]="现在，别的地方还需要我。"
D.Strings[54114]="等到你看见我要给你的东西……"
D.Strings[54115]="一波|cFFB600B8希克提克毁灭者|r加入了战斗。"
D.Strings[54116]="%s开始靠近平台！"
D.Strings[54117]="唔……我想到一个疯狂的主意，但这需要你们的帮助，英雄们。"
D.Strings[54118]="我们要让这些螳螂妖自食其果！"
D.Strings[54119]="李，罗，把树脂准备好！"
D.Strings[54120]="让派对开始吧，准备好了吗？"
D.Strings[54121]="来吧，丑八怪！"
D.Strings[54122]="|TInterface\\Icons\\spell_holy_surgeoflight.blp:20|t%s施放了|cFFFF0000|Hspell:122789|h[阳光]|h|r！"
D.Strings[54123]="虫群从斜坡上来了，快用树脂让他们减速。"
D.Strings[54124]="毁灭者，去吧！把一切化为灰烬！"
D.Strings[54125]="战士们，踩扁这些懦夫！粉碎他们！"
D.Strings[54126]="%s召唤了一个|cFFFFFFFF恐惧实体|r！"
D.Strings[54127]="里基屯村欢迎你，外乡人。"
D.Strings[54128]="分叉之刃已经准备好了，我们已经献出了馈赠。 施放你的咒语吧。"
D.Strings[54129]="是啊。这太可怕了。"
D.Strings[54130]="我想我可以称呼它为……恐惧老酒。你想尝尝吗，丽亚？"
D.Strings[54131]="不用了！我想我们已经证明了这并不是一个啤酒配方。"
D.Strings[54132]="好吧。那你呢，吴龙？"
D.Strings[54133]="耶！啤酒！！！"
D.Strings[54134]="你要是想找点刺激，这个木桶里的酒随时可供你饮用。"
D.Strings[54135]="哈！你以为自己能挑战我了吗？"
D.Strings[54136]="但愿待会儿你还能站得住。"
D.Strings[54137]="嗯？怎么回事？"
D.Strings[54138]="我是来挑战你的！"
D.Strings[54139]="怎么，你改变主意了？我自己也知道，跟一个像我这样的人挑战不是什么好主意。"
D.Strings[54140]="来吧，你就这点能耐？"
D.Strings[54141]="你比你看起来要厉害。"
D.Strings[54142]="我承认……这场战斗让人印象深刻。"
D.Strings[54143]="好吧，不打不相识。我们现在是朋友了！"
D.Strings[54144]="只要你需要，我都愿意和你再战一回。"
D.Strings[54145]="嗯……如果我将一些淡酒和烈酒混合……\n\n哦，我的天。瞧瞧这玩意儿！"
D.Strings[54146]="我另外有个问题。"
D.Strings[54147]="一位访客！潘达利亚正在非常时期——迷雾散去，再次现世。你应该是为了和平而来的吧？"
D.Strings[54148]="一波|cFF00dc29希克提克虫群|r和|cFF815d18希克提克战士|r加入了战斗。"
D.Strings[54149]="一波|cFFB600B8希克提克毁灭者|r和|cFF815d18希克提克战士|r加入了战斗。"
D.Strings[54150]="啊，你好，陌生人！洄梦仙酒味道如何？酒不醉人人自醉，雾里看花花非花。半梦半醒，谁是谁非？"
D.Strings[54151]="你我相识一场，不如陪我走走。你们那儿的人可喜欢园艺？"
D.Strings[54152]="他们令我们无法接近！快派空中支援！"
D.Strings[54153]="琥珀之翼，快去！围歼那些抵抗者！"
D.Strings[54154]="%s递给你一把剪刀，指着一棵未经修剪的高大树木。"
D.Strings[54155]="感受其中的黑暗吧！"
D.Strings[54156]="好极了，完美的修剪。所谓顺木之天，以致其性。"
D.Strings[54157]="有些人觉得哪里不如意就剪掉，那实在是取了这棵树的性命。此绝非熊猫人处世之道。"
D.Strings[54158]="哦看呐，谁又能知道如此美丽的东西藏于此中呢？看来你们联盟善于通过精心的修剪来改变周围的世界。真有趣。"
D.Strings[54159]="我是一个“游学者”——为我的人民跋涉历史的长河。我擅于运用言辞的力量。"
D.Strings[54160]="不幸的是，我的——呃——艺术天赋相对匮乏。你觉得我该怎么装饰这高墙？"
D.Strings[54161]="噢，对。我记得你。让我们瞧瞧你学会了什么。"
D.Strings[54162]="来次挑战，哈？看看你有什么本事。"
D.Strings[54163]="希望你的招式不会让人一眼看穿。"
D.Strings[54164]="噢，你想试试那招？来吧！"
D.Strings[54165]="怎么了，你忘记怎么出招了？"
D.Strings[54166]="好吧…这招还不错。"
D.Strings[54167]="哇哦！我以前从来没见过那招。看来你确实不赖。"
D.Strings[54168]="当然，我跟你走。还得研究一下你的招式呢！"
D.Strings[54169]="任何时候只要你需要我，我都在这儿。"
D.Strings[54170]="好了？出发！我迫切的想知道你有点什么本领。"
D.Strings[54171]="好的，让我们开始吧！"
D.Strings[54172]="不必说话。你的存在即是表达。我们熊猫人崇尚至美，而至美就存在于我们身边："
D.Strings[54173]="枝干的曲线，旭日的色彩，甚至是武士舞出剑弧的完美瞬间。"
D.Strings[54174]="游学者的技艺不够精妙，缺少专业的技术指导。 也许你能做得更好？"
D.Strings[54175]="<画一幅安度因王子的肖像画。>"
D.Strings[54176]="起来吧，我的宠物们！去吃了他们！"
D.Strings[54177]="我要亲眼见证你的死亡！"
D.Strings[54178]="这是谁啊？什么王子？一个孩子。啊，一个没有童年的孩子——他的眼神告诉我了。"
D.Strings[54179]="我感到你们从很小的时候就开始崇拜伟大的东西。"
D.Strings[54180]="我的任务就快完成了。来吧，来看看我收养的珍禽异鸟。能喂喂它们可是你的福气哦。"
D.Strings[54181]="这琥珀是我们的，闯入者！琥珀不是给螳螂妖准备的！"
D.Strings[54182]="这个英杰是女皇的！ 你休想得到他！"
D.Strings[54183]="我被称作游学者——可以说是我们熊猫人里的史学家。"
D.Strings[54184]="卡拉克西派你去对付虫群？ 啊，如此强大的人居然堕落到这个地步。 过来，小朋友。 如果可以的话，请带上这位英杰！"
D.Strings[54185]="跟着我，旅行者。让我们彼此多了解一下对方。"
D.Strings[54186]="也可以说，知识是我的护甲，羽毛笔就是我的利剑。"
D.Strings[54187]="潘达利亚的历史甚至对我们来说都笼罩着迷雾。"
D.Strings[54188]="这需要我们不倦地探索远古留下的线索，用智慧来揭示真相。"
D.Strings[54189]="啊，我们到了。小心——我曾经在这个地方遇到过麻烦。"
D.Strings[54190]="你已经胜过我了。如果你还想继续前行，就到山顶的道场去找雪流大师吧。"
D.Strings[54191]="%s施放了|cFFFF0000|Hspell:123244|h[隐藏]|h|r！"
D.Strings[54192]="终……于……我的时代来临了。"
D.Strings[54193]="有很多事情要做。不过首先，唤醒者……帮助我恢复体力。"
D.Strings[54194]="游学者的使命就是要让历史重见天日——将迷雾一团一团地驱散。"
D.Strings[54195]="%s施放了|cFFFF0000|Hspell:123461|h[滚开！]|h|r"
D.Strings[54196]="我上次看到这个地方，已经是很多年前了，唤醒者。很多东西都变了。"
D.Strings[54197]="我们必须尽快工作，让这个信标重新运作起来。"
D.Strings[54198]="嗯。琥珀的味道让人难以忘怀。"
D.Strings[54199]="我的眼睛欺骗了我？远处的城墙是怎么回事？"
D.Strings[54200]="遥想混沌初开之时，第一批凯帕圣树花开如锦。"
D.Strings[54201]="那些树上流出的琥珀养育了我们。 我们把它叫做凯帕琥珀，大地的血液。"
D.Strings[54202]="它治愈我们的伤口，强健我们的身体。它尝起来芳香中带着火辣，它赐予我们力量来征服其他弱小的种族。"
D.Strings[54203]="快点，唤醒者。我得竭力克制自己才能不把你撕成碎片。"
D.Strings[54204]="卡利姆多改变了很多。我都不认识这个地方了。"
D.Strings[54205]="古塔倒塌了吗？ 我从我的同胞那里听不到任何消息。"
D.Strings[54206]="你为何前来唤醒我？卡拉克西部族为何不派遣他们自己的成员前来？"
D.Strings[54207]="我现在要举行我族人的神圣仪式。"
D.Strings[54208]="附近的煞魔生物有我需要的阴影……但是你也可以在附近的野生动物身上找到一些。 祝你好运！"
D.Strings[54209]="%s召唤了一些元素来|cFFFF0000|Hspell:123250|h[保护]|h|r她！"
D.Strings[54210]="你受伤了吗？你需要什么吗？"
D.Strings[54211]="保持警惕。敌人随时可能发动攻击。"
D.Strings[54212]="多战斗，少说话。"
D.Strings[54213]="你真该看看我那个时候的螳螂帝国，唤醒者。我们的领土一直延伸到视线的尽头。"
D.Strings[54214]="当毁灭的召唤降临，我族的大军遮天蔽日。"
D.Strings[54215]="在他们让我沉眠于琥珀之前，我曾听过数百万计的虫群呼喊着我的名字。而现在，我什么都听不见。"
D.Strings[54216]="这些奇怪的生物是什么？"
D.Strings[54217]="他们把琥珀带去哪里了？熔炉在哪儿？琥珀锻工在哪儿？"
D.Strings[54218]="看起来好像有其他人也发现了琥珀的价值。"
D.Strings[54219]="哇呀呀呀呀"
D.Strings[54220]="一名游学者的工作是沉重枯燥的，旅行者。$b$b他必须运用纷繁复杂的知识去认识事物的本质。"
D.Strings[54221]="嗯？我在哪儿？发生了什么？$B$B对不起，我一定是迷迷糊糊的睡着了。"
D.Strings[54222]="有关于……脸！"
D.Strings[54223]="治愈佳酿来啦！来尝尝吧！"
D.Strings[54224]="这块石头讲述了两千五百年前一位伟大猢狲督军的故事。你们的领袖什么样？是诗人还是战士？我真想见见。"
D.Strings[54225]="去死吧，软皮！"
D.Strings[54226]="作好准备！蜥蜴人突袭者来了！"
D.Strings[54227]="自从篡位者改变了世界后，我们的种族就受到了很多威胁。前途渺茫。"
D.Strings[54228]="我们的祖先曾经看到了遥远的未来，看到了他的再生，但是我们看到的却是族人受到了诸多危险的困扰。 如果对这种危险置之不理，我们将会灭亡。"
D.Strings[54229]="是我建议我们最伟大的战士们进入琥珀休眠，然后在虫群最需要帮助的时候唤醒他们。"
D.Strings[54230]="这一觉睡下去，也许再也无法醒来。风险极高。代价极大。但却必须这么做。"
D.Strings[54231]="所以，我是第一个英杰。这也正是我为何是至尊者的原因。"
D.Strings[54232]="现在，卡拉克西号召我们战斗。现在，我已从沉睡中苏醒。"
D.Strings[54233]="蜥蜴人从魔古时期以来就一直肆虐于这片土地。他们不可能与我们达成和解。但是，我们从未停止过尝试！战争只是下策。"
D.Strings[54234]="雷施的倒影荡起不祥的涟漪。"
D.Strings[54235]="她的倒影又再次震荡起来。"
D.Strings[54236]="%s出现了！"
D.Strings[54237]="感谢你的帮助——这些笔记对我的研究至关重要。你的人民也同样重视知识吗？我想是的，因为你是乘坐一艘巨大的飞船来的。"
D.Strings[54238]="好了。快，我们得在他们回来之前继续前进。"
D.Strings[54239]="熊猫人的历史就说到这儿吧。谈谈你的种族，旅行者。"
D.Strings[54240]="仅仅观察你的动作，我已获益良多。你的招式既充满年轻人的热忱，又有老手的稳健。想必你是久经沙场了吧？"
D.Strings[54241]="对，是真的！这是凯帕圣树·扎尔！"
D.Strings[54242]="为什么我在其中感觉不到生命的迹象？在其根茎叶脉间为什么没有琥珀树脂在流动？"
D.Strings[54243]="我必须检查这棵树。在我做检查时保护好我，唤醒者！"
D.Strings[54244]="完成了。凯帕圣树·扎尔……因不堪忍受的痛苦而呻吟着。"
D.Strings[54245]="有兴趣租个风筝吗？"
D.Strings[54246]="我想去借农夫老方的风筝。"
D.Strings[54247]="哦，没问题！$b$b农夫老方说，如果你想要，你可以使用一只他精美的风筝。显然他喜欢上你了。"
D.Strings[54248]="我要拿标准红色风筝。"
D.Strings[54249]="我要拿高空蓝色风筝。"
D.Strings[54250]="我要拿迅捷黄色风筝。"
D.Strings[54251]="我要拿热舞绿色风筝。"
D.Strings[54252]="啊，这是个特别的地方。我的祖辈们曾把这片林子当做家。来吧，我们很快就好。"
D.Strings[54253]="另一个古老的地方，这个地方在近些年中变得更加特殊了。"
D.Strings[54254]="收集琥珀"
D.Strings[54255]="李，罗，照看好下面的朋友们。"
D.Strings[54256]="啊，大门锁住了，但我想我有办法弄开它。"
D.Strings[54257]="让我看看……三十秒的引线……"
D.Strings[54258]="我说三十了？我是想说三。"
D.Strings[54259]="快去，快！你必须阻止攻城！"
D.Strings[54260]="我感觉我能照顾自己了，$n。我必须要立即将这……邪煞……报告给议会。如果我们还能见面，应该是在卡拉克西维斯了。"
D.Strings[54261]="%s从她的保护气泡中浮现而出。"
D.Strings[54262]="我……需要……食物。"
D.Strings[54263]="真没想到我竟然睡了如此之久。许多事情都变了。"
D.Strings[54264]="当我醒来时，卡拉克西对我提起了你。看来你并非毫无用处。"
D.Strings[54265]="我一苏醒，卡拉克西就感觉到了我的存在，把敢于透露的一切都告诉了我。$B$B他们证实了我的怀疑。女皇果然不再适合统治帝国。她必须被……荡除。"
D.Strings[54266]="我效命于卡拉克西议会。不管他们要我做什么，我都必须服从。"
D.Strings[54267]="我一点都不认识这个世界了。所有事物都那么陌生，然而还有伟大的使命在等着我。"
D.Strings[54268]="成功了，我就知道行的！$B$B但即便如此，静止的效果还是超过了我原先的计算。"
D.Strings[54269]="放眼整片废土，凯帕圣树正在凋零。$B$B我恐怕……煞……就是这一切的罪魁祸首。"
D.Strings[54270]="远在西南方向，存活着一棵健康的凯帕圣树，但就在此时，女皇的奴隶正在试图毁灭它。"
D.Strings[54271]="如果我们放任凯帕圣树灭绝，这将是巨大的损失。$B$B琥珀即是生命。"
D.Strings[54272]="莱莎还在临产的时候可不行。我们还得等等。"
D.Strings[54273]="这段旅程何曾给过我们选择的机会？"
D.Strings[54274]="这本不该是一项战斗任务。"
D.Strings[54275]="德兹科，这是一件部落的武器。用它来狠狠的教训联盟。"
D.Strings[54276]="联盟也不该照搬你妻子所设想的远景。"
D.Strings[54277]="德兹科，我们必须向西方推进。我们留在这儿很容易受到攻击。"
D.Strings[54278]="感谢你的妻子带领我们来到这里，老朋友，只怪她在这个节骨眼生孩子。"
D.Strings[54279]="我感觉好多了。$B$B我需要再休息一段时间才能完全恢复，不过至少我已经能够参加战斗了。"
D.Strings[54280]="能在附近找到琥珀和鲜肉可真是辛运，唤醒者。$B$B如果都没有的话，我早就把你吃了。"
D.Strings[54281]="我们熊猫人并不崇拜祖先，不过我们尊崇他们传承下来的记忆和智慧。"
D.Strings[54282]="我刚才与你分享的魔古族传说，最早是我曾祖父讲给我听的。"
D.Strings[54283]="尽管你有一些明显的缺点，但我越来越喜欢你了，唤醒者。 我之所为能成为英杰，是因为在战场上勇猛善战。人们说我甚至能骗过死神。我现在就把这个起死回生的本领教给你，让你能在未来的任务中保住性命。"
D.Strings[54284]="有兴趣去抓一些稀有宠物么？"
D.Strings[54285]="你以前见过这么漂亮的兔子么？我能帮你抓一只属于你自己的！"
D.Strings[54286]="这是古老的帝王之路。据说魔古帝国曾经把他们的囚徒带到这里受刑。"
D.Strings[54287]="他们在挖什么？在这之前我从没见过魔古族使用这样的工具和武器。"
D.Strings[54288]="我不认为这些魔古来自这里。看起来他们像是在收集这些古老的圣物，而不是在埋藏或者掠夺它们。"
D.Strings[54289]="什么事？我忙着呢。"
D.Strings[54290]="这些够了么？"
D.Strings[54291]="把它和其他的放在一起，以便复国领主前来检查。"
D.Strings[54292]="可是，我是一个战斗大师，对这个世界的植物和动物都有着丰富的知识。我的这身本事难道帮不上忙吗？"
D.Strings[54293]="不——自己的问题，自己解决。"
D.Strings[54294]="但是，又来了一个幸存者。 看起来他们身体很健康……或许你可以教授他们一些战斗技巧？"
D.Strings[54295]="当然可以！这是我的荣幸。"
D.Strings[54296]="是从……墙那边传来的。"
D.Strings[54297]="我知道是从哪儿传来的，可那到底是什么？"
D.Strings[54298]="你们会成为出色的帝国奴隶。"
D.Strings[54299]="弟兄们！拿起武器！"
D.Strings[54300]="你们三个！去前面协助橡盾队长！"
D.Strings[54301]="绿耕！黑土！掩护我们的左侧！我可不想遭到偷袭！"
D.Strings[54302]="莱文，你去右侧！靠你自己了！"
D.Strings[54303]="其他人！如果你们拿得动武器，就去保护村庄！别让他们越过防线！你们……"
D.Strings[54304]="你们这些劣等种族马上就会明白谁才是你们真正的主人。"
D.Strings[54305]="你们将会了解自己的处境。"
D.Strings[54306]="我们毫无机会……"
D.Strings[54307]="所有人，退后！退……"
D.Strings[54308]="你觉得自己能挑战魔古的力量？"
D.Strings[54309]="何必管我们是谁？我们是来帮你的。"
D.Strings[54310]="嘿！给我一把干草叉！"
D.Strings[54311]="你投降了？为什么？因为这群入侵者能摧毁一道长城？别忘了你还有另一道长城…是由那些管这里叫做家的人…比肩铸成的。"
D.Strings[54312]="别忘了你还有另一道长城…是由那些管这里叫做家的人…比肩铸成的。"
D.Strings[54313]="我们任何人都甘愿放弃生命，以守护这片土地。"
D.Strings[54314]="这片土地属于我们……"
D.Strings[54315]="属于我们的祖先……"
D.Strings[54316]="属于我们的子孙。"
D.Strings[54317]="这决不会被改变。"
D.Strings[54318]="我只是随处走走，记录一些秘蓝岛当地的野生生物，突然……\n\n砰的一声！<墨乔用手比划着爆炸的样子。>\n\n我认为那是我有生以来听到过的最响的爆炸声！"
D.Strings[54319]="帝国再次崛起了！"
D.Strings[54320]="为了帝国！"
D.Strings[54321]="这片土地属于雷电之王。"
D.Strings[54322]="你胆敢挑战帝国？"
D.Strings[54323]="我们回来了！"
D.Strings[54324]="现在没有熊猫人来救你们了。"
D.Strings[54325]="你们主宰世界的时代已经过去了。"
D.Strings[54326]="为了复国领主！"
D.Strings[54327]="在我面前颤抖吧，懦夫！"
D.Strings[54328]="乞哀告怜吧。"
D.Strings[54329]="你们胆敢阻碍我们？"
D.Strings[54330]="你们注定将成为奴仆。"
D.Strings[54331]="感受新帝国的愤怒吧！"
D.Strings[54332]="嗞嗞！英杰！卡拉克西渗透者！"
D.Strings[54333]="守住塔！"
D.Strings[54334]="自寻死路，入侵者！"
D.Strings[54335]="偷信号的贼！这是女皇的塔！"
D.Strings[54336]="我很希望能了解你的先祖，陌生人。点燃那束香，让我们一起回想你的故乡，怎么样？"
D.Strings[54337]="真令人震惊！世代都是伟大的战士……来自全然不同的世界！熊猫人很少会离开自己的家园。你真该为自己的身份感到骄傲。"
D.Strings[54338]="真不可思议。你们看上去病怏怏的——现在我知道了真相。你们遭受着可怕黑暗的侵袭，但却奋勇向前，多么强大的力量！"
D.Strings[54339]="看哪。你们的族人也崇敬先祖，珍爱土地。我们的共同点真多！啊，可你们的先祖是游牧民，而我们熊猫人则喜欢待在温暖舒适的家里。很少有人外出远行。"
D.Strings[54340]="噢——果然不出所料。你们的祖先诞生于世界起源之日；强大的巨魔帝国盛极一时。你的眼中闪烁着复兴的火花和强大的意志，不是吗？"
D.Strings[54341]="啊，你身世高贵！然而可怕的重担总是随着强大的力量而来；力量无穷，则痛苦无尽。现在我明白为什么你们自称为“血”精灵了。"
D.Strings[54342]="嗯……真有趣。你的大多数祖先都葬身于烈火。天哪。你的族人为了进步，不惜以身犯险！真希望有更多熊猫人具备这种觉悟。"
D.Strings[54343]="啊，你的过往似曾相识！我承认，我曾以为你的家乡迷踪岛只是个传说。岛上的熊猫人比大陆上的更爱冒险……冒险的精神流淌在你们血液中！"
D.Strings[54344]="不！发生了……什么……"
D.Strings[54345]="觅血者斯基尔归来了！啊……"
D.Strings[54346]="是，卡拉克西瓦。议会下达了什么命令？斯基尔倾听。斯基尔服从。"
D.Strings[54347]="我……啊……噢！我……？眼睛……好……模糊。"
D.Strings[54348]="我必须走了。"
D.Strings[54349]="我不能再让水变浑了。你……你愿意帮忙吗？"
D.Strings[54350]="|TInterface\\Icons\\spell_nature_healingwavelesser.blp:20|t加拉隆|cFFFF0000|Hspell:123495|h[治疗]|h|r他的一条腿！"
D.Strings[54351]="蠢货！卖力点！别让这些弱小的熊猫人打败你！"
D.Strings[54352]="|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆准备|cFFFF0000|Hspell:122774|h[重碾]|h|r他的对手！"
D.Strings[54353]="再抬高一点！ 然后消灭它们！"
D.Strings[54354]="加拉隆的巨型盔甲开始碎裂了！"
D.Strings[54355]="欢迎参加我们首个获得官方批准的格斗赛事，破军比武场！"
D.Strings[54356]="啊……唤醒者，鲜血的气味是否让你重新焕发了活力？"
D.Strings[54357]="懦夫！蠢货！你们根本无法阻挡觅血者！"
D.Strings[54358]="只需要再等一小会，唤醒者！ 他们快要撑不住了！"
D.Strings[54359]="干得好，唤醒者。我会再留一会，满足我刀刃的渴望。你可以告诉其它人我回来了，但我相信我迅捷的双翼会让我赶在你之前飞抵卡拉克西维斯。"
D.Strings[54360]="那就敲响那面铜锣，让这些武僧看看你有多大能耐！……无论用怎样的方法，嘿嘿。"
D.Strings[54361]="聚生虫！肮脏的食粪者！你玷污了我们的洞穴。你休想逃走！"
D.Strings[54362]="怎么了？臣民们都不听我的了？他们还会爱自己的女皇吗？会不会像卡拉克西一样背叛我？"
D.Strings[54363]="他们派你来的？他们不敢！不敢的……"
D.Strings[54364]="你！我骁勇的勇士们会让你为自己的傲慢付出代价。他们一定会保护自己的女皇！"
D.Strings[54365]="臣民们，听我说！你们的女皇受到了外来者的威胁。他们要杀死我……杀死我们所有人！干掉他们！"
D.Strings[54366]="反对女皇的叛乱到此为止了！"
D.Strings[54367]="全潘达利亚都将拜倒在女皇之翼下！"
D.Strings[54368]="女皇……我……让你失望了……"
D.Strings[54369]="这是女皇的命令！"
D.Strings[54370]="我的剑永不落空！"
D.Strings[54371]="天空属于女皇！"
D.Strings[54372]="库尔提克势不可挡！"
D.Strings[54373]="瑟里提克掌控世间元素，将他们的敌人永世囚禁！"
D.Strings[54374]="强大的扎尔提克操纵风之意志！"
D.Strings[54375]="为女皇而死乃是荣耀！"
D.Strings[54376]="女皇之翼拒绝失败！"
D.Strings[54377]="你们要为此等罪行付出代价！"
D.Strings[54378]="你们就是一群懦夫！"
D.Strings[54379]="帮帮我，同胞们！"
D.Strings[54380]="为了生存，你必须战斗。"
D.Strings[54381]="只有弱者才希望和平！"
D.Strings[54382]="我知道的唯一办法是战斗。"
D.Strings[54383]="不可能！ 为什么我的力量如此不济？"
D.Strings[54384]="我要杀死一百个敌人！ 只等我……先喘口气。"
D.Strings[54385]="他们告诫过我刚醒来时很虚弱，可我没想到有这么糟。"
D.Strings[54386]="我会好起来的。$B$B这点小事情和战斗时留下的数千个伤疤相比，不算什么！"
D.Strings[54387]="我认为我们要少说话多战斗。"
D.Strings[54388]="试炼规则很简单。这些活动假人都装有炸弹。只要其中一个爆炸了，你的试炼就算失败。"
D.Strings[54389]="呃，或许你有个技能能让我们的训练课程变得更加有趣。尽你所能，保护寺院的治疗者免受入侵者的攻击。"
D.Strings[54390]="加入试炼的还有几位更……鲁莽的……弟子。想要证明你自己，就别让他们闲下来。"
D.Strings[54391]="我们让这变得更有趣些。"
D.Strings[54392]="希望你的腿脚够利索！"
D.Strings[54393]="漂亮。但这个你能行吗？"
D.Strings[54394]="别想逃出我的手心。"
D.Strings[54395]="女皇陛下……原谅我！"
D.Strings[54396]="长城就是你的坟墓！"
D.Strings[54397]="谁都不是我们的对手！"
D.Strings[54398]="*发出嘲讽的讥笑*"
D.Strings[54399]="我要把你们的尸体从塔上丢下去。"
D.Strings[54400]="我们……无穷无尽！你们……赢不了……"
D.Strings[54401]="封锁大门！堵住出口！消灭这些入侵者！"
D.Strings[54402]="胆敢挑战我帝国的人都只有死路一条！"
D.Strings[54403]="呃……啊……我……败了。"
D.Strings[54404]="品尝失败吧，陌生人！"
D.Strings[54405]="窒息而死！"
D.Strings[54406]="吟唱……对！痛苦地吟唱！"
D.Strings[54407]="你现在要效命于我了！"
D.Strings[54408]="质疑权威的人就是这个下场。"
D.Strings[54409]="力量……我必须有更大的力量！守卫！保护你们的女皇！"
D.Strings[54410]="你卷入了一场必败的战斗。"
D.Strings[54411]="我要处决这些不速之客。"
D.Strings[54412]="更多……更多！我要更多！"
D.Strings[54413]="空中优势。"
D.Strings[54414]="早有预料。"
D.Strings[54415]="你必须消灭这些外来者，女皇！他们来征服你的子民了！"
D.Strings[54416]="啊……真是没用！跪倒在我面前受死吧，肮脏的虫子。你们的种族对我毫无价值。"
D.Strings[54417]="至于你们其余的人，如果有胆量就来找我吧。和其他人一样，你们都将惨叫着死去。"
D.Strings[54418]="死亡或是屈服。你们打败不了我。"
D.Strings[54419]="一切都完了。"
D.Strings[54420]="拥抱你的绝望吧。"
D.Strings[54421]="你们逃不出我的掌心。我……无处……不在……"
D.Strings[54422]="看着自己四分五裂吧。"
D.Strings[54423]="屈服于灵魂深处的黑暗吧。"
D.Strings[54424]="在展现的技巧和力量的首场比试中，我们将要上场的是——最强大的龙龟“刀疤壳”！"
D.Strings[54425]="哎呦，真是一团糟啊！ 快派人通知禅院膳房： 我们今天晚上喝龟汤！"
D.Strings[54426]="现在要出场的是令土地精胆寒的庞然大物，十五英尺的长毛怪物，昆莱山特有的雪山恶兽，乔古鲁！"
D.Strings[54427]="哎哟！ 看来乔古鲁面对这三个杀人机器还没有做好充分的战斗准备！ 说起准备……"
D.Strings[54428]="她来这里结交新朋友……然后放火烧他们！这是潘达利亚最漂亮的小淘气纵火者，流炀！"
D.Strings[54429]="就像蜡烛被掐灭一般！就没有他们三个打败不了的人？"
D.Strings[54430]="刚有人说牦牛攻击了吗？这是斧头大师查干·焰蹄，螳螂高原上游荡的战士！"
D.Strings[54431]="多么激烈的战斗啊！ 我们的斗士干净利索地把查干剁成了一堆碎肉，我们可以准备野牛人烧烤了……"
D.Strings[54432]="如此野蛮恶毒，被赶下晴日峰的就是愤怒和疯狂的猴子武僧驾云者科博！"
D.Strings[54433]="多么血腥而激烈的战斗啊！我们的三位英雄向科博证明了一件事情：破军比武场可不是闹着玩的儿戏。"
D.Strings[54434]="我希望你不介意和我共享气球。我父亲经常告诫我不要和陌生人说话，但你看上去很友善。"
D.Strings[54435]="卓金界美丽吧？我一辈子都生活在这里。"
D.Strings[54436]="我父亲认为对于一个淑女来说，到卓金村城墙外面去太危险了。只有当我们需要去酒坛集采购补给时，他才让我离开。"
D.Strings[54437]="在我看来，我不是很擅长做淑女，我可能更适合做一个你这样的探险者。"
D.Strings[54438]="那些废墟真吓人。它们太古老了……"
D.Strings[54439]="看看那些船！它们从哪而来？"
D.Strings[54440]="哦不！看看那些小屋！ 他们为什么要攻击手无寸铁的村民？"
D.Strings[54441]="我的村庄在受到攻击！我希望家人都安好。"
D.Strings[54442]="看起来我父亲也错了。即使是在卓金也会是危险的！"
D.Strings[54443]="我要去看看我的家人。请帮帮我们！"
D.Strings[54444]="弓箭手！把那些飞行螳螂妖射下来！"
D.Strings[54445]="弯弓射箭，攻击那些飞虫！"
D.Strings[54446]="把油准备好……泼出去！"
D.Strings[54447]="把油倒下去！"
D.Strings[54448]="用火炮把自己发射出去！"
D.Strings[54449]="他的护甲破了。趁现在攻击他！"
D.Strings[54450]="自求多福吧，入侵者。我——刀锋领主塔亚克，将是你们的对手。"
D.Strings[54451]="完美的一击。"
D.Strings[54452]="这就是刀锋领主的绝技。"
D.Strings[54453]="刀锋啜饮鲜血的声音如此美妙，如此令我着迷。可这声音竟来自于我的身体，真是讽刺。"
D.Strings[54454]="谁胆敢召唤我蒙恩，至高无上的君王？！"
D.Strings[54455]="你犯下了欺君之罪，处以死刑！"
D.Strings[54456]="我……我不想死！"
D.Strings[54457]="被处决的……本该……是你……"
D.Strings[54458]="如同刀下蝼蚁，统统倒在我脚下吧！"
D.Strings[54459]="谁都不能违抗蒙恩的至高王权！"
D.Strings[54460]="别把血溅到我身上！肮脏！恶心！"
D.Strings[54461]="自我了断，供我消遣吧！"
D.Strings[54462]="到处都是……敌人！给我杀！杀光他们！"
D.Strings[54463]="我的军队无穷无尽，我的力量无可匹敌。"
D.Strings[54464]="我要粉碎你，让你形神俱亡。"
D.Strings[54465]="活水，杀死他们！"
D.Strings[54466]="我……不会被……打败……"
D.Strings[54467]="我的战术无以伦比。"
D.Strings[54468]="再一次胜利。"
D.Strings[54469]="帝王统御万物！"
D.Strings[54470]="士兵们！粉碎他们的侧翼！"
D.Strings[54471]="侧翼攻击！长驱直入！"
D.Strings[54472]="做强盗和做皇帝一样，都是各取所需！"
D.Strings[54473]="你很快就能看清自己的错误！"
D.Strings[54474]="我……败了。"
D.Strings[54475]="你太慢了！"
D.Strings[54476]="我可真是疾如风，智如神。"
D.Strings[54477]="你毫无半点机会！"
D.Strings[54478]="那都是你的？是我的！"
D.Strings[54479]="没有什么是我得不到的！"
D.Strings[54480]="我感觉到了……勇气。意志。光明。嗯。那可不行。"
D.Strings[54481]="你很快就会明白，为什么我的臣民惧怕暗影！"
D.Strings[54482]="黑暗……将我包围！"
D.Strings[54483]="堕入黑暗吧。"
D.Strings[54484]="暗影将你吞噬。"
D.Strings[54485]="这就是违抗皇帝的下场！"
D.Strings[54486]="黑暗来袭，死亡随之而来。"
D.Strings[54487]="竞技场战斗将在六十秒内结束。"
D.Strings[54488]="你的道路毫无希望。"
D.Strings[54489]="绿队获胜！"
D.Strings[54490]="黄队获胜！"
D.Strings[54491]="平局！不分胜负。"
D.Strings[54492]="等等……那是什么？！那些小屋都是从哪里冒出来的？！"
D.Strings[54493]="而且仓库里到处都是兔妖！"
D.Strings[54494]="你看酿酒厂还着火了。"
D.Strings[54495]="联盟离胜利不远了！"
D.Strings[54496]="部落离胜利不远了！"
D.Strings[54497]="联盟获得了胜利！"
D.Strings[54498]="部落获得了胜利！"
D.Strings[54499]="你的……脑袋……像芜菁……"
D.Strings[54500]="呃……胡萝卜吃多了……"
D.Strings[54501]="天旋地转！"
D.Strings[54502]="阿拉希盆地的战斗即将打响。"
D.Strings[54503]="新乌克上任派对现在开始！"
D.Strings[54504]="你啊我啊，屁股扭起来！"
D.Strings[54505]="使劲地扭！"
D.Strings[54506]="奔放地扭！"
D.Strings[54507]="欢快地扭！"
D.Strings[54508]="玩命地扭！"
D.Strings[54509]="扭啊扭！"
D.Strings[54510]="尽情摇摆！"
D.Strings[54511]="所有猢狲都听好了……"
D.Strings[54512]="镇上出了位新乌克……"
D.Strings[54513]="让我们端起风暴啤酒……"
D.Strings[54514]="尽情狂欢吧！"
D.Strings[54515]="让我们以猢狲的方式取乐！"
D.Strings[54516]="猢狲潮流永向前！"
D.Strings[54517]="猢狲好友遍天下！"
D.Strings[54518]="猢狲敌人死光光！"
D.Strings[54519]="又是那舞姿！"
D.Strings[54520]="舞动了我的心！"
D.Strings[54521]="迷醉在那舞步里！"
D.Strings[54522]="使劲摇摆！"
D.Strings[54523]="吉尔尼斯的战斗即将打响。"
D.Strings[54524]="碎银矿脉的战斗即将开始。"
D.Strings[54525]="那是啥……他们……在对我们的酒灵做什么？"
D.Strings[54526]="嘿……说你呢！那些是我们的飞行……啤酒怪？"
D.Strings[54527]="这视野太差了！"
D.Strings[54528]="怎么，你看不见战斗吗？"
D.Strings[54529]="不，我看得太清楚了！"
D.Strings[54530]="这组真差劲！"
D.Strings[54531]="恶心！"
D.Strings[54532]="明天还在这儿见？"
D.Strings[54533]="你这蠢货，整场对决你都在睡觉！"
D.Strings[54534]="谁蠢货？看的人才蠢！"
D.Strings[54535]="这组总算像样点了！"
D.Strings[54536]="那我们是不是可以不用来了？"
D.Strings[54537]="你觉得这组选手能从这场战斗学到什么吗？"
D.Strings[54538]="是的，这会让他们发奋读书！"
D.Strings[54539]="联盟夺取了旗帜！"
D.Strings[54540]="部落夺取了旗帜！"
D.Strings[54541]="给钱，他们没受那些酒灵的影响！"
D.Strings[54542]="给下一组双倍加注？"
D.Strings[54543]="我喜欢上一组！"
D.Strings[54544]="你为啥喜欢那组？"
D.Strings[54545]="我以为那是最后一组！"
D.Strings[54546]="我想我得再喝一杯！"
D.Strings[54547]="为什么这么说？"
D.Strings[54548]="我开始喜欢这些家伙了！"
D.Strings[54549]="你觉得我们死后还能复活吗？"
D.Strings[54550]="当然！上一组复活了差不多三十次！"
D.Strings[54551]="好，明天还是在这儿见！"
D.Strings[54552]="除非我走运，昏过去了！"
D.Strings[54553]="你——你在这里干什么？！走——走开！"
D.Strings[54554]="你知道这组好在哪里吗？"
D.Strings[54555]="他们把门打开了，我们能逃走了！"
D.Strings[54556]="我刚想说这是个烂组，好事就来了！"
D.Strings[54557]="寇魔古寺的战斗即将开始。"
D.Strings[54558]="他们退了！"
D.Strings[54559]="噢，这组又把我带回去了。"
D.Strings[54560]="如果你还看得见的话，也没回去多远！"
D.Strings[54561]="这些家伙也没多糟嘛！"
D.Strings[54562]="可也没多好！"
D.Strings[54563]="对——对不起！"
D.Strings[54564]="这都是你的错！"
D.Strings[54565]="别靠近我！"
D.Strings[54566]="我要躲起来，直到你们离开！"
D.Strings[54567]="我再也不想看见你了！"
D.Strings[54568]="我觉得这组会随着年龄的增长而进步！"
D.Strings[54569]="你觉得他们会变强？"
D.Strings[54570]="不，是我的视力会退化！"
D.Strings[54571]="我在想这个治疗有没有弱点！"
D.Strings[54572]="当然有！不会选队友！"
D.Strings[54573]="我们见过那些猢狲，一定有什么地方不对劲！"
D.Strings[54574]="因为这些家伙竟让它过去了！"
D.Strings[54575]="知道吗，我由衷地妒忌这些家伙！"
D.Strings[54576]="因为他们能在那个妩媚的灵魂医者身边待那么久！"
D.Strings[54577]="我觉得，这些家伙永远别想凑齐套装！"
D.Strings[54578]="他们的黑手总摸不出裤子！"
D.Strings[54579]="这些家伙是联盟还是部落？"
D.Strings[54580]="我总得知道该停止给哪边加油吧！"
D.Strings[54581]="我觉得那个德鲁伊喜欢我！不是你，是我。"
D.Strings[54582]="我对最后那个牧师一见钟情！"
D.Strings[54583]="那法师干吗不给自己的武器加智力？"
D.Strings[54584]="因为他不想让武器变得比他聪明！"
D.Strings[54585]="需要多少泥巴，才能涂满一面墙？"
D.Strings[54586]="我不知道，要多少？"
D.Strings[54587]="得看你用大力气扔泥巴！"
D.Strings[54588]="你认为那组亡灵全身而退了吗？"
D.Strings[54589]="不，我觉得他们没这胆！"
D.Strings[54590]="那圣骑给我来了个永久的拯救祝福！"
D.Strings[54591]="你怎么说？"
D.Strings[54592]="王者，谢谢。"
D.Strings[54593]="刚才那个萨满祭司站位不错！"
D.Strings[54594]="他应该站哪儿？"
D.Strings[54595]="外域！"
D.Strings[54596]="我这有个好玩的笑话！"
D.Strings[54597]="他们的烂武器！"
D.Strings[54598]="我听见了什么声音……"
D.Strings[54599]="真可惜……"
D.Strings[54600]="连尸体也别放过！"
D.Strings[54601]="烧光一切。血色十字军的耻辱不得外泄！"
D.Strings[54602]="你，也将化为灰烬！"
D.Strings[54603]="我的火焰……熄灭了……"
D.Strings[54604]="燃烧吧！燃烧吧！"
D.Strings[54605]="在烈焰中消亡吧！"
D.Strings[54606]="巨龙之息！"
D.Strings[54607]="让你们也尝尝我无尽的痛苦！"
D.Strings[54608]="一切……终于……结束了吗？"
D.Strings[54609]="找一个容器……然后重返人世！"
D.Strings[54610]="夺取一具肉身，然后复仇！"
D.Strings[54611]="不……这水……我必须……坚持住……我不会……害怕……"
D.Strings[54612]="你不属于这里！我必须保护水流……我要驱逐你，要不就杀死你！"
D.Strings[54613]="保护……水流……"
D.Strings[54614]="谢谢你，陌生人。我自由了。"
D.Strings[54615]="在黑暗中死去吧。"
D.Strings[54616]="黑夜将你包围……"
D.Strings[54617]="原谅我！"
D.Strings[54618]="首先，你们的村庄需要休息。我们会一直提供保护，直到他们休息好为止。"
D.Strings[54619]="我们唯一的要求，就是请你们帮忙寻找先知克哈祖尔。你们对这周围的岛屿更加熟悉。你们的知识是无比宝贵的。"
D.Strings[54620]="震慑灵魂的……恐惧！"
D.Strings[54621]="快逃……不然就死！"
D.Strings[54622]="承诺，承诺！你无论如何也救不了我们了。赞达拉残忍至极！"
D.Strings[54623]="即便我们能保护自己，也是寡不敌众！我们绝对赢不了！"
D.Strings[54624]="日落月升……"
D.Strings[54625]="黑暗滋长……"
D.Strings[54626]="光明消退……"
D.Strings[54627]="黑夜…变成白昼！"
D.Strings[54628]="阳光……照耀……"
D.Strings[54629]="再度……黎明……"
D.Strings[54630]="你总是那么消极啊，侯！"
D.Strings[54631]="那也许不是真的，侯。游学者似乎很有信心。你的保护要让我们付出什么代价？"
D.Strings[54632]="非常好。如果你能帮我们击退赞达拉，我们就告诉你该怎样找到先知。"
D.Strings[54633]="我要粉碎你。"
D.Strings[54634]="我不会被打败。我不可战胜。"
D.Strings[54635]="我的双拳沾满了……你的鲜血！"
D.Strings[54636]="要是你死了，就结束了。"
D.Strings[54637]="战技绝伦！"
D.Strings[54638]="可是……我的传说！"
D.Strings[54639]="我就是传说！"
D.Strings[54640]="你们大老远来到这里，就为了送死。我会让你们死得很干脆。"
D.Strings[54641]="你心中的光明将会寂灭。黑暗会笼罩你。潜伏其中的阴影会令你胆寒。"
D.Strings[54642]="你会知道什么是恐惧！"
D.Strings[54643]="淹溺在恐惧中吧。"
D.Strings[54644]="逃跑吧！"
D.Strings[54645]="在恐惧中颤抖！"
D.Strings[54646]="你以为这么容易就能战胜内心的恐惧吗？"
D.Strings[54647]="恐惧升腾！它循光而去。它在渴望。"
D.Strings[54648]="你打算怎么帮我们，游学者？"
D.Strings[54649]="为了格尔桑的荣耀！"
D.Strings[54650]="见识哈飒克的力量吧！"
D.Strings[54651]="为了克尔格西！"
D.Strings[54652]="死亡时间到！"
D.Strings[54653]="噢吼吼！那可真疼。"
D.Strings[54654]="嘿！呃呵呵呵呵。"
D.Strings[54655]="赞美灵魂！"
D.Strings[54656]="恐惧攫住了我的心神。我……无力抵抗。"
D.Strings[54657]="你面对自己的恐惧。迎接片刻的……安宁。"
D.Strings[54658]="我带的炸弹足够……炸飞你们！"
D.Strings[54659]="快躲起来吧，以免我奉煞魔之命，将你们赶尽杀绝！"
D.Strings[54660]="我……搞砸了……"
D.Strings[54661]="它的力量如此强大。它要我消灭你。"
D.Strings[54662]="我是炸弹……螳螂！"
D.Strings[54663]="你搞砸了！"
D.Strings[54664]="没人能对抗恐惧。你必将消亡。"
D.Strings[54665]="我可不会留情面！"
D.Strings[54666]="你还得练练！"
D.Strings[54667]="武艺不精。"
D.Strings[54668]="你们休想再封印我。影踪派阻止不了我。你们也不行！"
D.Strings[54669]="只要你们心中的暴虐不除……我……就会……回来的……"
D.Strings[54670]="又一次暴虐的死亡……"
D.Strings[54671]="恨之煞离开了我的身体……也离开了禅院。我必须要谢谢你，陌生人。影踪派欠你个人情。现在，还有很多事情要做……"
D.Strings[54672]="祝踏岚和影踪派是我的。快过来受死吧，跟我作对的人都不会有好下场！"
D.Strings[54673]="仇恨将吞噬一切，征服一切！"
D.Strings[54674]="为你的失败而愤怒吧。"
D.Strings[54675]="你的仇恨滋养了我！"
D.Strings[54676]="如果你不是来学习的，我就会把你当成教材。"
D.Strings[54677]="我会完成帕瓦拉克做不到的事！"
D.Strings[54678]="尽管你们从我的大军中杀出一条血路，来到了这里，但是……我会杀了你们，我会把桥造起来。"
D.Strings[54679]="架……桥……"
D.Strings[54680]="回去工作！这桥必须在曙光初露时完成！"
D.Strings[54681]="尖叫和犬吠声回响在大厅里。"
D.Strings[54682]="在岛上搜索美酒，添加到珀的大锅里，但要留人在附近保护珀！"
D.Strings[54683]="狠狠地打！"
D.Strings[54684]="无毛怪打死了大乌克门？！"
D.Strings[54685]="蠢蛋要被揍扁了！"
D.Strings[54686]="使劲打！"
D.Strings[54687]="蠢蛋是猢狲的大克星！"
D.Strings[54688]="你好，陌生人！你给那些猢狲留下了很深的印象。我敢说他们已经开始害怕你了。"
D.Strings[54689]="天呐——一个活的巨魔！你跟故事里讲的完全一样。你已经狠狠教训过那些猢狲了。"
D.Strings[54690]="%s发怒了！！"
D.Strings[54691]="你肯定是从那艘坠毁的飞船上下来的。我有很多问题要问你，但这不是聊天的地方。"
D.Strings[54692]="等你有空的时候，请到这座山上的千言洞来找我！"
D.Strings[54693]="<画出性感的图案。>"
D.Strings[54694]="<画出抽象的图案。>"
D.Strings[54695]="<画出英雄的图案。>"
D.Strings[54696]="啊！呵呵--现在我知道你们联盟为何而战了。"
D.Strings[54697]="当然我不介意你们多喂我的鸟儿一点肉，但我开始发现你们和熊猫人之间也并没有太大的差异嘛。"
D.Strings[54698]="让我们来看看……成片的红色和蓝色，在绿色的土地上剧烈碰撞。"
D.Strings[54699]="这意味着什么？我听到了你心中的忐忑，我的新朋友。"
D.Strings[54700]="我明白了——联盟伟大将士中的一员，是吗？你们选择雄狮作为徽记。"
D.Strings[54701]="你们的人民勇敢而强悍。但请记住，雄狮只在饥饿时才会杀戮。"
D.Strings[54702]="它们都在这儿，是的，就这样。你看，在这儿交朋友是不是很简单？"
D.Strings[54703]="请记住，在潘达利亚，不是所有的盟友都必须用刀剑来赢得的。"
D.Strings[54704]="好吧……我的鸟儿可喜欢你了。我听它们的。"
D.Strings[54705]="欢迎你，我来自联盟的新朋友！能为你效劳吗？"
D.Strings[54706]="太迟了！雷电之王将会崛起，从你手上夺取这片土地。"
D.Strings[54707]="雷电之王的遗骸哪儿去了？！"
D.Strings[54708]="野牛人太强大了……也许我们需要寻求你族人的庇护。"
D.Strings[54709]="我的家园……不知还在不在。我要回去看看！"
D.Strings[54710]="我……我差点就去见死神了！"
D.Strings[54711]="一个外来者……救了我？"
D.Strings[54712]="我还……活着？我还活着！我还活着！"
D.Strings[54713]="你的翔龙不能离开百木园！马上回百木园去！"
D.Strings[54714]="为了女皇！"
D.Strings[54715]="砮皂必亡！"
D.Strings[54716]="寺庙是我们的！"
D.Strings[54717]="真是蠢货，竟敢违抗女皇！"
D.Strings[54718]="潘达利亚的子民都要臣服于女皇陛下！"
D.Strings[54719]="你快要超出训练场地了！返回百木园或玉塔海，否则就要被甩下去了！"
D.Strings[54720]="皇家宰相佐尔洛克吸入狂热信息素！"
D.Strings[54721]="你做好在猛虎之眼展示武艺的准备了吗？"
D.Strings[54722]="准备好再次战斗了？敲响那面锣！即刻开始！"
D.Strings[54723]="摧毁寺庙！"
D.Strings[54724]="让他们瞧瞧她的力量！"
D.Strings[54725]="猢狲杀手！快跑！"
D.Strings[54726]="跑啊！是该死的猢狲杀手！"
D.Strings[54727]="不能让你回去。$B$B他们还在里面战斗。"
D.Strings[54728]="战斗结束。$B$B做好回到里面去的准备了吗？"
D.Strings[54729]="进入竞技场。"
D.Strings[54730]="杀千刀的猢狲杀手！"
D.Strings[54731]="谢谢，我的孩子们。"
D.Strings[54732]="我的头脑清醒了。谢谢你，$r。"
D.Strings[54733]="你休想击垮我们，煞！"
D.Strings[54734]="滚开，疑惧的爪牙！"
D.Strings[54735]="我们要把你逐出这片土地！"
D.Strings[54736]="很高兴能有一位$c与我们并肩作战！"
D.Strings[54737]="回到大地中去吧！"
D.Strings[54738]="你想成为“闷水壶”的船员？那你恐怕得像其他人那样，从头做起。"
D.Strings[54739]="锦鱼人爱好者！"
D.Strings[54740]="这般武器。必须归我！"
D.Strings[54741]="多么闪亮的护甲。快把它给我！"
D.Strings[54742]="流血吧……"
D.Strings[54743]="投降吧，温热的鲜血！"
D.Strings[54744]="你们的武器软弱无力！"
D.Strings[54745]="酒桶炸弹变得不稳定了！"
D.Strings[54746]="|TInterface\\Icons\\warrior_talent_icon_thunderstruck.blp:20|t加拉隆飞上高空，准备发起|cFFFF0000|Hspell:128555|h[重碾]|h|r！"
D.Strings[54747]="[PH——假装这里有一个完美的过场动画。]砰！你赶跑了那群野牛人！哦伙计，他们跑掉了！"
D.Strings[54748]="[PH]林正在追赶他们。哦不！林！"
D.Strings[54749]="[PH]野蛮的野牛人首领出现了（从大门另一侧），对你怒吼着。你最好准备和首领进行战斗！"
D.Strings[54750]="你不介意吧？我们打算在这里拍张照片。"
D.Strings[54751]="我等不及要把这张照片寄给我家乡的女朋友了。她肯定会抓狂的！"
D.Strings[54752]="让我们瞧瞧这里……$B$B“找到合适的光圈值。光圈值等于焦距除以‘有效光圈孔径’。”$B$B这可真让我头疼。"
D.Strings[54753]="幸亏我们上一季发了笔小财，我才能邮购到这台新式相机！"
D.Strings[54754]="我现在正在潜心提高自己的摄影技术。"
D.Strings[54755]="你能快点儿吗？我手臂都酸了！"
D.Strings[54756]="赶紧按下快门就是了！"
D.Strings[54757]="再等一秒！艺术是催不出来的！"
D.Strings[54758]="“……调焦至超焦距可确保取得从该距离的一半至无限距离的最大清晰度……”"
D.Strings[54759]="嘿，那你觉得你现在的“超焦距”是什么？"
D.Strings[54760]="我准备好出发了。走吧！"
D.Strings[54761]="装填！"
D.Strings[54762]="天哪，那是什么？"
D.Strings[54763]="我从没见过那样的东西。"
D.Strings[54764]="你是来看青龙的吗？"
D.Strings[54765]="哇哦……这么多武器。"
D.Strings[54766]="那是某种土地精吗？"
D.Strings[54767]="那……那是巨魔吗？故事书里的那种？"
D.Strings[54768]="你这身打扮可真奇怪。"
D.Strings[54769]="你看起来……与众不同。"
D.Strings[54770]="你是从昆莱来的吗？"
D.Strings[54771]="你是从龟背上来的吗？"
D.Strings[54772]="你需要多少武器？"
D.Strings[54773]="好了，我们去禅院吧。"
D.Strings[54774]="他在那边干什么呢？"
D.Strings[54775]="别理外面那两个白痴——他们患上“鲨鱼狂热综合症”了。$B$B我敢打赌，他们对那照片的新鲜劲持续不了几个月。"
D.Strings[54776]="这简直酷毙了！"
D.Strings[54777]="你来得正是时候，唤醒者。副官想趁我熟睡时消灭我。"
D.Strings[54778]="哪怕是在睡梦中，我都能听见他们的黑暗思想……她的黑暗思想。"
D.Strings[54779]="再等一分钟鲨鱼就给你用，还没轮到你呢！"
D.Strings[54780]="我们可以用气球。跟我来！"
D.Strings[54781]="女皇惧怕自己的灭亡，而惧怕本身就会为她招致灭亡。她已经超出了疯狂的底线。"
D.Strings[54782]="我们要严惩女皇犯下的重罪。别浪费时间了，唤醒者。到外面找我。"
D.Strings[54783]="长者，谢谢你们。我们一定不负所望。"
D.Strings[54784]="你似乎能帮我们赚点钱。$B$B来破军比武场转转怎么样，伙计？"
D.Strings[54785]="让他们畏惧赞达拉！"
D.Strings[54786]="享用他们的血肉吧，宠物们！"
D.Strings[54787]="这些入侵者何时才能停下来？！"
D.Strings[54788]="他们的凶残似乎永无休止。"
D.Strings[54789]="我觉得自己仿佛已经在这待了好多天了……"
D.Strings[54790]="还没等这村子陷落，我就要死了！"
D.Strings[54791]="我来替你站岗。去休息下，陪陪家人吧。"
D.Strings[54792]="你看起来精疲力尽。去休息下，为接下来的战斗做好准备。"
D.Strings[54793]="嘿，你好啊，$r。游学者周卓把你的事都告诉我了，至少是重要的部分。可这附近的人对你还不太了解，所以你最好先赢得他们的好感。"
D.Strings[54794]="又来了个陌生人？你爱品酒吗？要是你有兴趣，不妨尝尝金酿特饮！"
D.Strings[54795]="那么，陌生人，你是狂野疯狂如猢狲呢？$b$b还是安静深沉如锦鱼人？"
D.Strings[54796]="你是来自长城的另一边吗？"
D.Strings[54797]="你是从哪来的？"
D.Strings[54798]="哇哦，你看起来……嗯……那个……跟我想的不太一样。你还有同类吗？"
D.Strings[54799]="你衣服的颜色真有趣啊。是你自己做的吗？"
D.Strings[54800]="你还有同类吗？"
D.Strings[54801]="噢，你好啊陌生人。你看上去像是个经历丰富的家伙。"
D.Strings[54802]="你下巴的轮廓真迷人。衣着又如此鲜艳。你是打哪儿来的？"
D.Strings[54803]="嗯。什么护甲……"
D.Strings[54804]="有个陌生人？快瞧瞧。我很好奇他是从哪儿来的。"
D.Strings[54805]="真是个陌生又古怪的生物。你是带着和平的意图到我村子里来的吗？"
D.Strings[54806]="又一个陌生人？还长得……那么奇怪。"
D.Strings[54807]="可怜的小东西。骨瘦如柴……一定饿坏了。"
D.Strings[54808]="这就是周卓提到的那位陌生人。不知是否就他一个。"
D.Strings[54809]="欢迎你，陌生人。我好久没见到新面孔途径此地了。"
D.Strings[54810]="能告诉我你来自哪里吗？某个美酒欠奉的地方？嗯？"
D.Strings[54811]="有个陌生人？在这儿？别在我们的村子里惹麻烦。"
D.Strings[54812]="你的家族有多大？"
D.Strings[54813]="你见过西边的那道长城吗？"
D.Strings[54814]="你是一位斗士吗？你能不能教教我怎样战斗？"
D.Strings[54815]="我敢打赌，我爸爸绝对能揍你一顿。他是最棒的武僧。"
D.Strings[54816]="你怎么那么瘦啊？"
D.Strings[54817]="你这身装束可真滑稽。"
D.Strings[54818]="是谁把你全身的毛都给剃光了？"
D.Strings[54819]="你是土地精吗？你的背包呢？"
D.Strings[54820]="你是野牛人吗？我听说野牛人坏得很。"
D.Strings[54821]="你怎么粉嘟嘟的，还不长毛？"
D.Strings[54822]="你有柔软的耳朵！"
D.Strings[54823]="你的耳朵怎么软趴趴的？"
D.Strings[54824]="你的脸看起来很生气。"
D.Strings[54825]="你的背包遭逢不测了吗，土地精？"
D.Strings[54826]="你可真绿啊。你病了吗？"
D.Strings[54827]="你是魔古族吗？"
D.Strings[54828]="你走路的样子真像魔古族！"
D.Strings[54829]="你是巨魔吗？！我听说巨魔都很邪恶。"
D.Strings[54830]="你是巨魔吗？故事书里的那种？"
D.Strings[54831]="我要出发了。我们到另一边再见…但愿如此。"
D.Strings[54832]="|TInterface\\Icons\\ability_warlock_everlastingaffliction.blp:20|t%s受到了|cFFFF0000|Hspell:123011|h[暗影恐怖]|h|r的影响！驱散%s！"
D.Strings[54833]="哈！你要对剑术大师“赤烟”腾武说点儿什么？"
D.Strings[54834]="我们赶快吧？"
D.Strings[54835]="刀锋领主塔亚克把$n标记成了|cFFFF0000|Hspell:122949|h[无影击]|h|r的目标！"
D.Strings[54836]="这痛苦何时才能终结？"
D.Strings[54837]="就连死，都不能不被螃蟹折磨，痛痛快快地死，这世界究竟是怎么了？"
D.Strings[54838]="我还没死呢，你这食腐怪！"
D.Strings[54839]="真是绝配。渔夫被鱼给吃了……"
D.Strings[54840]="那陌生人在这儿！"
D.Strings[54841]="是我先看见的！"
D.Strings[54842]="你是胡子精吗？"
D.Strings[54843]="我几乎和你一样高！"
D.Strings[54844]="谢谢你。你不介意我与你同行，顺便报仇吧？"
D.Strings[54845]="哇哦！我比你高！"
D.Strings[54846]="还有其他土地精也来了吗？"
D.Strings[54847]="周卓说你是个“人类”。那是什么，跟猢狲一样吗？"
D.Strings[54848]="你怎么绿乎乎的？"
D.Strings[54849]="你干嘛要发出好多愤怒的声音？"
D.Strings[54850]="移走那些补给品！"
D.Strings[54851]="朋友，这里是晨芳园！熊猫人在翡翠林的生活中心。要是你想给人留下深刻的印象，相信这里有很多居民在等你帮忙。"
D.Strings[54852]="我先失陪了。托亚正在帮我搜集玉石。等他集齐之后，希望你能帮忙带到皇帝的预言地来交给我，那样我们也许就能知道，历史究竟对我们隐藏了什么秘密。"
D.Strings[54853]="你来得可真是时候。我正准备离开。但请你留下逛逛村庄，托亚正在搜集我们需要的玉石。"
D.Strings[54854]="回头见！"
D.Strings[54855]="我要去玩了。"
D.Strings[54856]="小心那蝎子，他看起来也许很友善，可真打起来简直是头野兽！"
D.Strings[54857]="你在看我的猫？"
D.Strings[54858]="你好啊，钓友！你来这里多久了？我和我的搭档“大钩”山南海北地到处寻找大鱼！$b$b我们偶然来到这里，当地人十分友好，又是给补给品，又是好酒好菜地招待，所以我们打算留下来啦！"
D.Strings[54859]="一直在为钓鱼者效劳？这些奖励是给你的！"
D.Strings[54860]="位于锦绣谷的魔古山宫殿已开放测试。该地下城适合87至89级的玩家。请组满队伍后再传送至地下城。该地下城的集合石尚未开放。\n\n穿过地下城内的常规出口，即可离开魔古山宫殿并被传送回达拉然。如果角色死亡并选择释放灵魂，请从该NPC处传送回去。"
D.Strings[54861]="%s激活了他的|cFFFF0404|Hspell:119311|h[利刃之流]|h|r陷阱！"
D.Strings[54862]="我已组好队伍，准备好被传送到魔古山宫殿了！"
D.Strings[54863]="送我回魔古山宫殿！"
D.Strings[54864]="%s激活了他的|cFFFF0404|Hspell:120142|h[战弩]|h|r陷阱！"
D.Strings[54865]="%s激活了他的|cFFFF0404|Hspell:119374|h[旋风斧]|h|r陷阱！"
D.Strings[54866]="我们必将再次崛起！"
D.Strings[54867]="请带我飞向格尔桑平台。"
D.Strings[54868]="我听闻了你旅行的消息。你乘变幻之风而来。"
D.Strings[54869]="我很好奇，在你的家乡，有和平可言吗？"
D.Strings[54870]="你觉得我们的土地怎么样？你学到什么了吗？"
D.Strings[54871]="打从黑暗时期开始，风裘拳击的武艺就在我的家族里代代相传。$b$b据说这套拳法最早是在魔古帝国的黑暗统治时代被发明的，在熊猫人争取自由的伟业中发挥了不小的作用。"
D.Strings[54872]="你的到来，犹如暴风雨来临前的一阵疾风。"
D.Strings[54873]="我听说你造访了林中的猢狲，并活了下来。看来我们会在今后的日子里发现你身上的特别之处。$b$b欢迎光临寒舍，旅行者。"
D.Strings[54874]="斜风细雨，总好过血风肉雨……明白？我只是开个玩笑。"
D.Strings[54875]="原来就是你让锦鱼人重振勇气，对抗猢狲的。$b$b这般勇气我们已经许久未见了。欢迎光临寒舍。"
D.Strings[54876]="%s施放了|cFFFF0000|Hspell:107140|h[磁力帷幕]|h|r。 集合以释放治疗能量！"
D.Strings[54877]="那么……你就是周卓提到的那位陌生人。$b$b欢迎来到晨芳园！我是佩吉·金酿，我家是潘达利亚一流的酿酒世家。$b$b我们跟那个游酒家族可不一样，他们只会以次充好，到处败坏酒仙的美名。我甚至还发现有个毛小子盯上了我的女儿。真过分！金酿家族决不会沦落到跟游酒家族为伍。"
D.Strings[54878]="我继续去寻找玉石了。你可以四处问问，看有没有人需要帮手。"
D.Strings[54879]="猢狲只给高手起叠名。$b$b也许有一天，他们会管你叫$n$n。"
D.Strings[54880]="快点，长者！你们必须藏起来！"
D.Strings[54881]="我发誓，我看见那个小塞拉·金酿给我们孩子“脸色看”。真受不了。"
D.Strings[54882]="谢天谢地，你来了！快把钓鱼竿扔下来，把我们救出去！"
D.Strings[54883]="科沃克似乎在冬眠中经受住了岁月的考验。"
D.Strings[54884]="要去昆莱？跳到船上来，我载你一程。"
D.Strings[54885]="原来是一位钓鱼爱好者！我从这些当地的渔夫手里弄到了各种装备，要用什么就跟我说！"
D.Strings[54886]="我的研究必须继续下去。"
D.Strings[54887]="不，不，不！我不能停下来。我的变异体必须活下去！"
D.Strings[54888]="唤醒者，我已经在你的手上涂了特殊的混合物。每次你打败敌人，他们的尸体将被注入一种特殊的毒素。观察效果，并利用它们取胜。"
D.Strings[54889]="万物皆有用处，唤醒者，可你必须得杀了它们才能找到！"
D.Strings[54890]="愿琥珀庇护滋养着你，唤醒者。"
D.Strings[54891]="让我的力量成为你的力量。你每次进行破坏性的攻击时，都会相应地偷取对手的生命值。"
D.Strings[54892]="我已经在你的武器上涂了特殊的浆液。把它注入敌人体内。如果注入过多，就会超出他们身体的负荷。"
D.Strings[54893]="来吧，唤醒者。我们去会会敌人。"
D.Strings[54894]="从我入睡以来，已经过去了多少年？这地方，这宫殿，还有我的女皇。一切都变了。"
D.Strings[54895]="这片白色惨雾是邪煞的杰作？我现在终于明白，在我们的文化间蔓延着何种邪恶。必须净化那些受感染者！"
D.Strings[54896]="看看下方那些螳螂妖。女皇这么早就派大军出袭了！这是她心智失常的又一迹象。"
D.Strings[54897]="它们怎么已经开始聚集了？还没到时候啊。"
D.Strings[54898]="在山谷小路上行走的感觉很是诡异。这里的地面也太平了。还那么热。$b$b我想念昆莱。"
D.Strings[54899]="有东西在驱使它们。它们被吓坏了。"
D.Strings[54900]="不论如何，就连我都能感受到荼毒它们心智的邪恶。我们必须终止它们的疯狂！"
D.Strings[54901]="我的睡眠很短暂。我认出了天空之主梅尔加拉克。他曾经是我的兄弟。现在，已经不是了。"
D.Strings[54902]="我的睡眠很短暂。我认出了塔亚克，就在宫殿门前。他是女皇麾下的刀锋勇士。在我的时代，他战无不胜。"
D.Strings[54903]="我的睡眠很短暂。我认出了昂舒克。他现在管自己叫琥珀塑形者。哈！他的本事始终在我之下。"
D.Strings[54904]="我的睡眠很短暂。我认出了佐尔洛克，女皇的传声筒。对她唯命是从的小跟班。"
D.Strings[54905]="我准备好起飞了，夏克里尔。"
D.Strings[54906]="修复遭到科尔里克破坏的地方需要一些时间，但可以完成。"
D.Strings[54907]="你听见从西边传来了微弱的咔嗒声……"
D.Strings[54908]="从远处传来了高音嗡鸣声……"
D.Strings[54909]="宝石粉碎了！"
D.Strings[54910]="你看到沿东墙发出了一道闪光……"
D.Strings[54911]="我在哪能找到助手布扎齐？"
D.Strings[54912]="我还能做些什么吗？"
D.Strings[54913]="蠢蛋挨了一下！"
D.Strings[54914]="蠢货被打中了！"
D.Strings[54915]="被打中了，蠢货！"
D.Strings[54916]="最后一种成分，是我们家族世代相传的秘密，来自于卡桑琅丛林。我几天前派了助手布扎齐去寻找这种成分，收到的消息是他昨天晚上到达了迷雾酒肆。你能前往远古之路去看看是什么让他耽搁了吗？他最好不要在酒馆里睡过了头！"
D.Strings[54917]="放机灵点，伙计！"
D.Strings[54918]="有部落可以杀了，小子们！我闻到了！"
D.Strings[54919]="非生即死，伙计们！无路可退！"
D.Strings[54920]="区区几只猴子，也配跟联盟作对！"
D.Strings[54921]="退下，野蛮人！我以联盟之名宣布对这片土地的占有权！"
D.Strings[54922]="坚持住，兄弟们！援军很快就到！"
D.Strings[54923]="被击中了，蠢——"
D.Strings[54924]="我今天需要你的协助，玛里克。"
D.Strings[54925]="唤醒者，秘诀就如同流水之道。不要与敌人的力量硬碰硬——而是要以柔克刚，让他的重拳擦身而过。这时候，再对他还以颜色。"
D.Strings[54926]="要不要土拨鼠？"
D.Strings[54927]="送我去晨芳园。"
D.Strings[54928]="当我看到那些蜥蜴人时，我慌了，打翻了船。"
D.Strings[54929]="啊！好！你成功了。是时候让这些“海盗”猢狲明白，它们为什么不该袭击我们的村庄。"
D.Strings[54930]="你确定已经准备好出发了？"
D.Strings[54931]="唤醒者，琥珀为英杰提供了喘息之机。如果你濒临死亡，它会自动激活。"
D.Strings[54932]="绝不手软！汲取鲜血之气！你越是攻击，越能获得更多的生命值。"
D.Strings[54933]="看来他只是失去意识了。我应该能把他叫醒。"
D.Strings[54934]="酒仙！在村外发现了巴塔里侦察小队！"
D.Strings[54935]="那是……嘿！你把他们带回来了！"
D.Strings[54936]="是你救了我！你真是大英雄！"
D.Strings[54937]="你是……你是打哪儿来的？谢谢你！"
D.Strings[54938]="这里的空气真干净。"
D.Strings[54939]="我是在迷踪岛上长大的。那里空间有限。没地方让我们狩猎，也没有什么值得一提的凶禽猛兽。$b$b可这里……这里有大块头的穆山兽，有野狼，还有各种各样的食肉动物。这里简直是让猎手美梦成真的乐园。"
D.Strings[54940]="头一次来潘达利亚？我也是。我还记得他们讲述的关于这个地方的故事。真令人兴奋！"
D.Strings[54941]="我最早是在荆棘谷遇见奈辛瓦里的成员的。在那之后，我就陆续跟他们见过几次面。终于在他们的远征队里找到了自己的一席之地！"
D.Strings[54942]="噢！我想我认识你。你是从迷踪岛来的是不？$b$b身处潘达利亚的感觉很奇妙吧？$b$b我一直以为这地方不过是传说罢了。真不敢相信，它竟然真实存在着！"
D.Strings[54943]="这里生机盎然，一望无垠。$b$b迷踪岛上地方狭小，猛兽根本没空间茁壮成长，供猎人捕杀。"
D.Strings[54944]="啊，很好！你找到远征队了。要是没有点旅行天赋，很容易在丛林里迷失方向。$b$b那些魔古族没完没了地妨碍我狩猎。"
D.Strings[54945]="|TInterface\\Icons\\creatureportrait_bubble.blp:20|t%s施放了|cFFFF0000|Hspell:124653|h[水体防护层]|h|r！用水柱破坏它！"
D.Strings[54946]="猎手狩猎。艺术家……则钻研艺术。$b$b我来这里是为了用艺术来表现狩猎的凶残。$b$b我们身处陌生的土地，而且在这世界上也没几个人熟悉我们要猎杀的这种奇怪生物。$b$b通过我的艺术，我能证明你的成功，以及奈辛瓦里远征队的成功。"
D.Strings[54947]="可以出发了。味道像是混合了海草和热垃圾，是吧？"
D.Strings[54948]="欢迎光临北风酒馆。"
D.Strings[54949]="你好啊朋友！想找个房间过夜吗？"
D.Strings[54950]="你能让我不掉进水里吗，塔蒂？"
D.Strings[54951]="我从没想过自己会被迫重拾武器作战……"
D.Strings[54952]="我几乎骗过了自己，相信卓金在这个世界上能免受黑暗的侵袭。"
D.Strings[54953]="我退出战斗，与世无争地和家人温馨度日。但看来战场不肯让我轻易离开啊。"
D.Strings[54954]="我曾经是位骁勇的战士。希望时间没有将我的战斗技能消磨殆尽。"
D.Strings[54955]="要让这村庄做好战斗的准备，不光是把武器交到村民的手里就行了。我们得教会他们，如何满怀信心地驾驭武器。"
D.Strings[54956]="安度因……快跑……"
D.Strings[54957]="又见面了，迷雾之外的陌生人。"
D.Strings[54958]="这场战争代价高昂。就连我也要若干年后才能重生。"
D.Strings[54959]="有所领悟吧！"
D.Strings[54960]="我不知道迷雾为何一分为二，但其中一定有原因。"
D.Strings[54961]="你显然不是要将战争带到这儿来。在潘达利亚潜藏着黑暗——你已经亲眼见到了！"
D.Strings[54962]="但我能肯定你就是迷雾分开的原因。弄清你来这里的意图吧。"
D.Strings[54963]="你能从四风谷了解到许多与这片土地有关的事。"
D.Strings[54964]="还有另一位迷雾之外的访客。叫“陈·风暴烈酒”，是个熊猫人，但却来自不同的故乡。"
D.Strings[54965]="和陈一起在这片土地上走走。跟这里的住民交交朋友。你终究会找到答案的。"
D.Strings[54966]="后会有期。希望我们下次碰面时能成为“朋友”。"
D.Strings[54967]="开炮！击落那些螳螂妖！"
D.Strings[54968]="<灯塔低声嗡鸣着。>"
D.Strings[54969]="它们要吃掉我！"
D.Strings[54970]="把它们从我身边赶走！"
D.Strings[54971]="我不是食物！"
D.Strings[54972]="我需要另一只鲨鱼！"
D.Strings[54973]="有兴趣抓只鲨鱼吗？"
D.Strings[54974]="兔妖把粮食都吃光了！"
D.Strings[54975]="$n，你能帮我解决掉这些兔妖吗？"
D.Strings[54976]="抓住那些兔妖！"
D.Strings[54977]="影踪派竟然让跟班替他们办事？也许山怖搞错了……"
D.Strings[54978]="哈哈！你……已经……失败了……"
D.Strings[54979]="想在战斗中停下来喘口气？那你可来对地方，找对人了。"
D.Strings[54980]="噢……我好像把剑弄丢了。"
D.Strings[54981]="当分裂之力将艾泽拉斯大陆撕扯开来时，我们熊猫人以为世界其它地区都遭到了彻底毁灭。"
D.Strings[54982]="然而在几个世纪之后，有位名叫刘浪的年轻探险家决定出去看看。他开始了对世界的探索……而他骑的竟是一只海龟！"
D.Strings[54983]="我们用雕像和歌谣赞美他的英雄气魄，可如果你在他出海的那天守在岸边——我相信，你会觉得他当时的样子傻得很。"
D.Strings[54984]="噢，那些熊猫人不遗余力地嘲笑他。可是刘浪比人们想象得要聪明。海龟总能回到自己出生的岸边。于是，尽管迷雾笼罩着我们的土地，刘浪总能安然返家。"
D.Strings[54985]="他每隔几年便回来——讲述旅途中的奇遇：沙漠中的神秘城市，无边草原上的游牧民族，寒冰之下的伟大帝国，还有黄金镀成的神奇王国。"
D.Strings[54986]="他每次回来，都有更多的熊猫人响应刘浪的召唤，爬到那日渐拥挤的龟背上，与他同行。他们是勇敢的探险家，是冒险王。"
D.Strings[54987]="那就是刘浪给我们的启示，朋友。人们总爱嘲笑探险家。他们笑啊，笑啊……等他回来就不笑了。"
D.Strings[54988]="于无声之处起波澜。比如说，一个宁静的池塘。水面平滑如镜。"
D.Strings[54989]="直到我丢进一块石子。如此微不足道——但瞬间，涟漪就会袭遍整个水面！"
D.Strings[54990]="锦鱼人也有着卑微的出身。本来只是一种原始生物，但有幸能生长在谷内含有魔法的池塘附近。"
D.Strings[54991]="池塘的魔力滋养着他们的心智、壮大着他们的躯体，把他们变成了潘达利亚最伟大的古老生物之一。"
D.Strings[54992]="锦鱼人中的智者确实非常睿智——他们与河流交流的方式，只有我族的长者才能知晓一二。"
D.Strings[54993]="在水流的低语声中，他们能听见未来。"
D.Strings[54994]="锦鱼人水语者们，在潘达利亚历史上的重要事件中，都扮演着核心角色。"
D.Strings[54995]="他们的真知灼见筑起了帝国，解救了奴隶，还在一万年前艾泽拉斯大分裂来临之前，向末代皇帝发出了警告。"
D.Strings[54996]="想想看——哪怕是最微弱的声音也能改变世界。下次当你决定掷出石子时，考虑一下吧，朋友。"
D.Strings[54997]="噢，我的弟子——你想要了解螳螂妖？我提醒你，边境前线上到处都是我原先弟子的坟冢。"
D.Strings[54998]="螳螂妖是严酷的老师。"
D.Strings[54999]="螳螂妖世代都汇集大军涌上蟠龙脊。它们杀死许多熊猫人，于是我们加倍奉还。可它们的后代又会卷土重来。为何要如此？"
D.Strings[55000]="我们熊猫人不知道。"
D.Strings[55001]="古书上说，螳螂妖一直都在这里。它们甚至比魔古族出现得还要早。它们是哪儿来的？"
D.Strings[55002]="如果你能和螳螂妖交上朋友，赢取了信任，那他们会告诉你螳螂妖的秘密。可我提醒你："
D.Strings[55003]="从来没人和螳螂妖交过朋友。"
D.Strings[55004]="我们熊猫人只知道——螳螂妖屠杀我们的族人，一代又一代地杀害了无数的熊猫人，它们让我们懂得了生命的价值。人生苦短，稍纵即逝，一不留神……灰飞烟灭。"
D.Strings[55005]="这就是螳螂妖教会我们的东西。"
D.Strings[55006]="你在这个世界上最怕什么？你是否能战胜恐惧，还是被恐惧征服？"
D.Strings[55007]="在世界崩裂之前的古老时代，魔古族皇帝统治着潘达利亚。我们的族人被当成奴隶，而且畏惧不已。"
D.Strings[55008]="魔古族是痛苦与折磨的高手，还精于使用黑暗魔法和恐怖武器。任何熊猫人、猢狲和锦鱼人都无力与之对抗。恐惧笼罩着熊猫人。"
D.Strings[55009]="是魔古族建造了蟠龙脊。运气最差的奴隶从事建造和防御工作，充当抵挡螳螂妖的炮灰。我的族人害怕极了。"
D.Strings[55010]="帝国羽翼渐丰，魔古族窥探谷中的秘密，进行实验。他们用活人的血肉和石头造出了可怕的武器。我的族人惶恐不已。"
D.Strings[55011]="而狂妄的魔古族万万没想到，最后推翻它们统治的，并非敌人，而是受压迫的民众。没想到会有一天，奴隶会挺身而起……"
D.Strings[55012]="……并且不再畏惧。"
D.Strings[55013]="火是最有魔力的元素。它能带来温暖，烹制食物。是它把一座房屋变成了一个家。如果善加利用，火能把钢铁铸成刀剑或犁头。但若放任不管，大火也能烧毁整座城市。"
D.Strings[55014]="火是变化的工具。"
D.Strings[55015]="很久以前，一群强健的游牧猎手在世界各处游荡。命运和他们开了个玩笑——在艾泽拉斯大分裂发生时，他们刚好来到潘达利亚。这群游荡者被困在了螳螂高原这片荒芜而危险的土地。"
D.Strings[55016]="那些高尚的猎手想出了自给自足的办法。其中火是关键。他们从地下掘油，用火来温暖房屋，烧饭做菜，烧灼敌人。他们变得强大起来了。"
D.Strings[55017]="命运之火熊熊燃烧，野牛人诞生了。他们定居在长城之外，拒绝臣服于除自己之外的任何律法。"
D.Strings[55018]="命运对野牛人是否不公？这就等于是问火究竟是好还是坏。"
D.Strings[55019]="命运就像火焰——既能塑造我们，也能毁灭我们。"
D.Strings[55020]="关键在于，你如何利用它。"
D.Strings[55021]="啊！你想打听我们最伟大的末代帝王少昊？朋友，我可没时间陪你追溯他一生中的冒险奇遇，可他在万年以前采取的行动，直到今天仍然影响深远。"
D.Strings[55022]="我们知道，他在翡翠林中荡除了自己的疑虑，在卡桑琅丛林里消除了自己的绝望，在螳螂高原上战胜了自己的恐惧，在昆莱山的巅峰击败了自己的愤怒、仇恨和暴力。"
D.Strings[55023]="人们为纪念这些圣地而建造了寺院。"
D.Strings[55024]="但请你想象一下，他归返的那一天，置身于这个山谷中。那一刻，大门为他缓缓开启，我们的皇帝成为了焕发纯净之光的造物——胸中无疑无惧亦无恨……"
D.Strings[55025]="据说，当时山谷中所有的林木都花开满枝，群芳争艳，一直盛开到今天。"
D.Strings[55026]="但愿我们所有人都能像圣祖皇帝那样生活。像他那样卸下肩头的重担，和宇宙相生共存。我相信，这就是在他化归大地，使潘达利亚免受灾变侵袭之前……想要传达给我们的。"
D.Strings[55027]="谢谢你，尊敬的皇帝陛下。"
D.Strings[55028]="有一天，一位父亲厌倦了幼子的顽劣。“你简直像只猢狲！”父亲斥责道。可那孩子还是我行我素。"
D.Strings[55029]="为了教训他，父亲把儿子拽到林子里，让他看看猢狲是如何生活的。“你知道猢狲是什么样了吧？你想像它们那样生活吗？”"
D.Strings[55030]="猢狲很是活泼好动。可那是个短命的种族，很少有猢狲能活过二十岁。它们的领袖也只是十四或十五岁。你十四岁时有多成熟？好好想想吧！"
D.Strings[55031]="然后，父亲问儿子学到了什么。"
D.Strings[55032]="儿子答道：“我学到的是，我们终日在那一亩三分地上劳作，可猢狲却把整个世界当成自己的花园。我们以寥落的烛光照明，可猢狲却能尽享漫天星光。我每天都要上学读书，可猢狲却在实践中掌握本领。”"
D.Strings[55033]="最后儿子总结道，“我还是乐得做只猢狲！”"
D.Strings[55034]="那么是谁更聪明？是父亲，还是儿子？"
D.Strings[55035]="这个问题就要让你自己去回答了。"
D.Strings[55036]="已经很久没人敢挑战我了。"
D.Strings[55037]="竞技场上见。"
D.Strings[55038]="全力以赴。"
D.Strings[55039]="打得很好！再接再厉。"
D.Strings[55040]="白羽？！不——！"
D.Strings[55041]="你……把我……打败了……"
D.Strings[55042]="你可真不简单。能与你并肩战斗是我的荣幸。"
D.Strings[55043]="向你致敬，朋友。我都不记得，上次被别人轻易战胜是什么时候了。"
D.Strings[55044]="砮皂……我们必须得救他！"
D.Strings[55045]="啊哈哈，伟大的砮皂。西方之力。神圣之神。弱者的保护神。"
D.Strings[55046]="你的囚犯，惧之煞，已经跑了。"
D.Strings[55047]="你掌握着神的力量，可你却被打败了！"
D.Strings[55048]="神灵的责任显然太过沉重。"
D.Strings[55049]="卸下你的责任，安息吧。"
D.Strings[55050]="你用双肩苦苦挑起了整个民族的负担。而他们是怎么回报你的呢？"
D.Strings[55051]="你默默地为一群不知感激的人承受着痛苦。"
D.Strings[55052]="我是连续六届投掷美酒大赛的冠军！要是你喜欢，我能让这瓶美酒绕村庄飞上一圈，来个陈酿打击！你要做的只是给我指明目标。要不要试试？"
D.Strings[55053]="当然！那再好不过了！"
D.Strings[55054]="我……绝不……放弃！"
D.Strings[55055]="寒噬主母开始召唤寒噬幼雏。"
D.Strings[55056]="皇家宰相佐尔洛克朝他其中一个平台飞去了！"
D.Strings[55057]="|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t皇家宰相佐尔洛克在整个房间里发送|cFFFF0000|Hspell:122336|h[超声波之环]|h|r！"
D.Strings[55058]="|TInterface\\Icons\\spell_druid_stamedingroar.blp:20|t皇家宰相佐尔洛克深深地|cFFFF0000|Hspell:122852|h[吸气]|h|r！"
D.Strings[55059]="|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|t皇家宰相佐尔洛克对|cFFFF0000$n|r使劲|cFFFF0000|Hspell:122761|h[吐气]|h|r！"
D.Strings[55060]="|TInterface\\Icons\\warrior_disruptingshout.blp:20|t皇家宰相佐尔洛克用|cFFFF0000|Hspell:122713|h[力与魄]|h|r进行呼喊！"
D.Strings[55061]="|TInterface\\Icons\\trade_archaeology_delicatemusicbox.blp:20|t皇家宰相佐尔洛克吟唱了|cFFFF0000|Hspell:123791|h[女皇赞歌]|h|r，对所有玩家造成伤害，直到他们开始和他战斗！"
D.Strings[55062]="|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|t皇家宰相佐尔洛克用他的声音|cFFFF0000|Hspell:122740|h[策反]|h|r团队成员攻击自己的同伴！"
D.Strings[55063]="|TInterface\\Icons\\ability_warrior_bladestorm.blp:20|t风领主梅尔加拉克开始施放|cFFF00000|Hspell:121896|h[回旋之刃]|h|r！"
D.Strings[55064]="这是……？！这不是海图！是一封信。是阿林亲笔写的吗？"
D.Strings[55065]="“亲爱的‘闷水壶’，等你看到这封信的时候，说明你终于鼓起勇气派人来寻找旧海图了。可你来得太迟了。”"
D.Strings[55066]="“我们知道雾海飞跃者并非受雇前往超出长城这么远的地方。我们知道本来只是要在翡翠林海岸上执行日常任务。”"
D.Strings[55067]="“原本只是历时一个礼拜的轻松捕鱼作业，竟然演变成了一场疯狂的灾难，害我们在这片大陆最危险的地方搁浅，差点让所有人都丢掉性命，这一切都是因为你对直觉的执着追寻。”"
D.Strings[55068]="“可我们只想说——谢谢你。”"
D.Strings[55069]="“谢谢你远赴遥远的地平线追逐财宝。谢谢你敢于做梦。最重要的是，谢谢你让我们与你同行。”"
D.Strings[55070]="“我们永远都是你的船员，‘闷水壶’。有船也好，无船也罢。我们都会追随你到天涯海角。”"
D.Strings[55071]="“此致，全体船员——和狗。”"
D.Strings[55072]="哇哦……"
D.Strings[55073]="看那些兔妖再敢吃我！"
D.Strings[55074]="你就当我疯了吧，我简直爱死这温暖的好天气了！我总觉得自己在苔原时像个流浪儿，可我觉得这新气候真是帮了我大忙！"
D.Strings[55075]="你在离家这么远的地方干什么呢？"
D.Strings[55076]="呃，北上变得越发困难了。尽管天灾的麻烦已经得到解决，我们还得不断迁移和觅食。我下定决心，是时候出去寻找新渔场了！$b$b在海上漂流了近一个月之后，我来到了这里。幸好我带了几箱腌鲱鱼，否则途中就要饿肚子了！"
D.Strings[55077]="我潜心苦练了好几年，以掌握真气冲击的要诀，很荣幸能与你并肩战斗。你需要我的协助吗？"
D.Strings[55078]="非常荣幸，全力以赴吧！"
D.Strings[55079]="你被|cFFFF4809|Hspell:116784|h[恐惧之心]|h|r选中了！"
D.Strings[55080]="琥珀凝结后形成了|cFFFF0404|Hspell:125803|h[琥珀陷阱]|h|r！"
D.Strings[55081]="<狗狗疑惑地看着你。>"
D.Strings[55082]="醒醒！我们必须守卫村庄，到炮台那去，帮帮我们！"
D.Strings[55083]="他们好像帮不上什么忙，让他们继续睡吧。"
D.Strings[55084]="%s在温水的出水口间兴奋地游曳着。"
D.Strings[55085]="%s摩挲着雾海飞跃者的船头，低声啜泣着。"
D.Strings[55086]="%s谨慎地环顾四周，然后才在鲸鱼的尸体上留下印记。"
D.Strings[55087]="真是适合垂钓的好日子，你觉得呢？你也是渔夫吗，$n？要是你有兴趣，我这刚好有一种古老的鱼饵，对这片水域里的鱼尤其有吸引力。"
D.Strings[55088]="很好，谢谢。"
D.Strings[55089]="金莲教肩负着守卫锦绣谷的重任。$B$B如果你想帮助我们，就去打败那些目前占据着锦绣谷的敌人吧。$B$B你也可以去残阳关卫戍营的训练场找安济·秋光，获取下一步的任务。"
D.Strings[55090]="卡桑琅的鱼简直凶猛至极！$B$B我本该继续留在海上，跟那大家伙较劲，可我得来这里贩卖今早的收获。有好多饥肠辘辘的人正张嘴等着吃饭呢！"
D.Strings[55091]="你去过四风谷吗？$B$B听说山谷中出现了危机，我们这些阡陌客正努力为这些难民种植食物。$B$B如果你想到乡间走走，请到半山来看我们！"
D.Strings[55092]="你好。我想你不会愿意徒步穿过那条隧道的。蜥蜴人今天在外面集结了军队，那是一支强大的护卫队。"
D.Strings[55093]="生命之火熄灭。"
D.Strings[55094]="曾有的已经消失。"
D.Strings[55095]="反制成功。"
D.Strings[55096]="过来！感受泰坦的力量！"
D.Strings[55097]="抽取备用能量。"
D.Strings[55098]="野牛人！？现在！？"
D.Strings[55099]="让能量吞噬你们！"
D.Strings[55100]="导管断线。"
D.Strings[55101]="在酿出好酒之前，我会全力保护它们的。然后我们就可以用这些酒来对付巴塔里掠夺者！这样一来，其他人就安全了！"
D.Strings[55102]="能量涡流缓降。"
D.Strings[55103]="能量重新定向。"
D.Strings[55104]="能量导管激活，趋向稳定。"
D.Strings[55105]="黑风即将准备登陆！"
D.Strings[55106]="存在终止……开始解体……"
D.Strings[55107]="我是从地精那里得到这个的，他说它可以阻止任何东西靠近，想试一下吗？"
D.Strings[55108]="当然了！我一定要试一试。"
D.Strings[55109]="不必了，你可以留着它，迪嘭先生。"
D.Strings[55110]="我……还活着？谢谢你……太感谢你了！"
D.Strings[55111]="告诉我，$r，你对钓鱼心怀向往吗？$B$B如果答案是肯定的，那你应该去卡桑琅丛林找垂钓翁。"
D.Strings[55112]="我是阡陌客的成员，这个组织是由潘达利亚的辛勤农夫组成的。如果你想对我们有更多的了解，可以到四风谷的半山来找我们。"
D.Strings[55113]="希望这次我们不会再嗝儿个没完了。"
D.Strings[55114]="以前到过昆莱吗？昆莱是个好地方。绵延不绝的农田。巍峨秀美的山脉。而且一点儿危险也没有。"
D.Strings[55115]="额……对。就是有猢狲捣乱。"
D.Strings[55116]="长矛只是吓唬人用的。只要我们待在船上，不跟它们有眼神接触，也不被长矛击中，应该就不会有危险。"
D.Strings[55117]="安全得很。我不久前刚送过游学者周卓和他诡异的同伴们。"
D.Strings[55118]="你又来了。在他跟前摆弄那熏香……等等。这好像有些不对劲。"
D.Strings[55119]="那些是难民吗？那边发生什么事了？我听见的是战斗的声音吗？"
D.Strings[55120]="这些人是农民，不是战士！他们也许需要我们的帮助！"
D.Strings[55121]="对，还有猛虎。"
D.Strings[55122]="猢狲会攻击土地精。"
D.Strings[55123]="猛虎。"
D.Strings[55124]="蜥蜴人危险得很。"
D.Strings[55125]="在远古之路住着许多蜥蜴人。"
D.Strings[55126]="那“兽人”想打我。"
D.Strings[55127]="我的盾牌不见了，我在村子里都找遍了！我希望自己能帮上忙，可没有盾牌，我什么也做不了！"
D.Strings[55128]="……你的盾牌就在你背上。赶紧起来帮帮我们！"
D.Strings[55129]="抱歉，我也没看见。也许这样倒好……"
D.Strings[55130]="哈哈！你找到它了！现在该去抗击野牛人了。"
D.Strings[55131]="这可真令人尴尬。战斗吧！"
D.Strings[55132]="没想到我的盾牌竟然在这儿，无所谓了，战斗吧！"
D.Strings[55133]="雾纱栈道在郭雅夫人的保护之下。"
D.Strings[55134]="在迷雾酒肆里，你会大有收获。"
D.Strings[55135]="迷雾酒肆只为话少的宾客服务。"
D.Strings[55136]="黑风深呼吸了！到他背后去！"
D.Strings[55137]="我听说，你跟我弟弟一起在螳螂高原效力。那小家伙怎么样？他给你讲过他是怎么失去那只眼睛的吗？"
D.Strings[55138]="蜥蜴人阻断了往来这里的交通，只有飞行才能抵达。$b$b当然，也骤然加大了溜进迷雾酒肆的难度。"
D.Strings[55139]="小心我的雄鹰。她会咬人的。"
D.Strings[55140]="山路上可能危机四伏。"
D.Strings[55141]="别问鹰眼大师砮荣他的眼罩是怎么回事。他唠叨起来没完没了。"
D.Strings[55142]="我们得加快速度了，唤醒者。这里并不安全。"
D.Strings[55143]="你的精神很是强大，唤醒者。就连现在，我都在奋力与你交流。想要控制你几乎是不可能的……"
D.Strings[55144]="你的思想吸引着我。你的行动充满目的性。你的复杂程度令人印象深刻。"
D.Strings[55145]="你的心智如同你的战技，迟早会有用武之地。我在你的心神中看到了这样的潜力，唤醒者。"
D.Strings[55146]="好了。有了这把武器，一定能把女皇的军队打得落花流水！"
D.Strings[55147]="我擅长投网，我能网住那些可恶的野牛人。"
D.Strings[55148]="好吧，把他们绑起来！"
D.Strings[55149]="没关系，你继续捣鼓那些网吧。"
D.Strings[55150]="黑风上岸了！"
D.Strings[55151]="我已经掌握了捕鱼的技巧，现在要去捕野牛人了！"
D.Strings[55152]="我和我可靠的渔网一定不会让村庄失望！"
D.Strings[55153]="欢迎来到闻道之座。这里是蕴藏着潘达利亚古代知识与智慧的伟大宝库。"
D.Strings[55154]="你一定是$n。$b$b我一直在等你。"
D.Strings[55155]="我可以乘坐风筝前往古鲁金山。"
D.Strings[55156]="那就来吧。我会亲自动手！"
D.Strings[55157]="我与迷雾同在，疗伤救人。"
D.Strings[55158]="我们需要你的帮助。"
D.Strings[55159]="我们不需要你的治疗技能。"
D.Strings[55160]="我们已经从那好管闲事的游学者身上得到需要的东西了。"
D.Strings[55161]="记住，正是在最黑暗的时刻，光明才格外耀眼。"
D.Strings[55162]="干得好，英雄们。"
D.Strings[55163]="入侵者攻进了寺院！"
D.Strings[55164]="软弱的蜥蜴！我要用你的皮装饰雷电之王的御座！"
D.Strings[55165]="唐骨！我要把你们这些没用的畜生大卸八块！"
D.Strings[55166]="没用的巫师！你竟敢让雷电之王失望！"
D.Strings[55167]="统领容古？！不可能！你现在居然退却了……"
D.Strings[55168]="我，尊贵的雷电之王雷神的使者，烛恒将军，前来向你挑战！"
D.Strings[55169]="容古、唐骨、冯恩、希提斯——用你们的生命……守住神器！"
D.Strings[55170]="我早知道自己有着一颗伐木工的心！"
D.Strings[55171]="我要坐风筝前往珠鳍村。"
D.Strings[55172]="又见面了，$n。我的鱼饵怎么样？"
D.Strings[55173]="又见面了，$n。我的斧子怎么样？"
D.Strings[55174]="下次再见吧，$n。"
D.Strings[55175]="我将永远感激你，我还以为自己死定了。"
D.Strings[55176]="还有那么多精彩的故事等着我们去探寻。那么多历史。难道不使人着迷吗？"
D.Strings[55177]="裘诺：处决他！"
D.Strings[55178]="谢谢！我们都没想到能活下来……我会尽我所能帮助你！"
D.Strings[55179]="他们已经拖走并杀害了其余的人。对不起……我太虚弱了，不能继续了……"
D.Strings[55180]="谢谢你！请你，救救……游学者福云，如果你可以的话……我……失败了……"
D.Strings[55181]="我们已经进入了危险地带，宝贝儿。蜥蜴人在这里变得极为狂暴，会把途径此地的所有船只统统击沉。我们千万要多加小心。"
D.Strings[55182]="烛恒将军准备把寇魔古寺的古代神器交给他的邪恶君主，雷电之王。我们不能让这种情况发生！"
D.Strings[55183]="拜托了，一定不能让它们落入将军的手里！我要返回锦绣谷向金莲报告。再次感谢！"
D.Strings[55184]="<米师满怀期待地望着你。>"
D.Strings[55185]="你的毅力壮大着我们。你的勇气指引着我们。你的荣耀激励着我们。"
D.Strings[55186]="从今天起，你就是我们的同胞手足。"
D.Strings[55187]="我不会让你和这村子失望。"
D.Strings[55188]="我奉命守卫这口井。这是重要的任务！"
D.Strings[55189]="朋友们说我有些慢，可我比他们所有人跑得都快！"
D.Strings[55190]="这口井至关重要。幸好他们派我来看守它。"
D.Strings[55191]="“科亚”，他们说，“去看守水井。”他们就说了这些。"
D.Strings[55192]="大家为什么都这么害怕？我不会让那些巨魔接近我们的水井！我是个合格的守卫！"
D.Strings[55193]="你好！我是科亚！你愿意跟我做朋友吗？"
D.Strings[55194]="我能让你从死亡中获得生命。"
D.Strings[55195]="我喜欢那声音。"
D.Strings[55196]="我还是别跟死亡搅在一起了。"
D.Strings[55197]="他们为什么要攻击我们？！"
D.Strings[55198]="我们怎样才能活下去？！"
D.Strings[55199]="谁来救救我们？！"
D.Strings[55200]="这里发生了一些事情。具体的情况还有待进一步查明。"
D.Strings[55201]="这帽子有魔力，你想试试吗？我们还有多余的！"
D.Strings[55202]="当——然！"
D.Strings[55203]="不用了，谢谢，我必须时刻提防入侵。"
D.Strings[55204]="这里一向风平浪静。可你看看现在。这些野牛人是从哪儿来的？"
D.Strings[55205]="如果你往西北走，可以去土地精集市逛逛。那有许多好看的饰品和幸运符。光顾那里的人总能交上好运。"
D.Strings[55206]="一只巴塔里战斗雪人从远古之路过来了！"
D.Strings[55207]="一只巴塔里战斗雪人从桥上过来了！"
D.Strings[55208]="一只巴塔里战斗雪人从西边过来了！"
D.Strings[55209]="有黑麦吗？"
D.Strings[55210]="闪耀上升吧。"
D.Strings[55211]="我喜欢酿月祭，每年都期盼着这节日的到来。"
D.Strings[55212]="牦牛。牦牛从不改变。"
D.Strings[55213]="你的牦牛在另一个棚舍里。"
D.Strings[55214]="一个人去很危险吧？"
D.Strings[55215]="你能好心告诉我怎么回昆莱吗？"
D.Strings[55216]="也许你能滚动一只桶。"
D.Strings[55217]="你在这里可能会死于痢疾。"
D.Strings[55218]="我只不过是个胡吃海喝的可怜虫。"
D.Strings[55219]="风和日丽，醇酒佳酿，肥美鲜鱼，还有什么不满足的？"
D.Strings[55220]="放入越多，进去越多。"
D.Strings[55221]="我很少和熊猫人交流，一旦交流……必定与美酒有关！"
D.Strings[55222]="坐在这么漂亮的东西上面真是不好意思。"
D.Strings[55223]="我是连续六届投掷美酒大赛的冠军！我是全潘达利亚的最强者。"
D.Strings[55224]="做梦的感觉就是这样吗？"
D.Strings[55225]="我发现酿月祭是个让我暂别研究，劳逸结合的好机会。"
D.Strings[55226]="十年了。我任劳任怨地刷牦牛十年了。"
D.Strings[55227]="在与牦牛争论时有两大理论。可哪个也不起作用。"
D.Strings[55228]="我只是来找芜菁的，我发誓！"
D.Strings[55229]="能看到禅院外面的世界，真好。"
D.Strings[55230]="我想开个派对，邀请了秘法师鸟羽帽，可你却把他赶走了。"
D.Strings[55231]="我想牦牛已经开始移动了。"
D.Strings[55232]="那些野牛人手握直剑。直。剑。"
D.Strings[55233]="噢，唉。低点。低点。"
D.Strings[55234]="我是位牦牛骑士。这是我的牦牛。"
D.Strings[55235]="在整个潘达利亚，什么都抵挡不了雄壮远足牦牛的狂怒。但愿你永远也不用亲眼见到。"
D.Strings[55236]="我无意针对你创立法规。"
D.Strings[55237]="牦牛尾巴对保持平衡有帮助吗？"
D.Strings[55238]="我会滚啊滚，滚进魔古山的大门。"
D.Strings[55239]="再给我一分钟就好。等等，那全错了。"
D.Strings[55240]="只给迪嘭迪嘭最好的酒。"
D.Strings[55241]="我在旅途中弄丢了盾牌，原本我只想要品尝好酒，可现在，我只想把盾牌找回来！"
D.Strings[55242]="你继续帮我指引方向，我继续丢桶！"
D.Strings[55243]="今天我能帮你什么忙吗？"
D.Strings[55244]="我需要食材来上烹饪课。"
D.Strings[55245]="你好啊，朋友。饿了吗？"
D.Strings[55246]="很明显，土地精已经被冻在这儿有一段时间了，但你看他的背包里有东西在闪闪发光。"
D.Strings[55247]="取出他背包中的东西。"
D.Strings[55248]="我将更新我的日记。"
D.Strings[55249]="我感觉像是一根血肠。"
D.Strings[55250]="我感觉若有所失。"
D.Strings[55251]="击中前部！"
D.Strings[55252]="我要烧掉你们的村庄[PH]。"
D.Strings[55253]="让我们喝一杯吧！"
D.Strings[55254]="这个可怜的土地精已经被冻在这儿有一段时间了。"
D.Strings[55255]="我们开始吧，米师！"
D.Strings[55256]="你会付出鲜血的代价！"
D.Strings[55257]="闪闪发光的武器。把它们交给我吧！"
D.Strings[55258]="看着我，充满朝气的青年人！"
D.Strings[55259]="好极了……挑战。"
D.Strings[55260]="我们现在更强大了！你死定了！"
D.Strings[55261]="我们是阶梯的主人了！"
D.Strings[55262]="我要吃掉你的脑袋！"
D.Strings[55263]="热血生物在我们的阶梯上绝无立足之地！"
D.Strings[55264]="我不这么认为。"
D.Strings[55265]="你休想打败我们。"
D.Strings[55266]="我被派去破坏希克提克桥的重建工作，可你在敌阵中左突右杀，像个真正的$c。你有机会消灭他们的领袖！"
D.Strings[55267]="你是谁，竟敢阻止我们？"
D.Strings[55268]="也许……我们出击得……过早了。"
D.Strings[55269]="送我回去，腾武！"
D.Strings[55270]="击中左侧！"
D.Strings[55271]="击中右侧！"
D.Strings[55272]="隐秘阶梯很快就会回到我们手里！"
D.Strings[55273]="煞弱化了熊猫人！是时候将他们彻底赶出隐秘阶梯了！"
D.Strings[55274]="这些旅行者真是绝佳的抢劫目标！把他们的东西抢走！把他们的东西全都抢走！！！"
D.Strings[55275]="全都偷走！把他们所有的东西都偷走！"
D.Strings[55276]="我是郭雅夫人的“救援专家”。是她的意愿引导着这条道路上来来往往的人流。$b$b我的职责是确保某些贪得无厌的人不要滥用她的热情款待。"
D.Strings[55277]="多加小心。盎迦猴岛的海盗非常可怕。可他们酿的酒不错！"
D.Strings[55278]="我们需要更多美酒。可以到西南边的海盗船上找找看。"
D.Strings[55279]="我们需要更多美酒。你应该去西北边的岛上找找。我想我看见那边有海滩派对。"
D.Strings[55280]="我们需要更多美酒。沿海岸西边的洞穴里也许还有存货。"
D.Strings[55281]="我们需要更多美酒。我好像看见猢狲在东南边的山峰上狂饮作乐。"
D.Strings[55282]="谁会把一堆炸弹和一门大炮放在自己的美酒旁边？啊，好吧。猢狲眼里的垃圾，到了酿酒师这，就会变成海岸防御工事。"
D.Strings[55283]="噢不！乌克头领？我以为他只是传说。"
D.Strings[55284]="看来猢狲把酒杯和酒桶弄得满岛都是。"
D.Strings[55285]="他们从海里过来了！快用火炮！"
D.Strings[55286]="猢狲在偷我们的美酒！"
D.Strings[55287]="蠢货……抢走了……我的酒……"
D.Strings[55288]="击中后部！"
D.Strings[55289]="就算你夺走我们的生命……也别想……夺走……我们的酒……"
D.Strings[55290]="蠢蛋……会遭……报应的。"
D.Strings[55291]="我死得其所！"
D.Strings[55292]="蠢蛋……坏透了……巴巴姆……"
D.Strings[55293]="螳螂妖对我唯命是从，蠢货。看看她有多听我的话。"
D.Strings[55294]="一直扔就对了！我想他们开始逃跑了。"
D.Strings[55295]="什么？！再也不会发生什么事情了？！"
D.Strings[55296]="赶快！抓起酒桶，豁出老命丢出去！"
D.Strings[55297]="你再也不会出去了！"
D.Strings[55298]="蜥蜴人的巫术。"
D.Strings[55299]="真是衰透了。"
D.Strings[55300]="幸运儿如果明智的话，就该掷桶了。"
D.Strings[55301]="不带炸药桶就出海，真是倒霉。"
D.Strings[55302]="这些在黑暗中成长的蜥蜴人非常危险，也非常强大。"
D.Strings[55303]="后退！爬行动物！"
D.Strings[55304]="哈哈！没想到吧，蜥蜴嘴！"
D.Strings[55305]="接着，爬行动物！"
D.Strings[55306]="啊！蜥蜴人上船了！蜥蜴人上船了！"
D.Strings[55307]="我们这儿有来自潘达利亚各地的造访者，他们肯定可以帮助我们解决这些掠夺者。"
D.Strings[55308]="告诉我有关卡桑琅荒原啤的事。"
D.Strings[55309]="告诉我关于布莱瓦·肖的事情。"
D.Strings[55310]="和我说说节日焰火。"
D.Strings[55311]="告诉我关于天禅院弟子的事情。"
D.Strings[55312]="和我说说受损的火炮。"
D.Strings[55313]="告诉我关于锦绣谷神射手的事情。"
D.Strings[55314]="告诉我关于天禅院织雾者的事情。"
D.Strings[55315]="告诉我关于快活的村民的事情。"
D.Strings[55316]="告诉我关于齐延姿的事情。"
D.Strings[55317]="告诉我关于雪怒执盾手的事情。"
D.Strings[55318]="告诉我关于迪嘭迪嘭的事情。"
D.Strings[55319]="告诉我关于滨岸渔民的事情。"
D.Strings[55320]="卡桑琅荒原啤极其易爆，$n！我们可以将酒桶放在野牛人的必经之路上，然后点火。拿上酒桶，我会做好标记，告诉你应该把它们放在哪里。"
D.Strings[55321]="布莱瓦·肖是投掷啤酒桶的高手，$n。他可以把酒桶扔到空中，然后让酒桶在野牛人中间摔碎！我今天上午在旅馆附近看到过他。去看看他是否愿意帮忙吧！"
D.Strings[55322]="我们的小镇上到处都有用于庆祝节日的大桶烟火。$n。把它们放在正确的位置，给它们来个恰到好处的打击，让它们可以造成各种各样的破坏。带上一桶烟花，我会在放置烟花的地方做标记。"
D.Strings[55323]="小镇上有天禅院弟子在庆祝酿月祭，$n！他们可以用学到的技艺帮助我们。和他们谈一谈，看他们是否可以阻止那些野牛人！"
D.Strings[55324]="旅馆后面的仓库里有一些破损的大炮，$n。如果你可以修复这些大炮，村民们就可以用它们击退野牛人！"
D.Strings[55325]="小镇上有一些锦绣谷神射手，他们在这里过夜休息，$n。他们用迫击炮在残阳关和螳螂妖战斗了很多年。你看一下能不能叫醒他们！"
D.Strings[55326]="小镇上有来自天禅院的天禅院织雾者，$n。他们在制造迷雾方面的能力可以帮助我们战斗得更久。请他们在战斗中帮助我们。"
D.Strings[55327]="小镇上有一些快活的村民，他们说他们制造了一种能够让所有事情更加顺利进行的头盔。虽然我表示怀疑，但戴上头盔又没有什么损失，你说呢？和他们谈一谈，看他们是不是愿意借你一个。"
D.Strings[55328]="齐延姿每年都来祝福我们的节日，$n。他不会参加战斗，但或许可以帮我们做一些其他事情。问问他是否能帮我们做些事情。"
D.Strings[55329]="雪怒执盾手每年都会从白虎寺来到山下，$n。他们或许可以阻止野牛人的入侵，以免野牛人进入村庄。和他们谈一谈，看他们是否可以帮助我们。"
D.Strings[55330]="迪嘭迪嘭时不时地来到镇上，向我们出售在昆莱山附近搜集到的奇怪的小玩意儿。和他谈一谈，看他有没有可以给我们当做武器的东西。"
D.Strings[55331]="滨岸渔民闭着眼睛都可以用渔网捉到醉醺醺的猢狲，$n。他们当然也可以帮我们捉一些野牛人了。和他们谈一谈帮助我们保卫村庄的事情吧！"
D.Strings[55332]="还有其他防御吗？"
D.Strings[55333]="昆莱劲酒完成了，$n！准备好见识一下潘达利亚最好的酒了吗？我要警告你，喝过这种酒之后，可能会产生踢东西的冲动。这是件好事，因为有太多的野牛人需要被踢飞了！"
D.Strings[55334]="快给我点儿！在野牛人夺走之前！"
D.Strings[55335]="向酒仙布夫要一些昆莱劲酒！"
D.Strings[55336]="你们要为这场骚扰付出代价！"
D.Strings[55337]="你们竟敢进入山谷！"
D.Strings[55338]="你们会后悔入侵这里的！"
D.Strings[55339]="你会缓慢而且痛苦地死去！"
D.Strings[55340]="你们的族类不允许进入山谷！"
D.Strings[55341]="第一个就要杀死你！"
D.Strings[55342]="你的小命正好用来祭奠我们的帝王！"
D.Strings[55343]="我们要在敌人的尸体上重建帝国！"
D.Strings[55344]="不服从者格杀勿论！"
D.Strings[55345]="你们的软弱让人恼火！"
D.Strings[55346]="我的死不会让你们得到救赎的……"
D.Strings[55347]="你们的胜利只是暂时的……"
D.Strings[55348]="当两个伟大的帝国重新合并，整个世界都会在他们面前颤抖……"
D.Strings[55349]="你们太晚了……"
D.Strings[55350]="我的死对你们没有任何好处！"
D.Strings[55351]="大海今天会为我们带来什么？"
D.Strings[55352]="他们让人不寒而栗，你说呢？我从来没有见过他们，但我一直在追捕他们。"
D.Strings[55353]="你们休想夺走我们的土地！"
D.Strings[55354]="与我们的帝国作对可不明智！"
D.Strings[55355]="赞达拉部族要定这片土地了！"
D.Strings[55356]="我们的帝国将会夺回自己的东西！"
D.Strings[55357]="|TInterface\\Icons\\spell_fire_volcano.blp:20|t%s开始施放|cFFFF0000|Hspell:125391|h[火焰裂隙]|h|r！"
D.Strings[55358]="琥珀增生影响到了%s的伤口，正在补充它的活力。"
D.Strings[55359]="%s正在逐渐丧失体力，突然之间倒下了。"
D.Strings[55360]="雕像的手里似乎有什么东西……"
D.Strings[55361]="取出他手中的东西。"
D.Strings[55362]="别找借口了，女皇！消灭这些傻瓜，否则我会亲手杀了你！"
D.Strings[55363]="战争使者虬碧的斧子掉了。快拿起来！"
D.Strings[55364]="|TInterface\\Icons\\inv_misc_dust.blp:20|t%s开始|cFFFF0000|Hspell:124359|h[掘地]|h|r！"
D.Strings[55365]="我要治疗和复活我的战斗宠物。"
D.Strings[55366]="你看我的宠物如何？"
D.Strings[55367]="我有一个任务要交给你。"
D.Strings[55368]="你们这些野蛮人最好考虑清楚还要不要攻击我们的村庄！"
D.Strings[55369]="你要告诉我遗迹藏在哪里！"
D.Strings[55370]="从这些上好的鱼竿中选择一根，然后小心地拉鱼线。这样可以更加轻松地钓到东西。"
D.Strings[55371]="嗯，这可不太常见……解决掉它，然后再拉另一根鱼线。"
D.Strings[55372]="哈……我在这里收获颇丰。我去把这宝贝儿送上岸，你继续好好拉鱼线吧！"
D.Strings[55373]="什么……以……玛祖……之名……啊！！"
D.Strings[55374]="你早些时候品尝的洄梦仙酒可以强化你的感觉，让你看到游离在世界之外的东西。我会教你如何正确使用，我们将会找到你的王子！$b$b但首先，请帮我酿一批新酒。"
D.Strings[55375]="甲板长官说你需要帮助。"
D.Strings[55376]="优质的洄梦仙酒酒力强劲。你要有高度集中的意识来分辨各种影像！"
D.Strings[55377]="现在，你要紧守本心。你可以集中或者放松精神，但是必须守住本心。"
D.Strings[55378]="啊，很好，看来要让你分心并不容易。我们熊猫人总是只关注当下，有时反而是种妨碍。"
D.Strings[55379]="抱歉，没吓着你吧？我们熊猫人最推崇高山崩于前而色不变的气度。"
D.Strings[55380]="那我就……这样？"
D.Strings[55381]="看呐！多么闲逸的风度。我很喜欢你。"
D.Strings[55382]="没有你，蒙蒙就变成了大臭蛋！蒙蒙会感谢你的。或许你和老愚也不是那么没用。"
D.Strings[55383]="你猜怎么？我要向他们证明，我也可以成为大师级农夫！$B$B我要把这个农场变成山谷里最繁荣的农场！$B$B但是，这对于一个熊猫人来说有点过于繁重了。你愿意帮助我吗？"
D.Strings[55384]="你要做什么，农夫老愚？"
D.Strings[55385]="真是万分感谢你对我的帮助，$r。我欠你的人情。"
D.Strings[55386]="嗨，陌生人……可不可以借些钱给口渴的旅行者？"
D.Strings[55387]="给鱼买杯酒？"
D.Strings[55388]="今天什么风把你给吹来了，我的$G兄弟:姐妹;？"
D.Strings[55389]="水流预示着今天会有好运气，$n。"
D.Strings[55390]="嗨，哥们，可不可以资助一下可怜的锦鱼？"
D.Strings[55391]="我渴坏了，哥们。"
D.Strings[55392]="锦鱼的朋友，来和我坐一会儿。"
D.Strings[55393]="嗨，朋友，介意和我一起喝一杯吗？"
D.Strings[55394]="嗨，我的好朋友，$n。我今天感觉清醒多了。或许是因为我少吃了一些酱油。"
D.Strings[55395]="你知道的，我决定把你当做朋友了。这让我想到，或许我可以再交一些朋友。"
D.Strings[55396]="负面情绪，如愤怒或疑虑，会在潘达利亚表现出一种诡异的力量。你将来就会明白的。"
D.Strings[55397]="我欠你的，所以我要告诉你。我会和我的父亲说，让你们加入阡陌客。"
D.Strings[55398]="感觉到了吗？源自灵魂的完美宁静！"
D.Strings[55399]="啊哦！你惹毛了一些愤怒的螃蟹！"
D.Strings[55400]="啊哦！你惹毛了一些蜘蛛！"
D.Strings[55401]="我们跟随着风的指引四处游荡，好心的$r。你愿意倾听一会儿吗？"
D.Strings[55402]="在旅途中，我们唱过很多的歌曲，但还有很多歌曲没有唱。"
D.Strings[55403]="我要召唤故乡的水……把我的敌人交给我吧！"
D.Strings[55404]="我和我们的人民正在研究附近的河流和水塘。我们以前从来没有见过如此具有活力的水。"
D.Strings[55405]="我们认为正是山谷中的独特水质造就了这片繁荣的区域。"
D.Strings[55406]="这个水塘里的水……非常糟糕。"
D.Strings[55407]="不幸的是，我们的兄弟贾古自从家人去世之后就活得很消沉。"
D.Strings[55408]="贾古来自另外一个部落。他来自遥远的北方，很少提起自己为什么会来到这里。"
D.Strings[55409]="那边的那位兄弟只是借酒消愁，对世事不闻不问，从不辛苦工作。"
D.Strings[55410]="哟！这酒真带劲儿！"
D.Strings[55411]="这里的食物非常美味。我从没想过要离开。"
D.Strings[55412]="基赢大师说我们必须继续研究，但偶尔来这里放松一下也是不错的事情。"
D.Strings[55413]="<当你抚摸这只大猫浓密的皮毛时，她只是冲着你动了动耳朵。>"
D.Strings[55414]="<这只大鸟躲开了你。>"
D.Strings[55415]="能与其他的部落幸存者重聚真是太幸运了。我根本没想到，还有别的同胞也被冲上了这片全新的土地。"
D.Strings[55416]="德兹科派我们来侦察这片地区。我们也许已经找到了莱莎幻像中出现的伟大治疗之力。"
D.Strings[55417]="当地人坚称，我们要找的伟大治愈之水不过是……风暴烈酒而已。我们得调查下这种说法的真实性。"
D.Strings[55418]="这巨魔抱怨食物不好吃，但他吃的比谁都多。"
D.Strings[55419]="你看到西面的长城了吗？我在想长城的外面有什么呢？"
D.Strings[55420]="这里所有的东西……都那么……那么……不同！"
D.Strings[55421]="海军上将泰勒派我们来此寻找年轻的王子。你能想到他们这里也酿啤酒吗？"
D.Strings[55422]="我们正在努力寻找安度因王子。顺道路过，来吃些干粮酒水。"
D.Strings[55423]="他们说潘达利亚有五千多种酒。我在尝遍这些酒之前是不会离开的！"
D.Strings[55424]="过来和我们喝一杯，$r！"
D.Strings[55425]="我就是喜欢听柯谈论他那些美味的食谱。我从不知道竟然有那么多种烤肉的方法。"
D.Strings[55426]="你有没有尝过柯的厨艺？我好像怎么都吃不够。"
D.Strings[55427]="他经常告诉我说他喜欢我的口音，我就一直问他，什么口音？"
D.Strings[55428]="嘿，$c，很高兴在这见到你！你也是被派去寻找小王子的？"
D.Strings[55429]="这里的本地人过着美好的田园生活。这不禁令我怀疑，自己是不是该放下魔杖，拿起锄头。"
D.Strings[55430]="我是专卖魔杖的小贩。我们都很幸运，我的大部分魔杖都躲过了那次海难！"
D.Strings[55431]="聪明的人会在疲劳时休息。"
D.Strings[55432]="整个潘达利亚最好的酒就产自这个山谷的风暴烈酒酿造厂。$B$B嗯，至少我是这么认为的。"
D.Strings[55433]="开心的时候，喝酒能够助兴。难过的时候，喝酒只会愁上加愁。$B$B喝酒要做好选择，我的朋友。"
D.Strings[55434]="啊，我认为最开心的事情就是吃的饱饱的。$B$B让美味的食物填饱你的肚子，你的灵魂也会感受到温暖。"
D.Strings[55435]="享受美味的水果是件开心的事情，但不要吃太多。"
D.Strings[55436]="祝你好运，$r！我和我的兄弟大老远赶来就是为了给人带来幸运符的。"
D.Strings[55437]="拜托，既然我们是村里的客人，就守规矩些。要是我们大开杀戒，主人们恐怕不会善罢甘休。"
D.Strings[55438]="我们不要让杀戮席卷这片净土，$G兄弟:姐妹;。"
D.Strings[55439]="我们一路搜寻，跨越了千山万水，可却偏巧在这里狭路相逢。看来不管走到哪里，我们的冲突都是难以避免的啊。"
D.Strings[55440]="我一直在观察你，$r。"
D.Strings[55441]="嗨，丑八怪，我恨不得立刻给你一拳……如果我觉得可以教训你！但是，你知道这里的人也会酿造啤酒吗？"
D.Strings[55442]="除了打得头破血流，不如用跳舞来解决……我们之间的分歧吧？"
D.Strings[55443]="嘿够了，这可不是打架的地方。不然谁也别想吃到这美食。"
D.Strings[55444]="嘿，$r，别没事找事！我袖子里藏着好几把魔杖，我可不介意把它们对准你！"
D.Strings[55445]="音乐对人的心灵、身体和灵魂都有好处！"
D.Strings[55446]="你是来享受这里的美景的吗？"
D.Strings[55447]="你能闻到风的气息吗，陌生人？它们带来了变化。"
D.Strings[55448]="我们在这里思考潘达利亚的各种奇观。"
D.Strings[55449]="站在悬崖边上时，不要忘记了呼吸。"
D.Strings[55450]="欢迎来到青龙瞭望台。你有没有带风筝？"
D.Strings[55451]="附近地方的农夫把他们的大麦送到这里，我们磨成面粉并对谷物进行分类。$B$B有些谷物要做成食物，有些谷物拿去卖掉，但大部分都送到风暴烈酒酿造厂……你猜对了……酿啤酒！"
D.Strings[55452]="这是一个安宁的地方。我们欣赏风景，我们沉思，我们制作工艺品，我们心满意足。"
D.Strings[55453]="你有没有去过晨芳园？你去那里的时候有没有多拿一个金酿的木桶？$b$b把它们运过来可不是什么轻松的事情。"
D.Strings[55454]="青龙！它……它碎掉了。"
D.Strings[55455]="我告诉过我的儿子，我告诉过迪恩，下雨时不要将牦牛带到牧场。然后他做了什么？他在雨天将牦牛带到牧场。$B$B现在我们的牦牛生病了，这并不奇怪！$B$B唉呀！我怎么会生出这样一个愚蠢的儿子？"
D.Strings[55456]="我的儿子吃的不多。看看他！骨瘦如柴！我要多给他吃点儿。"
D.Strings[55457]="为什么我的儿子就得是个矮子？我想要高大、强壮的儿子。$B$B在他小的时候，我就告诉他，不要在室内撑雨伞。我说，这样你会长不高！$B$B然后他做了什么？他总是打着雨伞玩！在房子里面！"
D.Strings[55458]="我的儿子迪恩说，妈妈做的饺子是全谷最好吃的！$B$B噢哈哈哈。真是我的好儿子。"
D.Strings[55459]="妈妈喜欢吃橙子，但在谷里很难找到橙子。$B$B我给我的儿子一些铜钱，让他去市集上买一些橘子。$B$B然后他做了什么？他买了一些豆子！$B$B我们又不是农民！我们是放养牦牛的牧民！我问你，我该怎么处理这些愚蠢的豆子？"
D.Strings[55460]="猢狲和锦鱼人总是在战斗，但从来没有像这样……"
D.Strings[55461]="我的儿子迪恩整天在牧场。他这么努力工作。妈妈很自豪。"
D.Strings[55462]="青龙……它现在想做什么？"
D.Strings[55463]="这是什么意思？潘达利亚的和平结束了吗？这是命中注定的吗？"
D.Strings[55464]="你来看妈妈吗？噢，坐一会儿！$B$B我告诉你，几天前，我听到一些流言。$B$B我听说吉娜·泥爪和她的父亲郝瀚·泥爪合不来！$B$B他想把她嫁给农夫老方，但她不愿意！她说她想经营她的市集。$B$B唉呀！现在的年轻姑娘们是怎么了？不想嫁给英俊的小伙子，不想成家吗？$B$B特别是老方……他这么抢手！人长得好看，又种出这么大棵的蔬菜。$B$B我的儿子怎么就没那么年轻英俊？！"
D.Strings[55465]="噢，我的儿子什么时候能遇见一位年轻漂亮的女子？他整天围着牦牛转！$B$B哪个女孩愿意嫁给臭烘烘的牦牛牧人啊？唉呀，妈妈真担心……"
D.Strings[55466]="啊，你好，$r！$B$B这是保留我们所有耕种历史和知识的地方。$B$B我们记录当地的天气，以及相应的收成，详细到谷里的每一粒种子和每一棵植物，甚至我们可能会不断种植的一堆种子。$B$B这些知识对我们而言是神圣的。即使有一天灾难会降临到这片土地上，我们也必须要保存这些种子。"
D.Strings[55467]="你好，旅行者。我在努力工作，打造我的下一个杰作！"
D.Strings[55468]="青龙雕像被毁坏了吗？怎么可能发生这样的事？"
D.Strings[55469]="难道你只喜欢看着鸟儿吗？我真想我也能飞。"
D.Strings[55470]="农民祈求降雨，但我不！雨天对做生意来说非常糟糕。看看我的市集！湿透了！"
D.Strings[55471]="今天得在雨中做牦牛和穆山兽生意！好吧，无论天晴下雨，我都要经营这个市集。"
D.Strings[55472]="看看天空，$n！下雨了！对作物生长应该有好处吧？"
D.Strings[55473]="哇，看看这场暴风雨！嗯，作物喜欢喝水，对不对？"
D.Strings[55474]="“煞魔”是什么？它从哪里来的？"
D.Strings[55475]="你会帮助我们治愈土地吗？"
D.Strings[55476]="可怜的猢狲和锦鱼人！我们知道他们不喜欢对方，但走到今天这一步……"
D.Strings[55477]="所有锦鱼人和猢狲都在那次战斗中灭亡了吗？有幸存者吗？"
D.Strings[55478]="你会帮助我们对付煞魔吗？"
D.Strings[55479]="失去了……这么多。$b$b我担心，$n，这仅仅只是个开始。"
D.Strings[55480]="嗯？你说什么？"
D.Strings[55481]="我们会看到鲨鱼吗？"
D.Strings[55482]="如果还有时间的话。"
D.Strings[55483]="古老的箱子布满灰尘……"
D.Strings[55484]="我们去哪儿？"
D.Strings[55485]="该是去市集买鱼的时候了。"
D.Strings[55486]="我们快到了。还有一小段路程。"
D.Strings[55487]="爸爸，你能抱我吗？"
D.Strings[55488]="不行，亲爱的。我要你的腿长得即好看又结实。你希望有一天像我一样强壮，对吗？"
D.Strings[55489]="哇！我从来不知道这会回到这里。"
D.Strings[55490]="哇！这不可怕吗？你觉得那里有鬼吗？"
D.Strings[55491]="呃！那是什么东西？"
D.Strings[55492]="就在那！老农阿蓟的宝藏！"
D.Strings[55493]="哇噢！"
D.Strings[55494]="万岁！我们找到了！我们找到了！老农阿蓟的秘密宝藏！哦天哪哦天哪哦天哪！！！"
D.Strings[55495]="少女，不是吗？嗯，我记得那就是我父亲过去常说的北面的河流。除此之外，我没有其他线索。"
D.Strings[55496]="什么回声，那黑黑的是什么？这还不知道！是个山洞！"
D.Strings[55497]="嗯，我还真不知道呢，$r。我以为是山谷的一部分，就是这里！四风谷！"
D.Strings[55498]="噢，我听说过先祖的阶梯。有些人就是这么称呼北面的群山的。"
D.Strings[55499]="你可以找到什么线索吗？"
D.Strings[55500]="你听过少女掩扇而笑的声音吗？"
D.Strings[55501]="我在哪里可以找到先祖的阶梯？"
D.Strings[55502]="在哪里可以对有回音的黑洞中发出低语？"
D.Strings[55503]="你可以让我加入战斗吗？大多数小女孩讨厌蛇，但我觉得蛇很可爱！"
D.Strings[55504]="我和我的家人将新鲜的鱼从渔人码头带到镇上。你想买一些吗？"
D.Strings[55505]="从镇上到香里拉有很长一段路，但走路对精神有好处。这肯定有助于让小艾黎到户外活动。"
D.Strings[55506]="我不应该和陌生人说话。"
D.Strings[55507]="5.0 烹饪——烹饪学生缺省1"
D.Strings[55508]="你看到那边的大鱼了吗，$n？"
D.Strings[55509]="你不要试图接近我！我的朋友总说我的脑后门上长着眼睛！"
D.Strings[55510]="我能为你做些什么吗，$n？"
D.Strings[55511]="哇噢！我仍然无法相信，我们发现了老农阿蓟的宝藏。我想所有这些民间故事并非完全真实，但我还是乐意讲给他们听！"
D.Strings[55512]="告诉我老农阿蓟的故事。"
D.Strings[55513]="现在他们说，无论谁得到地图，都可以找到失去的宝藏……"
D.Strings[55514]="噢？告诉我更多详情。"
D.Strings[55515]="现在，把我的技术传授给新人。"
D.Strings[55516]="我们不会容忍那些将煞魔释放到我们家园的人们。"
D.Strings[55517]="我们将煞魔击退，同样也会击败你们。"
D.Strings[55518]="有一次，我看见一条非常大的鱼，你发誓它是鲨鱼。现在想起来了……"
D.Strings[55519]="你是渔夫？和他们无力的手臂和沉重的护甲吗？"
D.Strings[55520]="欢迎光临潘达利亚海岸！这里一切可能冲刷海岸的东西已经或者将冲刷上海岸。"
D.Strings[55521]="你用什么样的诱饵？我知道一个熊猫人会使用自己的手掌做饵来钓鱼。$b$b我们叫他搏鱼者。$b$b听说他退休了，境况越来越糟。"
D.Strings[55522]="可曾见过海怪？老金称自己从前捕到一条，但又放回去了，因为它“腥味太重”了。$b$b我们打赌，看他是否还能再次捕到。"
D.Strings[55523]="那么，那鱼长什么样，你又从哪里来？"
D.Strings[55524]="常年笼罩着这片海滩的迷雾散去了，这背后一定有什么原因。"
D.Strings[55525]="我认识一名武僧，他擅长使用斗鱼招式。招数虽然相当有限，但是他炖的鱼汤非常好吃。"
D.Strings[55526]="新来的吗？这就像我们告诉孩子们，没有手握大把的诱饵和撤退策略就不要下水。"
D.Strings[55527]="有个孩子发誓，有一天，他看到了在鲨鱼和章鱼之间的一个十字形物。$b$b我知道海洋中有很多奇怪的事情，但在我看来，都很无聊。"
D.Strings[55528]="你可能已经看到船撞上我们的海岸。你的船也有过那样的遭遇吗？$b$b迷雾常常给我们带来那样的“礼物”。"
D.Strings[55529]="是翔龙骑士派你来的吗？他们的翔龙不断偷取我们最好的渔获物。"
D.Strings[55530]="在这里捕鱼的时间长了，就见怪不怪了。我看到过长了胳膊和腿的海象。而且，那海象还会说话！"
D.Strings[55531]="你们那的大海是什么样的？"
D.Strings[55532]="我总对这里的锦鱼人感到奇怪。但他们知道如何捕鱼，而且技术比我们更高，所以我有什么资格去评判呢。"
D.Strings[55533]="你是我最好的老师！"
D.Strings[55534]="等我长大了，我要成为潘达利亚最棒的大厨。"
D.Strings[55535]="噢，这太令人兴奋了！现实版的寻宝！"
D.Strings[55536]="你觉得我会成为一名好厨师吗？"
D.Strings[55537]="我们接下来要学什么？"
D.Strings[55538]="我会尽力当个好学生。"
D.Strings[55539]="那件事看上去太可怕了！你救了我们的命，$n！"
D.Strings[55540]="小道消息——选项1——测试——HW"
D.Strings[55541]="小道消息——选项2——测试——HW"
D.Strings[55542]="那么……想谈谈这个事儿吗？"
D.Strings[55543]="你确定？我听说每个人都或多或少碰到过这样的事。"
D.Strings[55544]="完全是新手。"
D.Strings[55545]="他们应该用功一点。"
D.Strings[55546]="一招半式不解决问题。"
D.Strings[55547]="他们没通过测试，你呢？"
D.Strings[55548]="他们来了？很好。要是我的学生们能在这旁观，从我即将展示的高超武艺中学上几招就好了……"
D.Strings[55549]="我们成功了！儿子啊儿子，等到我的朋友们全都知晓这件事。他们永远也不会相信它！再见，$n！"
D.Strings[55550]="这真是……太不同寻常了，$n！这些备注为我们的农民提供了宝贵的知识。我们衷心感谢老农阿蓟保存了这些记录，我们也感谢你发现了这些记录。谢谢你！"
D.Strings[55551]="雾海飞跃者二世在东南方向的码头。出发！"
D.Strings[55552]="鱼叉炮准备！"
D.Strings[55553]="瞄准前部、左侧、右侧浮力囊，以及后部……"
D.Strings[55554]="呃，对不起……让我换一种说法。"
D.Strings[55555]="先来个迎面痛击！接着打两侧！然后打尾巴！你知道的，这些是软肋。"
D.Strings[55556]="漂亮的射击！"
D.Strings[55557]="哈哈！老鱿鱼，你觉得怎么样？！"
D.Strings[55558]="玛祖，指引我出击……"
D.Strings[55559]="继续！"
D.Strings[55560]="对极了！滚回深渊中去吧！"
D.Strings[55561]="它好像被打漏了！"
D.Strings[55562]="那简直是一流的叉鱼技术！"
D.Strings[55563]="还有更多访客吗？呸！"
D.Strings[55564]="不知道我是怎么来到这的。但是……好运常常降临开明的人。"
D.Strings[55565]="永远不要低估治疗的重要性。"
D.Strings[55566]="治疗可以扭转战局。"
D.Strings[55567]="欢迎光临雷掌阁。在这里，我们将我们的技艺重点放在将我们的真气融入治疗中。"
D.Strings[55568]="如果你开始学习一样东西，你会发现还有很多要学。"
D.Strings[55569]="欢迎来到雷掌阁。别被盔甲蒙骗了。我们这是进行治疗训练的。"
D.Strings[55570]="这里平时相当平静。只有蜥蜴人狩猎小队会偶尔来给我们添些麻烦。而且蜥蜴人一般只在狂风暴雨来袭时才会出现。"
D.Strings[55571]="你见到酒仙布兰彻了吗？她经常在南边和东边的路上徘徊，总会带上口感绝妙的佳酿来造访我们，在这里家喻户晓。"
D.Strings[55572]="我在努力学习如何治疗。问题在于，你得先受伤，才能被治疗。"
D.Strings[55573]="前几天，有人说我“过量治疗”了。真让人困惑。"
D.Strings[55574]="我在学习如何帮别人消除痛苦。很厉害吧？"
D.Strings[55575]="现在不能说话。必须……集中精神。"
D.Strings[55576]="我从来不知道，泡茶有多少讲究。"
D.Strings[55577]="我……都快透不过气了。多亏你救了我。"
D.Strings[55578]="可怜的小羊……到处乱走终于害了他。"
D.Strings[55579]="他们的到来毫无征兆。令守卫束手无策。"
D.Strings[55580]="看来住在太过美丽的地方是有风险的……"
D.Strings[55581]="这些魔古族吓不走我们。现在这里是我们的家了。"
D.Strings[55582]="多亏有你，我才活了下来……我不会忘记你的恩德。"
D.Strings[55583]="我认识你！你在不到一个星期前才救过我的兄弟。你是位真正的英雄！"
D.Strings[55584]="我还以为……我还以为自己死定了。谢谢你，陌生人。"
D.Strings[55585]="等等！有敌人来了！"
D.Strings[55586]="有个新来的，前几天跟我开了个玩笑。他说我应该闻得到他身上的“治疗迷雾”。治疗跟迷雾有什么关系啊。"
D.Strings[55587]="出现攻击者！"
D.Strings[55588]="我将追随你左右，朋友。"
D.Strings[55589]="你赢得了我的帮助。现在去哪儿？"
D.Strings[55590]="准备与唤醒者交战吧！"
D.Strings[55591]="谢谢你，朋友。让我与你并肩战斗吧。"
D.Strings[55592]="在那笼子里待太久了。我要让这些魔古族知道，我对囚禁感觉如何……"
D.Strings[55593]="感谢你及时出手相救，英雄。"
D.Strings[55594]="我们永远不会放弃对山谷的防护！"
D.Strings[55595]="呒！我闻到羊肉的香味！"
D.Strings[55596]="金莲教万岁！"
D.Strings[55597]="天神的意愿！"
D.Strings[55598]="对羊肉大快朵颐的时候到了！"
D.Strings[55599]="我们联合起来。我们永远不会倒下！"
D.Strings[55600]="金莲教永远不会屈服。"
D.Strings[55601]="锦绣谷永远不会陷入魔古族手中！"
D.Strings[55602]="韶天赴死！"
D.Strings[55603]="屈服还是倒下！"
D.Strings[55604]="你的姿势错了。你完全站不稳脚跟。你的头脑太笨。$b$b当你已经学到准备去学的东西时，请返回这里。"
D.Strings[55605]="你会被韶天族的威力所烧焦！"
D.Strings[55606]="我们将取你的血来祭奠这个山谷！"
D.Strings[55607]="你的眼睛已经看不见面前的事物。毫无疑问，这是你平时不良的饮食习惯所造成的。"
D.Strings[55608]="你的灵魂将被我折磨！"
D.Strings[55609]="归来的国王将消灭你整个种族！"
D.Strings[55610]="我的杀戮之轮将从你的头颅上辗过！"
D.Strings[55611]="我要将你的首级顶在长矛上，$r！"
D.Strings[55612]="你就算是死了，也休想从我的手心里逃脱！"
D.Strings[55613]="瞧瞧你那可怜而又懦弱的反抗！"
D.Strings[55614]="你走起路来的步履犹如一头怀孕的牦牛。你还没有达到能在这里训练的要求。"
D.Strings[55615]="要想在水上奔跑，那么你必须跑得特别快。"
D.Strings[55616]="韶天族对这堆废墟似乎非常感兴趣。他们打算恢复其深处的力量。而我会将他们的尸首丢弃在上面。"
D.Strings[55617]="这些受训者太不堪一击了。他们根本还没学会飞檐走璧，更别说直接面对螳螂妖或魔古族了。还需要很长一段时间的训练，他们才能真正派上用场。"
D.Strings[55618]="通过城墙，我们全都在长途跋涉中效力于莱文。我们用野牛人和螳螂妖的血来祭奠我们的刀刃！这些低估我们实力的魔古族，会由于他们的错误判断而致命。"
D.Strings[55619]="踏上恐惧废土，使我明白了探查地形与洞悉敌人行动的重要性。不论是为了取胜还是存活，先发制人总能事半功倍。"
D.Strings[55620]="对于身经百战的老兵来说，很难适应和平环境，但那是我们的职责。这些村民厌恨战争，除非别无选择，否则就不要把战火引到他们门前。"
D.Strings[55621]="他是不是很了不起？！"
D.Strings[55622]="有这么多人要去养活，可是从来没有足够的食物去喂饱他们！"
D.Strings[55623]="到我这里来科沃克。"
D.Strings[55624]="我的一位先祖参加了徒圣起义，他的尸体就躺在这墓地里。我愿意放弃我的自尊去接受和平，但是墓地里的鬼魂知道这个世界是没有和平可言的。"
D.Strings[55625]="只有让受训者尝到了失败的滋味，他们才会明白胜利的意义。"
D.Strings[55626]="<他对你露出了满脸的狰狞。>"
D.Strings[55627]="<当你靠近的时候，他变得异常兴奋。>"
D.Strings[55628]="<他面无表情地注视着你。>"
D.Strings[55629]="我喜欢把自己看作此次行动的幕后智囊和台前花旦。安济的四肢发达。并且她也是个台前花旦。$B$B我们这里已经有很多台前花旦了。"
D.Strings[55630]="我讨厌蜘蛛。还有那些移动的神像。以及偷东西的精灵。这片废土上的一切我都讨厌。幸运的是，我还有安济，她可以让我的容貌完美无瑕！"
D.Strings[55631]="韶天族在这个山谷里没有可以藏身之处，他们低估了影踪派的坚韧不屈。"
D.Strings[55632]="魔古族的归来以及西边的螳螂妖纷涌而至，他们带来的威胁不断加剧，这些都引来了比以往更多的受训者。这很好。他们会派上用场的。"
D.Strings[55633]="魔古族可能是一个强大的威胁，但跟我和我的士兵所面对的恐惧废土的恐惧比起来，它根本不能恫吓住我们。我们一定可以在山谷中挖出一个洞来。"
D.Strings[55634]="我们跟你们一样对这个山谷一无所知。当闸门一打开，我们就来了。失去了我们在昆莱的家园。想必在这里我们可重建它。"
D.Strings[55635]="我想我们也许被某种方式给诅咒了。我们所遭受的恐惧，似乎从来没有停止。$B$B有时你所有能做的就是尽量保持良好的精神状态，或许可以对变化无常的曲折命运抱一丝淡淡的感激，而不必在乎到底最后的归宿为何。"
D.Strings[55636]="这是整个潘达利亚最美丽的地方！聪明人在这里可以赚得盆满钵满！"
D.Strings[55637]="充满生机的村庄是谋生的绝佳去处！这里需要很多物资，所以能进行各种各样的贸易。我想我确实可以在这里过着无忧无虑的生活！"
D.Strings[55638]="早在很久之前，我就听说这是个非常宁静、美丽的山谷，那个时候没有人被允许进入。现在我们置身其中，发现到处都是形形色色的野兽，不是想打碎我们的脑袋就是想咬掉我们的脚。$B$B所以这个传说是个谎言，或者说我们只是令人憎恶的不速之客？我还是摒弃后一种想法吧，因为那样想的话就太自欺欺人了。"
D.Strings[55639]="这里所有的一切都让人毛骨悚然，不是吗？还有这些陷阱，真是让人太不舒服了。这些魔古族真应该将这些陷阱做得隐蔽些。"
D.Strings[55640]="如果这个山谷里百花盛开是真正永恒的，那么对于刚长出来的新芽来说是相当危险的，不是吗？这正是我所担心的地方。我们将会在香软且令人窒息的花海中畅游。$B$B为了安全起见，我将小朵的花踩在脚下碾碎，只是为了保持事物的平衡，你明白吗？"
D.Strings[55641]="鲁克对朋友很好。"
D.Strings[55642]="鲁克想要捣毁魔古族，但是那些村民会处在危险之中！如果鲁克保护村民的安全，你会帮助他捣毁魔古族吗？"
D.Strings[55643]="为什么老魔古在这里修建破碎的柱子和墙壁？为什么不像其他人一样建造完整的建筑物？愚蠢的魔古。"
D.Strings[55644]="在这些废墟中藏有许多古魔古族的秘密。这里曾经整个都属于他们，甚至某些角落中还可以发现被熊猫人践踏过的脚印。"
D.Strings[55645]="魔古族是凶残的绑匪。如果我们勇敢的战士已经落入他们手里，那么不管在任何时候，我们就不应该再去冒险了。"
D.Strings[55646]="在最黑暗的时代，通常只有耐心的精神和可靠的手可以担负起最大的责任。"
D.Strings[55647]="我为这个村子的将来潸然泪下。只要魔古族呆在山谷里一天，他们和魔古族之间的痛苦噩梦似乎永远没有结束的时候。"
D.Strings[55648]="修建在生存之环中的反射可以使受训者在城墙外得以生存。在那里，威胁更不容易被放任。"
D.Strings[55649]="正好是你要求的时间！我想知道农夫老愚会什么时候通知我。你先走，今天市集的生意结束后，我会在那里和你会合。"
D.Strings[55650]="日歌农场需要我帮忙吗？今天市集的生意结束后，我会在那里和你会合。"
D.Strings[55651]="如果只待一小会儿，我想这些小鸡是不会介意的。今天市集的生意结束后，我会在那里和你会合。"
D.Strings[55652]="也许我可以暂时将事情交给蒙蒙来做，然后去老愚那里看一看。但是，我得先完成今天在市集上的生意。"
D.Strings[55653]="真的吗？整个池塘都是我的了？在我喝完这杯酒之后……我会在那里……嗝！"
D.Strings[55654]="好了，我想我又可以在去农场的路上活蹦乱跳了。但我还不能马上这么做。我有些要先在市集上完成的生意。"
D.Strings[55655]="我一直在想你什么时候会问起。一定的，但不是今天。一旦市集上的生意做完，我就会过去！"
D.Strings[55656]="我爸爸经常告诉我要在危难之际帮助邻居！我得先去市集上办一些事情才行。我会尽快过去的。"
D.Strings[55657]="当然，我想我能帮到你一些事情！我今天不能马上离开市集，不过我会尽快去那里的。"
D.Strings[55658]="好的，老板！吱吱今天在市集上有些事情要办，然后他会很快去那里的。"
D.Strings[55659]="一个蜥蜴人抱着一些宝藏逃到了隐藏的阶梯下面！"
D.Strings[55660]="不是所有的英杰都因为身手矫健而被选中的，唤醒者。"
D.Strings[55661]="多美的生物啊，你不觉得吗？别被它的小身材给骗了。恐虫在幼年时期也有着致命的杀伤力。$b$b在我的发现之前，恐虫只被当做武器，几乎无人关注它们的智力。我们竭力控制它们，直到我突然意识到，我们对它们的了解还远远不够。$b$b通过与这个物种建立起纽带，我们不再需要对其强行施加控制，而是形成一种伙伴关系。$b$b科沃克将是我的下一个实验对象。"
D.Strings[55662]="$n被困在琥珀监牢！释放他们！"
D.Strings[55663]="|TInterface\\Icons\\inv_sword_2h_mantid_01.blp:20|t风领主梅尔加拉克开始施放|cFFF00000|Hspell:122407|h[刃雨]|h|r！"
D.Strings[55664]="风领主梅尔加拉克察觉到4个以上的盟友丧失了能力，并释放了他们！"
D.Strings[55665]="巨兽！！"
D.Strings[55666]="我们要警告其他人！"
D.Strings[55667]="守卫土地精可不是我梦想的职业，不过他们给的报酬倒是不错。此外在山路上你会遇见很多奇怪的事情。"
D.Strings[55668]="你来自低地？我们没怎么见过来自低地的人会走这条路。"
D.Strings[55669]="什么风把你吹到山上来了？"
D.Strings[55670]="土地精经常有影踪派守护在其左右。我猜在蟠龙脊上一定有危险。"
D.Strings[55671]="你听说过煞魔吗？在风里，我们经常听到它的声音。不妙。大事不妙。"
D.Strings[55672]="高山猢狲正在肆虐。在这条路上行走要多加小心。$b$b迟早他们会发现影踪派不在这里，并会向我们追赶而来。"
D.Strings[55673]="有一次，在土地精集市我看到了一个奇怪的生物。看上去像一只蹲着的锦鱼人，但是他脾气很坏，口中叫嚷着“呒啊噶呒啊呒啊噶呒噶呒噶”。$b$b我猜是某个土地精把他从海岸线那里带过来的。"
D.Strings[55674]="影踪派最近并没有走过这条路。这可不太好。$b$b我们猜想还有几年的时间，才会遇到螳螂妖再次蜂拥而至。"
D.Strings[55675]="你真是太好了，$n。"
D.Strings[55676]="亲爱的，你对我太好了！"
D.Strings[55677]="你还想着我真是太好了，亲爱的。"
D.Strings[55678]="颜色真红！你不知道这是我最喜欢的颜色吗？"
D.Strings[55679]="哦天啊，太漂亮了。你怎么知道我喜欢珠宝？"
D.Strings[55680]="谢谢你，$n。女孩子总是觉得自己少一颗红宝石。"
D.Strings[55681]="你可以不用这样的！但是我很高兴你这么做了。"
D.Strings[55682]="你不就是一个$G甜心:宝贝;吗？"
D.Strings[55683]="胡说什么，你要宠坏我了！"
D.Strings[55684]="|TInterface\\Icons\\inv_misc_uncutgemnormal.blp:20|t$n被困在一个|cFFF00000|Hspell:121881|h[琥珀监牢]|h|r里！"
D.Strings[55685]="我是一个不善于表达自己感情的人，不过谢谢你。"
D.Strings[55686]="谢谢你，$c。你让我感到很荣幸。"
D.Strings[55687]="谢谢你，$n。我欠你一个人情。"
D.Strings[55688]="你太好了，$c。我该怎么报答你呢？"
D.Strings[55689]="不用了，$c。是我应该谢谢你才对。"
D.Strings[55690]="一直在追那些敌人，我一个女孩子家还真是有点饿了。谢谢你。"
D.Strings[55691]="噢，看起来很好吃。谢谢你，$c。"
D.Strings[55692]="嗯……战士应该要学会保持自己的体力。谢谢你。"
D.Strings[55693]="警戒是一刻也不能掉以轻心的，但我始终会腾出时间吃顿热饭的！"
D.Strings[55694]="我可以吃吗？我想只有一个办法才知道答案……"
D.Strings[55695]="你的感知力正在延伸。集中默念你要找的人。那位小王子——那头小狮子。他穿越时空……打开你的心眼。看见他了吗？"
D.Strings[55696]="嗯……这会给我一些提示，以便我专注于下一次预测。"
D.Strings[55697]="这是很整洁，$n。谢谢你，哥们。"
D.Strings[55698]="我非常喜欢这里，$n。谢谢你。"
D.Strings[55699]="谢谢你这么为我着想，哥们。只有你才会这样想着我。"
D.Strings[55700]="你太好了，$G女士:先生;……嗝！"
D.Strings[55701]="这些苹果看起来很好吃。谢谢！"
D.Strings[55702]="这个苹果是给我的吗？谢谢！"
D.Strings[55703]="那是什么？西红柿？石榴吗？噢！是苹果！"
D.Strings[55704]="那是苹果吗？见到我你一定很高兴……嗝！"
D.Strings[55705]="哦，它看起来很好吃。它搭配我的冷饮一起吃会很不错。"
D.Strings[55706]="一个神谕者需要食物才能预见未来。谢谢！"
D.Strings[55707]="我家族以前常常做这个……现在他们都走了，但是我还是喜欢这道菜。"
D.Strings[55708]="哦，你不用这样的。谢谢。"
D.Strings[55709]="但是我没有什么可以给你的。哪里哪里，还是要谢谢你。"
D.Strings[55710]="你真是太好了，$r。"
D.Strings[55711]="我猜我可以用它们中的一个。谢谢你。"
D.Strings[55712]="我不值得拥有这么好的东西。我想你会坚持。"
D.Strings[55713]="我不能拒绝，但你可以。谢谢，$r。"
D.Strings[55714]="我的儿子之前喜欢收集这些羽毛。"
D.Strings[55715]="这些羽毛让我回忆起我的儿子。谢谢你，$r。"
D.Strings[55716]="我的儿子很喜欢这些羽毛，因为它们像天空一样蓝。他总是说，他总有一天要飞翔。"
D.Strings[55717]="谢谢你，$n。我儿子原本喜欢见到这个。"
D.Strings[55718]="非常好，$n。谢谢你。"
D.Strings[55719]="你一定是个厨艺不错的人，$n。这看起来非常漂亮。"
D.Strings[55720]="谢谢你为一个孤独的老人着想，$n。"
D.Strings[55721]="你可以不用这样的！"
D.Strings[55722]="哦，嚯嚯，这是给我的吗？谢谢你。"
D.Strings[55723]="你的确知道怎么让一个熊猫人开心。谢谢。"
D.Strings[55724]="你真是慷慨。谢谢！"
D.Strings[55725]="这件礼物还不错。谢谢，$n。"
D.Strings[55726]="我期待下次还有更好的东西，$r。谢谢。"
D.Strings[55727]="这是相当不错的礼物，$n！非常感谢。"
D.Strings[55728]="逃跑或者被烧焦！"
D.Strings[55729]="虎肉排？这是我的最爱！你怎么知道的？"
D.Strings[55730]="他们说，通往阡陌客最近的道路是首领的食道？"
D.Strings[55731]="我们会燃焦你们的土地！"
D.Strings[55732]="你胆敢面对野牛人的烈焰？！"
D.Strings[55733]="你当然知道如何讨女孩喜欢！谢谢！"
D.Strings[55734]="你想得到我的青睐，不是吗，$r？嗯，对你来说有好处！"
D.Strings[55735]="死亡！拥抱你的命运！"
D.Strings[55736]="如果你再这样做的话，我就不得不喜欢上你了！"
D.Strings[55737]="你无法逃脱命运！"
D.Strings[55738]="这是给上了些年纪的吉娜的礼物吗？你真是太好了。"
D.Strings[55739]="好，就为这个，你可以随时来我的市集。"
D.Strings[55740]="你给我的礼物真是太好了。谢谢你。"
D.Strings[55741]="这朵漂亮的花是给我的吗？噢，等等。"
D.Strings[55742]="这花真漂亮。谢谢，$n。"
D.Strings[55743]="你是怎么知道我喜欢花的？"
D.Strings[55744]="你无法经受住野牛人的烈焰！！"
D.Strings[55745]="你会自己做迷雾汤吗？它闻起来很香。"
D.Strings[55746]="你们会与你们的土地一起被燃焦！"
D.Strings[55747]="有两种方式可以赢得吉娜的芳心，你知道是什么吗？一个是成为我市集的常客，另一个是迷雾汤！"
D.Strings[55748]="噢，看起来很好吃。谢谢你，$n。"
D.Strings[55749]="这个礼物太好了，$r。谢谢你。"
D.Strings[55750]="我怎样才能报答你的好意呢？"
D.Strings[55751]="嘿，你毕竟还不是那么糟糕，$r。"
D.Strings[55752]="我开始喜欢上你了，$r。"
D.Strings[55753]="你一直这样的话，我也只好告诉你我种出这么多蔬菜的秘密。"
D.Strings[55754]="这烤肉看起来很好吃。但愿是你自己做的。"
D.Strings[55755]="一点也不像是自己烤的！好吃！"
D.Strings[55756]="现在这是我们的土地！"
D.Strings[55757]="我妈妈总是跟我说，这些花象征好运。"
D.Strings[55758]="这些是野牛人的土地！"
D.Strings[55759]="你真是太好，送如此幸运的花给我。"
D.Strings[55760]="我们宣布你们的土地归我们所有！"
D.Strings[55761]="有些人可能会问我为什么这么喜欢花。我只是在欣赏这片土地的美丽。"
D.Strings[55762]="你确定，$n？哇，谢谢你！"
D.Strings[55763]="啊，再次把盐放进旧皮草的感觉很好。"
D.Strings[55764]="噢，不好，我没有给你任何东西作为回报！嘘……"
D.Strings[55765]="是的，太好了，$n。我很高兴认识像你这样的人。"
D.Strings[55766]="噢，我的爸爸总是说，这些小猫图形是象征好运！"
D.Strings[55767]="翡翠是好运的象征，你不知道吗？谢谢你把它送给我。"
D.Strings[55768]="拥有一小块翡翠就可以辟邪。非常感谢你送我这只小猫咪！我知道，它会保佑我平安。"
D.Strings[55769]="噢，你真是太客气了，$n。"
D.Strings[55770]="你真是太好了，还能想到我。"
D.Strings[55771]="我们的家园被人侵占了！所以我们要抢占你们的！"
D.Strings[55772]="在汇风岭的所有这些人之中，你把它送给我了吗？我甚至不知道该说什么，这是我莫大的荣幸。"
D.Strings[55773]="你是怎么知道我喜欢猫的？"
D.Strings[55774]="噢，不错礼物的送给吱吱！谢谢你！"
D.Strings[55775]="给吱吱的吗？你可以不用这样的！"
D.Strings[55776]="吱吱喜欢礼物！谢谢你！"
D.Strings[55777]="给吱吱的羽毛吗？谢谢你。"
D.Strings[55778]="老板……这个真不错。谢谢你。"
D.Strings[55779]="你太酷了，老板。谢谢你！"
D.Strings[55780]="我们新牧场的又一个奴隶！"
D.Strings[55781]="你胆敢挑战野牛人吗？"
D.Strings[55782]="你知道吗，我看见她了。$B$B玛祖。海之女神。$B$B我人生中最猛烈的风暴。我那时候年轻，而且缺乏经验。我从船上跌进海里。到处都是漆黑一片，我完蛋了。$B$B然后她出现在我面前，像夏天的午后一样清新。那样的美丽是你无法想象的，她的脖子上戴着贝壳，臀部挂着一串串的珍珠。她微笑着并且伸出纤细的手臂。$B$B然后我只记得，狗把我背在背上，并且船员拉我上了船。之前从未见过他，船员都说不知道他是从哪里冒出来的。但我知道他从哪里来。"
D.Strings[55783]="这里现在是我们的牧场。"
D.Strings[55784]="投降！"
D.Strings[55785]="不要……！咩咩羊！"
D.Strings[55786]="面对你的命运！"
D.Strings[55787]="祝你的朋友好运！"
D.Strings[55788]="啊！一次挑战！"
D.Strings[55789]="害怕野牛人的愤怒！"
D.Strings[55790]="你和吱吱成了熟人。"
D.Strings[55791]="吱吱是你的哥们了。"
D.Strings[55792]="吱吱是你的朋友了。"
D.Strings[55793]="你和吱吱已经成了好友。"
D.Strings[55794]="你和吱吱已经成了挚友。也许你可以和他聊聊，看他是否愿意为农场帮帮忙。"
D.Strings[55795]="你和艾拉是哥们了。"
D.Strings[55796]="你和艾拉是朋友了。"
D.Strings[55797]="你和艾拉已经成了好友。"
D.Strings[55798]="你和艾拉已经成了挚友。也许她会愿意帮助农夫老愚一阵子。"
D.Strings[55799]="你是玉儿的哥们了。"
D.Strings[55800]="你是玉儿的朋友了。"
D.Strings[55801]="你和玉儿已经成了好友。"
D.Strings[55802]="你和玉儿已经成了挚友。凭借她对动物的了解，她或许能帮你解决农场里的问题。"
D.Strings[55803]="不知不觉之中，你和农夫老方已经成了哥们。"
D.Strings[55804]="不知不觉之中，你和农夫老方已经成了朋友。"
D.Strings[55805]="不知不觉之中，你和农夫老方已经成了好友。"
D.Strings[55806]="不知不觉之中，你和农夫老方已经成了挚友。他或许乐意帮助日歌农场。"
D.Strings[55807]="你和吉娜是哥们了。"
D.Strings[55808]="你和吉娜是朋友了。"
D.Strings[55809]="你和吉娜已经成了好友。"
D.Strings[55810]="你和吉娜已经成了挚友。她乐于插手别人的事，所以，毫无疑问她会在农场上花些时间的。"
D.Strings[55811]="你和郝瀚是哥们了。"
D.Strings[55812]="你和郝瀚是朋友了。"
D.Strings[55813]="你和郝瀚已经成了好友。"
D.Strings[55814]="当你和郝瀚成为挚友时，毫无疑问他这个阡陌客的首领会向你伸出援手给予帮助。"
D.Strings[55815]="你和醉鬼贾古是哥们了。"
D.Strings[55816]="你和醉鬼贾古是朋友了。"
D.Strings[55817]="你和醉鬼贾古已经成了好友。"
D.Strings[55818]="你和醉鬼贾古已经一起经历了那么多收获季。除了他还有谁会是你农场的一笔财富？"
D.Strings[55819]="你和老农山掌是哥们了。"
D.Strings[55820]="你和老农山掌是朋友了。"
D.Strings[55821]="你和老农山掌已经成了好友。"
D.Strings[55822]="你为老农山掌做了这么多，这个老家伙可能正在怀念有你陪伴的时光。你应该叫他来农场帮助。"
D.Strings[55823]="你和阿烁是哥们了。"
D.Strings[55824]="你和阿烁是朋友了。"
D.Strings[55825]="你和阿烁已经成了好友。"
D.Strings[55826]="你已经向阿烁证明了你自己。她说如果你在任何时候需要帮助，她都会义不容辞。你可以请她来帮你照看庄稼。"
D.Strings[55827]="你和迪娜是哥们了。"
D.Strings[55828]="你和迪娜是朋友了。"
D.Strings[55829]="你和迪娜已经成了好友。"
D.Strings[55830]="按照迪娜的说法，你和她已经成了挚友。她或许会很乐意造访你的农场。"
D.Strings[55831]="风刃火速前往救助他们被困的盟友！"
D.Strings[55832]="欢迎，我年轻的朋友。"
D.Strings[55833]="海象人如何来到潘达利亚的？"
D.Strings[55834]="我的$c朋友，是时候谈些其他事情了。比如螃蟹和海洋，海龟和树木……"
D.Strings[55835]="我的$r朋友，是时候谈些其他事情了。比如猢狲和土地精，还有我的肚子饿了……"
D.Strings[55836]="我的小朋友，是时候谈些其他事情了。比如魔古族和巨魔，或者锦鱼人的河流通行费……"
D.Strings[55837]="我的傻朋友，是时候谈些其他事情了。比如雪人和牦牛，或者随机的鲨鱼袭击事件……"
D.Strings[55838]="不要惊慌，$n。$B$B我将梦中的自我投射在这里，以便帮助你对抗魔古族。"
D.Strings[55839]="她真漂亮，不是吗？几年前它被捞出来，它看起来就像她一样……改天问我关于它的事情。"
D.Strings[55840]="没关系。"
D.Strings[55841]="你好，$r！今天你想听什么音乐？"
D.Strings[55842]="闷水壶，告诉我关于雕像的事。"
D.Strings[55843]="你能为我演唱一曲吗？"
D.Strings[55844]="我想听《为你祝酒》。"
D.Strings[55845]="我想听《欢乐庆典》。"
D.Strings[55846]="我想听《翠竹旷野》。"
D.Strings[55847]="我想听《刘浪之歌》。"
D.Strings[55848]="我想听《刘浪回乡》。"
D.Strings[55849]="我想听《五晨寺》。"
D.Strings[55850]="我想听《卡斯特梅的雨季》。"
D.Strings[55851]="风领主梅尔加拉克察觉到一个盟友丧失了能力，并释放了他们！"
D.Strings[55852]="风领主梅尔加拉克察觉到2个以上的盟友丧失了能力，并释放了他们！"
D.Strings[55853]="给你又找到了一个！"
D.Strings[55854]="谢谢，随便放在哪里都行。"
D.Strings[55855]="你洗礼了古·穿云的灵魂，影踪派感谢你。"
D.Strings[55856]="雪流大师高度赞扬你在战斗中的表现。"
D.Strings[55857]="祝踏岚领主已经出城墙向西追捕恨之煞。我希望他追捕顺利。"
D.Strings[55858]="恨之煞不能再以我们的人民相威胁了，这多亏有你。我们感谢你。"
D.Strings[55859]="再次问候，$c。我一直在注视着你。"
D.Strings[55860]="你的武术技能无人能比。我还有很多想向你学习。"
D.Strings[55861]="你的确是武术格斗的高手。你的到来是我的荣幸。"
D.Strings[55862]="舒对我们而言非常重要。我们需要找到他，但是他各方面更趋向于小孩子，所以我们绝不能用我们的方法吓唬他。$B$B我会想想他可能待的地方，以及怎么样接近他最合适。耐心等待，我的朋友。"
D.Strings[55863]="对涓流要有耐心。他的行为举止也许像个孩子，实际上却是古老而强大的生灵。"
D.Strings[55864]="卖苹果！卖新鲜的苹果！"
D.Strings[55865]="四风谷里最大、最多汁、最可爱的苹果！就在这里！"
D.Strings[55866]="来买苹果喽！每天都闻苹果香，不用牧师开药方！"
D.Strings[55867]="这么说，你不过是想……我不知道……滚着玩还是怎么样？"
D.Strings[55868]="等等……它在动？"
D.Strings[55869]="我猜你知道刚才发生了什么？"
D.Strings[55870]="其实，算了——我并不想知道。我要回去了。"
D.Strings[55871]="朋友，你要吃苦头了。"
D.Strings[55872]="朋友，你阻挡不了赞达拉人。"
D.Strings[55873]="好。我的迅猛龙饿了。"
D.Strings[55874]="你现在面对的是赞达拉人。而不是一些暗矛部族的叛徒。"
D.Strings[55875]="你惹了不该惹的巨魔。"
D.Strings[55876]="小心选择你的阵营，兄弟。"
D.Strings[55877]="这里就是你的葬身之地。"
D.Strings[55878]="赞达拉人将会东山再起。"
D.Strings[55879]="朋友，你阻挡不了我们。"
D.Strings[55880]="颤抖吧，不知悔改的人们！蝗虫已经苏醒了！"
D.Strings[55881]="你将成为我下一个战利品。"
D.Strings[55882]="赞达拉人将重建昔日的光辉岁月。"
D.Strings[55883]="你无法打败联手的赞达拉巨魔和魔古族！"
D.Strings[55884]="呃……<咳嗽>暴食蝗没事儿！<咳嗽><咳嗽>"
D.Strings[55885]="卡拉克西召唤……"
D.Strings[55886]="新鲜的面包啊！"
D.Strings[55887]="看起来你在水中没什么不妥的啊。继续这样干。"
D.Strings[55888]="全是关于那些君王蟹的事情。亲爱的，他们就是蓝色黄金。"
D.Strings[55889]="风领主梅尔加拉克调遣援兵了！"
D.Strings[55890]="在闷水壶带我们偏离了原始的航向后，我们就在这里失事了。他以为能把我们当傻子耍。哈哈！$B$B说实话，我们很乐意看他尝试这么去做。我们每个人都不是“泛泛之辈”。"
D.Strings[55891]="欢迎来到半山市集，$r。"
D.Strings[55892]="欢迎来到半山市集，这里的价格一直很公道！"
D.Strings[55893]="好久不见了，$n。欢迎回来。"
D.Strings[55894]="你需要喝点什么，$r？"
D.Strings[55895]="你今天想喝点什么，$n？"
D.Strings[55896]="干着农活肯定让你很渴吧，$n？"
D.Strings[55897]="我要向你挑战。"
D.Strings[55898]="不可思议的事情发生了——我们对塞拉摩的围攻失败了。"
D.Strings[55899]="米线！我告诉你不要放这么多调料嘛！"
D.Strings[55900]="喔喔，米线，你在汤里放的什么啊？"
D.Strings[55901]="嗯。这汤味道不错。干得好，米线！"
D.Strings[55902]="这么说，你准备开始了？让我们看看你有什么能耐。"
D.Strings[55903]="应急计划由你前去执行。你的任务是混进塞拉摩岛。"
D.Strings[55904]="欢迎来到我的地盘，$c。$B$B现在，让我们教训教训这些螳螂妖！"
D.Strings[55905]="啊，只差一点。你得守住本心。要在这里生存下去，平和的心态是关键。来，再试一次！耐心也是熊猫人的美德。"
D.Strings[55906]="让火花保持在中间位置！"
D.Strings[55907]="不要被攻城车发现。"
D.Strings[55908]="你面前有一只猢狲！赶紧跳开，摆脱它！"
D.Strings[55909]="天呐！急迫的形势坚定了你的决心。我在这儿的任务已经完成了。"
D.Strings[55910]="参加酒仙场景战役的人可赢得勇气。要是你在与酒仙一同冒险时发现任何罕见物品，尽管将其收入囊中！"
D.Strings[55911]="潘达利亚地区最大的酿酒厂是四风谷的风暴烈酒酿造厂。如果你想冒险，可以从那里开始。$B$B酒仙实质上也是游荡者，并且他们经常四处闲逛，寻找稀有原料或调配新酒。$B$B这些酒仙通常会出现在独特的场景战役里。$B$B酒仙曲子在绿石村场景战役中抵御敌人。$B$B珀酒仙在盎迦猴岛场景战役中寻找热带配料。$B$B酒仙布夫在酿月祭场景战役中欢庆佳节，酒仙布兰琪在酝酿风暴场景战役中准备让人大吃一惊。"
D.Strings[55912]="帮助酒仙有奖励吗？"
D.Strings[55913]="我在哪里可以找到可能需要帮助的酒仙？"
D.Strings[55914]="你今天想帮助哪个酒仙？"
D.Strings[55915]="排队等待酝酿风暴场景战役。"
D.Strings[55916]="东西都弄到了吗？很好！跟我来"
D.Strings[55917]="排队等待酿月祭场景战役。"
D.Strings[55918]="要想靠洄梦仙酒找到你想找的东西，那你必须保持祥和的心境。我来演示给你看。"
D.Strings[55919]="排队等待盎迦猴岛场景战役。"
D.Strings[55920]="排队等待绿石村场景战役。"
D.Strings[55921]="先把酒喝了，朋友。"
D.Strings[55922]="告诉我相关场景战役的更多信息：酝酿风暴。"
D.Strings[55923]="告诉我相关场景战役的更多信息：盎迦猴岛。"
D.Strings[55924]="告诉我相关场景战役的更多信息：酿月祭。"
D.Strings[55925]="告诉我相关场景战役的更多信息：绿石村。"
D.Strings[55926]="酒仙布兰彻努力在暴风雨中制造闪电陈酿，但是受到了一些难缠敌人的阻碍。"
D.Strings[55927]="我将返回卡拉克西维斯会见议会。请照顾好科沃克。"
D.Strings[55928]="让我们看看你赞不赞成那种说法。"
D.Strings[55929]="把绿石村村民从那些顽皮（和危险）的森林居民手中解救出来。"
D.Strings[55930]="酿造一些美酒，抵挡野牛人的袭击。"
D.Strings[55931]="<腾武打哈欠。>\n\n我正在等待……"
D.Strings[55932]="滚开，这些粗野的螃蟹！"
D.Strings[55933]="把你喂给乌鸦！"
D.Strings[55934]="如果帮助垂钓翁，我能得到些什么好处？"
D.Strings[55935]="我可以在哪里找到垂钓翁？"
D.Strings[55936]="卡桑琅丛林东南部的渔人码头最适合垂钓了。欢迎大家来访垂钓！"
D.Strings[55937]="你问我你能从中得些什么好处，这么说是什么意思呢？那是个什么问题？$B$B难道从海里钓到大鱼还不够快乐吗？那么阳光照在你的脖子上，感觉怎么样呢？咸咸的海水飞洒到你的脸上，感觉怎么样呢？和朋友闲坐在一起，喝一杯冷啤感觉怎么样？$B$B这还不够吗？！？$B$B让我告诉你吧，$G渔夫:渔妇;的生活简直无与伦比！$B$B你可以从头学习提高钓鱼技能。获得足够的技能，你就可以购买功能强大的钓竿。$B$B倍受尊重的渔夫可以获得特殊的鱼类宠物和水黾坐骑，甚至还有自己专用的捕鱼木筏！"
D.Strings[55938]="你好，$r。$B$B我一眼就能看出你是位伟大的冒险家。$B$B在这片土地上，到处都是漆黑的地穴和广阔的宫殿，里面充满既可怕又强大的敌人。他们守着许多秘密，可是……高风险也意味着高收益。$B$B英雄中的佼佼者可以去试试身手，但千万要多加小心！你要跟时间赛跑，还要和其他英雄比拼技能。$B$B你愿意接受挑战吗？"
D.Strings[55939]="哦，我应该从哪里说起呢？！$B$B首先，农夫需要播种和收获庄稼。你出售的庄稼可以用于烧饭、拍卖出售、卖给其他买家，或者换购肉和鱼。我还听说，农夫可以种植一些稀有种子以获得特殊物品……甚至有可能是珍贵的宠物！$B$B接下来，还有整个半山供你探索！要想与当地人做朋友，最好的办法就是送他们礼物，而一旦你们成为朋友，他们就会给你一些不错的礼物作为回馈。$B$B田里一直有许多工作要做，多个人帮忙总是好的。"
D.Strings[55940]="嗯，阡陌客不会让你变得富有，而且也不会让你变强大以应付战事。$B$B不是这样的，农夫的生活略有不同。$B$B如果你坚持这样的生活，你会遇到一些非常有趣的人。你可以建立自己的农场、种植自己的庄稼，并且享受自己的劳动果实。$B$B所以，如果你感兴趣的话，就亲自去半山看看！"
D.Strings[55941]="我为什么应该帮助阡陌客？"
D.Strings[55942]="我可以和阡陌客一起做什么事？"
D.Strings[55943]="云端翔龙骑士团发誓保卫翡翠林。我们在翡翠林青龙寺正北面的百木园进行训练。"
D.Strings[55944]="在云端翔龙骑士团中获得晋升是一种莫大的荣耀。$B$B一旦证明了自己，你就能把翔龙当成飞行坐骑，任意驰骋。$B$B你还能学会骑乘云端翔龙的技能，可以骑乘潘达利亚的任何一条云端翔龙。"
D.Strings[55945]="一旦进入云端翔龙骑士团，你就可以利用翔龙坐骑开始一段旅程。$B$B你可以孵化一头幼小的翔龙，每天培训它，看着它长大成年。"
D.Strings[55946]="加入云端翔龙骑士团意味着什么？"
D.Strings[55947]="在云端翔龙骑士团中获得晋升会有什么奖励？"
D.Strings[55948]="玛祖对我很好。她用水使我维持生命，并且她用风将我带到遥远的地方。人生如此，夫复何求？"
D.Strings[55949]="需要幸运女神的眷顾么，$r？人人都要借助好运来让自己心想事成！$B$B别急，我能帮你扭转颓势！"
D.Strings[55950]="青龙玉珑，在东边担任警戒。很不幸，青龙寺已经落入疑之煞的魔掌。$B$B尽管如此，寺庙还是需要我们的帮助。我们必须尽全力将疑之煞困在港湾中！"
D.Strings[55951]="现在那里是一片和睦气象！"
D.Strings[55952]="白虎雪怒顶着寒冷的北风担任守卫工作。$B$B今天，雪怒试图通过列一系列比赛找到该地区最出色的勇士。$B$B如果你相信自己的能力，就北行至白虎寺，迎接挑战！"
D.Strings[55953]="玄牛砮皂将敌人阻挡在城墙之外。$B$B他也非常需要帮助，以击退渐渐入侵的螳螂妖。$B$B如果你想提供帮助，就西行至螳螂高原上的寺院。"
D.Strings[55954]="保护这四座寺庙，你就会受到至尊天神的褒奖，得以购买功能强大的物品。$B$B此外，你还可以提供帮助，保护这片土地免受强敌的攻击。"
D.Strings[55955]="我为什么要帮助至尊天神？"
D.Strings[55956]="我现在如何帮助至尊天神？"
D.Strings[55957]="锦绣谷正处于危难当中，$r。$B$B加尔鲁什·地狱咆哮用一件来自上古邪神的黑暗神器——亚煞极之心污染了这座圣谷中的水流。而他的恶行所造成的后果……呃……你也已经看见了。$B$B现在，煞魔余孽已经威胁到了我们的生存。我们别无选择，必须战斗。"
D.Strings[55958]="当然。我们应该奖励那些冒死护谷的人。$B$B通过帮助保护锦绣谷，你不仅可以使边界安宁，而且还能获得我们浩如烟海的强大珍宝。"
D.Strings[55959]="帮助护谷我会得到奖励吗？"
D.Strings[55960]="我如何才能帮助金莲教？"
D.Strings[55961]="请带我飞到扎尼维斯去。"
D.Strings[55962]="请带我飞到凯帕圣树·扎尔去。"
D.Strings[55963]="要想赢得我们的尊重，有以下几种办法。$B$B我们现正在昆莱山的火树村应对邪煞的攻势。帮助我们，你就能在我们的门徒间占得一席之地。$B$B影踪禅院也遇到了麻烦。你或许能帮帮我们在那里的兄弟姐妹。$B$B怒之煞在北面的昆莱旷野上横行。将它击败，你就能在我们的成员当中树立威信。$B$B最后，一支影踪分遣队被派往螳螂高原追击恨之煞。他们或许也需要帮助。$B$B如果你希望赢得我们最高的敬意，你必须证明自己，与金莲教的关系要先达到崇敬。然后，再到螳螂高原的影踪卫戍营来找我的兄弟姐妹们谈谈。"
D.Strings[55964]="我为什么应该帮助影踪派？"
D.Strings[55965]="我如何才能帮助影踪派？"
D.Strings[55966]="游学者将派你到潘达利亚的重要地区，以收回当地的文化神器。$B$B一旦找到属于一个系列的所有神器，你就可以听完整个故事的来龙去脉。$B$B找到所有文化神器，收集所有图书，变成一个游学者！$B$B如果你觉得有趣，就闻道之座的游学者周卓交谈。"
D.Strings[55967]="旅途本身就是馈赠，年轻人。在故事中寻找快乐，你就会得到无与伦比的财富。$B$B对了，还有件事。在游学者中地位升高的人还能获得特殊的礼物——驾云而行的能力。"
D.Strings[55968]="我为什么应该帮助游学者？"
D.Strings[55969]="我如何才能帮助游学者？"
D.Strings[55970]="我刚刚从城墙那边回来。$B$B我在那边听说了一些关于卡拉克西螳螂妖的谣言。据说他们来自蟠龙脊之外，可能是从螳螂妖帝国分裂出来的螳螂妖长老议会。如今他们正公然违抗螳螂妖女皇的命令。$B$B我亲眼见识了这些螳螂妖的法力。$B$B如果这些谣言可信，我们就有可能找到一条途径联合这些……卡拉克西……并和他们共同阻止螳螂妖虫群。"
D.Strings[55971]="这对我来说是个难解之谜，$r。如果你想找到他们，你就太傻、太疯狂了！$B$B但是我认为遇见卡拉克西的唯一途径是冒险越过这座城墙，到达恐惧废土。"
D.Strings[55972]="帮助卡拉克西有什么奖励？"
D.Strings[55973]="我如何才能帮助卡拉克西？"
D.Strings[55974]="它在这里！"
D.Strings[55975]="季已经把焰火准备好了。点燃它们，朝空中发射。"
D.Strings[55976]="你跑的真快。加油！"
D.Strings[55977]="这么做就对了！"
D.Strings[55978]="你做到了！就现在，趁它倒地时展开攻击。"
D.Strings[55979]="它掉下来了！打败它！"
D.Strings[55980]="太棒了！希望有一天能够和你并肩作战。"
D.Strings[55981]="我骑牦牛来。如果买幸运符是足够明智的，那么我把物品卖给他们就再好不过了。"
D.Strings[55982]="我让幸运符更加幸运。给我一个物品，我将改变它的命运，从而更好地为你服务……要付费啊。"
D.Strings[55983]="我们正在围攻砮皂寺。$B$B我们知道你是谁，$n。我们需要你再帮一把。"
D.Strings[55984]="我已经给你一头牦牛了！"
D.Strings[55985]="锦绣谷是什么？"
D.Strings[55986]="我们和螳螂妖、野牛人和魔古族作战。敌人从四面八方涌来。\n\n我来这儿是为了确保没有意外。"
D.Strings[55987]="杀啊……冲锋！"
D.Strings[55988]="且慢……蠢货！"
D.Strings[55989]="噢——你当然没有听说过锦绣谷。$b$b一万两千年前，它是魔古大军的基地，也是魔古帝国的心脏。传说那里有圣池，这是魔古法力的源泉。魔古族可以借助于魔古法力扭曲和改变肉身。但圣池也可以用于治愈神迹。这要看你是否相信传说。$b$b在熊猫人革命之后，天神同意封印锦绣谷，这样就无法滥用圣池的法力了。"
D.Strings[55990]="我将踏平你的树林！"
D.Strings[55991]="你已是我的盘中餐了！"
D.Strings[55992]="和乌克一起去烹饪！"
D.Strings[55993]="蠢蛋炖肉，就要端上来了！"
D.Strings[55994]="狂欢时间到！"
D.Strings[55995]="那蠢货要倒霉了！"
D.Strings[55996]="跳吧，蠢货！跳吧！"
D.Strings[55997]="啪啪，砰！"
D.Strings[55998]="啪啪啪啪，嘭！"
D.Strings[55999]="那小子要被痛扁一顿了！"
D.Strings[56000]="给你一个礼物。"
D.Strings[56001]="说“你好”然后“再见”！"
D.Strings[56002]="现在谁在锦绣谷？"
D.Strings[56003]="你的思想被|cFFFF0404|Hspell:124862|h[死亡幻象]|h|r感染了！"
D.Strings[56004]="几乎没人。由被称为“金莲教”的组织担任护卫。天神钦定金莲教人在锦绣谷担任警戒，但人数不多。$b$b打我小时候起，我就听过锦绣谷的故事。你相信这个地方真的存在吗？$b$b你认为圣池的传说是真的吗？我希望我可以亲眼见识一下！"
D.Strings[56005]="那到底是什么东西？"
D.Strings[56006]="噢！你不会那么容易抓到我的人。"
D.Strings[56007]="你忘了你是和谁在对着干吗？"
D.Strings[56008]="让我给你示范一下奈辛瓦里人是怎么狩猎的！"
D.Strings[56009]="好还是坏，我手里拿着枪我说了算。"
D.Strings[56010]="任何人不准惹我的人！"
D.Strings[56011]="把脏东西从我的人的头上拿开！"
D.Strings[56012]="注意那些雾瘴！那东西看起来有毒。"
D.Strings[56013]="注意这个昏暗的地方。小心！"
D.Strings[56014]="你知道那是啥东西吗？"
D.Strings[56015]="下次去打猎的时候，蒙住你那发光的眼睛。不然就会暴露你的位置。"
D.Strings[56016]="瞄准眼睛！"
D.Strings[56017]="不要站在射击范围内。"
D.Strings[56018]="干得好。$B$B没有你，我们就无法成功。"
D.Strings[56019]="此时此刻，锦绣谷不需要再做什么事情了，$n。你杀死魔古部落首领之后，魔古族就立马土崩瓦解了。我们现在安全了，谢谢你。"
D.Strings[56020]="烧毁他们的船只，杀掉飞行管理员，破坏战争机器。同时保证我方间谍的安全！"
D.Strings[56021]="扰乱他们，让我们重新部署。地狱咆哮的双眼注视着你！"
D.Strings[56022]="季·火掌热烈欢迎你的回归。"
D.Strings[56023]="酒桶破裂了，扑灭了%s的火焰！"
D.Strings[56024]="嗯，阡陌客不会让你变得富有，而且也不会让你变强大以应付战事。$B$B耕田劳作略有不同。$B$B那是一种慢节奏的惬意生活。你问杜凯算是问对人了！$B$B你可以建立自己的农场、种植自己的庄稼，并且享受自己的劳动果实。杜凯最喜欢的就是这个！$B$B所以，如果你感兴趣的话，就亲自去半山看看！"
D.Strings[56025]="哦，杜凯要从哪里说起呢？！$B$B首先，农夫需要播种和收获庄稼。你出售的庄稼可以用于烧饭、拍卖出售、卖给其他买家，或者换购其它东西。我还听说，农夫可以种植一些稀有种子以获得特殊物品……比如小宠物！$B$B另外，你应该去见见半山的每一个人！这里的住民有趣极了，就连像我这样的捣蛋鬼都喜欢他们。你给他们礼物，与他们做好朋友，他们就会用贴心的馈赠来回报你！$B$B在田野周围总有许多事情可做！"
D.Strings[56026]="螳螂妖炮兵在那里，你们要快一点，各位英雄！"
D.Strings[56027]="你问我你能从中得些什么好处，这么说是什么意思呢？那是个什么问题？$B$B难道从海里钓到大鱼还不够快乐吗？那么阳光照在你的脖子上，感觉怎么样呢？咸咸的海水飞洒到你的脸上，感觉怎么样呢？和朋友闲坐在一起，喝一杯冷啤感觉怎么样？$B$B这还不够吗？！？$B$B让我告诉你吧，$G渔夫:渔妇;的生活简直无与伦比！$B$B你可以从头学习提高钓鱼技能。帮助当地人可以获得一些工匠代币。获得足够的技能，你就可以购买功能强大的钓竿。$B$B倍受尊重的渔夫可以使用垂钓宠物和阔步者坐骑。这里竟然还有一个捕鱼木筏，我的天啊！"
D.Strings[56028]="感谢神真子你来了。我需要你帮忙！"
D.Strings[56029]="当它举起武器的时候一定要小心，这一击的威力非同小可。"
D.Strings[56030]="它在召唤援军！我来拖住它，你把增援干掉。"
D.Strings[56031]="它快要被拖垮了。坚持住！"
D.Strings[56032]="没有你我肯定无法做到这些。你来得太及时了。"
D.Strings[56033]="影踪派冰箭手出现在屋顶！"
D.Strings[56034]="我们有幸在大门打开后找到了这片山谷。我们寻求庇护，然后就找到了安全的避风港。$B$B你迷路了吗？我可以帮你什么忙吗？"
D.Strings[56035]="我自己没法做得更好。$B$B嗯，也许不能。"
D.Strings[56036]="船着火了！士兵们，立即回港！"
D.Strings[56037]="拍卖行位于二楼，在你进入的建筑物的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[56038]="银行位于二楼，在你进入的建筑物的右侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[56039]="飞行管理员位于主露台上，就在你进入主楼之前所看到的双楼梯的最上层。$B$B我会在你的地图上标记这个位置。"
D.Strings[56040]="旅店位于主楼层，在你进入建筑物时的右侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[56041]="在你进入主楼之前，可以在主露台上发现兽栏管理员贾许。他站在飞行管理员的旁边。$B$B我会在你的地图上标记这个位置。"
D.Strings[56042]="虚灵的商店开在楼上的走廊里，就在主建筑物进门的右手边。$B$B我会在你的地图上标出位置。"
D.Strings[56043]="雅拉·月落在工匠大厅内兜售试剂，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[56044]="铁针莱绅那漂亮的衣服是众所周知的事情。$B$B她在工匠大厅内工作，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[56045]="克拉拉·亨利携带着附魔物资。你可以在工匠大厅内找到她，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[56046]="啊，来了一位绘卷大师！我想你在寻找墨水和羊皮纸，对吗？在工匠大厅内可以发现他们，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[56047]="是的，城市里有药材供应商。在工匠大厅内可以发现托米·补铲，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[56048]="你正在寻找的药剂师。他配制一些真正神奇的药水和酊剂。立刻使我摆脱了皮疹！$B$B呃哼……绿苔药师在工匠大厅出售他的商品。我会在你的地图上标记这个位置。"
D.Strings[56049]="准备煮一顿热饭吗？你可以在乔乔那找到你所需的一切。她在工匠大厅出售商品。$B$B我会在你的地图上标记这个位置。"
D.Strings[56050]="你可以在工匠大厅内购买采矿用品，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[56051]="我依稀记得在工匠大厅内有一名工程师，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[56052]="皮革加工和皮草？你肯定在寻找一位皮匠。如果我没记错的话，应该在工匠大厅内。$B$B我会在你的地图上标记这个位置。"
D.Strings[56053]="噢，我希望伤势并不严重！治疗者在主大厅内，也就是中央楼梯的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[56054]="珠宝加工？这的确是件精细活儿。你可以从工匠大厅的贝诺那购买物资。$B$B我会在你的地图上标记这个位置。"
D.Strings[56055]="你在寻找食物和饮料吗？如果是的话，客栈的晃碟大厨那儿有你要寻找的东西。$B$B我会在你的地图上标记这个位置。"
D.Strings[56056]="在找啤酒吗？好的，有两名酒仙在城市里徘徊，出售优良的啤酒。$B$B如果你没有遇见他们，夜莺旅馆的哈兰·酒腹或旅店的萨娅·茗流可以帮你安排好一切的。"
D.Strings[56057]="嘴馋想要吃些甜品吗？你需要找到粉牡丹。$B$B她通常在神殿的前露台或正殿徘徊。"
D.Strings[56058]="面包师通常在神殿徘徊。他徘徊在正殿周围或露台上。"
D.Strings[56059]="你需要与米歇尔·扫榻谈谈。他供应充足的肉类。$B$B我会在你的地图上标记这个位置。祝你好运！"
D.Strings[56060]="考虑过引爆一个或两个烟花吗？我应该自己去买些烟花！主露台上可以发现供应商。$B$B我会在你的地图上标记这个位置。"
D.Strings[56061]="虎神，不能相信那些来自迷雾之外的陌生人。翡翠林中的残骸便是最好的证明。"
D.Strings[56062]="一艘飞艇正在逼近，上面装载的弹药足以夷平塞拉摩，炸飞岛上所有人。"
D.Strings[56063]="……我亲眼见过他们：魔古军团正在猛攻锦绣谷。我们可不擅长大规模作战！"
D.Strings[56064]="给我们纠正错误的机会吧。"
D.Strings[56065]="好了。要是你途径银月城，来跟我打个招呼，好吗？祝你好运……"
D.Strings[56066]="你好，旅行者。欢迎光临金色神灯！"
D.Strings[56067]="停下脚步，休息一会，$r。精美的食物和饮料等着你。"
D.Strings[56068]="噢，你看起来很瘦，$r。你必须吃些东西。坐下，我给你拿些吃的东西。"
D.Strings[56069]="在金色神灯，大家吃喝不停，这里是客流不断！你想要些什么吗？"
D.Strings[56070]="欢迎光临谷里最好的旅店——金色神灯。如果有人想跟我争，我就让他尝尝我的拳头。"
D.Strings[56071]="我这里有最柔软的羽毛床，千里难寻。你想试试吗？"
D.Strings[56072]="你吃饱了吗，$r？请记得要好好照顾自己。"
D.Strings[56073]="我的旅店舒适得像家一样。请别客气，随意。"
D.Strings[56074]="酊剂、药水、药膏和补品！"
D.Strings[56075]="瓶子，来买瓶子！"
D.Strings[56076]="热乎乎，新出炉的面包！"
D.Strings[56077]="你已经受|cFFFF0404|Hspell:123788|h[恐怖嚎叫]|h|r的影响！"
D.Strings[56078]="热乎乎，新出炉的面包！来买面包！"
D.Strings[56079]="出售鲜花，来买美丽的鲜花！"
D.Strings[56080]="%s撤退到她的护体中！"
D.Strings[56081]="%s从她的护体中冒了出来！"
D.Strings[56082]="出售刚采摘的鲜花！"
D.Strings[56083]="美丽的鲜花送给你爱的人！拿好你的鲜花！"
D.Strings[56084]="在这些罕见的花朵枯萎之前，取得它们！鲜花待售！"
D.Strings[56085]="惧之煞|cFFFF0404|Hspell:126121|h[腐蚀]|h|r不谐力场！"
D.Strings[56086]="那是一个好女孩，萨里。"
D.Strings[56087]="你是一只很好的小猫。"
D.Strings[56088]="好吧，舒展一下身体。"
D.Strings[56089]="萨里！去捡回来！"
D.Strings[56090]="呵呵，这就是我试图让一只猫去捡回来的东西。"
D.Strings[56091]="我爱我的妈妈和爸爸。"
D.Strings[56092]="看看他！早上的时候他总是有些脾气暴躁。"
D.Strings[56093]="哇哦，瞧瞧那个！真大啊！"
D.Strings[56094]="比两座房子还大！"
D.Strings[56095]="马亚，不要太靠近！它会咬掉你的头！"
D.Strings[56096]="不，它不是的！不要傻了！"
D.Strings[56097]="我想要些糖果！"
D.Strings[56098]="马亚，不要触摸大老虎！它会把你当美餐！"
D.Strings[56099]="哇……大猫咪！"
D.Strings[56100]="呀……！"
D.Strings[56101]="不要担心，马亚，我会保护你。"
D.Strings[56102]="它似乎受惊了。"
D.Strings[56103]="总有一天，我要驾驭其中的一个飞行。"
D.Strings[56104]="嘿，小姐，你能给我们看一些烟花吗？"
D.Strings[56105]="那女士从事什么工作？"
D.Strings[56106]="她真的制作烟花吗？"
D.Strings[56107]="小女孩，你想看烟花吗？"
D.Strings[56108]="哇！真响！"
D.Strings[56109]="哇！这看起来很酷！"
D.Strings[56110]="康诺，我饿了。"
D.Strings[56111]="你刚吃过，傻瓜。你怎么又饿了呢？"
D.Strings[56112]="我不知道……我就是饿！"
D.Strings[56113]="看看那位！他看起来……怪怪的。"
D.Strings[56114]="马亚，这样说不妥。即使他看起来有些怪，你也不应该当他的面说。"
D.Strings[56115]="哎呀……对不起。"
D.Strings[56116]="让我们玩个游戏。"
D.Strings[56117]="我很无聊！"
D.Strings[56118]="他是锦鱼人。"
D.Strings[56119]="它看起来像一条大鱼！"
D.Strings[56120]="如果他是鱼，他为什么不在水中游泳呢？"
D.Strings[56121]="这是因为锦鱼人是鱼。某种程度上是。"
D.Strings[56122]="我不那么认为。也许他有魔力。"
D.Strings[56123]="康诺，我们能乘坐风筝吗？"
D.Strings[56124]="应该可以。"
D.Strings[56125]="这场混乱毁掉了……一切。毁了所有人。"
D.Strings[56126]="绝对不能让部落找到聚焦之虹。消灭他们军队的所有残余力量，我会保护好神器。"
D.Strings[56127]="我必须在传送前调校好聚焦之虹。保护我！"
D.Strings[56128]="你的族人都是卑劣的懦夫，兽人。你们都会像疯狗一样被消灭，别想得到聚焦之虹。"
D.Strings[56129]="对怜悯吐口水？那你就得不到怜悯了。你想要杀戮？那就让加尔鲁什给你收尸吧。"
D.Strings[56130]="恐怕没人能保护你。杀了这个贱人，把那炸弹带回来。"
D.Strings[56131]="她不漂亮吗？唉……"
D.Strings[56132]="真是豪言壮语啊。等你乞求怜悯时，我会把口水吐你脸上。"
D.Strings[56133]="啊啊啊！我要把你的脑袋带给酋长！"
D.Strings[56134]="她是那么聪明、有趣！我为她神魂颠倒。"
D.Strings[56135]="我该如何告诉她我的真实感受呢？噢，我不擅言辞！"
D.Strings[56136]="你觉得她可能对我这样的人来电吗？我很……不赞同！"
D.Strings[56137]="我敢打赌，她喜欢雄壮的男人。我该怎么办？"
D.Strings[56138]="难道你觉得我应该去那些禅院中受训做一名武僧？你知道的，为了让她留下深刻的印象。"
D.Strings[56139]="我没有大啤酒肚。我需要一个大啤酒肚。好吧。说做就做！"
D.Strings[56140]="我知道她喜欢千杯不醉的男人，所以我每天晚上喝得烂醉，来锻炼我的酒量。"
D.Strings[56141]="怎么所有的男人都不急着约女人出来？"
D.Strings[56142]="我觉得他喜欢我，但我不确定。你是怎么想的，$r？"
D.Strings[56143]="噢，不，如果他认为我太多毛了呢？如果他不喜欢黑白相间的女子呢？"
D.Strings[56144]="我使出浑身解数调情，但我想他没收到讯息！"
D.Strings[56145]="他总是谈论扳手和超载电容器。他肯定知道哄骗女孩。嗷！"
D.Strings[56146]="我当然喜欢他漂亮的脸蛋。"
D.Strings[56147]="有联盟幸存者！快派……援军……"
D.Strings[56148]="[%s]忏悔：我曾经拿了一张猎人想要的弓。"
D.Strings[56149]="想看些你喜欢的护甲吗，$r？只有你在潘达利亚最具挑战性的地牢中证明自己的价值，你才能获得这些罕见的护甲套件。$B$B你必须寻找这些地牢，并步行进入。以足够快的速度赢得挑战的人们应得到我们大铸甲师的尊敬，也许还会在邮件中收到一个罕见护甲礼物。"
D.Strings[56150]="光明与你同在，$r。"
D.Strings[56151]="暴风城的王子毫无防备！我们为什么不为了部落抓住他呢？"
D.Strings[56152]="哈！口气真像加尔鲁什·地狱咆哮的信徙。我们的“酋长”会感到自豪的。$b$b但是我的部落不与手无寸铁的孩童打仗。我也不敢当着一位至尊天神的面在这个神圣殿堂开战。$b$b此外，这个小子取得了贝恩·血蹄大酋长的友谊和信任。出于这个原因，我要保护他。$b$b至少现在要保护。"
D.Strings[56153]="我和我的家人很早以前就是这个地方的牺牲品。$B$B让我们的命运警告那些想要插手巫术的人们。$B$B帮我解除诅咒，$c。消灭黑暗院长加丁。"
D.Strings[56154]="锦绣谷。$b$b谁能想到，酋长竟然忍心摧毁如此美丽的地方。$b$b金莲教总担心有朝一日，魔古族会重新占领这里。看来他们是低估了加尔鲁什的狂妄程度。"
D.Strings[56155]="噢，你好，$n。$b$b你的时机再好不过了。"
D.Strings[56156]="我们无家可归，但只要我们还活着，就会在其他地方重建家园。"
D.Strings[56157]="我们会卷土重来，$r。"
D.Strings[56158]="我们刚刚抵达时，这里是一座壮丽的山谷。它的池塘中充盈着我们从未见过的神奇之水。$B$B可跟着，那个名叫加尔鲁什·地狱咆哮的家伙就来了。他带来的只有毁灭。等他离开时，山谷中的水已经干涸了。"
D.Strings[56159]="在翡翠林所发生的是一场可怕的悲剧。我坚信，只有向他们学习，才能避免重蹈覆辙。$B$B这个图书馆里有很多知识。我已经了解到很多关于煞魔的知识。"
D.Strings[56160]="[%s]忏悔：我曾从我的公会银行“借过”东西。"
D.Strings[56161]="锦鱼人曾经从这个地方，以这个权力座位统治整个潘达利亚。$B$B我们必须学习所有历史知识，这样，我们才有可能收复失地。"
D.Strings[56162]="我自从溃败流落以这个海岸，便一直流浪。$r！$B$B一直以来，我从青龙寺到卡桑琅海岸，再到不息山山顶。$B$B这个地方很有名，我已经整理了我的所有发现。$B$B我迫不及待地将我的所见所闻告诉我探险者协会的同事！"
D.Strings[56163]="你永远不知道谁真正可以信任。要是你是我，你就会知道。"
D.Strings[56164]="女皇的间谍无处不在。"
D.Strings[56165]="那些试图通过武力夺取政权的人往往会发现自己孤单。"
D.Strings[56166]="我的女皇也恐惧和偏执。她的恐惧最终导致她的灭亡。"
D.Strings[56167]="我向来擅长算数！$B$B当地人见识了我心算加、减和微分方程的速度后，他们立马就聘用了我！"
D.Strings[56168]="你必须时刻保持坚强的意志，以承受从女皇处不断传来的窃窃私语。薄弱的意志将使你在不知不觉中落入她的手中。"
D.Strings[56169]="现在，我已经见过这个谷，我得说，这里有些地方感觉有点……熟悉。$B$B我知道，它并不像它，但我不能摆脱这种感觉。你认为那意味着什么！？"
D.Strings[56170]="他们是不是很伟大？我是他们的头号粉丝！"
D.Strings[56171]="欢迎，$r！留下来听一会。"
D.Strings[56172]="欢迎光临夜莺旅馆，$c。今天我们可以为你做些什么？"
D.Strings[56173]="这个图书馆里的知识令人震惊。"
D.Strings[56174]="[%s]忏悔：我总是忘记给装备镶宝石。"
D.Strings[56175]="[%s]忏悔：我花了半年时间刷迷时始祖幼龙。"
D.Strings[56176]="[%s]忏悔：我进入奥特兰克山谷，却根本没有帮助我的队伍。"
D.Strings[56177]="[%s]忏悔：我被电梯杀过。好像还不只一次。"
D.Strings[56178]="[%s]忏悔：我从来没有使用过光明之泉。"
D.Strings[56179]="[%s]忏悔：我一直想成为一名圣骑士。"
D.Strings[56180]="[%s]忏悔：巨魔的脚趾吓死我了。"
D.Strings[56181]="[%s]忏悔：我喜欢玩火自焚。"
D.Strings[56182]="[%s]忏悔：我告诉团长，我已经准备好了，但事实上，我没有准备好。"
D.Strings[56183]="[%s]忏悔：我从达拉然上摔下去过。"
D.Strings[56184]="有个名叫萨拉·芬克斯维奇的战斗训练师在主露台上训练她的宠物。$B$B我会在你的地图上标记这个位置。"
D.Strings[56185]="[%s]忏悔：我向一位朋友要了很多金子去买我的第一头坐骑。"
D.Strings[56186]="是的，楼下就有渔具供应商，就在夏之台的一楼。$B$B我会在你的地图上标记这个位置。"
D.Strings[56187]="[%s]忏悔：我告诉队友说，这个地下城我以前来过，但其实我完全不知道自己该干什么。真尴尬。"
D.Strings[56188]="[%s]忏悔：我曾经打了一个侏儒。没有原因。我就是那天心情不好。"
D.Strings[56189]="[%s]忏悔：我出比朋友更高的价格买下我其实并不想要的拍卖品。"
D.Strings[56190]="[%s]忏悔：我去地下城不是为了使艾泽拉斯变得更好，而是为了战利品。"
D.Strings[56191]="[%s]忏悔：其实，我没有参加安其拉的开门仪式。我只是读过这个故事。"
D.Strings[56192]="[%s]忏悔：我完全不知道辛多雷是个谁。"
D.Strings[56193]="[%s]忏悔：我研究考古学，但对历史并不感兴趣。"
D.Strings[56194]="[%s]忏悔：德莱尼人的笑声真的让我很烦。"
D.Strings[56195]="[%s]忏悔：我几个月没进理发店了。拿着剪刀的地精。叫人不寒而栗。"
D.Strings[56196]="[%s]忏悔：我曾经以为熊猫人和熊怪是亲戚。"
D.Strings[56197]="[%s]忏悔：噢，我抢过别人的蜡烛。"
D.Strings[56198]="[%s]忏悔：让老鼠打破了大门不过是个小小的反击。"
D.Strings[56199]="[%s]忏悔：在没有人看见时，我会烧东西，并且大喊大叫“让火焰净化一切”。"
D.Strings[56200]="[%s]忏悔：在风暴峭壁时我真的忘了你是谁。"
D.Strings[56201]="[%s]忏悔：我有时会忘记诺森德是在这里的南方还是北方。"
D.Strings[56202]="[%s]忏悔：我每次看到那些缩写就头疼，什么KLZ DPS CJQ 1Q9来强力的，完全看不懂啊。"
D.Strings[56203]="[%s]忏悔：我忘了太阳之井。"
D.Strings[56204]="[%s]忏悔：我真的没有准备好。谁知道我是不是自寻死路呢？"
D.Strings[56205]="[%s]忏悔：我有时候很好奇牛头人的味道是不是很像……你知道的。"
D.Strings[56206]="[%s]忏悔：我要求圣光给我力量，但我不确定它是否真的会给。"
D.Strings[56207]="[%s]忏悔：有时候路途很短，我也会使用我的坐骑。我是说真的很短的路程。"
D.Strings[56208]="[%s]忏悔：我不知道米尔豪斯是不是一个好人。"
D.Strings[56209]="[%s]忏悔：我知道加尔鲁什是个混蛋，但他也有不为人知的一面……"
D.Strings[56210]="[%s]忏悔：我被法师biu过一次，然后那伤害……我当时就给跪了。"
D.Strings[56211]="我们被这里的景色吸引。但是，即使是这样的景色，也无法与四风谷的美景相比。"
D.Strings[56212]="[%s]忏悔：过去的很长一段时间里，我都以为小样本事件的复数写法就是数据流。"
D.Strings[56213]="[%s]忏悔：有时候，其实我离得不远，但我还是叫术士拉我。"
D.Strings[56214]="[%s]忏悔：有时候我想独自一个人做任务，便假装听不见我的朋友说话……"
D.Strings[56215]="走了很长一段路才到这里。沿途之中我们错过了很多。$b$b但是……看看这个地方。太不可思议了！"
D.Strings[56216]="旅行者，你想吃点什么吗？"
D.Strings[56217]="出售食物和饮料！"
D.Strings[56218]="来份点心怎么样，$r？"
D.Strings[56219]="联盟跟随我们到这里。即使在这个宁静的地方，我也能闻到硝烟的味道。"
D.Strings[56220]="魔古族、螳螂妖和联盟都威胁到这个古老的地方的安全。我们必须不惜一切代价保护它。"
D.Strings[56221]="野牛人侵占了我们的家园！但这个地方……这个地方为我们提供一个新的开始。"
D.Strings[56222]="当野牛人袭击我们家园的时候，我以为全都完了。这是老生常谈，但老武僧说得对：“东方不亮，西方亮。”$b$b或者和这差不多的说法。他们的教导是不是太泛泛了。"
D.Strings[56223]="我们可以去看看青龙吗？"
D.Strings[56224]="今天不行，小家伙。我们有任务在身。"
D.Strings[56225]="我们可以去看看牛头人吗？他们看起来像野牛人。"
D.Strings[56226]="我们可以去看看亡灵女士吗？她看起来很有趣的。"
D.Strings[56227]="我们可以和地精玩耍吗？我比他们高！"
D.Strings[56228]="我们什么时候可以回家？"
D.Strings[56229]="我想念我的玩具。我们可以回家了吗？"
D.Strings[56230]="我们可以回昆莱山吗？这里的空气闻着很奇怪。"
D.Strings[56231]="很抱歉，我们需要在这里呆一会儿。部落保护着我们的安全。"
D.Strings[56232]="你好！你想和我宠物决斗吗？"
D.Strings[56233]="你好，$r。我也许比较小，但是在宠物的战斗中身材大小并不重要！"
D.Strings[56234]="你好，$c！你不觉得我的宠物很可爱吗？"
D.Strings[56235]="你好，亲爱的。你一直都在战场上吗？"
D.Strings[56236]="有什么我可以帮你吗？"
D.Strings[56237]="锄头是忠实的$G男人的:女人的;武器。"
D.Strings[56238]="你好啊，$n。汇风岭附近发生的一切我都已经了然于胸了，宝贝儿。活到我这把年纪，总会交到几个大嘴巴的朋友。"
D.Strings[56239]="我们走吧。千万别把自己的命给搭上。"
D.Strings[56240]="|TInterface\\Icons\\spell_shadow_corpseexplode.blp:20|t %s吃得太多，开始|cFFFF0000|Hspell:126126|h[呕吐]|h|r！"
D.Strings[56241]="寒心，我们为你而来！血债血偿的时候到了！"
D.Strings[56242]="|TInterface\\Icons\\inv_misc_monsterfang_02.blp:20|t %s用他的|cFFFF0000|Hspell:126187|h[钳颚]|h|r诱捕猎物！杀了他！"
D.Strings[56243]="人必须尊重他的家族。"
D.Strings[56244]="当缚魂魔袋看到指导者的灵魂被摧毁的时候，它开心地笑了起来。"
D.Strings[56245]="尽管缚魂魔袋看上去不大愿意进入大厅，但是还是跟了上来。"
D.Strings[56246]="一支人数众多的军队拿什么做点心？$B$B……$B$B撤退！"
D.Strings[56247]="我不是以治疗者而是牧师的身份来见你！"
D.Strings[56248]="不要问我怎么对付术士。我避开他们。哈哈哈哈！"
D.Strings[56249]="坦克为什么会在战斗之前感到紧张？$B$B……$B$B因为他们总是很忐忑！"
D.Strings[56250]="如果瓦里安国王倒台，会怎么样？$B$B……$B$B我不知道，但应该会发生不小的震动！"
D.Strings[56251]="……呃……！$B$B……什么是……什么是“内脏”……？"
D.Strings[56252]="我实在不忍心看。"
D.Strings[56253]="缚魂魔袋一言不发地进入第二个大厅。"
D.Strings[56254]="啊，这不是我最仰慕的刺客大师吗！我一直希望能在潘达利亚找到你呢。"
D.Strings[56255]="很好。我们谈谈吧。"
D.Strings[56256]="童福！拿酒来。"
D.Strings[56257]="我的父亲死亡之翼，曾经想摧毁整个艾泽拉斯。"
D.Strings[56258]="没错，他是误入歧途，可他却说对了一件事——我们的世界……确实脆弱不堪。"
D.Strings[56259]="我们是晦暗宇宙中的一点光亮。是飘摇在暴风雨中的烛光。"
D.Strings[56260]="有时我会想，正是我们这个世界的动荡，逼疯了我的父亲。"
D.Strings[56261]="啊，谢谢你，童福。"
D.Strings[56262]="现在，言归正传——我觉得一场末世浩劫正在酝酿。不，我说的不是联盟和部落之间的冲突。"
D.Strings[56263]="相信我——加尔鲁什·地狱咆哮在塞拉摩的所作所为，跟现在降临于我们脆弱家园的浩劫相比，根本算不了什么。"
D.Strings[56264]="可战争深深困扰着我。你理解我的顾虑吗？"
D.Strings[56265]="四分五裂的艾泽拉斯根本无力对抗黑暗。"
D.Strings[56266]="这场战争必须尽快结束。否则，它会耗尽我们的力量！"
D.Strings[56267]="请你相信，联盟在这场战役中，能得到我毫无保留、坚定不移的支持。"
D.Strings[56268]="你大可放心，我的忠诚与部落同在。"
D.Strings[56269]="我们该如何迅速果断地平息这场冲突？相信答案就在你们这些英雄心里。"
D.Strings[56270]="我们必须确定你能够执行这项任务……并把你武装起来。"
D.Strings[56271]="尽量保命！我们才刚刚开始这场传奇之旅。"
D.Strings[56272]="啊！我的英雄回来了。"
D.Strings[56273]="平台就在山上。多加小心，访客几乎全都有去无回。"
D.Strings[56274]="你看起来面色苍白，朋友！相信你还没有被恐惧打败吧？"
D.Strings[56275]="请允许我收拾一下东西，然后我会前去找你。"
D.Strings[56276]="我经常来这儿思考。这景色真让人叹为观止，你觉得呢？"
D.Strings[56277]="潘达利亚真是一颗明珠。美轮美奂。使你想要去保护她，是吧？"
D.Strings[56278]="我对艾泽拉斯也有同感。"
D.Strings[56279]="你成就斐然，我的朋友。我保证，这只是我们合作的开始。"
D.Strings[56280]="向你的手下败将学习力量。"
D.Strings[56281]="向不如你聪明的人学习智慧。"
D.Strings[56282]="看！它就是你所战胜的恐惧实体。愿它将恐惧注入你敌人的体内！"
D.Strings[56283]="终于等到了我要给你的礼物。别搞错了——黑龙军团还活着！"
D.Strings[56284]="好了。我的工作完成了。你现在能大大提高任何感染煞能的武器的威力。"
D.Strings[56285]="我们才刚刚开始，朋友！最大的挑战还在前头。"
D.Strings[56286]="但当战火烧到这片海岸时，你和我都会做好准备！"
D.Strings[56287]="很高兴再次见到你，$n！我相信我在拉文霍德给你的武器，已经派上大用场了，对吗？$b$b在潘达利亚，我有另一个“任务”给你。这将再次需要你的所有技能，我再次向你保证……这将是值得的！$b$b在我们开始前，重要的是你自己要熟悉地形。一旦你获得更多的经验，就来拜访我。"
D.Strings[56288]="你好，又见面了。$n，是它吗？是的，没错……我相信我们在东部王国留下了一些未完成的事业。你怎么找到潘达利亚的？$b$b如果你赢得这次挑战，我便再给你另一个任务。我保证这值得你去做。$b$b在我们开始前，重要的是你自己要熟悉地形。一旦你获得更多的经验，就来拜访我。"
D.Strings[56289]="<黑王子上下打量了你一番。>$b$b很高兴见到你，$c，探索新世界的先锋。在神秘大陆潘达利亚上冒险的感觉如何？$b$b你看起来就像是个办事可靠的人。我希望当你完成对这块大陆的游历之后，就立即回来找我。$b$b我会在这里等你。"
D.Strings[56290]="我所选择的名字是“拉希奥”。据我所知，我是最后一条黑龙。$b$b我的父亲是死亡之翼。他是灭世者、死亡的化身、毁灭者……但我希望你不会因此而排斥我。$b$b我不爱我的父亲，他的堕落摧毁了我的族群，我也不喜欢红龙军团，他把我的蛋偷去做试验，期望改造我。$b$b这么说吧，我如今是……孑然一身。而且，我一直在寻找志同道合的英雄。"
D.Strings[56291]="你在潘达利亚做什么？"
D.Strings[56292]="我当然可以有一些秘密。你不同意吗，$n？$b$b迷雾散去后不久，我就到达了……在我的同事拉文霍德了解了一次远离海岸的海战后，我可以飞到这里。$b$b这里已经被隐藏了一万年。我才刚刚开始探索之旅！"
D.Strings[56293]="你回来我很高兴，$n！我相信你现在已经适应了潘达利亚这片奇怪的新大陆，对吗？$b$b你过去已经证明了自己，这样我们就可以免去任何类似的测试或试验。让我们马上开始。$b$b你准备好改变世界了吗？"
D.Strings[56294]="欢迎，$c！我的眼线遍布潘达利亚，我得知，你一直都在忙碌着。我敬佩具备……“主动性”的凡人们。$b$b我们正处在一个历史的转折点上。如果你愿意带着我去迎接命运，我会确保你的付出能得到丰厚的回报。"
D.Strings[56295]="我们的熊猫人战役才刚刚开始，$n。"
D.Strings[56296]="我相信我们最终可以找到我父亲的青春之池。我们可以为泰兰德提供尽可能多的信息。"
D.Strings[56297]="因为我们来到这片新的土地，所以我的哨兵面临许多危险。我们准备好迎接任何挑战。"
D.Strings[56298]="在进入四风谷后，我军的士气有所提高。"
D.Strings[56299]="四风谷真是个的天堂。"
D.Strings[56300]="亲眼见到这个地方是我父亲的梦想。我必须在这里完成他的心愿。"
D.Strings[56301]="从南部海岸刮来了一阵恶风。你准备好了吗？"
D.Strings[56302]="在收集我们所要的信息之前，我们都在这个谷里休息。然后，我们必须想方设法回家。"
D.Strings[56303]="这里有一些屏障保护着四风谷，阴止我使用传送门魔法。"
D.Strings[56304]="我们能在这个四风谷遇见还真巧。"
D.Strings[56305]="加尔鲁什的狂妄摧毁了锦绣谷。这是无法治愈的创伤。"
D.Strings[56306]="这里的树比我在南部丛林见过的都更漂亮。"
D.Strings[56307]="我从来没有见过像这样的地方。"
D.Strings[56308]="这山谷里的池水莫非就是传说中的“青春之池”？也许我们可以再次掌握永生……"
D.Strings[56309]="我们已经听说了魔古族遍布四风谷的消息。他们不会胜过我们的。"
D.Strings[56310]="我们在研究池水的同时，还会巡逻城市的边界，保护这里的人。"
D.Strings[56311]="说实话，我起初并不相信瓦尔德林看见的幻像。但这地方确实散发着不同寻常的魔法之力——难道这就是传说中的“青春之池”？"
D.Strings[56312]="如果你有时间，你应该参观滨岸有名的酿月祭。我会酿造一些著名的昆莱劲酒。"
D.Strings[56313]="传说在这四风谷发生了大会战，许多勇敢武僧的鲜血将金色的原野染成了红色。魔古皇帝雷电之王雷神的军队战斗野蛮，但是最终被攻克。"
D.Strings[56314]="去死吧，加丁！杀了他！"
D.Strings[56315]="我有两百多艘船，唯独载着我儿子的那艘……不见了！"
D.Strings[56316]="我决心去寻找那座溪谷……溪谷……溪谷……"
D.Strings[56317]="抢占那片海滩，将那岛屿染成红色！"
D.Strings[56318]="|TInterface\\Icons\\ability_warlock_improvedsoulleech:20|t你受|cFFFF0000|Hspell:126228|h[撕裂的灵魂]|h|r的影响！杀了它！"
D.Strings[56319]="雷神溃败后的这些天，四风谷被最深黑色的乌云笼罩。雷神在他临终前召唤出异世的风暴笼罩四风谷，伴随着降雨和锯齿状的闪电长矛劈落在山上。"
D.Strings[56320]="亡者的鲜血被风暴冲刷到琼花湖，把湖水染成深红色。凭借最后一口气，风暴袭击了湖中心，点燃了湖水本身。湖水被烧了很多天，呈现出深红色。"
D.Strings[56321]="当大火平息，云端翔龙孵化，在湖中心周围飞行。它的鳞屑点燃风暴和火焰。在它所到之处，天空中呈现祥云朵朵。我的人把它称为阿拉尼，风暴之子的意思。"
D.Strings[56322]="他们说，阿拉尼只能看到最亮的闪电，也许只能听到最响惊雷的回声。你如果希望得到她的注意，则需要利用催生了她的天空本身。"
D.Strings[56323]="你好，朋友！我这里通常不会有太多人造访，你是否想听听锦绣谷的故事？"
D.Strings[56324]="我想！"
D.Strings[56325]="这很有意义！"
D.Strings[56326]="该死的蠢蛋！啤酒是给猢狲的！"
D.Strings[56327]="倒酒！"
D.Strings[56328]="没有你的啤酒！"
D.Strings[56329]="魔古族的古老地宫，数千年来封存未动，谁知道里面有什么秘密？"
D.Strings[56330]="人人为我！我为乌克！"
D.Strings[56331]="许多年轻的熊猫人都在这墓穴里……蒸发了。时刻保持警惕。"
D.Strings[56332]="魔古族对大地的石头有着极大的控制力。他们的魔法直到数个世纪之后余力犹存。"
D.Strings[56333]="庞大的魁麟似乎在把守大门。小心前行，以免唤醒它们。"
D.Strings[56334]="随着守卫的死去，大门的装置似乎被激活了。不知我们会在里面有何遭遇。"
D.Strings[56335]="我们似乎唤醒了什么东西的灵魂。"
D.Strings[56336]="看来传说是真的……"
D.Strings[56337]="我们打扰了不该打扰的东西。决不能让他逃离这囚牢！你必须消灭他！"
D.Strings[56338]="受诅者魔封遭到了四位魔古皇帝的背叛，他的身体每次都被摧毁，然后再度复活。"
D.Strings[56339]="猢狲打刀手！集合！"
D.Strings[56340]="这不会是我们最后一次看见魔封……"
D.Strings[56341]="赞达拉——魔古族的古老盟友！他们一定在宝库深处寻找传说中的武器！"
D.Strings[56342]="蠢蛋！"
D.Strings[56343]="你没有拿酒！"
D.Strings[56344]="拿下他们的头目！"
D.Strings[56345]="为了乌克头领！"
D.Strings[56346]="抱歉我没有早点告诉你！在这宝库里有一把威力无穷的武器！阻止他们！"
D.Strings[56347]="我要留下，进一步调查这里……"
D.Strings[56348]="这台子底下有个秘密通道，来这边！"
D.Strings[56349]="看看地上的灰尘，这黑暗的殿堂已有几百年无人踏入了。"
D.Strings[56350]="魔古族曾奴役潘达利亚的所有种族，并让他们屈从于自己的邪恶意志。"
D.Strings[56351]="这些锦鱼人被囚禁在永恒的奴役之中。"
D.Strings[56352]="我听见了微弱的嗡鸣声。是从这个方向传来的！"
D.Strings[56353]="那就结束了。可是……地下藏有多少这种机器？我们对魔古族的黑暗秘密又知道多少？"
D.Strings[56354]="恐怕我们对抗远古敌人的战斗还远未结束。"
D.Strings[56355]="难以置信！一台真真切切的魔古建造机器。"
D.Strings[56356]="千万不能让它落入恶人之手。"
D.Strings[56357]="无数没有灵魂的、畸形的怪物，浩浩荡荡……想到这机器中会涌出怎样的邪恶，我就打寒颤。"
D.Strings[56358]="就在此地，就趁现在，必须在它危害潘达利亚之前摧毁它。"
D.Strings[56359]="打开这台机器，我会帮你锁住后面的门。"
D.Strings[56360]="让神鹤指引你的脚步。"
D.Strings[56361]="不！回来，懦夫！"
D.Strings[56362]="唤醒者，这有许多奇妙的毒药。有些毒药可以活煮了你。有些会吞噬你的肉。有些会炸开你的肚子。$B$B这么多奇妙的毒药。"
D.Strings[56363]="快，摧毁它们。我们要追赶加丁！"
D.Strings[56364]="唤醒者，你试喝过毒药吗？开始时，你必须服用毒性非常温和的，第一次几滴就行了。$B$B然后，你很可能会生一场大病，也许甚至会失去一根或两根触须。$B$B但是，只要时间足够长，你就会慢慢适应。"
D.Strings[56365]="我曾经是夏柯希尔女皇最看重的皇家炼金术士，技术无人能及。"
D.Strings[56366]="唉！我记得当时昂舒克还微不足道，不敢配制他的第一份毒药。我量他不敢独自面对我。然后，我们将比比谁的炼金术才是终极的。"
D.Strings[56367]="向韶天鞠躬行礼！"
D.Strings[56368]="啊，又一个来自迷雾之外的旅行者。"
D.Strings[56369]="一万年前，末代熊猫人皇帝曾向我讨教治国之道。他也是一个充满矛盾的人。让我们看看你是否正确，踏岚。看看这个陌生人如何应对灵魂的骚动。"
D.Strings[56370]="很快他们将霸占整个大陆！我们何以划清界限？"
D.Strings[56371]="我们在翡翠林亲眼目睹了你所谓的“帮助”。那些“部落”，还有你的“联盟”——你们连自身都无法掌控，你们真是悲哀。"
D.Strings[56372]="草民，跪下。"
D.Strings[56373]="我们是来提供援助的。我们能帮忙保护溪谷。"
D.Strings[56374]="快去阻止加丁！别管这个女亡灵了！"
D.Strings[56375]="<他专心地俯视大厅。>"
D.Strings[56376]="|TInterface\\Icons\\ability_warlock_baneofhavoc:20|t%s开始施放|cFFFF0000|Hspell:126299|h[灵魂释放]|h|r！快跑开！"
D.Strings[56377]="这么说，金莲教也来了……"
D.Strings[56378]="你们太迟了。碧玉军团是我的了。"
D.Strings[56379]="而有了他们，我将以雷电之王的名义碾碎金莲教，夺回锦绣谷！"
D.Strings[56380]="无穷无尽的碧玉军团归我掌握！"
D.Strings[56381]="你那潜行者朋友自以为身手矫健。"
D.Strings[56382]="我的石雕将碾碎他的生命，只留下四分五裂的躯壳。"
D.Strings[56383]="他被你送上了绝路……"
D.Strings[56384]="多么高尚……来拯救一个必死的朋友……"
D.Strings[56385]="……徒劳无功。抓住他们！"
D.Strings[56386]="你的挣扎毫无意义。"
D.Strings[56387]="你对这座山谷蕴藏的强大秘密一无所知。我将得到它们，消灭你们所有人。"
D.Strings[56388]="将这些俘虏投进囚笼。让下面的人看好他们。"
D.Strings[56389]="我的下一个伟大的冒险即将开始。$B$B我看到的那是一道圣光吗？"
D.Strings[56390]="雷电之王的战盔……"
D.Strings[56391]="看来我的守卫都是废物。我还得亲自来对付你们。"
D.Strings[56392]="这次就不用囚笼了，我要直接把你们的四肢扯下来！"
D.Strings[56393]="屈服于我的力量！"
D.Strings[56394]="我要熄灭你的生命之火！"
D.Strings[56395]="我要撕裂你的灵魂！"
D.Strings[56396]="暴力。看见没有？充满了他们的身体。"
D.Strings[56397]="你没我想得那么弱，但战盔还是我的……"
D.Strings[56398]="啊啊！！法师，我们下次见面时，我一定要让你人头落地。"
D.Strings[56399]="对……我们是战士。可我们来自饱经肆虐的土地。我们击退过恶魔，也击退过死亡，甚至阻止过世界末日的到来！"
D.Strings[56400]="准备受死吧，恶棍！"
D.Strings[56401]="你不配让我动手。达苟！碾碎这只微不足道的跳蚤！"
D.Strings[56402]="是的。他们很强，有很多值得我们学习的地方。"
D.Strings[56403]="我要让你瞧瞧督军的真正力量！"
D.Strings[56404]="你无路可走了，懦夫！"
D.Strings[56405]="蠢货。你竟然妄想与魔古帝国展开全面对抗？"
D.Strings[56406]="你休想痛痛快快地死，懦夫。"
D.Strings[56407]="我们要夺回本该属于我们的一切！"
D.Strings[56408]="愚不可及，自作自受！"
D.Strings[56409]="我获得了新生！"
D.Strings[56410]="我体内的血液里流满了毒素。我再也不怕任何毒药了。我可真是自己的杰作！"
D.Strings[56411]="你不想尝尝毒药吗，唤醒者？一滴也不要？"
D.Strings[56412]="我再也不是螳螂妖了。我变得……更加强大。"
D.Strings[56413]="我想要学习烹炒之道。"
D.Strings[56414]="我想要学习酿造之道。"
D.Strings[56415]="我们赞同为正义事业而战是光荣的：如保卫家园或家人。可复仇呢？愤怒呢？我能在此人内心深处感觉到这些情绪。"
D.Strings[56416]="我每天都存入各种新旧资料。有时是古老的智慧书卷，有时则是某位墨水大师创作的山谷写生图。$b$b我们保存着这些知识，以便让后人能从我们的成功……和失败中借鉴一二。"
D.Strings[56417]="站到高处，避开暗影之雾！"
D.Strings[56418]="|TInterface\\Icons\\inv_misc_gem_bloodstone_03:20|t%s变成了|cFFFF0000|Hspell:126384|h[红色花岗岩]|h|r！"
D.Strings[56419]="|TInterface\\Icons\\inv_misc_gem_stone_01:20|t%s变成了|cFFFF0000|Hspell:126401|h[绿色花岗岩]|h|r！"
D.Strings[56420]="|TInterface\\Icons\\inv_ore_cobalt:20|t%s变成了|cFFFF0000|Hspell:126405|h[蓝色花岗岩]|h|r！"
D.Strings[56421]="我想要学习烧烤之道。"
D.Strings[56422]="我想要学习炖煮之道。"
D.Strings[56423]="我想要学习蒸烧之道。"
D.Strings[56424]="我想要学习烘焙之道。"
D.Strings[56425]="闻上去香极了，是吧？"
D.Strings[56426]="你想要学习如何烹饪吗？"
D.Strings[56427]="我想要学习熊猫人烹饪之法。"
D.Strings[56428]="我需要给厨房补充些食材和炊具。"
D.Strings[56429]="在黎明破晓时分，重锤将要砸落。"
D.Strings[56430]="生命中什么最美好？\n\n哥们儿，小曲儿和美酒！"
D.Strings[56431]="我喜欢女人就像我喜欢啤酒——丰满而醇厚。"
D.Strings[56432]="我为爱甘愿付出一切。可我不会这么做。至少，现在不行。"
D.Strings[56433]="这群小子可真麻烦。"
D.Strings[56434]="我答应带他们在这儿野餐，可这里太危险了。就在几天前，我听说有几个像你一样的陌生人打了起来。$b$b还有个从……龟背上来的人。$b$b我一直以为那海龟只是个传说。"
D.Strings[56435]="我们这里并不常遭遇掠食者。有时，如果下雨的话，蜥蜴人会出现。可他们只在电闪雷鸣的暴风雨来袭时才会来。"
D.Strings[56436]="妈妈！刘总是找我麻烦！"
D.Strings[56437]="刘抢走了我的锦鱼人饰品！"
D.Strings[56438]="刘刚才踩了我一脚！"
D.Strings[56439]="妈妈！刘总是像个猢狲一样！"
D.Strings[56440]="妈妈！刘打了我一拳！"
D.Strings[56441]="不，我没有！"
D.Strings[56442]="是他先惹我的！"
D.Strings[56443]="是你让我这么做的！"
D.Strings[56444]="不是！"
D.Strings[56445]="够了。你们俩简直是一对猢狲！"
D.Strings[56446]="要是你们不听话，我就马上结束野餐，带你们回家。你们愿意这样吗？"
D.Strings[56447]="泰，别说你哥哥坏话了。刘，你也别给你弟弟说坏话的理由。"
D.Strings[56448]="你们两个都给我住手。别弄得自己傻乎乎的。你们就不能像聪明的锦鱼人一样好好相处吗？还是说，你们就乐意毛毛躁躁地像个猢狲？"
D.Strings[56449]="发起挑战吧。"
D.Strings[56450]="这也许会让你茫然迷失，唤醒者。第一次亲眼看见，总是很困难的。"
D.Strings[56451]="非常好……金铁酒仙。"
D.Strings[56452]="我们都是暴风雨的儿女！"
D.Strings[56453]="我一直以为巨魔只在古老的故事中存在。"
D.Strings[56454]="真是一场艰苦的战斗。我们从前只需要提防蜥蜴人突袭者和偶尔前来捣乱的饥饿猢狲。$b$b那些巨魔……他们作战的方式很不一样。"
D.Strings[56455]="那些巨魔在找什么？"
D.Strings[56456]="现在你会看见。叛徒就混在我们自己人里。"
D.Strings[56457]="真是可怕的战斗。"
D.Strings[56458]="我现在真希望自己年少在禅院里受训时，没在防御课上打瞌睡。"
D.Strings[56459]="那些巨魔们想干什么？这只是个简单的小渔村。"
D.Strings[56460]="巨魔。那些是真正的巨魔！我们听过他们的传说。可现在亲眼看见了。他们跟故事里说的一样凶残。"
D.Strings[56461]="没错，愤怒在我们周身流淌。可我们懂得控制。兽人曾被愤怒驱策——终日活在对鲜血的渴望中——但还是战胜了它。"
D.Strings[56462]="你们想战胜的，只是彼此！"
D.Strings[56463]="只有死人才不会愤怒。但我们要学会克制。击败心中的愤怒，才能获得力量。"
D.Strings[56464]="|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t牢非的灵魂施放了|cFFFF0000|Hspell:126471|h[倚强凌弱]|h|r！"
D.Strings[56465]="说得好，智。来自迷雾之外的陌生人们虽然不缺乏热情，但我们得看看他们的自制力。愤怒出自仇恨，仇恨乃万苦之源。看，这就是你心中仇恨的模样！"
D.Strings[56466]="看见没有？这些外来者如此憎恨彼此！他们身披仇恨上阵，再把仇恨带进坟墓！"
D.Strings[56467]="不，那不是真的——对我们来说绝对不止这样！"
D.Strings[56468]="真有趣。他们带来了很多东西，但也带来了战争的阴影。"
D.Strings[56469]="和平终将来临。我发誓。往昔的仇恨将不复存在。你要相信我。"
D.Strings[56470]="|TInterface\\Icons\\ability_searingarrow.blp:20|t火霜施放了|cFFFF0000|Hspell:126304|h[烈焰之箭]|h|r！"
D.Strings[56471]="|TInterface\\Icons\\spell_frost_iceshard.blp:20|t火霜施放了|cFFFF0000|Hspell:126321|h[霜冻箭矢]|h|r！"
D.Strings[56472]="科尔里克！你为女皇效命多久了？！"
D.Strings[56473]="我看见英杰被唤醒了。"
D.Strings[56474]="英杰满嘴胡话，唤醒者。封存让他精神失常了。"
D.Strings[56475]="我们不能再让他这么疯癫下去了。卡拉克西希望制止他。"
D.Strings[56476]="你和卡拉克西都是蠢货！傲慢会让你走向灭亡！"
D.Strings[56477]="这里疯的只有你自己，科尔里克！你真以为自己能永远不被发现？"
D.Strings[56478]="你骗不了我们。我们能看穿你的真实身份！"
D.Strings[56479]="那看起来像是……我父亲！"
D.Strings[56480]="那……好像是加尔鲁什·地狱咆哮！"
D.Strings[56481]="你好，$c。我并无恶意。$B$B我在这以血色十字军成员的身份出现，是因为他们已经无可救药地堕入了腐化与邪恶。$B$B我需要你的帮助，彻底终结他们的罪孽。"
D.Strings[56482]="哦……哦不……我要死在这里了。"
D.Strings[56483]="不，你不会的！拿上这个！"
D.Strings[56484]="|TInterface\\Icons\\spell_fire_soulburn.blp:20|t %s正在施放|cFFFF0000|Hspell:126288|h[屠杀]|h|r！"
D.Strings[56485]="那野兽浑身裹满了油，把他点燃！"
D.Strings[56486]="弓箭手，放箭！让他燃烧起来！"
D.Strings[56487]="点燃热油！"
D.Strings[56488]="跳起以从网中挣脱！"
D.Strings[56489]="这个凡人证明了自己驾驭愤怒的能力。通过后辈们的话语和这位英雄的举动，我想我已经明白了。那些来自迷雾之外的人久经战火磨砺。他们伤痕累累，但已有所觉悟。我相信他们。"
D.Strings[56490]="你犯了个可怕的错误！"
D.Strings[56491]="我决定了，锦绣谷将继续对外来者开放。他们确实犯下了很大的罪孽……但是，我从他们身上看到了纠正错误的能力。"
D.Strings[56492]="谢谢你，白虎大师。我会证明给你看。相信我的族人——还有部落——内心本善。"
D.Strings[56493]="我要征求其他人的意见。大门口见。"
D.Strings[56494]="女皇夏柯希尔会消灭你！"
D.Strings[56495]="我发现你的信念很振奋人心，小家伙。可不知你见过我们的酋长吗？"
D.Strings[56496]="女皇夏柯希尔知道了你的计划。你要为背叛而受到惩罚……"
D.Strings[56497]="$n，在我把酒酿好之前，不要让野牛人靠近！"
D.Strings[56498]="我想再升级另一把感染了煞能的武器。你能帮忙吗？"
D.Strings[56499]="你确实已经证明了自己的价值，可材料也是要花钱的。$b$b我想我可以跟郭雅夫人做些安排，但价格可不便宜。$b$b请注意，任何时候都只能装备一块恐惧水晶。"
D.Strings[56500]="物有所值。我希望提升自己的敏捷。<付10,000金币。>"
D.Strings[56501]="我是听着白虎的传说长大的。他是潘达利亚人民的英雄。很荣幸能来此受训。"
D.Strings[56502]="我留下检查科尔里克的遗骸。等你完成这些任务之后，我会和你在卡拉克西维斯见面。"
D.Strings[56503]="|TInterface\\Icons\\ability_hunter_pet_spider.blp:20|t %s施放了|cFFFF0000|Hspell:126652|h[召唤虫群]|h|r！"
D.Strings[56504]="再给我一个火炬。"
D.Strings[56505]="小的们！给我找桶好酒来！"
D.Strings[56506]="攻进库房！偷取美酒！"
D.Strings[56507]="给，拿上这些补给品吧。你在任务中会用得上。"
D.Strings[56508]="|TInterface\\Icons\\inv_misc_idol_02.blp:20|t戈拉亚选择随机玩家，使其变成了|cFFFF0000|Hspell:122151|h[巫毒娃娃]|h|r！"
D.Strings[56509]="你变成了|cFFFF0000|Hspell:122151|h[巫毒娃娃]|h|r！你所受到的伤害，会被复制到你团队其他的巫毒娃娃身上！"
D.Strings[56510]="|TInterface\\Icons\\inv_enchant_voidsphere.blp:20|t戈拉亚使你彻底|cFFFF0000|Hspell:116727|h[被放逐]|h|r到了灵魂世界！你和你的同伴必须击败所有灵魂撕裂者，才能返回现实世界。"
D.Strings[56511]="信标彼此呼应，外来者。传递重要的信息。$b$b你的耳朵听不见那些信息。只有赢得卡拉克西信任的人才能听到他们说的话。"
D.Strings[56512]="能为我所笃信的一切牺牲自己，是我的荣耀。"
D.Strings[56513]="|TInterface\\Icons\\ability_shaman_astralshift.blp:20|t你的灵魂已得到充分治愈，能与现实世界中的躯体合二为一了！用你的|cFFFF0000|Hspell:120715|h[复苏之魂]|h|r动作按钮来拯救自己的灵魂！"
D.Strings[56514]="我很忙，外来者。"
D.Strings[56515]="你已经|cFFFF0000|Hspell:116161|h[灵魂越界]|h|r到了灵魂世界！你或某位同伴必须在30秒内为你的灵魂回复90%的生命，否则你就将消亡！"
D.Strings[56516]="终有一天，卡拉克西会晋升我的地位。会允许我消耗琥珀。"
D.Strings[56517]="卡拉克西从不轻易相信别人，外来者。我花了很多年时间才令他们正眼相看。"
D.Strings[56518]="我们人人都有天赋，外来者。只不过有些人表现得没那么明显。"
D.Strings[56519]="|TInterface\\Icons\\ability_druid_challangingroar.blp:20|t戈拉亚施放了|cFFFF0000|Hspell:117752|h[狂乱]|h|r！"
D.Strings[56520]="我想我们差不多干完一半了，对吧？已经解决了血色大厅，还剩下血色修道院。$B$B要是我突然消失了你可别吃惊——我得快点赶到那里。"
D.Strings[56521]="你拿到书典了吗？"
D.Strings[56522]="蒙面的十字军战士跪下来检查织焰者的尸体，同时在寻找着什么。"
D.Strings[56523]="现在，继续酿酒！"
D.Strings[56524]="那闪闪发亮的宝贝是我的！"
D.Strings[56525]="它是我的！"
D.Strings[56526]="我那亮晶晶的宝贝……"
D.Strings[56527]="我为成功守住我们的村庄而感到骄傲。"
D.Strings[56528]="父亲，我再也不是让你担忧的无助孩童了。"
D.Strings[56529]="我愿意继续训练，使自己能永远守护我们的家园。"
D.Strings[56530]="我会确保这村庄的安全，让你能安心地卸下武器。"
D.Strings[56531]="从没有哪个父亲为自己的孩子感到如此骄傲过，朔弥。"
D.Strings[56532]="你的言辞令我倍感荣耀，女儿。这是个值得骄傲的时刻。"
D.Strings[56533]="你永远都是我的小女孩，我始终都会牵挂你，可我知道，你现在能自己照顾自己了。"
D.Strings[56534]="真是好消息。我们对这里的能量和神器的研究有回报了。$B$B我们已经对在这里找到的魔古族装置有所了解，更令人振奋的是，还找到了让它们为我所用的方法。这座建筑的围墙会汲取和削弱任何置身其中的敌人的力量。"
D.Strings[56535]="是的，请停用装置。"
D.Strings[56536]="你确定吗？这地方很危险，而且我们的首批研究人员都还没能安然返回。如果我们禁用了弱化力场，我们就要离开，直到遗迹被安全守住后才能回来，而且不能再次激活装置。$B$B我再问一次——你确定吗？"
D.Strings[56537]="你太迟了。"
D.Strings[56538]="雷电之王的遗骸已被带去末劫岛了。"
D.Strings[56539]="我们举行了古老的仪式……"
D.Strings[56540]="现在，潘达利亚的真命天子要再次降临这个世界了。"
D.Strings[56541]="我真希望你知道自己在做什么。"
D.Strings[56542]="向熊猫人篡位者致哀吧！魔古族将再度崛起，赞达拉也将得到新的家园……"
D.Strings[56543]="守住遗骸，兄弟们！"
D.Strings[56544]="雷电之王必将重生……"
D.Strings[56545]="雷电之王复活了！我们的帝国再次团结在一起……"
D.Strings[56546]="我们需要这片土地！大灾变毁了我们的家园！"
D.Strings[56547]="这只是个开始……我们可不会接二连三地倒下……"
D.Strings[56548]="你终于来到了这污染的中心地带。我们会助你一臂之力。我们的歌声会在这扭曲之地四处回响，让那些遗弃我族的人，决心尽数瓦解。"
D.Strings[56549]="我们绝对能独自应对。撤退吧。等你们回来时就会发现女皇被杀死了，你们的麻烦也已得到解决。"
